def can_reach(D, stones):
    n = len(stones)
    if n == 0:
        return False
    current = stones[0]
    i = 0
    while i < n - 1:
        low = i + 1
        high = n - 1
        best = -1
        while low <= high:
            mid = (low + high) // 2
            if stones[mid] - current <= D:
                best = mid
                low = mid + 1
            else:
                high = mid - 1
        if best == -1:
            return False
        current = stones[best]
        i = best
    return current == stones[-1]

def compute_min_jumps(D, stones):
    n = len(stones)
    jumps = 0
    current = stones[0]
    i = 0
    while i < n - 1:
        low = i + 1
        high = n - 1
        best = -1
        while low <= high:
            mid = (low + high) // 2
            if stones[mid] - current <= D:
                best = mid
                low = mid + 1
            else:
                high = mid - 1
        if best == -1:
            return float('inf')
        jumps += 1
        current = stones[best]
        i = best
    return jumps

def compute_max_jumps(D, stones):
    n = len(stones)
    if n == 0:
        return 0
    count = 1
    prev = stones[0]
    for stone in stones[1:]:
        if stone - prev <= D:
            count += 1
            prev = stone
    if prev != stones[-1]:
        return 0
    return count - 1

def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N, K = int(input[ptr]), int(input[ptr+1])
        ptr += 2
        stones = list(map(int, input[ptr:ptr+N]))
        ptr += N

        if N == 1:
            print(0)
            continue

        max_consec = 0
        for i in range(1, N):
            diff = stones[i] - stones[i-1]
            if diff > max_consec:
                max_consec = diff

        low = max_consec
        high = stones[-1] - stones[0]
        answer = high

        while low <= high:
            mid = (low + high) // 2
            if not can_reach(mid, stones):
                low = mid + 1
                continue
            min_j = compute_min_jumps(mid, stones)
            max_j = compute_max_jumps(mid, stones)
            if min_j <= K <= max_j:
                answer = mid
                high = mid - 1
            else:
                if K < min_j:
                    low = mid + 1
                else:
                    high = mid - 1
        print(answer)

