            else:
                if leading_zero:
                    new_cnt = 1 if d != 0 else 0
                else:
                    new_cnt = cnt + (1 if d != 0 else 0)
            if new_cnt > K:
                continue
            res += dp(pos + 1, new_tight, new_leading_zero, new_cnt)
        return res

    print(dp(0, True, True, 0))

