import sys
from collections import deque

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    special = list(map(int, sys.stdin.readline().split()))
    special_set = set(special)
    edges = []
    for _ in range(m):
        u, v, w = map(int, sys.stdin.readline().split())
        if u != v:
            edges.append((w, u, v))
    edges.sort()

    parent = list(range(n+1))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        parent[v_root] = u_root
        return True

    mst_edges = []
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append((u, v, w))

    adj = [[] for _ in range(n+1)]
    for u, v, w in mst_edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    root = special[0]
    parent_arr = [0]*(n+1)
    edge_weight = [0]*(n+1)
    visited = [False]*(n+1)
    q = deque([root])
    visited[root] = True
    order = []

    while q:
        u = q.popleft()
        order.append(u)
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent_arr[v] = u
                edge_weight[v] = w
                q.append(v)

    count = [0]*(n+1)
    for u in reversed(order):
        if u in special_set:
            count[u] = 1
        for v, w in adj[u]:
            if parent_arr[v] == u:
                count[u] += count[v]

    max_edge = 0
    for v in range(1, n+1):
        if v == root:
            continue
        s = count[v]
        if s > 0 and (k - s) > 0:
            max_edge = max(max_edge, edge_weight[v])

    print(' '.join([str(max_edge)] * k))

