        religions[i].pop()

    s = [''.join(r) for r in religions]
    found = False
    for perm in permutations(s):
        a, b, c = perm
        ok_a, used_a = check_sequence(a, char_indices)
        if not ok_a:
            continue
        ok_b, used_b = check_sequence_with_exclusions(b, char_indices, used_a)
        if not ok_b:
            continue
        exclude_ab = used_a + used_b
        exclude_ab.sort()
        ok_c, _ = check_sequence_with_exclusions(c, char_indices, exclude_ab)
        if ok_c:
            found = True
            break
    print("YES" if found else "NO")

