    def compute_intervals(cuts, total):
        sorted_cuts = sorted(cuts)
        intervals = []
        prev = 0
        for cut in sorted_cuts:
            if prev < cut:
                intervals.append(cut - prev)
                prev = cut
        if prev < total:
            intervals.append(total - prev)
        return intervals

    v_intervals = compute_intervals(vertical_cuts, n)
    h_intervals = compute_intervals(horizontal_cuts, m)

    sum_a = 0
    for w in v_intervals:
        sum_a ^= (w-1)
    sum_b = 0
    for h in h_intervals:
        sum_b ^= (h-1)

    H = len(h_intervals)
    V = len(v_intervals)
    Hp = H % 2
    Vp = V % 2

    total = (sum_a * Hp) ^ (sum_b * Vp)

    if total == 0:
        print("SECOND")
        return

    def find_vertical():
        prev = 0
        for i, w in enumerate(v_intervals):
            a_prev = prev
            a_next = prev + w
            prev = a_next

            V_new = V +1
            Vp_new = V_new % 2

            if Hp != 0:
                desired_sum_a = (sum_b * Vp_new)
                delta = sum_a ^ desired_sum_a
                K = delta ^ (w-1)
                sum_total = w-2
                if (sum_total + K) % 2 != 0:
                    continue
                left = (sum_total + K) // 2
                right = (sum_total - K) // 2
                if left <0 or right <0:
                    continue
                if left + right != sum_total:
                    continue
                x = left +1
                if x <1 or x >= w:
                    continue
                x_cut = a_prev + x
                if x_cut <=0 or x_cut >= n:
                    continue
                return (x_cut, 0, x_cut, m)
            else:
                if (sum_b * Vp_new) !=0:
                    continue
                if w <2:
                    continue
                x_cut = a_prev +1
                if x_cut >0 and x_cut <n:
                    return (x_cut, 0, x_cut, m)
        return None

    def find_horizontal():
        prev = 0
        for i, h in enumerate(h_intervals):
            a_prev = prev
            a_next = prev + h
            prev = a_next

            H_new = H +1
            Hp_new = H_new % 2

            if Vp != 0:
                desired_sum_b = (sum_a * Hp_new)
                delta = sum_b ^ desired_sum_b
