    ptr += 1
    colors = list(map(int, input[ptr:ptr + N]))
    ptr += N
    color_map = defaultdict(list)
    for idx, color in enumerate(colors):
        color_map[color].append(idx)
    Q = int(input[ptr])
    ptr += 1
    for _ in range(Q):
        S = int(input[ptr])
