import sys
from collections import deque

def main():
    H, W, K = map(int, sys.stdin.readline().split())
    grid = []
    start = None
    for i in range(H):
        row = sys.stdin.readline().strip()
        grid.append(list(row))
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)

    # Precompute distance to the nearest exit for each cell
    distance = [[-1] * W for _ in range(H)]
    q = deque()
    for i in range(H):
        for j in range(W):
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                if grid[i][j] == '#':
                    continue  # Skip locked exit cells, but they can be unlocked later
                q.append((i, j))
                distance[i][j] = 0
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and distance[ni][nj] == -1:
                distance[ni][nj] = distance[i][j] + 1
                q.append((ni, nj))

    # Initialize unlocked grid and BFS for movement
    unlocked = [[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' or grid[i][j] == 'S':
                unlocked[i][j] = True

    current_reachable = deque()
    visited = [[False]*W for _ in range(H)]
    i0, j0 = start
    current_reachable.append((i0, j0))
    visited[i0][j0] = True

    cast = 0
    while True:
        # Check if any current_reachable cell is an exit
        found = False
        for i, j in current_reachable:
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                print(cast + 1)
                return
        if found:
            break

        # Collect adjacent locked cells
        candidates = set()
        for i, j in current_reachable:
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and not unlocked[ni][nj]:
                    candidates.add((ni, nj))

        # Sort candidates by distance to exit and unlock up to K
        sorted_candidates = sorted(candidates, key=lambda x: distance[x[0]][x[1]])
        unlock = sorted_candidates[:K]
        for i, j in unlock:
            unlocked[i][j] = True

        # BFS up to K steps
        next_reachable = deque()
        visited_new = [[False]*W for _ in range(H)]
        for _ in range(K):
            if not current_reachable:
                break
            level_size = len(current_reachable)
            for _ in range(level_size):
                i, j = current_reachable.popleft()
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W and unlocked[ni][nj] and not visited_new[ni][nj]:
                        visited_new[ni][nj] = True
                        next_reachable.append((ni, nj))
            current_reachable = next_reachable
            next_reachable = deque()

        # Update current_reachable with all visited_new cells
        current_reachable = deque()
        for i in range(H):
            for j in range(W):
                if visited_new[i][j]:
                    current_reachable.append((i, j))

        if not current_reachable:
            break

        cast += 1

    # If no exit found (shouldn't happen per problem statement)
    print(-1)

