import heapq

def solve():
    for line in sys.stdin:
        n = int(line.strip())
        if n == 0:
            break
        islands = []
        sum_total = 0
        for _ in range(n):
            t, c = map(int, sys.stdin.readline().split())
            islands.append((t, c))
            sum_total += t

        possible = False
        for last_idx in range(n):
            last_t, last_c = islands[last_idx]
            if last_c < sum_total:
                continue
            # Collect other islands
            others = []
            sum_rest = 0
            for i in range(n):
                if i != last_idx:
                    t, c = islands[i]
                    others.append((t, c - t))
                    sum_rest += t
            if sum_rest + last_t != sum_total:
                continue  # Should not happen

            m = len(others)
            if m == 0:
                possible = True
                break

            dp = {0: 0}
            heap = [(0, 0)]
            found = False
            while heap:
                current_sum, mask = heapq.heappop(heap)
                if dp[mask] < current_sum:
                    continue
                if mask == (1 << m) - 1:
                    found = True
                    break
                for j in range(m):
                    if not (mask & (1 << j)):
                        t_j, d_j = others[j]
                        if current_sum <= d_j:
                            new_mask = mask | (1 << j)
                            new_sum = current_sum + t_j
                            if new_sum < dp.get(new_mask, float('inf')):
                                dp[new_mask] = new_sum
                                heapq.heappush(heap, (new_sum, new_mask))
            if found:
                possible = True
                break

        print("Yes" if possible else "No")

