            return
        if m in factors:
            return
        d = find_divisor(m)
        if d is None:
            factors.add(m)
            return
        factor(d)
        factor(m // d)

    def find_divisor(m):
        s = send_query(f"sqrt 1")
        if s != -1 and s != 1 and s != m - 1:
            delta = (s - 1) % m
            d = math.gcd(delta, m)
            if 1 < d < m:
                return d
            delta_plus = (s + 1) % m
            d = math.gcd(delta_plus, m)
            if 1 < d < m:
                return d

        for _ in range(20):
            r = random.randint(1, m - 1)
            x = send_query(f"* {r} {r}")
            s = send_query(f"sqrt {x}")
            if s == -1:
                continue
            delta = (r - s) % m
            if delta == 0:
                continue
            d = math.gcd(delta, m)
            if 1 < d < m:
                return d
            delta_plus = (r + s) % m
            d = math.gcd(delta_plus, m)
            if 1 < d < m:
                return d
        return None

    factor(n)
    print(f"! {len(factors)} {' '.join(map(str, sorted(factors)))}")

