import sys

def main():
    n = int(sys.stdin.readline())
    objects = []
    for _ in range(n):
        parent, typ = map(int, sys.stdin.readline().split())
        objects.append((parent, typ))

    # Precompute type0_parent and part_leader
    type0_parent = [-1] * (n + 1)
    part_leader = [0] * (n + 1)
    for i in range(1, n + 1):
        parent, typ = objects[i-1]
        if parent != -1:
            if typ == 0:
                type0_parent[i] = parent
            else:
                type0_parent[i] = -1
        # Compute part_leader
        if parent == -1 or typ != 1:
            part_leader[i] = i
        else:
            part_leader[i] = part_leader[parent]

    # Compute depth0
    depth0 = [0] * (n + 1)
    for i in range(1, n + 1):
        if type0_parent[i] != -1:
            depth0[i] = depth0[type0_parent[i]] + 1
        else:
            depth0[i] = 0

    # Precompute binary lifting table for type0_parent
    max_level = 20
    up = [[-1] * (n + 1) for _ in range(max_level)]
    for i in range(1, n + 1):
        up[0][i] = type0_parent[i]
    for k in range(1, max_level):
        for i in range(1, n + 1):
            if up[k-1][i] != -1:
                up[k][i] = up[k-1][up[k-1][i]]

    # Process queries
    q = int(sys.stdin.readline())
    for _ in range(q):
        typ, u, v = map(int, sys.stdin.readline().split())
        if typ == 1:
            a = u
            b = v
        else:
            a = part_leader[v]
            b = u

        if a == b:
            print("YES")
            continue

        if depth0[a] > depth0[b]:
            print("NO")
            continue

        current = b
        delta = depth0[current] - depth0[a]
        found = True
        for k in reversed(range(max_level)):
            if delta >= (1 << k):
                next_node = up[k][current]
                if next_node == -1:
                    found = False
                    break
                current = next_node
                delta -= (1 << k)
        if not found:
            print("NO")
            continue
        print("YES" if current == a else "NO")

