import math
from collections import defaultdict

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = math.gcd(abs(a), abs(b))
    p = a // g
    q = b // g
    if p != 0:
        sign = p // abs(p)
    else:
        sign = q // abs(q) if q != 0 else 1
    p //= sign
    q //= sign
    return (p, q)

def main():
    N = int(sys.stdin.readline())
    zero_count = 0
    groups = defaultdict(int)
    for _ in range(N):
        a, b = map(int, sys.stdin.readline().split())
        if a == 0 and b == 0:
            zero_count += 1
        else:
            norm = normalize(a, b)
            groups[norm] += 1

    processed = set()
    product = 1
    for d in list(groups.keys()):
        if d in processed:
            continue
        a, b = d
        ortho = normalize(b, -a)
        if ortho in groups:
            if ortho in processed:
                continue
            cnt_d = groups[d]
            cnt_ortho = groups[ortho]
            term = (pow(2, cnt_d, MOD) + pow(2, cnt_ortho, MOD) - 1) % MOD
            product = (product * term) % MOD
            processed.add(d)
            processed.add(ortho)
        else:
            term = pow(2, groups[d], MOD)
            product = (product * term) % MOD
            processed.add(d)

    ans = (product - 1 + zero_count) % MOD
    print(ans)

