import sys

def comb(n, k):
    if n < k or k < 0:
        return 0
    if k == 0:
        return 1
    numerator = 1
    for i in range(k):
        numerator *= (n - i)
    denominator = 1
    for i in range(1, k + 1):
        denominator *= i
    return numerator // denominator

