def compute_min_k(a_target, b_target, h_initial, w_initial, sorted_a):
    # Compute product needed
    if h_initial >= a_target:
        ph = 1
    else:
        ph = (a_target + h_initial - 1) // h_initial
    if w_initial >= b_target:
        pw = 1
    else:
        pw = (b_target + w_initial - 1) // w_initial
    # Compute prefix up to min(n, 40)
    max_k = min(len(sorted_a), 40)
    prefix = [1]
    for ai in sorted_a[:max_k]:
        prefix.append(prefix[-1] * ai)
    # Iterate k from 1 to len(prefix)-1
    min_k = float('inf')
    for k in range(1, len(prefix)):
        for m in range(0, k + 1):
            if m >= len(prefix) or k >= len(prefix):
                continue
            product_h = prefix[m]
            product_w = prefix[k] // prefix[m] if prefix[m] != 0 else 0
            if product_h >= ph and product_w >= pw:
                if k < min_k:
                    min_k = k
                break  # break inner loop
        if min_k != float('inf'):
            break  # break outer loop
    return min_k

