    for _ in range(n-1):
        a, b = map(int, sys.stdin.readline().split())
        edges[a].append(b)
        edges[b].append(a)

    parent = [0]*(n+1)
    children = [[] for _ in range(n+1)]
    visited = [False]*(n+1)
    q = deque([1])
    visited[1] = True
    while q:
        u = q.popleft()
        for v in edges[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                q.append(v)

    size = [1]*(n+1)

    post_order = []
    stack = [(1, False)]
    while stack:
        u, processed = stack.pop()
        if processed:
            for v in children[u]:
                size[u] += size[v]
            post_order.append(u)
        else:
            stack.append((u, True))
            for v in reversed(children[u]):
                stack.append((v, False))

    can_match = [False]*(n+1)
    cnt_remove = [0]*(n+1)

    for u in post_order:
        s = size[u]
        if s % 2 != 0:
            can_match[u] = False
        else:
            odd_children = 0
            for v in children[u]:
                if size[v] % 2 != 0:
                    odd_children += 1
            can_match[u] = (odd_children % 2 == 0)

    for u in post_order:
        cnt = 0
        if size[u] % 2 == 1:
            s_after = size[u] - 1
            if s_after % 2 == 0:
                valid = True
                for v in children[u]:
                    if size[v] == s_after:
                        valid = False
                        break
                if valid:
                    if can_match[u]:
                        cnt += 1
        cnt_remove[u] = cnt

    ans = 0
    for v in range(2, n+1):
        u = parent[v]
        a = size[v]
        b = n - a
        if a % 2 == 0 and b % 2 == 0:
            if can_match[v] and can_match[1]:
                ans += a * b
        elif a % 2 == 1 and b % 2 == 1:
            cntA = a
            cntB = b
            ans += cntA * cntB

    print(ans)

