def generate_pal(required):
    first_half = []
    middle = ''
    for char in string.ascii_lowercase:
        count = required[char]
        if count == 0:
            continue
        pairs = count // 2
        if pairs > 0:
            first_half.append(char * pairs)
        if count % 2 == 1 and not middle:
            middle = char
    first_half_str = ''.join(first_half)
    return first_half_str + middle + first_half_str[::-1]

