import sys
import re
from sympy import expand, sympify, SympifyError

def preprocess(s):
    s = re.sub(r'([a-z])\s*\^\s*(\d)', r'\1**\2', s)
    s = s.replace(' ', '*')
    s = re.sub(r'(\))([a-z0-9(])', r'\1*\2', s)
    s = re.sub(r'([a-z])([a-z0-9(])', r'\1*\2', s)
    s = re.sub(r'(\d)([a-z(])', r'\1*\2', s)
    return s

def process_block(block):
    if not block:
        return
    correct_line = block[0]
    processed_correct = preprocess(correct_line)
    try:
        correct_expr = expand(sympify(processed_correct))
    except SympifyError:
        for _ in block[1:]:
            print("no")
        return
    for student_line in block[1:]:
        processed_student = preprocess(student_line)
        try:
            student_expr = expand(sympify(processed_student))
            if student_expr.equals(correct_expr):
                print("yes")
            else:
                print("no")
        except SympifyError:
            print("no")

def main():
    current_block = []
    for line in sys.stdin:
        stripped = line.strip()
        if stripped == '.':
            if not current_block:
                break
            else:
                process_block(current_block)
                print(".")
                current_block = []
        else:
            current_block.append(stripped)

