import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    values = [0] * (N + 1)  # 1-based indexing
    for i in range(1, N+1):
        values[i] = int(sys.stdin.readline())
    adj = [[] for _ in range(N+1)]
    in_degree = [0] * (N+1)
    for _ in range(M):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        in_degree[v] += 1

    # Compute topological order
    queue = deque()
    topo_order = []
    for i in range(1, N+1):
        if in_degree[i] == 0:
            queue.append(i)
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize dp, only start from node 1
    dp = [-float('inf')] * (N + 1)
    dp[1] = values[1]

    # Process nodes in topological order
    for u in topo_order:
        if dp[u] == -float('inf'):
            continue
        for v in adj[u]:
            if dp[v] < dp[u] + values[v]:
                dp[v] = dp[u] + values[v]

    # Find the maximum value in dp (ignore unvisited nodes)
    max_sum = max([val for val in dp if val != -float('inf')])
    print(max_sum)

if __name__ == "__main__":
    main()

import math
import heapq

def generate_edges(star):
    x, y, a_deg, r = star
    tips = []
    for k in range(5):
        angle_deg = a_deg + 72 * k
        angle_rad = math.radians(angle_deg)
        tip_x = x + r * math.sin(angle_rad)
        tip_y = y + r * math.cos(angle_rad)
        tips.append((tip_x, tip_y))
    edges = [
        (tips[0], tips[2]),
        (tips[2], tips[4]),
        (tips[4], tips[1]),
        (tips[1], tips[3]),
        (tips[3], tips[0])
    ]
    return edges

def ccw(A, B, C):
    return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])

def segments_intersect(s1, s2):
    A, B = s1
    C, D = s2
    ccw1 = ccw(A, B, C)
    ccw2 = ccw(A, B, D)
    ccw3 = ccw(C, D, A)
    ccw4 = ccw(C, D, B)

    if (ccw1 * ccw2 < 0) and (ccw3 * ccw4 < 0):
        return True, None

    def on_segment(a, b, c):
        return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

    for p in [C, D]:
        if ccw(A, B, p) == 0 and on_segment(A, B, p):
            return True, None
    for p in [A, B]:
        if ccw(C, D, p) == 0 and on_segment(C, D, p):
            return True, None
    return False, None

def minimal_distance_between_segments(s1, s2):
    intersect, _ = segments_intersect(s1, s2)
    if intersect:
        return 0.0

    P0, P1 = s1
    Q0, Q1 = s2
    u = (P1[0] - P0[0], P1[1] - P0[1])
    v = (Q1[0] - Q0[0], Q1[1] - Q0[1])
    w0 = (P0[0] - Q0[0], P0[1] - Q0[1])
    a = u[0] * u[0] + u[1] * u[1]
    b = u[0] * v[0] + u[1] * v[1]
    c = v[0] * v[0] + v[1] * v[1]
    d = u[0] * w0[0] + u[1] * w0[1]
    e = v[0] * w0[0] + v[1] * w0[1]
    denom = a * c - b * b

    if denom < 1e-14:
        sN, sD = 0.0, 1.0
        tN, tD = e, c
    else:
        sN = (b * e - c * d)
        tN = (a * e - b * d)
        if sN < 0:
            sN = 0.0
            tN = e
            tD = c
        elif sN > denom:
            sN = denom
            tN = e + b
            tD = c

    if tN < 0:
        tN = 0.0
        if -d < 0:
            sN = 0.0
        elif -d > a:
            sN = denom
        else:
            sN = -d
            sD = a
    elif tN > tD:
        tN = tD
        if (-d + b) < 0:
            sN = 0.0
        elif (-d + b) > a:
            sN = denom
        else:
            sN = (-d + b)
            sD = a

    sc = sN / sD if abs(sD) > 1e-14 else 0.0
    tc = tN / tD if abs(tD) > 1e-14 else 0.0

    P = (P0[0] + sc * u[0], P0[1] + sc * u[1])
    Q = (Q0[0] + tc * v[0], Q0[1] + tc * v[1])
    min_dist = math.hypot(P[0] - Q[0], P[1] - Q[1])

    endpoints = [P0, P1, Q0, Q1]
    for i in range(2):
        for j in range(2,4):
            d = math.hypot(endpoints[i][0]-endpoints[j][0], endpoints[i][1]-endpoints[j][1])
            if d < min_dist:
                min_dist = d
    return min_dist

def dijkstra(n, start, adj_matrix):
    dist = [float('inf')] * n
    dist[start] = 0.0
    heap = [(0.0, start)]
    visited = [False] * n

    while heap:
        current_dist, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        for v in range(n):
            if v == u:
                continue
            new_dist = current_dist + adj_matrix[u][v]
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))
    return dist

def main():
    while True:
        N, M, L = map(int, input().split())
        if N == 0 and M == 0 and L == 0:
            break
        stars = []
        for _ in range(N):
            x, y, a, r = map(int, input().split())
            stars.append((x, y, a, r))
        edges_for_stars = [generate_edges(star) for star in stars]

        n = N
        min_dist_matrix = [[float('inf')] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    min_dist_matrix[i][j] = 0.0
                    continue
                min_d = float('inf')
                for e1 in edges_for_stars[i]:
                    for e2 in edges_for_stars[j]:
                        d = minimal_distance_between_segments(e1, e2)
                        if d < min_d:
                            min_d = d
                            if d == 0.0:
                                break
                    if min_d == 0.0:
                        break
                min_dist_matrix[i][j] = min_d

        start = M - 1
        end = L - 1
        distances = dijkstra(n, start, min_dist_matrix)
        print("{0:.20f}".format(distances[end]))

