class DSU:
    def __init__(self, n):
        self.parent = list(range(n+1))
        self.size = [1] * (n+1)
        self.undo_steps = dict()  # Maps day to list of undo steps

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y, day):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        # Ensure x_root is the larger tree
        if self.size[x_root] < self.size[y_root]:
            x_root, y_root = y_root, x_root
        # Record undo step
        if day not in self.undo_steps:
            self.undo_steps[day] = []
        self.undo_steps[day].append((x_root, self.size[x_root], y_root))
        # Perform the union
        self.parent[y_root] = x_root
        self.size[x_root] += self.size[y_root]

    def undo(self, steps):
        # Undo steps in reverse order
        for x_root, original_size, y_root in reversed(steps):
            self.parent[y_root] = y_root
            self.size[x_root] = original_size

