from sys import setrecursionlimit

def main():
    sys.setrecursionlimit(1 << 25)
    n, m, k = map(int, stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    visited = [False] * (n + 1)
    path_stack = []
    pos = [-1] * (n + 1)

    for start in range(1, n+1):
        if not visited[start]:
            stack = [(start, iter(adj[start]), -1)]
            while stack:
                node_processing = False
                u, neighbors, parent = stack[-1]
                if not visited[u]:
                    visited[u] = True
                    path_stack.append(u)
                    pos[u] = len(path_stack) - 1
                    node_processing = True
                try:
                    v = next(neighbors)
                    if v == parent:
                        continue
                    if not visited[v]:
                        stack.append((v, iter(adj[v]), u))
                    else:
                        if pos[v] != -1:
                            cycle_length = len(path_stack) - pos[v]
                            if cycle_length >= k + 1:
                                cycle = path_stack[pos[v]:]
                                print(len(cycle))
                                print(' '.join(map(str, cycle)))
                                return
                except StopIteration:
                    stack.pop()
                    if node_processing:
                        path_stack.pop()
                        pos[u] = -1

main()

