import sys

def main():
    n, q = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    max_a = max(a) if a else 0

    def compute_mobius(max_mobius):
        if max_mobius < 1:
            return []
        spf = list(range(max_mobius + 1))
        for i in range(2, int(max_mobius**0.5) + 1):
            if spf[i] == i:
                for j in range(i * i, max_mobius + 1, i):
                    if spf[j] == j:
                        spf[j] = i
        mobius = [1] * (max_mobius + 1)
        for i in range(2, max_mobius + 1):
            x = i
            is_square_free = True
            factors = []
            while x != 1:
                p = spf[x]
                if (x // p) % p == 0:
                    is_square_free = False
                    break
                factors.append(p)
                x = x // p
            if not is_square_free:
                mobius[i] = 0
            else:
                mobius[i] = (-1) ** len(factors)
        return mobius

    mobius = compute_mobius(max_a)

    divisors_list = []
    for x in a:
        divs = set()
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divs.add(i)
                if i != x // i:
                    divs.add(x // i)
        divisors_list.append(list(divs))

    in_shelf = [False] * (n + 1)
    current_sum = 0
    count = [0] * (max_a + 2)

    for _ in range(q):
        x = int(sys.stdin.readline())
        idx = x - 1
        if not in_shelf[x]:
            delta = 0
            for d in divisors_list[idx]:
                delta += mobius[d] * count[d]
                count[d] += 1
            current_sum += delta
            in_shelf[x] = True
        else:
            delta = 0
            for d in divisors_list[idx]:
                delta -= mobius[d] * (count[d] - 1)
                count[d] -= 1
            current_sum += delta
            in_shelf[x] = False
        print(current_sum)

