def find_solution(x_a, x_b):
    for k_a in range(1, n):
        if k_a > len(c_sorted):
            continue
        required_a = x_a / k_a
        if c_sorted[k_a - 1] >= required_a:
            m = n - k_a
            if m < 1:
                continue
            low, high, best_k_b = 1, m, 0
            while low <= high:
                mid = (low + high) // 2
                idx = k_a + mid - 1
                if idx >= len(c_sorted):
                    valid = False
                else:
                    valid = c_sorted[idx] >= (x_b / mid)
                if valid:
                    best_k_b = mid
                    low = mid + 1
                else:
                    high = mid - 1
            if best_k_b > 0:
                return (k_a, best_k_b)
    return None

