def preprocess(s):
    n = len(s)
    next_0 = [None] * n
    next_1 = [None] * n
    last_0 = None
    last_1 = None
    for i in reversed(range(n)):
        if s[i] == '0':
            last_0 = i
        else:
            last_1 = i
        next_0[i] = last_0
        next_1[i] = last_1
    return next_0, next_1

def is_subsequence(s, next_0, next_1):
    current_pos = -1
    n = len(next_0)
    for c in s:
        if current_pos + 1 >= n:
            return False
        if c == '0':
            next_pos = next_0[current_pos + 1]
        else:
            next_pos = next_1[current_pos + 1]
        if next_pos is None:
            return False
        current_pos = next_pos
    return True

def find_shortest_non_subsequence(A, B):
    next_0_A, next_1_A = preprocess(A)
    next_0_B, next_1_B = preprocess(B)

    max_k = 20  # Sufficient for given constraints
    for k in range(1, max_k + 1):
        for num in range(0, 1 << k):
            s = bin(num)[2:].zfill(k)
            # Check if s is not a subsequence of both A and B
            is_sub_A = is_subsequence(s, next_0_A, next_1_A)
            is_sub_B = is_subsequence(s, next_0_B, next_1_B)
            if not is_sub_A and not is_sub_B:
                return s
    return '0'  # Fallback, though theoretically unreachable

