        for row in grid:
            valid = []
            for mask in range(0, 1 << W):
                if (mask & (mask << 1)) == 0:
                    s = 0
                    for i in range(W):
                        if mask & (1 << i):
                            s += row[i]
                    valid.append((mask, s))
            row_masks.append(valid)

        if not row_masks:
            print(f"Case {case}: 0")
            continue

        dp_prev = {}
        for mask, s in row_masks[0]:
            dp_prev[mask] = s

        for i in range(1, H):
            current_masks = row_masks[i]
            max_prev_sum = [0] * (1 << W)
            for m, val in dp_prev.items():
                if val > max_prev_sum[m]:
                    max_prev_sum[m] = val
            for i_bit in range(W):
                for S in range(1 << W):
                    if S & (1 << i_bit):
                        S_prev = S ^ (1 << i_bit)
                        if max_prev_sum[S_prev] > max_prev_sum[S]:
                            max_prev_sum[S] = max_prev_sum[S_prev]
            current_dp = {}
            for mask, sum_val in current_masks:
                s = (~mask) & ((1 << W) -1)
                prev_max = max_prev_sum[s]
                total = sum_val + prev_max
                if mask in current_dp:
                    if total > current_dp[mask]:
                        current_dp[mask] = total
                else:
                    current_dp[mask] = total
            dp_prev = current_dp

