def pns_number(n):
    if n == 0:
        return ""
    # Find the correct m
    m = 1
    while True:
        s = (3 ** (m + 1) - 3) // 2
        if s >= n:
            break
        m += 1
    s_prev = (3 ** m - 3) // 2
    pos = n - s_prev
    num = pos - 1

    # Convert num to base3
    if num == 0:
        base3 = '0'
    else:
        digits = []
        while num > 0:
            digits.append(num % 3)
            num = num // 3
        base3 = ''.join(str(d) for d in reversed(digits))

    # Pad with leading zeros to m digits and replace
    base3_padded = base3.zfill(m)
    result = []
    for c in base3_padded:
        if c == '0':
            result.append('4')
        elif c == '1':
            result.append('5')
        else:
            result.append('6')
    return ''.join(result)

