def main():
    n, m, q = map(int, stdin.readline().split())
    p = list(map(int, stdin.readline().split()))
    edges = []
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        a -= 1
        b -= 1
        edges.append((a, b))
    queries = []
    deleted = [False] * m
    for _ in range(q):
        parts = stdin.readline().split()
        if parts[0] == '1':
            v = int(parts[1]) - 1
            queries.append(('1', v))
        else:
            i = int(parts[1]) - 1
            deleted[i] = True
            queries.append(('2', i))

    parent = list(range(n))
    size = [1] * n
    max_val = p.copy()
    value_to_node = [0] * (n + 1)
    for i in range(n):
        value_to_node[p[i]] = i

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def unite(u, v):
        u = find(u)
        v = find(v)
        if u == v:
            return
        if size[u] < size[v]:
            u, v = v, u
        parent[v] = u
        if max_val[u] < max_val[v]:
            max_val[u] = max_val[v]
        size[u] += size[v]

    for i in range(m):
        if not deleted[i]:
            a, b = edges[i]
            unite(a, b)

    current_p = [0] * n
    for i in range(n):
        current_p[i] = p[i]

    answer = []
    for query in reversed(queries):
        if query[0] == '2':
            i = query[1]
            a, b = edges[i]
            unite(a, b)
        else:
            v = query[1]
            root = find(v)
            mv = max_val[root]
            if mv == 0:
                answer.append(0)
            else:
                answer.append(mv)
                u = value_to_node[mv]
                current_p[u] = mv
                root_u = find(u)
                if root_u == root:
                    candidates = []
                    for neighbor in [u, parent[u]]:
                        if find(neighbor) == root:
                            candidates.append(max_val[neighbor])
                    max_val[root] = max(candidates)

    for ans in reversed(answer):
        print(ans)

