# Initialize DP tables
dp_left = [[False] * n for _ in range(n)]
dp_right = [[False] * n for _ in range(n)]

# Base case: intervals of length 1
for i in range(n):
    # Check for dp_left[i][i] (parent is j+1 = i+1)
    if i + 1 < n:
        if gcd_table[i][i+1] > 1:
            dp_left[i][i] = True
    # Check for dp_right[i][i] (parent is i-1)
    if i - 1 >= 0:
        if gcd_table[i][i-1] > 1:
            dp_right[i][i] = True

# Fill DP tables for intervals of length >= 2
for l in range(2, n+1):
    for i in range(n - l + 1):
        j = i + l - 1

        # Compute dp_left[i][j]
        if j + 1 < n:
            for k in range(i, j+1):
                if gcd_table[k][j+1] > 1:
                    left_ok = True
                    if k > i:
                        left_ok = dp_left[i][k-1]
                    right_ok = True
                    if k < j:
                        right_ok = dp_right[k+1][j]
                    if left_ok and right_ok:
                        dp_left[i][j] = True
                        break  # No need to check other k

        # Compute dp_right[i][j]
        if i - 1 >= 0:
            for k in range(i, j+1):
