def find_centroids(n, adj):
    centroids = []
    size = [0] * (n + 1)

    def dfs(u, parent):
        size[u] = 1
        is_centroid = True
        for v in adj[u]:
            if v == parent:
                continue
            dfs(v, u)
            size[u] += size[v]
            if size[v] > n // 2:
                is_centroid = False
        if (n - size[u]) > n // 2:
            is_centroid = False
        if is_centroid:
            centroids.append(u)

    dfs(1, -1)
    return centroids

def find_leaf_in_subtree(u, v, adj):
    visited = set()
    stack = [(u, None)]
    leaf_edge = None

    while stack:
        node, parent = stack.pop()
        visited.add(node)
        children = []
        for neighbor in adj[node]:
            if node == u and neighbor == v:
                continue
            if neighbor != parent:
                children.append(neighbor)
        if not children and node != u:
            leaf_edge = (parent, node)
            break
        for child in reversed(children):
            stack.append((child, node))

    return leaf_edge

