class DSU:
    def __init__(self, size):
        self.parent = list(range(size+1))
        self.rank = [1]*(size+1)
        self.parity = [0]*(size+1)

    def find(self, u):
        if self.parent[u] != u:
            orig_parent = self.parent[u]
            root, p = self.find(orig_parent)
            self.parent[u] = root
            self.parity[u] ^= p
        return self.parent[u], self.parity[u]

    def union(self, u, v, c):
        pu, cu = self.find(u)
        pv, cv = self.find(v)
        if pu == pv:
            return (cu ^ cv) == c
        if self.rank[pu] < self.rank[pv]:
            pu, pv = pv, pu
            cu, cv = cv, cu
        self.parent[pv] = pu
        self.parity[pv] = (cu ^ cv ^ c)
        if self.rank[pu] == self.rank[pv]:
            self.rank[pu] += 1
        return True

