    road_adj = [set() for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in range(1, n + 1):
            if u != v and v not in rail_adj[u]:
                road_adj[u].add(v)

    # Check if train can reach n
    train_dist = [-1] * (n + 1)
    q = deque([1])
    train_dist[1] = 0
    while q:
        u = q.popleft()
        for v in rail_adj[u]:
            if train_dist[v] == -1:
                train_dist[v] = train_dist[u] + 1
                q.append(v)
                if v == n:
                    break
    if train_dist[n] == -1:
        print(-1)
        return

    # Check if bus can reach n
    bus_dist = [-1] * (n + 1)
    q = deque([1])
    bus_dist[1] = 0
    while q:
        u = q.popleft()
        for v in road_adj[u]:
            if bus_dist[v] == -1:
                bus_dist[v] = bus_dist[u] + 1
                q.append(v)
                if v == n:
                    break
    if bus_dist[n] == -1:
        print(-1)
        return

    # BFS for combined state
    visited = [[-1] * (n + 1) for _ in range(n + 1)]
    q = deque([(1, 1)])
    visited[1][1] = 0
    answer = -1
    found = False

    while q and not found:
        t_p, b_p = q.popleft()
        current_time = visited[t_p][b_p]

        if t_p == n and b_p == n:
            answer = current_time
            found = True
            break

        # Generate next positions for train
        if t_p == n:
            next_t_list = [n]
        else:
            next_t_list = list(rail_adj[t_p])

        # Generate next positions for bus
        if b_p == n:
            next_b_list = [n]
        else:
            next_b_list = list(road_adj[b_p])

        # Explore all combinations
        for next_t in next_t_list:
            for next_b in next_b_list:
                if next_t == next_b and next_t != n:
                    continue
                if visited[next_t][next_b] == -1:
                    visited[next_t][next_b] = current_time + 1
                    q.append((next_t, next_b))

    print(answer if found else -1)

