import sys

def decrypt(s):
    if not s:
        return ''
    shift = ord(s[0]) - ord('a')
    decrypted = []
    for c in s:
        original_ord = ord(c) - ord('a')
        decrypted_ord = (original_ord - shift) % 26
        decrypted_char = chr(decrypted_ord + ord('a'))
        decrypted.append(decrypted_char)
    return ''.join(decrypted)

