    edges = []
    for _ in range(M):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u-1, v-1))  # 0-based

    color = [-1] * N  # 0: B, 1: W
    adj_eq = [[] for _ in range(N)]
    conflict = False

    # Process edges with D[u] != D[v]
    for u, v in edges:
        if D[u] > D[v]:
            # u must be B (0), v must be W (1)
            if color[u] == 1 or color[v] == 0:
                conflict = True
            if color[u] == -1:
                color[u] = 0
            if color[v] == -1:
                color[v] = 1
            if color[u] != 0 or color[v] != 1:
                conflict = True
        elif D[u] < D[v]:
            # u must be W (1), v must be B (0)
            if color[u] == 0 or color[v] == 1:
                conflict = True
            if color[u] == -1:
                color[u] = 1
            if color[v] == -1:
                color[v] = 0
            if color[u] != 1 or color[v] != 0:
                conflict = True
        else:
            adj_eq[u].append(v)
            adj_eq[v].append(u)

    if conflict:
        print(-1)
        return

    # Process edges with D[u] == D[v], forming a bipartition graph
    # Now assign colors for nodes not yet colored, ensuring bipartition
    # Use BFS
    for i in range(N):
        if color[i] == -1:
            # Assign color 0 if possible
            color[i] = 0
            q = deque()
            q.append(i)
            while q:
                u = q.popleft()
                for v in adj_eq[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        print(-1)
                        return

    # Check all equality edges
    for u, v in edges:
        if D[u] == D[v]:
            if color[u] == color[v]:
                print(-1)
                return

    # Now check if all nodes have at least one neighbor of opposite color
    # Also check the minimal edge weight for each node
    adj_colors = [[] for _ in range(N)]  # list of (color, D of other)
    for u, v in edges:
        if color[u] != color[v]:
            adj_colors[u].append(D[v])
            adj_colors[v].append(D[u])

    has_black = False
    has_white = False
    for i in range(N):
        if color[i] == 0:
            has_black = True
        else:
            has_white = True
        if not adj_colors[i]:
            print(-1)
            return
        min_d = min(adj_colors[i])
        if color[i] == 0 and min_d != D[i]:
            print(-1)
            return
        if color[i] == 1 and min_d != D[i]:
            print(-1)
            return

    if not has_black or not has_white:
        print(-1)
        return

    # Assign edge weights
    output_edges = []
    for u, v in edges:
        if color[u] != color[v]:
            output_edges.append(max(D[u], D[v]))
        else:
