from collections import defaultdict

def main():
    while True:
        m, n, k, d = map(int, input().split())
        if m == 0 and n == 0 and k == 0 and d == 0:
            break
        cakes = list(map(int, input().split()))
        adj = defaultdict(list)
        for _ in range(d):
            s, t, e = input().split()
            e = int(e)
            adj[s].append((t, e))
            adj[t].append((s, e))

        max_mask = 1 << m
        sum_c = [0] * max_mask
        for mask in range(max_mask):
            total = 0
            for i in range(m):
                if mask & (1 << i):
                    total += cakes[i]
            sum_c[mask] = total

        dist = defaultdict(lambda: defaultdict(lambda: float('inf')))
        dist['H'][0] = 0
        heap = []
        heapq.heappush(heap, (0, 'H', 0))

        while heap:
            current_dist, u, mask = heapq.heappop(heap)
            if current_dist > dist[u][mask]:
                continue
            if u == 'D':
                continue
            for v, e in adj[u]:
                if v.startswith('C'):
                    c_num = int(v[1:])
                    idx = c_num - 1
                    if mask & (1 << idx):
                        continue
                    new_mask = mask | (1 << idx)
                    new_dist = current_dist + e
                    if new_dist < dist[v][new_mask]:
                        dist[v][new_mask] = new_dist
                        heapq.heappush(heap, (new_dist, v, new_mask))
                else:
                    new_mask = mask
                    new_dist = current_dist + e
                    if new_dist < dist[v][new_mask]:
                        dist[v][new_mask] = new_dist
                        heapq.heappush(heap, (new_dist, v, new_mask))

        min_net = float('inf')
        for mask in dist['D']:
            current_net = dist['D'][mask] * k - sum_c[mask]
            if current_net < min_net:
                min_net = current_net
        print(min_net)

