import sys
from collections import deque

def is_connected(cells):
    if not cells:
        return False
    visited = set()
    start = next(iter(cells))
    queue = deque([start])
    visited.add(start)
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in cells and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
    return len(visited) == len(cells)

def has_square(region, grid):
    for x in range(len(grid) - 1):
        for y in range(len(grid[0]) - 1):
            if (x, y) in region and (x + 1, y) in region and (x, y + 1) in region and (x + 1, y + 1) in region:
                val = grid[x][y]
                if val == grid[x + 1][y] == grid[x][y + 1] == grid[x + 1][y + 1]:
                    return True
    return False

