            if c == 'T':
                T_cells.append((i, j))
            elif c == 'D':
                D_cells.append((i, j))
            elif c == 'U':
                U_cells.append((i, j))

    u_count = len(U_cells)
    valid = 0

    for mask in range(0, 1 << u_count):
        subset = [U_cells[i] for i in range(u_count) if (mask & (1 << i))]
        tapan = set(T_cells) | set(subset)
        if not tapan:
            continue
        if not is_connected(tapan):
            continue

        divya = set(D_cells) | (set(U_cells) - set(subset))
        if not divya:
            continue
        if not is_connected(divya):
            continue

        t_size = len(tapan)
        d_size = len(divya)
        if abs(t_size - d_size) > K:
            continue

        if has_square(tapan, grid):
            continue
        if has_square(divya, grid):
