from collections import deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx]); idx +=1
    M = int(data[idx]); idx +=1
    K = int(data[idx]); idx +=1

    bikers = []
    for _ in range(N):
        x = int(data[idx]); idx +=1
        y = int(data[idx]); idx +=1
        bikers.append((x, y))

    bikes = []
    for _ in range(M):
        x = int(data[idx]); idx +=1
        y = int(data[idx]); idx +=1
        bikes.append((x, y))

    # Precompute squared distances
    dist_sq = []
    for bx, by in bikers:
        row = []
        for mx, my in bikes:
            dx = bx - mx
            dy = by - my
            row.append(dx*dx + dy*dy)
        dist_sq.append(row)

    max_d = max(max(row) for row in dist_sq)
    low = 0
    high = max_d
    answer = high

    def hopcroft_karp(graph, num_left, num_right):
        pair_u = [-1] * num_left
        pair_v = [-1] * num_right
        dist = [0] * num_left

        def bfs():
            queue = deque()
            for u in range(num_left):
                if pair_u[u] == -1:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist_null = float('inf')
            while queue:
                u = queue.popleft()
                if dist[u] < dist_null:
                    for v in graph[u]:
                        if pair_v[v] == -1:
                            dist_null = dist[u] + 1
                        elif dist[pair_v[v]] == float('inf'):
                            dist[pair_v[v]] = dist[u] + 1
                            queue.append(pair_v[v])
            return dist_null != float('inf')

        def dfs(u):
            for v in graph[u]:
                if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
            dist[u] = float('inf')
            return False

        result = 0
        while bfs():
            for u in range(num_left):
                if pair_u[u] == -1:
                    if dfs(u):
                        result += 1
        return result

    while low <= high:
        mid = (low + high) // 2
        # Build adjacency list for current mid
        graph = []
        for u in range(N):
            adj = [v for v in range(M) if dist_sq[u][v] <= mid]
            graph.append(adj)
        current = hopcroft_karp(graph, N, M)
        if current >= K:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    print(answer)

