import math

while True:
    n = int(input())
    if n == 0:
        break
    centers = [tuple(map(float, input().split(','))) for _ in range(n)]
    max_overlap = 0

    # Check all centers
    for (xc, yc) in centers:
        cnt = 0
        for (xj, yj) in centers:
            dx = xc - xj
            dy = yc - yj
            if dx*dx + dy*dy <= 4.0 + 1e-8:
                cnt += 1
        if cnt > max_overlap:
            max_overlap = cnt

    # Check all pairs for intersection points
    for i in range(n):
        x1, y1 = centers[i]
        for j in range(i + 1, n):
            x2, y2 = centers[j]
            dx = x2 - x1
            dy = y2 - y1
            d_sq = dx*dx + dy*dy
            if d_sq > 4.0 + 1e-8:
                continue

            d = math.sqrt(d_sq)
            h_sq = max(0.0, 1.0 - d_sq / 4.0)
            h = math.sqrt(h_sq)

            dx_perp = (-dy / d) * h if d != 0 else 0.0
            dy_perp = (dx / d) * h if d != 0 else 0.0

            xm = (x1 + x2) / 2.0
            ym = (y1 + y2) / 2.0

            for px, py in [(xm + dx_perp, ym + dy_perp), (xm - dx_perp, ym - dy_perp)]:
                if 0 <= px <= 10 and 0 <= py <= 10:
                    cnt = 0
                    for (xj, yj) in centers:
                        dx_p = px - xj
                        dy_p = py - yj
                        dist_sq = dx_p*dx_p + dy_p*dy_p
                        if dist_sq <= 1.0 + 1e-8:
                            cnt += 1
                    if cnt > max_overlap:
                        max_overlap = cnt

    print(max_overlap)

