class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        fx = self.find(x)
        fy = self.find(y)
        if fx == fy:
            return False
        self.parent[fy] = fx
        return True

def main():
    import sys
    input = sys.stdin.read().split('\n')
    ptr = 0
    while True:
        while ptr < len(input) and not input[ptr].strip():
            ptr += 1
        if ptr >= len(input):
            break
        line = input[ptr].strip()
        s, d = map(int, line.split())
        ptr += 1
        if s == 0 and d == 0:
            break

        edges = []
        # Read hot springs to districts
        for j in range(s):
            while ptr < len(input) and not input[ptr].strip():
                ptr += 1
            dists = list(map(int, input[ptr].strip().split()))
            ptr += 1
            for i in range(d):
                if dists[i] > 0:
                    u = j + 1
                    v = s + 1 + i
                    edges.append((dists[i], u, v))

        # Read districts to districts
        for i in range(d - 1):
            while ptr < len(input) and not input[ptr].strip():
                ptr += 1
            dists = list(map(int, input[ptr].strip().split()))
            ptr += 1
            for k in range(len(dists)):
                if dists[k] > 0:
                    u = s + 1 + i
                    v = s + 1 + (i + k + 1)
                    edges.append((dists[k], u, v))

        # Add virtual node to hot springs (weight 0)
        for j in range(s):
            edges.append((0, 0, j + 1))

        # Kruskal's algorithm
        edges.sort()
        total_nodes = 1 + s + d  # virtual + springs + districts
        uf = UnionFind(total_nodes)
        total_cost = 0

        for w, u, v in edges:
            if uf.find(u) != uf.find(v):
                uf.union(u, v)
                total_cost += w

        print(total_cost)

