def main():
    n, m = map(int, sys.stdin.readline().split())
    a_rows = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    b_rows = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    if sorted(a_rows) != sorted(b_rows):
        print(-1)
        return

    if n == 1:
        print(0)
        return

    graph = defaultdict(set)
    in_degree = defaultdict(int)
    for c in range(m):
        in_degree[c] = 0

    for i in range(n-1):
        row_i = b_rows[i]
        row_j = b_rows[i+1]
        D = []
        for d in range(m):
            if row_i[d] > row_j[d]:
                D.append(d)
        c = None
        for d in range(m):
            if row_i[d] < row_j[d]:
                c = d
                break
        if D:
            if c is None:
                print(-1)
                return
            for d in D:
                if c not in graph[d]:
                    graph[d].add(c)
                    in_degree[c] += 1

    queue = deque()
    for col in range(m):
        if in_degree[col] == 0:
            queue.append(col)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topo_order) != m:
        print(-1)
        return

    current = [list(row) for row in a_rows]
    for c in topo_order:
        current.sort(key=lambda x: x[c])

    current_tuples = [tuple(row) for row in current]
    if current_tuples != b_rows:
        print(-1)
        return

    print(len(topo_order))
    print(' '.join(map(str, [c+1 for c in topo_order])))

