import math

def compute_probability(a, b):
    if a == 0:
        if b == 0:
            return 1.0
        else:
            return 0.5
    if b == 0:
        return 1.0
    # General case for a > 0 and b > 0
    p0 = math.sqrt(2 * b)
    if a <= p0:
        area = (a**3) / 6 + a * b
    else:
        part1 = (p0**3) / 6 + b * p0
        part2 = 2 * b * (a - p0)
        area = part1 + part2
    total_area = a * 2 * b
    return area / total_area

