def compute_lps(arr):
    n = len(arr)
    lps = [0] * n
    length = 0  # length of the previous longest prefix suffix

    i = 1
    while i < n:
        if arr[i] == arr[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

