            for j in range(1, m+1):
                mask = 0
                for x in range(1, n+1):
                    for y in range(1, m+1):
                        if (x == i and y == j) or (abs(x - i) + abs(y - j) == d):
                            var_idx = (x-1)*m + (y-1)
                            mask ^= (1 << var_idx)
                rhs = grid[i-1][j-1]
                equations.append((mask, rhs))

        rank = 0
        num_vars = m * n
        for col in range(num_vars):
            pivot = -1
            for r in range(rank, len(equations)):
                if (equations[r][0] & (1 << col)) != 0:
                    pivot = r
                    break
            if pivot == -1:
                continue
            equations[rank], equations[pivot] = equations[pivot], equations[rank]
            current_row = equations[rank]
            for r in range(len(equations)):
                if r != rank and (equations[r][0] & (1 << col)):
                    equations[r] = (equations[r][0] ^ current_row[0], equations[r][1] ^ current_row[1])
            rank += 1

        possible = True
        for eq in equations:
            if eq[0] == 0 and eq[1] == 1:
                possible = False
                break

        print(1 if possible else 0)

