def solve():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    while True:
        N = int(input[idx])
        idx += 1
        if N == 0:
            break
        cards = list(map(int, input[idx:idx+N]))
        idx += N
        counts = [0] * 14
        for c in cards:
            counts[c] += 1

        def backtrack(counts, path, current_sum):
            if sum(counts) == 0:
                return path
            possible = []
            for r in range(1, 14):
                if counts[r] > 0 and current_sum % r == 0:
                    possible.append(r)
            possible.sort(reverse=True)
            for r in possible:
                new_counts = counts.copy()
                new_counts[r] -= 1
                new_path = path + [r]
                new_sum = current_sum + r
                res = backtrack(new_counts, new_path, new_sum)
                if res is not None:
                    return res
            return None

        result = None
        for first in range(1, 14):
            if counts[first] == 0:
                continue
            new_counts = counts.copy()
            new_counts[first] -= 1
            res = backtrack(new_counts, [first], first)
            if res is not None:
                result = res
                break

        if result:
            print(' '.join(map(str, result)))
        else:
            print("No")

