            x, y = pos
            moves = []
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] != '#':
                        moves.append((nx, ny))
            return moves

        def compute_outcome(q, a):
            key = (q, a)
            if key in memo:
                return memo[key]
            if q == a:
                memo[key] = -1
                return -1
            if key in processing:
                return 0
            processing.add(key)

            queen_moves = get_valid_moves(q)
