                            outcome = min_outcome if min_outcome != float('inf') else 0
                if outcome > max_outcome:
                    max_outcome = outcome

            if max_outcome == -float('inf'):
                max_outcome = -1

            memo[key] = max_outcome
            processing.discard(key)
            return max_outcome

        result = compute_outcome(q_pos, a_pos)
