import sys
from sys import stdin
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m, k = map(int, stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    L = (n + k - 1) // k
    path = None

    # Check if path is possible
    if L <= n - 1:
        # Attempt to find a path using BFS from each node
        for start in range(1, n + 1):
            visited = [False] * (n + 1)
            parent = [0] * (n + 1)
            q = deque()
            q.append(start)
            visited[start] = True
            max_depth = 0
            last_node = start
            found = False
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parent[v] = u
                        q.append(v)
                        if parent[v] != 0 and (parent[parent[v]] == 0 or parent[parent[v]] != v):
                            depth = 1
                            current = v
                            while parent[current] != 0:
                                current = parent[current]
                                depth += 1
                            if depth >= L:
                                path = []
                                current = v
                                while current != start:
                                    path.append(current)
                                    current = parent[current]
                                path.append(start)
                                path = path[::-1]
                                if len(path) -1 >= L:
                                    print("PATH")
                                    print(len(path))
                                    print(' '.join(map(str, path)))
                                    return
                                else:
                                    path = None
            if path:
                break

    # If no path found, try to find cycles
    cycles = []
    used = set()

    for u in range(1, n + 1):
        if len(cycles) >= k:
            break
        if u in used:
            continue
        neighbors = adj[u]
        found = False
        # Try to find two neighbors a and b that have a common neighbor c != u
        for i in range(len(neighbors)):
            a = neighbors[i]
            for j in range(i + 1, len(neighbors)):
                b = neighbors[j]
                if b in adj[a]:
                    continue  # cycle length 3
                # Check common neighbor c != u
                for c in adj[a]:
                    if c != u and c in adj[b]:
                        cycle = [u, a, c, b]
                        cycles.append((u, cycle))
                        used.add(u)
                        found = True
                        break
                if found:
                    break
                # Check another way
                for c in adj[b]:
                    if c != u and c in adj[a]:
                        cycle = [u, b, c, a]
                        cycles.append((u, cycle))
                        used.add(u)
                        found = True
                        break
                if found:
                    break
            if found:
                break
        if not found:
            # Alternative method: find a cycle via DFS back edges
            visited = {}
            parent = {}
            stack = [(u, None)]
            while stack:
                v, p = stack.pop()
                if v in visited:
                    if v == u and p is not None:
                        cycle = []
                        current = p
                        cycle.append(current)
                        while parent[current] != u:
                            current = parent[current]
                            cycle.append(current)
                        cycle.append(u)
                        if len(cycle) >=3 and len(cycle) %3 !=0:
                            cycles.append((u, [u] + cycle[::-1]))
                            used.add(u)
                            found = True
                    continue
                visited[v] = True
                parent[v] = p
                for w in adj[v]:
                    if w != p and w not in visited:
                        stack.append((w, v))
                if found:
                    break

    if len(cycles) >= k:
        print("CYCLES")
        for rep, cycle in cycles[:k]:
            print(len(cycle))
            print(' '.join(map(str, cycle)))
        return

    print(-1)

