import sys

def main():
    n, h, m, k = map(int, sys.stdin.readline().split())
    m_half = m // 2
    trains = []
    events = []

    for _ in range(n):
        h_i, m_i = map(int, sys.stdin.readline().split())
        s_total = h_i * m + m_i
        start = s_total % m_half
        end = (start + k) % m_half

        if start < end:
            a = start + 1
            b = end
            if a < b:
                events.append((a, 1))
                events.append((b, -1))
        else:
            a1 = start + 1
            b1 = m_half
            if a1 < b1:
                events.append((a1, 1))
                events.append((b1, -1))
            a2 = 0
            b2 = end
            if a2 < b2:
                events.append((a2, 1))
                events.append((b2, -1))
        trains.append((start, end))

    events.sort()
    min_coverage = n + 1
    current_coverage = 0
    prev_pos = 0
    best_intervals = []

    for pos, delta in events:
        if prev_pos < pos:
            coverage = current_coverage
            if coverage < min_coverage:
                min_coverage = coverage
                best_intervals = [(prev_pos, pos)]
            elif coverage == min_coverage:
                best_intervals.append((prev_pos, pos))
        current_coverage += delta
        prev_pos = pos

    if prev_pos < m_half:
        coverage = current_coverage
        if coverage < min_coverage:
            min_coverage = coverage
            best_intervals = [(prev_pos, m_half)]
        elif coverage == min_coverage:
            best_intervals.append((prev_pos, m_half))

    best_t = None
    for a, b in best_intervals:
        if a < b:
            candidate = a
            if best_t is None or candidate < best_t:
                best_t = candidate

    canceled = []
    for i in range(n):
        start, end = trains[i]
        if start < end:
            if start < best_t < end:
                canceled.append(i + 1)
        else:
            if best_t > start or best_t < end:
                canceled.append(i + 1)

    print(len(canceled), best_t)
    if canceled:
        print(' '.join(map(str, canceled)))

