def generate_k_tickets(k, m):
    tickets = set()
    if k == 0:
        # Generate numbers with at least one '0'
        count = 0
        num = 0
        while count < m:
            s = f"{num:08d}"
            if '0' in s:
                tickets.add(s)
                count += 1
            num += 1
    else:
        # Generate split-based tickets
        for x in range(1, 8):
            x_digits = x
            y_digits = 8 - x
            max_a = min(k, 10**x_digits - 1)
            min_a = max(0, k - (10**y_digits - 1))
            if min_a > max_a:
                continue
            for a in range(min_a, max_a + 1):
                b = k - a
                if b < 0 or b > 10**y_digits - 1:
                    continue
                ticket = f"{a:0{x_digits}}{b:0{y_digits}}"
                if len(ticket) == 8:
                    tickets.add(ticket)
                    if len(tickets) >= m:
                        break
            if len(tickets) >= m:
                break
        # Add the full number as k padded to 8 digits
        full_ticket = f"{k:08d}"
        if len(full_ticket) == 8:
            tickets.add(full_ticket)
        # Generate sum-based tickets if k <= 72
        if k <= 72:
            from itertools import product
            digits = []
            for digits_tuple in product(range(10), repeat=8):
                if sum(digits_tuple) == k:
                    ticket = ''.join(map(str, digits_tuple))
                    tickets.add(ticket)
                    if len(tickets) >= m:
                        break
    # Convert to list and output m tickets
    result = list(tickets)[:m]
    for t in result:
        print(t)

