import math

def get_info(initial_h, x, y, a, m):
    current_h = initial_h
    time = 0
    seen = {}
    times = []
    while current_h not in seen:
        if current_h == a:
            times.append(time)
        seen[current_h] = time
        current_h = (x * current_h + y) % m
        time += 1
    cycle_start = seen[current_h]
    cycle_length = time - cycle_start
    pre_cycle = [t for t in times if t < cycle_start]
    in_cycle = [t for t in times if cycle_start <= t < cycle_start + cycle_length]
    return {
        'pre_cycle': pre_cycle,
        'cycle_start': cycle_start,
        'cycle_length': cycle_length,
        'in_cycle': in_cycle
    }

def solve():
    import sys
    m = int(sys.stdin.readline())
    h1, a1 = map(int, sys.stdin.readline().split())
    x1, y1 = map(int, sys.stdin.readline().split())
    h2, a2 = map(int, sys.stdin.readline().split())
    x2, y2 = map(int, sys.stdin.readline().split())

    x_data = get_info(h1, x1, y1, a1, m)
    y_data = get_info(h2, x2, y2, a2, m)

    min_time = float('inf')

    # Case 1: X's pre and Y's pre
    for t in x_data['pre_cycle']:
        if t in y_data['pre_cycle']:
            min_time = min(min_time, t)

    # Case 2: X's pre and Y's cycle
    if y_data['in_cycle']:
        y_start = y_data['cycle_start']
        y_len = y_data['cycle_length']
        y_offsets = {t - y_start for t in y_data['in_cycle']}
        for t in x_data['pre_cycle']:
            if t >= y_start:
                rem = (t - y_start) % y_len
                if rem in y_offsets:
                    min_time = min(min_time, t)

    # Case 3: Y's pre and X's cycle
    if x_data['in_cycle']:
        x_start = x_data['cycle_start']
        x_len = x_data['cycle_length']
        x_offsets = {t - x_start for t in x_data['in_cycle']}
        for t in y_data['pre_cycle']:
            if t >= x_start:
                rem = (t - x_start) % x_len
                if rem in x_offsets:
                    min_time = min(min_time, t)

    # Case 4: X's cycle and Y's cycle
    if x_data['in_cycle'] and y_data['in_cycle']:
        x_start = x_data['cycle_start']
        x_len = x_data['cycle_length']
        y_start = y_data['cycle_start']
        y_len = y_data['cycle_length']
        for x_off in x_data['in_cycle']:
            for y_off in y_data['in_cycle']:
                a, b = x_off, y_off
                m_t, n_t = x_len, y_len
                d = math.gcd(m_t, n_t)
                if (a - b) % d != 0:
                    continue
                m_prime = m_t // d
                n_prime = n_t // d
                c = (b - a) // d
                try:
                    inv = pow(m_prime, -1, n_prime)
                except ValueError:
                    continue
                k0 = (c * inv) % n_prime
                t0 = a + k0 * m_t
                lcm = (m_t * n_t) // d
                required = max(a, b)
                if t0 < required:
                    delta = required - t0
                    steps = (delta + lcm - 1) // lcm
                    t0 += steps * lcm
                if t0 < min_time:
                    min_time = t0

    print(min_time if min_time != float('inf') else -1)

