    if max_s < 2:
        print(0)
        return

    # Precompute smallest prime factors up to max_s
    spf = list(range(max_s + 1))
    for i in range(2, int(max_s ** 0.5) + 1):
        if spf[i] == i:  # i is a prime
            for j in range(i * i, max_s + 1, i):
                if spf[j] == j:
                    spf[j] = i

    count = defaultdict(int)

