        if x == 1:
            continue
        temp = x
        primes = set()
        while temp != 1:
            p = spf[temp]
            primes.add(p)
            while temp % p == 0:
                temp //= p
        for p in primes:
            count[p] += 1

    if not count:
        print(0)
    else:
        max_count = max(count.values())
        print(max_count if max_count >= 2 else 0)

