def main():
    base = 911382629
    mod = 10**18 + 3

    # Precompute powers of base up to 32
    pow_base = [1] * 33
    for i in range(1, 33):
        pow_base[i] = (pow_base[i-1] * base) % mod

    # Generate valid rows and their hashes
    valid_rows = []
    for a in range(32):
        row = []
        for b in range(32):
            if (a + b) % 2 == 0:
                row.append('_')
            else:
                row.append('#')
        valid_rows.append(''.join(row))

    valid_hash_to_a = {}
    for a in range(32):
        s = valid_rows[a]
        current_hash = 0
        for c in s:
            current_hash = (current_hash * base + ord(c)) % mod
        valid_hash_to_a[current_hash] = a

    # Read input
    n, m = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(n)]

    # Precompute bitmask for each row and a
    row_a_bitmask = [[0 for _ in range(32)] for _ in range(n)]

    for i in range(n):
        s = grid[i]
        len_s = len(s)
        if len_s < 32:
            continue
        prefix_hash = [0] * (len_s + 1)
        for j in range(len_s):
            prefix_hash[j+1] = (prefix_hash[j] * base + ord(s[j])) % mod
        for j in range(len_s - 31):
            current_hash = (prefix_hash[j+32] - prefix_hash[j] * pow_base[32]) % mod
            current_hash = current_hash % mod
            a = valid_hash_to_a.get(current_hash, -1)
            if a != -1:
                row_a_bitmask[i][a] |= 1 << j

    # Count valid boards
    count = 0
    max_x = n - 32
    max_y = m - 32
    for x in range(max_x + 1):
        for y in range(max_y + 1):
            valid = True
            for a in range(32):
                current_row = x + a
                if (row_a_bitmask[current_row][a] & (1 << y)) == 0:
                    valid = False
                    break
            if valid:
                count += 1
    print(count)

