    katanas_sorted = sorted(katanas, key=lambda x: -x[1])
    prefix_b = [0] * (N + 1)
    for i in range(N):
        prefix_b[i+1] = prefix_b[i] + katanas_sorted[i][1]

    max_a_suffix = [0] * (N + 1)
    for i in range(N-1, -1, -1):
        max_a_suffix[i] = max(katanas_sorted[i][0], max_a_suffix[i+1])

    min_attacks = float('inf')

    # Check all possible k in initial approach
    for k in range(N + 1):
        sum_b = prefix_b[k]
        if sum_b >= H:
            candidate = k
        else:
            a_remain = max_a_suffix[k]
            if a_remain == 0:
                continue  # Not possible
            rem = H - sum_b
            attacks = k + (rem + a_remain - 1) // a_remain
            candidate = attacks
        if candidate < min_attacks:
            min_attacks = candidate

    # Check each katana for x uses then throw
    for a, b in katanas:
        if b >= H:
            if 1 < min_attacks:
                min_attacks = 1
            continue
        rem = H - b
        if a == 0:
            continue  # Not possible as per problem constraints
        x = (rem + a - 1) // a
        total_attacks = x + 1
        if a * x + b >= H and total_attacks < min_attacks:
            min_attacks = total_attacks

    print(min_attacks)

