import sys
import random

random.seed(0)

class Node:
    __slots__ = ['key', 'pri', 'left', 'right', 'size']
    def __init__(self, key, pri):
        self.key = key
        self.pri = pri
        self.left = None
        self.right = None
        self.size = 1

    def update_size(self):
        self.size = 1
        if self.left:
            self.size += self.left.size
        if self.right:
            self.size += self.right.size

def split(node, key):
    if node is None:
        return (None, None)
    if node.key <= key:
        left, right = split(node.right, key)
        node.right = left
        node.update_size()
        return (node, right)
    else:
        left, right = split(node.left, key)
        node.left = right
        node.update_size()
        return (left, node)

def merge(left, right):
    if left is None:
        return right
    if right is None:
        return left
    if left.pri > right.pri:
        left.right = merge(left.right, right)
        left.update_size()
        return left
    else:
        right.left = merge(left, right.left)
        right.update_size()
        return right

def insert(root, key, pri):
    new_node = Node(key, pri)
    left, right = split(root, key)
    return merge(merge(left, new_node), right)

def delete(root, key):
    split_key = (key[0], key[1] - 1)
    left, right = split(root, split_key)
    left_right, right_right = split(right, key)
    return merge(left, right_right)

def find_kth(node, k):
    while node:
        left_size = node.left.size if node.left else 0
        if k < left_size:
            node = node.left
        elif k == left_size:
            return node.key
        else:
            k -= left_size + 1
            node = node.right
    return None

