def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr +=1
    for _ in range(T):
        N = int(input[ptr])
        M = int(input[ptr+1])
        ptr +=2
        edges = []
        for __ in range(M):
            u = int(input[ptr])
            v = int(input[ptr+1])
            ptr +=2
            if u > v:
                u, v = v, u
            edges.append((u, v))
        result = 0
        for mask in range(0, 1 << M):
            S_edges = [edges[i] for i in range(M) if (mask >> i) & 1]
            m = len(S_edges)
            if m > N - 1:
                continue
            adj = {}
            degree = {}
            nodes = set()
            for u, v in S_edges:
                adj.setdefault(u, []).append(v)
                adj.setdefault(v, []).append(u)
                degree[u] = degree.get(u, 0) + 1
                degree[v] = degree.get(v, 0) + 1
                nodes.add(u)
                nodes.add(v)
            invalid = False
            for node in degree:
                if degree[node] > 2:
                    invalid = True
                    break
            if invalid:
                continue
            visited = set()
            c_edges = 0
            invalid_component = False
            for node in nodes:
                if node not in visited:
                    stack = [node]
                    component = set()
                    component.add(node)
                    visited.add(node)
                    while stack:
                        current = stack.pop()
                        for neighbor in adj.get(current, []):
                            if neighbor not in visited:
                                visited.add(neighbor)
                                component.add(neighbor)
                                stack.append(neighbor)
                    has_edges = False
                    for n in component:
                        if degree.get(n, 0) > 0:
                            has_edges = True
                            break
                    if not has_edges:
                        continue
                    cnt_deg1 = 0
                    for n in component:
                        d = degree.get(n, 0)
                        if d == 1:
                            cnt_deg1 += 1
                        elif d != 2:
                            invalid_component = True
                            break
                    if invalid_component:
                        break
                    if cnt_deg1 != 2:
                        invalid_component = True
                        break
                    c_edges += 1
            if invalid_component:
                continue
            sign = (-1) ** m
            pow2 = pow(2, c_edges, MOD)
            if N - m < 0:
                fact_term = 0
            else:
                fact_term = fact[N - m]
            term = sign * pow2 * fact_term % MOD
            result = (result + term) % MOD
        print(result % MOD)

