def factor(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    max_i = int(n**0.5) + 1
    while i <= max_i and n > 1:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
            max_i = int(n**0.5) + 1
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p in factors:
        exponents = [p**e for e in range(1, factors[p] + 1)]
        new_divisors = []
        for d in divisors:
            for e in exponents:
                new_divisors.append(d * e)
        divisors += new_divisors
    divisors = sorted(divisors)
    return divisors

