import math

def sieve(n):
    """Generate list of primes up to n using Sieve of Eratosthenes."""
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve[i]:
            sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])
    return [i for i, is_prime in enumerate(sieve) if is_prime]

def segmented_sieve(l, r, block_size=10**6):
    """Generate primes in [l, r] using segmented sieve with block processing."""
    if l > r:
        return []
    primes = sieve(int(math.isqrt(r)) + 1)
    prime_list = []
    for low in range(l, r + 1, block_size):
        high = min(low + block_size - 1, r)
        sieve_len = high - low + 1
        sieve_segment = [True] * sieve_len
        if low == 0:
            sieve_segment[0] = False
            if high >= 1:
                sieve_segment[1] = False
        elif low == 1:
            sieve_segment[0] = False
        for p in primes:
            start = max(p * p, ((low + p - 1) // p) * p)
            if start > high:
                continue
            start_idx = start - low
            sieve_segment[start_idx::p] = [False] * len(sieve_segment[start_idx::p])
        for i in range(sieve_len):
            if sieve_segment[i]:
                num = low + i
                prime_list.append(num)
    return prime_list

