import math

def read_points():
    n = int(input())
    points = []
    for _ in range(n):
        x, y = map(float, input().split())
        points.append((x, y))
    return points

def convex_hull(points):
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def vector_angle(v):
    return math.atan2(v[1], v[0])

def angle_between_edges(hull):
    min_angle = float('inf')
    n = len(hull)
    for i in range(n):
        a = hull[i]
        b = hull[(i+1)%n]
        dx1 = b[0] - a[0]
        dy1 = b[1] - a[1]
        for j in range(i+1, n):
            c = hull[j]
            d = hull[(j+1)%n]
            dx2 = d[0] - c[0]
            dy2 = d[1] - c[1]
            angle1 = vector_angle((dx1, dy1))
            angle2 = vector_angle((dx2, dy2))
            diff = abs(angle1 - angle2)
            diff = min(diff, 2 * math.pi - diff)
            deg_diff = math.degrees(diff)
            if deg_diff < min_angle:
                min_angle = deg_diff
    return min_angle

