import math

def main():
    n = int(input())
    strings = [input().strip() for _ in range(n)]
    m = len(strings[0]) if n > 0 else 0

    if n == 1:
        print("0.000000000000000")
        return

    # Precompute combinations for m choose t
    comb_m = [math.comb(m, t) for t in range(m + 1)]

    total_expectation = 0.0

    for s in strings:
        diffs = []
        for other in strings:
            if other == s:
                continue
            mask = 0
            for i in range(m):
                if s[i] != other[i]:
                    mask |= 1 << i
            diffs.append(mask)

        hits = [0] * (m + 1)

        # Iterate over all possible subsets (bitmask)
        for mask in range(1 << m):
            valid = True
            for D in diffs:
                if (mask & D) == 0:
                    valid = False
                    break
            if valid:
                t = bin(mask).count('1')
                hits[t] += 1

        # Calculate expected contribution for this string
        s_expectation = 0.0
        for k in range(1, m + 1):
            t = k - 1
            if comb_m[t] == 0:
                prob = 0.0
            else:
                bad = comb_m[t] - hits[t]
                prob = bad / comb_m[t]
            s_expectation += prob

        total_expectation += s_expectation / n

    print("{0:.15f}".format(total_expectation))

