MOD = 10**9 + 7

def factor(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for prime, exp in factors.items():
        primes_powers = [prime**e for e in range(1, exp + 1)]
        temp = []
        for d in divisors:
            for pp in primes_powers:
                temp.append(d * pp)
        divisors += temp
        divisors = list(sorted(set(divisors)))
    return divisors

def multiplicative_order(k, p):
    if k == 0 or p <= 1:
        return 0
    phi = p - 1
    factors = factor(phi)
    divisors = generate_divisors(factors)
    for m in divisors:
        if pow(k, m, p) == 1:
            return m
    return phi

