from collections import defaultdict

def main():
    while True:
        n, m = map(int, input().split())
        if n == 0 and m == 0:
            break
        s, g = map(int, input().split())
        adj = defaultdict(list)
        for _ in range(m):
            x, y, d, c = map(int, input().split())
            adj[x].append((y, d, c))
            adj[y].append((x, d, c))

        heap = []
        dist = dict()

        # Initialize with roads from s at speed 1
        for road in adj[s]:
            next_city, d, c = road
            if 1 <= c:
                time = d / 1.0
                state = (next_city, s, 1)
                if state not in dist or time < dist[state]:
                    dist[state] = time
                    heapq.heappush(heap, (time, next_city, s, 1))

        found = False
        answer = 0.0
        while heap:
            current_time, u, prev_u, speed = heapq.heappop(heap)

            # Check if goal is reached with speed 1
            if u == g and speed == 1:
                found = True
                answer = current_time
                break

            # Skip if a better time already exists
            if (u, prev_u, speed) in dist and current_time > dist[(u, prev_u, speed)]:
                continue

            # Generate possible speed adjustments
            for delta in (-1, 0, 1):
                new_speed = speed + delta
                if new_speed < 1:
                    continue

                # Explore all adjacent cities except previous
                for road in adj[u]:
                    v, d, c = road
                    if v == prev_u:
                        continue
                    if new_speed > c:
                        continue

                    new_time = current_time + d / new_speed
                    new_state = (v, u, new_speed)
                    if new_state not in dist or new_time < dist.get(new_state, float('inf')):
                        dist[new_state] = new_time
                        heapq.heappush(heap, (new_time, v, u, new_speed))

        if found:
            print("{0:.5f}".format(answer))
        else:
            print("unreachable")

