            adj[X].append((Y, T))
            adj[Y].append((X, T))

        INF = float('inf')
        dist = [[INF] * (M + 1) for _ in range(N)]
        heap = []
        dist[A][M] = 0
        heapq.heappush(heap, (0, A, M))
        found = False

        while heap:
            time, u, s = heapq.heappop(heap)
            if u == H:
                print(time)
                found = True
                break
            if time > dist[u][s]:
                continue

            for v, T in adj[u]:
                if s >= T:
                    new_s = s - T
                    new_time = time + T
                    if new_s >= 0 and new_time < dist[v][new_s]:
                        dist[v][new_s] = new_time
                        heapq.heappush(heap, (new_time, v, new_s))

            if u in freezing:
                max_x = M - s
                for x in range(0, max_x + 1):
                    new_s = s + x
                    new_time = time + x
                    if new_s > M:
                        continue
                    if new_time < dist[u][new_s]:
                        dist[u][new_s] = new_time
                        heapq.heappush(heap, (new_time, u, new_s))

