import sys

def square_free(x):
    if x == 0:
        return 0
    sign = 1 if x > 0 else -1
    x = abs(x)
    square_free_part = 1

    # Handle even factors
    exponent = 0
    while x % 2 == 0:
        x = x // 2
        exponent += 1
    if exponent % 2 == 1:
        square_free_part *= 2

    # Check odd factors
    i = 3
    while i * i <= x:
        exponent = 0
        while x % i == 0:
            x = x // i
            exponent += 1
        if exponent % 2 == 1:
            square_free_part *= i
        i += 2

    if x > 1:
        square_free_part *= x
    return sign * square_free_part

