def is_palindrome(s, left, right):
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def find_palindrome_index(s):
    left = 0
    right = len(s) - 1
    while left < right:
        if s[left] == s[right]:
            left += 1
            right -= 1
        else:
            if is_palindrome(s, left + 1, right):
                return left
            if is_palindrome(s, left, right - 1):
                return right
            return -2  # According to problem constraints, this line should never be reached
    return -1

