    def min_max(nums, bit):
        if bit < 0:
            return 0
        mask = 1 << bit
        zeros = []
        ones = []
        for num in nums:
            if num & mask:
                ones.append(num)
            else:
                zeros.append(num)
        if not zeros:
            return min_max(ones, bit - 1)
        elif not ones:
            return min_max(zeros, bit - 1)
        else:
            return (1 << bit) + min(min_max(zeros, bit - 1), min_max(ones, bit - 1))

