from collections import defaultdict

def main():
    max_a = 200000
    spf = list(range(max_a + 1))
    for i in range(2, int(max_a**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def factorize(x):
        factors = {}
        if x == 1:
            return factors
        while x != 1:
            p = spf[x]
            count = 0
            while x % p == 0:
                x //= p
                count += 1
            factors[p] = count
        return factors

    n, *rest = map(int, sys.stdin.read().split())
    a = rest[:n]

    primes_dict = defaultdict(list)

    for num in a:
        factors = factorize(num)
        for p, exp in factors.items():
            primes_dict[p].append(exp)

    result = 1
    for p in primes_dict:
        count_p = len(primes_dict[p])
        if count_p >= n - 1:
            exponents = primes_dict[p]
            exponents.sort()
            if count_p == n:
                required_exp = exponents[1]
            else:
                required_exp = exponents[0]
            result *= p ** required_exp

    print(result)

