import sys
MOD = 10**9 + 7

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, t = map(int, sys.stdin.readline().split())
        adj[u].append((v, t))
        adj[v].append((u, t))

    visited = [False] * (n + 1)
    total = 0

    for u in range(1, n + 1):
        if not visited[u]:
            from collections import deque
            q = deque()
            q.append(u)
            visited[u] = True
            xor_val = {u: 0}
            parent = {u: -1}
            component_nodes = [u]
            cycle_xors = []

            while q:
                current = q.popleft()
                for (nei, t) in adj[current]:
                    if not visited[nei]:
                        visited[nei] = True
                        xor_val[nei] = xor_val[current] ^ t
                        parent[nei] = current
                        q.append(nei)
                        component_nodes.append(nei)
                    elif parent[current] != nei:
                        cx = xor_val[current] ^ xor_val[nei] ^ t
                        cycle_xors.append(cx)

            # Build the basis using Gaussian elimination
            basis_temp = [0] * 61
            for x in cycle_xors:
                if x == 0:
                    continue
                current = x
                for i in reversed(range(61)):
                    if (current >> i) & 1:
                        if basis_temp[i]:
                            current ^= basis_temp[i]
                        else:
                            basis_temp[i] = current
                            break
            basis = [b for b in basis_temp if b != 0]
            k = len(basis)
            c = len(component_nodes)

            for i in range(61):
                has_bit = False
                for b in basis:
                    if (b >> i) & 1:
                        has_bit = True
                        break
                if has_bit:
                    term = (c * (c - 1) // 2) % MOD
                    exponent = (k - 1 + i)
                    pow_val = pow(2, exponent, MOD)
                    contrib = (term * pow_val) % MOD
                    total = (total + contrib) % MOD
                else:
                    count_1 = 0
                    for node in component_nodes:
                        if (xor_val[node] >> i) & 1:
                            count_1 += 1
                    term = (count_1 * (c - count_1)) % MOD
                    exponent = (k + i)
                    pow_val = pow(2, exponent, MOD)
                    contrib = (term * pow_val) % MOD
                    total = (total + contrib) % MOD

    print(total % MOD)

