mod = 4294967143
n_digits = 11

# Initialize the adjacency matrix
M = np.zeros((n_digits, n_digits), dtype=np.int64)
for i in range(n_digits):
    for j in range(n_digits):
        if abs(i - j) == 1:
            M[i][j] = 1

def matrix_power(mat, power):
    result = np.eye(n_digits, dtype=np.int64)
    while power > 0:
        if power % 2 == 1:
            result = (result @ mat) % mod
        mat = (mat @ mat) % mod
        power //= 2
    return result

