    degrees = [0] * (N+1)
    for _ in range(N-1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)
        degrees[a] += 1
        degrees[b] += 1

    queue = deque()
    matched = [False] * (N+1)
    for i in range(1, N+1):
        if degrees[i] == 1:
            queue.append(i)

    while queue:
        u = queue.popleft()
        if matched[u]:
            continue
        # Find the only possible parent v
        v = None
        for candidate in adj[u]:
            if not matched[candidate]:
                v = candidate
                break
        if v is None or matched[v]:
            print("First")
            return
        matched[u] = matched[v] = True
        # Decrease degrees of v's neighbors
        for neighbor in adj[v]:
            if neighbor == u or matched[neighbor]:
                continue
            degrees[neighbor] -= 1
            if degrees[neighbor] == 1:
                queue.append(neighbor)

    if sum(matched) == N:
        print("Second")
    else:
        print("First")

