from collections import deque

def main():
    n, k = map(int, sys.stdin.readline().split())
    edges = []
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, sys.stdin.readline().split())
        edges.append((a, b))
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        dist = [-1] * (n + 1)
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    max_count = 0

    if k % 2 == 0:
        t = k // 2
        for u in range(1, n + 1):
            dist = bfs(u)
            cnt = sum(1 for x in dist[1:] if x <= t and x != -1)
            if cnt > max_count:
                max_count = cnt
    else:
        t = (k - 1) // 2
        for a, b in edges:
            dist_a = bfs(a)
            dist_b = bfs(b)
            cnt = 0
            for i in range(1, n + 1):
                if dist_a[i] <= t or dist_b[i] <= t:
                    cnt += 1
            if cnt > max_count:
                max_count = cnt

