import sys

def get_primes(k):
    primes = []
    candidate = 2
    while len(primes) < k:
        is_prime = True
        for p in primes:
            if candidate % p == 0:
                is_prime = False
                break
            if p * p > candidate:
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1
    return primes

def generate_partitions(n, max_factor, current):
    if n == 1:
        if current:
            yield current
        return
    factors = set()
    for i in range(2, min(max_factor, n) + 1):
        if n % i == 0:
            factors.add(i)
    if n >= 2 and n <= max_factor:
        factors.add(n)
    for d in sorted(factors, reverse=True):
        yield from generate_partitions(n // d, d, current + [d])

