def main():
    import sys
    from math import gcd

    def combine(a1, m1, a2, m2):
        if m1 == 0 or m2 == 0:
            return None
        g = gcd(m1, m2)
        if (a2 - a1) % g != 0:
            return None
        m1_dash = m1 // g
        m2_dash = m2 // g
        a_dash = (a2 - a1) // g

        def extended_gcd(a, b):
            if a == 0:
                return (b, 0, 1)
            else:
                g, y, x = extended_gcd(b % a, a)
                return (g, x - (b // a) * y, y)

        g_inv, x, y = extended_gcd(m1_dash, m2_dash)
        if g_inv != 1:
            return None
        inv = x % m2_dash
        k0 = (a_dash * inv) % m2_dash
        x0 = a1 + k0 * m1
        m_new = m1 * m2 // g
        a_new = x0 % m_new
        return (a_new, m_new)

    # Read input
    N = int(sys.stdin.readline())
    P = list(map(int, sys.stdin.readline().split()))
    Q = list(map(int, sys.stdin.readline().split()))

    # Decompose Q into cycles
    visited = [False] * (N + 1)
    cycles = []
    for x in range(1, N + 1):
        if not visited[x]:
            current = x
            cycle = []
            while True:
                if visited[current]:
                    break
                visited[current] = True
                cycle.append(current)
                current = Q[current - 1]
            cycles.append(cycle)

    # Check if P[i] is in the same cycle as i for all i
    cycle_map = {}
    for idx, cycle in enumerate(cycles):
        for num in cycle:
            cycle_map[num] = idx
    for i in range(1, N + 1):
        if cycle_map[i] != cycle_map[P[i - 1]]:
            print(-1)
            return

    # Process each cycle to get congruences
    congruences = []
    for cycle in cycles:
        L = len(cycle)
        pos = {num: idx for idx, num in enumerate(cycle)}
        first_k = None
        valid = True
        for num in cycle:
            p_num = P[num - 1]
            pos_num = pos[num]
            pos_p = pos[p_num]
            k = (pos_num - pos_p) % L
            if first_k is None:
                first_k = k
            elif k != first_k:
                print(-1)
                return
        congruences.append((first_k, L))

    # Solve the system of congruences
    current_a = 0
    current_m = 1
    for a, m in congruences:
        if m == 1:
            continue  # no effect
        res = combine(current_a, current_m, a, m)
        if not res:
            print(-1)
            return
        current_a, current_m = res

    print(current_a)

