class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [{'ee': 0, 'eo': 0, 'oe': 0, 'oo': 0} for _ in range(2 * self.size)]
        for i in range(self.n):
            val = data[i]
            self.tree[self.size + i] = {'ee': 0, 'eo': val, 'oe': -val, 'oo': 0}
        for i in range(self.size - 1, 0, -1):
            left = 2 * i
            right = 2 * i + 1
            self.tree[i] = self.merge(self.tree[left], self.tree[right])

    def merge(self, left, right):
        ee = max(left['ee'] + right['ee'], left['eo'] + right['oe'])
        eo = max(left['ee'] + right['eo'], left['eo'] + right['oo'])
        oe = max(left['oe'] + right['ee'], left['oo'] + right['oe'])
        oo = max(left['oe'] + right['eo'], left['oo'] + right['oo'])
        return {'ee': ee, 'eo': eo, 'oe': oe, 'oo': oo}

    def update(self, pos, value):
        pos += self.size
        self.tree[pos] = {'ee': 0, 'eo': value, 'oe': -value, 'oo': 0}
        pos >>= 1
        while pos >= 1:
            left = 2 * pos
            right = 2 * pos + 1
            self.tree[pos] = self.merge(self.tree[left], self.tree[right])
            pos >>= 1

    def get_max(self):
        return max(self.tree[1]['ee'], self.tree[1]['eo'])

