import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    # Precompute all-pairs shortest paths using BFS
    dist = [[-1] * (n + 1) for _ in range(n + 1)]
    for u in range(1, n + 1):
        q = deque()
        q.append(u)
        dist[u][u] = 0
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if dist[u][neighbor] == -1:
                    dist[u][neighbor] = dist[u][current] + 1
                    q.append(neighbor)

    # Read the two paths' constraints
    s1, t1, l1 = map(int, sys.stdin.readline().split())
    s2, t2, l2 = map(int, sys.stdin.readline().split())

    # Check if initial paths are possible
    if dist[s1][t1] > l1 or dist[s2][t2] > l2:
        print(-1)
        return

    sum_initial = dist[s1][t1] + dist[s2][t2]
    min_sum = sum_initial

    # Iterate all possible u and v to find better sums
    for u in range(1, n + 1):
        for v in range(1, n + 1):
            # Calculate possible len1 options for path1 (s1 to t1 via u and v)
            len1_options = []
            case1 = dist[s1][u] + dist[u][v] + dist[v][t1]
            if case1 <= l1:
                len1_options.append(case1)
            case2 = dist[s1][v] + dist[u][v] + dist[u][t1]
            if case2 <= l1:
                len1_options.append(case2)
            if not len1_options:
                continue

            # Calculate possible len2 options for path2 (s2 to t2 via u and v)
            len2_options = []
            case1_p2 = dist[s2][u] + dist[u][v] + dist[v][t2]
            if case1_p2 <= l2:
                len2_options.append(case1_p2)
            case2_p2 = dist[s2][v] + dist[u][v] + dist[u][t2]
            if case2_p2 <= l2:
                len2_options.append(case2_p2)
            if not len2_options:
                continue

            # Update min_sum with all combinations of len1 and len2
            for len1 in len1_options:
                for len2 in len2_options:
                    current_sum = len1 + len2 - dist[u][v]
                    if current_sum < min_sum:
                        min_sum = current_sum

    print(m - min_sum)

