class Node:
    def __init__(self, val):
        self.val = val
        self.parent = None
        self.left = None
        self.right = None
        self.rev = False

    def is_root(self):
        return self.parent is None or (self.parent.left != self and self.parent.right != self)

    def push(self):
        if self.rev:
            self.rev = False
            self.left, self.right = self.right, self.left
            if self.left:
                self.left.rev ^= True
            if self.right:
                self.right.rev ^= True

    def rotate(self):
        p = self.parent
        g = p.parent
        if g is not None:
            if g.left == p:
                g.left = self
            else:
                g.right = self
        self.parent = g
        if p.left == self:
            p.left = self.right
            if self.right:
                self.right.parent = p
            self.right = p
        else:
            p.right = self.left
            if self.left:
                self.left.parent = p
            self.left = p
        p.parent = self

    def splay(self):
        while not self.is_root():
            p = self.parent
            if p.is_root():
                p.push()
                self.push()
                self.rotate()
            else:
                g = p.parent
                g.push()
                p.push()
                self.push()
                if (g.left == p) == (p.left == self):
                    p.rotate()
                    self.rotate()
                else:
                    self.rotate()
                    self.rotate()

    def access(self):
        self.splay()
        self.push()
        self.right = None
        curr = self
        while curr.parent is not None:
            p = curr.parent
            p.splay()
            p.push()
            p.right = curr
            curr.splay()
            curr = p
        return curr

    def find_root(self):
        self.access()
        curr = self
        curr.push()
        while curr.left:
            curr = curr.left
            curr.push()
        curr.access()
        return curr

    def evert(self):
        self.access()
        self.rev ^= True
        self.push()

    def link(self, other):
        self.evert()
        other.access()
        self.parent = other

    def cut(self):
        self.access()
        if self.left:
            self.left.parent = None
            self.left = None

