    # Precompute training DP
    max_e = S
    training_dp = [[-float('inf')] * (max_e + 1) for _ in range(U + 1)]
    training_dp[0][0] = 0
    for e_i, c_i in trainings:
        for u in range(U-1, -1, -1):
            for sum_e in range(max_e + 1):
                if training_dp[u][sum_e] != -float('inf'):
                    new_u = u + 1
                    new_sum_e = sum_e + e_i
                    new_sum_c = training_dp[u][sum_e] + c_i
                    if new_u <= U and new_sum_e <= max_e:
                        if training_dp[new_u][new_sum_e] < new_sum_c:
                            training_dp[new_u][new_sum_e] = new_sum_c

    # Precompute donut DP
    max_c = U * 100  # max possible sum_c
    donut_dp = [0] * (max_c + 1)
    for h_j, a_j in donuts:
        for a in range(a_j, max_c + 1):
            if donut_dp[a - a_j] + h_j > donut_dp[a]:
                donut_dp[a] = donut_dp[a - a_j] + h_j

    # Main DP
    main_dp = [[-float('inf')] * (S + 1) for _ in range(D + 2)]
    for s in range(S + 1):
        main_dp[D+1][s] = 0

    for day in range(D, 0, -1):
        for s in range(S + 1):
            if s < U:
                main_dp[day][s] = -float('inf')
                continue

            max_happiness = -float('inf')
            for sum_e in range(U, s + 1):
                if training_dp[U][sum_e] == -float('inf'):
                    continue
                sum_c = training_dp[U][sum_e]
                if sum_c > max_c:
                    sum_c = max_c

                current_h = donut_dp[sum_c]
                new_strength = min(s - sum_e + O, S)
                next_day = day + 1
                if next_day > D:
                    next_h = 0
                else:
                    next_h = main_dp[next_day][new_strength]
                    if next_h == -float('inf'):
                        continue

                total = current_h + next_h
                if total > max_happiness:
                    max_happiness = total

            main_dp[day][s] = max_happiness if max_happiness != -float('inf') else -float('inf')

