    # Check rows
    for row in board:
        if all(c in (player, 'T') for c in row) and row.count(player) >= 3:
            return True
    # Check columns
    for col in range(4):
        column = [board[row][col] for row in range(4)]
        if all(c in (player, 'T') for c in column) and column.count(player) >= 3:
            return True
    # Check diagonals
    diag1 = [board[i][i] for i in range(4)]
    if all(c in (player, 'T') for c in diag1) and diag1.count(player) >= 3:
        return True
    diag2 = [board[i][3-i] for i in range(4)]
    if all(c in (player, 'T') for c in diag2) and diag2.count(player) >= 3:
        return True
    return False

