def count_divisors(x):
    if x == 0:
        return 0
    count = 1
    i = 2
    while i * i <= x:
        exponent = 0
        while x % i == 0:
            exponent += 1
            x = x // i
        if exponent > 0:
            count *= (exponent + 1)
        i += 1
    if x > 1:
        count *= 2
    return count

def find_triangular(n):
    k = 1
    while True:
        if k % 2 == 0:
            a = k // 2
            b = k + 1
        else:
            a = k
            b = (k + 1) // 2
        div_a = count_divisors(a)
        div_b = count_divisors(b)
        total = div_a * div_b
        if total > n:
            return (k * (k + 1)) // 2
        k += 1

