import math
from functools import reduce

def lcm(a, b):
    return a * b // math.gcd(a, b)

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n, m = map(int, line.split())
        if n == 0 and m == 0:
            break
        p_list = list(map(int, sys.stdin.readline().split()))
        unique_p = []
        seen = set()
        for p in p_list:
            if p in seen:
                continue
            seen.add(p)
            if p <= n and n % p == 0:
                unique_p.append(p)
        m = len(unique_p)
        if m == 0:
            expected = (n * (n + 1) // 2) / n if n != 0 else 0.0
            print("{0:.10f}".format(expected))
            continue
        count_div = 0
        sum_div = 0
        for mask in range(1, 1 << m):
            subset = []
            for i in range(m):
                if mask & (1 << i):
                    subset.append(unique_p[i])
            current_lcm = reduce(lcm, subset, 1)
            if current_lcm > n:
                continue
            k = n // current_lcm
            sum_multiples = current_lcm * k * (k + 1) // 2
            count_multiples = k
            s = len(subset)
            sign = (-1) ** (s + 1)
            count_div += sign * count_multiples
            sum_div += sign * sum_multiples
        allowed_count = n - count_div
        if allowed_count == 0:
            print("0.0000000000")
        else:
            allowed_sum = (n * (n + 1) // 2) - sum_div
            expected = allowed_sum / allowed_count
            print("{0:.10f}".format(expected))

