panels = {'L': 0, 'R': 2, 'U': 1, 'D': 1}

def is_natural(s):
    n = len(s)
    if n == 0:
        return False
    # Check for consecutive duplicates
    for i in range(1, n):
        if s[i] == s[i-1]:
            return False
    # Initialize possible states for the first step
    possible_states = set()
    first_char = s[0]
    possible_states.add((first_char, None, 'right'))
    possible_states.add((None, first_char, 'left'))

    for i in range(1, n):
        current_char = s[i]
        new_possible_states = set()
        for state in possible_states:
            left, right, next_foot = state
            if next_foot == 'left':
                new_left = current_char
                new_right = right
                new_next_foot = 'right'
            else:  # next_foot is 'right'
                new_right = current_char
                new_left = left
                new_next_foot = 'left'
            # Check if positions are valid (non-crossing)
            valid = True
            if new_left is not None and new_right is not None:
                if panels[new_left] > panels[new_right]:
                    valid = False
            if valid:
                new_state = (new_left, new_right, new_next_foot)
                new_possible_states.add(new_state)
        possible_states = new_possible_states
        if not possible_states:
            break
    return len(possible_states) > 0

