from collections import deque

def minimal_swaps(N, start_r, start_c):
    target = (1, 1)
    visited = set()
    queue = deque([(start_r, start_c, 0)])
    visited.add((start_r, start_c))

    while queue:
        r, c, steps = queue.popleft()
        if (r, c) == target:
            return steps
        # Generate neighboring positions
        neighbors = []
        # Upwards
        if r > 1:
            if c > 1:
                neighbors.append((r-1, c-1))  # Up-left
            if c <= r-1:
                neighbors.append((r-1, c))    # Up
        # Downwards
        if r < N:
            neighbors.append((r+1, c))        # Down-left
            neighbors.append((r+1, c+1))      # Down-right
        # Check each neighbor
        for nr, nc in neighbors:
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, steps + 1))
    return -1  # According to problem statement, not reachable

