import sys

def main():
    sys.setrecursionlimit(1 << 25)
    input = sys.stdin.read().split()
    ptr = 0
    while ptr < len(input):
        n = int(input[ptr])
        m = int(input[ptr+1])
        ptr += 2
        adj = [[] for _ in range(n+1)]
        for _ in range(m):
            s = int(input[ptr])
            t = int(input[ptr+1])
            adj[s].append(t)
            ptr += 2

        # Kosaraju's algorithm to find SCCs
        visited = [False] * (n + 1)
        order = []
        for u in range(1, n + 1):
            if not visited[u]:
                stack = [(u, False)]
                while stack:
                    node, processed = stack.pop()
                    if processed:
                        order.append(node)
                        continue
                    if visited[node]:
                        continue
                    visited[node] = True
                    stack.append((node, True))
                    for v in adj[node]:
                        if not visited[v]:
                            stack.append((v, False))

        # Build reversed graph
        reversed_adj = [[] for _ in range(n + 1)]
        for u in range(1, n + 1):
            for v in adj[u]:
                reversed_adj[v].append(u)

        # Process reversed graph to find SCCs
        visited = [False] * (n + 1)
        sccs = []
        for u in reversed(order):
            if not visited[u]:
                stack = [u]
                visited[u] = True
                scc = [u]
                while stack:
                    node = stack.pop()
                    for v in reversed_adj[node]:
                        if not visited[v]:
                            visited[v] = True
                            stack.append(v)
                            scc.append(v)
                sccs.append(scc)

        # Calculate the answer
        R = sum(len(scc) - 1 for scc in sccs)
        print(m - R)

