import sys

def main():
    n, m = map(int, sys.stdin.readline().split())
    parent = list(range(n))
    rank = [1] * n

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        # Union by rank
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1

    for _ in range(m):
        s, t = map(int, sys.stdin.readline().split())
        union(s, t)

    q = int(sys.stdin.readline())
    for _ in range(q):
        s, t = map(int, sys.stdin.readline().split())
        if find(s) == find(t):
            print("yes")
        else:
            print("no")

