import sys

def is_matching(open_char, close_char):
    return (open_char == '(' and close_char == ')') or \
           (open_char == '[' and close_char == ']') or \
           (open_char == '{' and close_char == '}') or \
           (open_char == '<' and close_char == '>')

def main():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr +=1
    for _ in range(T):
        N = int(input[ptr])
        ptr +=1
        chars = list(input[ptr])
        ptr +=1
        nums = list(map(int, input[ptr:ptr+N]))
        ptr += N
        prefix = [0]*(N+1)
        for i in range(N):
            prefix[i+1] = prefix[i] + nums[i]
        stack = [ (-1, 0) ]
        max_sum = 0
        for i in range(N):
            if chars[i] in {'(', '[', '{', '<'}:
                current_max = stack[-1][1]
                stack.append( (i, current_max) )
            else:
                if len(stack) > 1:
                    open_idx, prev_max = stack[-1]
                    if open_idx == -1:
                        stack = [ (i, 0) ]
                        continue
                    open_char = chars[open_idx]
                    close_char = chars[i]
                    if is_matching(open_char, close_char):
                        stack.pop()
                        current_sum = prefix[i+1] - prefix[open_idx]
                        new_max = max(current_sum, current_sum + prev_max)
                        if new_max > max_sum:
                            max_sum = new_max
                        if stack:
                            stack[-1] = (stack[-1][0], max(stack[-1][1], new_max))
                    else:
                        stack = [ (i, 0) ]
                else:
                    stack = [ (i, 0) ]
        print(max(max_sum, 0))

