import sys
from collections import deque

def main():
    r, c = map(int, sys.stdin.readline().split())
    grid = []
    start = None
    exit_pos = None

    for i in range(r):
        row = sys.stdin.readline().strip()
        grid.append(row)
        if 'S' in row:
            j = row.index('S')
            start = (i, j)
        if 'E' in row:
            j = row.index('E')
            exit_pos = (i, j)

    # BFS from exit to compute distances
    distance_exit = [[-1] * c for _ in range(r)]
    q = deque([exit_pos])
    distance_exit[exit_pos[0]][exit_pos[1]] = 0
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c:
                if grid[ni][nj] != 'T' and distance_exit[ni][nj] == -1:
                    distance_exit[ni][nj] = distance_exit[i][j] + 1
                    q.append((ni, nj))

    # BFS from start to exit to find minimal steps T
    T = -1
    visited = [[False] * c for _ in range(r)]
    q = deque([(start[0], start[1], 0)])
    visited[start[0]][start[1]] = True

    while q:
        i, j, d = q.popleft()
        if (i, j) == exit_pos:
            T = d
            break
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < r and 0 <= nj < c and not visited[ni][nj] and grid[ni][nj] != 'T':
                visited[ni][nj] = True
                q.append((ni, nj, d + 1))

    total = 0
    for i in range(r):
        for j in range(c):
            cell = grid[i][j]
            if cell in {'S', 'E', 'T'}:
                continue
            if cell.isdigit():
                cnt = int(cell)
                if cnt > 0 and distance_exit[i][j] != -1 and distance_exit[i][j] <= T:
                    total += cnt

    print(total)

