import heapq

def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        R = int(input[ptr+1])
        ptr +=2
        graph = [dict() for _ in range(N+1)]
        for __ in range(R):
            x = int(input[ptr])
            y = int(input[ptr+1])
            d = int(input[ptr+2])
            ptr +=3
            if x != y:
                if y in graph[x]:
                    if d < graph[x][y]:
                        graph[x][y] = d
                else:
                    graph[x][y] = d
                if x in graph[y]:
                    if d < graph[y][x]:
                        graph[y][x] = d
                else:
                    graph[y][x] = d
        S = int(input[ptr])
        ptr +=1

        INF = float('inf')
        distances = [INF]*(N+1)
        distances[S] = 0
        heap = []
        heapq.heappush(heap, (0, S))

        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > distances[u]:
                continue
            for v in graph[u]:
                new_dist = current_dist + graph[u][v]
                if new_dist < distances[v]:
                    distances[v] = new_dist
                    heapq.heappush(heap, (new_dist, v))

        output = []
        for i in range(1, N+1):
            if i == S:
                continue
            if distances[i] == INF:
                output.append(-1)
            else:
                output.append(distances[i])
        print(' '.join(map(str, output)))

