MOD = 998244353

def main():
    import sys
    K, N = map(int, sys.stdin.readline().split())
    max_n = 4000  # Since B + rem - 1 can be up to 2000 + 2000 -1 = 3999
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(n, k):
        if n < 0 or k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    results = []
    for i in range(2, 2*K + 1):
        # Compute T
        if i % 2 == 0:
            half = i // 2
            T = 1 if half <= K else 0
        else:
            T = 0

        # Compute S
        low = max(1, i - K)
        high = (i - 1) // 2
        if low > high:
            S = 0
        else:
            S = high - low + 1

        A = S + T
        B = K - S - T

        if B == 0:
            if N > A:
                ans = 0
            else:
                ans = comb(A, N)
        else:
            ans = 0
            max_k = min(A, N)
            for k in range(0, max_k + 1):
                rem = N - k
                c1 = comb(A, k)
                c2 = comb(B + rem - 1, rem)
                ans = (ans + c1 * c2) % MOD

        results.append(ans)

    print(' '.join(map(str, results)))

