import math

def count_primes(n_values):
    if not n_values:
        return []
    max_n = max(n_values)
    sieve = [True] * (max_n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.sqrt(max_n)) + 1):
        if sieve[i]:
            sieve[i*i : max_n+1 : i] = [False] * len(sieve[i*i : max_n+1 : i])
    # Compute prefix sums
    prefix = [0] * (max_n + 1)
    count = 0
    for i in range(max_n + 1):
        if sieve[i]:
            count += 1
        prefix[i] = count
    return [prefix[n] for n in n_values]

