from collections import deque

def get_previous(s, x):
    prev = []
    i = 0
    n = len(s)
    while i < n:
        if i + 2 < n and s[i] == 'A' and s[i+1] == 'B' and s[i+2] == 'C':
            prev.append(x)
            i += 3
        else:
            if s[i] == x:
                return None
            prev.append(s[i])
            i += 1
    return ''.join(prev)

