        for x in ['A', 'B', 'C']:
            prev = get_previous(current, x)
            if prev is not None:
                if prev == "ABC":
                    print("Yes")
                    return
                if len(prev) >= 3 and prev not in visited:
                    visited.add(prev)
                    queue.append(prev)
    print("No")

