import sys
import math
from math import gcd
from functools import reduce

def compute_gcd(list_numbers):
    return reduce(lambda a, b: math.gcd(a, b), list_numbers)

def get_prime_factors(n):
    factors = set()
    if n <= 1:
        return factors
    while n % 2 == 0:
        factors.add(2)
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.add(i)
            n = n // i
        i += 2
    if n > 2:
        factors.add(n)
    return factors

def main():
    n, x, y = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    initial_gcd = compute_gcd(a)
    if initial_gcd != 1:
        print(0)
        return

    total_delete = n * x
    primes = set()

    for num in a:
        for t in [num, num + 1]:
            factors = get_prime_factors(t)
            primes.update(factors)

    minimal_cost = total_delete

    for p in primes:
        if p == 1:
            continue
        sum_cost = 0
        count_modify = 0
        for ai in a:
            rem = ai % p
            steps = (p - rem) % p
            cost_modify = steps * y
            if cost_modify < x:
                count_modify += 1
            sum_cost += min(cost_modify, x)
        if count_modify == 0:
            continue
        if sum_cost < minimal_cost:
            minimal_cost = sum_cost

    print(min(minimal_cost, total_delete))

