def main():
    import sys
    n, k = map(int, sys.stdin.readline().split())

    if k % 2 == 0 or k < 1 or k > 2 * n - 1:
        print(-1)
        return

    a = [0] * n

    def build(start, end, count, current_val):
        if count == 1:
            for i in range(start, end):
                a[i] = current_val
                current_val += 1
            return current_val
        else:
            m = end - start
            l = m // 2
            r = m - l

            left_count = min(2 * l - 1, count - 1 - 1)
            while left_count >= 1:
                rc = count - 1 - left_count
                if rc >= 1 and rc <= 2 * r - 1 and rc % 2 == 1:
                    break
                left_count -= 2
            if left_count < 1:
                return -1  # This should not happen due to earlier checks

            right_count = count - 1 - left_count

            current_val = build(start + l, end, right_count, current_val)
            current_val = build(start, start + l, left_count, current_val)
            return current_val

    result = build(0, n, k, 1)
    if result != n + 1:
        print(-1)
    else:
        print(' '.join(map(str, a)))

