import sys

def sieve(n):
    spf = list(range(n+1))
    for i in range(2, int(n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def get_factors(x, spf):
    factors = set()
    if x == 1:
        return factors
    while x != 1:
        p = spf[x]
        factors.add(p)
        while x % p == 0:
            x = x // p
    return factors

def main():
    X2 = int(sys.stdin.readline())
    spf = sieve(10**6)
    p2_list = get_factors(X2, spf)
    min_x0 = float('inf')

    for p2 in p2_list:
        m = X2 // p2
        lower_X1 = (m - 1) * p2 + 1
        upper_X1 = X2

        for X1 in range(lower_X1, upper_X1 + 1):
            if X1 == 1:
                continue
            if spf[X1] == X1:  # X1 is prime
                continue
            factors = get_factors(X1, spf)
            current_min = float('inf')

            for p1 in factors:
                k = X1 // p1
                candidate = max(p1 + 1, (k - 1) * p1 + 1)
                if candidate < current_min:
                    current_min = candidate

            if current_min < min_x0:
                min_x0 = current_min

    print(min_x0)

