        min_time = [[float('inf')] * (m + 1) for _ in range(m + 1)]

        for start in range(1, m + 1):
            # Dijkstra for cost
            dist = [float('inf')] * (m + 1)
            dist[start] = 0
            heap = [(0, start)]
