                if visited[u]:
                    continue
                visited[u] = True
                for v, c, t in adj[u]:
                    if dist[v] > current_dist + c:
                        dist[v] = current_dist + c
                        heapq.heappush(heap, (dist[v], v))

            for v in range(1, m + 1):
                min_cost[start][v] = dist[v]

            # Dijkstra for time
            dist = [float('inf')] * (m + 1)
            dist[start] = 0
            heap = [(0, start)]
            visited = [False] * (m + 1)

            while heap:
