MOD = 10**9 + 7

def main():
    N, M = map(int, input().split())
    if N == 0:
        print(1)
        return
    if N < M - 1:
        print(1)
        return

    e = N - (M - 1)

    # Initialize transformation matrix
    T = [[0] * M for _ in range(M)]
    T[0][0] = 1
    T[0][M-1] = 1
    for i in range(1, M):
        T[i][i-1] = 1

    # Matrix multiplication
    def multiply(a, b):
        res = [[0]*M for _ in range(M)]
        for i in range(M):
            for k in range(M):
                if a[i][k]:
                    for j in range(M):
                        res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
        return res

    # Matrix exponentiation
    def matrix_pow(mat, power):
        result = [[0]*M for _ in range(M)]
        for i in range(M):
            result[i][i] = 1
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    T_e = matrix_pow(T, e)

    # Initial vector [f(M-1), f(M-2), ..., f(0)] = [1, 1, ..., 1]
    res = 0
    for j in range(M):
        res = (res + T_e[0][j] * 1) % MOD

    print(res)

