import bisect

class SegmentTreeNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.max_s = 0
        self.min_f = float('inf')

def build(l, r, buses):
    node = SegmentTreeNode(l, r)
    if l == r:
        node.max_s = buses[l][1]
        node.min_f = buses[l][2]
    else:
        mid = (l + r) // 2
        node.left = build(l, mid, buses)
        node.right = build(mid + 1, r, buses)
        node.max_s = max(node.left.max_s, node.right.max_s)
        node.min_f = min(node.left.min_f, node.right.min_f)
    return node

def query_segment_tree(node, query_l, query_r, li, ri):
    if node.r < query_l or node.l > query_r:
        return None
    if query_l <= node.l and node.r <= query_r:
        if node.max_s <= li and node.min_f >= ri:
            return node.l
        else:
            if node.left is None and node.right is None:
                return None
            res_left = query_segment_tree(node.left, query_l, query_r, li, ri)
            if res_left is not None:
                return res_left
            res_right = query_segment_tree(node.right, query_l, query_r, li, ri)
            return res_right
    else:
        res_left = query_segment_tree(node.left, query_l, query_r, li, ri)
        if res_left is not None:
            return res_left
        res_right = query_segment_tree(node.right, query_l, query_r, li, ri)
        return res_right

