import math

def get_divisors(n):
    divisors = set()
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            if i != n // i:
                divisors.add(n // i)
    divisors.add(n)
    return sorted(divisors)

def is_2_type(b, d):
    current_d = d
    k = 0
    while True:
        g = math.gcd(current_d, b)
        if g == 1:
            break
        current_d = current_d // g
        k += 1
    return (current_d == 1, k)

def is_3_type(b, d):
    return (b - 1) % d == 0

def is_11_type(b, d):
    return (b + 1) % d == 0

def can_decompose(b, d):
    def helper(remaining, factors):
        if remaining == 1:
            return True
        divisors = get_divisors(remaining)
        for m in divisors:
            if any(math.gcd(m, f) != 1 for f in factors):
                continue
            is_2 = is_2_type(b, m)[0]
            is_3 = is_3_type(b, m)
            is_11 = is_11_type(b, m)
            if not (is_2 or is_3 or is_11):
                continue
            if helper(remaining // m, factors + [m]):
                return True
        return False
    return helper(d, [])

