def compute_failure(v):
    m = len(v)
    fail = [0] * m
    for i in range(1, m):
        j = fail[i - 1]
        while j > 0 and v[i] != v[j]:
            j = fail[j - 1]
        if v[i] == v[j]:
            j += 1
        else:
            j = 0
        fail[i] = j
    return fail

def compute_transition(v, fail):
    m = len(v)
    transition = [{} for _ in range(m)]
    for k in range(m):
        for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            current_k = k
            while True:
                if v[current_k] == c:
                    new_k = current_k + 1
                    break
                else:
                    if current_k == 0:
                        new_k = 0
                        break
                    current_k = fail[current_k - 1]
            transition[k][c] = new_k
    return transition

