    for i in range(8):
        for j in range(i + 1, 8):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dz = points[i][2] - points[j][2]
            squared = dx * dx + dy * dy + dz * dz
            if squared == 0:
                return False
            squared_distances.append(squared)

    d_counts = {}
    for d in squared_distances:
        d_counts[d] = d_counts.get(d, 0) + 1

    if len(d_counts) != 3:
        return False
    sorted_d = sorted(d_counts.keys())
    d1, d2, d3 = sorted_d
    if d2 != 2 * d1 or d3 != 3 * d1:
        return False
    if d_counts[d1] != 12 or d_counts[d2] != 12 or d_counts[d3] != 4:
        return False
    return True

