from collections import deque

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())
        grid = [sys.stdin.readline().strip() for _ in range(3)]
        initial_row = -1
        train_segments = []
        for r in range(3):
            row = grid[r]
            for c in range(n):
                char = row[c]
                if char == 's':
                    initial_row = r
                elif char.isupper():
                    train_segments.append((r, c))
        visited = set()
        queue = deque()
        start = (initial_row, 0)
        queue.append(start)
        visited.add(start)
        found = False
        while queue:
            current_r, current_t = queue.popleft()
            if current_t == n - 2:
                found = True
                break
            for dr in (-1, 0, 1):
                next_r = current_r + dr
                if next_r < 0 or next_r >= 3:
                    continue
                new_t = current_t + 1
                if new_t > n - 2:
                    continue
                collision = False
                for (seg_r, seg_c) in train_segments:
                    if seg_r == next_r and (seg_c == 3 * current_t + 2 or seg_c == 3 * current_t + 3):
                        collision = True
                        break
                if not collision:
                    state = (next_r, new_t)
                    if state not in visited:
                        visited.add(state)
                        queue.append(state)
        print("YES" if found else "NO")

