import sys
from fractions import Fraction

def compute_rref(matrix):
    rows = len(matrix)
    if rows == 0:
        return ()
    cols = len(matrix[0])
    lead = 0
    for r in range(rows):
        if lead >= cols:
            break
        i = r
        while i < rows and matrix[i][lead].numerator == 0:
            i += 1
        if i == rows:
            lead += 1
            r -= 1
            continue
        matrix[i], matrix[r] = matrix[r], matrix[i]
        pivot = matrix[r][lead]
        divisor = pivot
        matrix[r] = [x / divisor for x in matrix[r]]
        for i in range(rows):
            if i != r:
                factor = matrix[i][lead]
                matrix[i] = [matrix[i][j] - factor * matrix[r][j] for j in range(cols)]
        lead += 1
    rref_rows = []
    for row in matrix:
        if any(x.numerator != 0 for x in row):
            rref_rows.append(tuple(row))
    return tuple(rref_rows)

