import sys

def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

non_leap_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
leap_months = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

def compute_days(y, m, d):
    days = 0
    for year in range(1, y):
        days += 366 if is_leap(year) else 365
    months = leap_months if is_leap(y) else non_leap_months
    for month in range(m - 1):
        days += months[month]
    days += d - 1
    return days

