import sys

def main():
    var_map = {}
    blocks = {}
    block_counter = 1
    # Read all lines from stdin
    lines = [line.strip() for line in sys.stdin if line.strip()]
    # The first line is the number of commands, but we'll process all lines except the first if needed
    # However, looking at the example input, the first line might not be part of the command count.
    # So we'll process all lines as commands, assuming that the first line is part of the input.
    for line in lines:
        if not line:
            continue
        if line.startswith('free('):
            # Handle free command
            var = line[5:-1]
            if var in var_map:
                block_id = var_map[var]
                # Mark the block as freed
                if block_id in blocks:
                    blocks[block_id]['freed'] = True
                del var_map[var]
        else:
            # Split into variable and operation
            var_part, op_part = line.split('=')
            var = var_part.strip()
            op_part = op_part.strip()
            if op_part.startswith('malloc('):
                # Handle malloc
                size = int(op_part[7:-1])
                # Remove variable from var_map if it exists
                if var in var_map:
                    del var_map[var]
                # Create new block
                new_id = block_counter
                block_counter += 1
                blocks[new_id] = {'size': size, 'freed': False}
                var_map[var] = new_id
            elif op_part.startswith('clone('):
                # Handle clone
                cloned_var = op_part[6:-1]
                if cloned_var in var_map:
                    cloned_id = var_map[cloned_var]
                    if var in var_map:
                        del var_map[var]
                    var_map[var] = cloned_id
    # Calculate total leak: sum of sizes of blocks not freed
    total_leak = sum(block['size'] for block in blocks.values() if not block['freed'])
    print(total_leak)

