import itertools

def can_form_k(remaining, K):
    sum_remaining = sum(remaining)
    if sum_remaining < K:
        return False
    if K in remaining:
        return True

    mid = len(remaining) // 2
    left = remaining[:mid]
    right = remaining[mid:]

    sum_left = set()
    for mask in itertools.product([0, 1], repeat=len(left)):
        s = sum(num for num, bit in zip(left, mask) if bit)
        sum_left.add(s)

    sum_right = set()
    for mask in itertools.product([0, 1], repeat=len(right)):
        s = sum(num for num, bit in zip(right, mask) if bit)
        sum_right.add(s)

    for s_l in sum_left:
        if (K - s_l) in sum_right:
            return True
    return False

