import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    events = [sys.stdin.readline().split() for _ in range(n)]

    friends = defaultdict(set)
    current_interval = -1

    for event in events:
        if event[0] == '1':
            current_interval += 1
        else:
            s = event[1]
            friends[s].add(current_interval)

    friends_list = list(friends.keys())
    m_real = len(friends_list)

    conflict = [[False] * m_real for _ in range(m_real)]
    for i in range(m_real):
        for j in range(i + 1, m_real):
            if friends[friends_list[i]] & friends[friends_list[j]]:
                conflict[i][j] = True
                conflict[j][i] = True

    conflict_mask = [0] * m_real
    for i in range(m_real):
        for j in range(m_real):
            if conflict[i][j]:
                conflict_mask[i] |= 1 << j

    sorted_order = sorted(range(m_real), key=lambda x: bin(conflict_mask[x]).count('1'), reverse=True)
    new_conflict_mask = [0] * m_real
    for i in range(m_real):
        original_i = sorted_order[i]
        mask = 0
        for j in range(m_real):
            original_j = sorted_order[j]
            if conflict[original_i][original_j]:
                mask |= 1 << j
        new_conflict_mask[i] = mask

    current_max = 0

    def backtrack(index, allowed_mask, count):
        nonlocal current_max
        if index == m_real:
            if count > current_max:
                current_max = count
            return
        if count + (m_real - index) <= current_max:
            return
        backtrack(index + 1, allowed_mask, count)
        if (allowed_mask & (1 << index)) == 0:
            return
        new_allowed = allowed_mask & ~new_conflict_mask[index]
        backtrack(index + 1, new_allowed, count + 1)

    backtrack(0, (1 << m_real) - 1, 0)
    print(current_max)

