def prime_factors(n):
    factors = []
    if n == 1:
        return factors
    count = 0
    while n % 2 == 0:
        count += 1
        n = n // 2
    if count > 0:
        factors.append((2, count))
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n = n // i
        if count > 0:
            factors.append((i, count))
        i += 2
    if n > 1:
        factors.append((n, 1))
    return factors

