import sys
MOD = 10**18 + 3
BASE = 911382629

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    U = sys.stdin.readline().strip()
    Q = int(sys.stdin.readline())
    queries = [sys.stdin.readline().strip() for _ in range(Q)]

    pow_base = [1] * (N + 2)
    for i in range(1, N + 2):
        pow_base[i] = (pow_base[i-1] * BASE) % MOD
    inv_base_1 = pow(BASE - 1, MOD - 2, MOD)
    pre_sum = [0] * (N + 2)
    for i in range(1, N + 2):
        pre_sum[i] = (pow_base[i] - 1) * inv_base_1 % MOD

    class SegmentTreeNode:
        __slots__ = ['l', 'r', 'left', 'right', 'char', 'hash', 'lazy']
        def __init__(self, l, r):
            self.l = l
            self.r = r
            self.left = None
            self.right = None
            self.char = None
            self.hash = 0
            self.lazy = None

    def build(l, r):
        node = SegmentTreeNode(l, r)
        if l == r:
            c = U[l]
            node.char = c
            c_val = ord(c) - ord('a') + 1
            node.hash = c_val * pre_sum[1] % MOD
            return node
        mid = (l + r) // 2
        node.left = build(l, mid)
        node.right = build(mid+1, r)
        node.hash = (node.left.hash * pow_base[r - mid] + node.right.hash) % MOD
        if node.left.char == node.right.char and node.left.char is not None:
            node.char = node.left.char
        else:
            node.char = None
        return node

    def apply(node, c):
        if node is None:
            return
        node.char = c
        length = node.r - node.l + 1
        c_val = ord(c) - ord('a') + 1
        node.hash = c_val * pre_sum[length] % MOD
        node.lazy = c

    def push(node):
        if node.lazy is not None and node.left is not None:
            c = node.lazy
            apply(node.left, c)
            apply(node.right, c)
            node.lazy = None

    def range_set(node, l, r, c):
        if node.r < l or node.l > r:
            return
        if l <= node.l and node.r <= r:
            apply(node, c)
            return
        push(node)
        range_set(node.left, l, r, c)
        range_set(node.right, l, r, c)
        node.hash = (node.left.hash * pow_base[node.right.r - node.right.l + 1] + node.right.hash) % MOD
        if node.left.char == node.right.char and node.left.char is not None:
            node.char = node.left.char
        else:
            node.char = None

    def get_hash(node, l, r):
        if node.r < l or node.l > r:
            return (0, 0)
        if l <= node.l and node.r <= r:
            return (node.hash, node.r - node.l + 1)
        push(node)
        left_hash, left_len = get_hash(node.left, l, r)
        right_hash, right_len = get_hash(node.right, l, r)
        combined_hash = (left_hash * pow_base[right_len] + right_hash) % MOD
        combined_len = left_len + right_len
        return (combined_hash, combined_len)

    def get_char(node, idx):
        while True:
            if node.l == node.r:
                return node.char
            push(node)
            mid = (node.l + node.r) // 2
            if idx <= mid:
                node = node.left
            else:
                node = node.right

    root = build(0, N-1)

    for query in queries:
        parts = query.split()
        if parts[0] == 'set':
            x = int(parts[1]) - 1
            y = int(parts[2]) - 1
            z = parts[3]
            range_set(root, x, y, z)
        else:
            a = int(parts[1]) - 1
            b = int(parts[2]) - 1
            c_start = int(parts[3]) - 1
            d = int(parts[4]) - 1
            len_s = b - a + 1
            len_t = d - c_start + 1
            min_len = min(len_s, len_t)
            low = 0
            high = min_len
            lcp = 0
            while low <= high:
                mid = (low + high) // 2
                if mid == 0:
                    lcp = 0
                    low = mid + 1
                    continue
                s_end = a + mid - 1
                t_end = c_start + mid - 1
                s_hash, s_len = get_hash(root, a, s_end)
                t_hash, t_len = get_hash(root, c_start, t_end)
                if s_hash == t_hash and s_len == mid and t_len == mid:
                    lcp = mid
                    low = mid + 1
                else:
                    high = mid - 1
            if lcp == min_len:
                if len_s < len_t:
                    print('s')
                elif len_s > len_t:
                    print('t')
                else:
                    print('e')
            else:
                s_char = get_char(root, a + lcp)
                t_char = get_char(root, c_start + lcp)
                if s_char < t_char:
                    print('s')
                else:
                    print('t')

