import sys
from collections import deque

def get_positions(grid, value):
    positions = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == value:
                positions.append((i, j))
    return positions

def bfs(start, end, grid, blocked_cells):
    n = len(grid)
    m = len(grid[0]) if n else 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([(start[0], start[1], 0)])
    visited[start[0]][start[1]] = True

    if grid[start[0]][start[1]] == 1 or grid[end[0]][end[1]] == 1:
        return -1
    if start in blocked_cells or end in blocked_cells:
        return -1

    while queue:
        x, y, dist = queue.popleft()
        if (x, y) == end:
            return dist
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if not visited[nx][ny] and grid[nx][ny] != 1 and (nx, ny) not in blocked_cells:
                    visited[nx][ny] = True
                    queue.append((nx, ny, dist + 1))
    return -1

def get_all_paths(start, end, grid):
    n = len(grid)
    m = len(grid[0]) if n else 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    s_x, s_y = start
    e_x, e_y = end

    if grid[s_x][s_y] == 1 or grid[e_x][e_y] == 1:
        return []

    initial_mask = 1 << (s_x * m + s_y)
    queue = deque([(s_x, s_y, initial_mask, 0)])
    visited = {}
    paths = []

    while queue:
        x, y, mask, length = queue.popleft()
        if (x, y) == (e_x, e_y):
            paths.append((mask, length))
            continue
        key = (x, y, mask)
        if key in visited and visited[key] <= length:
            continue
        visited[key] = length
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if grid[nx][ny] == 1:
                    continue
                bit = nx * m + ny
                if mask & (1 << bit):
                    continue
                new_mask = mask | (1 << bit)
                new_length = length + 1
                queue.append((nx, ny, new_mask, new_length))
    paths.sort(key=lambda x: x[1])
    return paths

def solve():
    while True:
        line = sys.stdin.readline()
        if not line.strip():
            line = sys.stdin.readline()
        if not line:
            break
        n, m = map(int, line.strip().split())
        if n == 0 and m == 0:
            break
        grid = []
        for _ in range(n):
            row = list(map(int, sys.stdin.readline().strip().split()))
            grid.append(row)
        twos = get_positions(grid, 2)
        threes = get_positions(grid, 3)
        if len(twos) != 2 or len(threes) != 2:
            print(0)
            continue
        s2, e2 = twos
        s3, e3 = threes

        paths_2_alone = get_all_paths(s2, e2, grid)
        paths_3_alone = get_all_paths(s3, e3, grid)
        if not paths_2_alone or not paths_3_alone:
            print(0)
            continue

        min_sum = float('inf')

        paths_2 = get_all_paths(s2, e2, grid)
        for mask_2, len_2 in paths_2:
            blocked = set()
            for i in range(n):
                for j in range(m):
                    if mask_2 & (1 << (i * m + j)):
                        blocked.add((i, j))
            if s3 in blocked or e3 in blocked:
                continue
            len_3 = bfs(s3, e3, grid, blocked)
