import math

def readints():
    return list(map(int, input().split()))

def cross(o, a, b):
    return (a[0] - o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def segments_intersect(a1, a2, b1, b2):
    def ccw(A, B, C):
        return (B[0]-A[0])*(C[1]-A[1]) - (B[1]-A[1])*(C[0]-A[0])
    A, B, C, D = a1, a2, b1, b2
    return ccw(A,C,D)*ccw(B,C,D) < 0 and ccw(C,A,B)*ccw(D,A,B) < 0

def line_segment_distance(a1, a2, b1, b2):
    def dot(a, b):
        return a[0]*b[0] + a[1]*b[1]
    def length(v):
        return math.hypot(v[0], v[1])
    def vector_sub(a, b):
        return (a[0]-b[0], a[1]-b[1])
    v = vector_sub(a2, a1)
    w = vector_sub(b2, b1)
    vlen = length(v)
    if vlen == 0:
        return min( (math.hypot(p[0]-b1[0], p[1]-b1[1]) for p in [a1, a2]) )
    t = max(0, min(1, dot(vector_sub(b1, a1), v) / (vlen**2) ))
    p = (a1[0] + t*v[0], a1[1] + t*v[1])
    d = math.hypot(p[0]-b1[0], p[1]-b1[1])
    for seg in [(a1, a2), (b1, b2)]:
        for p in [seg[0], seg[1]]:
            d = min(d, math.hypot(p[0]-b1[0], p[1]-b1[1]))
    if segments_intersect(a1, a2, b1, b2):
        return 0.0
    return d

