import math

def compute_sum_phi(n):
    if n < 1:
        return 0
    phi = list(range(n + 1))
    for i in range(2, n + 1):
        if phi[i] == i:  # i is prime
            for j in range(i, n + 1, i):
                phi[j] -= phi[j] // i
    return sum(phi[2: n+1])

def main():
    n, m = map(int, sys.stdin.readline().split())
    if n == 1:
        if m == 0:
            print("Possible")
        else:
            print("Impossible")
        return

    max_edges = compute_sum_phi(n)
    min_edges = n - 1
    if m < min_edges or m > max_edges:
        print("Impossible")
        return

    print("Possible")
    edges = []
    # Step 1: Connect 1 to all others
    for i in range(2, n+1):
        edges.append((1, i))
    rem = m - (n - 1)

    # Step 2: Connect 2 to all odds >=3
    if rem > 0:
        j = 3
        while j <= n and rem > 0:
            edges.append((2, j))
            rem -=1
            j +=2

    # Step 3: Connect even i to i+1
    if rem > 0:
        i = 2
        while i <= n-1 and rem > 0:
            if i % 2 == 0:  # even i
                edges.append((i, i+1))
                rem -=1
            i += 2  # next even

    # Step 4: Connect 3 to even j not divisible by 3
    if rem > 0:
        j =4
        while j <=n and rem >0:
            if j %3 !=0 and j %2 ==0:
                edges.append((3, j))
                rem -=1
            j +=2

    # Step 5: Connect 4 to odds >=5
    if rem >0:
        j =5
        while j <=n and rem >0:
