from collections import defaultdict

class DSU:
    def __init__(self, size):
        self.parent = list(range(size + 1))  # 1-based indexing
        self.size = [1] * (size + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.size[x_root] < self.size[y_root]:
            x_root, y_root = y_root, x_root
        self.parent[y_root] = x_root
        self.size[x_root] += self.size[y_root]

def main():
    n, m = map(int, stdin.readline().split())
    dsu = DSU(n)
    degree = [0] * (n + 1)

    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        dsu.union(a, b)
        degree[a] += 1
        degree[b] += 1

    sum_degree = defaultdict(int)
    for u in range(1, n + 1):
        root = dsu.find(u)
        sum_degree[root] += degree[u]

    for root in sum_degree:
        s = dsu.size[root]
        e = sum_degree[root] // 2
        if e != s * (s - 1) // 2:
            print("NO")
            return

    print("YES")

