def build_trie(elements, n):
    trie = {}
    for x in elements:
        current = trie
        for bit in reversed(range(n)):  # Process from MSB to LSB
            bit_val = (x >> bit) & 1
            if bit_val not in current:
                current[bit_val] = {}
            current = current[bit_val]
        current['is_end'] = True
    return trie

def query_subsets(trie, mask, n):
    results = []
    stack = [(trie, 0, 0)]  # (current node, bit position, current_value)
    max_bit = n - 1
    while stack:
        node, bit_pos, current_value = stack.pop()
        if bit_pos == n:
            if 'is_end' in node:
                results.append(current_value)
            continue
        current_bit = max_bit - bit_pos
        bit_mask = 1 << current_bit
        mask_bit = (mask & bit_mask) != 0
        if mask_bit:
            if 0 in node:
                stack.append((node[0], bit_pos + 1, current_value))
        else:
            for b in [0, 1]:
                if b in node:
                    new_value = current_value | (b << current_bit)
                    stack.append((node[b], bit_pos + 1, new_value))
    return results

