import sys
from collections import deque

def process_picture(lines, h):
    components = []
    visited = set()
    for y in range(h):
        line = lines[y].rstrip()
        for x in range(len(line)):
            if line[x] == '*' and (y, x) not in visited:
                # BFS to find connected component (8-direction)
                q = deque()
                q.append((y, x))
                visited.add((y, x))
                component = set()
                component.add((y, x))
                while q:
                    cy, cx = q.popleft()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny = cy + dy
                            nx = cx + dx
                            if 0 <= ny < h:
                                line_ny = lines[ny].rstrip()
                                if nx < len(line_ny) and line_ny[nx] == '*' and (ny, nx) not in visited:
                                    visited.add((ny, nx))
                                    component.add((ny, nx))
                                    q.append((ny, nx))
                components.append(component)

    areas = []
    for component in components:
        ys = [y for (y, x) in component]
        if not ys:
            continue
        min_y = min(ys)
        max_y = max(ys)
        delta_y_total = max_y - min_y
        if delta_y_total < 2:
            continue

        lines_by_y = {}
        for (y, x) in component:
            if y not in lines_by_y:
                lines_by_y[y] = []
            lines_by_y[y].append(x)

        horizontal_lines = []
        for y in lines_by_y:
            xs = sorted(lines_by_y[y])
            runs = []
            if not xs:
                continue
            current_start = xs[0]
            current_end = xs[0]
            for x in xs[1:]:
                if x == current_end + 1:
                    current_end = x
                else:
                    if current_end - current_start + 1 >= 3:
                        runs.append((current_start, current_end))
                    current_start = x
                    current_end = x
            if current_end - current_start + 1 >= 3:
                runs.append((current_start, current_end))
            for (s, e) in runs:
                horizontal_lines.append((y, s, e))

        if len(horizontal_lines) != 2:
            continue

        (y0, s0, e0), (y1, s1, e1) = horizontal_lines
        if not ((y0 == min_y and y1 == max_y) or (y1 == min_y and y0 == max_y)):
            continue

        if y0 == min_y:
            top_line = (y0, s0, e0)
            bottom_line = (y1, s1, e1)
        else:
            top_line = (y1, s1, e1)
            bottom_line = (y0, s0, e0)

        top_len = top_line[2] - top_line[1] + 1
        bottom_len = bottom_line[2] - bottom_line[1] + 1
        if top_len < 3 or bottom_len < 3:
            continue

        delta_y = bottom_line[0] - top_line[0]
        x_start_top = top_line[1]
        x_start_bottom = bottom_line[1]
        x_end_top = top_line[2]
        x_end_bottom = bottom_line[2]
        delta_x_left = x_start_bottom - x_start_top
        delta_x_right = x_end_bottom - x_end_top

        if delta_x_left not in [0, delta_y, -delta_y]:
            continue
        if delta_x_right not in [0, delta_y, -delta_y]:
            continue

        valid = True
        for y in range(top_line[0], bottom_line[0] + 1):
            if delta_x_left == 0:
                x = x_start_top
            elif delta_x_left == delta_y:
                x = x_start_top + (y - top_line[0])
            else:
                x = x_start_top - (y - top_line[0])
            if (y, x) not in component:
                valid = False
                break
        if not valid:
            continue

        for y in range(top_line[0], bottom_line[0] + 1):
            if delta_x_right == 0:
                x = x_end_top
            elif delta_x_right == delta_y:
                x = x_end_top + (y - top_line[0])
            else:
                x = x_end_top - (y - top_line[0])
            if (y, x) not in component:
                valid = False
                break
        if not valid:
            continue

        height = delta_y + 1
        area = (top_len + bottom_len) * height // 2
        areas.append(area)

    return areas

def main():
    first = True
    while True:
        h = int(sys.stdin.readline())
        if h == 0:
            break
        if not first:
            print('-' * 10)
        first = False
        lines = []
        for _ in range(h):
            lines.append(sys.stdin.readline().rstrip())
        areas = process_picture(lines, h)
        from collections import defaultdict
        count = defaultdict(int)
        for area in areas:
            count[area] += 1
        for key in sorted(count.keys()):
            print(f"{key} {count[key]}")

if __name__ == "__main__":
    main()

