def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    C = int(input[idx])
    idx += 1
    events = []
    for _ in range(N):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        events.append((a, b, c))

    sum_total = sum(a + b for a, b, c in events)
    low = 0
    high = sum_total // 2
    answer = 0

    def is_possible(X):
        if X == 0:
            return True
        dp = [[-1] * (X + 1) for _ in range(C + 1)]
        dp[0][0] = 0
        for a_i, b_i, c_i in events:
            new_dp = [row[:] for row in dp]
            for c in range(C + 1):
                for a in range(X + 1):
                    current_b = dp[c][a]
                    if current_b == -1:
                        continue
                    # Assign to A
                    new_c = c + c_i
                    if new_c <= C:
                        new_a = min(a + a_i, X)
                        new_b = min(current_b + b_i, X)
                        if new_b > new_dp[new_c][new_a]:
                            new_dp[new_c][new_a] = new_b
                    # Assign to B
                    new_c = c + c_i
                    if new_c <= C:
                        new_a_b = min(a + b_i, X)
                        new_b_b = min(current_b + a_i, X)
                        if new_b_b > new_dp[new_c][new_a_b]:
                            new_dp[new_c][new_a_b] = new_b_b
            dp = new_dp
        for c in range(C + 1):
            for a in range(X + 1):
                if a >= X and dp[c][a] >= X:
                    return True
        return False

    while low <= high:
        mid = (low + high) // 2
        if is_possible(mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1
    print(answer)

