def bfs(start, graph, n):
    visited = [-1] * (n+1)
    q = deque([start])
    visited[start] = 0
    max_dist = 0
    far_node = start
    while q:
        u = q.popleft()
        for v in graph[u]:
            if visited[v] == -1:
                visited[v] = visited[u] + 1
                if visited[v] > max_dist:
                    max_dist = visited[v]
                    far_node = v
                q.append(v)
    return far_node, max_dist

def compute_diameter(graph, n):
    u, _ = bfs(1, graph, n)
    v, d = bfs(u, graph, n)
    return d

