def max_colors(n):
    if n == 1:
        return 1
    primes = set()
    i = 2
    while i * i <= n:
        if n % i == 0:
            primes.add(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        primes.add(n)
    if len(primes) == 1:
        return primes.pop()
    else:
        return 1

