def generate_variations(pin, k):
    digits = list(pin)
    variations = []
    for positions in itertools.combinations(range(4), k):
        possible_digits = []
        for pos in positions:
            original = digits[pos]
            possible = [d for d in '0123456789' if d != original]
            possible_digits.append(possible)
        for digits_comb in itertools.product(*possible_digits):
            new_digits = list(digits)
            for i in range(len(positions)):
                new_digits[positions[i]] = digits_comb[i]
            new_pin = ''.join(new_digits)
            variations.append(new_pin)
    return variations

