def generate_divisors():
    primes = [2, 3, 5, 7]
    exponents = [
        [0, 1, 2, 3],
        [0, 1, 2],
        [0, 1],
        [0, 1]
    ]
    divisor_exponents = list(itertools.product(*exponents))
    divisors = []
    for exp_tuple in divisor_exponents:
        divisor = 1
        for i in range(len(primes)):
            divisor *= primes[i] ** exp_tuple[i]
        divisors.append(divisor)
    divisors = list(set(divisors))
    divisors.sort()
    return divisors

