        res = 0
        max_d = int(n_str[pos]) if tight else 9
        for d in range(0, max_d + 1):
            new_tight = tight and (d == max_d)
            new_mod = (mod * 10 + d) % 2520
            new_has_non_zero = has_non_zero or (d != 0)
            if d == 0:
                new_lcm_idx = lcm_idx
            else:
                new_lcm_val = lcm(DIVISORS[lcm_idx], d)
                new_lcm_idx = DIVISOR_MAP[new_lcm_val]
            res += dp(pos + 1, new_tight, new_mod, new_lcm_idx, new_has_non_zero)
        return res
    return dp(0, True, 0, 0, False)

