    q = deque([s])
    f_reach[s] = True
    while q:
        u = q.popleft()
        for v, _ in adj[u]:
            if not f_reach[v]:
                f_reach[v] = True
                q.append(v)

    # Compute r_reach: nodes that can reach t (reverse graph)
    reverse_adj = [[] for _ in range(n+1)]
    for u in range(n+1):
        for v, e_idx in adj[u]:
            reverse_adj[v].append((u, e_idx))
    r_reach = [False]*(n+1)
    q = deque([t])
    r_reach[t] = True
    while q:
        u = q.popleft()
        for v, _ in reverse_adj[u]:
            if not r_reach[v]:
                r_reach[v] = True
                q.append(v)

    # Determine edges in E
    E = []
    for idx, (x, y, w, eid) in enumerate(edges):
        if (f_reach[x] and r_reach[y]) or (f_reach[y] and r_reach[x]):
            E.append((x, y, w, eid))

    # Find all bridges using Tarjan's algorithm
    bridges = set()
    disc = [-1]*(n+1)
    low = [-1]*(n+1)
    time = 0
    parent = [-1]*(n+1)

    def tarjan(u):
        nonlocal time
        disc[u] = low[u] = time
        time +=1
        for v, e_idx in adj[u]:
            if disc[v] == -1:
                parent[v] = (u, e_idx)
                tarjan(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.add(e_idx)
            elif parent[u][0] != v if parent[u] != -1 else True:
                low[u] = min(low[u], disc[v])

    for u in range(1, n+1):
        if disc[u] == -1:
            tarjan(u)

    # Collect bridges in E
    bridge_edges = []
    for x, y, w, eid in E:
