    # Build bridge tree and find path between s and t
    # Assign nodes to their 2-edge-connected components
    component = [0]*(n+1)
    comp_id = 0
    visited = [False]*(n+1)

    def dfs(u, comp_id):
        stack = [(u, -1)]
        visited[u] = True
        component[u] = comp_id
        while stack:
            u, p = stack.pop()
            for v, e_idx in adj[u]:
                if not visited[v] and (e_idx not in bridges or (parent[v] == (u, e_idx) and e_idx in bridges)):
                    visited[v] = True
                    component[v] = comp_id
                    stack.append((v, u))
                elif v != p and component[v] == 0 and e_idx not in bridges:
                    visited[v] = True
                    component[v] = comp_id
                    stack.append((v, u))

    comp_id = 0
    for u in range(1, n+1):
