            c1 = component[x]
            c2 = component[y]
            adj_comp.setdefault(c1, []).append((c2, e_idx))
            adj_comp.setdefault(c2, []).append((c1, e_idx))

        # BFS to find path from s_comp to t_comp in bridge tree
        parent_comp = {}
        q = deque([s_comp])
        parent_comp[s_comp] = None
        found = False
        while q and not found:
            u = q.popleft()
