    pow10 = [1] * (max_pow + 1)
    for i in range(1, max_pow + 1):
        pow10[i] = (pow10[i-1] * 10) % MOD

    current = defaultdict(int)
    current[(0, 0)] = 1
    answer = 0

    for i in range(N):
        next_phase = defaultdict(int)
        for (phase, s) in current:
            cnt = current[(phase, s)]
            for a in range(1, 11):
                new_p = phase
                new_sum = s
                if phase == 0:
                    new_sum = s + a
                    if new_sum == X:
                        new_p = 1
                        new_sum = 0
                    elif new_sum < X:
                        new_p = 0
                    else:
                        continue
                elif phase == 1:
                    new_sum = s + a
                    if new_sum == Y:
                        new_p = 2
                        new_sum = 0
                    elif new_sum < Y:
                        new_p = 1
                    else:
                        continue
                elif phase == 2:
                    new_sum = s + a
                    if new_sum == Z:
                        new_p = 3
                    elif new_sum < Z:
                        new_p = 2
                    else:
                        continue
                else:
                    continue

                if new_p == 3:
                    remaining = N - (i + 1)
                    contribution = (cnt * pow10[remaining]) % MOD
                    answer = (answer + contribution) % MOD
                else:
                    next_phase[(new_p, new_sum)] = (next_phase[(new_p, new_sum)] + cnt) % MOD
        current = next_phase

    print(answer % MOD)

