import sys

def encrypt(s):
    s_list = list(s)
    for c in ['b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']:
        try:
            idx = s_list.index(c)
            s_list[idx] = chr(ord(c) - 1)
        except ValueError:
            continue
    return ''.join(s_list)

def reverse_step(c, s):
    predecessors = set()
    target_char = chr(ord(c) - 1)
    if c not in s:
        predecessors.add(s)
    for i in range(len(s)):
        if s[i] == target_char:
            prefix = s[:i]
            if c not in prefix:
                t = s[:i] + c + s[i+1:]
                predecessors.add(t)
    return predecessors

def get_candidates(encrypted):
    candidates = {encrypted}
    for c in reversed('bcdefghijklmnopqrstuvwxyz'):
        new_candidates = set()
        for s in candidates:
            new_candidates.update(reverse_step(c, s))
        candidates = new_candidates
        if not candidates:
            break
    valid = []
    for candidate in candidates:
        if encrypt(candidate) == encrypted:
            valid.append(candidate)
    return valid

