def compute_sum(x, n):
    m = n - 1
    if m <= 0:
        return x
    t = x.bit_length() - 1
    if m <= t:
        total = 0
        for k in range(m + 1):
            total += x >> k
        return total
    else:
        s_bits = bin(x).count('1')
        return 2 * x - s_bits

