import sys
MOD = 10**9 + 7

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, k, q = map(int, input[ptr:ptr+3])
    ptr +=3

    a = []
    for _ in range(n):
        a.append(int(input[ptr]))
        ptr +=1

    queries = []
    for _ in range(q):
        queries.append(int(input[ptr]))
        ptr +=1

    max_d = 10**6
    # Precompute smallest prime factors (SPF)
    spf = list(range(max_d + 1))
    for i in range(2, int(max_d**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_d + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute Euler's totient function (phi)
    phi = list(range(max_d + 1))
    for p in range(2, max_d + 1):
        if spf[p] == p:
            for m in range(p, max_d + 1, p):
                phi[m] -= phi[m] // p

    # Precompute factorials and inverse factorials modulo MOD
    max_fact = 2 * 10**5 + 10
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], MOD-2, MOD)
    for i in range(max_fact -1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i + 1) % MOD

    def comb(n, k):
        if n < k or k < 0:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    # Initialize divisor count array
    c = [0] * (max_d + 1)

    def get_divisors(x):
        divisors = [1]
        tmp = x
        factors = {}
        while tmp > 1:
            p = spf[tmp]
            cnt = 0
            while tmp % p == 0:
                cnt += 1
                tmp //= p
            if cnt > 0:
                factors[p] = cnt
        for p, cnt in factors.items():
            temp = []
            for d in divisors:
                current = d
                for _ in range(cnt):
                    current *= p
                    temp.append(current)
            divisors += temp
        return divisors

    # Process initial flower counts
    for num in a:
        divisors = get_divisors(num)
        for d in divisors:
            c[d] += 1

    # Calculate initial sum_total
    sum_total = 0
    for d in range(1, max_d + 1):
        sum_total = (sum_total + phi[d] * comb(c[d], k)) % MOD

    # Process each query
    for x in queries:
        divisors = get_divisors(x)
        for d in divisors:
            old = c[d]
            delta = (comb(old + 1, k) - comb(old, k)) * phi[d]
            delta %= MOD
            sum_total = (sum_total + delta) % MOD
            c[d] += 1
        print(sum_total % MOD)

