        if T[i][j] < gain:
            T[i][j] = gain

# Matrix exponentiation
def multiply(A, B):
    res = [[INF] * m for _ in range(m)]
    for i in range(m):
        for k in range(m):
            if A[i][k] == INF:
                continue
            for j in range(m):
                if B[k][j] == INF:
                    continue
                res[i][j] = max(res[i][j], A[i][k] + B[k][j])
    return res

def matrix_pow(mat, power):
    res = [[INF] * m for _ in range(m)]
    for i in range(m):
        res[i][i] = 0
    while power > 0:
        if power % 2 == 1:
            res = multiply(res, mat)
        mat = multiply(mat, mat)
        power //= 2
    return res

