import sys
from math import log2, ceil
from collections import deque

sys.setrecursionlimit(1 << 25)

def main():
    input = sys.stdin.read().split()
    idx = 0
    n, q = map(int, input[idx:idx+2])
    idx += 2
    p = list(map(int, input[idx:idx+n-1]))
    idx += n-1

    parent = [0] * (n + 1)
    for i in range(2, n+1):
        parent[i] = p[i-2]

    LOG = ceil(log2(n)) if n > 1 else 1
    up = [[0] * (n + 1) for _ in range(LOG + 1)]
    depth = [0] * (n + 1)

    for i in range(1, n+1):
        up[0][i] = parent[i]

    for k in range(1, LOG + 1):
        for i in range(1, n+1):
            up[k][i] = up[k-1][up[k-1][i]]

    queue = deque([1])
    visited = [False] * (n + 1)
    visited[1] = True
    while queue:
        u = queue.popleft()
        for v in range(2, n+1):
            if not visited[v] and parent[v] == u:
                depth[v] = depth[u] + 1
                visited[v] = True
                queue.append(v)

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    def get_dist(u, v):
        ancestor = lca(u, v)
        return depth[u] + depth[v] - 2 * depth[ancestor]

    for _ in range(q):
        a, b, c = map(int, input[idx:idx+3])
        idx += 3
        max_common = 0

        for f in [a, b, c]:
            if f == a:
                x, y = b, c
            elif f == b:
                x, y = a, c
            else:
                x, y = a, b

            lca_xy = lca(x, y)
            lca_xf = lca(x, f)
            lca_yf = lca(y, f)
            lca_lca_xy_f = lca(lca_xy, f)

            candidates = [lca_xy, lca_xf, lca_yf, lca_lca_xy_f]
            z = max(candidates, key=lambda node: depth[node])
            ancestor_z_f = lca(z, f)
            dist = depth[z] + depth[f] - 2 * depth[ancestor_z_f]
            current_common = dist + 1
            if current_common > max_common:
                max_common = current_common

        print(max_common)

