import sys

def convert_integer(n):
    if n == 0:
        return '0' * 8
    binary = bin(n)[2:]
    if len(binary) > 8:
        return None
    return binary.zfill(8)

def convert_fraction(numerator, denominator):
    if numerator == 0:
        return '0000', True
    bits = []
    remaining = numerator
    for _ in range(4):
        remaining *= 2
        if remaining >= denominator:
            bits.append('1')
            remaining -= denominator
        else:
            bits.append('0')
        if remaining == 0:
            break
    if remaining != 0:
        return None, False
    bits = ''.join(bits).ljust(4, '0')[:4]
    return bits, True

