import sys

def find_min_m(e):
    min_sum = float('inf')
    z = 0
    while True:
        z_cubed = z ** 3
        if z_cubed > e:
            break
        remaining = e - z_cubed
        y_max = int(remaining ** 0.5)
        for y in range(y_max + 1):
            y_sq = y * y
            x = remaining - y_sq
            current_sum = x + y + z
            if current_sum < min_sum:
                min_sum = current_sum
        z += 1
    return min_sum

