import sys

def sum_digits(m):
    return sum(int(d) for d in str(m))

def find_meeting_point(n):
    current_n = n
    current_1, current_3, current_9 = 1, 3, 9

    while True:
        if current_1 == current_n:
            return (1, current_n)
        if current_3 == current_n:
            return (3, current_n)
        if current_9 == current_n:
            return (9, current_n)

        # Advance river 1
        while current_1 < current_n:
            current_1 += sum_digits(current_1)
            if current_1 == current_n:
                return (1, current_n)
        if current_1 == current_n:
            return (1, current_n)

        # Advance river 3
        while current_3 < current_n:
            current_3 += sum_digits(current_3)
            if current_3 == current_n:
                return (3, current_n)
        if current_3 == current_n:
            return (3, current_n)

        # Advance river 9
        while current_9 < current_n:
            current_9 += sum_digits(current_9)
            if current_9 == current_n:
                return (9, current_n)
        if current_9 == current_n:
            return (9, current_n)

        # Move to next step in current river
        current_n += sum_digits(current_n)

