def count_good_substrings(s):
    n = len(s)
    if n == 0:
        return 0
    # Precompute prev_ones array
    prev_ones = []
    last_one = -1
    for idx, c in enumerate(s):
        if c == '1':
            last_one = idx
        prev_ones.append(last_one)
    ones_positions = [i for i, c in enumerate(s) if c == '1']
    count = 0
    for i in ones_positions:
        for m in range(1, 21):
            if i + m > n:
                break
            # Extract binary part
            binary_str = s[i:i+m]
            if not binary_str.startswith('1'):
                continue
            try:
                x = int(binary_str, 2)
            except:
                continue
            k = x
            required_leading = k - m
            if required_leading < 0:
                continue
            start = i - required_leading
            if start < 0:
                continue
            # Check leading zeros
            if start <= i - 1:
                if i - 1 >= 0:
                    last_one_pos = prev_ones[i-1]
                    if last_one_pos >= start:
                        continue
            # Check end of substring
            end_sub = i + m - 1
            if end_sub >= n:
                continue
            count += 1
    return count

