    same_count = [0] * (n + 1)
    for u in range(1, n + 1):
        cnt = 0
        for v in enemies[u]:
            if party[v] == party[u]:
                cnt += 1
        same_count[u] = cnt

    queue = deque()
    in_queue = [False] * (n + 1)
    for u in range(1, n + 1):
        if same_count[u] > 1:
            queue.append(u)
            in_queue[u] = True

    while queue:
        u = queue.popleft()
        in_queue[u] = False
        if same_count[u] <= 1:
            continue

        old_p = party[u]
        new_p = 1 - old_p
        party[u] = new_p

        # Update same_count for all enemies of u
        for v in enemies[u]:
            if party[v] == old_p:
                same_count[v] -= 1
                if same_count[v] > 1 and not in_queue[v]:
                    queue.append(v)
                    in_queue[v] = True
            else:
                same_count[v] += 1
                if same_count[v] > 1 and not in_queue[v]:
                    queue.append(v)
                    in_queue[v] = True

        # Recalculate same_count for u
        new_same = 0
        for v in enemies[u]:
            if party[v] == new_p:
                new_same += 1
        same_count[u] = new_same
        if same_count[u] > 1 and not in_queue[u]:
            queue.append(u)
            in_queue[u] = True

