# Check if the graph is bipartite and compute s_total
for u in range(1, n + 1):
    if color[u] is None:
        q = deque([u])
        color[u] = 0
        partition0 = 1
        partition1 = 0
        is_component_bipartite = True
        while q:
            current = q.popleft()
            for neighbor in edges[current]:
                if color[neighbor] is None:
                    color[neighbor] = 1 - color[current]
                    if color[neighbor] == 0:
                        partition0 += 1
                    else:
