                    q.append(neighbor)
                else:
                    if color[neighbor] == color[current]:
                        is_component_bipartite = False
        if not is_component_bipartite:
            is_bipartite = False
            break
        s_total += (partition0 * (partition0 - 1)) // 2 + (partition1 * (partition1 - 1)) // 2

