import sys
from collections import deque

def main():
    n, m, T = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, t = map(int, sys.stdin.readline().split())
        edges[u].append((v, t))

    # Compute topological order using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for (v, t) in edges[u]:
            in_degree[v] += 1

    queue = deque()
    for u in range(1, n + 1):
        if in_degree[u] == 0:
            queue.append(u)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for (v, t) in edges[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Initialize DP and predecessor arrays
    INF = float('inf')
    dp = [[INF] * (n + 2) for _ in range(n + 2)]
    prev = [[(-1, -1) for _ in range(n + 2)] for _ in range(n + 2)]
    dp[1][1] = 0

    # Process nodes in topological order
    for u in top_order:
        for k in range(1, n + 1):
            if dp[u][k] == INF:
                continue
            for (v, t) in edges[u]:
                new_time = dp[u][k] + t
                if new_time < dp[v][k + 1]:
                    dp[v][k + 1] = new_time
                    prev[v][k + 1] = (u, k)

    # Find maximum k where dp[n][k] <= T
    max_k = -1
    for k in range(1, n + 1):
        if dp[n][k] <= T:
            max_k = k

    # Reconstruct the path
    path = []
    current, current_k = n, max_k
    while current != -1 and current_k > 0:
        path.append(current)
        current, current_k = prev[current][current_k]

    path.reverse()
    print(len(path))
    print(' '.join(map(str, path)))

