import math

def precompute_multiples(max_p):
    multiples = [[] for _ in range(max_p + 1)]
    for p in range(2, max_p + 1):
        k = 2
        while p * k <= max_p:
            multiples[p].append(p * k)
            k += 1
    return multiples

MAX_P = 60
MULTIPLES = precompute_multiples(MAX_P)

def compute_root(n, p):
    if n == 0:
        return 0
    if p == 0:
        return 0
    try:
        if p == 2:
            a = int(math.isqrt(n))
        else:
            a = int(n ** (1.0 / p))
    except OverflowError:
        a = 1
    # Adjust upwards
    while True:
        current = 1
        overflow = False
        for _ in range(p):
            current *= (a + 1)
            if current > n:
                overflow = True
                break
        if not overflow:
            a += 1
        else:
            break
    # Adjust downwards
    while True:
        current = 1
        overflow = False
        for _ in range(p):
            current *= a
            if current > n:
                overflow = True
                break
        if overflow:
            a -= 1
        else:
            break
    return a

