    n, m = len(s), len(t)

    # Precompute all substrings of s and their counts using a dictionary
    from collections import defaultdict
    freq = defaultdict(int)
    for i in range(n):
        for j in range(i+1, n+1):
            substr = s[i:j]
            freq[substr] += 1

    # Compute count_t for each unique substring x_str in freq
    ans = 0
    for x_str, cnt in freq.items():
        len_x = len(x_str)
        if len_x > len(t):
            continue
        # Dynamic programming to count subsequences in t equal to x_str
        dp = [0] * (len_x + 1)
        dp[0] = 1
        for c in t:
            for k in range(len_x, 0, -1):
                if c == x_str[k-1]:
                    dp[k] = (dp[k] + dp[k-1]) % MOD
        ans = (ans + cnt * dp[len_x]) % MOD
    print(ans % MOD)

