solution:
def is_gp(arr):
    n = len(arr)
    if n <= 1:
        return True
    if all(x == 0 for x in arr):
        return True
    if arr[0] == 0:
        for num in arr:
            if num != 0:
                return False
        return True
    a = arr[0]
    b = arr[1]
    if b == 0:
        for i in range(2, n):
            if arr[i] != 0:
                return False
        return True
    else:
        for i in range(2, n):
            if arr[i-1] == 0:
                return False
            if arr[i] * a != arr[i-1] * b:
                return False
        return True

def find_first_error(arr):
    n = len(arr)
    if n <= 1:
        return -1
    if all(x == 0 for x in arr):
        return -1
    if arr[0] == 0:
        for i in range(1, n):
            if arr[i] != 0:
                return i
        return -1
    a = arr[0]
    b = arr[1]
    if b == 0:
        for i in range(2, n):
            if arr[i] != 0:
                return i
        return -1
    else:
        for i in range(2, n):
            if arr[i-1] == 0:
                return i
            if arr[i] * a != arr[i-1] * b:
                return i
        return -1

def is_gp_after_removal(arr, remove_idx):
    virtual_arr = []
    for i in range(len(arr)):
        if i != remove_idx:
            virtual_arr.append(arr[i])
    return is_gp(virtual_arr)

def main():
    import sys
    n = int(sys.stdin.readline())
    arr = list(map(int, sys.stdin.readline().split()))
    if is_gp(arr):
        print(0)
        return
    first_error = find_first_error(arr)
    if first_error == -1:
        print(0)
        return
    valid_candidates = set()
    for c in [first_error - 1, first_error, first_error + 1]:
        if 0 <= c < n:
            valid_candidates.add(c)
    for c in [0, 1]:
        if c < n:
            valid_candidates.add(c)
    if n > 0:
        valid_candidates.add(n - 1)
    for c in valid_candidates:
        if is_gp_after_removal(arr, c):
            print(1)
            return
    print(2)

