import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(n)]
    component_id = [[-1 for _ in range(m)] for _ in range(n)]
    component_sizes = []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    current_component = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and component_id[i][j] == -1:
                q = deque()
                q.append((i, j))
                component_id[i][j] = current_component
                size = 1
                while q:
                    x, y = q.popleft()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and component_id[nx][ny] == -1:
                                component_id[nx][ny] = current_component
                                size += 1
                                q.append((nx, ny))
                component_sizes.append(size)
                current_component += 1

    result = []
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j] == '.':
                row.append('.')
            else:
                unique = set()
                for dx, dy in directions:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if grid[nx][ny] == '.':
                            unique.add(component_id[nx][ny])
                total = 1
                for c in unique:
                    total += component_sizes[c]
                row.append(str(total % 10))
        result.append(''.join(row))

    print('\n'.join(result))

