memo = {}

def get_year(s):
    if s in memo:
        return memo[s]
    s_len = len(s)
    mod = 10 ** s_len
    s_num = int(s) if s else 0  # s is non-empty as per problem statement
    target = s_num % mod
    base = 1989
    remainder = base % mod
    if remainder <= target:
        candidate = base - remainder + target
