def multiply_matrices(a, b):
    result = [[0] * 10 for _ in range(10)]
    for i in range(10):
        for k in range(10):
            if a[i][k]:
                for j in range(10):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result

def matrix_power(matrix, power):
    result = [[0] * 10 for _ in range(10)]
    for i in range(10):
        result[i][i] = 1
    current = [row[:] for row in matrix]
    while power > 0:
        if power % 2 == 1:
            result = multiply_matrices(result, current)
        current = multiply_matrices(current, current)
        power //= 2
    return result

def multiply_vector(matrix, vec):
    res = [0] * 10
    for i in range(10):
        for j in range(10):
            res[i] = (res[i] + matrix[i][j] * vec[j]) % mod
    return res

