import sys

def game_over(a, b):
    return (a >= 11 or b >= 11) and abs(a - b) >= 2

def process_game(serve_sequence, initial_server):
    a = 0
    b = 0
    current_server = initial_server
    n = len(serve_sequence)
    for i in range(n):
        if i < n - 1:
            next_server = serve_sequence[i + 1]
            if current_server == next_server:
                if current_server == 'A':
                    a += 1
                else:
                    b += 1
            else:
                if current_server == 'A':
                    b += 1
                else:
                    a += 1
            current_server = next_server
        else:
            temp_a, temp_b = a, b
            if current_server == 'A':
                temp_a += 1
            else:
                temp_b += 1
            if game_over(temp_a, temp_b):
                a, b = temp_a, temp_b
            else:
                if current_server == 'A':
                    b += 1
                else:
                    a += 1
    return a, b

