import math

def ccw(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])

def on_segment(a, b, c):
    return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

def segments_intersect_in_interior(p1, p2, q1, q2):
    o1 = ccw(p1, p2, q1)
    o2 = ccw(p1, p2, q2)
    o3 = ccw(q1, q2, p1)
    o4 = ccw(q1, q2, p2)

    if (o1 * o2 < 0) and (o3 * o4 < 0):
        return True

    if o1 == 0 and on_segment(p1, p2, q1) and q1 not in (p1, p2):
        return True
    if o2 == 0 and on_segment(p1, p2, q2) and q2 not in (p1, p2):
        return True
    if o3 == 0 and on_segment(q1, q2, p1) and p1 not in (q1, q2):
        return True
    if o4 == 0 and on_segment(q1, q2, p2) and p2 not in (q1, q2):
        return True
    return False

def compute_min_edge_distance(bx, by, p, q):
    a, b = p
    c = q[0] - p[0]
    d = q[1] - p[1]
    K = a * by - bx * b
    M = c * by - bx * d
    A = (a - bx)**2 + (b - by)**2
    B_term = 2 * (c * (a - bx) + d * (b - by))
    C = c**2 + d**2

    candidates = [0.0, 1.0]

    if M != 0:
        t1 = -K / M
        if 0 <= t1 <= 1:
            candidates.append(t1)

    denominator = M * B_term - 2 * K * C
    if denominator != 0:
        numerator = K * B_term - 2 * M * A
        t2 = numerator / denominator
        if 0 <= t2 <= 1:
            candidates.append(t2)

    min_dist = float('inf')
    for t in candidates:
        if t < 0 or t > 1:
            continue
        Sx = a + c * t
        Sy = b + d * t
        numerator = abs(Sx * by - bx * Sy)
        dx, dy = Sx - bx, Sy - by
        denominator = math.hypot(dx, dy)
        if denominator < 1e-9:
            continue
        current_dist = numerator / denominator
        if current_dist < min_dist:
            min_dist = current_dist
    return min_dist

