        kx, ky = -1, -1
        mx, my = -1, -1
        for y in range(H):
            for x in range(W):
                if grid[y][x] == 'K':
                    kx, ky = x, y
                if grid[y][x] == 'M':
                    mx, my = x, y

        # Find K's initial direction
        k_dir = -1
        for d in range(4):
            dx, dy = [(0, -1), (1, 0), (0, 1), (-1, 0)][d]
            nx = kx + dx
            ny = ky + dy
            if 0 <= nx < W and 0 <= ny < H and grid[ny][nx] == '.':
                k_dir = d
                break

        # Find M's initial direction
        m_dir = -1
        for d in range(4):
            dx, dy = [(0, -1), (1, 0), (0, 1), (-1, 0)][d]
            nx = mx + dx
            ny = my + dy
            if 0 <= nx < W and 0 <= ny < H and grid[ny][nx] == '.':
                m_dir = d
