class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None, None]
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()
        self.max_bits = 20  # Sufficient for K up to 1e6

    def insert(self, x):
        node = self.root
        for i in reversed(range(self.max_bits)):
            bit = (x >> i) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def query(self, x, K):
        node = self.root
        count = 0
        for i in reversed(range(self.max_bits)):
            if not node:
                break
            x_bit = (x >> i) & 1
            k_bit = (K >> i) & 1
            desired_y_bit = x_bit ^ k_bit
            other_y_bit = 1 - desired_y_bit
            other_xor_bit = x_bit ^ other_y_bit
            if other_xor_bit < k_bit:
                if node.children[other_y_bit]:
                    count += node.children[other_y_bit].count
            if node.children[desired_y_bit]:
                node = node.children[desired_y_bit]
            else:
                node = None
        return count

