import sys
from math import gcd
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)

    # Kosaraju's algorithm to find SCCs
    visited = [False] * (n + 1)
    order = []
    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited[v]:
                    stack.append((v, False))

    for u in range(1, n + 1):
        if not visited[u]:
            dfs(u)

    reverse_adj = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in adj[u]:
            reverse_adj[v].append(u)

    visited = [False] * (n + 1)
    sccs = []
    for u in reversed(order):
        if not visited[u]:
            stack = [u]
            visited[u] = True
            component = []
            while stack:
                node = stack.pop()
                component.append(node)
                for v in reverse_adj[node]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            sccs.append(component)

    cycle_gcds = []
    for component in sccs:
        if len(component) == 1:
            u = component[0]
            for v in adj[u]:
                if v == u:
                    cycle_gcds.append(1)
                    break
        else:
            current_gcd = 0
            start = component[0]
            d = {node: -1 for node in component}
            d[start] = 0
            q = deque([start])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if v not in d:
                        continue
                    if d[v] == -1:
                        d[v] = d[u] + 1
                        q.append(v)
                    delta = d[v] - (d[u] + 1)
                    current_gcd = gcd(current_gcd, abs(delta))
            if current_gcd != 0:
                cycle_gcds.append(current_gcd)

    if not cycle_gcds:
        print(n)
    else:
        overall_gcd = cycle_gcds[0]
        for g in cycle_gcds[1:]:
            overall_gcd = gcd(overall_gcd, g)
        print(overall_gcd if overall_gcd != 0 else n)

