class Interval:
    def __init__(self, start, end, g):
        self.start = start
        self.end = end
        self.g = g

intervals = [Interval(1, 2, 0)]
current_end = 2

def compute_mex(x):
    low = (x + 3) // 4  # ceil(x/4)
    high = x // 2
    if low > high:
        return 0
    s = set()
    for interval in intervals:
        if interval.start > high:
            break
        if interval.end <= low:
            continue
        s.add(interval.g)
    mex = 0
    while mex in s:
        mex += 1
    return mex

def build_intervals_up_to(max_x):
    global current_end, intervals
    while current_end <= max_x:
        x = current_end
        mex = compute_mex(x)
        left = x
        right = x
        while True:
            if right > max_x * 2:
                break
            current_mex = compute_mex(right)
            if current_mex == mex:
                right *= 2
            else:
                break
        right = min(right, max_x * 2)
        best = x
        while left <= right:
            mid = (left + right) // 2
            if mid > max_x * 2:
                break
            current_mex = compute_mex(mid)
            if current_mex == mex:
                best = mid
                left = mid + 1
            else:
                right = mid - 1
        end = best + 1
        intervals.append(Interval(x, end, mex))
        current_end = end
        if current_end > max_x:
            break

