import sys
from collections import defaultdict

def main():
    m = int(sys.stdin.readline())
    essay = sys.stdin.readline().split()
    n = int(sys.stdin.readline())
    synonyms = [tuple(sys.stdin.readline().split()) for _ in range(n)]

    all_words = set(essay)
    for x, y in synonyms:
        all_words.add(x)
        all_words.add(y)

    word_info = defaultdict(lambda: (float('inf'), float('inf')))
    for word in all_words:
        lower_word = word.lower()
        r = sum(1 for c in word if c.lower() == 'r')
        l = len(word)
        if (r, l) < word_info[lower_word]:
            word_info[lower_word] = (r, l)

    graph = defaultdict(list)
    for x, y in synonyms:
        src = x.lower()
        dest = y.lower()
        graph[src].append(dest)
    for word in word_info:
        if word not in graph:
            graph[word] = []

    def kosaraju(g):
        visited = set()
        order = []
        for node in g:
            if node not in visited:
                stack = [(node, False)]
                while stack:
                    v, processed = stack.pop()
                    if processed:
                        order.append(v)
                        continue
                    if v in visited:
                        continue
                    visited.add(v)
                    stack.append((v, True))
                    for neighbor in g.get(v, []):
                        if neighbor not in visited:
                            stack.append((neighbor, False))
        reversed_g = defaultdict(list)
        for u in g:
            for v in g[u]:
                reversed_g[v].append(u)
        visited = set()
        components = []
        for node in reversed(order):
            if node not in visited:
                stack = [node]
                visited.add(node)
                component = []
                while stack:
                    u = stack.pop()
                    component.append(u)
                    for v in reversed_g.get(u, []):
                        if v not in visited:
                            visited.add(v)
                            stack.append(v)
                components.append(component)
        return components

    components = kosaraju(graph)

    node_component = {}
    for i, comp in enumerate(components):
        for node in comp:
            node_component[node] = i

    component_min = []
    for comp in components:
        min_r, min_len = word_info[comp[0]]
        for node in comp[1:]:
            r, l = word_info[node]
            if r < min_r or (r == min_r and l < min_len):
                min_r, min_len = r, l
        component_min.append((min_r, min_len))

    condensed_graph = defaultdict(set)
    for u in graph:
        for v in graph[u]:
            uc = node_component[u]
            vc = node_component[v]
            if uc != vc:
                condensed_graph[uc].add(vc)

    visited = [False] * len(components)
    topo_order = []

    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                topo_order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in condensed_graph.get(node, []):
                if not visited[v]:
                    stack.append((v, False))

    for i in range(len(components)):
        if not visited[i]:
            dfs(i)
    topo_order.reverse()

    for u in topo_order:
        current_r, current_len = component_min[u]
        for v in condensed_graph.get(u, []):
            vr, vl = component_min[v]
            if (vr < current_r) or (vr == current_r and vl < current_len):
                current_r, current_len = vr, vl
        component_min[u] = (current_r, current_len)

    total_r = 0
    total_len = 0
    for word in essay:
        lower_word = word.lower()
        comp_idx = node_component.get(lower_word, -1)
        if comp_idx == -1:
            r, l = word_info[lower_word]
        else:
            r, l = component_min[comp_idx]
        total_r += r
        total_len += l

    print(total_r, total_len)

