    for _ in range(N):
        x = int(input[idx])
        y = int(input[idx+1])
        original_points.append((x, y))
        idx +=2

    hull = convex_hull(original_points)
    m = len(hull)
    probabilities = [0.0]*N

    if m == 2:
        for i in range(N):
            if original_points[i] in hull:
                probabilities[i] = 0.5
    else:
        for i in range(m):
            current = hull[i]
            prev_p = hull[(i-1) % m]
            next_p = hull[(i+1) % m]

            BA = (prev_p[0] - current[0], prev_p[1] - current[1])
            BC = (next_p[0] - current[0], next_p[1] - current[1])

            dot = BA[0] * BC[0] + BA[1] * BC[1]
            mag_BA = math.hypot(BA[0], BA[1])
            mag_BC = math.hypot(BC[0], BC[1])

            if mag_BA == 0 or mag_BC == 0:
                cos_theta = 0.0
            else:
                cos_theta = dot / (mag_BA * mag_BC)

            cos_theta = max(-1.0, min(1.0, cos_theta))
            theta = math.acos(cos_theta)
            prob = (math.pi - theta) / (2 * math.pi)

            idx_original = original_points.index(current)
            probabilities[idx_original] = prob

    for p in probabilities:
        print("{0:.20f}".format(p))

