def process_dataset(n):
    if n == 0:
        return
    k = (n - 1) // 2
    # Compute quadratic residues modulo n
    residues = set()
    for x in range(1, n):
        residues.add((x * x) % n)
    residues = list(residues)
    counts = [0] * (k + 1)
    # Iterate over all ordered pairs (a, b)
    for a in residues:
        for b in residues:
            if a == b:
                continue
            diff = (a - b) % n
            if diff > k:
                diff = n - diff
            counts[diff] += 1
    # Output the counts for differences 1 to k
    for i in range(1, k + 1):
        print(counts[i])

