def determinant_mod(mat, mod):
    n = len(mat)
    mat = [row[:] for row in mat]
    swaps = 0
    for col in range(n):
        pivot = -1
        for row in range(col, n):
            if mat[row][col] != 0:
                pivot = row
                break
        if pivot == -1:
            return 0
        if pivot != col:
            mat[col], mat[pivot] = mat[pivot], mat[col]
            swaps += 1
        inv_pivot = pow(mat[col][col], mod-2, mod)
        for row in range(col+1, n):
            factor = mat[row][col] * inv_pivot % mod
            for c in range(col, n):
                mat[row][c] = (mat[row][c] - factor * mat[col][c]) % mod
    det = 1
    for i in range(n):
        det = det * mat[i][i] % mod
    det = det * (-1)**swaps % mod
    return det

