def prime_factors(n):
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n = n // 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n = n // i
        i += 2
    if n > 1:
        factors.add(n)
    return factors

def euler_phi(n):
    if n == 0:
        return 0
    factors = prime_factors(n)
    result = n
    for p in factors:
        result = result // p * (p - 1)
    return result

