import sys

def tokenize(code_str):
    tokens = []
    i = 0
    n = len(code_str)
    while i < n:
        while i < n and code_str[i].isspace():
            i += 1
        if i >= n:
            break
        if code_str[i] == '=' and i+1 < n and code_str[i+1] == '=':
            tokens.append('==')
            i += 2
            continue
        if code_str[i] in '(){};+-*/<>':
            tokens.append(code_str[i])
            i += 1
            continue
        if code_str[i].isdigit():
            j = i
            while j < n and code_str[j].isdigit():
                j += 1
            tokens.append(code_str[i:j])
            i = j
            continue
        if code_str[i].isalpha():
            j = i
            while j < n and (code_str[j].isalnum() or code_str[j] == '_'):
                j += 1
            token = code_str[i:j]
            tokens.append(token)
            i = j
            continue
        raise ValueError(f"Unexpected character: {code_str[i]}")
    return tokens

def parse_arithmExpr(tokens):
    def parse_sum():
        def parse_product():
            def parse_multiplier():
                tok = tokens[0]
                if tok == 'n':
                    tokens.pop(0)
                    return lambda n, fv: n
                elif tok.isdigit():
                    val = int(tok)
                    tokens.pop(0)
                    return lambda n, fv: val
                elif tok == 'f':
                    tokens.pop(0)
                    if tokens[0] != '(':
                        raise ValueError("Expected '(' after f")
                    tokens.pop(0)
                    expr = parse_sum()
                    if tokens[0] != ')':
                        raise ValueError("Expected ')' after f's argument")
                    tokens.pop(0)
                    return lambda n, fv: fv[expr(n, fv) % 32768]
                else:
                    raise ValueError(f"Unexpected multiplier token: {tok}")

            left = parse_multiplier()
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.pop(0)
                right = parse_multiplier()
                if op == '*':
                    new_left = lambda n, fv, l=left, r=right: (l(n, fv) * r(n, fv)) % 32768
                else:
                    new_left = lambda n, fv, l=left, r=right: (l(n, fv) // r(n, fv)) if r(n, fv) != 0 else 0
                left = new_left
            return left

        left = parse_product()
        while tokens and tokens[0] in ('+', '-'):
            op = tokens.pop(0)
            right = parse_product()
            if op == '+':
                new_left = lambda n, fv, l=left, r=right: (l(n, fv) + r(n, fv)) % 32768
            else:
                new_left = lambda n, fv, l=left, r=right: (l(n, fv) - r(n, fv)) % 32768
            left = new_left
        return left
    return parse_sum()

def parse_logicalExpr(tokens):
    left = parse_arithmExpr(tokens)
    op = tokens.pop(0)
    right = parse_arithmExpr(tokens)
    if op == '<':
        return lambda n, fv: left(n, fv) < right(n, fv)
    elif op == '>':
        return lambda n, fv: left(n, fv) > right(n, fv)
    elif op == '==':
        return lambda n, fv: left(n, fv) == right(n, fv)
    else:
        raise ValueError(f"Invalid operator: {op}")

def parse_statements(tokens):
    statements = []
    while tokens and tokens[0] != '}':
        if tokens[0] == 'if':
            tokens.pop(0)
            tokens.pop(0)  # '('
            cond = parse_logicalExpr(tokens)
            tokens.pop(0)  # ')'
            if tokens[0] != 'return':
                raise ValueError("Expected return")
            tokens.pop(0)
            expr = parse_arithmExpr(tokens)
            tokens.pop(0)  # ';'
            statements.append( (cond, expr) )
        elif tokens[0] == 'return':
            tokens.pop(0)
            expr = parse_arithmExpr(tokens)
            tokens.pop(0)  # ';'
            statements.append( (None, expr) )
        else:
            raise ValueError(f"Unexpected token: {tokens[0]}")
    return statements

def main():
    target = int(sys.stdin.readline())
    code_lines = [line.rstrip() for line in sys.stdin]
    code_str = ''.join(code_lines)
    tokens = tokenize(code_str)

    try:
        if tokens[:6] != ['int', 'f', '(', 'int', 'n', ')'] or tokens[6] != '{':
            raise ValueError("Invalid function signature")
        body_tokens = tokens[7:tokens.index('}')]
    except (ValueError, IndexError):
        print(-1)
        return

    try:
        statements = parse_statements(body_tokens)
    except:
        print(-1)
        return

    f_values = [0] * 32768
    for n in range(32768):
        for cond, expr in statements:
            if cond is None:
                f_values[n] = expr(n, f_values) % 32768
                break
            elif cond(n, f_values):
                f_values[n] = expr(n, f_values) % 32768
                break

    for n in reversed(range(32768)):
        if f_values[n] == target:
            print(n)
            return
    print(-1)

