import sys
from collections import deque

def sliding_max(arr, k):
    q = deque()
    max_vals = []
    for i, num in enumerate(arr):
        while q and num >= arr[q[-1]]:
            q.pop()
        q.append(i)
        while q[0] <= i - k:
            q.popleft()
        if i >= k - 1:
            max_vals.append(arr[q[0]])
    return max_vals

def main():
