        grid[x-1][y-1] = t

    row_max = []
    for row in grid:
        if m >= k:
            rm = sliding_max(row, k)
            row_max.append(rm)

    all_maxima = []
    if not row_max:
        print(-1)
        return

    cols = len(row_max[0])
