    for y in range(H):
        for x in range(W):
            if (x == 0 or x == W-1 or y == 0 or y == H-1) and grid[y][x] == 0:
                if not exterior[y][x]:
                    exterior[y][x] = True
                    q.append((x, y))

    # BFS to mark exterior regions
    while q:
        x, y = q.popleft()
        parity = (y + 1) % 2
        neighbors = []
        neighbors.append((x + 1, y))
        neighbors.append((x - 1, y))
        if parity == 1:
            neighbors.extend([(x, y - 1), (x - 1, y - 1), (x, y + 1), (x - 1, y + 1)])
        else:
            neighbors.extend([(x + 1, y - 1), (x, y - 1), (x + 1, y + 1), (x, y + 1)])
        for nx, ny in neighbors:
            if 0 <= nx < W and 0 <= ny < H:
                if grid[ny][nx] == 0 and not exterior[ny][nx]:
                    exterior[ny][nx] = True
                    q.append((nx, ny))

    total = 0
    # Calculate perimeter for each building cell
    for y in range(H):
