import sys
from collections import deque

class Node:
    __slots__ = ['children', 'fail', 'output']
    def __init__(self):
        self.children = dict()
        self.fail = None
        self.output = []

def build_automaton(patterns):
    root = Node()
    for p in patterns:
        node = root
        for c in p:
            if c not in node.children:
                node.children[c] = Node()
            node = node.children[c]
        node.output.append(len(p))
    q = deque()
    for child in root.children.values():
        child.fail = root
        q.append(child)
    while q:
        current_node = q.popleft()
        for c, child in current_node.children.items():
            fail_node = current_node.fail
            while fail_node is not None and c not in fail_node.children:
                fail_node = fail_node.fail
            child.fail = fail_node.children[c] if fail_node else root
            child.output += child.fail.output
            q.append(child)
    return root

def main():
    S = sys.stdin.readline().strip()
    N = int(sys.stdin.readline())
    P = [sys.stdin.readline().strip() for _ in range(N)]
    root = build_automaton(P)
    current_node = root
    intervals = []
    for i in range(len(S)):
        c = S[i]
        while current_node is not None and c not in current_node.children:
            current_node = current_node.fail
        if current_node is None:
            current_node = root
        else:
            current_node = current_node.children[c]
        for L in current_node.output:
            start = i - L + 1
            if start >= 0:
                intervals.append((start, i))
    intervals = list({(s, e) for s, e in intervals})
    intervals.sort(key=lambda x: x[1])
    count = 0
    last = -1
    for s, e in intervals:
        if s > last:
            count += 1
            last = e
    print(count)

