import sys
from collections import deque

def find_centers(n, adj):
    if n == 1:
        return [1]
    def bfs(start):
        visited = [-1] * (n + 1)
        q = deque([start])
        visited[start] = 0
        max_dist = 0
        far_node = start
        while q:
            u = q.popleft()
            for v in adj[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    if visited[v] > max_dist:
                        max_dist = visited[v]
                        far_node = v
                    q.append(v)
        return far_node, max_dist
    u, _ = bfs(1)
    v, diameter = bfs(u)
    parents = {}
    q = deque([v])
    visited = {v: None}
    while q:
        node = q.popleft()
        for neighbor in adj[node]:
            if neighbor not in visited:
                visited[neighbor] = node
                q.append(neighbor)
    path = []
    current = u
    while current is not None:
        path.append(current)
        current = visited.get(current)
    mid = (diameter) // 2
    if diameter % 2 == 0:
        centers = [path[mid]]
    else:
        centers = [path[mid], path[mid + 1]]
    return centers

