# Function to compute sliding max/min for fixed window size
def sliding_window(arr, size, is_max):
    dq = deque()
    result = []
    for i in range(len(arr)):
        if is_max:
            while dq and arr[i] >= arr[dq[-1]]:
                dq.pop()
        else:
            while dq and arr[i] <= arr[dq[-1]]:
                dq.pop()
        dq.append(i)
        # Remove elements out of window
        while dq[0] <= i - size:
            dq.popleft()
        if i >= size - 1:
            result.append(arr[dq[0]])
    return result

