import math

def prime_factors(n):
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        factors.add(n)
    return factors

def compute_f(x, y):
    d = math.gcd(x, y)
    a_prime = x // d
    b_prime = y // d
    res = 0
    while True:
        if b_prime == 0:
            break
        if a_prime == 1:
            res += b_prime
            break
        primes = prime_factors(a_prime)
        max_x = -1
        for p in primes:
            q = (b_prime - 1) // p
            current_x = p * q
            if current_x > max_x:
                max_x = current_x
        if max_x >= 0:
            k = b_prime - max_x
            res += k
            g = math.gcd(a_prime, max_x)
        else:
            res += b_prime
            break
        a_prime = a_prime // g
