import sys

def longest_palindrome_subseq(s):
    n = len(s)
    if n == 0:
        return ""
    # Initialize DP table
    dp = [[0] * n for _ in range(n)]
    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the palindrome
    i, j = 0, n-1
    left, right = [], []
    while i <= j:
        if i == j:
            left.append(s[i])
            break
        elif s[i] == s[j]:
            left.append(s[i])
            right.append(s[j])
            i += 1
            j -= 1
        else:
            if dp[i+1][j] > dp[i][j-1]:
                i += 1
            else:
                j -= 1
    return ''.join(left) + ''.join(reversed(right))

