    else:
        size = k
        matrix = [[0] * size for _ in range(size)]
        for i in range(size - 1):
            matrix[i][i + 1] = 1
        matrix[-1] = [bi % mod for bi in b]

        def multiply(a, b):
            res = [[0] * len(b[0]) for _ in range(len(a))]
            for i in range(len(a)):
                for k_row in range(len(b)):
                    if a[i][k_row] == 0:
                        continue
                    for j in range(len(b[0])):
                        res[i][j] = (res[i][j] + a[i][k_row] * b[k_row][j]) % mod
            return res

        def matrix_pow(mat, power):
            result = [[0] * len(mat) for _ in range(len(mat))]
            for i in range(len(mat)):
                result[i][i] = 1
            while power > 0:
                if power % 2 == 1:
                    result = multiply(result, mat)
                mat = multiply(mat, mat)
                power //= 2
            return result

        def vec_mat_mult(vec, mat):
            res = [0] * len(vec)
            for i in range(len(vec)):
                if vec[i] == 0:
                    continue
                for j in range(len(mat[i])):
                    res[j] = (res[j] + vec[i] * mat[i][j]) % mod
            return res

        power = n - k
        if power < 0:
            exponent = 0
        else:
            mat_powed = matrix_pow(matrix, power)
            initial = [0] * k
            initial[-1] = 1
            final = vec_mat_mult(initial, mat_powed)
            exponent = final[-1]
    exponent %= mod

