    t = exponent // d
    mod_new = mod // d
    try:
        inv_t = pow(t, -1, mod_new)
    except ValueError:
        print(-1)
        return

    candidate = pow(m, inv_t, p)
    if pow(candidate, exponent, p) == m:
        print(candidate)
