from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    rev_adj = [[] for _ in range(n+1)]  # Reversed graph for BFS
    adj = [[] for _ in range(n+1)]      # Original graph to collect edges

    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        rev_adj[v].append(u)

    k = int(sys.stdin.readline())
    path = list(map(int, sys.stdin.readline().split()))
    t = path[-1]

    # Compute shortest distances from t using reversed graph
    d = [-1] * (n+1)
    q = deque([t])
    d[t] = 0
    while q:
        u = q.popleft()
        for v in rev_adj[u]:
            if d[v] == -1:
                d[v] = d[u] + 1
                q.append(v)

    # Precompute for each node u, the list of next nodes in shortest paths
    adj_shortest = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        if d[u] == -1:
            continue
        for v in adj[u]:
            if d[v] == d[u] - 1:
                adj_shortest[u].append(v)

    min_rebuild = 0
    max_rebuild = 0

    for i in range(k-1):
        u = path[i]
        v = path[i+1]
        if d[u] - 1 != d[v]:
            min_rebuild += 1
            max_rebuild += 1
        else:
            if len(adj_shortest[u]) > 1:
                max_rebuild += 1

    print(min_rebuild, max_rebuild)

