MOD = 10**9 + 7

def sum_power(m, l, r):
    if l > r:
        return 0
    def sum_1_to_n(n):
        if n < 0:
            return 0
        if m == 0:
            return n % MOD
        elif m == 1:
            return (n * (n + 1) // 2) % MOD
        elif m == 2:
            return (n * (n + 1) * (2 * n + 1) // 6) % MOD
        elif m == 3:
            s = (n * (n + 1) // 2) % MOD
            return (s * s) % MOD
        elif m == 4:
            inv30 = 233333335
            term1 = 6 * pow(n, 5, MOD)
            term2 = 15 * pow(n, 4, MOD)
            term3 = 10 * pow(n, 3, MOD)
            term4 = (-n) % MOD
            total = (term1 + term2 + term3 + term4) % MOD
            return (total * inv30) % MOD
        elif m == 5:
            inv12 = 83333334
            term1 = 2 * pow(n, 6, MOD)
            term2 = 6 * pow(n, 5, MOD)
            term3 = 5 * pow(n, 4, MOD)
            term4 = (-pow(n, 2, MOD)) % MOD
            total = (term1 + term2 + term3 + term4) % MOD
            return (total * inv12) % MOD
        else:
            return 0
    total = (sum_1_to_n(r) - sum_1_to_n(l - 1)) % MOD
    return total if total >= 0 else total + MOD

class SegmentTreeNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.sum_im = [0] * 6
        self.lazy = None

    def push(self):
        if self.lazy is not None and self.left:
            x = self.lazy
            self.left.lazy = x
            self.right.lazy = x
            for m in range(6):
                self.left.sum_im[m] = x * sum_power(m, self.left.l + 1, self.left.r + 1) % MOD
                self.right.sum_im[m] = x * sum_power(m, self.right.l + 1, self.right.r + 1) % MOD
            self.lazy = None

    def update(self, l, r, x):
        if self.r < l or self.l > r:
            return
        if l <= self.l and self.r <= r:
            self.lazy = x
            for m in range(6):
                self.sum_im[m] = x * sum_power(m, self.l + 1, self.r + 1) % MOD
            return
        self.push()
        self.left.update(l, r, x)
        self.right.update(l, r, x)
        for m in range(6):
            self.sum_im[m] = (self.left.sum_im[m] + self.right.sum_im[m]) % MOD

    def query(self, l, r):
        if self.r < l or self.l > r:
            return [0] * 6
        if l <= self.l and self.r <= r:
            return self.sum_im.copy()
        self.push()
        left_sum = self.left.query(l, r)
        right_sum = self.right.query(l, r)
        res = [(left_sum[m] + right_sum[m]) % MOD for m in range(6)]
        return res

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.root = self.build(0, self.n - 1, data)

    def build(self, l, r, data):
        node = SegmentTreeNode(l, r)
        if l == r:
            for m in range(6):
                node.sum_im[m] = data[l] * pow(l + 1, m, MOD) % MOD
            return node
        mid = (l + r) // 2
        node.left = self.build(l, mid, data)
        node.right = self.build(mid + 1, r, data)
        for m in range(6):
            node.sum_im[m] = (node.left.sum_im[m] + node.right.sum_im[m]) % MOD
        return node

    def update_range(self, l, r, x):
        self.root.update(l - 1, r - 1, x)

    def query_range(self, l, r):
        return self.root.query(l - 1, r - 1)

