import sys
import math
from itertools import combinations

def is_harmony(sequence):
    for a, b in combinations(sequence, 2):
        if math.gcd(a, b) != 1:
            return False
    return True

def generate_candidates(a, max_candidates=5):
    candidates = []
    seen = set()
    candidates.append(1)
    seen.add(1)
    if a not in seen:
        candidates.append(a)
        seen.add(a)
    delta = 1
    while len(candidates) < max_candidates:
        lower = a - delta
        if lower > 0 and lower not in seen:
            candidates.append(lower)
            seen.add(lower)
        if len(candidates) >= max_candidates:
            break
        upper = a + delta
        if upper not in seen:
            candidates.append(upper)
            seen.add(upper)
        delta += 1
    candidates.sort(key=lambda x: abs(x - a))
    return candidates[:max_candidates]

def backtrack(index, current, current_sum, a, candidates_list, min_sum, best_seq):
    if index == len(a):
        if current_sum < min_sum[0] and is_harmony(current):
            min_sum[0] = current_sum
            best_seq[:] = current.copy()
        return
    if current_sum >= min_sum[0]:
        return
    for candidate in candidates_list[index]:
        delta = abs(candidate - a[index])
        new_sum = current_sum + delta
        if new_sum >= min_sum[0]:
            continue
        valid = True
        for i in range(index):
            if math.gcd(current[i], candidate) != 1:
                valid = False
                break
        if valid:
            current.append(candidate)
            backtrack(index + 1, current, new_sum, a, candidates_list, min_sum, best_seq)
            current.pop()

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    if is_harmony(a):
        print(' '.join(map(str, a)))
        return
    candidates_list = [generate_candidates(num, 5) for num in a]
    min_sum = [float('inf')]
    best_seq = []
    backtrack(0, [], 0, a, candidates_list, min_sum, best_seq)
    print(' '.join(map(str, best_seq)) + ' ')

