class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None, None]
        self.count = 0

def insert(root, number):
    node = root
    for i in reversed(range(30)):
        bit = (number >> i) & 1
        if not node.children[bit]:
            node.children[bit] = TrieNode()
        node = node.children[bit]
        node.count += 1

def delete(root, number):
    node = root
    path = []
    for i in reversed(range(30)):
        bit = (number >> i) & 1
        path.append( (node, bit) )
        node = node.children[bit]
        if not node:
            return

    for i in reversed(range(30)):
        parent_node, bit = path[i]
        current_node = parent_node.children[bit]
        current_node.count -= 1
        if current_node.count == 0:
            parent_node.children[bit] = None

def find_min_xor(root, a):
    node = root
    p = 0
    for i in reversed(range(30)):
        desired_bit = (a >> i) & 1
        if node.children[desired_bit] and node.children[desired_bit].count > 0:
            node = node.children[desired_bit]
            p = (p << 1) | desired_bit
        else:
            other_bit = 1 - desired_bit
            if node.children[other_bit] and node.children[other_bit].count > 0:
                node = node.children[other_bit]
                p = (p << 1) | other_bit
            else:
                return None
    return p

