import sys
from collections import defaultdict

def main():
    for line in sys.stdin:
        n, s = map(int, line.strip().split())
        # Calculate minimum and maximum possible sums
        min_sum = sum(i * (n - i) for i in range(1, n + 1))
        max_sum = sum(i * (9 - n + i) for i in range(1, n + 1))
        if s < min_sum or s > max_sum:
            print(0)
            continue
        # Initialize dynamic programming table
        dp = defaultdict(lambda: defaultdict(int))
        dp[0][0] = 1  # Starting with mask 0 (no digits used) and sum 0
        for pos in range(1, n + 1):
            new_dp = defaultdict(lambda: defaultdict(int))
            for mask in dp:
                for current_sum in dp[mask]:
                    count = dp[mask][current_sum]
                    for d in range(10):
                        if not (mask & (1 << d)):
                            new_mask = mask | (1 << d)
                            new_sum = current_sum + pos * d
                            if new_sum > s:
                                continue  # Prune sums exceeding s
                            new_dp[new_mask][new_sum] += count
            dp = new_dp
        # Sum all valid combinations
        total = 0
        for mask in dp:
            if bin(mask).count('1') == n:  # Check if exactly n digits are used
                total += dp[mask].get(s, 0)
        print(total)

