        lose = []
        for _ in range(L):
            lose.append(int(sys.stdin.readline().strip()))
        back = []
        for _ in range(B):
            back.append(int(sys.stdin.readline().strip()))
        lose_set = set(lose)
        back_set = set(back)

        # Initialize DP table: dp[t][p][s]
        dp = [[[0.0 for _ in range(2)] for __ in range(N+1)] for ___ in range(T+1)]
        dp[T][0][0] = 1.0
        success = 0.0

        for t_remaining in range(T, 0, -1):
            for p in range(N+1):
                for s in [0, 1]:
                    current_prob = dp[t_remaining][p][s]
                    if current_prob <= 0:
                        continue
                    if p == N:
                        success += current_prob
                        continue
                    if s == 1:
                        # Skip this turn
                        dp[t_remaining-1][p][0] += current_prob
                    else:
                        # Roll the dice
                        for d in range(1, 7):
                            new_p = p + d
                            if new_p > N:
                                new_p = 2 * N - new_p
                            # Check Back squares
                            if new_p in back_set:
                                new_p = 0
                            # Check Lose squares
                            new_skip = 1 if new_p in lose_set else 0
                            if new_p == N:
                                success += current_prob * (1/6)
                            else:
                                if t_remaining - 1 >= 0:
                                    dp[t_remaining-1][new_p][new_skip] += current_prob * (1/6)
        print("{0:.6f}".format(success))

