import sys
from collections import defaultdict, deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    edge_set = set()
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        x, y = map(int, sys.stdin.readline().split())
        if x > y:
            x, y = y, x
        edges.append((x, y))
        edge_set.add((x, y))
        adj[x].append(y)
        adj[y].append(x)

    k = int(sys.stdin.readline())
    required = []
    for _ in range(k):
        a, b = map(int, sys.stdin.readline().split())
        required.append((a, b))

    # Assign directions greedily based on required paths
    edge_direction = {}
    conflict = False

    for a, b in required:
        visited = [False] * (n+1)
        prev = {}
        q = deque()
        q.append(a)
        visited[a] = True
        found = False
        while q and not found:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    prev[v] = u
                    visited[v] = True
                    if v == b:
                        found = True
                        break
                    q.append(v)
            if found:
                break

        if not found:
            print("No")
            return

        path = []
        current = b
        while current != a:
            parent = prev[current]
            path.append((parent, current))
            current = parent

        for u, v in path:
            if (u, v) in edge_set:
                if (u, v) in edge_direction:
                    if edge_direction[(u, v)] != (u, v):
                        conflict = True
                        break
                else:
                    edge_direction[(u, v)] = (u, v)
            else:
                # must be (v, u) in edge_set
                if (v, u) in edge_direction:
                    if edge_direction[(v, u)] != (u, v):
                        conflict = True
                        break
                else:
                    edge_direction[(v, u)] = (u, v)
        if conflict:
            break

    if conflict:
        print("No")
        return

    # Assign remaining edges (those not in any path) arbitrarily
    for x, y in edges:
        if (x, y) not in edge_direction:
            edge_direction[(x, y)] = (x, y)

    # Check if all required transfers are satisfied
    # Build the directed adjacency list
    dir_adj = [[] for _ in range(n+1)]
    for x, y in edges:
        if (x, y) in edge_direction:
            u, v = edge_direction[(x, y)]
            dir_adj[u].append(v)
        else:
            u, v = edge_direction[(y, x)]
            dir_adj[u].append(v)

    # Preprocess for BFS
    reachable = defaultdict(set)
    for a, b in required:
        if b in reachable[a]:
            continue
        visited = [False]*(n+1)
        q = deque()
        q.append(a)
        visited[a] = True
        while q:
            u = q.popleft()
            for v in dir_adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
                    reachable[a].add(v)
                if v == b:
                    break
            if visited[b]:
                break
        if not visited[b]:
            print("No")
            return

    print("Yes")
    for x, y in edges:
        if (x, y) in edge_direction:
            print(edge_direction[(x, y)][0], edge_direction[(x, y)][1])
        else:
            print(edge_direction[(y, x)][1], edge_direction[(y, x)][0])

