        # Generate all possible sums with existing weights
        current_sums = {0}
        for w in weights:
            new_sums = set()
            for s in current_sums:
                new_sums.add(s + w)
                new_sums.add(s - w)
                new_sums.add(s)
            current_sums = new_sums

        required_a = [a for a in a_list if a not in current_sums]
        if not required_a:
            print(0)
            continue

        # Collect possible x candidates for each required_a
        candidates = []
        possible = True
        for a in required_a:
            possible_x = set()
            for s in current_sums:
                x1 = a - s
                if x1 > 0:
                    possible_x.add(x1)
                x2 = s - a
                if x2 > 0:
                    possible_x.add(x2)
            if not possible_x:
                possible = False
                break
            candidates.append(possible_x)

        if not possible:
            print(-1)
            continue

        # Find intersection of all candidates
        common = candidates[0].copy()
        for s_set in candidates[1:]:
            common.intersection_update(s_set)
            if not common:
                break

        if common:
            print(min(common))
        else:
            print(-1)

