import sys

def compute_unit_digit(N):
    total = 0
    for k in range(1, N + 1):
        d = k % 10
        if d in {0, 1, 5, 6}:
            term = d
        elif d == 4:
            term = 6
        elif d == 9:
            term = 1
        else:
            if k >= 4:
                term = 6 if d in {2, 8} else 1
            else:
                exponent = 1 if k == 1 else 2
                term = pow(d, exponent, 10)
        total += term
    return total % 10

