def merge(a, b, k):
    merged = []
    i = j = 0
    while i < len(a) and j < len(b) and len(merged) < k:
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1
    while i < len(a) and len(merged) < k:
        merged.append(a[i])
        i += 1
    while j < len(b) and len(merged) < k:
        merged.append(b[j])
        j += 1
    return merged

