class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def find_kth(ft, k):
    low = 1
    high = ft.n
    res = -1
    while low <= high:
        mid = (low + high) // 2
        sum_mid = ft.query(mid)
        if sum_mid >= k:
            res = mid
            high = mid - 1
        else:
            low = mid + 1
    return res

