import sys

def intersect(v_boundary, h_boundary):
    if v_boundary == 'left_edge':
        x = 0.0
        if h_boundary == 'bottom_edge':
            return (0.0, 0.0)
        elif h_boundary == 'top_edge':
            return (0.0, 1.0)
        else:
            c, d = h_boundary
            y = c + (d - c) * x
            return (x, y)
    elif v_boundary == 'right_edge':
        x = 1.0
        if h_boundary == 'bottom_edge':
            return (1.0, 0.0)
        elif h_boundary == 'top_edge':
            return (1.0, 1.0)
        else:
            c, d = h_boundary
            y = c + (d - c) * x
            return (x, y)
    else:
        a, b = v_boundary
        if h_boundary == 'bottom_edge':
            return (a, 0.0)
        elif h_boundary == 'top_edge':
            return (b, 1.0)
        else:
            c, d = h_boundary
            denominator = 1.0 - (d - c) * (b - a)
            if denominator == 0:
                return (0.0, 0.0)
            numerator = c + a * (d - c)
            y = numerator / denominator
            x = a + (b - a) * y
            return (x, y)

def polygon_area(points):
    area = 0.0
    n = len(points)
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i+1) % n]
        area += (x1 * y2 - y1 * x2)
    return abs(area) * 0.5

