import sys

def solve():
    for line in sys.stdin:
        N = int(line.strip())
        if N == 0:
            break
        a = list(map(str, input().split()))

        # Check for adjacent x's
        has_adjacent_x = False
        for i in range(N):
            if a[i] == 'x':
                if (i > 0 and a[i-1] == 'x') or (i < N-1 and a[i+1] == 'x'):
                    has_adjacent_x = True
                    break
        if has_adjacent_x:
            print('none')
            continue

        count_x = sum(1 for elem in a if elem == 'x')
        if count_x == 0:
            # Check if the array is valid
            valid = True
            for i in range(N):
                current_val = int(a[i])
                pos = i + 1
                if pos % 2 == 0:
                    # Must be peak
                    for di in [-1, 1]:
                        ni = i + di
                        if 0 <= ni < N:
                            nval = int(a[ni])
                            if current_val <= nval:
                                valid = False
                                break
                    if not valid:
                        break
                else:
                    # Must be valley
                    for di in [-1, 1]:
                        ni = i + di
                        if 0 <= ni < N:
                            nval = int(a[ni])
                            if current_val >= nval:
                                valid = False
                                break
                    if not valid:
                        break
            print('ambiguous' if valid else 'none')
            continue

        lower = -float('inf')
        upper = float('inf')
        possible = True

        for i in range(N):
            if a[i] != 'x':
                current_val = int(a[i])
                pos = i + 1
                if pos % 2 == 0:
                    # Even, must be peak
                    for di in [-1, 1]:
                        ni = i + di
                        if 0 <= ni < N:
                            nval = a[ni]
                            if nval != 'x':
                                nval_int = int(nval)
                                if current_val <= nval_int:
                                    possible = False
                                    break
                            else:
                                # Neighbor is x, current_val > k
                                upper = min(upper, current_val - 1)
                    if not possible:
                        break
                else:
                    # Odd, must be valley
                    for di in [-1, 1]:
                        ni = i + di
                        if 0 <= ni < N:
                            nval = a[ni]
                            if nval != 'x':
                                nval_int = int(nval)
                                if current_val >= nval_int:
                                    possible = False
                                    break
                            else:
                                # Neighbor is x, current_val < k
                                lower = max(lower, current_val + 1)
                    if not possible:
                        break
            else:
                # Current is x
                pos = i + 1
                if pos % 2 == 0:
                    # Even, must be peak, k > neighbors
                    if i > 0:
                        left_val = int(a[i-1])
                        lower = max(lower, left_val + 1)
                    if i < N-1:
                        right_val = int(a[i+1])
                        lower = max(lower, right_val + 1)
                else:
                    # Odd, must be valley, k < neighbors
                    if i > 0:
                        left_val = int(a[i-1])
                        upper = min(upper, left_val - 1)
                    if i < N-1:
                        right_val = int(a[i+1])
                        upper = min(upper, right_val - 1)

        if not possible:
            print('none')
        else:
            if lower > upper:
                print('none')
            elif lower == upper:
                print(lower)
            else:
                print('ambiguous')

