import sys

def split_runs(s):
    if not s:
        return []
    runs = []
    current = s[0]
    count = 1
    for c in s[1:]:
        if c == current:
            count += 1
        else:
            runs.append((current, count))
            current = c
            count = 1
    runs.append((current, count))
    return runs

