        else:
            n = int(input[ptr+1])
            ptr +=2
            events.append((t, n, s))

    for ev in events:
        t, n, s = ev
        L = len(s)
        if n < L:
            print(0)
            continue
        # Compute KMP failure function
        fail = [0]*L
        for i in range(1, L):
            j = fail[i-1]
            while j >0 and s[i] != s[j]:
                j = fail[j-1]
            if s[i] == s[j]:
                j +=1
            fail[i] = j
        # Precompute transitions for each state j
        transitions = [{} for _ in range(L+1)]
        for j in range(L):
            for c in range(26):
                char = chr(ord('a') + c)
                if char == s[j]:
                    k = j+1
                    if k not in transitions[j]:
                        transitions[j][k] =0
                    transitions[j][k] +=1
                else:
                    current = j
                    while True:
                        if current ==0:
                            if s[0] == char:
                                k =1
                            else:
                                k =0
                            break
                        current = fail[current-1]
                        if s[current] == char:
                            k = current+1
                            break
                        elif current ==0:
                            if s[0] == char:
                                k =1
                            else:
                                k =0
                            break
                    if k not in transitions[j]:
                        transitions[j][k] =0
                    transitions[j][k] +=1
        # For state L, all transitions stay in L
        transitions[L][L] =26

        # Now compute dp[n] using matrix exponentiation
        # states 0..L
        # Initialize dp[0] = 1
        from collections import defaultdict

        def multiply_vec(vec, trans):
            new_vec = defaultdict(int)
            for j in vec:
                cnt = vec[j]
                for k in trans[j]:
                    new_vec[k] = (new_vec[k] + cnt * trans[j][k]) % MOD
            return new_vec

        def matrix_pow(vec, trans, power):
            result = vec.copy()
            while power >0:
                if power %2 ==1:
                    result = multiply_vec(result, trans)
                trans = multiply_trans(trans, trans)
                power //=2
            return result

        def multiply_trans(a, b):
            new_trans = [defaultdict(int) for _ in range(L+1)]
            for j in range(L+1):
                for k in a[j]:
                    cnt = a[j][k]
                    for l in b[k]:
                        new_trans[j][l] = (new_trans[j][l] + cnt * b[k][l]) % MOD
            return new_trans

        # Initial vector: state 0 has count 1
        vec = defaultdict(int)
        vec[0] =1
        # Compute transitions for each step
        trans = [defaultdict(int) for _ in range(L+1)]
        for j in range(L+1):
            for k in transitions[j]:
                trans[j][k] = transitions[j][k]
        # Exponentiate to n steps
        final_vec = matrix_pow(vec, trans, n)
        forbidden =0
        for j in range(L):
            forbidden = (forbidden + final_vec.get(j,0)) % MOD
        total = pow(26, n, MOD)
        ans = (total - forbidden) % MOD
        print(ans)

