from collections import deque

def main():
    N, M = map(int, sys.stdin.readline().split())
    original_adj = [set() for _ in range(N + 1)]
    for _ in range(M):
        a, b = map(int, sys.stdin.readline().split())
        original_adj[a].add(b)
        original_adj[b].add(a)

    # Build complement adjacency list
    complement_adj = [set() for _ in range(N + 1)]
    for u in range(1, N + 1):
        for v in range(1, N + 1):
            if u != v and v not in original_adj[u]:
                complement_adj[u].add(v)

    # Check if complement graph is bipartite and get components
    visited = [False] * (N + 1)
    color = [-1] * (N + 1)
    components = []
    is_bipartite = True

    for u in range(1, N + 1):
        if not visited[u]:
            q = deque()
            q.append(u)
            visited[u] = True
            color[u] = 0
            cnt = [0, 0]
            cnt[0] += 1
            while q:
                current = q.popleft()
                for neighbor in complement_adj[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        color[neighbor] = 1 - color[current]
                        cnt[color[neighbor]] += 1
                        q.append(neighbor)
                    else:
                        if color[neighbor] == color[current]:
                            is_bipartite = False
                            break
                if not is_bipartite:
                    break
            if not is_bipartite:
                break
            components.append((cnt[0], cnt[1]))

    if not is_bipartite:
        print(-1)
        return

    # Dynamic programming to find minimal sum
    dp = [False] * (N + 1)
    dp[0] = True
    for a, b in components:
        new_dp = [False] * (N + 1)
        for s in range(N + 1):
            if dp[s]:
                if s + a <= N:
                    new_dp[s + a] = True
                if s + b <= N:
                    new_dp[s + b] = True
        dp = new_dp

    min_ans = float('inf')
    for s in range(N + 1):
        if dp[s]:
            current = (s * (s - 1) // 2) + ((N - s) * (N - s - 1) // 2)
            if current < min_ans:
                min_ans = current

    print(min_ans if min_ans != float('inf') else -1)

