import sys
from functools import lru_cache

def main():
    sys.setrecursionlimit(1000000)

    def generate_splits(stones):
        n = len(stones)
        splits = []
        for mask in range(1, (1 << n) - 1):
            left = []
            right = []
            for i in range(n):
                if mask & (1 << i):
                    left.append(stones[i])
                else:
                    right.append(stones[i])
            splits.append((tuple(sorted(left)), tuple(sorted(right))))
        return splits

    @lru_cache(maxsize=None)
    def compute_mobiles(stones):
        stones = tuple(sorted(stones))
        if len(stones) == 1:
            return [(stones[0], 0.0, 0.0)]
        splits = generate_splits(stones)
        mobiles = []
        for left_stones, right_stones in splits:
            left_mobiles = compute_mobiles(left_stones)
            right_mobiles = compute_mobiles(right_stones)
            for lm in left_mobiles:
                for rm in right_mobiles:
                    total_weight = lm[0] + rm[0]
                    a = rm[0] / total_weight
                    left_width = a + lm[1]
                    right_width = (1.0 - a) + rm[2]
                    mobiles.append((total_weight, left_width, right_width))
        return mobiles

    T = int(sys.stdin.readline())
    for _ in range(T):
        r = float(sys.stdin.readline().strip())
        s = int(sys.stdin.readline())
        stones = [int(sys.stdin.readline()) for _ in range(s)]
        stones_tuple = tuple(sorted(stones))
        possible_mobiles = compute_mobiles(stones_tuple)
        max_width = -1.0
        for mobile in possible_mobiles:
            width = mobile[1] + mobile[2]
            if width < r and width > max_width:
                max_width = width
        if max_width < 0:
            print(-1)
        else:
            print("{0:.15f}".format(max_width).rstrip('0').rstrip('.') if '.' in "{0:.15f}".format(max_width) else "{0:.15f}".format(max_width))

