import sys

def compute_d0(N):
    X = N + 1
    if (X & (X - 1)) == 0:
        return X.bit_length() - 1
    else:
        return X.bit_length()

def is_enough(d, E, N):
    total = 0
    for k in range(1, E + 1):
        if k > d:
            continue
        comb = 1
        overflow = False
        for i in range(1, k + 1):
            comb *= (d - i + 1)
            comb //= i
            if comb > N:
                overflow = True
                break
        if overflow:
            return True
        total += comb
        if total >= N:
            return True
    return total >= N

def find_min_d(N, E):
    low = 1
    high = 1
    while not is_enough(high, E, N):
        high *= 2
    while low < high:
        mid = (low + high) // 2
        if is_enough(mid, E, N):
            high = mid
        else:
            low = mid + 1
    return high

