MOD = 10**9 + 7

def compute_comb_mod(n, k, mod):
    if k < 0 or k > n:
        return 0
    result = 1
    for i in range(k):
        result = result * (n - i) % mod
    for i in range(1, k + 1):
        result = result * pow(i, mod - 2, mod) % mod
    return result

def compute_c(m):
    s = list(map(int, str(m)))
    n = len(s)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(pos, tight, leading_zero, cnt):
        if pos == n:
            return {cnt: 1} if not leading_zero else {}
        upper = s[pos] if tight else 9
        result = {}
        for d in range(0, upper + 1):
            new_tight = tight and (d == upper)
            new_leading_zero = leading_zero and (d == 0)
            new_cnt = cnt
            if not new_leading_zero and d in (4, 7):
                new_cnt += 1
            next_state = dfs(pos + 1, new_tight, new_leading_zero, new_cnt)
            for k in next_state:
                result[k] = result.get(k, 0) + next_state[k]
        return result

    counts = dfs(0, True, True, 0)
    return counts

def main():
    m = int(input())
    c = compute_c(m)
    max_k = max(c.keys()) if c else 0
    fact6 = 720  # 6! = 720

    ans = 0
    for l in c:
        if l == 0:
            continue
        c_prime = {}
        for k in c:
            if k == l:
                c_prime[k] = c[k] - 1
            else:
                c_prime[k] = c[k]
        dp = [[0] * l for _ in range(7)]
        dp[0][0] = 1
        for k in c_prime:
            current_count = c_prime[k]
            if current_count < 0:
                continue
            for t in range(0, min(current_count, 6) + 1):
                comb_t = compute_comb_mod(current_count, t, MOD)
                if comb_t == 0:
                    continue
                for s in range(6, t - 1, -1):
                    for sum_ in range(l - 1, k * t - 1, -1):
                        prev_s = s - t
                        prev_sum = sum_ - k * t
                        if prev_s >= 0 and prev_sum >= 0:
                            dp[s][sum_] = (dp[s][sum_] + dp[prev_s][prev_sum] * comb_t) % MOD
        total = sum(dp[6][:l]) % MOD
        ans = (ans + c[l] * total % MOD * fact6) % MOD
    print(ans % MOD)

