import sys
from collections import deque

def compute_region_distances(grid, n, m, region):
    dist = [[float('inf')] * m for _ in range(n)]
    q = deque()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == region:
                dist[i][j] = 0
                q.append((i, j))
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                cell = grid[ni][nj]
                if cell == '#':
                    continue
                new_cost = dist[i][j]
                if cell == '.':
                    new_cost += 1
                if new_cost < dist[ni][nj]:
                    dist[ni][nj] = new_cost
                    if cell == '.':
                        q.append((ni, nj))
                    else:
                        q.appendleft((ni, nj))
    return dist

def compute_pairwise_distance(grid, n, m, start_r, end_r):
    dist = [[float('inf')] * m for _ in range(n)]
    q = deque()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == start_r:
                dist[i][j] = 0
                q.append((i, j))
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    min_dist = float('inf')
    while q:
        i, j = q.popleft()
        if grid[i][j] == end_r:
            min_dist = dist[i][j]
            break
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                cell = grid[ni][nj]
                if cell == '#':
                    continue
                new_cost = dist[i][j]
                if cell == '.':
                    new_cost += 1
                if new_cost < dist[ni][nj]:
                    dist[ni][nj] = new_cost
                    if cell == '.':
                        q.append((ni, nj))
                    else:
                        q.appendleft((ni, nj))
    return min_dist

