from math import inf

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        C, D, W, X = map(int, line.strip().split())
        if C == 0 and D == 0 and W == 0 and X == 0:
            break
        E = []
        for _ in range(C):
            E.append(list(map(int, sys.stdin.readline().split())))
        F = []
        for _ in range(C):
            F.append(list(map(int, sys.stdin.readline().split())))

        precompute_day = []
        for j in range(D):
            intervals = []
            for i in range(C):
                if E[i][j] == 0:
                    continue
                sum_e = E[i][j]
                sum_f = F[i][j]
                intervals.append((sum_e, sum_f, 1))
                current_end = i
                for end in range(i + 1, C):
                    if E[end][j] == 0:
                        break
                    sum_e += E[end][j]
                    sum_f += F[end][j]
                    current_end = end
                    intervals.append((sum_e, sum_f, current_end - i + 1))
            intervals.append((0, 0, 0))
            precompute_day.append(intervals)

        prev_dp = [[-inf] * (W + 1) for _ in range(X + 1)]
        prev_dp[0][0] = 0

        for day in range(D):
            curr_dp = [[-inf] * (W + 1) for _ in range(X + 1)]
            for x_prev in range(X + 1):
                for w_prev in range(W + 1):
                    if prev_dp[x_prev][w_prev] == -inf:
                        continue
                    current_profit = prev_dp[x_prev][w_prev]
                    for sum_e, sum_f, length in precompute_day[day]:
                        new_w = w_prev + sum_f
                        if new_w > W:
                            continue
                        if length >= 2:
                            new_x = x_prev + 1
                            if new_x > X:
                                continue
                        else:
                            new_x = x_prev
                        if curr_dp[new_x][new_w] < current_profit + sum_e:
                            curr_dp[new_x][new_w] = current_profit + sum_e
            prev_dp = curr_dp

        max_profit = 0
        for x in range(X + 1):
            for w in range(W + 1):
                if prev_dp[x][w] > max_profit:
                    max_profit = prev_dp[x][w]
        print(max_profit)

