from collections import deque

def main():
    while True:
        line = sys.stdin.readline().strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) == 2 and parts[0] == '0' and parts[1] == '0':
            break
        N, C = map(int, parts)
        board = []
        for _ in range(N):
            while True:
                l = sys.stdin.readline().strip()
                if l:
                    break
            row = list(map(int, l.split()))
            board.append(row)
        max_score = -float('inf')
        # Iterate over all empty cells
        for r in range(N):
            for c in range(len(board[r])):
                if board[r][c] == 0:
                    # Create new board
                    new_board = [row.copy() for row in board]
                    new_board[r][c] = C
                    # Find all groups
                    visited = [[False for _ in row] for row in new_board]
                    groups = []
                    for i in range(N):
                        for j in range(len(new_board[i])):
                            if not visited[i][j] and new_board[i][j] != 0:
                                # BFS to find group
                                queue = deque()
                                queue.append((i, j))
                                visited[i][j] = True
                                group_num = new_board[i][j]
                                group_cells = [(i, j)]
                                while queue:
                                    x, y = queue.popleft()
                                    # Generate adjacent cells
                                    adj = []
                                    if x > 0:
                                        if y - 1 >= 0:
                                            adj.append((x-1, y-1))
                                        if y < len(new_board[x-1]):
                                            adj.append((x-1, y))
                                    if x < N - 1:
                                        if y < len(new_board[x+1]):
                                            adj.append((x+1, y))
                                        if y + 1 < len(new_board[x+1]):
                                            adj.append((x+1, y+1))
                                    if y > 0:
                                        adj.append((x, y-1))
                                    if y < len(new_board[x]) - 1:
                                        adj.append((x, y+1))
                                    # Check adjacents
                                    for (nx, ny) in adj:
                                        if not visited[nx][ny] and new_board[nx][ny] == group_num:
                                            visited[nx][ny] = True
                                            queue.append((nx, ny))
                                            group_cells.append((nx, ny))
                                groups.append((group_num, group_cells))
                    # Check each group for removal
                    gain = 0
                    loss = 0
                    for (num, cells) in groups:
                        has_empty = False
                        for (x, y) in cells:
                            # Generate adjacents for (x, y)
                            adj = []
                            if x > 0:
                                if y - 1 >= 0:
                                    adj.append((x-1, y-1))
                                if y < len(new_board[x-1]):
                                    adj.append((x-1, y))
                            if x < N - 1:
                                if y < len(new_board[x+1]):
                                    adj.append((x+1, y))
                                if y + 1 < len(new_board[x+1]):
                                    adj.append((x+1, y+1))
                            if y > 0:
                                adj.append((x, y-1))
                            if y < len(new_board[x]) - 1:
                                adj.append((x, y+1))
                            # Check any adjacent is 0
                            for (nx, ny) in adj:
                                if new_board[nx][ny] == 0:
                                    has_empty = True
                                    break
                            if has_empty:
                                break
                        if not has_empty:
                            if num == C:
                                loss += len(cells)
                            else:
                                gain += len(cells)
                    current_score = gain - loss
                    if current_score > max_score:
                        max_score = current_score
        print(max_score if max_score != -float('inf') else 0)

