        visited = set()
        q = deque()
        start_x, start_y = start
        q.append((start_x, start_y, 0, 0))
        visited.add((start_x, start_y, 0))
        answer = -1
        found = False
        while q and not found:
            x, y, mask, time = q.popleft()
