        t = int(input[idx]); idx +=1
        p = int(input[idx]); idx +=1
        adj[f].append((t, p))
        adj[t].append((f, p))

    xor = [0] * N
    parent = [-1] * N
    visited = [False] * N
    q = deque([0])
    visited[0] = True
    cycles = []

    while q:
        u = q.popleft()
        for v, p in adj[u]:
            if not visited[v]:
                visited[v] = True
                xor[v] = xor[u] ^ p
                parent[v] = u
                q.append(v)
            else:
                if parent[u] != v:
                    cycle_xor = xor[u] ^ p ^ xor[v]
                    cycles.append(cycle_xor)

    class LinearBasis:
        def __init__(self):
            self.basis = [0] * 60

        def insert(self, x):
            for i in reversed(range(60)):
                if (x >> i) & 1:
                    if self.basis[i] == 0:
                        self.basis[i] = x
                        break
                    else:
                        x ^= self.basis[i]

        def max_xor(self, x):
            res = x
            for i in reversed(range(60)):
                res = max(res, res ^ self.basis[i])
            return res

    lb = LinearBasis()
    for num in cycles:
        lb.insert(num)

    output = []
    for _ in range(Q):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        res = xor[a] ^ xor[b]
        output.append(lb.max_xor(res))

    print('\n'.join(map(str, output)))

