import math

def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    d = [x - 1 for x in a]

    g = 0
    for num in d:
        g = math.gcd(g, num)

    # Compute h by removing all factors of 2 from g
    h = g
    while h % 2 == 0:
        h //= 2

    # Function to generate all divisors of h
    def get_divisors(h_val):
        if h_val == 0:
            return []
        factors = {}
        temp = h_val
        # Factorize h_val
        i = 3
        while i * i <= temp:
            while temp % i == 0:
                factors[i] = factors.get(i, 0) + 1
                temp //= i
            i += 2
        if temp > 1:
            factors[temp] = 1

        divisors = [1]
        for prime, exp in factors.items():
            current_length = len(divisors)
            prime_pows = [prime**e for e in range(1, exp + 1)]
            for pow_val in prime_pows:
                for j in range(current_length):
                    divisors.append(divisors[j] * pow_val)
        return divisors

    divisors = get_divisors(h)

    ans = 0
    for s in divisors:
        current = s
        while current <= m - 1:
            ans += (m - current)
            current *= 2

    print(ans)

solve()

