import sys

def sieve(max_n):
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def get_primes(n, spf):
    primes = set()
    while n > 1:
        p = spf[n]
        primes.add(p)
        while n % p == 0:
            n //= p
    return primes

class UnionFind:
    def __init__(self, primes):
        self.parent = {}
        for p in primes:
            self.parent[p] = p

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]  # Path compression
            x = self.parent[x]
        return x

    def union(self, x, y):
        fx = self.find(x)
        fy = self.find(y)
        if fx != fy:
            self.parent[fy] = fx

