import sys
from itertools import permutations

def parse_expression(s):
    tokens = []
    current_number = []
    for c in s:
        if c in '+-*/=':
            if not current_number:
                return None, "Operator with no preceding number"
            num = ''.join(current_number)
            if len(num) > 1 and num[0] == '0':
                return None, "Leading zero"
            tokens.append(num)
            current_number = []
            tokens.append(c)
        else:
            current_number.append(c)
    if current_number:
        num = ''.join(current_number)
        if len(num) > 1 and num[0] == '0':
            return None, "Leading zero"
        tokens.append(num)
    if not tokens:
        return None, "Empty expression"
    if len(tokens) % 2 == 0:
        return None, "Expression ends with operator"
    for i in range(len(tokens)):
        if i % 2 == 0:
            if not tokens[i].isdigit():
                return None, "Non-digit in number"
            num = tokens[i]
            if len(num) > 1 and num[0] == '0':
                return None, "Leading zero"
        else:
            if tokens[i] not in '+-*/':
                return None, "Invalid operator"
    return tokens, None

def evaluate(tokens):
    tokens = tokens.copy()
    i = 0
    while i < len(tokens):
        if tokens[i] in '*/':
            op = tokens[i]
            left = int(tokens[i-1])
            right = int(tokens[i+1])
            if op == '/':
                if right == 0:
                    return None, "Division by zero"
                if left % right != 0:
                    return None, "Non-integer division"
                res = left // right
            else:
                res = left * right
            tokens = tokens[:i-1] + [str(res)] + tokens[i+2:]
            i = i-1
        else:
            i += 1
    i = 0
    while i < len(tokens):
        if tokens[i] in '+-':
            op = tokens[i]
            left = int(tokens[i-1])
            right = int(tokens[i+1])
            if op == '+':
                res = left + right
            else:
                res = left - right
            tokens = tokens[:i-1] + [str(res)] + tokens[i+2:]
            i = i-1
        else:
            i += 1
    if len(tokens) != 1:
        return None, "Invalid evaluation"
    return int(tokens[0]), None

