import math
import heapq

def readints():
    return list(map(int, input().split()))

def distance(p1, p2):
    return math.hypot(p1[0]-p2[0], p1[1]-p2[1])

def dijkstra(graph, start, end):
    heap = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    visited = set()
    while heap:
        current_dist, u = heapq.heappop(heap)
        if u in visited:
            continue
        if u == end:
            return current_dist
        visited.add(u)
        for v in graph[u]:
            if distances[v] > current_dist + graph[u][v]:
                distances[v] = current_dist + graph[u][v]
                heapq.heappush(heap, (distances[v], v))
    return distances[end]

def main():
    while True:
        m, n = readints()
        if m == 0 and n == 0:
            break
        points = []
        for _ in range(m + n):
            x, y = readints()
            points.append((x, y))
        start = points[0]
        end = points[m-1]
        pins = points[m:]
        nodes = [start, end] + pins
        graph = {node: {} for node in nodes}
        for i in range(len(nodes)):
            for j in range(i+1, len(nodes)):
                dist = distance(nodes[i], nodes[j])
                graph[nodes[i]][nodes[j]] = dist
                graph[nodes[j]][nodes[i]] = dist
        shortest = dijkstra(graph, start, end)
        print("{0:.10f}".format(shortest))

