def resolve_members(group_name, groups, memo):
    if group_name in memo:
        return memo[group_name]

    members = groups[group_name]
    employees = set()

    for member in members:
        if member in groups:
            sub_employees = resolve_members(member, groups, memo)
            employees.update(sub_employees)
        else:
            employees.add(member)

    memo[group_name] = employees
    return employees

