def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # Precompute previous greater or equal using monotonic stack
    L = [-1] * n
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            L[i] = stack[-1]
        else:
            L[i] = -1
        stack.append(i)

    # Precompute next greater using monotonic stack
    R = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and a[stack[-1]] <= a[i]:
            stack.pop()
        if stack:
            R[i] = stack[-1]
        else:
            R[i] = n
        stack.append(i)

    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i+1] = prefix_sum[i] + a[i]

    count = 0
    for i in range(n):
        m = a[i]
        if m > n:
            continue
        s_start = max(L[i] + 1, i - m + 1)
        s_end = min(i, R[i] - m)
        if s_start > s_end:
            continue
        for s in range(s_start, s_end + 1):
            e = s + m - 1
            if e >= n:
                continue
            current_sum = prefix_sum[e+1] - prefix_sum[s]
            if current_sum == m * (m + 1) // 2:
                count += 1
    print(count)

