    factor_counts = get_prime_factors(s)
    divisors = generate_divisors(factor_counts)
    valid_pairs = []
    divisor_set = set(divisors)
    for d in divisors:
        if (d + 1) in divisor_set:
            n = d
            denominator = n * (n + 1)
            if denominator == 0:
                continue
            if s % denominator != 0:
                continue
            temp = s // denominator
            m_num = temp + n - 1
            if m_num % 3 != 0:
                continue
            m = m_num // 3
            if m >= n:
                valid_pairs.append((n, m))
    all_pairs = []
    for (a, b) in valid_pairs:
        if a == b:
            all_pairs.append((a, b))
        else:
            all_pairs.append((a, b))
            all_pairs.append((b, a))
    all_pairs.sort()
    unique_pairs = []
