import heapq

def dijkstra(n, adj, s, t):
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    heap = [(0, s)]
    prev = [-1] * n
    while heap:
        d, u = heapq.heappop(heap)
        if u == t:
            break
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > d + w:
                dist[v] = d + w
                prev[v] = u
                heapq.heappush(heap, (dist[v], v))
    return dist[t], prev

