        for j in range(M):
            A, B = map(int, sys.stdin.readline().split())
            roads.append((A, B))
            adj[A].append((B, j))  # j is road index (0-based)

        # Compute original distance
        def original_bfs():
            visited = [float('inf')] * (N + 1)
            q = deque([S])
            visited[S] = 0
            while q:
                u = q.popleft()
                for (v, j) in adj[u]:
                    if visited[v] > visited[u] + 1:
                        visited[v] = visited[u] + 1
                        q.append(v)
            return visited[T]

        original_dist = original_bfs()
        best_dist = original_dist
        best_road = 0

        # Check each road reversal
        for road_idx in range(M):
            A_i, B_i = roads[road_idx]
            visited = [float('inf')] * (N + 1)
            q = deque([S])
            visited[S] = 0
            while q:
                u = q.popleft()
                current_dist = visited[u]
                # Process original edges excluding the current road
                for (v, j) in adj[u]:
                    if j != road_idx:
                        if visited[v] > current_dist + 1:
                            visited[v] = current_dist + 1
                            q.append(v)
                # Process reversed edge if applicable
                if u == B_i:
                    v = A_i
                    if visited[v] > current_dist + 1:
                        visited[v] = current_dist + 1
                        q.append(v)
            new_dist = visited[T]
            # Update best_dist and best_road
            if new_dist < best_dist:
                best_dist = new_dist
                best_road = road_idx + 1  # convert to 1-based
            elif new_dist == best_dist:
