from itertools import product

def generate_good_integers(n):
    good = []
    digits = ['2', '8']
    max_length = len(str(n)) if n > 0 else 1  # handle n=0 which is not in input
    for length in range(1, max_length + 1):
        for num_tuple in product(digits, repeat=length):
            num_str = ''.join(num_tuple)
            num = int(num_str)
            if num <= n:
                good.append(num)
    good = sorted(list(set(good)))  # remove duplicates and sort
    return good

def solve(n):
    if n == 1:
        return -1
    good_ints = generate_good_integers(n)
    if not good_ints:
        return -1
    memo = {}

    def dfs(n):
        if n in memo:
            return memo[n]
        if n == 1:
            return 0
        max_count = -1
        for g in good_ints:
            if g > n:
                break
            if g == 1:
                continue
            if n % g == 0:
                quotient = n // g
                cnt = dfs(quotient)
                if cnt != -1:
                    current = 1 + cnt
                    if current > max_count:
                        max_count = current
        memo[n] = max_count
        return max_count

    result = dfs(n)
    return result if result != -1 else -1

