def calculate(x, k):
    if x < 0:
        return 0
    s = str(x)
    digits = list(map(int, s))
    n = len(digits)

    pow10_remain = [pow(10, (n - 1 - pos), MOD) for pos in range(n)]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, mask, is_tight, started):
        if pos == n:
            if not started:
                final_mask = 1 << 0
            else:
                final_mask = mask
            if bin(final_mask).count('1') <= k:
                return (1, 0)
            else:
                return (0, 0)
        res_count = 0
        res_sum = 0
        max_d = digits[pos] if is_tight else 9
        for d in range(0, max_d + 1):
            new_is_tight = is_tight and (d == max_d)
            new_started = started or (d != 0)
            new_mask = mask
            if new_started:
                new_mask |= 1 << d

            cnt, sm = dp(pos + 1, new_mask, new_is_tight, new_started)
            res_count = (res_count + cnt) % MOD

            if new_started:
                contribution = (d * pow10_remain[pos] % MOD) * cnt % MOD
                contribution = (contribution + sm) % MOD
            else:
                contribution = sm % MOD

            res_sum = (res_sum + contribution) % MOD

        return (res_count, res_sum)

    cnt, sm = dp(0, 0, True, False)
    return sm % MOD

