from collections import deque, defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    # Precompute distances for each node
    distance = [[-1]*(n+1) for _ in range(n+1)]
    for u in range(1, n+1):
        q = deque()
        q.append(u)
        dist = [-1] * (n+1)
        dist[u] = 0
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[current] + 1
                    q.append(neighbor)
        for i in range(1, n+1):
            distance[u][i] = dist[i]

    max_prob = 0.0
    for u in range(1, n+1):
        for v in range(1, n+1):
            prob = 0.0
            # Add cases where s == u (d1=0)
            prob += 1.0 / n
            group = defaultdict(lambda: defaultdict(float))
            for s in range(1, n+1):
                d1 = distance[u][s]
                if d1 == 0:
                    continue
                degree_s = len(adj[s])
                if degree_s == 0:
                    continue
                for t in adj[s]:
                    d2 = distance[v][t]
                    contribution = 1.0 / (n * degree_s)
                    group_key = (d1, d2)
                    group[group_key][t] += contribution
            # Sum the maximum contributions for each group
            for key in group:
                t_dict = group[key]
                max_t = max(t_dict.values())
                prob += max_t
            if prob > max_prob:
                max_prob = prob
    print("{0:.12f}".format(max_prob))

