        else:
            parent[v] = u
            children[u].append(v)

    subtree_size = [1] * (n + 1)

    def dfs(u):
        for v in children[u]:
            dfs(v)
            subtree_size[u] += subtree_size[v]

    dfs(root)

    for v in range(1, n + 1):
        if v == root:
            sizes = [subtree_size[child] for child in children[v]]
        else:
            parent_part = n - subtree_size[v]
            child_sizes = [subtree_size[child] for child in children[v]]
            sizes = [parent_part] + child_sizes

        if not sizes:
            print(0)
            continue

        M = max(sizes)
        others = [s for s in sizes if s < M]

        if not others:
            # All are M, so split one M into two parts and attach to another M
            minimal_new_max = M // 2 if M % 2 == 0 else (M + 1) // 2
        else:
