import math

def compute_inradius(p1, p2, p3):
    a = math.hypot(p2[0] - p3[0], p2[1] - p3[1])
    b = math.hypot(p1[0] - p3[0], p1[1] - p3[1])
    c = math.hypot(p1[0] - p2[0], p1[1] - p2[1])
    s = (a + b + c) / 2.0
    area = 0.5 * abs( (p2[0] - p1[0])*(p3[1] - p1[1]) - (p2[1] - p1[1])*(p3[0] - p1[0]) )
    return area / s if s != 0 else 0.0

def distance(p1, p2):
    return math.hypot(p1[0]-p2[0], p1[1]-p2[1])

def line_intersection(line1, line2):
    a1, b1, c1 = line1
    a2, b2, c2 = line2
    denom = a1 * b2 - a2 * b1
    if denom == 0:
        return None
    x = (b1 * c2 - b2 * c1) / denom
    y = (a2 * c1 - a1 * c2) / denom
    return (x, y)

def is_possible(r, p1, p2, p3):
    def get_offset_line(pa, pb, pc):
        a = pb[1] - pa[1]
        b = pa[0] - pb[0]
        c = pb[0] * pa[1] - pa[0] * pb[1]
        s = a * pc[0] + b * pc[1] + c
        D = math.hypot(a, b)
        if D == 0:
            return None
        new_c = c - r * D if s > 0 else c + r * D
        return (a, b, new_c)

    lines = []
    line_ab = get_offset_line(p1, p2, p3)
    line_bc = get_offset_line(p2, p3, p1)
    line_ca = get_offset_line(p3, p1, p2)

    if None in (line_ab, line_bc, line_ca):
        return False

    points = []
    for l1, l2 in [(line_ab, line_bc), (line_bc, line_ca), (line_ca, line_ab)]:
        pt = line_intersection(l1, l2)
        if not pt:
            return False
        points.append(pt)

    max_dist = 0.0
    for i in range(3):
        for j in range(i+1, 3):
            max_dist = max(max_dist, distance(points[i], points[j]))
    return max_dist >= 2 * r - 1e-12

