def multiply(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k]:
                for j in range(n):
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % mod
    return res

def matrix_power(mat, power, mod):
    n = len(mat)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    current_mat = mat
    while power > 0:
        if power % 2 == 1:
            result = multiply(result, current_mat, mod)
        current_mat = multiply(current_mat, current_mat, mod)
        power = power // 2
    return result

def multiply_matrix_vector(mat, vec, mod):
    n = len(vec)
    res = [0] * n
    for i in range(n):
        s = 0
        for j in range(n):
            s = (s + mat[i][j] * vec[j]) % mod
        res[i] = s % mod
    return res

