def previous_day(y, m, d):
    if d > 1:
        return (y, m, d - 1)
    if m == 1:
        return (y - 1, 12, 31)
    else:
        prev_m = m - 1
        if prev_m in (1, 3, 5, 7, 8, 10, 12):
            prev_d = 31
        elif prev_m in (4, 6, 9, 11):
            prev_d = 30
        else:
            prev_d = 29 if is_leap(y) else 28
        return (y, prev_m, prev_d)

def count_friday_13_up_to(Y, M, D):
    if Y < 0:
        return 0
    full_cycles = Y // 400
    rem_year = Y % 400
    count = full_cycles * C
    start_cycle = Y - rem_year
    for (y_off, m_actual) in precompute_list:
        actual_year = start_cycle + y_off
        if actual_year < 0 or actual_year > Y:
            continue
        if actual_year < Y:
            count += 1
        else:
            if m_actual < M:
                count += 1
            elif m_actual == M and 13 <= D:
                count += 1
    return count

