import sys
from collections import deque, defaultdict
from sys import stdin

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    edges = []
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)
        edges.append((a, b))

    # Tarjan's algorithm to find bridges
    disc = [0] * (n+1)
    low = [0] * (n+1)
    time = 1
    bridges = set()
    visited = [False] * (n+1)
    parent = [0] * (n+1)

    for u in range(1, n+1):
        if not visited[u]:
            stack = [(u, -1, False)]
            while stack:
                node, p, processed = stack.pop()
                if not processed:
                    if visited[node]:
                        continue
                    visited[node] = True
                    disc[node] = time
                    low[node] = time
                    time += 1
                    parent[node] = p
                    # Re-add as processed and push children
                    stack.append((node, p, True))
                    # Push children in reverse order to process in order
                    children = []
                    for v in adj[node]:
                        if v == p:
                            continue
                        if not visited[v]:
                            children.append(v)
                        else:
                            low[node] = min(low[node], disc[v])
                    for v in reversed(children):
                        stack.append((v, node, False))
                else:
                    for v in adj[node]:
                        if v != p and parent[v] == node:
                            low[node] = min(low[node], low[v])
                            if low[v] > disc[node]:
                                bridges.add(frozenset((node, v)))
                    if p != -1:
                        low[p] = min(low[p], low[node])

    # Build DSU
    class DSU:
        def __init__(self, size):
            self.parent = list(range(size +1))
            self.rank = [1]*(size +1)

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            x_root = self.find(x)
            y_root = self.find(y)
            if x_root == y_root:
                return
            if self.rank[x_root] < self.rank[y_root]:
                self.parent[x_root] = y_root
                self.rank[y_root] += self.rank[x_root]
            else:
                self.parent[y_root] = x_root
                self.rank[x_root] += self.rank[y_root]

    dsu = DSU(n)
    for a, b in edges:
        if frozenset((a, b)) not in bridges:
            dsu.union(a, b)

    # Build bridge tree
    bridge_edges = []
    for bridge in bridges:
        a, b = tuple(bridge)
        ra = dsu.find(a)
        rb = dsu.find(b)
        bridge_edges.append((ra, rb))

    # Check if all in one component
    unique_roots = set(dsu.find(u) for u in range(1, n+1))
    if len(unique_roots) == 1:
        k = int(sys.stdin.readline())
        for _ in range(k):
            sys.stdin.readline()
            print(0)
        return

    # Build adjacency list for bridge tree
    bridge_adj = defaultdict(list)
    for a, b in bridge_edges:
        bridge_adj[a].append(b)
        bridge_adj[b].append(a)

    # BFS to compute depth and parent
    root = next(iter(unique_roots))
    depth = [0]*(n+1)
    parent_lca = [-1]*(n+1)
    q = deque([root])
    depth[root] = 0
    parent_lca[root] = -1
    while q:
        u = q.popleft()
        for v in bridge_adj[u]:
            if depth[v] == 0 and v != root:
                depth[v] = depth[u] + 1
                parent_lca[v] = u
                q.append(v)

    # Preprocess binary lifting for LCA
    max_level = 20
    up = [[-1]*(n+1) for _ in range(max_level)]
    for v in unique_roots:
        up[0][v] = parent_lca[v]
    for k in range(1, max_level):
        for v in unique_roots:
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
            else:
                up[k][v] = -1

    # LCA function
    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to the depth of v
        for k in range(max_level-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(max_level-1, -1, -1):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Process queries
    k = int(sys.stdin.readline())
    for _ in range(k):
        s, l = map(int, sys.stdin.readline().split())
        s_root = dsu.find(s)
        l_root = dsu.find(l)
        if s_root == l_root:
            print(0)
            continue
        lca_node = get_lca(s_root, l_root)
        distance = depth[s_root] + depth[l_root] - 2 * depth[lca_node]
        print(distance)

