def minimal_change(amount):
    coins = [500, 100, 50, 10, 5, 1]
    count = 0
    for coin in coins:
        if amount == 0:
            break
        if coin > amount:
            continue
        num = amount // coin
        count += num
        amount -= num * coin
    return count

