import math
from itertools import product

def reflect_point(point, mirror):
    x, y = point
    (px, py), (qx, qy) = mirror
    dx, dy = qx - px, qy - py
    if dx == 0 and dy == 0:
        return (x, y)
    vpx, vpy = x - px, y - py
    t = (vpx * dx + vpy * dy) / (dx**2 + dy**2)
    proj_x = px + t * dx
    proj_y = py + t * dy
    return (2 * proj_x - x, 2 * proj_y - y)

def compute_intersection(line_start, line_end, mirror):
    (x1, y1), (x2, y2) = line_start, line_end
    (px, py), (qx, qy) = mirror
    a, c = x2 - x1, y2 - y1
    b, d = -(qx - px), -(qy - py)
    e, f = px - x1, py - y1
    det = a * d - b * c
    if det == 0:
        return None
    t = (d * e - b * f) / det
    s = (a * f - c * e) / det
    if 0 <= t <= 1 and 0 <= s <= 1:
        mirror_len = math.hypot(qx - px, qy - py)
        if mirror_len < 1e-9:
            return None
        if s * mirror_len < 0.001 or (1 - s) * mirror_len < 0.001:
            return None
        ix = x1 + t * (x2 - x1)
        iy = y1 + t * (y2 - y1)
        return (t, (ix, iy))
    return None

def solve():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    while True:
        n = int(input[idx])
        idx += 1
        if n == 0:
            break
        mirrors = []
        for _ in range(n):
            px, py, qx, qy = map(int, input[idx:idx+4])
            mirrors.append(((px, py), (qx, qy)))
            idx += 4
        tx, ty = int(input[idx]), int(input[idx+1])
        idx += 2
        lx, ly = int(input[idx]), int(input[idx+1])
        idx += 2

        min_dist = float('inf')
        for k in range(0, 6):
            for seq in product(range(n), repeat=k):
                mirrored_point = (tx, ty)
                for m_idx in seq:
                    mirrored_point = reflect_point(mirrored_point, mirrors[m_idx])
                valid = True
                current_line_start = (lx, ly)
                for m_idx in reversed(seq):
                    mirror = mirrors[m_idx]
                    intersection = compute_intersection(current_line_start, mirrored_point, mirror)
                    if not intersection:
                        valid = False
                        break
                    t, pt = intersection
                    if t <= 0:
                        valid = False
                        break
                    current_line_start = pt
                if not valid:
                    continue
                if k == 0:
                    for mirror in mirrors:
                        if compute_intersection((lx, ly), (tx, ty), mirror):
                            valid = False
                            break
                if valid:
                    dist = math.hypot(mirrored_point[0] - lx, mirrored_point[1] - ly)
                    if dist < min_dist:
                        min_dist = dist
        print("{0:.14f}".format(min_dist))

