import heapq

def main():
    while True:
        n, m, c = map(int, input().split())
        if n == 0 and m == 0 and c == 0:
            break
        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            f, t, cost = map(int, input().split())
            adj[f].append((t, cost))

        heap = []
        heapq.heappush(heap, (0, 0, 0, 1))  # (k, -sum_edges, sum_total, node)
        best = {}
        answer = -1
        found = False

        while heap and not found:
            k, neg_se, sum_total, u = heapq.heappop(heap)
            sum_edges = -neg_se

            if u == n:
                required_reduction = sum_total - c
                if sum_edges >= required_reduction:
                    answer = k
                    found = True
                continue

            key = (u, k)
            if key in best:
                existing_se, existing_st = best[key]
                if sum_edges <= existing_se and sum_total >= existing_st:
                    continue
            best[key] = (sum_edges, sum_total)

            for v, e in adj[u]:
                # Case 1: do not modify this edge
                new_k = k
                new_se = sum_edges
                new_st = sum_total + e
                new_neg_se = -new_se
                new_key = (v, new_k)

                proceed = False
                if new_key not in best:
                    proceed = True
                else:
                    existing_se, existing_st = best[new_key]
                    if new_se > existing_se or (new_se == existing_se and new_st < existing_st):
                        proceed = True
                if proceed:
                    heapq.heappush(heap, (new_k, new_neg_se, new_st, v))
                    best[new_key] = (new_se, new_st)

                # Case 2: modify this edge
                new_k = k + 1
                new_se = sum_edges + e
                new_st = sum_total + e
                new_neg_se = -new_se
                new_key = (v, new_k)

                proceed = False
                if new_key not in best:
                    proceed = True
                else:
                    existing_se, existing_st = best[new_key]
                    if new_se > existing_se or (new_se == existing_se and new_st < existing_st):
                        proceed = True
                if proceed:
                    heapq.heappush(heap, (new_k, new_neg_se, new_st, v))
                    best[new_key] = (new_se, new_st)

        print(answer)

