def compute_allowed_minute(weekday, time):
    allowed = [False] * 10080
    for m in range(10080):
        day = (m // 1440) % 7
        time_in_day = m % 1440

        # Check day
        if weekday == 'All':
            day_ok = True
        else:
            target_day = day_map.get(weekday, 0)  # default to Sun if not found (shouldn't happen)
            day_ok = (day == target_day)

        # Check time
        if time == 'All':
            time_ok = True
        elif time == 'Day':
            time_ok = 360 <= time_in_day < 1080
        elif time == 'Night':
            time_ok = time_in_day < 360 or time_in_day >= 1080
        else:
            time_ok = False

        allowed[m] = day_ok and time_ok
    return allowed

