    for L in range(2, M + 1):
        forbidden = set()
        for s in S:
            if len(s) >= L:
                for i in range(len(s) - L + 1):
                    substr = s[i:i+L]
                    forbidden.add(substr)
        required = 26 ** L
        if len(forbidden) < required:
            if L <= 5:
                # Generate all possible strings in lex order
                for tpl in product('abcdefghijklmnopqrstuvwxyz', repeat=L):
                    candidate = ''.join(tpl)
                    if candidate not in forbidden:
                        print(candidate)
                        return
            else:
                # Try 'a' * L
                candidate = 'a' * L
                if candidate not in forbidden:
                    print(candidate)
                    return
                # Try next possible candidates
                next_candidates = [
                    'a'*(L-1) + 'b',
                    'a'*(L-2) + 'ba',
                    'a'*(L-3) + 'bba'
                ]
                for cand in next_candidates:
                    if cand not in forbidden:
                        print(cand)
                        return
                # Fallback to 'a' * L (even if in forbidden, but this is incorrect)
                print(candidate)
                return

