def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    idx += 1
    q = int(input[idx])
    idx += 1

    parent = list(range(n))
    rank = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # Path compression
            x = parent[x]
        return x

    def unite(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return
        # Union by rank
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1

    output = []
    for _ in range(q):
        com = int(input[idx])
        x = int(input[idx+1])
        y = int(input[idx+2])
        idx += 3
        if com == 0:
            unite(x, y)
        else:
            if find(x) == find(y):
                output.append('1')
            else:
                output.append('0')
    print('\n'.join(output))

