import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        if u > v:
            u, v = v, u
        edges.append((u, v))

    current_edges = list(edges)

    def is_connected(edges_list):
        if not edges_list:
            return False
        adj = defaultdict(list)
        nodes = set()
        for u, v in edges_list:
            adj[u].append(v)
            adj[v].append(u)
            nodes.add(u)
            nodes.add(v)
        if not nodes:
            return True
        start = next(iter(nodes))
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            for neighbor in adj[node]:
                if neighbor not in visited:
                    stack.append(neighbor)
        return len(visited) == len(nodes)

    def find_bridges(edges_list):
        adj = defaultdict(list)
        for u, v in edges_list:
            adj[u].append(v)
            adj[v].append(u)
        visited = set()
        disc = {}
        low = {}
        bridges = set()
        time = 0
        parent = {}

        def dfs(u):
            nonlocal time
            visited.add(u)
            disc[u] = low[u] = time
            time += 1
            for v in adj[u]:
                if v not in visited:
                    parent[v] = u
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        a, b = sorted((u, v))
                        bridges.add((a, b))
                elif v != parent.get(u, None):
                    low[u] = min(low[u], disc[v])

        for node in adj:
            if node not in visited:
                dfs(node)
        return bridges

    def is_2_edge_connected(edges_list):
        if not edges_list:
            return False
        if not is_connected(edges_list):
            return False
        return len(find_bridges(edges_list)) == 0

    edges_removed = True
    while edges_removed:
        edges_removed = False
        for edge in reversed(edges):
            if edge not in current_edges:
                continue
            temp = list(current_edges)
            temp.remove(edge)
            if is_2_edge_connected(temp):
                current_edges = temp
                edges_removed = True

    print(len(current_edges))
    for u, v in current_edges:
        print(u, v)

