import itertools

def ccw(a, b, c):
    val = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    return 1 if val > 0 else -1 if val < 0 else 0

def segments_intersect(ab, cd):
    a, b = ab
    c, d = cd
    o1 = ccw(a, b, c)
    o2 = ccw(a, b, d)
    o3 = ccw(c, d, a)
    o4 = ccw(c, d, b)
    return (o1 != o2) and (o3 != o4)

