def determine_winner(H):
    factors = {}
    current = H
    # Factor out 2
    count = 0
    while current % 2 == 0:
        count += 1
        current //= 2
    if count > 0:
        factors[2] = count
    # Check odd factors
    i = 3
    while i * i <= current:
        count = 0
        while current % i == 0:
            count += 1
            current //= i
        if count > 0:
            factors[i] = count
        i += 2
    if current > 1:
        factors[current] = 1
    # Calculate XOR of exponents
    xor_sum = 0
    for exp in factors.values():
        xor_sum ^= exp
    return "Printf{}" if xor_sum != 0 else "Pappu Bhujia"

