import sys

def tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            if j > i:
                tokens.append(expr[i:j])
            i = j
    return tokens

def infix_to_postfix(tokens):
    output = []
    stack = []
    precedence = {'+':1, '-':1, '*':2, '/':2, '(':0}
    for token in tokens:
        if isinstance(token, int):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if stack:
                stack.pop()
        else:
            while stack and precedence.get(stack[-1], 0) >= precedence[token]:
                output.append(stack.pop())
            stack.append(token)
    while stack:
        output.append(stack.pop())
    return output

def evaluate_postfix(postfix, p):
    stack = []
    for token in postfix:
        if isinstance(token, int):
            stack.append(token)
        else:
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = (a + b) % p
            elif token == '-':
                res = (a - b) % p
            elif token == '*':
                res = (a * b) % p
            elif token == '/':
                if b == 0:
                    return None
                inv_b = pow(b, p-2, p)
                res = (a * inv_b) % p
            stack.append(res)
    return stack[0] if len(stack) == 1 else None

def process_dataset(line):
    if not line or line.strip() == '0:':
        return
    parts = line.split(':', 1)
    p_str, exp_part = parts[0].strip(), parts[1].strip()
    if p_str == '0':
        return
    p = int(p_str)
    exp_clean = exp_part.replace(' ', '')
    tokens = tokenize(exp_clean)
    processed_tokens = []
    for tok in tokens:
        if tok in '+-*/()':
            processed_tokens.append(tok)
        else:
            processed_tokens.append(int(tok) % p)
    postfix = infix_to_postfix(processed_tokens)
    result = evaluate_postfix(postfix, p)
    print(f"{exp_clean} = {result} (mod {p})" if result is not None else "NG")

