import sys
from collections import deque

def rotate90(grid):
    n = len(grid)
    rotated = []
    for i in range(n):
        new_row = []
        for j in range(n):
            new_row.append(grid[n - j - 1][i])
        rotated.append(''.join(new_row))
    return rotated

def has_path(grid):
    n = len(grid)
    left = [(i, 0) for i in range(n) if grid[i][0] == '.']
    right = set((i, n-1) for i in range(n) if grid[i][n-1] == '.')
    if not left or not right:
        return False
    visited = set(left)
    queue = deque(left)
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    while queue:
        x, y = queue.popleft()
        if (x, y) in right:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                if grid[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
    return False

