def split_tokens(s):
    tokens = []
    current = []
    inside = False
    for c in s:
        if not inside:
            if c == '"':
                if current:
                    tokens.append(''.join(current))
                    current = []
                current.append(c)
                inside = True
            else:
                current.append(c)
        else:
            current.append(c)
            if c == '"':
                tokens.append(''.join(current))
                current = []
                inside = False
    if not inside and current:
        tokens.append(''.join(current))
    return tokens

def judge(s1, s2):
    tokens1 = split_tokens(s1)
    tokens2 = split_tokens(s2)
    if len(tokens1) != len(tokens2):
        return "DIFFERENT"
    for t1, t2 in zip(tokens1, tokens2):
        is_str1 = t1.startswith('"') and t1.endswith('"')
        is_str2 = t2.startswith('"') and t2.endswith('"')
        if is_str1 != is_str2:
            return "DIFFERENT"
    for t1, t2 in zip(tokens1, tokens2):
        if not t1.startswith('"'):
            if t1 != t2:
                return "DIFFERENT"
    diff = 0
    for t1, t2 in zip(tokens1, tokens2):
        if t1.startswith('"'):
            if t1 != t2:
                diff += 1
    if diff == 0:
        return "IDENTICAL"
    elif diff == 1:
        return "CLOSE"
    else:
        return "DIFFERENT"

