from collections import deque

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        N, M = map(int, sys.stdin.readline().split())
        adj = [[] for _ in range(N+1)]
        in_degree = [0] * (N+1)
        for _ in range(M):
            a, b = map(int, sys.stdin.readline().split())
            adj[a].append(b)
            in_degree[b] += 1

        # Kahn's algorithm for topological sort
        queue = deque()
        topo_order = []
        for i in range(1, N+1):
            if in_degree[i] == 0:
                queue.append(i)

        while queue:
            u = queue.popleft()
            topo_order.append(u)
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        if len(topo_order) != N:
            print("IMPOSSIBLE")
        else:
            F = [1] * (N+1)
            for u in topo_order:
                for v in adj[u]:
                    if F[v] < F[u] + 1:
                        F[v] = F[u] + 1
            print(max(F[1:N+1]))

