def count_divisors(x):
    if x == 1:
        return 1
    cnt = 1
    temp = x
    for i in range(2, int(math.isqrt(temp)) + 1):
        if i * i > temp:
            break
        if temp % i == 0:
            exp = 0
            while temp % i == 0:
                exp += 1
                temp //= i
            cnt *= (exp + 1)
    if temp > 1:
        cnt *= 2
    return cnt

