            if v == a or v == b:
                continue
            a_conn = is_polygon_edge(a, v, n) or (tuple(sorted((a, v)) in current))
            b_conn = is_polygon_edge(b, v, n) or (tuple(sorted((b, v)) in current))
            if a_conn and b_conn:
                if x is None:
                    x = v
                else:
                    y = v
                    break
        new_diag = tuple(sorted((x, y)))
        steps.append((found, new_diag))
        current.remove(found)
        current.add(new_diag)
    return steps

