            ways = 0
            # Left cell (r, c-1)
            if c > 1:
                ways += dp[r][c-1][s_prev]
            # Up cell (r-1, c)
            if r > 1:
                ways += dp[r-1][c][s_prev]
            ways %= MOD
            if ways == 0:
