            # Update current based on whether current cell is special
            if (r, c) in special:
                new_s = s_prev + 1
                if new_s <= k:
                    current[new_s] = (current[new_s] + ways) % MOD
            else:
                current[s_prev] = (current[s_prev] + ways) % MOD
