    nodes = {}
    current_pos = steps[0][0]
    for current_node, op, next_node in steps:
        if current_node not in nodes:
            nodes[current_node] = {'prev': None, 'next': None}
        curr_prev = nodes[current_node]['prev']
        curr_next = nodes[current_node]['next']
        if op == '->':
            if curr_next is None:
                nodes[current_node]['next'] = next_node
            if next_node not in nodes:
                nodes[next_node] = {'prev': None, 'next': None}
            if nodes[next_node]['prev'] is None:
                nodes[next_node]['prev'] = current_node
        else:
            if curr_prev is None:
                nodes[current_node]['prev'] = next_node
            if next_node not in nodes:
                nodes[next_node] = {'prev': None, 'next': None}
            if nodes[next_node]['next'] is None:
                nodes[next_node]['next'] = current_node
        current_pos = next_node
    head = current_pos
    while True:
        prev_node = nodes.get(head, {'prev': None})['prev']
        if prev_node is None:
            break
        head = prev_node
    formation = []
