def sum_of_digits(x):
    s = 0
    while x > 0:
        s += x % 10
        x = x // 10
    return s

def compute_cache():
    cache = {}
    for m in range(1, 163):
        seen = set()
        current = m
        while True:
            if current in (1, 4):
                cache[m] = True
                break
            if current in seen:
                cache[m] = False
                break
            seen.add(current)
            current = sum_of_digits(current ** 2)
    return cache

