    while queue:
        current = queue.popleft()
        if not current:
            found = True
            break
        for i in range(len(current)):
            if current[i][1] >= 2:
                # Generate new_groups by removing the current group and merging
                new_groups = current[:i] + current[i+1:]
                merged = []
                for g in new_groups:
