                        merged[-1] = (g[0], merged[-1][1] + g[1])
                    else:
                        merged.append(g)
                if not merged:
                    found = True
                    queue = deque()
                    break
                merged_tuple = tuple(merged)
                if merged_tuple not in visited:
                    visited.add(merged_tuple)
