def generate_primes(m):
    primes = []
    candidate = 2
    while len(primes) < m:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1
    return primes

def get_factor_sequences(n):
    def dfs(m, max_factor):
        if m == 1:
            return [[]]
        sequences = []
        divisors = []
        for d in range(min(m, max_factor), 1, -1):
            if m % d == 0:
                divisors.append(d)
        for d in divisors:
            for seq in dfs(m // d, d):
                sequences.append([d] + seq)
        return sequences
    return dfs(n, n)

