    a, b, c = sorted((l, m, n))
    print(max_jumps(a, b, c))

@lru_cache(maxsize=None)
def max_jumps(a, b, c):
    max_steps = 0
    # Check left jump (a is the leftmost)
    if c - b > 1:
        for x in range(b + 1, c):
            new_a, new_b, new_c = sorted((b, x, c))
            current = 1 + max_jumps(new_a, new_b, new_c)
            if current > max_steps:
                max_steps = current
    # Check right jump (c is the rightmost)
    if b - a > 1:
        for x in range(a + 1, b):
            new_a, new_b, new_c = sorted((a, x, b))
            current = 1 + max_jumps(new_a, new_b, new_c)
            if current > max_steps:
                max_steps = current
    return max_steps

