from collections import deque

def main():
    n, k = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)

    def bfs(start):
        visited = [-1] * (n + 1)
        q = deque([start])
        visited[start] = 0
        while q:
            u = q.popleft()
            for v in edges[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    q.append(v)
        max_dist = max(visited)
        far_node = visited.index(max_dist)
        return far_node, max_dist

    u, _ = bfs(1)
    v, diameter = bfs(u)

    parent = [0] * (n + 1)
    visited = [False] * (n + 1)
    q = deque([u])
    visited[u] = True
    while q:
        node = q.popleft()
        if node == v:
            break
        for neighbor in edges[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                parent[neighbor] = node
                q.append(neighbor)

    path = []
    current = v
    while current != u:
        path.append(current)
        current = parent[current]
    path.append(u)
    path.reverse()

    m = len(path)
    hubs = []
    step = (k - 1) // 2
    if step == 0:
        step = 1
    i = 0
    while i < m:
        hubs.append(path[i])
        i += step

    shortcuts = []
    for i in range(1, len(hubs)):
        shortcuts.append((hubs[i-1], hubs[i]))

    for node in path:
        if node not in hubs:
            closest = None
            min_dist = float('inf')
            for h in hubs:
                dist = abs(path.index(h) - path.index(node))
                if dist < min_dist:
                    min_dist = dist
                    closest = h
            if closest != node:
                shortcuts.append((node, closest))

    extra_hub = path[m // 2]
    for h in hubs:
        if h != extra_hub:
            shortcuts.append((h, extra_hub))

    printed = set()
    unique_shortcuts = []
    for u, v in shortcuts:
        if (u, v) not in printed and (v, u) not in printed and u != v:
            printed.add((u, v))
            unique_shortcuts.append((u, v))

    print(len(unique_shortcuts))
    for u, v in unique_shortcuts:
        print(u, v)

