import sys
from collections import deque

sys.setrecursionlimit(1 << 25)

def main():
    n = int(sys.stdin.readline())
    edges_input = []
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        edges_input.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Compute parent and build tree
    parent = [0]*(n+1)
    visited = [False]*(n+1)
    q = deque([1])
    visited[1] = True
    parent[1] = -1
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v] and v != parent[u]:
                parent[v] = u
                visited[v] = True
                q.append(v)

    # Determine child for each edge
    child_nodes = []
    for u, v in edges_input:
        if parent[u] == v:
            child_nodes.append(u)
        else:
            assert parent[v] == u
            child_nodes.append(v)

    # Compute sizes using iterative post-order traversal
    size = [1]*(n+1)
    stack = [(1, False)]
    while stack:
        node, visited_flag = stack.pop()
        if visited_flag:
            for v in adj[node]:
                if v != parent[node]:
                    size[node] += size[v]
        else:
            stack.append((node, True))
            for v in adj[node]:
                if v != parent[node]:
                    stack.append((v, False))

    # HLD variables
    current_pos = 0
    head = [0]*(n+1)
    depth = [0]*(n+1)
    pos_in_hld = [0]*(n+1)

    # Iterative HLD
    stack = [(1, 1, 0)]  # (node, head, depth)
    traversal_order = []
    while stack:
        u, h, d = stack.pop()
        if pos_in_hld[u] != 0:
            continue
        head[u] = h
        depth[u] = d
        pos_in_hld[u] = current_pos
        current_pos += 1
        max_size = -1
        heavy = -1
        for v in adj[u]:
            if v != parent[u] and size[v] > max_size:
                max_size = size[v]
                heavy = v
        # Push light children first, then heavy to process heavy next
        for v in reversed(adj[u]):
            if v != parent[u] and v != heavy:
                stack.append((v, v, d+1))
        if heavy != -1:
            stack.append((heavy, h, d))

    # LCA binary lifting
    log_max = 20
    up = [[-1]*(n+1) for _ in range(log_max)]
    up[0] = parent[:]
    for k in range(1, log_max):
        for v in range(1, n+1):
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to depth of v
        for k in range(log_max-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(log_max-1, -1, -1):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Segment Tree
    class SegmentTree:
        def __init__(self, size):
            self.n = size
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [0]*(2*self.size)
            self.lazy = [0]*(2*self.size)

        def push(self, node, l, r):
            if self.lazy[node] != 0:
                self.tree[node] += self.lazy[node] * (r - l + 1)
                if l != r:
                    self.lazy[2*node] += self.lazy[node]
                    self.lazy[2*node+1] += self.lazy[node]
                self.lazy[node] = 0

        def range_add(self, a, b, val):
            def _add(node, l, r, a, b, val):
                self.push(node, l, r)
                if a > r or b < l:
                    return
                if a <= l and r <= b:
                    self.lazy[node] += val
                    self.push(node, l, r)
                    return
                mid = (l + r) // 2
                _add(2*node, l, mid, a, b, val)
                _add(2*node+1, mid+1, r, a, b, val)
                self.tree[node] = self.tree[2*node] + self.tree[2*node+1]
            _add(1, 0, self.size-1, a, b, val)

        def point_query(self, idx):
            res = 0
            a = idx
            def _query(node, l, r):
                nonlocal res
                self.push(node, l, r)
                if l == r:
                    res += self.tree[node]
                    return
                mid = (l + r) // 2
                if a <= mid:
                    _query(2*node, l, mid)
                else:
                    _query(2*node+1, mid+1, r)
            _query(1, 0, self.size-1)
            return res

    st = SegmentTree(current_pos)

    k = int(sys.stdin.readline())
    for _ in range(k):
        a, b = map(int, sys.stdin.readline().split())
        l = lca(a, b)
        # Update path a to l
        u = a
        while head[u] != head[l]:
            st.range_add(pos_in_hld[head[u]], pos_in_hld[u], 1)
            u = parent[head[u]]
        if u != l:
            st.range_add(pos_in_hld[l]+1, pos_in_hld[u], 1)
        # Update path b to l
        u = b
        while head[u] != head[l]:
            st.range_add(pos_in_hld[head[u]], pos_in_hld[u], 1)
            u = parent[head[u]]
        if u != l:
            st.range_add(pos_in_hld[l]+1, pos_in_hld[u], 1)

    # Collect results
    output = []
    for child in child_nodes:
        output.append(str(st.point_query(pos_in_hld[child])))
    print(' '.join(output))

