from itertools import combinations

def main():
    n = int(sys.stdin.readline())
    c = list(map(int, sys.stdin.readline().split()))

    if c.count(n) != 1:
        print("NO")
        return

    available = [x for x in c if x != n]
    available_sorted = sorted(available, reverse=True)

    def is_possible(available, target_sum, min_children):
        available_sorted = sorted(available, reverse=True)
        for k in range(min_children, len(available_sorted) + 1):
            for combo in combinations(available_sorted, k):
                if sum(combo) != target_sum:
                    continue
                remaining = list(available_sorted)
                valid_combo = True
