from sys import stdin

def main():
    for line in stdin:
        line = line.strip()
        if not line:
            continue
        W, H = map(int, line.split())
        if W == 0 and H == 0:
            break
        grid = []
        for _ in range(H):
            row = list(map(int, stdin.readline().split()))
            grid.append(row)
        target = 0
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 1:
                    pos = i * W + j
                    target |= (1 << pos)
        if target == 0:
            print(0)
            continue
        squares = []
        for i in range(H):
            for j in range(W):
                if grid[i][j] != 1:
                    continue
                max_size = min(H - i, W - j)
                for s in range(1, max_size + 1):
                    valid = True
                    for x in range(i, i + s):
                        for y in range(j, j + s):
                            if grid[x][y] != 1:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        mask = 0
                        for x in range(i, i + s):
                            for y in range(j, j + s):
                                pos = x * W + y
                                mask |= (1 << pos)
                        squares.append((mask, s))
        squares.sort(key=lambda x: (-x[1], -bin(x[0]).count('1')))
        best = float('inf')
        n = len(squares)

        def backtrack(covered, count, start):
            nonlocal best
            if covered == target:
                best = min(best, count)
                return
            if count >= best:
                return
            remaining = bin(target & ~covered).count('1')
            if remaining == 0:
                return
            max_s = 0
            for i in range(start, n):
                s = squares[i][1]
                if s > max_s:
                    max_s = s
            if max_s == 0:
                return
            max_area = max_s ** 2
            lower_bound = (remaining + max_area - 1) // max_area
            if count + lower_bound >= best:
                return
            for i in range(start, n):
                mask, s = squares[i][0], squares[i][1]
                new_covered = covered | mask
                if new_covered == covered:
                    continue
                backtrack(new_covered, count + 1, i + 1)
                if best <= count + 1:
                    break

        backtrack(0, 0, 0)
        print(best if best != float('inf') else 0)

