import sys

def find_fraction(R):
    if R < 1e-10:
        return f"{round(math.pi)}/1"
    b_threshold = math.ceil(0.5 / R)
    for b in range(1, b_threshold + 1):
        a = round(math.pi * b)
        error = abs(a / b - math.pi)
        if error <= R + 1e-10:
            return f"{a}/{b}"
    a = round(math.pi * b_threshold)
    return f"{a}/{b_threshold}"

