def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] in '^&|':
            tokens.append(s[i])
            i += 1
        else:
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
    return tokens

def evaluate(tokens):
    def parse_primary(i):
        return int(tokens[i]), i + 1

    def parse_xor(i):
        val, i = parse_primary(i)
        while i < len(tokens) and tokens[i] == '^':
            rhs, i = parse_primary(i + 1)
            val ^= rhs
        return val, i

    def parse_and(i):
        val, i = parse_xor(i)
        while i < len(tokens) and tokens[i] == '&':
            rhs, i = parse_xor(i + 1)
            val &= rhs
        return val, i

    def parse_or(i):
        val, i = parse_and(i)
        while i < len(tokens) and tokens[i] == '|':
            rhs, i = parse_and(i + 1)
            val |= rhs
        return val, i

    res, _ = parse_or(0)
    return res

