import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    max_c = 0
    for i in range(m):
        u, v, c = map(int, sys.stdin.readline().split())
        edges.append((u, v, c, i + 1))
        if c > max_c:
            max_c = c

    # Binary search for minimal C
    low, high = 0, max_c
    answer_C = max_c
    while low <= high:
        mid = (low + high) // 2
        adj = [[] for _ in range(n + 1)]
        in_degree = [0] * (n + 1)
        for u, v, c, idx in edges:
            if c > mid:
                adj[u].append(v)
                in_degree[v] += 1
        # Kahn's algorithm
        q = deque()
        visited = 0
        for i in range(1, n + 1):
            if in_degree[i] == 0:
                q.append(i)
        while q:
            u = q.popleft()
            visited += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    q.append(v)
        if visited == n:
            answer_C = mid
            high = mid - 1
        else:
            low = mid + 1

    # Reconstruct the DAG for answer_C to find topological order
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)
    for u, v, c, idx in edges:
        if c > answer_C:
            adj[u].append(v)
            in_degree[v] += 1
    q = deque()
    order = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            q.append(i)
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)
    pos = {node: idx for idx, node in enumerate(order)}
    reversed_edges = []
    for u, v, c, idx in edges:
