        for i in range(1, n):
            if q[i] > peaks[-1]:
                peaks.append(q[i])

        # Collect available numbers
        available = []
        peak_set = set(peaks)
        for num in range(1, n + 1):
            if num not in peak_set:
                available.append(num)
        available.sort()
        available_ptr = 0
        possible = True
        p = [0] * n
        current_peak_index = 0

        for i in range(n):
            if i == 0:
                p[i] = peaks[current_peak_index]
                current_peak_index += 1
            else:
                if q[i] > q[i - 1]:
