                        possible = False
                        break
                    p[i] = peaks[current_peak_index]
                    current_peak_index += 1
                else:
                    if available_ptr < len(available) and available[available_ptr] < q[i]:
                        p[i] = available[available_ptr]
                        available_ptr += 1
