import sys

def main():
    sys.setrecursionlimit(1 << 25)
    n, m, k = map(int, sys.stdin.readline().split())
    priority = []
    for _ in range(n):
        priority.append(list(map(int, sys.stdin.readline().split())))

    cells = []
    for i in range(n):
        for j in range(m):
            cells.append((i, j))

    # Sort cells first by i+j, then by priority
    cells.sort(key=lambda x: (x[0] + x[1], priority[x[0]][x[1]]))

    # Now process cells in this order
    grid = [[None for _ in range(m)] for __ in range(n)]
    open_count = [[0 for _ in range(m)] for __ in range(n)]

    # Precompute the required final open count
    total_length = n + m - 1
    if total_length % 2 != 0:
        print("")  # According to problem statement, this won't happen
        return
    required_open = total_length // 2

    # For memoization of possible counts
    memo = {}

    def dp(i, j, current_open):
        if (i, j, current_open) in memo:
            return memo[(i, j, current_open)]
        if i == n-1 and j == m-1:
            if current_open == required_open:
                return 1
            else:
                return 0
        next_i, next_j = 0, 0
        found = False
        for idx in range(len(cells)):
            ci, cj = cells[idx]
            if ci == i and cj == j:
                if idx +1 < len(cells):
                    next_i, next_j = cells[idx+1]
                    found = True
                break
        if not found:
            return 0
        sum_next = next_i + next_j
        possible = []
        if next_i == i and next_j == j +1:
            prev_open = current_open
        elif next_j == j and next_i == i +1:
            prev_open = current_open
        else:
            left = open_count[next_i][next_j -1] if next_j >0 else -1
            top = open_count[next_i -1][next_j] if next_i >0 else -1
            if next_j ==0:
                prev_open = top
            elif next_i ==0:
                prev_open = left
            else:
                if left != top:
                    return 0
                prev_open = left
        total = 0
        for delta in [0,1]:
            new_open = prev_open + delta
            balance = 2 * new_open - (next_i + next_j +1 -1)
            if balance <0:
                continue
            if next_i == n-1 and next_j == m-1:
                if new_open != required_open:
                    continue
            open_count[next_i][next_j] = new_open
            cnt = dp(next_i, next_j, new_open)
            total += cnt
        memo[(i,j, current_open)] = total
        return total

    for cell in cells:
        i, j = cell
        if i ==0 and j ==0:
            possible = []
            for delta in [1]:
                new_open = delta
                balance = 2 * new_open -1
                if balance <0:
                    continue
                if n ==1 and m ==1:
                    if new_open != required_open:
                        continue
                possible.append(delta)
            assert len(possible) ==1
            delta = possible[0]
            grid[i][j] = '(' if delta ==1 else ')'
            open_count[i][j] = delta
            continue
        if i ==0:
            left_i, left_j = i, j-1
            prev_open = open_count[left_i][left_j]
        elif j ==0:
            top_i, top_j = i-1, j
            prev_open = open_count[top_i][top_j]
        else:
            left_open = open_count[i][j-1]
            top_open = open_count[i-1][j]
            if left_open != top_open:
                possible = []
            else:
                prev_open = left_open
        possible = []
        for delta in [0,1]:
            new_open = prev_open + delta
            balance = 2 * new_open - (i + j +1 -1)
            if balance <0:
                continue
            if i == n-1 and j == m-1:
                if new_open != required_open:
                    continue
            possible.append(delta)
        cnt0 = 0
        cnt1 = 0
        for delta in possible:
            if delta ==0:
                cnt0 = dp(i, j, new_open)
            else:
                cnt1 = dp(i, j, new_open)
        possible_deltas = []
        for delta in possible:
            possible_deltas.append((delta, cnt1 if delta else cnt0))
        if not possible_deltas:
            print("")
            return
        for delta, cnt in possible_deltas:
            if k <= cnt:
                grid[i][j] = '(' if delta else ')'
                open_count[i][j] = prev_open + delta
                break
            else:
                k -= cnt
        else:
            print("")
            return
    for row in grid:
        print(''.join(row))

