def main():
    import sys
    n, *rest = list(map(int, sys.stdin.read().split()))
    a = rest[:n]

    zeros_blocks = []
    i = 0
    while i < n:
        if a[i] == 0:
            start = i
            while i < n and a[i] == 0:
                i += 1
            end = i - 1
            # Find left and right shields
            left_shield = start - 1 if start > 0 else -1
            right_shield = end + 1 if end < n-1 else n
            zeros_blocks.append((start, end, left_shield, right_shield))
        else:
            i += 1

    splits = []
    for blk in zeros_blocks:
        l, r, s, e = blk
        m = r - l + 1
        if m < 2:
            continue
        for split_pos in range(l, r):
            i = split_pos
            cost_left = i - s if s != -1 else float('inf')
            cost_right = e - (i + 1) if e != n else float('inf')
            cost = min(cost_left, cost_right)
            if cost == float('inf'):
                continue
            m1 = i - l + 1
            m2 = r - i
            gain = m1 * m2
            splits.append((cost, gain))

    max_k = n * (n - 1) // 2
    dp = [-1] * (max_k + 1)
    dp[0] = 0
    for cost, gain in splits:
        for k in range(max_k, cost - 1, -1):
            if dp[k - cost] != -1:
                if dp[k] < dp[k - cost] + gain:
                    dp[k] = dp[k - cost] + gain
        for k in range(1, max_k + 1):
            if dp[k] < dp[k - 1]:
                dp[k] = dp[k - 1]

    total_zeros = sum(1 - x for x in a)
    T = total_zeros * (total_zeros - 1) // 2
    S = 0
    for blk in zeros_blocks:
        l, r, _, _ = blk
        m = r - l + 1
        S += m * (m - 1) // 2
    initial_protection = T - S

    max_protection = [0] * (max_k + 1)
    current_max = initial_protection
    for k in range(max_k + 1):
        if dp[k] != -1:
            current_max = max(current_max, initial_protection + dp[k])
        max_protection[k] = current_max

    required_length = n * (n - 1) // 2 + 1
    if len(max_protection) < required_length:
        last = max_protection[-1]
        max_protection += [last] * (required_length - len(max_protection))
    else:
        max_protection = max_protection[:required_length]

    print(' '.join(map(str, max_protection)))

