from sys import stdin

def main():
    n, m = map(int, stdin.readline().split())
    if m == 0:
        print(0)
        return

    parent = list(range(n + 1))
    rank = [1] * (n + 1)
    degrees = [0] * (n + 1)

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1

    for _ in range(m):
        x, y = map(int, stdin.readline().split())
        if x != y:
            degrees[x] += 1
            degrees[y] += 1
            union(x, y)
        else:
            degrees[x] += 2

    has_edge = set()
    for node in range(1, n + 1):
        if degrees[node] > 0:
            root = find(node)
            has_edge.add(root)

    C = len(has_edge)
    total_odd = sum(1 for node in range(1, n + 1) if degrees[node] % 2 == 1)
    edges_needed = (total_odd - 2 * (C - 1)) // 2 + (C - 1)
    print(edges_needed)

