import sys
from collections import deque
import math

def is_valid(grid):
    n = len(grid)
    m = len(grid[0])
    visited = [[False]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                q = deque()
                q.append((i, j))
                visited[i][j] = True
                val = grid[i][j]
                min_r = max_r = i
                min_c = max_c = j
                while q:
                    x, y = q.popleft()
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nx, ny = x+dx, y+dy
                        if 0<=nx<n and 0<=ny<m and not visited[nx][ny] and grid[nx][ny] == val:
                            visited[nx][ny] = True
                            q.append((nx, ny))
                            min_r = min(min_r, nx)
                            max_r = max(max_r, nx)
                            min_c = min(min_c, ny)
                            max_c = max(max_c, ny)
                for x in range(min_r, max_r+1):
                    for y in range(min_c, max_c+1):
                        if grid[x][y] != val:
                            return False
    return True

def compute_cost(grid, n, m, vertical):
    if vertical:
        prefix_0 = []
        prefix_1 = []
        for row in grid:
            p0 = [0]*m
            p1 = [0]*m
            c0 = c1 = 0
            for i in range(m):
                if row[i] != 0:
                    c0 +=1
                if row[i] != 1:
                    c1 +=1
                p0[i] = c0
                p1[i] = c1
            prefix_0.append(p0)
            prefix_1.append(p1)
    else:
        prefix_0 = []
        prefix_1 = []
        for j in range(m):
            p0 = [0]*n
            p1 = [0]*n
            c0 = c1 =0
            for i in range(n):
                if grid[i][j] !=0:
                    c0 +=1
                if grid[i][j] !=1:
                    c1 +=1
                p0[i] = c0
                p1[i] = c1
            prefix_0.append(p0)
            prefix_1.append(p1)
        n, m = m, n  # swap for horizontal processing

    dp = [[math.inf]*2 for _ in range(m)]
    dp[-1] = [0, 0]  # j=-1 as initial state

    for i in range(m):
        for current_color in [0, 1]:
            min_cost = math.inf
            for j in range(-1, i):
                for prev_color in [0, 1]:
                    if prev_color == current_color:
                        continue
                    a = j + 1
                    b = i
                    if a > b:
                        continue
                    cost = 0
                    if vertical:
                        for x in range(n):
                            if a ==0:
                                c = prefix_0[x][b] if current_color ==0 else prefix_1[x][b]
                            else:
                                c = prefix_0[x][b] - prefix_0[x][a-1] if current_color ==0 else prefix_1[x][b] - prefix_1[x][a-1]
                            cost += c
                    else:
                        for y in range(m):
                            if a ==0:
                                c = prefix_0[y][b] if current_color ==0 else prefix_1[y][b]
                            else:
                                c = prefix_0[y][b] - prefix_0[y][a-1] if current_color ==0 else prefix_1[y][b] - prefix_1[y][a-1]
                            cost += c
                    prev_cost = dp[j][prev_color] if j !=-1 else 0
                    if prev_cost + cost < min_cost:
                        min_cost = prev_cost + cost
            dp[i][current_color] = min(dp[i][current_color], min_cost)
    return min(dp[m-1][0], dp[m-1][1])

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))
    if is_valid(grid):
        print(0)
        return
    vertical_cost = compute_cost(grid, n, m, vertical=True)
    horizontal_cost = compute_cost([list(row) for row in zip(*grid)], m, n, vertical=False)
    min_cost = min(vertical_cost, horizontal_cost)
    if min_cost <= k:
        print(min_cost)
    else:
        print(-1)

