MOD = 10**9 + 7

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    s = list(map(int, data[1:n+1]))

    # Precompute Fibonacci numbers up to 2^17
    max_fib = 1 << 17
    fib = [0] * (max_fib + 1)
    fib[1] = 1
    for i in range(2, max_fib + 1):
        fib[i] = (fib[i-1] + fib[i-2]) % MOD

    # Compute frequency array cnt
    cnt = {}
    for num in s:
        cnt[num] = cnt.get(num, 0) + 1

    max_mask = 1 << 17
    cnt_array = [0] * max_mask
    for x in cnt:
        cnt_array[x] = cnt[x]

    # Compute subset convolution for count_X (number of a,b pairs)
    def subset_convolution(f):
        n_bits = 17
        size = 1 << n_bits
        popcount = [0] * size
        for mask in range(size):
            popcount[mask] = bin(mask).count('1')

        f_hat = [[0]*(n_bits+1) for _ in range(size)]
        for mask in range(size):
            k = popcount[mask]
            if k <= n_bits:
                f_hat[mask][k] = f[mask] % MOD

        # Zeta transform for each layer
        for k in range(n_bits+1):
            for i in range(n_bits):
                for mask in range(size):
                    if not (mask & (1 << i)):
                        f_hat[mask | (1 << i)][k] = (f_hat[mask | (1 << i)][k] + f_hat[mask][k]) % MOD

        # Multiply f_hat with itself
        h_hat = [[0]*(n_bits+1) for _ in range(size)]
        for mask in range(size):
            for i in range(n_bits+1):
                for j in range(n_bits+1 - i):
                    h_hat[mask][i + j] = (h_hat[mask][i + j] + f_hat[mask][i] * f_hat[mask][j]) % MOD

        # Inverse Möbius transform
        for k in range(n_bits+1):
            for i in range(n_bits):
                for mask in range(size):
                    if mask & (1 << i):
                        h_hat[mask][k] = (h_hat[mask][k] - h_hat[mask ^ (1 << i)][k]) % MOD

        # Extract result
        h = [0] * size
        for mask in range(size):
            k = popcount[mask]
            if k <= n_bits:
                h[mask] = h_hat[mask][k] % MOD
        return h

    count_X = subset_convolution(cnt_array)

    # Compute xor_count using FWHT
    def fwht(a):
        h = 1
        while h < max_mask:
            for i in range(0, max_mask, h * 2):
                for j in range(i, i + h):
                    x = a[j]
                    y = a[j + h]
                    a[j] = (x + y) % MOD
                    a[j + h] = (x - y) % MOD
            h <<= 1
    def inv_fwht(a):
        fwht(a)
        inv = pow(max_mask, MOD-2, MOD)
        for i in range(max_mask):
            a[i] = a[i] * inv % MOD

    freq = [0] * max_mask
    for num in s:
        freq[num] += 1
    a = freq.copy()
    fwht(a)
    for i in range(max_mask):
        a[i] = a[i] * a[i] % MOD
    inv_fwht(a)
    xor_count = a

    # Compute fx, fy, fz
    fx = [ (count_X[x] * fib[x]) % MOD for x in range(max_mask) ]
    fy = [ (cnt.get(x,0) * fib[x]) % MOD for x in range(max_mask) ]
    fz = [ (xor_count[x] * fib[x]) % MOD for x in range(max_mask) ]

    # Compute Zeta transforms
    def zeta_transform(f):
        for i in range(17):
            for mask in range(max_mask):
                if not (mask & (1 << i)):
                    f[mask | (1 << i)] = (f[mask | (1 << i)] + f[mask]) % MOD
    zeta_transform(fx)
    zeta_transform(fy)
    zeta_transform(fz)

    total = 0
    from itertools import product

    for k in range(17):
        other_bits = [i for i in range(17) if i != k]
        m = len(other_bits)
        for bits in product([0, 1], repeat=m):
            t = 1 << k
            cnt_bits = 0
            for i in range(m):
                if bits[i]:
                    t |= 1 << other_bits[i]
                    cnt_bits += 1
            contrib = fx[t] * fy[t] % MOD
            contrib = contrib * fz[t] % MOD
            if cnt_bits % 2 == 0:
                total = (total + contrib) % MOD
            else:
                total = (total - contrib) % MOD
    print(total % MOD)

