import heapq

def dijkstra(n, adj, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = []
    heapq.heappush(heap, (0, start))
    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, d in adj[u]:
            if dist[v] > current_dist + d:
                dist[v] = current_dist + d
                heapq.heappush(heap, (dist[v], v))
    return dist

class Edge:
    def __init__(self, to, rev, capacity):
        self.to = to
        self.rev = rev
        self.capacity = capacity

class Dinic:
    def __init__(self, n):
        self.size = n
        self.graph = [[] for _ in range(n + 1)]

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs_level(self, s, t, level):
        q = [s]
        level[:] = [-1] * (self.size + 1)
        level[s] = 0
        while q:
            u = q.pop(0)
            for edge in self.graph[u]:
                if edge.capacity > 0 and level[edge.to] == -1:
                    level[edge.to] = level[u] + 1
                    q.append(edge.to)
                    if edge.to == t:
                        return

    def dfs_flow(self, u, t, upTo, iter_, level):
        if u == t:
            return upTo
        for i in range(iter_[u], len(self.graph[u])):
            edge = self.graph[u][i]
            if edge.capacity > 0 and level[u] < level[edge.to]:
                d = self.dfs_flow(edge.to, t, min(upTo, edge.capacity), iter_, level)
                if d > 0:
                    edge.capacity -= d
                    self.graph[edge.to][edge.rev].capacity += d
                    return d
            iter_[u] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        level = [-1] * (self.size + 1)
        while True:
            self.bfs_level(s, t, level)
            if level[t] == -1:
                return flow
            iter_ = [0] * (self.size + 1)
            while True:
                f = self.dfs_flow(s, t, float('inf'), iter_, level)
                if f == 0:
                    break
                flow += f

