def count_special_primes(l, r):
    if r < 2:
        return 0

    sqrt_r = math.isqrt(r)
    sieve_size = sqrt_r + 1
    sieve = [True] * sieve_size
    sieve[0] = sieve[1] = False
    for i in range(2, math.isqrt(sieve_size) + 1):
        if sieve[i]:
            sieve[i*i : sieve_size : i] = [False] * len(sieve[i*i : sieve_size : i])
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    seg_size = r - l + 1
    seg_sieve = [True] * seg_size

    if l <= 0:
        for i in range(max(0, 0 - l), min(seg_size, 2 - l)):
            seg_sieve[i] = False

    for p in primes:
        if p == 0:
            continue
        start = max(p * p, ((l + p - 1) // p) * p)
        for multiple in range(start, r + 1, p):
            seg_sieve[multiple - l] = False

    count = 0
    for i in range(seg_size):
        if seg_sieve[i]:
            num = i + l
            if num == 2 or (num % 4 == 1):
                count += 1
    return count

