import heapq

def main():
    n, m, r = map(int, input().split())
    car_matrices = []
    for _ in range(m):
        matrix = [list(map(int, input().split())) for _ in range(n)]
        car_matrices.append(matrix)

    # Precompute Floyd-Warshall for each car's distance
    car_distances = []
    for c in range(m):
        dist = [row.copy() for row in car_matrices[c]]
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]
        car_distances.append(dist)

    # Precompute best_unlimited with Floyd-Warshall
    best_unlimited = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            best_unlimited[i][j] = min(car_distances[c][i][j] for c in range(m))

    for k in range(n):
        for i in range(n):
            for j in range(n):
                best_unlimited[i][j] = min(best_unlimited[i][j], best_unlimited[i][k] + best_unlimited[k][j])

    # Precompute ans for each s, t, k up to max_k=58
    max_k = 58
    ans = [[[float('inf')] * (max_k + 1) for _ in range(n)] for __ in range(n)]
    for s in range(n):
        dist = [[[float('inf')] * m for _ in range(n)] for __ in range(max_k + 1)]
        for c in range(m):
            dist[0][s][c] = 0
        heap = []
        for c in range(m):
            heapq.heappush(heap, (0, s, c, 0))

        while heap:
            time, u, car, changes = heapq.heappop(heap)
            if time > dist[changes][u][car]:
                continue
            # Move to other cities with current car
            for v in range(n):
                if u == v:
                    continue
                new_time = time + car_distances[car][u][v]
                if new_time < dist[changes][v][car]:
                    dist[changes][v][car] = new_time
                    heapq.heappush(heap, (new_time, v, car, changes))
            # Change car
            if changes < max_k:
                for new_car in range(m):
                    if new_car == car:
                        continue
                    if time < dist[changes + 1][u][new_car]:
                        dist[changes + 1][u][new_car] = time
                        heapq.heappush(heap, (time, u, new_car, changes + 1))

        # Fill ans for s
        for t in range(n):
            for k_val in range(max_k + 1):
                min_time = float('inf')
                for changes_used in range(k_val + 1):
                    for c in range(m):
                        min_time = min(min_time, dist[changes_used][t][c])
                ans[s][t][k_val] = min_time

    # Process queries
    for _ in range(r):
        s, t, k = map(int, input().split())
        s -= 1
        t -= 1
        if k >= n - 1:
            print(best_unlimited[s][t])
        else:
            if k > max_k:
                print(best_unlimited[s][t])
            else:
                print(ans[s][t][k])

