def main():
    n, m = map(int, sys.stdin.readline().split())
    clauses = []
    for _ in range(n):
        parts = list(map(int, sys.stdin.readline().split()))
        clauses.append(parts[1:])

    assignments = {}
    single_clauses = [c for c in clauses if len(c) == 1]
    for c in single_clauses:
        v = c[0]
        x = abs(v)
        desired = v > 0
        if x in assignments:
            if assignments[x] != desired:
                print("NO")
                return
        else:
            assignments[x] = desired

    remaining_clauses = []
    var_to_clauses = defaultdict(list)
    for idx, clause in enumerate(clauses):
        satisfied = False
        for v in clause:
            x = abs(v)
            if x in assignments:
                if (v > 0 and assignments[x]) or (v < 0 and not assignments[x]):
                    satisfied = True
                    break
        if satisfied:
            continue
        new_clause = []
        for v in clause:
            x = abs(v)
            if x not in assignments:
                new_clause.append(v)
        if not new_clause:
            print("NO")
            return
        remaining_clauses.append(new_clause)
        for v in new_clause:
            var_to_clauses[abs(v)].append((len(remaining_clauses)-1, v))

    clause_status = [False] * len(remaining_clauses)
    clause_lists = [clause.copy() for clause in remaining_clauses]
    queue = deque(range(len(remaining_clauses)))

    while queue:
        clause_idx = queue.popleft()
        if clause_status[clause_idx]:
            continue
        current_clause = clause_lists[clause_idx]
        satisfied = False
        new_literals = []
        for v in current_clause:
            x = abs(v)
            if x in assignments:
                val = assignments[x]
                if (v > 0 and val) or (v < 0 and not val):
                    satisfied = True
                    break
            else:
                new_literals.append(v)
        if satisfied:
            clause_status[clause_idx] = True
            continue
        if not new_literals:
            print("NO")
            return
        v = new_literals[0]
        x = abs(v)
        desired = v > 0
        if x in assignments:
            if assignments[x] != desired:
                print("NO")
                return
        else:
            assignments[x] = desired
        for (cl_i, lit) in var_to_clauses[x]:
            if clause_status[cl_i]:
                continue
            if (lit > 0 and assignments[x]) or (lit < 0 and not assignments[x]):
                clause_status[cl_i] = True
            else:
                new_cl = [l for l in clause_lists[cl_i] if abs(l) != x]
                if not new_cl:
                    print("NO")
                    return
                clause_lists[cl_i] = new_cl
                queue.append(cl_i)

    output = []
    for x in range(1, m+1):
        output.append('1' if assignments.get(x, False) else '0')
    print("YES")
    print(''.join(output))

