import sys
from sys import stdin

class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [1] * (n + 1)
        self.xor = [0] * (n + 1)

    def find(self, u):
        if self.parent[u] != u:
            orig_parent = self.parent[u]
            self.parent[u] = self.find(self.parent[u])
            self.xor[u] ^= self.xor[orig_parent]
        return self.parent[u]

    def union(self, u, v, w):
        u_root = self.find(u)
        v_root = self.find(v)
        if u_root == v_root:
            return False
        if self.rank[u_root] < self.rank[v_root]:
            u_root, v_root = v_root, u_root
            u, v = v, u
            w = w  # since the edge is undirected, weight remains the same
        self.parent[v_root] = u_root
        self.xor[v_root] = self.xor[u] ^ self.xor[v] ^ w
        self.rank[u_root] += self.rank[v_root]
        return True

    def get_xor(self, u):
        self.find(u)
        return self.xor[u]

class Basis:
    def __init__(self):
        self.basis = [0] * 30

    def insert(self, x):
        for i in reversed(range(30)):
            if (x >> i) & 1:
                if self.basis[i] == 0:
                    self.basis[i] = x
                    break
                else:
                    x ^= self.basis[i]
        return

    def get_min(self, x):
        res = x
        for i in reversed(range(30)):
            if (res >> i) & 1 and self.basis[i] != 0:
                res ^= self.basis[i]
        return res

