import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    edges = [[] for _ in range(N+1)]
    for _ in range(N-1):
        a, b = map(int, sys.stdin.readline().split())
        edges[a].append(b)
        edges[b].append(a)

    # BFS to determine parity (A: even depth, B: odd depth)
    parity = [-1] * (N+1)
    A = []
    B = []
    queue = deque()
    root = 1
    parity[root] = 0
    A.append(root)
    queue.append(root)

    while queue:
        u = queue.popleft()
        for v in edges[u]:
