def main():
    for line in sys.stdin:
        parts = list(map(int, line.strip().split()))
        if len(parts) == 1 and parts[0] > 4:
            break
        if len(parts) != 8:
            continue

        displacements = []
        for i in range(0, 8, 2):
            dx, dy = parts[i], parts[i+1]
            displacements.append((dx, dy))

        edges = set()
        for dx, dy in displacements:
            for y in range(4):
                for x in range(4):
                    x2 = x + dx
                    y2 = y + dy
                    if 0 <= x2 < 4 and 0 <= y2 < 4:
                        i_cell = y * 4 + x
                        j_cell = y2 * 4 + x2
                        if i_cell < j_cell:
                            edges.add((i_cell, j_cell))
                        else:
                            edges.add((j_cell, i_cell))

        dp = [0] * (1 << 16)
        dp[0] = 1
        for mask in range(1 << 16):
            if dp[mask] == 0:
                continue

            free = None
            for i in range(16):
                if not (mask & (1 << i)):
                    free = i
                    break
            if free is None:
                continue

            for j in range(free + 1, 16):
                if (free, j) in edges and not (mask & (1 << j)):
                    new_mask = mask | (1 << free) | (1 << j)
                    dp[new_mask] += dp[mask]

        print(dp[0xffff])

