def hungarian(matrix):
    n = len(matrix)
    m = len(matrix[0])
    u = [0] * (n+1)
    v = [0] * (m+1)
    p = [0] * (m+1)
    way = [0] * (m+1)
    INF = float('inf')

    for i in range(1, n+1):
        p[0] = i
        minv = [INF] * (m+1)
        used = [False] * (m+1)
        j0 = 0
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m+1):
                if not used[j]:
                    cur = matrix[i0-1][j-1] - u[i0-1] - v[j-1]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m+1):
                if used[j]:
                    u[p[j]-1] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    result = [0] * n
    for j in range(1, m+1):
        if p[j] != 0:
            result[p[j] - 1] = j - 1
    total = sum(matrix[i][result[i]] for i in range(n))
    return total, result

