import itertools

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __hash__(self):
        return hash((self.x, self.y))

    def __repr__(self):
        return f"({self.x}, {self.y})"

def ccw(a, b, c):
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)

def segment_intersect(a1, a2, b1, b2):
    # Check if line segments a1a2 and b1b2 intersect, return intersection point if they do
    # Return None if not. If they overlap, returns None (we just need any point)
    a1 = Point(a1[0], a1[1])
    a2 = Point(a2[0], a2[1])
    b1 = Point(b1[0], b1[1])
    b2 = Point(b2[0], b2[1])
    # Check if the segments intersect
    ccw1 = ccw(a1, a2, b1)
    ccw2 = ccw(a1, a2, b2)
    ccw3 = ccw(b1, b2, a1)
    ccw4 = ccw(b1, b2, a2)
    if (ccw1 * ccw2 < 0) and (ccw3 * ccw4 < 0):
        # Lines intersect, compute the point
        dx = a2.x - a1.x
        dy = a2.y - a1.y
        dx1 = b1.x - a1.x
        dy1 = b1.y - a1.y
        dx2 = b2.x - a1.x
        dy2 = b2.y - a1.y
        area1 = dx * dy1 - dy * dx1
        area2 = dx * dy2 - dy * dx2
        if area1 * area2 >= 0:
            return None
        t = area1 / (area1 - area2)
        x = b1.x + t * (b2.x - b1.x)
        y = b1.y + t * (b2.y - b1.y)
        return Point(x, y)
    # Check if any endpoints are colinear and overlapping
    def on_segment(a, b, c):
        return (min(a.x, b.x) <= c.x <= max(a.x, b.x)) and (min(a.y, b.y) <= c.y <= max(a.y, b.y))
    if ccw(a1, a2, b1) == 0 and on_segment(a1, a2, b1):
        return Point(b1.x, b1.y)
    if ccw(a1, a2, b2) == 0 and on_segment(a1, a2, b2):
        return Point(b2.x, b2.y)
    if ccw(b1, b2, a1) == 0 and on_segment(b1, b2, a1):
        return Point(a1.x, a1.y)
    if ccw(b1, b2, a2) == 0 and on_segment(b1, b2, a2):
        return Point(a2.x, a2.y)
    return None

def point_in_polygon(p, polygon):
    # p is a Point, polygon is a list of Points in CCW order
    # Returns True if p is inside the polygon
    x, y = p.x, p.y
    inside = False
    n = len(polygon)
    for i in range(n):
        j = (i + 1) % n
        xi, yi = polygon[i].x, polygon[i].y
        xj, yj = polygon[j].x, polygon[j].y
        # Check if the point is on the edge (exclude edges)
        if (yj - yi) * (x - xi) == (y - yi) * (xj - xi):
            if min(xi, xj) <= x <= max(xi, xj) and min(yi, yj) <= y <= max(yi, yj):
                return False  # on edge, not inside
        # Ray casting algorithm
        if ((yi > y) != (yj > y)):
            x_inters = (y - yi) * (xj - xi) / (yj - yi) + xi
            if x < x_inters:
                inside = not inside
    return inside

def get_edges(polygon):
    edges = []
    n = len(polygon)
    for i in range(n):
        a = polygon[i]
        b = polygon[(i+1)%n]
        edges.append( (a, b) )
    return edges

def generate_candidates(obstacles, voters):
    candidates = set()
    # Add all voters' positions
    for v in voters:
        candidates.add( Point(v[0], v[1]) )
    # Add all polygon vertices
    for obs in obstacles:
        for p in obs['vertices']:
            candidates.add( Point(p.x, p.y) )
    # Generate all edges
    all_edges = []
    for obs in obstacles:
        all_edges.extend( obs['edges'] )
    # Add intersections between all pairs of edges
    for e1, e2 in itertools.combinations(all_edges, 2):
        a1, a2 = e1
        b1, b2 = e2
        inter = segment_intersect( (a1.x, a1.y), (a2.x, a2.y), (b1.x, b1.y), (b2.x, b2.y) )
        if inter is not None:
            candidates.add( inter )
    # Add intersections between lines from voters to polygon vertices and all edges
    for v in voters:
        vx, vy = v
        for obs in obstacles:
            for vertex in obs['vertices']:
                # Line from voter to vertex
                line_start = (vx, vy)
                line_end = (vertex.x, vertex.y)
                for edge in all_edges:
                    e1, e2 = edge
                    inter = segment_intersect( line_start, line_end, (e1.x, e1.y), (e2.x, e2.y) )
                    if inter is not None:
                        candidates.add( inter )
    return candidates

def is_segment_blocked(v, p, obstacles):
    # Check if the segment vp is blocked by any obstacle
    for obs in obstacles:
        polygon = obs['vertices']
        edges = obs['edges']
        # Check if any part of vp is inside the obstacle
        # Collect all intersections between vp and edges of the obstacle
        intersections = []
        v_point = Point(v[0], v[1])
        p_point = Point(p.x, p.y)
        for edge in edges:
            a, b = edge
            inter = segment_intersect( (v_point.x, v_point.y), (p_point.x, p_point.y), (a.x, a.y), (b.x, b.y) )
            if inter is not None:
                intersections.append(inter)
        # Sort intersections along the segment v->p
        def key_func(point):
            dx = point.x - v_point.x
            dy = point.y - v_point.y
            return dx*dx + dy*dy
        intersections.sort(key=key_func)
        # Check consecutive pairs
        for i in range(len(intersections)-1):
            a = intersections[i]
            b = intersections[i+1]
            midpoint = Point( (a.x + b.x)/2, (a.y + b.y)/2 )
            if point_in_polygon(midpoint, polygon):
                return True
        # Also check if the entire segment is inside (midpoint)
        midpoint_vp = Point( (v_point.x + p_point.x)/2, (v_point.y + p_point.y)/2 )
        if point_in_polygon(midpoint_vp, polygon):
            return True
    return False

