            vertices.append( Point(x, y) )
        edges = get_edges(vertices)
        obstacles.append( { 'vertices': vertices, 'edges': edges } )
    voters = []
    for _ in range(M):
        x = float(input[ptr])
        y = float(input[ptr+1])
        ptr +=2
        voters.append( (x, y) )
    # Generate all candidate points
    candidates = generate_candidates(obstacles, voters)
    max_count = 0
    for candidate in candidates:
        # Check if candidate is inside any obstacle
        inside_any = False
        for obs in obstacles:
            if point_in_polygon(candidate, obs['vertices']):
                inside_any = True
                break
        if inside_any:
            continue
        # Check how many voters can see this point
        count = 0
        for v in voters:
            if not is_segment_blocked(v, candidate, obstacles):
                count +=1
        if count > max_count:
            max_count = count
    print(max_count)

