def main():
    import sys
    from functools import lru_cache

    N = sys.stdin.readline().strip()
    if not N:
        print(0)
        return
    N = int(N)
    if N <= 0:
        print(0)
        return
    digits = list(str(N))
    len_digits = len(digits)

    @lru_cache(maxsize=None)
    def count_free(pos, tight):
        if pos == len_digits:
            return 1
        limit = int(digits[pos]) if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            total += count_free(pos + 1, new_tight)
        return total

    @lru_cache(maxsize=None)
    def dp(pos, state, tight, leading_zero):
        if pos == len_digits:
            return 1 if state == 4 else 0
        res = 0
        limit = int(digits[pos]) if tight else 9
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_leading_zero = leading_zero and (d == 0)
            if new_leading_zero:
                new_state = 0
            else:
                if leading_zero:
                    new_state = 1 if d == 5 else 0
                else:
                    if state == 0:
                        new_state = 1 if d == 5 else 0
                    elif state == 1:
                        if d == 1:
                            new_state = 2
                        elif d == 5:
                            new_state = 1
                        else:
                            new_state = 0
                    elif state == 2:
                        new_state = 3
                    elif state == 3:
                        if d == 3:
                            new_state = 4
                        else:
                            new_state = 1 if d == 5 else 0
                    elif state == 4:
                        new_state = 4
            if new_state == 4:
                res += count_free(pos + 1, new_tight)
            else:
                res += dp(pos + 1, new_state, new_tight, new_leading_zero)
        return res

    total = dp(0, 0, True, True)
    print(total)

