import sys

def number_to_word(n):
    n += 1
    s = ''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(ord('a') + rem) + s
    return s

def tokenize(s, reserved_tokens):
    reserved_sorted = sorted(reserved_tokens, key=lambda x: (-len(x), x))
    tokens = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i].isspace():
            i += 1
        if i >= len(s):
            break
        max_len = 0
        best_rt = None
        for rt in reserved_sorted:
            if s.startswith(rt, i):
                rt_len = len(rt)
                if rt_len > max_len:
                    max_len = rt_len
                    best_rt = rt
        if best_rt is not None:
            tokens.append(best_rt)
            i += max_len
            continue
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        if s[i].isalpha() or s[i] in {'_', '$'}:
            j = i
            while j < len(s) and (s[j].isalnum() or s[j] in {'_', '$'}):
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        tokens.append(s[i])
        i += 1
    return tokens

def can_join(prev, curr, reserved):
    s = prev + curr
    tokens = tokenize(s, reserved)
    return len(tokens) == 2 and tokens[0] == prev and tokens[1] == curr

