def compute_distance(adj, start, end):
    visited = [-1] * (len(adj) + 1)
    q = deque([start])
    visited[start] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if visited[v] == -1:
                visited[v] = visited[u] + 1
                if v == end:
                    return visited[v]
                q.append(v)
    return visited[end]

def compute_diameter(adj):
    def bfs(start):
        visited = [-1] * (len(adj) + 1)
        q = deque([start])
        visited[start] = 0
        max_node, max_dist = start, 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    if visited[v] > max_dist:
                        max_dist = visited[v]
                        max_node = v
                    q.append(v)
        return max_node, max_dist
    u, _ = bfs(1)
    v, dist = bfs(u)
    return dist

