import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n, k = map(int, stdin.readline().split())
    mod = 2 * k
    edges = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)
    a = list(map(int, stdin.readline().split()))

    # Post-order to compute subtree_xor
    subtree_xor = [[0] * mod for _ in range(n + 1)]
    stack = [(1, 0, False)]  # node, parent, visited

    while stack:
        node, parent, visited = stack.pop()
        if not visited:
            stack.append((node, parent, True))
            # Push children in reverse order (to process left to right)
            for neighbor in reversed(edges[node]):
                if neighbor != parent:
                    stack.append((neighbor, node, False))
        else:
            subtree_xor[node] = [0] * mod
            subtree_xor[node][0] = a[node - 1]
            for child in edges[node]:
                if child != parent:
                    for m in range(mod):
                        shifted = (m + 1) % mod
                        subtree_xor[node][shifted] ^= subtree_xor[child][m]

    # Pre-order to compute sum_ for each node
    sum_ = [[0] * mod for _ in range(n + 1)]
    sum_[1] = subtree_xor[1].copy()
    stack = [(1, 0)]  # node, parent

    while stack:
        u, p = stack.pop()
        for v in edges[u]:
            if v != p:
                sum_v = [0] * mod
                for m in range(mod):
                    new_m_plus_1 = (m + 1) % mod
                    new_m_minus_1 = (m - 1) % mod
                    sum_v[m] = subtree_xor[v][new_m_plus_1] ^ (sum_[u][new_m_minus_1] ^ subtree_xor[v][new_m_minus_1])
                sum_[v] = sum_v
                stack.append((v, u))

    # Compute the result for each root
    result = []
    for r in range(1, n + 1):
        total = 0
        for m in range(k, mod):
            total ^= sum_[r][m]
        result.append(1 if total != 0 else 0)
    print(' '.join(map(str, result)))

