import sys
from collections import deque

class Edge:
    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class MaxFlow:
    def __init__(self, n):
        self.size = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs_level(self, s, t, level):
        q = deque([s])
        level[:] = [-1]*self.size
        level[s] = 0
        while q:
            u = q.popleft()
            for edge in self.graph[u]:
                if edge.cap > 0 and level[edge.to] == -1:
                    level[edge.to] = level[u] + 1
                    q.append(edge.to)
                    if edge.to == t:
                        return

    def dfs_flow(self, u, t, upTo, iter_, level):
        if u == t:
            return upTo
        for i in range(iter_[u], len(self.graph[u])):
            edge = self.graph[u][i]
            if edge.cap > 0 and level[u] < level[edge.to]:
                d = self.dfs_flow(edge.to, t, min(upTo, edge.cap), iter_, level)
                if d > 0:
                    edge.cap -= d
                    self.graph[edge.to][edge.rev].cap += d
                    return d
            iter_[u] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        level = [-1]*self.size
        while True:
            self.bfs_level(s, t, level)
            if level[t] == -1:
                return flow
            iter_ = [0]*self.size
            while True:
                f = self.dfs_flow(s, t, float('inf'), iter_, level)
                if f == 0:
                    break
                flow += f
            level = [-1]*self.size
        return flow

def find_min_cut(mf, s, n, current_cap):
    visited = [False]*n
    q = deque([s])
    visited[s] = True
    while q:
        u = q.popleft()
        for edge in mf.graph[u]:
            if edge.cap > 0 and not visited[edge.to]:
                visited[edge.to] = True
                q.append(edge.to)
    S = set(i for i in range(n) if visited[i])
    edges_in_cut = []
    for u in S:
        for v in range(n):
            if not visited[v] and current_cap[u][v] > 0:
                edges_in_cut.append( (u, v) )
    return edges_in_cut

def main():
    n, k = map(int, sys.stdin.readline().split())
    original_cap = []
    for _ in range(n):
        original_cap.append( list(map(int, sys.stdin.readline().split())) )
    current_cap = [row[:] for row in original_cap]
    current_k = k

    while True:
        mf = MaxFlow(n)
        for i in range(n):
            for j in range(n):
                if current_cap[i][j] > 0:
                    mf.add_edge(i, j, current_cap[i][j])
        s, t = 0, n-1
        flow = mf.max_flow(s, t)
        edges_in_cut = find_min_cut(mf, s, n, current_cap)
        if not edges_in_cut or current_k == 0:
            break

        sum_c = sum(current_cap[u][v] for u, v in edges_in_cut)
        low, high = 0, current_k
        best_delta = 0

        while low <= high:
            mid = (low + high) // 2
            temp_cap = [row[:] for row in current_cap]
            for u, v in edges_in_cut:
                temp_cap[u][v] += mid
            temp_mf = MaxFlow(n)
            for i in range(n):
                for j in range(n):
                    if temp_cap[i][j] > 0:
                        temp_mf.add_edge(i, j, temp_cap[i][j])
            temp_flow = temp_mf.max_flow(s, t)
            if temp_flow == sum_c + mid:
                best_delta = mid
                low = mid + 1
            else:
                high = mid - 1

        for u, v in edges_in_cut:
            current_cap[u][v] += best_delta
        current_k -= best_delta
        if best_delta == 0:
            break

    final_mf = MaxFlow(n)
    for i in range(n):
        for j in range(n):
            if current_cap[i][j] > 0:
                final_mf.add_edge(i, j, current_cap[i][j])
    print(final_mf.max_flow(0, n-1))

