        sorted_weights = sorted(weights)
        rank_dict = {v: i+1 for i, v in enumerate(sorted_weights)}
        ranks = [rank_dict[v] for v in weights]
        ft = FenwickTree(n)
        res = []
        for r in reversed(ranks):
            count = ft.query(r - 1)
            res.append(count)
            ft.update(r, 1)
        res = res[::-1]
        print(' '.join(map(str, res)))

