def are_connected(b1, b2):
    (p1, p2), (p3, p4) = b1, b2
    points_b1 = [p1, p2, ((p1[0]+p2[0]), (p1[1]+p2[1]))]
    for pt in [p1, p2]:
        if pt in (p3, p4):
            return True
        midpoint_b2 = ((p3[0]+p4[0]), (p3[1]+p4[1]))
        if pt == midpoint_b2:
            return True
    midpoint_b1 = ((p1[0]+p2[0]), (p1[1]+p2[1]))
    for pt in [p3, p4]:
        if pt == midpoint_b1:
            return True
    return False

def determine_digit(component):
    edges = {}
    for (a, b) in component:
        edges[a] = edges.get(a, 0) + 1
        edges[b] = edges.get(b, 0) + 1
    node_counts = sorted(edges.values(), reverse=True)
    num_bars = len(component)
    if num_bars == 6:
        if node_counts[:2] == [3,3]:
            return 0
        else:
            return 9
    elif num_bars == 2:
        return 1
    elif num_bars == 5:
        if node_counts[0] == 3:
            return 2
        else:
            return 5 if node_counts.count(3) == 2 else 3
    elif num_bars == 4:
        return 4
    elif num_bars == 3:
        return 7
    elif num_bars == 7:
        return 8
    else:
        return 6

