import heapq

def dijkstra(graph, start, n_nodes):
    INF = float('inf')
    dist = [INF] * (n_nodes + 1)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, c in graph[u]:
            if dist[v] > current_dist + c:
                dist[v] = current_dist + c
                heapq.heappush(heap, (dist[v], v))
    return dist

