import sys
from collections import defaultdict, deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    w = list(map(int, sys.stdin.readline().split()))
    edges = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)
    s = int(sys.stdin.readline())

    # Step 1: Find all bridges using Tarjan's algorithm
    bridges = []
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    time = 1
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)

    for start in range(1, n + 1):
        if not visited[start]:
            stack = [(start, False, -1)]  # (node, is_processed, prev_node)
            while stack:
                node, is_processed, prev_node = stack.pop()
                if is_processed:
                    for neighbor in edges[node]:
                        if parent[neighbor] == node:
                            if low[neighbor] > disc[node]:
                                bridges.append((node, neighbor))
                                bridges.append((neighbor, node))
                            low[node] = min(low[node], low[neighbor])
                        elif neighbor != parent[node]:
                            low[node] = min(low[node], disc[neighbor])
                    continue
                if visited[node]:
                    continue
                visited[node] = True
                disc[node] = low[node] = time
                time += 1
                stack.append((node, True, prev_node))
                for neighbor in reversed(edges[node]):  # To maintain order
                    if neighbor == prev_node:
                        continue
                    if not visited[neighbor]:
                        parent[neighbor] = node
                        stack.append((neighbor, False, node))
                    else:
                        low[node] = min(low[node], disc[neighbor])

    # Step 2: Find 2-edge-connected components (blocks)
    bridge_set = set(bridges)
    adj_without_bridges = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in edges[u]:
            if (u, v) not in bridge_set:
                adj_without_bridges[u].append(v)

    component = [0] * (n + 1)
    current_component = 0
    visited = [False] * (n + 1)
    for i in range(1, n+1):
        if not visited[i]:
            current_component += 1
            q = deque()
            q.append(i)
            visited[i] = True
            component[i] = current_component
            while q:
                u = q.popleft()
                for v in adj_without_bridges[u]:
                    if not visited[v]:
                        visited[v] = True
                        component[v] = current_component
                        q.append(v)

    # Step 3: Compute block sums
    block_sum = defaultdict(int)
    for i in range(1, n+1):
        block = component[i]
        block_sum[block] += w[i-1]

    # Step 4: Build block tree
    block_tree = defaultdict(list)
    for u, v in bridges:
        if component[u] != component[v]:
            a = component[u]
            b = component[v]
            block_tree[a].append(b)
            block_tree[b].append(a)
    # Deduplicate edges
    for key in block_tree:
        block_tree[key] = list(set(block_tree[key]))

    # Step 5: Compute max sum using iterative DFS
    root = component[s]
    if not block_tree[root]:
        print(block_sum[root])
        return

    max_child_sums = {}
    stack = [(root, None, False)]
    while stack:
        u, parent, visited_flag = stack.pop()
        if not visited_flag:
            stack.append((u, parent, True))
            for v in block_tree[u]:
                if v != parent:
                    stack.append((v, u, False))
            max_child_sums[u] = 0
        else:
            current_max = 0
            for v in block_tree[u]:
                if v != parent:
                    current_max = max(current_max, max_child_sums[v])
            max_child_sums[u] = block_sum[u] + current_max
    print(max_child_sums[root])

