        ki, a1, xi, yi, mi = parts
        a = [a1]
        for j in range(1, ki):
            next_a = (a[-1] * xi + yi) % mi
            a.append(next_a)
        runs = []
        current_run = [a[0]]
        for num in a[1:]:
            if num >= current_run[-1]:
                current_run.append(num)
            else:
                runs.append(current_run)
                current_run = [num]
        runs.append(current_run)
        scientists.append({'runs': runs, 'current_run_idx': 0})

    first_heap = []
    second_heap = []
    merged = []
    bad_pairs = 0
    last_end = -float('inf')

    # Initialize heaps with first runs of each scientist
    for sci_idx in range(n):
        sci = scientists[sci_idx]
        if not sci['runs']:
            continue
        run = sci['runs'][0]
        start = run[0]
        end = run[-1]
        if start >= last_end:
            heapq.heappush(first_heap, (start, end, sci_idx, run))
        else:
            heapq.heappush(second_heap, (start, end, sci_idx, run))

    while first_heap or second_heap:
        if first_heap:
            start, end, sci_idx, elements = heapq.heappop(first_heap)
        else:
            start, end, sci_idx, elements = heapq.heappop(second_heap)
            if last_end > start:
                bad_pairs += 1

        merged.extend([(elem, sci_idx + 1) for elem in elements])
        if last_end > start:
            bad_pairs += 1
        last_end = end

        sci = scientists[sci_idx]
        sci['current_run_idx'] += 1
        if sci['current_run_idx'] < len(sci['runs']):
            next_run = sci['runs'][sci['current_run_idx']]
