from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n = int(stdin.readline())
    f = list(map(int, stdin.readline().split()))
    adj = [[] for _ in range(n+1)]  # 1-based
    for i in range(1, n+1):
        adj[i].append(f[i-1])
    reverse_adj = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        reverse_adj[f[i-1]].append(i)

    # Kosaraju's algorithm to find SCCs
    visited = [False] * (n + 1)
    order = []
    for i in range(1, n+1):
        if not visited[i]:
            stack = [(i, False)]
            while stack:
                node, processed = stack.pop()
                if processed:
                    order.append(node)
                    continue
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, True))
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        stack.append((neighbor, False))

    visited = [False] * (n + 1)
    components = []
    for node in reversed(order):
        if not visited[node]:
            stack = [node]
            visited[node] = True
            component = []
            while stack:
                u = stack.pop()
                component.append(u)
                for v in reverse_adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(component)

    # Build condensation DAG
    component_id = [0] * (n + 1)
    for i in range(len(components)):
        for node in components[i]:
            component_id[node] = i

    in_degree = [0] * len(components)
    out_degree = [0] * len(components)
    cond_adj = [[] for _ in range(len(components))]
    for i in range(len(components)):
        component = components[i]
        outgoing = set()
        for node in component:
            for neighbor in adj[node]:
                nc = component_id[neighbor]
                if nc != i:
                    outgoing.add(nc)
        for nc in outgoing:
            cond_adj[i].append(nc)
            out_degree[i] += 1
            in_degree[nc] += 1

    sources = [i for i in range(len(components)) if in_degree[i] == 0]
    sinks = [i for i in range(len(components)) if out_degree[i] == 0]
    s = len(sources)
    t = len(sinks)
    if len(components) == 1:
        print(0)
    else:
        k = max(s, t)
        source_reps = [components[comp][0] for comp in sources]
        sink_reps = [components[comp][0] for comp in sinks]
        edges = []
        for i in range(k):
            from_rep = sink_reps[i % len(sink_reps)]
            to_rep = source_reps[(i + 1) % len(source_reps)]
            edges.append((from_rep, to_rep))
        print(k)
        for a, b in edges:
            print(a, b)

