    parent_jump = [[-1] * max_level for _ in range(n+1)]
    time_jump = [[0] * max_level for _ in range(n+1)]
    documents = []
    event_count = 0

    for _ in range(m):
        parts = list(map(int, sys.stdin.readline().split()))
        event_type = parts[0]
        event_count += 1

        if event_type == 1:
            x, y = parts[1], parts[2]
            parent_jump[x][0] = y
            time_jump[x][0] = event_count
            for k in range(1, max_level):
                prev_ancestor = parent_jump[x][k-1]
                if prev_ancestor == -1:
                    parent_jump[x][k] = -1
                    time_jump[x][k] = 0
                else:
                    parent_jump[x][k] = parent_jump[prev_ancestor][k-1]
                    time_jump[x][k] = max(time_jump[x][k-1], time_jump[prev_ancestor][k-1])
        elif event_type == 2:
            x = parts[1]
            documents.append((x, event_count))
        elif event_type == 3:
            x, i = parts[1], parts[2]
            doc_x, doc_time = documents[i-1]
            current = doc_x
            found = (current == x)
            if not found:
                while True:
                    jumped = False
                    for k in reversed(range(max_level)):
                        if parent_jump[current][k] != -1 and time_jump[current][k] <= doc_time:
                            next_node = parent_jump[current][k]
                            if next_node == x:
                                found = True
                                break
                            current = next_node
                            jumped = True
                            break
                    if found or not jumped:
                        break
            print("YES" if found else "NO")

