import sys

def compute_intersection(s, e, a, b, c):
    x1, y1 = s
    x2, y2 = e
    denominator = a * (x2 - x1) + b * (y2 - y1)
    if denominator == 0:
        return None
    t_numerator = -(a * x1 + b * y1 + c)
    t = t_numerator / denominator
    if 0 <= t <= 1:
        x = x1 + t * (x2 - x1)
        y = y1 + t * (y2 - y1)
        return (x, y)
    return None

def clip_polygon(poly, a, b, c):
    output = []
    if not poly:
        return output
    n = len(poly)
    for i in range(n):
        s = poly[i]
        e = poly[(i + 1) % n]
        s_inside = (a * s[0] + b * s[1] + c) >= 0
        e_inside = (a * e[0] + b * e[1] + c) >= 0
        if s_inside and e_inside:
            output.append(e)
        elif s_inside and not e_inside:
            inter = compute_intersection(s, e, a, b, c)
            if inter:
                output.append(inter)
        elif not s_inside and e_inside:
            inter = compute_intersection(s, e, a, b, c)
            if inter:
                output.append(inter)
                output.append(e)
    cleaned = []
    prev = None
    for p in output:
        if prev is None or p != prev:
            cleaned.append(p)
        prev = p
    if cleaned and cleaned[0] == cleaned[-1]:
        cleaned.pop()
    return cleaned

def polygon_area(poly):
    if len(poly) < 3:
        return 0.0
    n = len(poly)
    area = 0.0
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i+1) % n]
        area += (x1 * y2 - x2 * y1)
    return abs(area) / 2.0

