def is_colinear(ax, ay, bx, by, cx, cy):
    return (by - ay) * (cx - ax) == (cy - ay) * (bx - ax)

def count_containing_point(n, m, px, py):
    total = 0
    for ax in range(n):
        for ay in range(m):
            for bx in range(n):
                for by in range(m):
                    if (ax == bx and ay == by):
                        continue
                    for cx in range(n):
                        for cy in range(m):
                            if (ax == cx and ay == cy) or (bx == cx and by == cy):
                                continue
                            if is_colinear(ax, ay, bx, by, cx, cy):
                                continue
                            # Check if (px, py) is inside or on the triangle
                            def sign(ax, ay, bx, by, cx, cy):
                                return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
                            b1 = sign(ax, ay, bx, by, px, py) <= 0
                            b2 = sign(bx, by, cx, cy, px, py) <= 0
                            b3 = sign(cx, cy, ax, ay, px, py) <= 0
                            if (b1 == b2 == b3):
