import sys

class Cat:
    def __init__(self, x, y, c):
        self.x = x
        self.y = y
        self.c = c
        self.priority = []

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        N, M = map(int, line.strip().split())
        if N == 0 and M == 0:
            break
        if N == 0:
            print(0)
            for _ in range(M):
                sys.stdin.readline()
            continue

        cats = []
        for _ in range(N):
            x, y, c = map(int, sys.stdin.readline().split())
            cats.append(Cat(x, y, c))

        bowl_xs = []
        for _ in range(M):
            x = int(sys.stdin.readline().strip())
            bowl_xs.append(x)

        bowl_list = [(x, i) for i, x in enumerate(bowl_xs)]

        for cat in cats:
            x_c, y_c = cat.x, cat.y
            bowl_dist = []
            for x_b, i in bowl_list:
                dx = x_c - x_b
                dist_sq = dx * dx + y_c * y_c
                bowl_dist.append((dist_sq, x_b, i))
            bowl_dist.sort(key=lambda t: (t[0], t[1]))
            cat.priority = [t[2] for t in bowl_dist]

        sum_C = sum(cat.c for cat in cats)
        low, high = 0, sum_C
        answer = sum_C

        while low <= high:
            mid = (low + high) // 2
            allowed = set(range(M))
            assigned = [0] * M
            valid = True

            for cat in cats:
                for b in cat.priority:
                    if b in allowed:
                        assigned[b] += cat.c
                        break
                else:
                    valid = False
                    break

            if not valid:
                low = mid + 1
                continue

            while True:
                max_current = max((assigned[b] for b in allowed), default=0)
                if max_current <= mid:
                    answer = mid
                    high = mid - 1
                    break

                to_remove = [b for b in allowed if assigned[b] > mid]
                if not to_remove:
                    answer = mid
                    high = mid - 1
                    break

                allowed -= set(to_remove)
                if not allowed:
                    low = mid + 1
                    break

                assigned = [0] * M
                valid = True
                for cat in cats:
                    for b in cat.priority:
                        if b in allowed:
                            assigned[b] += cat.c
                            break
                    else:
                        valid = False
                        break
                if not valid:
                    low = mid + 1
                    break

        print(answer)

