def line_segment_circle_intersection(s, t, R, r, R_sin):
    x1, y1 = s
    x2, y2 = t
    dx = x2 - x1
    dy = y2 - y1
    a = dx**2 + dy**2
    if a == 0:
        return False
    t = - (x1*dx + y1*dy) / a
    t = max(0, min(1, t))
    nx = x1 + t*dx
    ny = y1 + t*dy
    d_sq = nx**2 + ny**2
    R_plus_r = R + r
    R_minus_r = R - r
    if (R_minus_r**2 <= d_sq <= R_plus_r**2) and (abs(ny) >= R_sin - 1e-9):
        return True
    for tt in [0, 1]:
        if tt == 0:
            x, y = x1, y1
        else:
            x, y = x2, y2
        d_sq = x**2 + y**2
        if (R_minus_r**2 <= d_sq <= R_plus_r**2) and (abs(y) >= R_sin - 1e-9):
            return True
    for inter_t in [0.0, 1.0]:
        x = x1 + inter_t * dx
        y = y1 + inter_t * dy
        d_sq = x**2 + y**2
        if (R_minus_r**2 <= d_sq <= R_plus_r**2) and (abs(y) >= R_sin - 1e-9):
            return True
    steps = 1000
    for i in range(steps + 1):
        t = i / steps
        x = x1 + t * dx
        y = y1 + t * dy
        d_sq = x**2 + y**2
        if (R_minus_r**2 <= d_sq <= R_plus_r**2) and (abs(y) >= R_sin - 1e-9):
            return True
    return False

def check_vertical(s, t, r_v, R_v):
    x1, y1 = s
    x2, y2 = t
    if x1 > x2:
        x1, x2 = x2, x1
        y1, y2 = y2, y1
    if x1 <= r_v and x2 >= -r_v:
        y_at_minus_r = y1 + ( (-r_v - x1) * (y2 - y1) ) / (x2 - x1) if x2 != x1 else y1
        y_at_plus_r = y1 + ( (r_v - x1) * (y2 - y1) ) / (x2 - x1) if x2 != x1 else y1
        for y in [y_at_minus_r, y_at_plus_r]:
            if abs(y) >= R_v - 1e-9:
                return True
    return False

def compute_min_path(n, r, R, xs, ys, xt, yt):
    S = (xs, ys)
    T = (xt, yt)
    R_sin = R * math.sin(math.pi/(2*n))
    a = R + r
    b = R - r

    vertical_forbidden = check_vertical(S, T, r, R)
    annular_forbidden = line_segment_circle_intersection(S, T, R, r, R_sin)

    if not vertical_forbidden and not annular_forbidden:
        return distance(S, T)
    else:
        return -1

