        print(1)
        return

    allowed_pairs = set()
    for i in range(len(t) - 1):
        allowed_pairs.add((t[i], t[i+1]))

    char_to_idx = {'A':0, 'B':1, 'C':2, 'D':3}
    INF = float('inf')

    # Initialize the transition matrix
    matrix = [[INF]*4 for _ in range(4)]
    for x in ['A', 'B', 'C', 'D']:
        for y in ['A', 'B', 'C', 'D']:
            x_idx = char_to_idx[x]
            y_idx = char_to_idx[y]
            if (x, y) in allowed_pairs:
                matrix[x_idx][y_idx] = 1
            else:
                matrix[x_idx][y_idx] = 0

    def multiply(a, b):
        res = [[INF]*4 for _ in range(4)]
        for i in range(4):
            for k in range(4):
                if a[i][k] == INF:
                    continue
                for j in range(4):
                    if b[k][j] == INF:
                        continue
                    res[i][j] = min(res[i][j], a[i][k] + b[k][j])
        return res

    def matrix_pow(mat, power):
        # Initialize result as identity matrix
        result = [[INF]*4 for _ in range(4)]
        for i in range(4):
            result[i][i] = 0
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    power = n - 1
    mat = matrix_pow(matrix, power)

    min_sum = INF
    for row in mat:
        current_min = min(row)
        if current_min < min_sum:
            min_sum = current_min

    print(n - min_sum)

