def generate_fib_set(n):
    fib = {0, 1}
    a, b = 0, 1
    while True:
        c = a + b
        if c > n:
            break
        fib.add(c)
        a, b = b, c
    return fib

def is_prime(n):
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0:
        return False
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    for a in [2, 3, 5, 7, 11, 13, 17]:
        if a >= n:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s-1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def determine_winner(N):
    if N == 0:
        return "Tac"
    fib_set = generate_fib_set(N)
    sum_fib = sum(x for x in fib_set if 1 <= x <= N)
    total = N * (N + 1) // 2
    sum_non_fib = total - sum_fib
    if sum_non_fib <= 1:
        if sum_non_fib % 2 == 0:
            return "Tac"
        else:
            return "Toe"
    if is_prime(sum_non_fib):
        return "Tic"
    elif sum_non_fib % 2 == 0:
        return "Tac"
    else:
        return "Toe"

