    dp[0] = 0
    for i in range(1, n + 1):
        # Check if current element is already in place
        if p[i-1] == i-1:
            dp[i] = min(dp[i], dp[i-1])
        else:
            dp[i] = dp[i-1] + min(A, B)  # Assuming single element shift, which might not be correct

        for j in range(i):
            # Check subarray [j+1, i] (1-based) which is [j, i-1] in 0-based
            l = j
            r = i - 1
            if l >= r:
                continue
            # Check if left shift can make it consecutive
            valid = True
            # After left shift, the elements should be consecutive
            # So the original array must be [x, x+1, ..., x+k-1, x-1]
            # Then left shift becomes x+1, ..., x+k-1, x-1, x
            x_plus_1 = p[l+1] if l+1 <= r else None
            if x_plus_1 is None:
                continue
            x = x_plus_1
            expected_first = x + (r - l)
            if p[l] != expected_first:
                continue
            for k in range(l+1, r):
                if p[k+1] != p[k] + 1:
                    valid = False
                    break
            if valid:
                dp[i] = min(dp[i], dp[j] + A)
