from collections import defaultdict

def generate_combinations():
    result = []
    path = []
    def backtrack(start, current_sum):
        if current_sum == 10:
            result.append(path.copy())
            return
        if current_sum > 10:
            return
        for num in range(start, 10):
            if current_sum + num > 10:
                continue
            path.append(num)
            backtrack(num, current_sum + num)
            path.pop()
    backtrack(1, 0)
    return result

