comb_freqs.sort(key=lambda x: (-max(x.keys()) if x else 0, -len(x)))

def can_form(k, freq, comb_freqs):
    if k == 0:
        return True
    remaining_sum = sum(weight * count for weight, count in freq.items())
    if remaining_sum < 10 * k:
        return False
    for cf in comb_freqs:
        valid = True
        for weight, cnt in cf.items():
            if freq.get(weight, 0) < cnt:
                valid = False
                break
        if not valid:
            continue
        new_freq = defaultdict(int)
        for w, c in freq.items():
            new_freq[w] = c
        for weight, cnt in cf.items():
            new_freq[weight] -= cnt
            if new_freq[weight] == 0:
                del new_freq[weight]
        if can_form(k-1, new_freq, comb_freqs):
            return True
    return False

