import sys

def build_sparse_table(arr):
    n = len(arr) - 1  # 1-based array
    if n == 0:
        return [], 0
    logn = 0
    while (1 << logn) <= n:
        logn += 1
    logn -= 1
    st = [[0] * (n + 1) for _ in range(logn + 1)]
    for i in range(1, n + 1):
        st[0][i] = arr[i]
    for k in range(1, logn + 1):
        step = 1 << (k - 1)
        for i in range(1, n - step + 2):
            st[k][i] = max(st[k-1][i], st[k-1][i + step])
    return st, logn

def query_max(st, logn, L, R):
    if L > R:
        return -float('inf')
    length = R - L + 1
    k = 0
    while (1 << (k + 1)) <= length:
        k += 1
    return max(st[k][L], st[k][R - (1 << k) + 1])

def compute_sum(R, left_st, left_logn, right_st, right_logn, c, n):
    total = 0
    for i in range(1, n + 1):
        L_i = max(1, i - R)
        R_i = min(n, i + R)
        left_max = query_max(left_st, left_logn, L_i, i)
        right_max = query_max(right_st, right_logn, i, R_i)
        current_max = max(left_max - c * i, right_max + c * i)
        total += current_max
    return total

def main():
    n, m, c = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    a = [0] + a  # 1-based indexing

    left_val = [0] * (n + 1)
    right_val = [0] * (n + 1)
    for i in range(1, n + 1):
        left_val[i] = a[i] + c * i
        right_val[i] = a[i] - c * i

    left_st, left_logn = build_sparse_table(left_val)
    right_st, right_logn = build_sparse_table(right_val)

    max_R = n - 1
    sum_max = compute_sum(max_R, left_st, left_logn, right_st, right_logn, c, n)
    if sum_max < m:
        print(-1)
        return

    low = 0
    high = max_R
    answer = max_R
    while low <= high:
        mid = (low + high) // 2
        current_sum = compute_sum(mid, left_st, left_logn, right_st, right_logn, c, n)
        if current_sum >= m:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1
    print(answer)

