    bit_line = input().strip()

    if all(c == '0' for c in bit_line) or all(c == '1' for c in bit_line):
        print(0)
        return

    unique_table = {}
    memo = {}

    def make_node(var, start):
        if (var, start) in memo:
            return memo[(var, start)]

        length = 2 ** (N - var + 1)
        end = start + length

        s = bit_line[start:end]
        if all(c == '0' for c in s):
            memo[(var, start)] = '0'
            return '0'
        if all(c == '1' for c in s):
            memo[(var, start)] = '1'
            return '1'

        split_length = length // 2
        low_start = start
        high_start = start + split_length

        low = make_node(var + 1, low_start)
        high = make_node(var + 1, high_start)

        if low == high:
            memo[(var, start)] = low
            return low

        key = (var, low, high)
        if key in unique_table:
            memo[(var, start)] = unique_table[key]
            return unique_table[key]
        else:
            unique_table[key] = key
            memo[(var, start)] = key
            return key

    make_node(1, 0)
    print(len(unique_table))

