def multiply_by_two(n_str):
    carry = 0
    result = []
    for c in reversed(n_str):
        digit = int(c)
        total = digit * 2 + carry
        carry = total // 10
        result.append(str(total % 10))
    if carry:
        result.append(str(carry))
    return ''.join(reversed(result))

def subtract_two(s_str):
    digits = list(s_str)
    i = len(digits) - 1
    current = int(digits[i]) - 2
    if current >= 0:
        digits[i] = str(current)
    else:
        digits[i] = str(current + 10)
        i -= 1
        while i >= 0 and digits[i] == '0':
            digits[i] = '9'
            i -= 1
        if i >= 0:
            digits[i] = str(int(digits[i]) - 1)
    res = ''.join(digits).lstrip('0')
    return res or '0'

