        primes = set()
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            counts[p] = counts.get(p, 0) + 1

    if not counts:
        print(-1)
    else:
        max_freq = max(counts.values())
        print(n - max_freq)

