import sys
from collections import defaultdict

def main():
    n = int(sys.stdin.readline())
    intervals = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    a = [[0.0 for _ in range(n)] for _ in range(n)]

    for i in range(n):
        li, ri = intervals[i]
        other_j = [j for j in range(n) if j != i]

        critical_points = set()
        critical_points.add(li)
        critical_points.add(ri)
        for j in other_j:
            lj, rj = intervals[j]
            if lj > li and lj < ri:
                critical_points.add(lj)
            if rj > li and rj < ri:
                critical_points.add(rj)

        sorted_points = sorted(critical_points)
        for idx in range(len(sorted_points) - 1):
            a_interval = sorted_points[idx]
            b_interval = sorted_points[idx + 1]
            a_curr = max(a_interval, li)
            b_curr = min(b_interval, ri)
            if a_curr >= b_curr:
                continue

            terms = []
            for j in other_j:
                lj, rj = intervals[j]
                if b_curr <= lj:
                    terms.append(0)
                elif a_curr >= rj:
                    terms.append(1)
                else:
                    terms.append(2)

            dp_prev = defaultdict(lambda: defaultdict(float))
            dp_prev[0][0] = 1.0
            for j_idx, j in enumerate(other_j):
                term_type = terms[j_idx]
                dp_next = defaultdict(lambda: defaultdict(float))
                if term_type == 0:
                    for k in dp_prev:
                        for m, coeff in dp_prev[k].items():
                            dp_next[k][m] += coeff
                elif term_type == 1:
                    for k in dp_prev:
                        for m, coeff in dp_prev[k].items():
                            dp_next[k + 1][m] += coeff
                else:
                    lj, rj = intervals[j]
                    denom = rj - lj
                    A = 1.0 / denom
                    B = -lj * A
                    C = -A
                    D = rj * A
                    for k in dp_prev:
                        for m, coeff in dp_prev[k].items():
                            dp_next[k + 1][m + 1] += coeff * A
                            dp_next[k + 1][m] += coeff * B
                            dp_next[k][m + 1] += coeff * C
                            dp_next[k][m] += coeff * D
                dp_prev = dp_next

            for k in dp_prev:
                total = 0.0
                for m, coeff in dp_prev[k].items():
                    if coeff == 0:
                        continue
                    m_p1 = m + 1
                    integral_part = coeff * (pow(b_curr, m_p1) - pow(a_curr, m_p1)) / m_p1
                    total += integral_part
                total *= 1.0 / (ri - li)
                if k + 1 < n:
                    a[i][k + 1] += total
                else:
                    a[i][n - 1] += total

    for row in a:
        formatted = []
        for prob in row:
            if abs(prob) < 1e-9:
                formatted.append(0.0)
            else:
                formatted.append(prob)
        print(' '.join(f"{x:.10f}".rstrip('0').rstrip('.') if '.' in f"{x:.10f}" else f"{x:.10f}" for x in formatted))

