import sys

def minimal_time(N):
    low = 0
    high = 2 * 10**18
    ans = 0
    while low <= high:
        mid = (low + high) // 2
        s = mid * (mid + 1) // 2
        if s >= N:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

