def main():
    import sys
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    a.sort()
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    # Precompute cost[l][r] for interval [l, r]
    cost = [[0] * n for _ in range(n)]
    for l in range(n):
        for r in range(l, n):
            m = r - l + 1
            median_pos = l + (m - 1) // 2
            median = a[median_pos]
            left_sum = median * (median_pos - l) - (prefix[median_pos] - prefix[l])
            right_sum = (prefix[r + 1] - prefix[median_pos + 1]) - median * (r - median_pos)
            cost[l][r] = left_sum + right_sum

    # Initialize DP
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for prev in range(i):
                if dp[prev][j - 1] == INF:
                    continue
                current_cost = cost[prev][i - 1]
                if dp[i][j] > dp[prev][j - 1] + current_cost:
                    dp[i][j] = dp[prev][j - 1] + current_cost

    print(dp[n][k], end='\n')

