from collections import defaultdict

char_to_digit = {
    'a': '2', 'b': '2', 'c': '2',
    'd': '3', 'e': '3', 'f': '3',
    'g': '4', 'h': '4', 'i': '4',
    'j': '5', 'k': '5', 'l': '5',
    'm': '6', 'n': '6', 'o': '6',
    'p': '7', 'q': '7', 'r': '7', 's': '7',
    't': '8', 'u': '8', 'v': '8',
    'w': '9', 'x': '9', 'y': '9', 'z': '9'
}

def process_case(n, words, sequence):
    digit_to_words = defaultdict(list)
    for word in words:
        digits = ''.join([char_to_digit[c] for c in word])
        digit_to_words[digits].append(word)

    if not digit_to_words:
        return []

    max_len = max(len(d) for d in digit_to_words.keys())
    results = []

    def backtrack(start, path):
        if start == len(sequence):
            results.append(' '.join(path) + '.')
            return
        for l in range(1, max_len + 1):
            end = start + l
            if end > len(sequence):
                break
            substr = sequence[start:end]
            if substr in digit_to_words:
                for word in digit_to_words[substr]:
                    backtrack(end, path + [word])

    backtrack(0, [])
    return results

