            if char == '?':
                if i == len_n - 1:
                    digits = list(range(1, 10))
                else:
                    digits = list(range(0, 10))
            else:
                digits = [int(char)]
            possible_b.append(digits)

            # Process possible_c
            char = reversed_C[i]
            if char == '?':
                if i == len_n - 1:
                    digits = list(range(1, 10))
                else:
                    digits = list(range(0, 10))
            else:
                digits = [int(char)]
            possible_c.append(digits)

        # Initialize DP
        dp = [[0] * 2 for _ in range(len_n + 1)]
        dp[0][0] = 1

        for i in range(len_n):
