    for bit in reversed(range(30)):
        b = (x >> bit) & 1
        desired_bit = 1 - b
        if current.children[desired_bit] and current.children[desired_bit].count > 0:
            res |= (1 << bit)
            current = current.children[desired_bit]
        else:
            current = current.children[b]
    return res

