def get_intervals(N, max_x):
    intervals = []
    x = 1
    while x <= max_x:
        q = N // x
        if q == 0:
            break
        max_x_for_q = N // q
        current_max_x = min(max_x_for_q, max_x)
        count = current_max_x - x + 1
        intervals.append((q, count))
        x = current_max_x + 1
    return intervals

def main():
    N, K = map(int, input().split())

    # Initial DP: after first element (K=1)
    initial_intervals = get_intervals(N, N)
    dp = {}
    for q, cnt in initial_intervals:
        dp[q] = dp.get(q, 0) + cnt
        dp[q] %= MOD

    for step in range(2, K + 1):
        next_dp = {}
        for m in dp:
            current_count = dp[m]
            intervals = get_intervals(N, m)
            for q, cnt in intervals:
                total = (current_count * cnt) % MOD
                next_dp[q] = (next_dp.get(q, 0) + total) % MOD
        dp = next_dp

    print(sum(dp.values()) % MOD if dp else 0)

