import sys
from collections import deque

class Group:
    def __init__(self, i):
        self.arrival_time = 5 * i
        self.size = 5 if i % 5 == 1 else 2
        self.meal_time = 17 * (i % 2) + 3 * (i % 3) + 19
        self.seated_time = None

def find_consecutive(seats, x, T):
    current_run = 0
    start_idx = 0
    for i in range(len(seats)):
        if seats[i] <= T:
            current_run += 1
            if current_run == x:
                return start_idx
        else:
            current_run = 0
            start_idx = i + 1
    return -1

def simulate(groups):
    seats = [0] * 17
    queue = deque()
    for T in range(0, 1000):  # Simulate up to 1000 minutes
        # Process queue
        temp_queue = deque()
        while queue:
            group = queue.popleft()
            start = find_consecutive(seats, group.size, T)
            if start != -1:
                group.seated_time = T
                for i in range(start, start + group.size):
                    seats[i] = T + group.meal_time
            else:
                temp_queue.append(group)
                break
        temp_queue.extend(queue)
        queue = temp_queue

        # Process arrivals
        if T % 5 == 0:
            i = T // 5
            if i < 100:
                group = groups[i]
                if group.seated_time is None:
                    if not queue:
                        start = find_consecutive(seats, group.size, T)
                        if start != -1:
                            group.seated_time = T
                            for i in range(start, start + group.size):
                                seats[i] = T + group.meal_time
                        else:
                            queue.append(group)
                    else:
                        queue.append(group)
        # Check if all groups are seated
        all_seated = all(g.seated_time is not None for g in groups)
        if all_seated:
            break

groups = [Group(i) for i in range(100)]
