import sys
from collections import defaultdict

def main():
    case_number = 0
    while True:
        n, t, k = map(int, sys.stdin.readline().split())
        if n == 0 and t == 0 and k == 0:
            break
        case_number += 1

        edges = []
        adj = defaultdict(list)
        for _ in range(n-1):
            u, v, c = map(int, sys.stdin.readline().split())
            edges.append((u, v, c))
            adj[u].append((v, c))
            adj[v].append((u, c))

        bases = set()
        for _ in range(t):
            bases.add(int(sys.stdin.readline()))

        if t == 0:
            print(f"Case {case_number}: 0")
            continue

        parent = {}
        visited = [False] * (n + 1)
        subtree_base = [0] * (n + 1)

        stack = [(1, -1)]
        while stack:
            u, p = stack.pop()
            parent[u] = p
            visited[u] = True
            if u in bases:
                subtree_base[u] = 1
            for v, c in adj[u]:
                if v != p and not visited[v]:
                    stack.append((v, u))

        post_order = []
        visited = [False] * (n + 1)
        stack = [(1, False)]
        while stack:
            u, processed = stack.pop()
            if processed:
                post_order.append(u)
                continue
            visited[u] = True
            stack.append((u, True))
            for v, c in adj[u]:
                if v != parent[u] and not visited[v]:
                    stack.append((v, False))

        for u in post_order:
            if parent[u] != -1:
                subtree_base[parent[u]] += subtree_base[u]

        valid_edges = []
        for u, v, c in edges:
            if parent[u] == v:
                u, v = v, u
            if parent[v] == u:
                m = subtree_base[v]
                if 1 <= m <= t-1:
                    valid_edges.append(c)

        valid_edges.sort()
        if len(valid_edges) < k:
            print(f"Case {case_number}: Impossible")
        else:
            total = sum(valid_edges[:k])
            print(f"Case {case_number}: {total}")

