        dp_current = defaultdict(list)
        for carry_in_prev in dp_prev:
            for days_prev, p_prev in dp_prev[carry_in_prev]:
                current_X = X - carry_in_prev
                if current_X < 0:
                    current_X = 0
                if current_X >= Y:
                    new_c_in = 0
                    new_days = days_prev + 1
                    new_p = p_prev
                    entries = dp_current[new_c_in]
                    found = False
                    for j in range(len(entries)):
                        ed, ep = entries[j]
                        if ed >= new_days and ep <= new_p:
                            found = True
                            break
                        if ed <= new_days and ep >= new_p:
                            entries[j] = (new_days, new_p)
                            found = True
                            break
                    if not found:
                        entries.append((new_days, new_p))
                    entries.sort(key=lambda x: (-x[0], x[1]))
                else:
                    required_t = Y - current_X
                    if required_t < 0:
                        required_t = 0
                    new_p_take = p_prev + required_t
                    if new_p_take <= P:
                        new_c_in_take = required_t
                        new_days_take = days_prev + 1
                        entries = dp_current[new_c_in_take]
                        found = False
                        for j in range(len(entries)):
                            ed, ep = entries[j]
                            if ed >= new_days_take and ep <= new_p_take:
                                found = True
                                break
                            if ed <= new_days_take and ep >= new_p_take:
                                entries[j] = (new_days_take, new_p_take)
                                found = True
                                break
                        if not found:
                            entries.append((new_days_take, new_p_take))
                        entries.sort(key=lambda x: (-x[0], x[1]))
                    new_c_in_skip = 0
                    new_days_skip = days_prev
                    new_p_skip = p_prev
                    entries = dp_current[new_c_in_skip]
                    found = False
                    for j in range(len(entries)):
                        ed, ep = entries[j]
                        if ed >= new_days_skip and ep <= new_p_skip:
                            found = True
                            break
                        if ed <= new_days_skip and ep >= new_p_skip:
                            entries[j] = (new_days_skip, new_p_skip)
                            found = True
                            break
                    if not found:
                        entries.append((new_days_skip, new_p_skip))
                    entries.sort(key=lambda x: (-x[0], x[1]))
        dp_prev = defaultdict(list)
        for c_in in dp_current:
            pruned = []
            for days_taken, p_used in dp_current[c_in]:
                keep = True
                for d, p in pruned:
                    if d >= days_taken and p <= p_used:
                        keep = False
                        break
                if keep:
