                    pruned.append( (days_taken, p_used) )
                    pruned.sort(key=lambda x: (-x[0], x[1]))
            dp_prev[c_in] = pruned

    max_days = 0
    for c_in in dp_prev:
        for days_taken, p_used in dp_prev[c_in]:
            if p_used <= P and days_taken > max_days:
                max_days = days_taken
    print(max_days)

