def can_divide(nums, k, target):
    sums = [0] * k
    n = len(nums)

    def backtrack(index):
        if index == n:
            return True
        current = nums[index]
        for i in range(k):
            if sums[i] + current <= target:
                sums[i] += current
                if backtrack(index + 1):
                    return True
                sums[i] -= current
                if sums[i] == 0:
                    break
        return False

    return backtrack(0)

