class Edge:
    def __init__(self, to, rev, capacity):
        self.to = to
        self.rev = rev
        self.capacity = capacity

class Dinic:
    def __init__(self, n):
        self.size = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs_level(self, s, t, level):
        q = deque()
        level[:] = [-1] * self.size
        level[s] = 0
        q.append(s)
        while q:
            v = q.popleft()
            for edge in self.graph[v]:
                if edge.capacity > 0 and level[edge.to] == -1:
                    level[edge.to] = level[v] + 1
                    q.append(edge.to)
                    if edge.to == t:
                        return

    def dfs_flow(self, v, t, upTo, iter_, level):
        if v == t:
            return upTo
        for i in range(iter_[v], len(self.graph[v])):
            edge = self.graph[v][i]
            if edge.capacity > 0 and level[v] < level[edge.to]:
                d = self.dfs_flow(edge.to, t, min(upTo, edge.capacity), iter_, level)
                if d > 0:
                    edge.capacity -= d
                    self.graph[edge.to][edge.rev].capacity += d
                    return d
            iter_[v] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        level = [-1] * self.size
        while True:
            self.bfs_level(s, t, level)
            if level[t] == -1:
                return flow
            iter_ = [0] * self.size
            while True:
                f = self.dfs_flow(s, t, float('inf'), iter_, level)
                if f == 0:
                    break
                flow += f
        return flow

def compute_max_ab_sum(group_a, group_b):
    a_size = len(group_a)
    b_size = len(group_b)
    if a_size == 0 and b_size == 0:
        return 0
    sum_a = sum(p for p, c in group_a)
    sum_b = sum(p for p, c in group_b)
    total = sum_a + sum_b
    s = 0
    t = a_size + b_size + 1
    dinic = Dinic(t + 1)
    for i in range(a_size):
        p, c = group_a[i]
        dinic.add_edge(s, i + 1, p)
    for i in range(b_size):
        p, c = group_b[i]
        dinic.add_edge(a_size + 1 + i, t, p)
    for i in range(a_size):
        a_c = group_a[i][1]
        for j in range(b_size):
            b_c = group_b[j][1]
            if is_prime[a_c + b_c]:
                dinic.add_edge(i + 1, a_size + 1 + j, float('inf'))
    max_flow_val = dinic.max_flow(s, t)
    return total - max_flow_val

def is_possible(l, cards, k):
    eligible = [card for card in cards if card[2] <= l]
    group_a = []
    group_b = []
    group_c = []
    for p, c, li in eligible:
        if c % 2 == 0:
            if c != 1:
                group_a.append((p, c))
        else:
            if c == 1:
                group_c.append((p, c))
            else:
                group_b.append((p, c))
    sum_a = compute_max_ab_sum(group_a, group_b)
    sum_b = 0
    if group_c:
        max_c_p = max(p for p, c in group_c)
        new_a = [(p, c) for p, c in group_a if not is_prime[c + 1]]
        new_b = [(p, c) for p, c in group_b if not is_prime[c + 1]]
        sum_b = max_c_p + compute_max_ab_sum(new_a, new_b)
    return max(sum_a, sum_b) >= k

