def convex_hull(points):
    points = sorted(points)
    if len(points) <= 1:
        return points.copy()
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_point_inside_convex_polygon(point, polygon):
    if not polygon:
        return False
    if len(polygon) == 1:
        return point == polygon[0]
    cross_products = []
    for i in range(len(polygon)):
        a = polygon[i]
        b = polygon[(i+1) % len(polygon)]
        ab = (b[0] - a[0], b[1] - a[1])
        ap = (point[0] - a[0], point[1] - a[1])
        cp = ab[0] * ap[1] - ab[1] * ap[0]
        cross_products.append(cp)
    if all(cp >= 0 for cp in cross_products) or all(cp <= 0 for cp in cross_products):
        return True
    return False

def segments_intersect(a1, a2, b1, b2):
    def ccw(A, B, C):
        return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])
    A, B, C, D = a1, a2, b1, b2
    return (ccw(A,C,D) * ccw(B,C,D) < 0) and (ccw(C,A,B) * ccw(D,A,B) < 0)

def are_convex_hulls_disjoint(B_hull, W_hull):
    if len(B_hull) == 1:
        return not is_point_inside_convex_polygon(B_hull[0], W_hull)
    if len(W_hull) == 1:
        return not is_point_inside_convex_polygon(W_hull[0], B_hull)

    for i in range(len(B_hull)):
        a, b = B_hull[i], B_hull[(i+1)%len(B_hull)]
        dx, dy = b[0]-a[0], b[1]-a[1]
        normal = (dy, -dx)
        proj_B = [normal[0]*p[0] + normal[1]*p[1] for p in B_hull]
        proj_W = [normal[0]*p[0] + normal[1]*p[1] for p in W_hull]
        if max(proj_B) < min(proj_W) or max(proj_W) < min(proj_B):
            return True

    for i in range(len(W_hull)):
        a, b = W_hull[i], W_hull[(i+1)%len(W_hull)]
        dx, dy = b[0]-a[0], b[1]-a[1]
        normal = (dy, -dx)
        proj_B = [normal[0]*p[0] + normal[1]*p[1] for p in B_hull]
        proj_W = [normal[0]*p[0] + normal[1]*p[1] for p in W_hull]
        if max(proj_B) < min(proj_W) or max(proj_W) < min(proj_B):
            return True

    for p in B_hull:
        if is_point_inside_convex_polygon(p, W_hull):
            return False
    for p in W_hull:
        if is_point_inside_convex_polygon(p, B_hull):
            return False

    for i in range(len(B_hull)):
        a1, a2 = B_hull[i], B_hull[(i+1)%len(B_hull)]
        for j in range(len(W_hull)):
            b1, b2 = W_hull[j], W_hull[(j+1)%len(W_hull)]
            if segments_intersect(a1, a2, b1, b2):
                return False
    return True

