                # According to problem statement, this should not happen
                final = next_pos if next_pos >= N else None
                break
            if memo[next_pos] != -1:
                final = memo[next_pos]
                break
            current = next_pos
        if not loop:
            for node in path:
                memo[node] = final

    # BFS
    visited = [False] * (N + 1)
    queue = deque()
    queue.append((1, 0))
    visited[1] = True

    while queue:
        current_pos, steps = queue.popleft()
        for d in range(1, 7):
            next_pos = current_pos + d
            if next_pos >= N:
                print(steps + 1)
                return
            if next_pos < 1 or next_pos > N:
