            if memo[next_pos] is None:
                continue
            final_pos = memo[next_pos]
            if final_pos >= N:
                print(steps + 1)
                return
            if final_pos < 1 or final_pos > N:
                continue
            if not visited[final_pos]:
                visited[final_pos] = True
                queue.append((final_pos, steps + 1))

