def precompute_classy_numbers():
    max_num = 10**18
    classy = set()

    # Generate k=1: exactly one non-zero digit
    for d in range(1, 10):
        m = 0
        while True:
            num = d * (10 ** m)
            if num > max_num:
                break
            classy.add(num)
            m += 1

    # Generate k=2: exactly two non-zero digits
    pow10 = [10**i for i in range(18)]  # Precompute powers of 10
    for a in range(18):
        for b in range(a):
            for d1 in range(1, 10):
                for d2 in range(1, 10):
                    num = d1 * pow10[a] + d2 * pow10[b]
                    if num <= max_num:
                        classy.add(num)

    # Generate k=3: exactly three non-zero digits
    for positions in combinations(range(18), 3):
        a, b, c = sorted(positions, reverse=True)
        for d1 in range(1, 10):
            for d2 in range(1, 10):
                for d3 in range(1, 10):
                    num = d1 * pow10[a] + d2 * pow10[b] + d3 * pow10[c]
                    if num <= max_num:
                        classy.add(num)

    return sorted(classy)

