    def compute(S):
        lenS = len(S)
        n = len(s)
        # dp[j] will represent the number of ways to split first i characters into j parts
        dp = [0]*(m+1)
        dp[0] = 1
        for i in range(1, n+1):
            new_dp = [0]*(m+1)
            for j in range(1, m+1):
                for k in range(0, i):
                    if j == 0:
                        continue
                    sub = s[k:i]
                    if len(sub) < lenS:
                        continue
                    if sub > S:
                        new_dp[j] += dp[j-1]
                    elif sub == S:
                        new_dp[j] += dp[j-1]
            dp = new_dp
        return dp[m]

    # Iterate through possible S in reverse lex order
    for S in substr_list:
        A = compute(S)
        B = compute(S + 'z')  # Hack to compute B(S) as S + 'z' is larger than any string starting with S
        count = A - B
        if count >= k:
