import sys
from sys import stdin

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(stdin.readline())
    a = list(map(int, stdin.readline().split()))
    a = [0] + a  # 1-based indexing

    pos = [0] * (n + 2)  # pos[value] = index
    for i in range(1, n+1):
        pos[a[i]] = i

    data = [0] * (n + 2)  # data[k] is 1 if pos[k] > pos[k+1], else 0

    for k in range(1, n):
        if pos[k] > pos[k+1]:
            data[k] = 1
        else:
            data[k] = 0

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(n)
    for k in range(1, n):
        ft.update(k, data[k])

    q = int(stdin.readline())
    for _ in range(q):
        parts = stdin.readline().split()
        p = int(parts[0])
        x = int(parts[1])
        y = int(parts[2])

        if p == 1:
            l = x
            r = y
            if l == r:
                print(1)
                continue
            res = ft.query(r-1) - ft.query(l-1)
            print(res + 1)
        else:
            xi = x
            yi = y
            u = a[xi]
            v = a[yi]
            affected_ks = {u-1, u, v-1, v}

            for k in affected_ks:
                if 1 <= k <= n-1:
                    ft.update(k, -data[k])

            a[xi], a[yi] = a[yi], a[xi]
            pos[u] = yi
            pos[v] = xi

            for k in affected_ks:
                if 1 <= k <= n-1:
                    if pos[k] > pos[k+1]:
                        new_val = 1
                    else:
                        new_val = 0
                    data[k] = new_val
                    ft.update(k, new_val)

