import sys
import math

MOD = 10**9 + 7
PHI = MOD - 1

def compute_R(n):
    precomputed = {
        0: 1,
        1: 1,
        2: 1,
        3: 3,
        4: 3,
        5: 15,
        6: 15,
        7: 105,
        8: 105,
        9: 105,
        10: 105
    }
    memo = {}

    def helper(n):
        if n in memo:
            return memo[n]
        if n <= 10:
            memo[n] = precomputed[n]
            return precomputed[n]
        else:
            ceil_4 = (n + 3) // 4
            part1 = pow(2, ceil_4, MOD)
            ceil_5 = (n + 4) // 5
            part2 = helper(ceil_5)
            ceil_10 = (n + 9) // 10
            part3 = helper(ceil_10)
            res = (part1 * part2) % MOD
            res = (res * part3) % MOD
            memo[n] = res
            return res
    return helper(n)

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        n = int(sys.stdin.readline())
        R = compute_R(n)
        max_val = 0
        allowed = [(0, 1), (1, 0)]
        for a in range(1, 6):
            for b in range(1, 6):
                if math.gcd(a, b) == 1:
                    allowed.append((a, b))
        for a, b in allowed:
            if a == 0 and b == 1:
                val = 0
            elif a == 1 and b == 0:
                val = 1
            else:
                B = (R * a) % MOD
                if B == 0:
                    val = 0
                else:
                    E = R * b
                    E_mod = E % PHI
                    if E_mod == 0 and E != 0:
                        E_mod = PHI
                    val = pow(B, E_mod, MOD)
            if val > max_val:
                max_val = val
        print(max_val % MOD)

