def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    balls = [tuple(map(int, sys.stdin.readline().split())) for _ in range(2*N)]

    # Precompute min for each column and row
    min_col = {}
    min_row = {}
    for x, y in balls:
        if x not in min_col or y < min_col[x][1]:
            min_col[x] = (x, y)
        if y not in min_row or x < min_row[y][0]:
            min_row[y] = (x, y)

    # Check which balls are critical (min in both)
    critical = []
    for x, y in balls:
        if min_col[x][1] == y and min_row[y][0] == x:
            critical.append((x, y))

    # Build bipartite graph
    from collections import defaultdict, deque
    A = defaultdict(list)  # A[x] -> list of B's y
    B = defaultdict(list)  # B[y] -> list of A's x
    for x, y in critical:
        A[x].append(y)
        B[y].append(x)

    # Check for cycles using BFS
    visited_A = {}
    visited_B = {}
    component = 0
    valid = True
    for x in A:
        if x not in visited_A:
            queue = deque()
            queue.append(('A', x))
            visited_A[x] = component
            prev = None
            while queue:
                type_node, node = queue.popleft()
                if type_node == 'A':
                    for y in A[node]:
                        if y not in visited_B:
                            visited_B[y] = component
                            queue.append(('B', y))
                        elif visited_B[y] != component:
                            valid = False
                else:
                    for x2 in B[node]:
                        if x2 not in visited_A:
                            visited_A[x2] = component
                            queue.append(('A', x2))
                        elif visited_A[x2] != component:
                            valid = False
            component += 1
    if not valid:
        print(0)
        return

    # Compute the product of factorials
    max_n = 2*N
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    # Number of ways is (N!)^2 * 2^c
    c = len(critical)
    ans = pow(2, c, MOD)
    ans = ans * fact[N] % MOD
    ans = ans * fact[N] % MOD

    print(ans)

