                goal = (i, j)
    initial = frozenset(stones)
    if goal in initial:
        print("yes")
        return

    visited = set()
    visited.add(initial)
    q = deque([initial])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def push(s, stone, dx, dy):
        new_stones = set(s)
        if stone not in new_stones:
            return new_stones
        new_stones.remove(stone)
        x, y = stone
        nx, ny = x, y
        while True:
            next_x = nx + dx
            next_y = ny + dy
            if not (0 <= next_x < H and 0 <= next_y < W):
                break
            if (next_x, next_y) in new_stones:
                break
            nx, ny = next_x, next_y
        new_stones.add((nx, ny))
        next_stone = (nx + dx, ny + dy)
        if next_stone in new_stones:
            new_stones = push(new_stones, next_stone, dx, dy)
        return new_stones

    while q:
        current = q.popleft()
        if goal in current:
            print("yes")
            return
        for stone in current:
            for dx, dy in directions:
                new_set = push(current, stone, dx, dy)
                new_state = frozenset(new_set)
                if new_state not in visited:
                    visited.add(new_state)
                    q.append(new_state)
    print("no")

