n = int(input())
cards = []
for _ in range(n):
    c, r, b = input().split()
    cards.append((c, int(r), int(b)))

heap = []
heapq.heappush(heap, (0, 0, 0, 0, 0, 0))  # steps, mask, A, B, r, b

best = {}
final_mask = (1 << n) - 1

while heap:
    steps, mask, A, B, r, b = heapq.heappop(heap)

    if mask == final_mask:
        print(steps)
        exit()

    key = (mask, A, B)

    if key in best:
        min_steps_prev, r_prev, b_prev = best[key]
        if steps < min_steps_prev:
            best[key] = (steps, r, b)
        elif steps == min_steps_prev:
            if r > r_prev or b > b_prev:
                best[key] = (steps, r, b)
            else:
                continue  # Skip if not better
        else:
            continue  # Skip higher steps
    else:
        best[key] = (steps, r, b)

    for i in range(n):
        if not (mask & (1 << i)):
            c, ri, bi = cards[i]
            req_r = max(ri - A, 0)
            req_b = max(bi - B, 0)

            k = max(req_r - r, req_b - b, 0)
            new_r = r + k - req_r
            new_b = b + k - req_b
            new_steps = steps + k + 1
            new_mask = mask | (1 << i)
            new_A = A + (1 if c == 'R' else 0)
            new_B = B + (1 if c == 'B' else 0)
            new_key = (new_mask, new_A, new_B)

            add_to_heap = True
            if new_key in best:
                existing_min_steps, existing_r, existing_b = best[new_key]
                if new_steps > existing_min_steps:
                    add_to_heap = False
                elif new_steps == existing_min_steps:
                    if existing_r >= new_r and existing_b >= new_b:
                        add_to_heap = False

            if add_to_heap:
                heapq.heappush(heap, (new_steps, new_mask, new_A, new_B, new_r, new_b))

