import math

def has_valid_divisor(Q, max_k):
    if max_k < 2:
        return False
    if Q <= max_k:
        return True
    sqrt_q = int(math.isqrt(Q))
    for i in range(2, sqrt_q + 1):
        if Q % i == 0:
            if i <= max_k:
                return True
            other = Q // i
            if other <= max_k and other >= 2:
                return True
    return False

