class Node:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.max_val = 0

def build(l, r, arr):
    node = Node(l, r)
    if l == r:
        node.max_val = arr[l-1]
        return node
    mid = (l + r) // 2
    node.left = build(l, mid, arr)
    node.right = build(mid+1, r, arr)
    node.max_val = max(node.left.max_val, node.right.max_val)
    return node

def update(node, x, y):
    if node.l == node.r == x:
        node.max_val = y
        return
    if x <= node.left.r:
        update(node.left, x, y)
    else:
        update(node.right, x, y)
    node.max_val = max(node.left.max_val, node.right.max_val)

def find_first(node, v):
    stack = [node]
    while stack:
        current = stack.pop()
        if current.max_val < v:
            continue
        if current.l == current.r:
            return current.l
        stack.append(current.right)
        stack.append(current.left)
    return -1

