from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    S = [list(sys.stdin.readline().strip()) for _ in range(N)]

    a_nodes = []
    b_nodes = []
    for i in range(N):
        for j in range(M):
            if S[i][j] == '.':
                if (i + j) % 2 == 0:
                    a_nodes.append((i, j))
                else:
                    b_nodes.append((i, j))

    a_index = {(i, j): idx for idx, (i, j) in enumerate(a_nodes)}
    b_index = {(i, j): idx for idx, (i, j) in enumerate(b_nodes)}

    adj = [[] for _ in range(len(a_nodes))]
    for idx, (i, j) in enumerate(a_nodes):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x = i + dx
            y = j + dy
            if 0 <= x < N and 0 <= y < M:
                if S[x][y] == '.' and (x + y) % 2 == 1:
                    if (x, y) in b_index:
                        adj[idx].append(b_index[(x, y)])

    def hopcroft_karp():
        pair_U = [-1] * len(a_nodes)
        pair_V = [-1] * len(b_nodes)
        dist = [0] * len(a_nodes)

        def bfs():
            queue = deque()
            for u in range(len(a_nodes)):
                if pair_U[u] == -1:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist_found = float('inf')
            while queue:
                u = queue.popleft()
                if dist[u] < dist_found:
                    for v in adj[u]:
                        if pair_V[v] == -1:
                            dist_found = dist[u] + 1
                        elif dist[pair_V[v]] == float('inf'):
                            dist[pair_V[v]] = dist[u] + 1
                            queue.append(pair_V[v])
            return dist_found != float('inf')

        def dfs(u):
            for v in adj[u]:
                if pair_V[v] == -1 or (dist[pair_V[v]] == dist[u] + 1 and dfs(pair_V[v])):
                    pair_U[u] = v
                    pair_V[v] = u
                    return True
            dist[u] = float('inf')
            return False

        result = 0
        while bfs():
            for u in range(len(a_nodes)):
                if pair_U[u] == -1:
                    if dfs(u):
                        result += 1
        return result, pair_U

    max_tiles, pair_U = hopcroft_karp()
    print(max_tiles)

    t = [list(row[:]) for row in S]
    for u, v in enumerate(pair_U):
        if v == -1:
            continue
        i, j = a_nodes[u]
        x, y = b_nodes[v]
        if i == x:
            if j < y:
                t[i][j] = '>'
                t[x][y] = '<'
            else:
                t[i][j] = '<'
                t[x][y] = '>'
        else:
            if i < x:
                t[i][j] = 'v'
                t[x][y] = '^'
            else:
                t[i][j] = '^'
                t[x][y] = 'v'

    for row in t:
        print(''.join(row))

