import sys

def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def euler_phi(n):
    if n == 1:
        return 1
    factors = factorize(n)
    result = 1
    for p in factors:
        e = factors[p]
        result *= (p ** (e - 1)) * (p - 1)
    return result

def multiplicative_order(a, m):
    phi_val = euler_phi(m)
    if phi_val == 0:
        return 1
    factors = factorize(phi_val)
    primes = list(factors.keys())
    exponent_lists = []
    for p in primes:
        exponents = [p**e for e in range(factors[p]+1)]
        exponent_lists.append(exponents)
    divisors = [1]
    for exp_list in exponent_lists:
        temp = []
        for d in divisors:
            for e in exp_list:
                temp.append(d * e)
        divisors = temp
    divisors = sorted(divisors)
    for d in divisors:
        if pow(a, d, m) == 1:
            return d
    return phi_val

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

