            for x in range(X):
                if maze[y][x] == 'X' and block_id[y][x] == -1:
                    q = deque()
                    q.append((x, y))
                    block_id[y][x] = current_block
                    size = 1
                    while q:
                        cx, cy = q.popleft()
                        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nx, ny = cx + dx, cy + dy
                            if 0 <= nx < X and 0 <= ny < Y:
                                if maze[ny][nx] == 'X' and block_id[ny][nx] == -1:
                                    block_id[ny][nx] = current_block
                                    size += 1
                                    q.append((nx, ny))
                    block_sizes.append(size)
                    current_block += 1
        # BFS initialization
        visited = {}
        q = deque()
        sx, sy = start
        initial_counts = {}
        initial_key = (sx, sy, tuple(sorted(initial_counts.items())))
        visited[initial_key] = 0
        q.append((sx, sy, initial_counts, 0))
        found = False
        # BFS loop
        while q and not found:
            x, y, counts, steps = q.popleft()
            if (x, y) == goal:
