                nx, ny = x + dx, y + dy
                if 0 <= nx < X and 0 <= ny < Y:
                    cell = maze[ny][nx]
                    if cell == '#':
                        continue
                    # Process move to plain, S, or G
                    if cell in ('.', 'S', 'G'):
                        new_counts = counts.copy()
                        key_tuple = tuple(sorted(new_counts.items()))
                        state_key = (nx, ny, key_tuple)
