import sys
from sys import stdin

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, stdin.readline().split())
    parents = [0] * (N + 1)
    for i in range(1, M+1):
        p = int(stdin.readline())
        parents[i] = p
    children = [[] for _ in range(N+1)]
    for i in range(1, M+1):
        p = parents[i]
        children[p].append(i)
    roots = list(range(M+1, N+1))
    grundy = [0] * (N + 1)
    possible_xors = dict()  # node: set of possible xors

    for root in roots:
        stack = [(root, False)]
        visited = [False] * (N + 1)
        post_order = []
        while stack:
            node, processed = stack.pop()
            if processed:
                post_order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            # Push children in reverse order for correct post-order
            for child in reversed(children[node]):
                if not visited[child]:
                    stack.append((child, False))
        # Process each node in post_order
        for node in post_order:
            sum_children = 0
            for child in children[node]:
                sum_children ^= grundy[child]
            current_possible = {sum_children}
            # Iterate through each child
            for child in children[node]:
                s = sum_children ^ grundy[child]
                if child in possible_xors:
                    child_set = possible_xors[child]
                    for x in child_set:
                        current_possible.add(s ^ x)
            # Compute mex
            mex = 0
            while mex in current_possible:
                mex += 1
            grundy[node] = mex
            possible_xors[node] = current_possible

    total = 0
    for root in roots:
        total ^= grundy[root]
    print("Alice" if total != 0 else "Bob")

