    sum_group3_w = sum(w for w, v in group3)
    sum_group3_v = sum(v for w, v in group3)
    new_W = W - sum_group3_w

    sorted_group1 = sorted(group1, key=lambda x: (-(x[1]/x[0]), x[0])) if group1 else []
    r = sorted_group1[0][1]/sorted_group1[0][0] if sorted_group1 else 0.0

    sum_group4_v = 0.0
    sum_group4_w = 0.0
    for w, v in group4:
        if v + r * (-w) > 1e-9:
            sum_group4_v += v
            sum_group4_w += w

    available = new_W - sum_group4_w
    current_total = sum_group3_v + sum_group4_v

    for w, v in sorted_group1:
        if available <= 0:
            break
        take = min(1.0, available / w)
