from collections import deque

def main():
    n, k, x_val = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    INF = -10**18

    prev = [INF] * (n + 2)  # 1-based indexing

    # Initialize for j=1
    for i in range(1, k + 1):
        if i <= n:
            prev[i] = a[i - 1]

    for j in range(2, x_val + 1):
        curr = [INF] * (n + 2)
        q = deque()
        for i in range(1, n + 1):
            # Add the current index (i-1) to the deque
            while q and prev[q[-1]] <= prev[i - 1]:
                q.pop()
            q.append(i - 1)

            # Calculate the start of the window
            start = max(1, i - k)
            # Remove elements out of the window
            while q and q[0] < start:
                q.popleft()

            if q:
                max_prev = prev[q[0]]
                if max_prev != INF:
                    curr[i] = max_prev + a[i - 1]
        prev = curr

    # Find the maximum in the last k positions
    result = INF
    start = max(1, n - k + 1)
    for i in range(start, n + 1):
        if prev[i] > result:
            result = prev[i]

    print(result if result != INF else -1)

