def main():
    max_A = 10**5
    total_pairs = [0] * (max_A + 1)

    # Precompute total_pairs for all A from 1 to max_A
    for A in range(1, max_A + 1):
        sqrt_A = math.isqrt(A)
        count = 0
        for i in range(1, sqrt_A + 1):
            if A % i == 0:
                count += 1
        total_pairs[A] = count

    # Precompute is_square array
    is_square = [False] * (max_A + 1)
    for B in range(0, max_A + 1):
        s = math.isqrt(B)
        if s * s == B:
            is_square[B] = True
        else:
            is_square[B] = False

    # Read input efficiently
    input_data = sys.stdin.read().split()
    T = int(input_data[0])
    results = []
    for i in range(1, T + 1):
        A = int(input_data[i])
        if A % 4 != 0:
