            B = A // 4
            if is_square[B]:
                invalid = total_pairs[B] - 1
            else:
                invalid = total_pairs[B]
        ans = total_pairs[A] - invalid
        results.append(ans)

    # Output all results
    sys.stdout.write('\n'.join(map(str, results)) + '\n')

