import sys
from collections import deque

def bfs(start, adj, n):
    visited = [False] * (n + 1)
    q = deque([start])
    visited[start] = True
    parent = [0] * (n + 1)
    parent[start] = -1
    last_node = start
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                q.append(v)
                last_node = v
    return last_node, parent

def find_center(adj, n):
    u, _ = bfs(1, adj, n)
    v, parent = bfs(u, adj, n)
    path = []
    current = v
    while current != -1:
        path.append(current)
        current = parent[current]
    path.reverse()
    L = len(path) - 1
    center_index = L // 2
    return path[center_index]

def compute_ranks(adj, root, n):
    rank = [0] * (n + 1)
    stack = [(root, -1, False)]
    while stack:
        node, parent_node, visited = stack.pop()
        if not visited:
            stack.append((node, parent_node, True))
            for neighbor in adj[node]:
                if neighbor != parent_node:
                    stack.append((neighbor, node, False))
        else:
            max_rank = 0
            count = 0
            for neighbor in adj[node]:
                if neighbor != parent_node:
                    cr = rank[neighbor]
                    if cr > max_rank:
                        max_rank = cr
                        count = 1
                    elif cr == max_rank:
                        count += 1
            if count >= 2:
                rank[node] = max_rank + 1
            else:
                rank[node] = max_rank if max_rank != 0 else 1
    return rank

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)
    if n == 1:
        print('A')
        return
    center = find_center(adj, n)
    ranks = compute_ranks(adj, center, n)
    max_rank = max(ranks[1:])
    if max_rank > 26:
        print("Impossible!")
    else:
        res = [chr(ord('A') + (max_rank - r)) for r in ranks[1:]]
        print(' '.join(res))

