import sys
from bisect import bisect_left, bisect_right

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    row0 = sys.stdin.readline().strip()
    row1 = sys.stdin.readline().strip()

    # Preprocess intervals for each row
    def get_intervals(row):
        intervals = []
        start = 0
        for i in range(len(row)):
            if row[i] == '.':
                if i == 0 or row[i-1] == 'X':
                    start = i
                if i == len(row)-1 or row[i+1] == 'X':
                    intervals.append( (start, i) )
        return intervals

    intervals0 = get_intervals(row0)
    intervals1 = get_intervals(row1)

    # For each column, find which interval it belongs to (row0 and row1)
    col_to_interval0 = [-1]*n
    for idx, (s, e) in enumerate(intervals0):
        for c in range(s, e+1):
            col_to_interval0[c] = idx
    col_to_interval1 = [-1]*n
    for idx, (s, e) in enumerate(intervals1):
        for c in range(s, e+1):
            col_to_interval1[c] = idx

    # Collect all gates (columns where both are '.')
    gates = []
    for c in range(n):
        if row0[c] == '.' and row1[c] == '.':
            gates.append(c)

    # DSU for intervals
    parent = {}
    gate_lists = {}

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if len(gate_lists[u_root]) > len(gate_lists[v_root]):
            u_root, v_root = v_root, u_root
        parent[u_root] = v_root
        gate_lists[v_root].extend(gate_lists[u_root])
        gate_lists[v_root].sort()

    # Initialize DSU: each interval is a node
    # For row0 intervals
    for i in range(len(intervals0)):
        node = ('0', i)
        parent[node] = node
        gate_lists[node] = []
    # For row1 intervals
    for i in range(len(intervals1)):
        node = ('1', i)
        parent[node] = node
        gate_lists[node] = []

    # Merge intervals connected by gates
    for c in gates:
        if col_to_interval0[c] == -1 or col_to_interval1[c] == -1:
            continue
        node0 = ('0', col_to_interval0[c])
        node1 = ('1', col_to_interval1[c])
        if find(node0) not in gate_lists:
            gate_lists[find(node0)] = []
        if find(node1) not in gate_lists:
            gate_lists[find(node1)] = []
        union(node0, node1)
        # Add the gate to the merged component
        root = find(node0)
        gate_lists[root].append(c)
        gate_lists[root].sort()

    # Now, for each interval, after unions, find the root
    # Also, collect the gates for each component

    # Precompute the component for each cell
    cell_component = {}
    for r in range(2):
        for c in range(n):
            if r == 0 and row0[c] == '.':
                interval_idx = col_to_interval0[c]
                node = ('0', interval_idx)
                root = find(node)
                cell_component[(r, c)] = root
            elif r == 1 and row1[c] == '.':
                interval_idx = col_to_interval1[c]
                node = ('1', interval_idx)
                root = find(node)
                cell_component[(r, c)] = root

    # Process queries
    for _ in range(m):
        v, u = map(int, sys.stdin.readline().split())
        v -= 1
        u -= 1
        # Convert to (r, c)
        def get_rc(x):
            if x < n:
                return (0, x)
            else:
                return (1, x - n)
        r1, c1 = get_rc(v)
        r2, c2 = get_rc(u)
        if (r1, c1) not in cell_component or (r2, c2) not in cell_component:
            print(-1)
            continue
        if cell_component[(r1, c1)] != cell_component[(r2, c2)]:
            print(-1)
            continue
        if (r1, c1) == (r2, c2):
            print(0)
            continue
        # Same component
        same_row = (r1 == r2)
        # Check if same interval in same row
        if same_row:
            if r1 == 0:
                interval_idx1 = col_to_interval0[c1]
                interval_idx2 = col_to_interval0[c2]
            else:
                interval_idx1 = col_to_interval1[c1]
                interval_idx2 = col_to_interval1[c2]
            if interval_idx1 == interval_idx2:
                print(abs(c1 - c2))
                continue
        # Need to use gates
        root = cell_component[(r1, c1)]
        gates_in_component = gate_lists.get(root, [])
        if not gates_in_component:
            print(-1)
            continue
        min_c = min(c1, c2)
        max_c = max(c1, c2)
        # Find the best gate
        idx_left = bisect_right(gates_in_component, min_c) - 1
        idx_right = bisect_left(gates_in_component, max_c)
        best = float('inf')
        # Check gates in [min_c, max_c]
        left_gate = None
        right_gate = None
        if idx_left >= 0:
            left_gate = gates_in_component[idx_left]
        if idx_right < len(gates_in_component):
            right_gate = gates_in_component[idx_right]
        # Also check gates in between
        start = bisect_left(gates_in_component, min_c)
        end = bisect_right(gates_in_component, max_c)
        candidates = []
        if start < len(gates_in_component) and gates_in_component[start] <= max_c:
            candidates.append(gates_in_component[start])
        if start > 0:
            candidates.append(gates_in_component[start-1])
        if end > 0 and end-1 < len(gates_in_component):
            candidates.append(gates_in_component[end-1])
        if end < len(gates_in_component):
            candidates.append(gates_in_component[end])
        if left_gate is not None:
            candidates.append(left_gate)
        if right_gate is not None:
            candidates.append(right_gate)
        # Dedup
        candidates = list(set(candidates))
        for g in candidates:
            if g < min_c or g > max_c:
                continue
            if same_row:
                steps = abs(c1 - g) + abs(c2 - g) + 2
            else:
                steps = abs(c1 - g) + abs(c2 - g) + 1
            if steps < best:
                best = steps
        # Check left and right gates if no gates in between
        if best == float('inf'):
            # Use leftmost or rightmost gate
            leftmost = gates_in_component[0]
            steps_left = abs(c1 - leftmost) + abs(c2 - leftmost) + (2 if same_row else 1)
            rightmost = gates_in_component[-1]
            steps_right = abs(c1 - rightmost) + abs(c2 - rightmost) + (2 if same_row else 1)
            best = min(steps_left, steps_right)
        else:
            # Also consider the left and right gates outside the range
            if left_gate is not None and left_gate < min_c:
                steps = (c1 - left_gate) + (c2 - left_gate) + (2 if same_row else 1)
                if steps < best:
                    best = steps
            if right_gate is not None and right_gate > max_c:
                steps = (right_gate - c1) + (right_gate - c2) + (2 if same_row else 1)
                if steps < best:
                    best = steps
        print(best if best != float('inf') else -1)

