class Line:
    __slots__ = ['a', 'b']
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def get(self, x):
        return self.a * x + self.b

class LiChaoNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.line = None
        self.left = None
        self.right = None

    def add_line(self, new_line):
        if self.line is None:
            self.line = new_line
            return
        mid = (self.l + self.r) // 2
        curr_val = self.line.get(mid)
        new_val = new_line.get(mid)
        if new_val > curr_val:
            self.line, new_line = new_line, self.line
        if self.l == self.r - 1:
            return
        if new_line.get(self.l) > self.line.get(self.l):
            if not self.left:
                self.left = LiChaoNode(self.l, mid)
            self.left.add_line(new_line)
        if new_line.get(self.r) > self.line.get(self.r):
            if not self.right:
                self.right = LiChaoNode(mid, self.r)
            self.right.add_line(new_line)

    def query(self, x):
        res = -float('inf')
        if self.line is not None:
            res = self.line.get(x)
        mid = (self.l + self.r) // 2
        if x < mid and self.left:
            res = max(res, self.left.query(x))
        elif x >= mid and self.right:
            res = max(res, self.right.query(x))
        return res

class SegmentTreeNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.lichao = LiChaoNode(-10**18, 10**18)

    def insert_line(self, a, b, start, end):
        if end <= self.l or start >= self.r:
            return
        if start <= self.l and self.r <= end:
            self.lichao.add_line(Line(a, b))
            return
        mid = (self.l + self.r) // 2
        if not self.left or not self.right:
            self.left = SegmentTreeNode(self.l, mid)
            self.right = SegmentTreeNode(mid, self.r)
        self.left.insert_line(a, b, start, end)
        self.right.insert_line(a, b, start, end)

    def query(self, x, q):
        res = self.lichao.query(q)
        if self.l == self.r - 1:
            return res
        mid = (self.l + self.r) // 2
        if x < mid and self.left:
            res = max(res, self.left.query(x, q))
        elif x >= mid and self.right:
            res = max(res, self.right.query(x, q))
        return res

