import math

def rotate_point(x, y, cx, cy, theta_deg):
    theta = math.radians(theta_deg)
    dx = x - cx
    dy = y - cy
    new_x = dx * math.cos(theta) + dy * math.sin(theta) + cx
    new_y = -dx * math.sin(theta) + dy * math.cos(theta) + cy
    return (new_x, new_y)

def ccw(A, B, C):
    return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])

def segments_intersect(A, B, C, D):
    def bbox_intersect(a1, a2, b1, b2):
        return max(a1, b1) <= min(a2, b2)

    x1, y1 = A
    x2, y2 = B
    x3, y3 = C
    x4, y4 = D

    if not (bbox_intersect(min(x1, x2), max(x1, x2), min(x3, x4), max(x3, x4)) and
            bbox_intersect(min(y1, y2), max(y1, y2), min(y3, y4), max(y3, y4))):
        return False

    ccw1 = ccw(A, B, C)
    ccw2 = ccw(A, B, D)
    ccw3 = ccw(C, D, A)
    ccw4 = ccw(C, D, B)

    if (ccw1 * ccw2 > 0) or (ccw3 * ccw4 > 0):
        return False

    if ccw1 == 0 and ccw2 == 0 and ccw3 == 0 and ccw4 == 0:
        return (max(x1, x2) >= min(x3, x4) and min(x1, x2) <= max(x3, x4) and
                max(y1, y2) >= min(y3, y4) and min(y1, y2) <= max(y3, y4))

    return True

def point_in_convex_polygon(point, poly):
    x, y = point
    for i in range(len(poly)):
        a = poly[i]
        b = poly[(i + 1) % len(poly)]
        cross = (b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0])
        if cross < 0:
            return False
    return True

def point_in_polygon(p, polygon):
    x, y = p
    n = len(polygon)
    inside = False
    for i in range(n):
        ax, ay = polygon[i]
        bx, by = polygon[(i + 1) % n]
        if min(ay, by) < y <= max(ay, by):
            x_intersect = (y - ay) * (bx - ax) / (by - ay) + ax if by != ay else ax
            if x <= x_intersect:
                inside = not inside
    return inside

def collision_detected(equipment, patient, cx, cy, theta):
    rotated_eq = [rotate_point(x, y, cx, cy, theta) for (x, y) in equipment]

    for p in rotated_eq:
        if point_in_convex_polygon(p, patient):
            return True

    for p in patient:
        if point_in_polygon(p, rotated_eq):
            return True

    for i in range(len(rotated_eq)):
        a = rotated_eq[i]
        b = rotated_eq[(i + 1) % len(rotated_eq)]
        for j in range(len(patient)):
            c = patient[j]
            d = patient[(j + 1) % len(patient)]
            if segments_intersect(a, b, c, d):
                return True

    return False

def find_max_angle(equipment, patient, cx, cy):
    low = 0.0
    high = 360.0
    for _ in range(100):
        mid = (low + high) / 2
        if collision_detected(equipment, patient, cx, cy, mid):
            high = mid
        else:
            low = mid
    if high < 360.0 and collision_detected(equipment, patient, cx, cy, high):
        return high
    else:
        return 360.0

