def calculate_pages(n):
    if n < 1:
        return "Impossible!"
    sum_prev = 0
    d = 1
    while True:
        current_max = 9 * (10 ** (d - 1)) * d
        sum_current = sum_prev + current_max
        if sum_prev < n <= sum_current:
            remaining = n - sum_prev
            if remaining % d != 0:
                return "Impossible!"
            pages_count = remaining // d
            p = 10 ** (d - 1) + pages_count - 1
            return p
        elif sum_current < n:
            sum_prev = sum_current
            d += 1
        else:
            return "Impossible!"

