    div_map = {}
    for idx, num in enumerate(s):
        if num not in div_map:
            div_map[num] = []
        div_map[num].append(idx)
    for num in div_map:
        div_map[num].sort()
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        l = int(input[ptr])
        ptr += 1
        r = int(input[ptr])
        ptr += 1
        l_prime = l - 1
        r_prime = r - 1
        if l_prime > r_prime:
            print(0)
            continue
        length = r_prime - l_prime + 1
        k = length.bit_length() - 1
        if (1 << k) > length:
            k -= 1
        a = st[k][l_prime] if k < len(st) else 0
        b = st[k][r_prime - (1 << k) + 1] if k < len(st) and (r_prime - (1 << k) + 1) >= 0 else 0
        g = gcd(a, b)
        factors = dict(factorize(g))
        divisors = get_divisors(factors)
