import sys

def count_comparisons(arr, target):
    left = 0
    right = len(arr) - 1
    count = 0
    while left <= right:
        mid = (left + right) // 2
        count += 1
        if arr[mid] == target:
            break
        elif target < arr[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return count

