    while True:
        line = sys.stdin.readline()
        while line.strip() == '':
            line = sys.stdin.readline()
        I, J = map(int, line.strip().split())
        if I == 0 and J == 0:
            break
        if I == J:
            continue
        if J == 0:
            found = False
            for p in piles:
                if I in p:
                    if p[0] == I:
                        found = True
                        break
                    else:
                        idx = p.index(I)
                        before = p[:idx]
                        after = p[idx:]
                        piles.remove(p)
                        if before:
                            piles.append(before)
                        for cube in after:
                            piles.append([cube])
                        found = True
                        break
            continue
        else:
            pile_i = None
            pile_j = None
            for p in piles:
                if I in p:
                    pile_i = p
                if J in p:
                    pile_j = p
            if not pile_i or not pile_j:
                continue
            if pile_i == pile_j:
                i_idx = pile_i.index(I)
                j_idx = pile_j.index(J)
                if i_idx < j_idx:
                    before = pile_i[:i_idx+1]
                    after = pile_i[i_idx+1:]
                    piles.remove(pile_i)
                    if before:
                        piles.append(before)
                    for cube in after:
                        piles.append([cube])
                    j_pile = None
                    for p in piles:
                        if J in p and len(p) == 1:
                            j_pile = p
                            break
                    for p in piles:
                        if p == before:
                            if I in p:
                                p.remove(I)
                                if not p:
                                    piles.remove(p)
                            break
                    if j_pile:
                        j_pile.append(I)
            else:
                for p in piles:
                    if I in p:
                        i_pile = p
                        break
                idx = i_pile.index(I)
                before = i_pile[:idx]
                after = i_pile[idx:]
                piles.remove(i_pile)
                if before:
                    piles.append(before)
                for cube in after:
                    piles.append([cube])
                for p in piles:
                    if J in p:
                        p.append(I)
                        break
    sizes = [len(p) for p in piles]
    sizes.sort()
    for s in sizes:
