def solve():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n, i, j = map(int, line.split())
        if n == 0 and i == 0 and j == 0:
            break
        a = i - 1
        b = j - 1
        # Convert to binary strings with leading zeros to n bits
        bin_a = bin(a)[2:].zfill(n)
        bin_b = bin(b)[2:].zfill(n)
        # Compute XOR for each bit
        result = []
        for k in range(n):
            if bin_a[k] != bin_b[k]:
                result.append('R')
            else:
                result.append('L')
        print(''.join(result))

