def compute_prefix_function(s):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def build_transition_table(s):
    n = len(s)
    pi = compute_prefix_function(s)
    transition = [[0] * 26 for _ in range(n + 1)]
    for state in range(n + 1):
        for c in range(26):
            current = state
            while True:
                if current == n:
                    current = pi[-1] if n > 0 else 0
                if current < n and s[current] == chr(ord('a') + c):
                    current += 1
                    break
                else:
                    if current == 0:
                        break
                    current = pi[current - 1]
            transition[state][c] = current
    return transition

