import sys
from collections import deque

def bfs(n, m, start_x, start_y, targets):
    visited = [[-1 for _ in range(m+1)] for _ in range(n+1)]
    q = deque([(start_x, start_y)])
    visited[start_x][start_y] = 0
    for tx, ty in targets:
        if start_x == tx and start_y == ty:
            return 0
    while q:
        x, y = q.popleft()
        for dx, dy in [ (2,1), (2,-1), (-2,1), (-2,-1), (1,2), (1,-2), (-1,2), (-1,-2) ]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= m and visited[nx][ny] == -1:
                visited[nx][ny] = visited[x][y] + 1
                q.append((nx, ny))
                for tx, ty in targets:
                    if nx == tx and ny == ty:
                        return visited[nx][ny]
    return float('inf')

def bfs_path(n, m, start_x, start_y, target_x, target_y):
    parent = [[None]*(m+1) for _ in range(n+1)]
    q = deque([(start_x, start_y)])
    parent[start_x][start_y] = None
    found = False
    while q:
        x, y = q.popleft()
        if x == target_x and y == target_y:
            found = True
            break
        for dx, dy in [ (2,1), (2,-1), (-2,1), (-2,-1), (1,2), (1,-2), (-1,2), (-1,-2) ]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= n and 1 <= ny <= m and parent[nx][ny] is None:
                parent[nx][ny] = (x, y)
                q.append((nx, ny))
    if not found:
        return []
    path = []
    x, y = target_x, target_y
    while (x, y) != (start_x, start_y):
        path.append((x, y))
        x, y = parent[x][y]
    path.append((start_x, start_y))
    path.reverse()
    return path[1:]

def get_attack_positions(x, y, n, m):
    positions = []
    for dx, dy in [ (2,1), (2,-1), (-2,1), (-2,-1), (1,2), (1,-2), (-1,2), (-1,-2) ]:
        nx, ny = x + dx, y + dy
        if 1 <= nx <= n and 1 <= ny <= m:
            positions.append((nx, ny))
    return positions

