from collections import defaultdict

def main():
    k = int(sys.stdin.readline())
    boxes = []
    elements = []
    sum_total = 0
    element_to_box = {}
    for i in range(k):
        parts = list(map(int, sys.stdin.readline().split()))
        n_i = parts[0]
        a_list = parts[1:]
        boxes.append(a_list)
        sum_i = sum(a_list)
        sum_total += sum_i
        for x in a_list:
            if x in element_to_box:
                print("No")
                return
            element_to_box[x] = i
        elements.append((sum_i, a_list))

    if sum_total % k != 0:
        print("No")
        return

    target = sum_total // k
    deltas = []
    for sum_i, _ in elements:
        deltas.append(target - sum_i)

    transitions = [[] for _ in range(k)]
    for i in range(k):
        sum_i, a_list = elements[i]
        for c in a_list:
            x = c + deltas[i]
            if x in element_to_box:
                j = element_to_box[x]
                transitions[i].append((c, j, x))

    path = []
    visited = [False]*k
    memo = {}

    def backtrack(current_box, required_element, mask, current_path):
        if mask == (1 << k) -1:
            if required_element == path[0][0] and current_box == path[0][1]:
                return current_path
            else:
                return None
        if (current_box, required_element, mask) in memo:
            return None
        memo[(current_box, required_element, mask)] = True
        sum_i, a_list = elements[current_box]
        for c in a_list:
            if c != required_element:
                continue
            for (c_i, j, x) in transitions[current_box]:
                if c_i != c:
                    continue
                if visited[j]:
                    continue
                if (mask & (1 << j)) != 0:
                    continue
                visited[j] = True
                res = backtrack(j, x, mask | (1 << j), current_path + [(c_i, j+1)])
                if res is not None:
                    return res
                visited[j] = False
        return None

    for i in range(k):
        sum_i, a_list = elements[i]
        for c in a_list:
            x = c + deltas[i]
            if x not in element_to_box:
                continue
            j = element_to_box[x]
            path = [(c, i+1)]
            visited = [False]*k
            visited[i] = True
            res = backtrack(j, x, (1 << i) | (1 << j), path)
            if res is not None and len(res) == k:
                output = [0]*k
                for idx in range(len(res)):
                    c_i, p_i = res[idx]
                    current_box = element_to_box[c_i]
                    next_box = p_i -1
                    output[current_box] = (c_i, next_box +1)
                print("Yes")
                for c, p in output:
                    print(c, p)
                return

    print("No")

