import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    levels = [-1] * (n+1)
    dq = deque()
    dq.append((1, -1, 0))

    while dq:
        root, parent_in_decomp, level = dq.popleft()
        if levels[root] != -1:
            continue

        subtree_sizes = {}
        stack = [(root, -1)]
        while stack:
            node, parent = stack.pop()
            if levels[node] != -1:
                subtree_sizes[node] = 0
                continue
            size = 1
            for neighbor in adj[node]:
                if neighbor == parent or neighbor == parent_in_decomp:
                    continue
                if neighbor in subtree_sizes:
                    size += subtree_sizes[neighbor]
                else:
                    stack.append((neighbor, node))
            subtree_sizes[node] = size

        total_size = subtree_sizes.get(root, 0)
        if total_size == 0:
            continue

        current = root
        parent_in_traversal = parent_in_decomp
        while True:
            max_child_size = 0
            max_child = -1
            for neighbor in adj[current]:
                if neighbor == parent_in_traversal or levels[neighbor] != -1:
                    continue
                cs = subtree_sizes.get(neighbor, 0)
                if cs > max_child_size:
                    max_child_size = cs
                    max_child = neighbor
            if max_child_size * 2 > total_size:
                parent_in_traversal = current
                current = max_child
            else:
                break

        centroid = current
        levels[centroid] = level

        for neighbor in adj[centroid]:
            if neighbor != parent_in_decomp and levels[neighbor] == -1:
                dq.append((neighbor, centroid, level + 1))

    max_level = max(levels[1:])
    if max_level >= 26:
        print("Impossible!")
    else:
        print(' '.join([chr(ord('A') + levels[i]) for i in range(1, n+1)]))

