import math

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, x, y = extended_gcd(b % a, a)
        return (g, y - (b // a) * x, x)

def mod_inverse(a, m):
    g, x, y = extended_gcd(a, m)
    if g != 1:
        return None
    else:
        return x % m

def merge(a1, m1, a2, m2):
    d = math.gcd(m1, m2)
    if (a1 - a2) % d != 0:
        return None
    lcm = m1 // d * m2
    m_div = m1 // d
    rhs_mod = m2 // d
    k_num = (a2 - a1) // d
    inv_m = mod_inverse(m_div, rhs_mod)
    if inv_m is None:
        return None
    k = (k_num * inv_m) % rhs_mod
    a = (a1 + k * m1) % lcm
    return (a, lcm)

