import sys
from collections import defaultdict, deque

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        max_s = int(line.strip())
        if max_s == 0:
            break
        n = int(sys.stdin.readline().strip())
        d_list = []
        for _ in range(n):
            d = int(sys.stdin.readline().strip())
            d_list.append(d)
        agari = n + 1
        graph = defaultdict(set)
        for p in range(agari + 1):
            if p == agari:
                continue
            for s in range(1, max_s + 1):
                pos1 = p + s
                if pos1 > agari:
                    pos1 = agari
                if pos1 == agari:
                    graph[p].add(agari)
                    continue
                if pos1 == 0:
                    graph[p].add(0)
                    continue
                di = d_list[pos1 - 1]
                if di == 0:
                    graph[p].add(pos1)
                    continue
                new_pos = pos1 + di
                if new_pos >= agari:
                    new_pos = agari
                elif new_pos < 0:
                    new_pos = 0
                graph[p].add(new_pos)
        reachable = set()
        queue = deque([0])
        reachable.add(0)
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if v not in reachable:
                    reachable.add(v)
                    queue.append(v)
        if agari not in reachable:
            print("NG")
            continue
        rev_graph = defaultdict(set)
        for u in graph:
            for v in graph[u]:
                rev_graph[v].add(u)
        nodes_reaching_agari = set()
        queue = deque([agari])
        nodes_reaching_agari.add(agari)
        while queue:
            u = queue.popleft()
            for v in rev_graph[u]:
                if v not in nodes_reaching_agari:
                    nodes_reaching_agari.add(v)
                    queue.append(v)
        reachable_non_agari = reachable - {agari}
        if not reachable_non_agari:
            print("OK")
            continue
        subgraph = defaultdict(set)
        for u in reachable_non_agari:
            for v in graph[u]:
                if v in reachable_non_agari:
                    subgraph[u].add(v)
        sccs = []
        index = 0
        indices = {}
        low = {}
        on_stack = set()
        stack = []
        def strongconnect(v):
            nonlocal index
            indices[v] = index
            low[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)
            for w in subgraph.get(v, set()):
                if w not in indices:
                    strongconnect(w)
                    low[v] = min(low[v], low[w])
                elif w in on_stack:
                    low[v] = min(low[v], indices[w])
            if low[v] == indices[v]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == v:
                        break
                sccs.append(scc)
        for u in reachable_non_agari:
            if u not in indices:
                strongconnect(u)
        found_ng = False
        for scc in sccs:
            has_cycle = (len(scc) > 1) or (scc[0] in subgraph.get(scc[0], set()))
            if has_cycle:
                can_reach = any(node in nodes_reaching_agari for node in scc)
                if not can_reach:
                    found_ng = True
                    break
        print("NG" if found_ng else "OK")

