                if mask & (1<<i):
                    subset.append(i+1)
            valid = True
            for i in range(q):
                item = required[i]
                opts = item_options[i]
                found = False
                for s in opts:
                    if s in subset:
                        found = True
                        break
                if not found:
                    valid = False
                    break
            if not valid:
                continue
            K = len(subset)
            if K ==0:
                if q ==0:
                    current_dist =0
                    if current_dist < min_distance:
                        min_distance = current_dist
                continue
            tsp_dist = INF
            index_map = {s: idx for idx, s in enumerate(subset)}
            dp = [[INF]*(1<<K) for _ in range(K)]
            for i in range(K):
                s = subset[i]
                dp[i][1<<i] = dist[0][s]
            for mask_tsp in range(1<<K):
                for curr in range(K):
                    if not (mask_tsp & (1<<curr)):
                        continue
                    current_cost = dp[curr][mask_tsp]
                    if current_cost == INF:
                        continue
                    for next_node in range(K):
                        if mask_tsp & (1<<next_node):
                            continue
                        new_mask = mask_tsp | (1<<next_node)
                        new_cost = current_cost + dist[subset[curr]][subset[next_node]]
                        if new_cost < dp[next_node][new_mask]:
                            dp[next_node][new_mask] = new_cost
            full_mask = (1<<K) -1
            for i in range(K):
                if dp[i][full_mask] != INF:
                    total = dp[i][full_mask] + dist[subset[i]][0]
                    if total < tsp_dist:
                        tsp_dist = total
            if tsp_dist < min_distance:
                min_distance = tsp_dist
        if min_distance == INF:
