import math
from itertools import combinations, permutations

def main():
    while True:
        line = sys.stdin.readline()
        if not line.strip():
            continue
        parts = list(map(int, line.strip().split()))
        if len(parts) < 2:
            break
        N, M = parts
        if N == 0 and M == 0:
            break
        R = []
        for _ in range(N):
            R.append(list(map(int, sys.stdin.readline().split())))
        if N == 1:
            print(1 if M == 1 else 0)
            continue

        h = math.ceil(math.log2(N))
        S = 1 << h
        total = 0

        for mask in combinations(range(S), N):
            valid_mask = True
            for i in range(0, S, 2):
                if i not in mask and i+1 not in mask:
                    valid_mask = False
                    break
            if not valid_mask:
                continue

            players = list(range(1, N+1))
            for perm in permutations(players):
                tournament = [0] * S
                pos_iter = iter(sorted(mask))
                for p in perm:
                    tournament[next(pos_iter)] = p

                current = []
                for i in range(S):
                    current.append(tournament[i] if tournament[i] != 0 else 0)

                level_size = S
                valid = True
                while level_size > 1:
                    next_level = []
                    for i in range(0, level_size, 2):
                        a = current[i]
                        b = current[i+1]
                        if a == 0 and b == 0:
                            valid = False
                            break
                        elif a == 0:
                            next_level.append(b)
                        elif b == 0:
                            next_level.append(a)
                        else:
                            if R[a-1][b-1]:
                                next_level.append(a)
                            else:
                                next_level.append(b)
                    if not valid:
                        break
                    current = next_level
                    level_size >>= 1

                if valid and len(current) == 1 and current[0] == M:
                    total += 1
        print(total)

