import sys
from collections import deque, defaultdict

def main():
    X, Y, Z, N, M, S, T = map(int, sys.stdin.readline().split())
    sandwiches = []
    for _ in range(N):
        A, B = map(int, sys.stdin.readline().split())
        sandwiches.append((A, B))
    curries = []
    for _ in range(M):
        C, D = map(int, sys.stdin.readline().split())
        curries.append((C, D))

    # Precompute dictionaries
    sand_to_sandwiches = defaultdict(list)
    cutlet_to_sandwiches = defaultdict(list)
    for idx in range(N):
        A, B = sandwiches[idx]
        sand_to_sandwiches[A].append(idx + 1)
        cutlet_to_sandwiches[B].append(idx + 1)

    cutlet_to_curries = defaultdict(list)
    curry_to_curries = defaultdict(list)
    for idx in range(M):
        C, D = curries[idx]
        cutlet_to_curries[C].append(idx + 1)
        curry_to_curries[D].append(idx + 1)

    processed_sands = set()
    processed_cutlets = set()
    processed_curries = set()

    visited_sand = [False] * (N + 1)
    visited_curry = [False] * (M + 1)

    queue = deque()
    visited_sand[S] = True
    queue.append(('s', S, 0))

    answer = -1

    while queue:
        type_, id_, steps = queue.popleft()

        if type_ == 'c' and id_ == T:
            answer = steps
            break

        if type_ == 's':
            A, B = sandwiches[id_ - 1]
            if A not in processed_sands:
                processed_sands.add(A)
                for s_id in sand_to_sandwiches[A]:
                    if not visited_sand[s_id]:
                        visited_sand[s_id] = True
                        queue.append(('s', s_id, steps + 1))
            if B not in processed_cutlets:
                processed_cutlets.add(B)
                for s_id in cutlet_to_sandwiches[B]:
                    if not visited_sand[s_id]:
                        visited_sand[s_id] = True
                        queue.append(('s', s_id, steps + 1))
                for c_id in cutlet_to_curries[B]:
                    if not visited_curry[c_id]:
                        visited_curry[c_id] = True
                        queue.append(('c', c_id, steps + 1))
        else:
            C, D = curries[id_ - 1]
            if C not in processed_cutlets:
                processed_cutlets.add(C)
                for c_id in cutlet_to_curries[C]:
                    if not visited_curry[c_id]:
                        visited_curry[c_id] = True
                        queue.append(('c', c_id, steps + 1))
                for s_id in cutlet_to_sandwiches[C]:
                    if not visited_sand[s_id]:
                        visited_sand[s_id] = True
                        queue.append(('s', s_id, steps + 1))
            if D not in processed_curries:
                processed_curries.add(D)
                for c_id in curry_to_curries[D]:
                    if not visited_curry[c_id]:
                        visited_curry[c_id] = True
                        queue.append(('c', c_id, steps + 1))

    print(answer if answer != -1 else -1)

