    n = len(s)
    divisors = []
    for d in range(1, n + 1):
        if n % d == 0:
            divisors.append(d)
    for d in divisors:
        base = s[:d]
        k = n // d
        if base * k == s:
            return (base, k)
    return (s, 1)

