import math

def convex_hull(points):
    points = sorted(points)
    if len(points) <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and (lower[-1][0] - lower[-2][0])*(p[1] - lower[-1][1]) - (lower[-1][1] - lower[-2][1])*(p[0] - lower[-1][0]) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and (upper[-1][0] - upper[-2][0])*(p[1] - upper[-1][1]) - (upper[-1][1] - upper[-2][1])*(p[0] - upper[-1][0]) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def point_in_convex_polygon(point, polygon):
    cross = None
    for i in range(len(polygon)):
        a = polygon[i]
        b = polygon[(i+1)%len(polygon)]
        ab = (b[0] - a[0], b[1] - a[1])
        ap = (point[0] - a[0], point[1] - a[1])
        current_cross = ab[0] * ap[1] - ab[1] * ap[0]
        if current_cross == 0:
            continue
        if cross is None:
            cross = current_cross
        else:
            if (cross > 0) != (current_cross > 0):
                return False
    return True

def polygon_area(polygon):
    area = 0.0
    n = len(polygon)
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i+1)%n]
        area += (x1 * y2 - x2 * y1)
    return abs(area) / 2.0

