def main():
    import sys
    N, A, B, C, D = map(int, sys.stdin.readline().split())
    max_n = N
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n -1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    dp = [0] * (N + 1)
    dp[0] = 1

    for s in range(A, B +1):
        new_dp = dp.copy()
        for m in range(C, D +1):
            if m == 0:
                continue
            k = m * s
            if k > N:
                continue
            term = pow(inv_fact[s], m, MOD)
            term = term * inv_fact[m] % MOD
            for n in range(N - k +1):
                if dp[n]:
                    new_dp[n + k] = (new_dp[n + k] + dp[n] * term) % MOD
        dp = new_dp

    ans = dp[N] * fact[N] % MOD
    print(ans)

