import sys

def josephus_simulation(n, m):
    people = list(range(1, n + 1))
    current_pos = n - 1  # initial position is the last person (n)
    while len(people) > 1:
        for _ in range(m):
            current_pos = (current_pos + 1) % len(people)
        people.pop(current_pos)
        current_pos = current_pos % len(people) if people else 0
    return people[0]

