class Node:
    __slots__ = ['start', 'end', 'left', 'right', 'count']
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.count = 0

root = Node(0, 10**9)

def insert(x):
    def _insert(node):
        if node.start == node.end:
            if node.count == 0:
                node.count = 1
                return True
            return False
        mid = (node.start + node.end) // 2
        if x <= mid:
            if not node.left:
                node.left = Node(node.start, mid)
            if _insert(node.left):
                node.count += 1
                return True
            else:
                return False
        else:
            if not node.right:
                node.right = Node(mid + 1, node.end)
            if _insert(node.right):
                node.count += 1
                return True
            else:
                return False
    return _insert(root)

def delete(x):
    def _delete(node):
        if node.start == node.end:
            if node.count == 1:
                node.count = 0
                return True
            return False
        mid = (node.start + node.end) // 2
        deleted = False
        if x <= mid:
            if node.left:
                deleted = _delete(node.left)
        else:
            if node.right:
                deleted = _delete(node.right)
        if deleted:
            node.count -= 1
        return deleted
    return _delete(root)

