import math

def compute_phi(n):
    if n == 0:
        return 0
    phi = n
    i = 2
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n = n // i
            phi -= phi // i
        i += 1
    if n > 1:
        phi -= phi // n
    return phi

