    if r < 0:
        return -1
    if r == 0:
        return 0
    if r < 4:
        return -1
    if r % 2 == 0:
        if r % 4 == 0:
            return r // 4
        else:
            if r >= 6:
                return (r - 6) // 4 + 1
            else:
                return -1
    else:
        if r < 9:
            return -1
        if r == 9:
            return 1
        rem = r - 9
        if rem < 4 or rem % 2 != 0:
            return -1
        if rem % 4 == 0:
            cnt = rem // 4
        else:
            if rem >= 6:
                cnt = (rem - 6) // 4 + 1
            else:
                return -1
        return 1 + cnt

