from collections import defaultdict

fact = [1] * 5
for i in range(1, 5):
    fact[i] = fact[i-1] * i

def generate_distributions(n, N):
    if N == 1:
        yield (n,)
    else:
        for first in range(n + 1):
            for rest in generate_distributions(n - first, N - 1):
                yield (first,) + rest

def main():
    test_case = 0
    while True:
        line = sys.stdin.readline()
        while line.strip() == '':
            line = sys.stdin.readline()
        N = int(line.strip())
        if N == 0:
            break
        test_case += 1

        p = []
        for _ in range(N):
            while True:
                line = sys.stdin.readline()
                if line.strip() != '':
                    break
            row = list(map(float, line.strip().split()))
            p.append(row)

        while True:
            line = sys.stdin.readline()
            if line.strip() != '':
                break
        required_n = list(map(int, line.strip().split()))

        all_zero = all(x == 0 for x in required_n)
        if all_zero:
            print(f"Case {test_case}: 0.00000000")
            continue

        if sum(required_n) == 0:
            print(f"Case {test_case}: -INFINITY")
            continue

        drinks = []
        for i in range(N):
            ni = required_n[i]
            if ni == 0:
                continue
            distributions = []
            for dist in generate_distributions(ni, N):
                multinom = fact[ni]
                for kj in dist:
                    multinom //= fact[kj]
                prob = 1.0
                for j in range(N):
                    prob *= (p[i][j] ** dist[j])
                distributions.append((dist, multinom * prob))
            drinks.append(distributions)

        dp = defaultdict(float)
        initial_state = tuple([0]*N)
        dp[initial_state] = 1.0

        for distributions in drinks:
            new_dp = defaultdict(float)
            for state in dp:
                current_prob = dp[state]
                for (dist, prob) in distributions:
                    new_state = list(state)
                    valid = True
                    for j in range(N):
                        new_state[j] += dist[j]
                        if new_state[j] > required_n[j]:
                            valid = False
                            break
                    if not valid:
                        continue
                    new_state_tuple = tuple(new_state)
                    new_dp[new_state_tuple] += current_prob * prob
            dp = new_dp
            if not dp:
                break

        target = tuple(required_n)
        if target not in dp or dp[target] <= 0:
            print(f"Case {test_case}: -INFINITY")
        else:
            log_prob = log(dp[target])
            print(f"Case {test_case}: {log_prob:.8f}")

