class Node:
    __slots__ = ['key', 'left', 'right']
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

def insert(root, key):
    new_node = Node(key)
    if root is None:
        return new_node
    current = root
    while True:
        if key < current.key:
            if current.left is None:
                current.left = new_node
                break
            else:
                current = current.left
        elif key > current.key:
            if current.right is None:
                current.right = new_node
                break
            else:
                current = current.right
        else:
            break  # No duplicates per problem constraints
    return root

def find(root, key):
    current = root
    while current is not None:
        if current.key == key:
            return True
        elif key < current.key:
            current = current.left
        else:
            current = current.right
    return False

def inorder(node, res):
    if node is not None:
        inorder(node.left, res)
        res.append(node.key)
        inorder(node.right, res)

def preorder(node, res):
    if node is not None:
        res.append(node.key)
        preorder(node.left, res)
        preorder(node.right, res)

