import sys

def square_free(x):
    if x == 1:
        return 1
    res = 1
    cnt = 0
    while x % 2 == 0:
        cnt += 1
        x = x // 2
    if cnt % 2 == 1:
        res *= 2
    i = 3
    while i * i <= x:
        cnt = 0
        while x % i == 0:
            cnt += 1
            x = x // i
        if cnt % 2 == 1:
            res *= i
        i += 2
    if x > 1:
        res *= x
    return res

