import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))

    # Bipartition the grid into two colors like a chessboard
    black = []
    white = []
    for i in range(n):
        for j in range(m):
            if (i + j) % 2 == 0:
                black.append((i, j))
            else:
                white.append((i, j))

    # Build adjacency list with costs
    adj = [[] for _ in range(len(black))]
    for i, (bi, bj) in enumerate(black):
        for dir in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = bi + dir[0], bj + dir[1]
            if 0 <= ni < n and 0 <= nj < m:
                for k, (wi, wj) in enumerate(white):
                    if (ni, nj) == (wi, wj):
                        cost = 0 if grid[bi][bj] == grid[ni][nj] else 1
                        adj[i].append((k, cost))
                        break

    # Hungarian Algorithm for Bipartite Matching (min weight)
    def hungarian():
        U = len(black)
        V = len(white)
        assert U == V, "Not a bipartite graph with equal partitions"
        INF = float('inf')
        mu = [-1] * U
        mv = [-1] * V
        cost = 0

        for u in range(U):
            in_U = [False] * U
            in_V = [False] * V
            prev = [-1] * V
            C = [INF] * V
            C[0] = 0  # start with the first vertex in V
            end = -1
            while True:
                min_val = INF
                for v in range(V):
                    if not in_V[v] and C[v] < min_val:
                        min_val = C[v]
                        v_sel = v
                if min_val == INF:
                    break
                in_V[v_sel] = True
                u2 = mv[v_sel]
                if u2 == -1:
                    end = v_sel
                    break
                in_U[u2] = True
                for v_next in range(V):
                    if not in_V[v_next]:
                        new_cost = C[v_sel] + (0 if grid[black[u2][0]][black[u2][1]] == grid[white[v_next][0]][white[v_next][1]] else 1)
                        if C[v_next] > new_cost:
                            C[v_next] = new_cost
                            prev[v_next] = v_sel
            if end == -1:
                return -1  # no matching
            while True:
                v_prev = prev[end]
                u_prev = mu[v_prev]
                mu[v_prev] = end
                mv[end] = v_prev
                end = v_prev
                if end == 0:
                    break
            cost += C[end]
        return cost

    total_cost = hungarian()
    print(total_cost * 2)

