    for i in range(1, max_len + 2):
        pow10[i] = (pow10[i-1] * 10) % M

    inv10 = pow(10, -1, M) if M != 1 else 0
    inv_pow10 = [1] * (max_len + 2)
    for i in range(1, max_len + 2):
        inv_pow10[i] = (inv_pow10[i-1] * inv10) % M

    total = 0

    visited = [False] * n

    def get_size(u, parent):
        size = 1
        for v, _ in edges[u]:
            if v != parent and not visited[v]:
                size += get_size(v, u)
        return size

    def get_centroid(u, parent, desired):
        sz = 1
        max_c_size = 0
        centroid = -1
        for v, _ in edges[u]:
            if v == parent or visited[v]:
                continue
            c_size = get_size(v, u)
            sz += c_size
            if c_size > max_c_size:
                max_c_size = c_size
                centroid = v
        if max_c_size <= desired // 2 and sz > desired // 2:
            return u
        return get_centroid(centroid, u, desired)

    def decompose(u):
        nonlocal total
        size = get_size(u, -1)
        if size == 1:
            visited[u] = True
            return
        centroid = get_centroid(u, -1, size)
        visited[centroid] = True

        up_map = defaultdict(int)
        down_map = defaultdict(int)

        for v, w in edges[centroid]:
            if visited[v]:
                continue

            subtree = []
            q = deque()
            q.append((v, centroid, w, 1))
            up_vals = []
            down_vals = []

            while q:
