                    down_val = (down_val_prev * 10 + weight) % M
                up_vals.append((up_val, depth))
                down_vals.append((down_val, depth))
                subtree.append(node)
                for child, w_child in edges[node]:
                    if child != parent and not visited[child]:
                        q.append((child, node, w_child, depth + 1))
                        up_val_prev = up_val
                        down_val_prev = down_val

            temp_up = defaultdict(int)
            temp_down = defaultdict(int)

            for up_val, l in up_vals:
                temp_up[up_val] += 1
                req_down = (-up_val * pow10[l]) % M
                total += down_map.get(req_down, 0)
                if up_val == 0:
