            for down_val, m in down_vals:
                temp_down[down_val] += 1
                req_up = (-down_val * inv_pow10[m]) % M
                total += up_map.get(req_up, 0)
                if down_val == 0:
                    total += 1

            for key in temp_up:
                up_map[key] += temp_up[key]
            for key in temp_down:
                down_map[key] += temp_down[key]

        for v, _ in edges[centroid]:
            if not visited[v]:
                decompose(v)

    decompose(0)
