def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    t = list(map(int, input[1:N+1]))
    max_t = max(t)

    # Find all divisors of max_t
    def get_divisors(n):
        divisors = set()
        for i in range(1, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return sorted(divisors)

    divisors = get_divisors(max_t)

    total = 0
    for ti in t:
        # Find the smallest divisor >= ti
        # Binary search
        left = 0
        right = len(divisors)
        while left < right:
            mid = (left + right) // 2
            if divisors[mid] >= ti:
                right = mid
            else:
                left = mid + 1
        if left == len(divisors):
            # Not possible, but max_t >= ti and max_t is a divisor
            d = max_t
        else:
            d = divisors[left]
        total += d - ti
    print(total)

