import sys
from collections import deque

def bfs(start_x, start_y, target_x, target_y, grid, h, w):
    if start_x == target_x and start_y == target_y:
        return 0
    dist = [[-1] * w for _ in range(h)]
    q = deque()
    q.append((start_x, start_y))
    dist[start_y][start_x] = 0
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while q:
        x, y = q.popleft()
        current_dist = dist[y][x]
        for dx, dy in directions:
            nx = x + dx
            ny = y + dy
            if 0 <= nx < w and 0 <= ny < h:
                if grid[ny][nx] != 'x' and dist[ny][nx] == -1:
                    dist[ny][nx] = current_dist + 1
                    if nx == target_x and ny == target_y:
                        return dist[ny][nx]
                    q.append((nx, ny))
    return -1

def main():
    while True:
        w, h = map(int, sys.stdin.readline().split())
        if w == 0 and h == 0:
            break
        grid = []
        start = None
        dirties = []
        for y in range(h):
            line = sys.stdin.readline().strip()
            grid.append(line)
            for x, c in enumerate(line):
                if c == 'o':
                    start = (x, y)
                elif c == '*':
                    dirties.append((x, y))
        m = len(dirties)
        if m == 0:
            print(0)
            continue
        # Check if all dirties are reachable from start
        valid = True
        for (x, y) in dirties:
            if bfs(start[0], start[1], x, y, grid, h, w) == -1:
                valid = False
                break
        if not valid:
            print(-1)
            continue
        nodes = [start] + dirties
        distance = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            for j in range(m + 1):
                if i == j:
                    distance[i][j] = 0
                else:
                    ix, iy = nodes[i]
                    jx, jy = nodes[j]
                    d = bfs(ix, iy, jx, jy, grid, h, w)
                    distance[i][j] = d
                    if d == -1:
                        valid = False
        if not valid:
            print(-1)
            continue
        INF = float('inf')
        dp = [[INF] * (m + 1) for _ in range(1 << m)]
        dp[0][0] = 0
        for mask in range(0, 1 << m):
            for u in range(m + 1):
                if dp[mask][u] == INF:
                    continue
                for v in range(1, m + 1):
                    bit = v - 1
                    if not (mask & (1 << bit)):
                        new_mask = mask | (1 << bit)
                        new_cost = dp[mask][u] + distance[u][v]
                        if new_cost < dp[new_mask][v]:
                            dp[new_mask][v] = new_cost
        full_mask = (1 << m) - 1
        result = min(dp[full_mask][1:m+1])
        print(result if result != INF else -1)

