    main()

import sys
import re

def parse_array_access(s):
    bracket_pos = s.find('[')
    if bracket_pos == -1:
        raise ValueError
    array_name = s[:bracket_pos]
    count = 1
    i = bracket_pos + 1
    n = len(s)
    while i < n:
        if s[i] == '[':
            count += 1
        elif s[i] == ']':
            count -= 1
            if count == 0:
                index_expr = s[bracket_pos+1:i]
                return (array_name, index_expr)
        i += 1
    raise ValueError

def evaluate_expression(expr, arrays):
    if expr.isdigit():
        return int(expr)
    else:
        array_name, index_expr = parse_array_access(expr)
        index = evaluate_expression(index_expr, arrays)
        if array_name not in arrays:
            raise ValueError
        size, values = arrays[array_name]
        if not (0 <= index < size):
            raise ValueError
        if index not in values:
            raise ValueError
        return values[index]

def main():
    lines = [line.rstrip('\n') for line in sys.stdin]
    datasets = []
    current_dataset = []
    for line in lines:
        if line == '.':
            if current_dataset:
                datasets.append(current_dataset)
                current_dataset = []
        else:
            current_dataset.append(line)
    if current_dataset:
        datasets.append(current_dataset)
    for program in datasets:
        arrays = {}
        bug_line = 0
        line_number = 0
        for line in program:
            line_number += 1
            if re.fullmatch(r'^[a-zA-Z]+\[\d+\]$', line):
                match = re.match(r'^([a-zA-Z]+)\[(\d+)\]$', line)
                array_name, size = match.group(1), int(match.group(2))
                arrays[array_name] = (size, {})
            else:
                try:
                    lhs, rhs = line.split('=', 1)
                    lhs = lhs.strip()
                    rhs = rhs.strip()
                    array_name, index_expr = parse_array_access(lhs)
                    index = evaluate_expression(index_expr, arrays)
                    if array_name not in arrays:
                        bug_line = line_number
                        break
                    size, values = arrays[array_name]
                    if not (0 <= index < size):
                        bug_line = line_number
                        break
                    rhs_value = evaluate_expression(rhs, arrays)
                    values[index] = rhs_value
                except ValueError:
                    bug_line = line_number
                    break
                except:
                    bug_line = line_number
                    break
            if bug_line:
                break
        print(bug_line if bug_line else 0)

