import sys
from math import gcd
from itertools import product

def read_poly(n):
    pts = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    return pts

def convex_hull(pts):
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    pts = sorted(pts)
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def area(pts):
    n = len(pts)
    s = 0
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i+1)%n]
        s += x1 * y2 - x2 * y1
    return abs(s) // 2

def check_convex(pts):
    n = len(pts)
    if n < 3:
        return False
    for i in range(n):
        a, b, c = pts[i], pts[(i+1)%n], pts[(i+2)%n]
        cross = (b[0]-a[0])*(c[1]-b[1]) - (b[1]-a[1])*(c[0]-b[0])
        if cross < 0:
            return False
    return True

def generate_candidates():
    candidates = []
    for a, b, c, d in product(range(3), repeat=4):
        if a*d - b*c == 1:
            candidates.append((a, b, c, d))
    return candidates

def main():
    while True:
        n, m = map(int, sys.stdin.readline().split())
        if n == 0 and m == 0:
            break
        R = read_poly(n)
        S = read_poly(m)
        min_sum = float('inf')
        candidates = generate_candidates()
        for a, b, c, d in candidates:
            P_pts = []
            for (rx, ry) in R:
                for (sx, sy) in S:
                    px = d * rx - b * sx
                    py = d * ry - b * sy
                    P_pts.append((px, py))
            P_hull = convex_hull(P_pts)
            if not check_convex(P_hull):
                continue
            Q_pts = []
            for (rx, ry) in R:
                for (sx, sy) in S:
                    qx = -c * rx + a * sx
                    qy = -c * ry + a * sy
                    Q_pts.append((qx, qy))
            Q_hull = convex_hull(Q_pts)
            if not check_convex(Q_hull):
                continue
            area_P = area(P_hull)
            area_Q = area(Q_hull)
            min_sum = min(min_sum, area_P + area_Q)
        print(min_sum * 2)

