import sys
from collections import deque

def main():
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    total = sum(a)
    if total < k:
        print(-1)
        return
    queue = deque()
    for i in range(n):
        if a[i] > 0:
            queue.append((i, a[i]))
    while queue and k > 0:
        m = min(a for _, a in queue)
        current_length = len(queue)
        steps_in_batch = m * current_length
        if steps_in_batch <= k:
            k -= steps_in_batch
            new_queue = deque()
            for i, ai in queue:
                new_a = ai - m
                if new_a > 0:
                    new_queue.append((i, new_a))
            queue = new_queue
        else:
            steps = k
            for _ in range(steps):
                if not queue:
                    break
                i, ai = queue.popleft()
                ai -= 1
                if ai > 0:
                    queue.append((i, ai))
            k = 0
    print(' '.join(str(i + 1) for i, _ in queue))

