MOD = 10**9 + 7

def main():
    import sys
    K = int(sys.stdin.readline())
    N = sys.stdin.readline().strip()
    digits = list(map(int, N))
    n = len(digits)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, sum_so_far, count, non_zero):
        if pos == n:
            return count % MOD
        res = 0
        max_digit = digits[pos] if tight else 9
        for d in range(0, max_digit + 1):
            new_tight = tight and (d == max_digit)
            new_non_zero = non_zero or (d != 0)
            current_l = 0
            if new_non_zero:
                if d == 4 or d == 7:
                    current_l = 1
            new_sum = sum_so_far + current_l
            new_count = count
            if new_sum > K:
                new_count = (new_count + 1) % MOD
                new_sum_after = 0
            else:
                new_sum_after = new_sum
            res = (res + dp(pos + 1, new_tight, new_sum_after, new_count, new_non_zero)) % MOD
        if not non_zero:
            res = (res + dp(pos + 1, False, 0, count, False)) % MOD
        return res % MOD

    total = dp(0, True, 0, 0, False)

    def subtract_one(num_str):
        num = list(num_str)
        i = len(num) - 1
        while i >= 0 and num[i] == '0':
            num[i] = '9'
            i -= 1
        if i >= 0:
            num[i] = str(int(num[i]) - 1)
        if num[0] == '0' and len(num) > 1:
            num = num[1:]
        return ''.join(num)

    N_minus_1 = subtract_one(N)
    if N_minus_1 == '':
        N_minus_1 = '0'
    digits_minus_1 = list(map(int, N_minus_1))
    m = len(digits_minus_1)

    @lru_cache(maxsize=None)
    def dp_minus(pos, tight, sum_so_far, count, non_zero):
        if pos == m:
            return count % MOD
        res = 0
        max_digit = digits_minus_1[pos] if tight else 9
        for d in range(0, max_digit + 1):
            new_tight = tight and (d == max_digit)
            new_non_zero = non_zero or (d != 0)
            current_l = 0
            if new_non_zero:
                if d == 4 or d == 7:
                    current_l = 1
            new_sum = sum_so_far + current_l
            new_count = count
            if new_sum > K:
                new_count = (new_count + 1) % MOD
                new_sum_after = 0
            else:
                new_sum_after = new_sum
            res = (res + dp_minus(pos + 1, new_tight, new_sum_after, new_count, new_non_zero)) % MOD
        if not non_zero:
            res = (res + dp_minus(pos + 1, False, 0, count, False)) % MOD
        return res % MOD

    total_minus = dp_minus(0, True, 0, 0, False)
    answer = (total - total_minus) % MOD
    print(answer)

