import numpy as np
from itertools import permutations

def read_tree(n):
    nodes = [np.array(list(map(int, input().split())), dtype=float) for _ in range(n)]
    edges = set()
    for _ in range(n-1):
        u, v = map(int, input().split())
        if u > v:
            u, v = v, u
        edges.add((u-1, v-1))  # converting to 0-based index
    return nodes, edges

def is_isomorphic(n, edges1, edges2, mapping):
    # Check if the mapping preserves adjacency
    reverse_mapping = {v: k for k, v in enumerate(mapping)}
    for u, v in edges1:
        nu = mapping[u]
        nv = mapping[v]
        if nu > nv:
            nu, nv = nv, nu
        if (nu, nv) not in edges2:
            return False
    return True

def check_geometric(p_list, q_list):
    n = len(p_list)
    if n == 0:
        return False
    p0 = p_list[0]
    q0 = q_list[0]
    if n == 1:
        return np.allclose(p0, q0)
    vectors_p = []
    vectors_q = []
    for i in range(1, n):
        vp = p_list[i] - p0
        vq = q_list[i] - q0
        if np.linalg.norm(vp) < 1e-8:
            if np.linalg.norm(vq) > 1e-8:
                return False
            continue
        vectors_p.append(vp)
        vectors_q.append(vq)
    if not vectors_p:
        return np.allclose(p_list, q_list)
    s = None
    for vp, vq in zip(vectors_p, vectors_q):
        nv_p = np.linalg.norm(vp)
        nv_q = np.linalg.norm(vq)
        if nv_p < 1e-8:
            if nv_q >= 1e-8:
                return False
            continue
        if s is None:
            s = nv_q / nv_p
            if s <= 1e-8:
                return False
        else:
            if not np.isclose(nv_q, s * nv_p, atol=1e-6):
                return False
    if s is None:
        s = 1.0
    vectors_p = [vp for vp in vectors_p if np.linalg.norm(vp) > 1e-8]
    vectors_q = [vq for vq in vectors_q if np.linalg.norm(vq) > 1e-8]
    if len(vectors_p) < 1:
        t = q0 - s * p0
        valid = all(np.allclose(s * p + t, q) for p, q in zip(p_list, q_list))
        return valid
    A = np.array(vectors_p)
    B = np.array(vectors_q) / s
    H = A.T @ B
    U, S, Vt = np.linalg.svd(H)
    R = Vt.T @ U.T
    if np.linalg.det(R) < 0:
        Vt[-1, :] *= -1
        R = Vt.T @ U.T
    t = q0 - s * (R @ p0)
    valid = True
    for p, q in zip(p_list, q_list):
        q_pred = s * (R @ p) + t
        if not np.allclose(q_pred, q, atol=1e-6):
            valid = False
            break
    return valid

def main():
    n = int(input())
    nodes1, edges1 = read_tree(n)
    nodes2, edges2 = read_tree(n)
    if len(edges1) != len(edges2):
        print(0)
        return
    nodes2_indices = list(range(n, 2*n))
    count = 0
    for perm in permutations(nodes2_indices):
        perm = list(perm)
        if not is_isomorphic(n, edges1, edges2, perm):
            continue
        mapped_nodes1 = [nodes1[i] for i in range(n)]
        mapped_nodes2 = [nodes2[pi - n] for pi in perm]
        if check_geometric(mapped_nodes1, mapped_nodes2):
            count += 1
    print(count)

