            Qj = int(input[ptr]); ptr +=1
            products[Rj] = Qj
        cities.append( (Xj, Yj, products) )

    trips = []
    for mask in range(1, 1 << N):
        subset = [i for i in range(N) if (mask & (1 << i))]
        min_time = float('inf')
        for perm in permutations(subset):
            time = 0
            prev_x, prev_y = 0, 0
            for city_idx in perm:
                x, y, _ = cities[city_idx]
                dx = abs(x - prev_x)
                dy = abs(y - prev_y)
                time += dx + dy
                prev_x, prev_y = x, y
            time += prev_x + prev_y
            if time < min_time:
                min_time = time
        if min_time > T:
            continue
        product_min_price = {}
        for city_idx in subset:
            _, _, city_products = cities[city_idx]
            for p_name, price in city_products.items():
