            v, p = products_info[p_name]
            if p > min_p:
                items.append( (v, p - min_p) )
        dp_sub = [0] * (W + 1)
        for v, profit in items:
            for w in range(v, W + 1):
                if dp_sub[w - v] + profit > dp_sub[w]:
                    dp_sub[w] = dp_sub[w - v] + profit
        max_profit = dp_sub[W]
