def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '(' and i + 1 < n and s[i+1] == ')':
            tokens.append('()')
            i += 2
        else:
            tokens.append(s[i])
            i += 1
    return tokens

def main():
    import sys
    input_str = sys.stdin.read().strip()
    tokens = tokenize(input_str)

    stack = []
    memo = {}
    node_info = {0: (None, None, 0)}  # leaf: (left, right, pastes)
    current_id = 1

    for token in tokens:
        if token == '()':
            stack.append((0, 0))
        elif token == '(':
            stack.append(None)
        elif token == ')':
            elements = []
            while stack[-1] is not None:
                elements.append(stack.pop())
            stack.pop()  # Remove the None marker

            if len(elements) != 2:
                raise ValueError("Invalid input")
            right = elements[0]
            left = elements[1]
            left_id, left_pastes = left
            right_id, right_pastes = right

            if left_id == right_id:
                if left_id == 0 and right_id == 0:
                    pastes = 0
                else:
                    pastes = left_pastes + 1
            else:
                pastes = left_pastes + right_pastes

            key = (left_id, right_id)
            if key in memo:
                branch_id = memo[key]
            else:
                branch_id = current_id
                memo[key] = branch_id
                node_info[branch_id] = (left_id, right_id, pastes)
                current_id += 1
            stack.append((branch_id, node_info[branch_id][2]))

    if len(stack) != 1:
        raise ValueError("Invalid input structure")

    root_id, root_pastes = stack[0]
    left_id, right_id, _ = node_info[root_id]

    if left_id == 0 and right_id == 0:
        print(0)
    else:
        print(root_pastes)

