import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    while True:
        n = int(input[ptr])
        m = int(input[ptr+1])
        ptr +=2
        if n ==0 and m ==0:
            break
        edges = []
        for _ in range(m):
            s = int(input[ptr])-1
            t = int(input[ptr+1])-1
            c = int(input[ptr+2])
            ptr +=3
            edges.append( (c, s, t) )
        edges.sort()
        sorted_costs = [c for c, s, t in edges]
        k = (n-2)//2
        required = k +1

        left = 0
        right = len(sorted_costs)-1
        answer = None

        def is_possible(c_val):
            a_edges = []
            b_edges = []
            for edge in edges:
                if edge[0] <= c_val:
                    a_edges.append(edge)
                else:
                    b_edges.append(edge)
            parent = list(range(n))
            rank = [1]*n

            def find(u):
                while parent[u] != u:
                    parent[u] = parent[parent[u]]
                    u = parent[u]
                return u

            def union(u, v):
                u_root = find(u)
                v_root = find(v)
                if u_root == v_root:
                    return False
                if rank[u_root] < rank[v_root]:
                    parent[u_root] = v_root
                else:
                    parent[v_root] = u_root
                    if rank[u_root] == rank[v_root]:
                        rank[u_root] +=1
                return True

            a_count =0
            for c_e, s, t in a_edges:
                if union(s, t):
                    a_count +=1
            for c_e, s, t in b_edges:
                union(s, t)
            root = find(0)
            for u in range(1, n):
                if find(u) != root:
                    return False
            return a_count >= required

        while left <= right:
            mid = (left + right) //2
            c = sorted_costs[mid]
            if is_possible(c):
                answer = c
                right = mid -1
            else:
                left = mid +1
        print(answer)

