import sys

def find_bridges():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    disc = [-1] * n
    low = [-1] * n
    time = 0
    bridges = []
    stack = []

    for start in range(n):
        if disc[start] == -1:
            stack.append((start, -1, False))
            while stack:
                node, parent_node, visited = stack.pop()
                if not visited:
                    if disc[node] != -1:
                        continue
                    disc[node] = time
                    low[node] = time
                    time += 1
                    stack.append((node, parent_node, True))
                    for neighbor in adj[node]:
                        if neighbor == parent_node:
                            continue
                        if disc[neighbor] == -1:
                            stack.append((neighbor, node, False))
                        else:
                            low[node] = min(low[node], disc[neighbor])
                else:
                    for neighbor in adj[node]:
                        if neighbor == parent_node:
                            continue
                        if disc[neighbor] > disc[node]:
                            low[node] = min(low[node], low[neighbor])
                            if low[neighbor] > disc[node]:
                                u, v = sorted((node, neighbor))
                                bridges.append((u, v))

    bridges = sorted(list(set(bridges)))
    for u, v in bridges:
        print(u, v)

