from functools import lru_cache

def main():
    import sys
    r, s, p = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dp(r, s, p):
        if r == 0 and s == 0:
            return (0.0, 0.0, 1.0)
        if s == 0 and p == 0:
            return (1.0, 0.0, 0.0)
        if r == 0 and p == 0:
            return (0.0, 1.0, 0.0)
        if p == 0:
            return (1.0, 0.0, 0.0) if r > 0 and s > 0 else (0.0, 0.0, 0.0)
        if r == 0:
            return (0.0, 1.0, 0.0) if s > 0 and p > 0 else (0.0, 0.0, 0.0)
        if s == 0:
            return (0.0, 0.0, 1.0) if p > 0 and r > 0 else (0.0, 0.0, 0.0)
        total = r * s + s * p + p * r
        pr = ps = pp = 0.0
        # Rock and Scissors meet
        if s >= 1:
            c_r, c_s, c_p = dp(r, s-1, p)
            pr += r * s * c_r
            ps += r * s * c_s
            pp += r * s * c_p
        # Scissors and Paper meet
        if p >= 1:
            c_r, c_s, c_p = dp(r, s, p-1)
            pr += s * p * c_r
            ps += s * p * c_s
            pp += s * p * c_p
        # Paper and Rock meet
        if r >= 1:
            c_r, c_s, c_p = dp(r-1, s, p)
            pr += p * r * c_r
            ps += p * r * c_s
            pp += p * r * c_p
        pr /= total
        ps /= total
        pp /= total
        return (pr, ps, pp)

    rock, scissors, paper = dp(r, s, p)
    print("{0:.12f} {1:.12f} {2:.12f}".format(rock, scissors, paper))

