import math

def compute_lps(s):
    n = len(s)
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length-1]
            else:
                lps[i] = 0
                i += 1
    return lps

def compute_z(s):
    n = len(s)
    Z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i > r:
            l = r = i
            while r < n and s[r - l] == s[r]:
                r += 1
            Z[i] = r - l
            r -= 1
        else:
            k = i - l
            if Z[k] < r - i + 1:
                Z[i] = Z[k]
            else:
                l = i
                while r < n and s[r - l] == s[r]:
                    r += 1
                Z[i] = r - l
                r -= 1
    return Z

def build_sparse_table(arr):
    n = len(arr)
    if n == 0:
        return []
    k = math.floor(math.log2(n)) if n else 0
    st = [[0] * n for _ in range(k+1)]
    st[0] = arr.copy()
    for j in range(1, k+1):
        for i in range(n - (1 << j) + 1):
            st[j][i] = max(st[j-1][i], st[j-1][i + (1 << (j-1))])
    return st

def query_sparse_table(st, l, r):
    if l > r:
        return -1
    length = r - l + 1
    k = length.bit_length() - 1
    if (1 << k) > length:
        k -= 1
    if k < 0:
        return -1
    max_val = max(st[k][l], st[k][r - (1 << k) + 1])
    return max_val

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    T = int(data[idx])
    idx += 1
    for _ in range(T):
        s = data[idx]
        K = int(data[idx+1])
        idx +=2
        n = len(s)
        if n == 0:
            print("Puchi is a cheat!")
            continue
        lps = compute_lps(s)
        candidates = []
        current = lps[-1] if n > 0 else 0
        while current > 0:
            candidates.append(current)
            current = lps[current -1] if current > 0 else 0
        Z = compute_z(s)
        st = build_sparse_table(Z)
        found = False
        for L in candidates:
            if L == 0:
                continue
            if L > K:
                continue
            end = K - L
            if end < 1:
                continue
            if end >= len(Z):
                end = len(Z) -1
            max_z = query_sparse_table(st, 1, end)
            if max_z >= L:
                print(s[:L])
                found = True
                break
        if not found:
            print("Puchi is a cheat!")

