from collections import defaultdict

def main():
    # Read the first line of input
    first_line = sys.stdin.readline().strip().split()
    N, M, X, Y, K = map(int, first_line)

    # Read M edges and build transitions
    transitions = defaultdict(lambda: defaultdict(float))
    for _ in range(M):
        u, v, w = map(int, sys.stdin.readline().strip().split())
        transitions[u][v] += w

    # Process each node to compute probabilities and handle nodes with no outgoing edges
    processed_transitions = {}
    for u in range(1, N + 1):
        if u not in transitions or sum(transitions[u].values()) == 0:
            # Add self-loop if no outgoing edges
            processed_transitions[u] = {u: 1.0}
        else:
            total = sum(transitions[u].values())
            prob_dict = {}
            for v, weight in transitions[u].items():
                prob_dict[v] = weight / total
            processed_transitions[u] = prob_dict

    # Initialize current probabilities
    current_prob = [0.0] * (N + 1)
    current_prob[X] = 1.0

    # Perform K steps
    for _ in range(K):
        next_prob = [0.0] * (N + 1)
        for u in range(1, N + 1):
            if current_prob[u] == 0:
                continue
            for v, p in processed_transitions[u].items():
                next_prob[v] += current_prob[u] * p
        current_prob = next_prob

    # Output the result with sufficient precision
    print("{0:.6f}".format(current_prob[Y]))

