import re

def parse_polynomial(s):
    terms = re.split(r'(?=[+-])', s)
    if terms and terms[0] == '':
        terms = terms[1:]
    coeff_dict = {}
    for term in terms:
        sign = 1
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            term = term[1:]
        if 'x' not in term:
            coeff = sign * int(term)
            exp = 0
        else:
            parts = term.split('x', 1)
            coeff_part = parts[0]
            exp_part = parts[1] if len(parts) > 1 else ''
            coeff = sign * (int(coeff_part) if coeff_part else 1)
            if exp_part.startswith('^'):
                exp = int(exp_part[1:])
            else:
                exp = 1 if exp_part else 1
        coeff_dict[exp] = coeff_dict.get(exp, 0) + coeff
    max_exp = max(coeff_dict.keys()) if coeff_dict else 0
    coefficients = [coeff_dict.get(e, 0) for e in range(max_exp, -1, -1)]
    return coefficients

def synthetic_division(coeffs, r):
    quotient = []
    remainder = 0
    for c in coeffs:
        remainder = c + remainder * r
        quotient.append(remainder)
    return quotient[:-1]

def get_divisors(n):
    if n == 0:
        return []
    divisors = set()
    abs_n = abs(n)
    for i in range(1, int(abs_n**0.5) + 1):
        if abs_n % i == 0:
            divisors.add(i)
            divisors.add(abs_n // i)
    divisors = sorted(divisors) + [-d for d in divisors]
    return sorted(divisors, key=lambda x: (abs(x), x))

def find_roots(coefficients):
    if not coefficients:
        return []
    roots = []
    current_coeff = coefficients.copy()
    degree = len(current_coeff) - 1
    for _ in range(degree):
        constant = current_coeff[-1]
        if constant == 0:
            roots.append(0)
            current_coeff = synthetic_division(current_coeff, 0)
            continue
        possible_roots = get_divisors(constant)
        found = False
        for r in possible_roots:
            value = sum(c * (r ** (len(current_coeff) - 1 - i)) for i, c in enumerate(current_coeff))
            if value == 0:
                roots.append(r)
                current_coeff = synthetic_division(current_coeff, r)
                found = True
                break
        if not found:
            raise ValueError("No root found")
    return roots

