    parent = [0] * (n + 1)
    parent_edge = [0] * (n + 1)
    depth = [0] * (n + 1)
    root = 1
    queue = deque([root])
    parent[root] = 0
    depth[root] = 0

    while queue:
        u = queue.popleft()
        for v, edge_idx, x in adj[u]:
            if v != parent[u]:
                parent[v] = u
                parent_edge[v] = edge_idx
                depth[v] = depth[u] + 1
                queue.append(v)

    max_level = 20
    up = [[0] * (max_level + 1) for _ in range(n + 1)]
    for u in range(1, n + 1):
