    for k in range(1, max_level + 1):
        for u in range(1, n + 1):
            up[u][k] = up[up[u][k-1]][k-1] if up[u][k-1] != 0 else 0

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(max_level, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[u][k]
        if u == v:
            return u
        for k in range(max_level, -1, -1):
            if up[u][k] != up[v][k]:
                u = up[u][k]
                v = up[v][k]
        return parent[u]

