import sys

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    if not points:
        return []
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    full = lower[:-1] + upper[:-1]
    seen = set()
    unique = []
    for p in full:
        key = (p[0], p[1])
        if key not in seen:
            seen.add(key)
            unique.append(p)
    return unique

def is_point_in_convex_hull(poly, point):
    n = len(poly)
    if n == 0:
        return False
    a = poly[0]
    b = poly[1]
    c = point
    val = cross(a, b, c)
    if val < 0:
        return False
    d = poly[-1]
    val = cross(a, d, c)
    if val < 0:
        return False
    low, high = 1, n - 1
    while high - low > 1:
        mid = (low + high) // 2
        m = poly[mid]
        if cross(a, m, c) >= 0:
            low = mid
        else:
            high = mid
    m = poly[low]
    n_pt = poly[high]
    return cross(m, n_pt, c) >= 0

