while True:
    formula = input().strip()
    if formula == '0':
        break
    stack = [{}]
    i = 0
    n = len(formula)
    unknown = False
    try:
        while i < n:
            if formula[i] == '(':
                stack.append({})
                i += 1
            elif formula[i] == ')':
                current_group = stack.pop()
                i += 1
                j = i
                while j < n and formula[j].isdigit():
                    j += 1
                multiplier = int(formula[i:j]) if j > i else 1
                i = j
                parent = stack[-1]
                for atom, count in current_group.items():
                    parent[atom] = parent.get(atom, 0) + count * multiplier
            else:
                # Parse atomic symbol
                if i + 1 < n and formula[i+1].islower():
                    symbol = formula[i:i+2]
                    i += 2
                else:
                    symbol = formula[i]
                    i += 1
                if symbol not in atomic_table:
                    unknown = True
                    break
                # Parse multiplier
                j = i
                while j < n and formula[j].isdigit():
                    j += 1
                multiplier = int(formula[i:j]) if j > i else 1
                i = j
                current_group = stack[-1]
