import sys

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        n = int(line.strip())
        if n == 0:
            break
        lines = []
        for _ in range(n):
            current_line = sys.stdin.readline().strip()
            level = 0
            while level < len(current_line) and current_line[level] == '.':
                level += 1
            value = current_line[level:]
            lines.append((level, value))

        def parse(index, current_level):
            level, val = lines[index]
            assert level == current_level
            if val in ('+', '*'):
                operator = val
                next_index = index + 1
                operands = []
                while next_index < len(lines) and lines[next_index][0] == current_level + 1:
                    operand, next_index = parse(next_index, current_level + 1)
                    operands.append(operand)
                if operator == '+':
                    return (sum(operands), next_index)
                else:
                    product = 1
                    for num in operands:
                        product *= num
                    return (product, next_index)
            else:
                return (int(val), index + 1)

        result, _ = parse(0, 0)
        print(result)

