def is_point_in_polygon(p, polygon):
    n = len(polygon)
    inside = False
    for i in range(n):
        a = polygon[i]
        b = polygon[(i+1)%n]
        if a[1] == b[1] and a[1] == p[1]:
            if min(a[0], b[0]) <= p[0] <= max(a[0], b[0]):
                return True
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1]) + a[0]
            if p[0] <= x:
                inside = not inside
    return inside

