import sys
import math
from collections import defaultdict

def distance(p1, p2):
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

def compute_tspp(A, B, factories):
    m = len(factories)
    if m == 0:
        return distance(A, B)

    dist_A = [distance(A, f) for f in factories]
    dist_f = [[distance(f1, f2) for f2 in factories] for f1 in factories]
    dist_B = [distance(f, B) for f in factories]

    size = 1 << m
    dp = [[math.inf] * m for _ in range(size)]

    for u in range(m):
        mask = 1 << u
        dp[mask][u] = dist_A[u]

    for mask in range(size):
        for u in range(m):
            if not (mask & (1 << u)) or dp[mask][u] == math.inf:
                continue
            for v in range(m):
                if mask & (1 << v):
                    continue
                new_mask = mask | (1 << v)
                if dp[new_mask][v] > dp[mask][u] + dist_f[u][v]:
                    dp[new_mask][v] = dp[mask][u] + dist_f[u][v]

    full_mask = (1 << m) - 1
    min_total = math.inf
    for u in range(m):
        if dp[full_mask][u] != math.inf:
            total = dp[full_mask][u] + dist_B[u]
            if total < min_total:
                min_total = total
    return min_total

class TwoSAT:
    def __init__(self, n_vars):
        self.n = n_vars
        self.graph = defaultdict(list)
        self.rev_graph = defaultdict(list)

    def add_clause(self, a, b):
        self.add_implication((a[0], not a[1]), b)
        self.add_implication((b[0], not b[1]), a)

    def add_implication(self, a, b):
        na = a[0] * 2 + (0 if a[1] else 1)
        nb = b[0] * 2 + (0 if b[1] else 1)
        self.graph[na].append(nb)
        self.rev_graph[nb].append(na)
        ncontra_b = (b[0] * 2) + (1 if b[1] else 0)
        ncontra_a = (a[0] * 2) + (1 if a[1] else 0)
        self.graph[ncontra_b].append(ncontra_a)
        self.rev_graph[ncontra_a].append(ncontra_b)

    def is_satisfiable(self):
        visited = [False] * (2 * self.n)
        order = []
        def dfs(u):
            if not visited[u]:
                visited[u] = True
                for v in self.graph[u]:
                    dfs(v)
                order.append(u)
        for u in range(2 * self.n):
            dfs(u)
        visited = [False] * (2 * self.n)
        component = [0] * (2 * self.n)
        current = 0
        def reverse_dfs(u):
            stack = [u]
            visited[u] = True
            component[u] = current
            while stack:
                node = stack.pop()
                for v in self.rev_graph[node]:
                    if not visited[v]:
                        visited[v] = True
                        component[v] = current
                        stack.append(v)
        for u in reversed(order):
            if not visited[u]:
                reverse_dfs(u)
                nonlocal current
                current += 1
        for i in range(self.n):
            if component[2 * i] == component[2 * i + 1]:
                return False
        return True

def main():
    n, m = map(int, sys.stdin.readline().split())
    stores = []
    for _ in range(n):
        a, b, c, d = map(int, sys.stdin.readline().split())
        stores.append( ( (a, b), (c, d) ) )
    factories = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    all_positions = []
    for s in stores:
        all_positions.append(s[0])
        all_positions.append(s[1])

    tsp_cache = {}
    len_all = len(all_positions)
    for i in range(len_all):
        for j in range(len_all):
            A = all_positions[i]
            B = all_positions[j]
            tsp_cache[(i, j)] = compute_tspp(A, B, factories)

    low = 0.0
    high = 1e18
    eps = 1e-8
    answer = high

    for _ in range(100):
        mid = (low + high) / 2
        ts = TwoSAT(n)
