import sys

def find_smallest_non_representable(test_case):
    counts = list(map(int, test_case.split()))
    # Check for missing digits 1-9
    for d in range(1, 10):
        if counts[d] == 0:
            return d
    # Check if zero is missing (for 10)
    if counts[0] == 0:
        return 10
    # Find the minimal count in digits 1-9
    min_count = min(counts[1:])
    # Collect digits with minimal count
    candidates = [d for d in range(1, 10) if counts[d] == min_count]
    min_digit = min(candidates)
    # Form the number with min_count + 1 repetitions
    return int(str(min_digit) * (min_count + 1))

