import sys

def main():
    n, m = map(int, sys.stdin.readline().split())
    a = []
    for _ in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        a.append(row)

    # Precompute min_diff_consecutive and min_diff_inter_col
    min_diff_consecutive = [[float('inf')] * n for _ in range(n)]
    for u in range(n):
        for v in range(n):
            if u == v:
                continue
            min_val = float('inf')
            for j in range(m):
                diff = abs(a[u][j] - a[v][j])
                if diff < min_val:
                    min_val = diff
            min_diff_consecutive[u][v] = min_val

    min_diff_inter_col = [[float('inf')] * n for _ in range(n)]
    for u in range(n):
        for v in range(n):
            if m == 1:
                min_val = float('inf')
            else:
                min_val = float('inf')
                for j in range(m-1):
                    diff = abs(a[v][j] - a[u][j+1])
                    if diff < min_val:
                        min_val = diff
            min_diff_inter_col[u][v] = min_val

    # Binary search setup
    max_possible = 0
    for u in range(n):
        for v in range(n):
            if min_diff_consecutive[u][v] > max_possible:
                max_possible = min_diff_consecutive[u][v]
            if min_diff_inter_col[u][v] > max_possible:
                max_possible = min_diff_inter_col[u][v]
    low = 0
    high = max_possible
    answer = 0

    while low <= high:
        mid = (low + high) // 2

        # Build adjacency and next_nodes
        adj = [[False]*n for _ in range(n)]
        next_nodes = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if u != v and min_diff_consecutive[u][v] >= mid:
                    adj[u][v] = True
                    next_nodes[u].append(v)

        inter_col = [[False]*n for _ in range(n)]
        for u in range(n):
            for v in range(n):
                inter_col[v][u] = (min_diff_inter_col[v][u] >= mid)

        # DP initialization
        dp = [[[False]*n for _ in range(n)] for __ in range(1 << n)]
        for u in range(n):
            mask = 1 << u
            dp[mask][u][u] = True

        # Process each mask
        for mask in range(1 << n):
            for start in range(n):
                if not (mask & (1 << start)):
                    continue
                for end in range(n):
                    if not (mask & (1 << end)) or not dp[mask][start][end]:
                        continue
                    for w in next_nodes[end]:
                        if mask & (1 << w):
                            continue
                        new_mask = mask | (1 << w)
                        if not dp[new_mask][start][w]:
                            dp[new_mask][start][w] = True

        # Check full mask
        full_mask = (1 << n) - 1
        found = False
        for start in range(n):
            for end in range(n):
                if dp[full_mask][start][end] and inter_col[end][start]:
                    found = True
                    break
            if found:
                break

        if found:
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)

