import sys

def is_perfect_cube(s):
    if s < 0:
        return False
    low = 0
    high = 10**5  # since 10^5^3 = 1e15, which is the maximum possible sum
    while low <= high:
        mid = (low + high) // 2
        cube = mid ** 3
        if cube == s:
            return True
        elif cube < s:
            low = mid + 1
        else:
            high = mid - 1
    return False

