def main():
    while True:
        N, M, L = map(int, sys.stdin.readline().split())
        if N == 0 and M == 0 and L == 0:
            break
        INF = float('inf')
        dist = [[INF] * N for _ in range(N)]
        for i in range(N):
            dist[i][i] = 0
        for _ in range(M):
            u, v, d = map(int, sys.stdin.readline().split())
            if dist[u][v] > d:
                dist[u][v] = d
                dist[v][u] = d
        for k in range(N):
            for i in range(N):
                if dist[i][k] == INF:
                    continue
                for j in range(N):
                    if dist[k][j] == INF:
                        continue
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]
        requests = []
        for _ in range(L):
            p, t = map(int, sys.stdin.readline().split())
            requests.append((t, p))
        requests.sort()
        L_current = len(requests)
        graph = [[] for _ in range(L_current)]
        for i in range(L_current):
            t_i, p_i = requests[i]
            for j in range(i + 1, L_current):
                t_j, p_j = requests[j]
                if dist[p_i][p_j] <= t_j - t_i:
                    graph[i].append(j)
        def hopcroft_karp():
            pair_U = [-1] * L_current
            pair_V = [-1] * L_current
            dist_bfs = [0] * L_current

            def bfs():
                queue = deque()
                dist_null = INF
                for u in range(L_current):
                    if pair_U[u] == -1:
                        dist_bfs[u] = 0
                        queue.append(u)
                    else:
                        dist_bfs[u] = INF
                while queue:
                    u = queue.popleft()
                    if dist_bfs[u] < dist_null:
                        for v in graph[u]:
                            if pair_V[v] == -1:
                                dist_null = dist_bfs[u] + 1
                            elif dist_bfs[pair_V[v]] == INF:
                                dist_bfs[pair_V[v]] = dist_bfs[u] + 1
                                queue.append(pair_V[v])
                return dist_null != INF

            def dfs(u):
                for v in graph[u]:
                    if pair_V[v] == -1 or (dist_bfs[pair_V[v]] == dist_bfs[u] + 1 and dfs(pair_V[v])):
                        pair_U[u] = v
                        pair_V[v] = u
                        return True
                dist_bfs[u] = INF
                return False

            result = 0
            while bfs():
                for u in range(L_current):
                    if pair_U[u] == -1:
                        if dfs(u):
                            result += 1
            return result

        max_match = hopcroft_karp()
        print(L_current - max_match)

