import sys
from collections import deque

class Edge:
    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class Dinic:
    def __init__(self, n):
        self.size = n
        self.graph = [[] for _ in range(n+1)]  # 1-based indexing

    def add_edge(self, fr, to, cap):
        forward = Edge(to, len(self.graph[to]), cap)
        backward = Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def max_flow(self, s, t):
        flow = 0
        while True:
            level = [-1] * (self.size +1)
            self.bfs_level(s, t, level)
            if level[t] == -1:
                break
            iter_ = [0]*(self.size+1)
            while True:
                f = self.dfs_augment(s, t, float('inf'), iter_, level)
                if f ==0:
                    break
                flow +=f
        return flow

    def bfs_level(self, s, t, level):
        q = deque()
        q.append(s)
        level[s] =0
        while q:
            u = q.popleft()
            for e in self.graph[u]:
                if e.cap >0 and level[e.to] ==-1:
                    level[e.to] = level[u] +1
                    q.append(e.to)
                    if e.to ==t:
                        return

    def dfs_augment(self, u, t, flow, iter_, level):
        if u ==t:
            return flow
        for i in range(iter_[u], len(self.graph[u])):
            e = self.graph[u][i]
            if e.cap >0 and level[e.to] == level[u]+1:
                min_flow = min(flow, e.cap)
                res = self.dfs_augment(e.to, t, min_flow, iter_, level)
                if res >0:
                    e.cap -=res
                    self.graph[e.to][e.rev].cap +=res
                    return res
            iter_[u] +=1
        return 0

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == '0 0 0 0':
            break
        parts = list(map(int, line.split()))
        N, M, S, T = parts
        edges = []
        for _ in range(M):
            a, b = map(int, sys.stdin.readline().split())
            edges.append( (a, b) )
        # Compute original max flow
        dinic = Dinic(N)
        for a, b in edges:
            dinic.add_edge(a, b, 1)
        original_flow = dinic.max_flow(S, T)
        # Compute R_S: reachable from S in residual graph
        visited_S = [False]*(N+1)
        q = deque()
        q.append(S)
        visited_S[S] = True
        while q:
            u = q.popleft()
            for e in dinic.graph[u]:
                if e.cap >0 and not visited_S[e.to]:
                    visited_S[e.to] = True
                    q.append(e.to)
        # Compute R_T: can reach T in residual graph (using reverse_adj)
        reverse_adj = [[] for _ in range(N+1)]
        for u in range(1, N+1):
            for e in dinic.graph[u]:
                if e.cap >0:
                    reverse_adj[e.to].append(u)
        visited_T = [False]*(N+1)
        q = deque()
        q.append(T)
        visited_T[T] = True
        while q:
            v = q.popleft()
            for u in reverse_adj[v]:
                if not visited_T[u]:
                    visited_T[u] = True
                    q.append(u)
        # Count eligible edges
        cnt =0
        for a, b in edges:
            if visited_S[b] and visited_T[a]:
                cnt +=1
        if cnt >0:
            print(original_flow +1, cnt)
        else:
            print(original_flow, 0)

