            M_i = crime_info[idx][1]
            new_residues[idx] = (new_residues[idx] + 1) % M_i
            new_code = 0
            product = 1
            for i, r in enumerate(new_residues):
                new_code += r * product
                product *= crime_info[i][1]
            matrix[code][new_code] += 1

    def multiply(a, b):
        res = [[0] * S for _ in range(S)]
        for i in range(S):
            for k in range(S):
                if a[i][k]:
                    for j in range(S):
                        res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
        return res

    def matrix_power(mat, power):
        result = [[0] * S for _ in range(S)]
        for i in range(S):
            result[i][i] = 1
        while power > 0:
            if power % 2:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    initial_code = 0
    product = 1
    for info in crime_info:
        product *= info[1]

    if n == 0:
