import heapq

class Substring:
    def __init__(self, start, length, s):
        self.start = start
        self.length = length
        self.s = s

    def __lt__(self, other):
        min_len = min(self.length, other.length)
        for i in range(min_len):
            if self.s[self.start + i] < other.s[other.start + i]:
                return True
            elif self.s[self.start + i] > other.s[other.start + i]:
                return False
        if self.length != other.length:
            return self.length < other.length
        else:
            return self.start < other.start

