import sys
import math

def get_divisors(n):
    divisors = set()
    i = 2
    while i*i <= n:
        if n % i == 0:
            divisors.add(i)
            if i*i != n:
                divisors.add(n//i)
        i += 1
    divisors.add(n)
    return sorted(divisors)

def is_prime_power(n):
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            while n % i == 0:
                n = n // i
            return n == 1
    return False

def get_prime_factors(n):
    factors = set()
    i = 2
    while i*i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n = n // i
        i += 1
    if n > 1:
        factors.add(n)
    return sorted(factors)

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        divisors = get_divisors(n)
        if len(divisors) == 0:
            print()
            print(0)
            continue
        if is_prime_power(n):
            print(' '.join(map(str, sorted(divisors))) + ' ')
            print(0)
            continue
        primes = get_prime_factors(n)
        if len(primes) == 2 and all(n % (p**2) != 0 for p in primes):
            p1, p2 = primes
            d = sorted(divisors)
            ordered = []
            ordered.append(p1)
            ordered.append(p2)
            ordered.append(p1*p2)
            for num in d:
                if num not in ordered:
                    ordered.append(num)
            ordered = ordered + [n]
            print(' '.join(map(str, ordered)) + ' ')
            print(1)
        else:
            primes = get_prime_factors(n)
            primes.sort()
            divisors_sorted = []
            divisors_sorted.append(primes[0])
            divisors_sorted.append(n)
            seen = {primes[0], n}
            for p in primes[1:]:
                product = primes[0] * p
                if product in divisors and product not in seen:
                    divisors_sorted.append(product)
                    seen.add(product)
                divisors_sorted.append(p)
                seen.add(p)
                product = p * primes[0]
                if product in divisors and product not in seen:
                    divisors_sorted.append(product)
                    seen.add(product)
            remaining = [d for d in divisors if d not in seen]
            for d in remaining:
                divisors_sorted.append(d)
            print(' '.join(map(str, divisors_sorted)) + ' ')
            print(0)

