def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

cum_days = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365]

def days_before_month(year, month):
    if month == 0:
        return 0
    total = cum_days[month - 1]
    if is_leap(year) and month > 2:
        total += 1
    return total

def date_to_days(y, m, d):
    y_prev = y - 1
    leap_count = y_prev // 4 - y_prev // 100 + y_prev // 400
    days_prev_years = y_prev * 365 + leap_count
    days_prev_months = days_before_month(y, m)
    return days_prev_years + days_prev_months + (d - 1)

