from collections import deque
import sys

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(n)]

    degrees = [[0]*m for _ in range(n)]
    dirs = [ (-1,0), (1,0), (0,-1), (0,1) ]

    # Calculate initial degrees
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                cnt = 0
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                        cnt += 1
                degrees[i][j] = cnt

    q = deque()
    for i in range(n):
        for j in range(m):
            if degrees[i][j] == 1:
                q.append((i, j))

    while q:
        i, j = q.popleft()
        if grid[i][j] != '.':
            continue

        # Find the only possible neighbor
        found = False
        for dx, dy in dirs:
            ni, nj = i + dx, j + dy
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                found = (dx, dy)
                break
        if not found:
            print("Not unique")
            return

        dx, dy = found
        ni, nj = i + dx, j + dy

        # Determine tile characters
        if (dx, dy) == (0, 1):
            grid[i][j], grid[ni][nj] = '<', '>'
        elif (dx, dy) == (0, -1):
            grid[i][j], grid[ni][nj] = '>', '<'
        elif (dx, dy) == (1, 0):
            grid[i][j], grid[ni][nj] = '^', 'v'
        else:
            grid[i][j], grid[ni][nj] = 'v', '^'

        # Update degrees for neighbors of both cells
        for x, y in [(i, j), (ni, nj)]:
            for ddx, ddy in dirs:
                nx, ny = x + ddx, y + ddy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                    degrees[nx][ny] -= 1
                    if degrees[nx][ny] == 1:
                        q.append((nx, ny))

    # Check if all cells are covered
    for row in grid:
        if '.' in row:
            print("Not unique")
            return

    for r in grid:
        print(''.join(r))

