class Line:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def get(self, x):
        return self.a * x + self.b

class LiChaoNode:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.line = None

class LiChaoTree:
    def __init__(self, x_min, x_max):
        self.root = LiChaoNode(x_min, x_max)

    def insert(self, node, new_line):
        l = node.l
        r = node.r
        m = (l + r) // 2
        if node.line is None:
            node.line = new_line
            return
        current_val_m = node.line.get(m)
        new_val_m = new_line.get(m)
        if new_val_m > current_val_m:
            node.line, new_line = new_line, node.line
        if new_line.get(l) > node.line.get(l):
            if not node.left:
                node.left = LiChaoNode(l, m)
            self.insert(node.left, new_line)
        else:
            if not node.right:
                node.right = LiChaoNode(m + 1, r)
            self.insert(node.right, new_line)

    def query(self, node, x):
        if node is None:
            return -float('inf')
        current_val = node.line.get(x) if node.line else -float('inf')
        m = (node.l + node.r) // 2
        if x <= m:
            return max(current_val, self.query(node.left, x))
        else:
            return max(current_val, self.query(node.right, x))

