    for i in range(1, n + 1):
        prefix_S[i] = prefix_S[i-1] + a[i-1]
        prefix_T[i] = prefix_T[i-1] + i * a[i-1]

    x_min = -2 * 10**5
    x_max = 0
    tree = LiChaoTree(x_min, x_max)
    max_total = 0

