def main():
    n, q = map(int, sys.stdin.readline().split())
    c = list(map(int, sys.stdin.readline().split()))
    c = [0] + c  # 1-based indexing

    queries = [[] for _ in range(n + 2)]  # queries[r] contains (l, query_index)
    for idx in range(q):
        l, r = map(int, sys.stdin.readline().split())
        queries[r].append((l, idx))

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)  # 1-based

        def add(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(n)
    last_occurrence = {}
    ans = [0] * q

    for i in range(1, n + 1):
        color = c[i]
        if color in last_occurrence:
            prev = last_occurrence[color]
            ft.add(prev, -1)
        ft.add(i, 1)
        last_occurrence[color] = i

        for (l, q_idx) in queries[i]:
            ans[q_idx] = ft.query(i) - ft.query(l - 1)

    for a in ans:
        print(a)

