def compute_score(throws):
    total = 0
    current_throw = 0
    for frame in range(9):
        if current_throw >= len(throws):
            break
        if throws[current_throw] == 10:
            # Strike
            total += 10
            if current_throw + 1 < len(throws):
                total += throws[current_throw + 1]
            if current_throw + 2 < len(throws):
                total += throws[current_throw + 2]
            current_throw += 1
        else:
            if current_throw + 1 >= len(throws):
                total += throws[current_throw]
                current_throw += 1
                break
            first = throws[current_throw]
            second = throws[current_throw + 1]
            if first + second >= 10:
                # Spare
                total += 10
                if current_throw + 2 < len(throws):
                    total += throws[current_throw + 2]
                current_throw += 2
            else:
                total += first + second
                current_throw += 2
    # Add 10th frame
    total += sum(throws[current_throw:])
    return total

