def compute_prefix(s):
    m = len(s)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def build_transition(s, pi):
    m = len(s)
    transition = [[0]*2 for _ in range(m)]
    for k in range(m):
        for c in ['(', ')']:
            current_k = k
            while True:
                if current_k < m and s[current_k] == c:
                    next_k = current_k + 1
                    break
                elif current_k == 0:
                    next_k = 0
                    break
                else:
                    current_k = pi[current_k - 1]
            transition[k][0 if c == '(' else 1] = next_k
    return transition

