class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None, None]
        self.count = 0

def insert(node, x):
    for i in reversed(range(30)):  # Process from MSB to LSB (30 bits)
        bit = (x >> i) & 1
        if not node.children[bit]:
            node.children[bit] = TrieNode()
        node = node.children[bit]
        node.count += 1

def query(node, x, k):
    result = 0
    nodes = [(node, True)]  # (current_node, equal_so_far)
    for i in reversed(range(30)):
        c_bit = (x >> i) & 1
        k_bit = (k >> i) & 1
        new_nodes = []
        for current_node, equal_so_far in nodes:
            if not equal_so_far:
                # Add all children counts
                for child in [0, 1]:
                    if current_node.children[child]:
                        result += current_node.children[child].count
                continue
            # Process each child
            for child_bit in [0, 1]:
                child_node = current_node.children[child_bit]
                if not child_node:
                    continue
                xor_bit = c_bit ^ child_bit
                if xor_bit < k_bit:
                    result += child_node.count
                elif xor_bit == k_bit:
                    new_nodes.append((child_node, True))
        nodes = new_nodes
    return result

