def main():
    import sys
    from collections import defaultdict

    N, *rest = list(map(int, sys.stdin.read().split()))
    a = rest[:N]

    c1_initial = 0
    c2_initial = 0
    c3_initial = 0
    for num in a:
        if num == 1:
            c1_initial += 1
        elif num == 2:
            c2_initial += 1
        elif num == 3:
            c3_initial += 1

    max_s = sum(a)

    # Precompute all possible states for each s
    states_per_s = defaultdict(list)
    for s in range(0, max_s + 1):
        max_c3 = min(s // 3, N)
        for c3 in range(0, max_c3 + 1):
            rem = s - 3 * c3
            if rem < 0:
                continue
            max_c2 = rem // 2
            for c2 in range(0, max_c2 + 1):
                c1 = rem - 2 * c2
                if c1 < 0:
                    continue
                total_dishes = c1 + c2 + c3
                if total_dishes > N:
                    continue
                states_per_s[s].append((c1, c2, c3))

    memo = {}

    # Process states in order of increasing s
    for s in sorted(states_per_s.keys()):
        for (c1, c2, c3) in states_per_s[s]:
            if s == 0:
                memo[(c1, c2, c3)] = 0.0
                continue

            sum_nonzero = c1 + c2 + c3
            if sum_nonzero == 0:
                memo[(c1, c2, c3)] = 0.0
                continue

            total = N  # Start with N from the formula

            if c1 > 0:
                prev = (c1 - 1, c2, c3)
                total += c1 * memo.get(prev, 0.0)
            if c2 > 0:
                prev = (c1 + 1, c2 - 1, c3)
                total += c2 * memo.get(prev, 0.0)
            if c3 > 0:
                prev = (c1, c2 + 1, c3 - 1)
                total += c3 * memo.get(prev, 0.0)

            memo[(c1, c2, c3)] = total / sum_nonzero

    initial_state = (c1_initial, c2_initial, c3_initial)
    print("{0:.15f}".format(memo.get(initial_state, 0.0)))

