def main():
    import sys
    query = sys.stdin.readline().strip()
    yaml_lines = []
    for line in sys.stdin:
        yaml_lines.append(line.rstrip('\n'))

    # Parse YAML into a nested dictionary structure
    def parse_yaml(lines):
        root = {}
        stack = [(root, -1)]  # Each entry is (mapping, indent_level)
        for line in lines:
            line = line.rstrip('\n')
            if not line.strip():
                continue
            indent_count = len(line) - len(line.lstrip(' '))
            content = line.lstrip()
            while stack and stack[-1][1] > indent_count:
                stack.pop()
            parent, _ = stack[-1]
            key_part, sep, rest = content.partition(':')
            key = key_part.strip()
            value_part = rest.lstrip()
            if sep:
                if value_part:
                    parent[key] = value_part
                else:
                    new_map = {}
                    parent[key] = new_map
                    stack.append((new_map, indent_count))
        return root

    root = parse_yaml(yaml_lines)

    # Process the query
    parts = query.split('.')[1:]
    current = root
    for part in parts:
        if not isinstance(current, dict) or part not in current:
            print("no such property")
