import sys
from collections import deque

class Edge:
    def __init__(self, x1, y1, x2, y2):
        self.x1, self.y1 = x1, y1
        self.x2, self.y2 = x2, y2

def simulate_movement(start_x, start_y, dx, dy, goal_x, goal_y, edges):
    if dx == 0 and dy == 0:
        return (False, start_x, start_y)
    current_x, current_y = start_x, start_y
    original_dx, original_dy = dx, dy
    current_dx, current_dy = dx, dy
    visited = set()

    while True:
        if (current_x, current_y) == (goal_x, goal_y):
            return (True, 0, 0)
        if (current_dx, current_dy) in visited:
            break
        visited.add((current_dx, current_dy))

        min_t = float('inf')
        intersect_edge = None
        for e in edges:
            if e.x1 == e.x2:
                if current_dx == 0:
                    continue
                t = (e.x1 - current_x) / current_dx
                if t < 1e-9:
                    continue
                y = current_y + t * current_dy
                y_min, y_max = sorted([e.y1, e.y2])
                if y_min - 1e-9 <= y <= y_max + 1e-9 and t < min_t:
                    min_t = t
                    intersect_edge = e
            else:
                if current_dy == 0:
                    continue
                t = (e.y1 - current_y) / current_dy
                if t < 1e-9:
                    continue
                x = current_x + t * current_dx
                x_min, x_max = sorted([e.x1, e.x2])
                if x_min - 1e-9 <= x <= x_max + 1e-9 and t < min_t:
                    min_t = t
                    intersect_edge = e

        if intersect_edge is None:
            if (current_x, current_y) == (goal_x, goal_y):
                return (True, 0, 0)
            return (False, current_x + dx * 1e9, current_y + dy * 1e9)

        xi = current_x + min_t * current_dx
        yi = current_y + min_t * current_dy

        if (dx != 0 or dy != 0):
            if (goal_x - current_x) * dy == (goal_y - current_y) * dx:
                t_goal = (goal_x - current_x) / dx if dx != 0 else (goal_y - current_y) / dy
                if 0 <= t_goal <= min_t:
                    return (True, 0, 0)

        if intersect_edge.x1 == intersect_edge.x2:
            new_dx = 0
            new_dy = original_dy
        else:
            new_dx = original_dx
            new_dy = 0

        if new_dx == 0:
            y_end = intersect_edge.y2 if new_dy > 0 else intersect_edge.y1
            if intersect_edge.y2 < intersect_edge.y1:
                y_end = intersect_edge.y1 if new_dy > 0 else intersect_edge.y2
            if abs(yi - y_end) < 1e-9:
                current_x, current_y = xi, yi
                current_dx, current_dy = original_dx, original_dy
                continue
            if (new_dy > 0 and yi <= goal_y <= y_end or new_dy < 0 and y_end <= goal_y <= yi) and abs(goal_x - xi) < 1e-9:
                return (True, 0, 0)
            current_x, current_y = xi, y_end
            current_dx, current_dy = original_dx, original_dy
        else:
            x_end = intersect_edge.x2 if new_dx > 0 else intersect_edge.x1
            if intersect_edge.x2 < intersect_edge.x1:
                x_end = intersect_edge.x1 if new_dx > 0 else intersect_edge.x2
            if abs(xi - x_end) < 1e-9:
                current_x, current_y = xi, yi
                current_dx, current_dy = original_dx, original_dy
                continue
            if (new_dx > 0 and xi <= goal_x <= x_end or new_dx < 0 and x_end <= goal_x <= xi) and abs(goal_y - yi) < 1e-9:
                return (True, 0, 0)
            current_x, current_y = x_end, yi
            current_dx, current_dy = original_dx, original_dy

    return (False, current_x, current_y)

def main():
    directions = [(dx, dy) for dx in (-1,0,1) for dy in (-1,0,1) if not (dx==0 and dy==0)]
    while True:
        line = sys.stdin.readline().strip()
        if not line or line == '0':
            break
        N = int(line)
        sx, sy, gx, gy = map(int, sys.stdin.readline().split())
        polygon = [tuple(map(int, sys.stdin.readline().split())) for _ in range(N)]
        edges = []
        for i in range(N):
            x1, y1 = polygon[i]
            x2, y2 = polygon[(i+1)%N]
            edges.append(Edge(x1, y1, x2, y2))
        visited = {}
        q = deque([(sx, sy, 0)])
        visited[(sx, sy)] = 0
        found = False
        while q:
            x, y, cnt = q.popleft()
            if x == gx and y == gy:
                print(cnt)
                found = True
                break
            for dx, dy in directions:
                success, nx, ny = simulate_movement(x, y, dx, dy, gx, gy, edges)
                if success:
                    print(cnt +1)
                    found = True
                    q = deque()
                    break
                key = (nx, ny)
                if key not in visited or cnt+1 < visited[key]:
                    visited[key] = cnt+1
                    q.append((nx, ny, cnt+1))
