    for _ in range(t):
        n = int(input[idx])
        m = int(input[idx+1])
        idx += 2
        a = []
        for i in range(n):
            row = list(map(int, input[idx:idx+m]))
            a.append(row)
            idx += m
        # Compute s matrix
        s = [[a[i][j] - (i + j) for j in range(m)] for i in range(n)]
        # Binary search for maximum x
        low = min(s[i][j] for i in range(n) for j in range(m))
        high = a[0][0]
        best_x = low
        while low <= high:
            mid = (low + high) // 2
            # Check if path exists for mid
            dp = [[False]*m for _ in range(n)]
            dp[0][0] = s[0][0] >= mid
            for i in range(n):
                for j in range(m):
                    if i == 0 and j == 0:
                        continue
                    if s[i][j] < mid:
                        continue
                    valid = False
                    if i > 0 and dp[i-1][j]:
                        valid = True
                    if j > 0 and dp[i][j-1]:
                        valid = True
                    dp[i][j] = valid
            if dp[n-1][m-1]:
                best_x = mid
                low = mid + 1
            else:
                high = mid - 1
        # Compute minimal sum for best_x
        INF = float('inf')
        sum_dp = [[INF]*m for _ in range(n)]
        sum_dp[0][0] = s[0][0] if s[0][0] >= best_x else INF
        for i in range(n):
            for j in range(m):
                if s[i][j] < best_x:
                    continue
                if i == 0 and j == 0:
