                current = s[i][j]
                min_prev = INF
                if i > 0:
                    min_prev = min(min_prev, sum_dp[i-1][j])
                if j > 0:
                    min_prev = min(min_prev, sum_dp[i][j-1])
                if min_prev != INF:
                    sum_dp[i][j] = current + min_prev
        total = sum_dp[n-1][m-1]
        print(total - best_x * (n + m - 1))

