def min_number_with_digit_sum(s):
    if s == 0:
        return '0'
    if s % 9 == 0:
        return '9' * (s // 9)
    else:
        return str(s % 9) + '9' * (s // 9)

def find_min_x(n, k):
    if k == 0:
        if n == 0:
            return 0
        if n % 9 == 0:
            return int('9' * (n // 9))
        else:
            return int(str(n % 9) + '9' * (n // 9))
    else:
        total = k * (k + 1) // 2
        if (n - total) < 0 or (n - total) % (k + 1) != 0:
            no_carry = None
        else:
            s = (n - total) // (k + 1)
            d_max = 9 - k
            min_candidate = None
            for d in range(min(d_max, s), -1, -1):
                sum_rest = s - d
                if sum_rest < 0:
                    continue
                if sum_rest == 0:
                    rest_str = '0'
                else:
                    if sum_rest % 9 == 0:
                        rest_str = '9' * (sum_rest // 9)
                    else:
                        rest_str = str(sum_rest % 9) + '9' * (sum_rest // 9)
                if rest_str == '0' and d == 0:
                    candidate = 0
                else:
                    if rest_str == '0':
                        candidate = d
                    else:
                        candidate_str = rest_str + str(d)
                        if candidate_str[0] == '0':
                            continue
                        candidate = int(candidate_str)
                if candidate is not None:
                    if (min_candidate is None) or (candidate < min_candidate):
                        min_candidate = candidate
            no_carry = min_candidate
        brute_force = None
        for x in range(0, 100000):
            current_sum = 0
            for i in range(x, x + k + 1):
                current_sum += sum(map(int, str(i)))
                if current_sum > n:
                    break
            if current_sum == n:
                brute_force = x
                break
        candidates = []
        if no_carry is not None:
            candidates.append(no_carry)
        if brute_force is not None:
            candidates.append(brute_force)
        if not candidates:
            return -1
        else:
            return min(candidates)

