import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        a, b = map(int, sys.stdin.readline().split())
        s = list(sys.stdin.readline().strip())
        n = len(s)
        possible = True
        count0 = 0
        count1 = 0
        pairs_to_fill = []

        # Process pairs
        for i in range(n // 2):
            j = n - 1 - i
            c1 = s[i]
            c2 = s[j]
            if c1 != '?' and c2 != '?':
                if c1 != c2:
                    possible = False
                else:
                    if c1 == '0':
                        count0 += 2
                    else:
                        count1 += 2
            elif c1 == '?' and c2 == '?':
                pairs_to_fill.append((i, j))
            else:
                # One is '?'
                if c1 == '?':
                    s[i] = c2
                    if c2 == '0':
                        count0 += 2
                    else:
                        count1 += 2
                else:
                    s[j] = c1
                    if c1 == '0':
                        count0 += 2
                    else:
                        count1 += 2

        if not possible:
            print(-1)
            continue

        # Check middle character
        middle = None
        middle_char = None
        if n % 2 == 1:
            middle = n // 2
            middle_char = s[middle]
            if middle_char == '0':
                count0 += 1
            elif middle_char == '1':
                count1 += 1

        required_0 = a - count0
        required_1 = b - count1

        if required_0 < 0 or required_1 < 0:
            print(-1)
            continue

        pairs_left = len(pairs_to_fill)
        middle_left = 1 if (middle is not None and middle_char == '?') else 0

        if middle_left:
            # Handle middle
            possible_middle_0 = False
            possible_middle_1 = False
            new_req_0 = required_0 - 1
            new_req_1 = required_1
            if new_req_0 >= 0 and new_req_1 >= 0:
                if (new_req_0 % 2 == 0) and (new_req_1 % 2 == 0) and (new_req_0 + new_req_1 == 2 * pairs_left):
                    possible_middle_0 = True
            new_req_0_2 = required_0
            new_req_1_2 = required_1 - 1
            if new_req_0_2 >= 0 and new_req_1_2 >= 0:
                if (new_req_0_2 % 2 == 0) and (new_req_1_2 % 2 == 0) and (new_req_0_2 + new_req_1_2 == 2 * pairs_left):
                    possible_middle_1 = True
            if not possible_middle_0 and not possible_middle_1:
                print(-1)
                continue
            if possible_middle_0:
                s[middle] = '0'
                count0 += 1
                pairs_0 = new_req_0 // 2
                pairs_1 = new_req_1 // 2
            else:
                s[middle] = '1'
                count1 += 1
                pairs_0 = new_req_0_2 // 2
                pairs_1 = new_req_1_2 // 2
        else:
            # No middle
            if (required_0 % 2 != 0) or (required_1 % 2 != 0) or (required_0 + required_1 != 2 * pairs_left):
                print(-1)
                continue
            pairs_0 = required_0 // 2
            pairs_1 = required_1 // 2

        # Assign pairs
        for i in range(len(pairs_to_fill)):
            idx_i, idx_j = pairs_to_fill[i]
            if i < pairs_0:
                s[idx_i] = '0'
                s[idx_j] = '0'
            else:
                s[idx_i] = '1'
                s[idx_j] = '1'

        # Final checks
        final_count0 = sum(1 for c in s if c == '0')
        final_count1 = sum(1 for c in s if c == '1')
        if final_count0 != a or final_count1 != b:
            print(-1)
            continue
        is_pal = True
        for i in range(n//2):
            if s[i] != s[n-1-i]:
                is_pal = False
                break
        if not is_pal:
            print(-1)
            continue
        print(''.join(s))

