class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None, None]
        self.count = 0

class Trie:
    def __init__(self, bits=40):
        self.root = TrieNode()
        self.bits = bits

    def insert(self, num):
        node = self.root
        for i in reversed(range(self.bits)):
            bit = (num >> i) & 1
            if not node.children[bit]:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def delete(self, num):
        node = self.root
        path = []
        for i in reversed(range(self.bits)):
            bit = (num >> i) & 1
            if not node.children[bit]:
                return  # Not present
            path.append((node, bit))
            node = node.children[bit]
        # Decrement the leaf node count
        node.count -= 1
        # Backtrack and prune if needed
        for i in reversed(range(len(path))):
            parent, bit = path[i]
            current_node = parent.children[bit]
            if current_node.count == 0:
                parent.children[bit] = None
            else:
                break  # No more pruning needed

    def query_max_xor(self, num):
        if not self.root.children[0] and not self.root.children[1]:
            return 0
        node = self.root
        max_xor = 0
        for i in reversed(range(self.bits)):
            bit = (num >> i) & 1
            desired_bit = 1 - bit
            if node.children[desired_bit] and node.children[desired_bit].count > 0:
                max_xor |= (1 << i)
                node = node.children[desired_bit]
            else:
                if node.children[bit] and node.children[bit].count > 0:
                    node = node.children[bit]
                else:
                    return 0  # No path found
        return max_xor

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))

    # Compute prefix_xor
    prefix_xor = [0] * (n + 1)
    for i in range(1, n+1):
        prefix_xor[i] = prefix_xor[i-1] ^ a[i-1]

    # Compute postfix_xor
    postfix_xor = [0] * (n + 1)
    for j in range(1, n+1):
        postfix_xor[j] = postfix_xor[j-1] ^ a[n - j]

    # Initialize Trie and insert all postfix_xor
    trie = Trie()
    for j in range(n+1):
        trie.insert(postfix_xor[j])

    max_pleasure = 0
