import sys

def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isalpha():
            j = i
            while j < len(s) and s[j].isalpha():
                j += 1
            tokens.append(s[i:j])
            i = j
        else:
            i += 1
    return tokens

def parse_formula(tokens, idx, variables_dict):
    dim, error = parse_term(tokens, idx, variables_dict)
    if error:
        return None, True
    while idx[0] < len(tokens) and tokens[idx[0]] in '+-':
        op = tokens[idx[0]]
        idx[0] += 1
        dim_term, error_term = parse_term(tokens, idx, variables_dict)
        if error_term:
            return None, True
        if dim != dim_term:
            return None, True
    return dim, False

def parse_term(tokens, idx, variables_dict):
    dim, error = parse_factor(tokens, idx, variables_dict)
    if error:
        return None, True
    while idx[0] < len(tokens) and tokens[idx[0]] in '*/':
        op = tokens[idx[0]]
        idx[0] += 1
        dim_factor, error_factor = parse_factor(tokens, idx, variables_dict)
        if error_factor:
            return None, True
        if op == '*':
            new_dim = tuple(a + b for a, b in zip(dim, dim_factor))
        else:
            new_dim = tuple(a - b for a, b in zip(dim, dim_factor))
        dim = new_dim
    return dim, False

def parse_factor(tokens, idx, variables_dict):
    if idx[0] >= len(tokens):
        return None, True
    token = tokens[idx[0]]
    if token == '(':
        idx[0] += 1
        dim, error = parse_formula(tokens, idx, variables_dict)
        if error:
            return None, True
        if idx[0] >= len(tokens) or tokens[idx[0]] != ')':
            return None, True
        idx[0] += 1
        return dim, False
    elif token.isalpha():
        var_name = token
        if var_name not in variables_dict:
            return None, True
        dim = variables_dict[var_name]
        idx[0] += 1
        return dim, False
    else:
        return None, True

