import heapq

def main():
    N, M, R = map(int, input().split())
    d = list(map(int, input().split()))
    roads = [[] for _ in range(N+1)]  # 1-based indexing
    for _ in range(M):
        a, b, c = map(int, input().split())
        roads[a].append((b, c))
        roads[b].append((a, c))

    # Initialize the priority queue with (time, current_town, next_collect_tuple, score)
    initial_next_collect = tuple([0] * N)
    heap = []
    heapq.heappush(heap, (0, 1, initial_next_collect, 0))

    # Dictionary to track the best states for each (town, time)
    best = {}
    max_score = 0

    while heap:
        current_time, town, next_collect, score = heapq.heappop(heap)

        # Check if we've reached town N at exactly R time
        if town == N and current_time == R:
            if score > max_score:
                max_score = score
            continue

        # If current_time exceeds R, skip processing
        if current_time > R:
            continue

        # Check dominance with existing states for this town and time
        if (town, current_time) in best:
            dominated = False
            for (existing_next, existing_score) in best[(town, current_time)]:
                # Check if existing state dominates the current state
                if existing_score >= score and all(existing_next[i] <= next_collect[i] for i in range(N)):
                    dominated = True
                    break
            if dominated:
                continue

        # Add current state to best if not dominated
        if (town, current_time) not in best:
            best[(town, current_time)] = []
        best[(town, current_time)].append((next_collect, score))

        # Process all neighbors
        for neighbor, cost in roads[town]:
            new_time = current_time + cost
            if new_time > R:
                continue

            # Generate not collect case
            new_next_collect_not = next_collect
            new_score_not = score
            # Check if this state is worth adding
            add_not = True
            if (neighbor, new_time) in best:
                for (existing_next, existing_score) in best[(neighbor, new_time)]:
                    if existing_score >= new_score_not and all(existing_next[i] <= new_next_collect_not[i] for i in range(N)):
                        add_not = False
                        break
            if add_not:
                # Check if this new state is not dominated by existing ones
                heapq.heappush(heap, (new_time, neighbor, new_next_collect_not, new_score_not))

            # Generate collect case if possible
            idx = neighbor - 1
            if new_time >= next_collect[idx]:
                new_next_collect_collect = list(next_collect)
                new_next_collect_collect[idx] = new_time + 15
                new_next_collect_collect = tuple(new_next_collect_collect)
                new_score_collect = score + d[idx]

                add_collect = True
                if (neighbor, new_time) in best:
                    for (existing_next, existing_score) in best[(neighbor, new_time)]:
                        if existing_score >= new_score_collect and all(existing_next[i] <= new_next_collect_collect[i] for i in range(N)):
                            add_collect = False
                            break
                if add_collect:
                    heapq.heappush(heap, (new_time, neighbor, new_next_collect_collect, new_score_collect))

    print(max_score)

