from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, k = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v, d = map(int, sys.stdin.readline().split())
        adj[u].append((v, d))
        adj[v].append((u, d))

    # Function to perform BFS and return distances and parent pointers
    def bfs(start):
        dist = {start: 0}
        parent = {}
        q = deque([start])
        while q:
            u = q.popleft()
            for v, w in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + w
                    parent[v] = u
                    q.append(v)
        max_node = max(dist, key=lambda x: dist[x])
        return max_node, dist[max_node], parent

    # First BFS to find u
    u, _, _ = bfs(1)
    # Second BFS to find v and L (diameter length)
    v, L, parent = bfs(u)
    # Reconstruct path from u to v
    path = []
    current = v
    while current is not None:
        path.append(current)
        current = parent.get(current, None)
    path_set = set(path)

    # Compute max_dist_off_diameter using Dijkstra's algorithm
    INF = float('inf')
    distance = [INF] * (n + 1)
    heap = []
    for node in path:
        distance[node] = 0
        heapq.heappush(heap, (0, node))

    while heap:
        dist_u, u = heapq.heappop(heap)
        if dist_u > distance[u]:
            continue
        for v, w in adj[u]:
            if distance[v] > dist_u + w:
                distance[v] = dist_u + w
                heapq.heappush(heap, (distance[v], v))

    max_dist_off_diameter = max(distance[1:n+1])

    # Binary search
    low = 0
    high = max(L, max_dist_off_diameter)
    answer = high
    while low <= high:
        mid = (low + high) // 2
        if max_dist_off_diameter > mid:
            low = mid + 1
        else:
            if 2 * mid == 0:
                required = 0 if L == 0 else 1
            else:
                required = (L + 2 * mid - 1) // (2 * mid)  # Ceil division
            if required <= k:
                answer = mid
                high = mid - 1
            else:
                low = mid + 1
    print(answer)

