import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n, m = map(int, stdin.readline().split())
    p = list(map(int, stdin.readline().split()))

    # Build the tree
    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    parent[1] = 0
    for i in range(2, n + 1):
        parent[i] = p[i - 2]
        children[p[i - 2]].append(i)

    # Compute depth and binary lifting table for LCA
    log_max = 20
    depth = [0] * (n + 1)
    up = [[0] * (n + 1) for _ in range(log_max)]
    stack = [1]
    while stack:
        u = stack.pop()
        for v in children[u]:
            depth[v] = depth[u] + 1
            up[0][v] = u
            stack.append(v)
    up[0][1] = 0  # Root has no parent

    for k in range(1, log_max):
        for v in range(1, n + 1):
            up[k][v] = up[k-1][up[k-1][v]]

    # Compute subtree sizes and heavy child
    size = [1] * (n + 1)
    stack = [(1, False)]
    while stack:
        u, visited = stack.pop()
        if visited:
            max_size = 0
            heavy = -1
            for v in children[u]:
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy = v
            # Rearrange children to have heavy child first
            if heavy != -1:
                idx = children[u].index(heavy)
                children[u][0], children[u][idx] = children[u][idx], children[u][0]
        else:
            stack.append((u, True))
            for v in reversed(children[u]):
                stack.append((v, False))

    # HLD to compute head and pos
    head = [0] * (n + 1)
    pos = [0] * (n + 1)
    current_pos = 0
    stack = [(1, 1)]
    while stack:
        u, h = stack.pop()
        head[u] = h
        pos[u] = current_pos
        current_pos += 1
        # Process children, heavy child first
        if children[u]:
            heavy = children[u][0]
            stack.append((heavy, h))
            for v in reversed(children[u][1:]):
                stack.append((v, v))

    # LCA function
    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u up to the depth of v
        for k in range(log_max-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(log_max-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Function to get path segments
    def get_path_segments(u, v):
        ancestor = lca(u, v)
        segments = []
        # Move u to ancestor
        while u != ancestor:
            if head[u] == head[ancestor]:
                segments.append((pos[ancestor], pos[u]))
                break
            segments.append((pos[head[u]], pos[u]))
            u = parent[head[u]]
        # Move v to ancestor
        while v != ancestor:
            if head[v] == head[ancestor]:
                segments.append((pos[ancestor], pos[v]))
                break
            segments.append((pos[head[v]], pos[v]))
            v = parent[head[v]]
        return segments

    # Read additional edges and sort by -c
    edges = []
    for _ in range(m):
        u, v, c = map(int, stdin.readline().split())
        edges.append((-c, u, v))
    edges.sort()

    # Segment Tree with lazy propagation
    class SegmentTree:
        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.size = self.n
            self.tree = [False] * (2 * self.n)
            self.lazy = [False] * (2 * self.n)

        def _push(self, node, l, r):
            if self.lazy[node]:
                self.tree[node] = True
                if l != r:
                    self.lazy[2*node] = True
                    self.lazy[2*node+1] = True
                self.lazy[node] = False

        def update_range(self, a, b):
            def _update(node, l, r, a, b):
                self._push(node, l, r)
                if a > r or b < l:
                    return
                if a <= l and r <= b:
                    self.lazy[node] = True
                    self._push(node, l, r)
                    return
                mid = (l + r) // 2
                _update(2*node, l, mid, a, b)
                _update(2*node+1, mid+1, r, a, b)
                self.tree[node] = self.tree[2*node] or self.tree[2*node+1]
            _update(1, 0, self.n - 1, a, b)

        def query_range(self, a, b):
            def _query(node, l, r, a, b):
                self._push(node, l, r)
                if a > r or b < l:
                    return False
                if a <= l and r <= b:
                    return self.tree[node]
                mid = (l + r) // 2
                return _query(2*node, l, mid, a, b) or _query(2*node+1, mid+1, r, a, b)
            return _query(1, 0, self.n - 1, a, b)

    st = SegmentTree(n)
    ans = 0

    for c, u, v in edges:
        c = -c
        segments = get_path_segments(u, v)
        valid = True
        for a, b in segments:
            if st.query_range(a, b):
                valid = False
                break
        if valid:
            ans += c
            for a, b in segments:
                st.update_range(a, b)

    print(ans)

