def factorize(z):
    factors = {}
    while z % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        z = z // 2
    i = 3
    while i * i <= z:
        while z % i == 0:
            factors[i] = factors.get(i, 0) + 1
            z = z // i
        i += 2
    if z > 1:
        factors[z] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        for d in divisors:
            current = d
            for _ in range(exp):
                current *= p
                temp.append(current)
        divisors += temp
    return divisors

def count_pairs(Z, M, N):
    if Z == 0:
        return 0
    factors = factorize(Z)
    divisors = generate_divisors(factors)
    count = 0
    for d in divisors:
        if d <= M and (Z // d) <= N:
            count += 1
    return count

