import re
import sys

class Panel:
    def __init__(self, name, x1, y1, x2, y2):
        self.name = name
        self.x1 = x1
        self.y1 = y1
        self.x2 = x2
        self.y2 = y2
        self.children = []

def parse_tag_structure(s):
    tokens = re.split(r'(<[^>]+>)', s)
    tokens = [t.strip() for t in tokens if t.strip()]
    stack = []
    main_panel = None
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.startswith('<') and not token.startswith('</'):
            name = token[1:-1]
            i += 1
            if i >= len(tokens):
                break
            data = tokens[i]
            x1, y1, x2, y2 = map(int, data.split(','))
            panel = Panel(name, x1, y1, x2, y2)
            if stack:
                stack[-1].children.append(panel)
            stack.append(panel)
            i += 1
        elif token.startswith('</'):
            name = token[2:-1]
            if stack:
                popped = stack.pop()
                if not stack:
                    main_panel = popped
            i += 1
        else:
            i += 1
    return main_panel

def find_selected_panel(panel, x, y):
    if not (panel.x1 <= x <= panel.x2 and panel.y1 <= y <= panel.y2):
        return None
    for child in reversed(panel.children):
        result = find_selected_panel(child, x, y)
        if result is not None:
            return result
    return panel

