import itertools
import math

def convex_hull(points):
    points = sorted(points)
    if len(points) == 1:
        return points
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def is_point_inside_convex_hull(q, hull):
    for i in range(len(hull)):
        a = hull[i]
        b = hull[(i+1) % len(hull)]
        cross_prod = (b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0])
        if cross_prod < 0:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    while True:
        N = int(input[idx])
        K = int(input[idx+1])
        idx +=2
        if N ==0 and K ==0:
            break
        points = []
        for _ in range(N):
            x = int(input[idx])
            y = int(input[idx+1])
            points.append((x, y))
            idx +=2
        valid = []
        for m in range(3, N+1):
            for subset in itertools.combinations(points, m):
                hull = convex_hull(subset)
                if len(hull) <3:
                    continue
                all_inside = True
                for p in points:
                    if p in subset:
                        continue
                    if not is_point_inside_convex_hull(p, hull):
                        all_inside = False
                        break
                if all_inside:
                    perimeter = 0.0
                    for i in range(len(hull)):
                        a = hull[i]
                        b = hull[(i+1)%len(hull)]
                        dx = a[0] - b[0]
                        dy = a[1] - b[1]
                        perimeter += math.hypot(dx, dy)
                    valid.append(perimeter)
