    a = list(map(int, sys.stdin.readline().split()))
    total = sum(a)
    if total == 0:
        print(-1)
        return
    if total == 1:
        print(-1)
        return

    prefix = []
    current = 0
    for num in a:
        current += num
        prefix.append(current)

    # Compute GCD of prefix sums
    def compute_gcd(arr):
        from math import gcd
        g = arr[0]
        for num in arr[1:]:
            g = math.gcd(g, num)
            if g == 1:
                break
        return g

    if len(prefix) == 0:
        print(-1)
        return
    gcd_all = compute_gcd(prefix)
    if gcd_all > 1:
        print(0)
        return

    # Find all divisors of total >1
    def get_divisors(s):
        divisors = set()
        for i in range(2, int(math.isqrt(s)) + 1):
            if s % i == 0:
                divisors.add(i)
                if i != s // i:
                    divisors.add(s // i)
        if s > 1:
            divisors.add(s)
        return sorted(divisors)

    divisors = get_divisors(total)
    if not divisors:
        print(-1)
        return

    min_cost = float('inf')
    target = total
    for k in divisors:
        prev = 0
        cost = 0
        valid = True
        for s in prefix:
            m_min = (prev + k -1) // k
            candidate = m_min * k
            if candidate > s:
                cost += candidate - s
                prev = candidate
            else:
                q, r = divmod(s, k)
                options = []
                if q * k >= prev:
                    options.append(q * k)
                if (q +1)*k >= prev:
                    options.append((q+1)*k)
                if not options:
                    options.append(m_min * k)
                best = None
                min_diff = float('inf')
                for opt in options:
                    d = abs(opt - s)
                    if d < min_diff or (d == min_diff and (best is None or opt < best)):
                        min_diff = d
                        best = opt
                cost += min_diff
                prev = best
            if prev > target:
                valid = False
                break
        if valid and prev == target:
            if cost < min_cost:
                min_cost = cost
    if min_cost != float('inf'):
        print(min_cost)
    else:
        print(-1)

