def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, stdin.readline().split())
    edges = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)

    LOG = 20
    parent = [[0]*(n+1) for _ in range(LOG)]
    depth = [0]*(n+1)
    q = deque([1])
    visited = [False]*(n+1)
    visited[1] = True
    while q:
        u = q.popleft()
        for v in edges[u]:
            if not visited[v]:
                visited[v] = True
                parent[0][v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    for k in range(1, LOG):
        for v in range(1, n+1):
            parent[k][v] = parent[k-1][parent[k-1][v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = parent[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if parent[k][u] != parent[k][v]:
                u = parent[k][u]
                v = parent[k][v]
        return parent[0][u]

    edge_dir = {}
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        ancestor = lca(a, b)
        path_a = []
        u = a
        while u != ancestor:
            p = parent[0][u]
            path_a.append((u, p))
            u = p
        path_b = []
        u = b
        while u != ancestor:
            p = parent[0][u]
            path_b.append((p, u))
            u = p
        path = path_a + path_b[::-1]
        for u, v in path:
            if (u, v) in edge_dir:
                if edge_dir[(u, v)] == -1:
                    edge_dir[(u, v)] = 1
                else:
                    if edge_dir[(u, v)] != 1:
                        print(-1)
                        return
            elif (v, u) in edge_dir:
                if edge_dir[(v, u)] == 1:
                    edge_dir[(v, u)] = -1
                else:
                    if edge_dir[(v, u)] != -1:
                        print(-1)
                        return
            else:
                edge_dir[(u, v)] = 1
                edge_dir[(v, u)] = -1

    adj = [[] for _ in range(n+1)]
    in_degree = [0]*(n+1)
    for u in range(1, n+1):
        for v in edges[u]:
            if (u, v) in edge_dir and edge_dir[(u, v)] == 1:
                adj[u].append(v)
                in_degree[v] += 1

    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    if len(topo) != n:
        print(-1)
        return

    c = [0]*(n+1)
