class Node:
    __slots__ = ['start', 'end', 'left', 'right', 'op']
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.op = None  # (xi, yi, timestamp)

def update(node, l, r, xi, yi, timestamp):
    if node.end < l or node.start > r:
        return
    if l <= node.start and node.end <= r:
        if node.op is None or node.op[2] < timestamp:
            node.op = (xi, yi, timestamp)
        return
    else:
        if not node.left:
            mid = (node.start + node.end) // 2
            node.left = Node(node.start, mid)
            node.right = Node(mid + 1, node.end)
        update(node.left, l, r, xi, yi, timestamp)
        update(node.right, l, r, xi, yi, timestamp)

def query_x(node, x):
    max_op = None
    current = node
    while current is not None:
        if current.start <= x <= current.end:
            if current.op is not None:
                if max_op is None or current.op[2] > max_op[2]:
                    max_op = current.op
            if current.left is None:
                break
            mid = (current.start + current.end) // 2
            if x <= mid:
                current = current.left
            else:
                current = current.right
        else:
            break
    return max_op

