def sum_max_subarrays(arr):
    n = len(arr)
    if n == 0:
        return 0
    prev_greater = [-1] * n
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] <= arr[i]:
            stack.pop()
        if stack:
            prev_greater[i] = stack[-1]
        else:
            prev_greater[i] = -1
        stack.append(i)

    next_ge = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and arr[stack[-1]] < arr[i]:
            stack.pop()
        if stack:
            next_ge[i] = stack[-1]
        else:
            next_ge[i] = n
        stack.append(i)

    total = 0
    for i in range(n):
        left = prev_greater[i]
        right = next_ge[i]
        count = (i - left) * (right - i)
        total += arr[i] * count
    return total

