def multiply(m1, m2):
    a = (m1[0][0] * m2[0][0] + m1[0][1] * m2[1][0]) % MOD
    b = (m1[0][0] * m2[0][1] + m1[0][1] * m2[1][1]) % MOD
    c = (m1[1][0] * m2[0][0] + m1[1][1] * m2[1][0]) % MOD
    d = (m1[1][0] * m2[0][1] + m1[1][1] * m2[1][1]) % MOD
    return [[a, b], [c, d]]

def matrix_power(mat, power):
    result = [[1, 0], [0, 1]]  # Identity matrix
    while power > 0:
        if power % 2 == 1:
            result = multiply(result, mat)
        mat = multiply(mat, mat)
        power //= 2
    return result

def compute_fib_pair(k):
    if k == 0:
        return (0, 0)
    if k == 1:
        return (1, 0)
    def fast_doubling(n):
        if n == 0:
            return (0, 1)
        a, b = fast_doubling(n >> 1)
        c = a * (2 * b - a) % MOD
        d = (a * a + b * b) % MOD
        if n & 1:
            return (d, (c + d) % MOD)
        else:
            return (c, d)
    a, b = fast_doubling(k-1)
    return (b, a)

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.sum0 = [0] * (2 * self.size)
        self.sum1 = [0] * (2 * self.size)
        self.lazy = [ [[1,0], [0,1]] for _ in range(2 * self.size) ]
        for i in range(self.n):
            self.sum0[self.size + i] = data[i][0]
            self.sum1[self.size + i] = data[i][1]
        for i in range(self.size-1, 0, -1):
            self.sum0[i] = (self.sum0[2*i] + self.sum0[2*i+1]) % MOD
            self.sum1[i] = (self.sum1[2*i] + self.sum1[2*i+1]) % MOD

    def apply(self, node, matrix):
        s0 = self.sum0[node]
        s1 = self.sum1[node]
        new_s0 = (matrix[0][0] * s0 + matrix[0][1] * s1) % MOD
        new_s1 = (matrix[1][0] * s0 + matrix[1][1] * s1) % MOD
        self.sum0[node] = new_s0
        self.sum1[node] = new_s1
        current_lazy = self.lazy[node]
        new_lazy = [
            [
                (matrix[0][0] * current_lazy[0][0] + matrix[0][1] * current_lazy[1][0]) % MOD,
                (matrix[0][0] * current_lazy[0][1] + matrix[0][1] * current_lazy[1][1]) % MOD
            ],
            [
                (matrix[1][0] * current_lazy[0][0] + matrix[1][1] * current_lazy[1][0]) % MOD,
                (matrix[1][0] * current_lazy[0][1] + matrix[1][1] * current_lazy[1][1]) % MOD
            ]
        ]
        self.lazy[node] = new_lazy

    def push(self, node, l, r):
        if self.lazy[node] != [[1,0], [0,1]] and node < self.size:
            mid = (l + r) // 2
            self.apply(2*node, self.lazy[node])
            self.apply(2*node+1, self.lazy[node])
            self.lazy[node] = [[1,0], [0,1]]

    def range_update(self, a, b, matrix):
        def update(node, l, r):
            if a <= l and r <= b:
                self.apply(node, matrix)
                return
            self.push(node, l, r)
            mid = (l + r) // 2
            if a < mid:
                update(2*node, l, mid)
            if mid < b:
                update(2*node+1, mid, r)
            self.sum0[node] = (self.sum0[2*node] + self.sum0[2*node+1]) % MOD
            self.sum1[node] = (self.sum1[2*node] + self.sum1[2*node+1]) % MOD
        update(1, 0, self.size)

    def range_query(self, a, b):
        res = 0
        def query(node, l, r):
            nonlocal res
            if a <= l and r <= b:
                return self.sum0[node]
            self.push(node, l, r)
            mid = (l + r) // 2
            val = 0
            if a < mid:
                val += query(2*node, l, mid)
            if mid < b:
                val += query(2*node+1, mid, r)
            return val % MOD
        return query(1, 0, self.size)

