def is_bicolorable(n, adj):
    color = [-1] * n
    queue = deque([0])
    color[0] = 0
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if color[v] == -1:
                color[v] = 1 - color[u]
                queue.append(v)
            elif color[v] == color[u]:
                return False
    return True

