def compute_mu():
    mu = [0] * 101
    mu[1] = 1
    for n in range(2, 101):
        temp = n
        is_square_free = True
        factors = {}
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                if cnt > 1:
                    is_square_free = False
                    break
                factors[p] = 1
        if not is_square_free:
            mu[n] = 0
            continue
        if temp > 1:
            factors[temp] = 1
        mu[n] = (-1) ** len(factors)
    return mu

