import math

def compute_gcd(arr):
    current_gcd = 0
    for num in arr:
        current_gcd = math.gcd(current_gcd, abs(num))
    return current_gcd

def prime_factors(n):
    factors = set()
    if n <= 1:
        return factors
    while n % 2 == 0:
        factors.add(2)
        n = n // 2
    i = 3
    max_i = int(math.isqrt(n)) + 1
    while i <= max_i and n > 1:
        while n % i == 0:
            factors.add(i)
            n = n // i
            max_i = int(math.isqrt(n)) + 1
        i += 2
    if n > 1:
        factors.add(n)
    return factors

def sieve(n):
    if n < 2:
        return []
    sieve_list = [True] * (n + 1)
    sieve_list[0] = sieve_list[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve_list[i]:
            sieve_list[i*i : n+1 : i] = [False] * len(sieve_list[i*i : n+1 : i])
    primes = [i for i, is_prime in enumerate(sieve_list) if is_prime]
    return primes

def check_p(p, coefficients, N):
    if p == 0:
        return False
    arr = [0] * p
    for idx in range(len(coefficients)):
        i = N - idx
        a_i = coefficients[idx]
        a_i_mod = a_i % p
        if a_i_mod < 0:
            a_i_mod += p
        if i == 0:
            arr[0] = (arr[0] + a_i_mod) % p
        else:
            if p == 1:
                continue
            e = ((i - 1) % (p - 1)) + 1
            if e < p:
                arr[e] = (arr[e] + a_i_mod) % p
    return all(x == 0 for x in arr)

