    blacks = [ (a, i) for c, a, i in balls if c == 'B' ]
    whites.sort()
    blacks.sort()

    wp = [0] * (N + 1)
    for k in range(1, N+1):
        wp[k] = whites[k-1][1]

    bp = [0] * (N + 1)
    for k in range(1, N+1):
        bp[k] = blacks[k-1][1]

    # Precompute w_prev and b_prev
    w_prev = [0] * (N + 1)
    for k in range(1, N+1):
        cnt = 0
        for m in range(1, k):
            if wp[m] > wp[k]:
                cnt += 1
        w_prev[k] = cnt

    b_prev = [0] * (N + 1)
    for l in range(1, N+1):
        cnt = 0
        for m in range(1, l):
            if bp[m] > bp[l]:
                cnt += 1
        b_prev[l] = cnt

    # Precompute bc_white and wc_black
    bc_white = [ [0]*(N+1) for _ in range(N+1) ]
    for k in range(1, N+1):
        current = 0
        for j in range(1, N+1):
            if bp[j] > wp[k]:
                current += 1
            bc_white[k][j] = current

    wc_black = [ [0]*(N+1) for _ in range(N+1) ]
    for l in range(1, N+1):
        current = 0
        for i in range(1, N+1):
            if wp[i] > bp[l]:
                current += 1
            wc_black[l][i] = current

    # Initialize DP
    INF = float('inf')
    dp = [ [INF]*(N+1) for _ in range(N+1) ]
    dp[0][0] = 0

    for s in range(0, 2*N + 1):
        for i in range(0, s + 1):
            j = s - i
            if i > N or j > N:
                continue
            if dp[i][j] == INF:
                continue

            # Transition to white i+1
            if i < N:
                next_i = i + 1
                cost = w_prev[next_i] + bc_white[next_i][j]
                if dp[next_i][j] > dp[i][j] + cost:
                    dp[next_i][j] = dp[i][j] + cost

            # Transition to black j+1
            if j < N:
                next_j = j + 1
                cost = b_prev[next_j] + wc_black[next_j][i]
                if dp[i][next_j] > dp[i][j] + cost:
                    dp[i][next_j] = dp[i][j] + cost

    print(dp[N][N])

