def build_adjacency(data):
    adj = defaultdict(set)
    nodes = set()
    for a, b in data:
        if a == 0 and b == 0:
            continue
        adj[a].add(b)
        adj[b].add(a)
        nodes.add(a)
        nodes.add(b)
    return adj, nodes

def find_dominators(adj, start, end):
    dominators = {node: set(nodes) for node in nodes}
    dominators[start] = {start}
    changed = True
    nodes_list = list(nodes)
    while changed:
        changed = False
        for node in nodes_list:
            if node == start:
                continue
            new_dom = set(nodes)
            for pred in adj[node]:
                if pred == node:
                    continue
                if node in adj[pred]:
                    new_dom.intersection_update(dominators[pred])
            new_dom.add(node)
            if new_dom != dominators[node]:
                dominators[node] = new_dom.copy()
                changed = True
    return dominators

def is_linear_dominator_chain(dominators, start, end):
    dom_list = []
    current = end
    while True:
        found = False
        for node in dominators[current]:
            if node == current:
                continue
            if node in dominators[current]:
                dom_list.append(current)
                current = node
                found = True
                break
        if not found:
            break
    dom_list.append(start)
    dom_list = dom_list[::-1]
    if dom_list[0] != start or dom_list[-1] != end:
        return False
    for i in range(1, len(dom_list)):
        if dom_list[i-1] not in dominators[dom_list[i]]:
            return False
    return True

