import math
from collections import defaultdict

def is_zero(poly):
    return not poly or all(coeff == 0 for coeff in poly.values())

def add_poly(p1, p2):
    result = defaultdict(int)
    for exp, coeff in p1.items():
        result[exp] += coeff
    for exp, coeff in p2.items():
        result[exp] += coeff
    return {exp: c for exp, c in result.items() if c != 0}

def sub_poly(p1, p2):
    result = defaultdict(int)
    for exp, coeff in p1.items():
        result[exp] += coeff
    for exp, coeff in p2.items():
        result[exp] -= coeff
    return {exp: c for exp, c in result.items() if c != 0}

def mul_poly(p1, p2):
    result = defaultdict(int)
    for exp1, coeff1 in p1.items():
        for exp2, coeff2 in p2.items():
            exp = exp1 + exp2
            result[exp] += coeff1 * coeff2
    return {exp: c for exp, c in result.items() if c != 0}

def multiply_poly_by_constant(p, c):
    return {exp: coeff * c for exp, coeff in p.items()} if c != 0 else {}

def multiply_poly_by_x_power(p, e):
    return {exp + e: coeff for exp, coeff in p.items()}

def degree(poly):
    if not poly:
        return -1
    return max(poly.keys())

def get_leading_coeff(poly):
    if not poly:
        return 0
    return poly[degree(poly)]

def content(poly):
    if not poly:
        return 0
    coeffs = poly.values()
    current_gcd = abs(next(iter(coeffs)))
    for coeff in coeffs:
        current_gcd = math.gcd(current_gcd, abs(coeff))
        if current_gcd == 1:
            break
    return current_gcd

def make_primitive(poly):
    c = content(poly)
    return {exp: coeff // c for exp, coeff in poly.items()} if c != 0 else {}

def poly_div(a, b):
    quotient = defaultdict(int)
    remainder = defaultdict(int, a)
    a_deg = degree(a)
    b_deg = degree(b)
    if b_deg == -1:
        raise ValueError("Division by zero polynomial")
    lc_b = get_leading_coeff(b)
    while (a_deg := degree(remainder)) >= b_deg and not is_zero(remainder):
        exp_diff = a_deg - b_deg
        lc_r = get_leading_coeff(remainder)
        q_coeff = lc_r // lc_b
        term = multiply_poly_by_constant(b, q_coeff)
        term = multiply_poly_by_x_power(term, exp_diff)
        remainder = sub_poly(remainder, term)
        quotient[exp_diff] = q_coeff
    return dict(quotient), dict(remainder)

def pseudo_remainder(a, b):
    m = degree(a)
    n = degree(b)
    if m < n:
        return dict(a)
    lc_b = get_leading_coeff(b)
    d = m - n
    factor = lc_b ** (d + 1)
    a_scaled = multiply_poly_by_constant(a, factor)
    _, rem = poly_div(a_scaled, b)
    return rem

def poly_gcd(a, b):
    a = make_primitive(a)
    b = make_primitive(b)
    while not is_zero(b):
        prem = pseudo_remainder(a, b)
        prem = make_primitive(prem)
        a, b = b, prem
    return a

def normalize_poly(poly):
    if not poly:
        return {}
    c = content(poly)
    if c == 0:
        return {}
    normalized = {exp: coeff // c for exp, coeff in poly.items()}
    lc = get_leading_coeff(normalized)
    if lc < 0:
        normalized = multiply_poly_by_constant(normalized, -1)
    return normalized

class Parser:
    def __init__(self, s):
        self.s = s.replace(' ', '')
        self.pos = 0
        self.n = len(self.s)

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        terms = []
        sign = 1
        if self.current() == '-':
            sign = -1
            self.consume()
        elif self.current() == '+':
            self.consume()
        term = self.parse_term()
        term = multiply_poly_by_constant(term, sign)
        terms.append(term)
        while self.current() in '+-':
            op = self.consume()
            term = self.parse_term()
            term = multiply_poly_by_constant(term, -1 if op == '-' else 1)
            terms.append(term)
        result = {}
        for t in terms:
            result = add_poly(result, t)
        return result

    def parse_term(self):
        factors = []
        while self.current() not in '+-)':
            if self.current() is None:
                break
            factor = self.parse_factor()
            factors.append(factor)
        if not factors:
            return {}
        result = factors[0]
        for f in factors[1:]:
            result = mul_poly(result, f)
        return result

    def parse_factor(self):
        primary = self.parse_primary()
        if self.current() == '^':
            self.consume()
            exponent = self.parse_digits()
            return self.pow_poly(primary, exponent)
        return primary

    def pow_poly(self, p, exponent):
        result = {0:1}
        for _ in range(exponent):
            result = mul_poly(result, p)
        return result

    def parse_primary(self):
        c = self.current()
        if c == 'x':
            self.consume()
            return {1:1}
        elif c == '(':
            self.consume()
            expr = self.parse_expression()
            if self.current() == ')':
                self.consume()
            return expr
        elif c.isdigit():
            num = self.parse_digits()
            return {0: num}
        elif c == '-':
            self.consume()
            return multiply_poly_by_constant(self.parse_primary(), -1)
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_digits(self):
        start = self.pos
        while self.current() and self.current().isdigit():
            self.consume()
        return int(self.s[start:self.pos])

    def current(self):
        return self.s[self.pos] if self.pos < self.n else None

    def consume(self):
        if self.pos < self.n:
            self.pos +=1

def format_poly(poly):
    if not poly:
        return "0"
    sorted_terms = sorted(poly.items(), key=lambda x: (-x[0], x[0]))
    output = []
    for i, (exp, coeff) in enumerate(sorted_terms):
        if coeff == 0:
            continue
        abs_coeff = abs(coeff)
        if exp == 0:
            term = f"{abs_coeff}"
        else:
            if abs_coeff == 1:
                coeff_str = "" if exp == 0 else ""
            else:
                coeff_str = f"{abs_coeff}"
            if exp == 1:
                x_part = "x"
            else:
                x_part = f"x^{exp}"
            term = f"{coeff_str}{x_part}" if coeff_str else x_part
        if i == 0:
            if coeff < 0:
                output.append(f"-{term}")
            else:
                output.append(term)
        else:
            if coeff < 0:
                output.append(f" - {term}")
            else:
                output.append(f" + {term}")
    if not output:
        return "0"
    return ''.join(output).replace(" 1x", " x").replace("-1x", "-x")

def main():
    while True:
        line = sys.stdin.readline().strip()
        if line == '.':
            break
        line2 = sys.stdin.readline().strip()
        poly1 = Parser(line).parse()
        poly2 = Parser(line2).parse()
        gcd = poly_gcd(poly1, poly2)
        normalized = normalize_poly(gcd)
        print(format_poly(normalized))

