def main():
    while True:
        N, M, L, K = map(int, sys.stdin.readline().split())
        if N == M == L == K == 0:
            break
        edges = [[] for _ in range(N+1)]  # 1-based
        for _ in range(M):
            u, v, c = map(int, sys.stdin.readline().split())
            edges[u].append((v, c))
            edges[v].append((u, c))
        S, G = map(int, sys.stdin.readline().split())
        B = []
        ball_to_index = {}
        for idx in range(L):
            b = int(sys.stdin.readline())
            B.append(b)
            ball_to_index[b] = idx

        full_mask = (1 << L) - 1

        initial_mask = 0
        for i in range(L):
            if B[i] == S:
                initial_mask |= (1 << i)

        dist = defaultdict(list)
        heap = []
        heapq.heappush(heap, (0, S, initial_mask))
        if (S, initial_mask) not in dist:
            dist[(S, initial_mask)] = []
        bisect.insort(dist[(S, initial_mask)], 0)
        if len(dist[(S, initial_mask)]) > K:
            dist[(S, initial_mask)] = dist[(S, initial_mask)][:K]

        target_times = []
        found = False

        while heap:
            current_time, u, mask = heapq.heappop(heap)

            if u == G and mask == full_mask:
                pos = bisect.bisect_left(target_times, current_time)
                if pos >= len(target_times) or target_times[pos] != current_time:
                    bisect.insort(target_times, current_time)
                    if len(target_times) == K:
                        print(current_time)
                        found = True
                        break

            if (u, mask) not in dist:
                continue
            current_list = dist[(u, mask)]
            idx = bisect.bisect_left(current_list, current_time)
            if idx >= len(current_list) or current_list[idx] != current_time:
                continue

            for v, c in edges[u]:
                new_time = current_time + c
                new_mask = mask
                if v in ball_to_index:
                    i = ball_to_index[v]
                    if not (mask & (1 << i)):
                        new_mask = mask | (1 << i)

                key = (v, new_mask)
                if key not in dist:
                    dist[key] = []
                times_list = dist[key]
                pos = bisect.bisect_left(times_list, new_time)
                if pos < len(times_list) and times_list[pos] == new_time:
                    continue
                if len(times_list) < K or (len(times_list) >= K and new_time < times_list[-1]):
                    bisect.insort(times_list, new_time)
                    if len(times_list) > K:
                        times_list.pop()
                    heapq.heappush(heap, (new_time, v, new_mask))

        if not found:
            if len(target_times) >= K:
                print(target_times[K-1])
            else:
                print("NA")

