            else:
                Single_spells.append((damage, mp))
        max_HP = max(HPs)
        max_x = max_HP
        dp_single = [float('inf')] * (max_x + 1)
        dp_single[0] = 0
        for x in range(max_x + 1):
            for (d, m) in Single_spells:
                prev_x = max(x - d, 0)
                if dp_single[prev_x] + m < dp_single[x]:
                    dp_single[x] = dp_single[prev_x] + m
        max_all_damage = max_HP
        dp_all = [float('inf')] * (max_all_damage + 1)
        dp_all[0] = 0
        for s in range(max_all_damage + 1):
            if dp_all[s] == float('inf'):
                continue
            for (d, m) in All_spells:
                next_s = s + d
                if next_s > max_all_damage:
                    next_s = max_all_damage
                if dp_all[s] + m < dp_all[next_s]:
                    dp_all[next_s] = dp_all[s] + m
        min_total = float('inf')
        for s in range(max_all_damage + 1):
            if dp_all[s] == float('inf'):
                continue
            cost_all = dp_all[s]
            cost_single = 0
            valid = True
            for hp in HPs:
                rem = max(0, hp - s)
                if rem == 0:
