import sys

def determine_direction(N):
    parity = N % 2
    start_L = 1 if parity else 2
    for L in range(start_L, 60, 2):
        if L >= N:
            break
        E = N - L
        if E < (1 << L):  # 2^L
            continue
        if E > (1 << (L + 1)) - 2:
            continue
        if E % 4 == 0:
            return "LEFT"
        else:
            return "RIGHT"
    return "NO"

