from collections import deque

def multiply(a, b):
    return tuple(a[x] for x in b)

def compute_closure(generators):
    if not generators:
        return frozenset()
    closure_set = set(generators)
    queue = deque(closure_set)
    while queue:
        a = queue.popleft()
        for b in list(closure_set):
            for c in (multiply(a, b), multiply(b, a)):
                if c not in closure_set:
                    closure_set.add(c)
                    queue.append(c)
    return frozenset(closure_set)

