    groups_prev = {}

    for r in range(n):
        current_perm = permutations[r]
        new_groups = {}

        single_generators = [current_perm]
        single_group = compute_closure(single_generators)
        new_groups[single_group] = new_groups.get(single_group, 0) + 1

        for group, cnt in groups_prev.items():
