                combined_group = group
            else:
                generators = list(group) + [current_perm]
                combined_group = compute_closure(generators)
            new_groups[combined_group] = new_groups.get(combined_group, 0) + cnt

        current_sum = sum(len(g) * c for g, c in new_groups.items())
