import sys
from collections import deque

def hopcroft_karp(adj, num_right):
    N_left = len(adj)
    pair_u = [-1] * N_left
    pair_v = [-1] * num_right
    dist = [0] * N_left

    def bfs():
        queue = deque()
        for u in range(N_left):
            if pair_u[u] == -1:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        dist_null = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < dist_null:
                for v in adj[u]:
                    if pair_v[v] == -1:
                        dist_null = dist[u] + 1
                    elif dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        queue.append(pair_v[v])
        return dist_null != float('inf')

    def dfs(u):
        for v in adj[u]:
            if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = float('inf')
        return False

    result = 0
    while bfs():
        for u in range(N_left):
            if pair_u[u] == -1:
                if dfs(u):
                    result += 1
    return result

def main():
    import bisect
    N, M = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(M):
        u, v, d = map(int, sys.stdin.readline().split())
        edges.append( (d, u-1, v-1) )  # convert to 0-based
    edges.sort()
    sorted_d = [e[0] for e in edges]

    # Check if full graph has a perfect matching
    full_adj = [[] for _ in range(N)]
    for d, u, v in edges:
        full_adj[u].append(v)
    if hopcroft_karp(full_adj, N) != N:
        print(-1)
        return

    # Binary search on d
    low = edges[0][0]
    high = edges[-1][0]
    answer = high

    while low <= high:
        mid = (low + high) // 2
        k = bisect.bisect_right(sorted_d, mid)
        adj = [[] for _ in range(N)]
        for i in range(k):
            d, u, v = edges[i]
            adj[u].append(v)
        current_match = hopcroft_karp(adj, N)
        if current_match == N:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    print(answer)

