def compute_total(m):
    state = 0
    total = 0
    steps = 0
    visited = {}
    while steps < m:
        if state in visited:
            prev_steps, prev_total = visited[state]
            cycle_steps = steps - prev_steps
            cycle_total = total - prev_total
            if cycle_steps <= 0:
                break
            remaining = m - steps
            num_cycles = remaining // cycle_steps
            total += num_cycles * cycle_total
            steps += num_cycles * cycle_steps
            if steps >= m:
                break
            visited = {}
        else:
            visited[state] = (steps, total)
        a_used_step, new_state = transitions[state]
        total += a_used_step
        steps += 1
        state = new_state
    return total

