import sys
from math import gcd
from collections import deque

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for i in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        for j in range(n):
            if row[j] > 0:
                adj[i].append(j)
                rev_adj[j].append(i)

    # Check if the graph is strongly connected
    def is_strongly_connected():
        visited = [False] * n
        q = deque([0])
        visited[0] = True
        count = 1
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    count += 1
                    q.append(v)
        if count != n:
            return False

        visited = [False] * n
        q = deque([0])
        visited[0] = True
        count = 1
        while q:
            u = q.popleft()
            for v in rev_adj[u]:
                if not visited[v]:
                    visited[v] = True
                    count += 1
                    q.append(v)
        return count == n

    if not is_strongly_connected():
        print("NO")
        return

    # Compute shortest paths from node 0 using BFS
    s = [-1] * n
    q = deque([0])
    s[0] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if s[v] == -1:
                s[v] = s[u] + 1
                q.append(v)

    # Calculate the gcd of all deltas
    current_gcd = 0
    for u in range(n):
        for v in adj[u]:
            delta = s[u] + 1 - s[v]
            current_gcd = gcd(current_gcd, delta)

    print("YES" if current_gcd == 1 else "NO")

