import sys
import functools

@functools.lru_cache(maxsize=None)
def min_cost(h, w, s):
    if h > w:
        return min_cost(w, h, s)
    if s == 0 or s == h * w:
        return 0
    min_total = float('inf')
    # Vertical splits (along width)
    for w1 in range(1, w):
        w2 = w - w1
        cost_split = h ** 2
        max_s1 = min(h * w1, s)
        min_s1 = max(0, s - h * w2)
        for s1 in range(min_s1, max_s1 + 1):
            s2 = s - s1
            if s2 < 0 or s2 > h * w2:
                continue
            current = cost_split + min_cost(h, w1, s1) + min_cost(h, w2, s2)
            if current < min_total:
                min_total = current
    # Horizontal splits (along height)
    for h1 in range(1, h):
        h2 = h - h1
        cost_split = w ** 2
        max_s1 = min(h1 * w, s)
        min_s1 = max(0, s - h2 * w)
        for s1 in range(min_s1, max_s1 + 1):
            s2 = s - s1
            if s2 < 0 or s2 > h2 * w:
                continue
            current = cost_split + min_cost(h1, w, s1) + min_cost(h2, w, s2)
            if current < min_total:
                min_total = current
    return min_total if min_total != float('inf') else 0

