for k in range(2, n + 1):
    p = parents[k - 2]
    depth[k] = depth[p] + 1
    jump[k][0] = p
    for i in range(1, max_level):
        if jump[k][i - 1] != -1:
            jump[k][i] = jump[jump[k][i - 1]][i - 1]
        else:
