def get_lca(a, b):
    if depth[a] < depth[b]:
        a, b = b, a
    for i in range(max_level-1, -1, -1):
        if depth[a] - (1 << i) >= depth[b]:
            a = jump[a][i]
    if a == b:
        return a
    for i in range(max_level-1, -1, -1):
        if jump[a][i] != -1 and jump[a][i] != jump[b][i]:
            a = jump[a][i]
            b = jump[b][i]
    return jump[a][0]

