    lca_ku = get_lca(k, u)
    d1 = depth[k] + depth[u] - 2 * depth[lca_ku]
    lca_kv = get_lca(k, v)
    d2 = depth[k] + depth[v] - 2 * depth[lca_kv]
    max_dist = max(d1, d2)

    if max_dist > current_diameter:
        current_diameter = max_dist
        if d1 > d2:
            v = k
        else:
            u = k
    output.append(str(current_diameter))

