        prev_speeds.append(s // 3)  # 3x pressed
    prev_speeds.append(s * 3)       # 1/3x pressed
    return prev_speeds

def solve(t):
    if t == 0:
        return 0
    visited = {}
    queue = deque()
    queue.append((t, 1, 0))
    visited[(t, 1)] = 0
    while queue:
        sum_remaining, current_speed, steps = queue.popleft()
        new_sum = sum_remaining - current_speed
        if new_sum == 0:
            return steps + 1
        if new_sum < 0:
            continue
        for prev_s in get_prev_speeds(current_speed):
            if prev_s <= 0:
                continue
            key = (new_sum, prev_s)
            if key in visited:
                if visited[key] <= steps + 1:
                    continue
            visited[key] = steps + 1
            queue.append((new_sum, prev_s, steps + 1))
    return -1

