import math

def find_rent_plan(b):
    s = 2 * b
    max_m = int(math.sqrt(s))
    for m in range(max_m, 0, -1):
        if s % m != 0:
            continue
        temp = (s // m) - m + 1
        if temp <= 0 or temp % 2 != 0:
            continue
        k = temp // 2
        if k > 0:
            return (k, m)
    return (b, 1)

