def calculate_swaps(arr, is_peak):
    array = arr.copy()
    swaps = 0
    length = len(array)
    for i in range(1, length - 1, 2):
        current = array[i]
        left = array[i-1]
        right = array[i+1]
        if is_peak:
            if current > left and current > right:
                continue
            if left > right:
                array[i], array[i-1] = array[i-1], array[i]
            else:
                array[i], array[i+1] = array[i+1], array[i]
            swaps += 1
        else:
            if current < left and current < right:
                continue
            if left < right:
                array[i], array[i-1] = array[i-1], array[i]
            else:
                array[i], array[i+1] = array[i+1], array[i]
            swaps += 1
    return swaps

