class Node:
    def __init__(self, key, priority):
        self.key = key
        self.priority = priority
        self.left = None
        self.right = None

def right_rotate(t):
    s = t.left
    t.left = s.right
    s.right = t
    return s

def left_rotate(t):
    s = t.right
    t.right = s.left
    s.left = t
    return s

def insert(t, key, priority):
    if t is None:
        return Node(key, priority)
    if key == t.key:
        return t
    if key < t.key:
        t.left = insert(t.left, key, priority)
        if t.left.priority > t.priority:
            t = right_rotate(t)
    else:
        t.right = insert(t.right, key, priority)
        if t.right.priority > t.priority:
            t = left_rotate(t)
    return t

def find(t, key):
    while t is not None:
        if t.key == key:
            return True
        t = t.left if key < t.key else t.right
    return False

def delete(t, key):
    if t is None:
        return None
    if key < t.key:
        t.left = delete(t.left, key)
    elif key > t.key:
        t.right = delete(t.right, key)
    else:
        if t.left is None and t.right is None:
            return None
        if t.left is None:
            t = left_rotate(t)
            t.left = delete(t.left, key)
        elif t.right is None:
            t = right_rotate(t)
            t.right = delete(t.right, key)
        else:
            if t.left.priority > t.right.priority:
                t = right_rotate(t)
                t.right = delete(t.right, key)
            else:
                t = left_rotate(t)
                t.left = delete(t.left, key)
    return t

def inorder(t):
    res = []
    def _inorder(node):
        if node:
            _inorder(node.left)
            res.append(node.key)
            _inorder(node.right)
    _inorder(t)
    return res

def preorder(t):
    res = []
    def _preorder(node):
        if node:
            res.append(node.key)
            _preorder(node.left)
            _preorder(node.right)
    _preorder(t)
    return res

