import sys
from collections import deque

def main():
    n, m, a, b = map(int, sys.stdin.readline().split())
    grid = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]

    # Compute prefix sums
    prefix = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(m):
            prefix[i+1][j+1] = grid[i][j] + prefix[i+1][j] + prefix[i][j+1] - prefix[i][j]

    # Compute row-wise sliding minimum
    row_minima = []
    for row in grid:
        q = deque()
        row_min = []
        for j in range(len(row)):
            while q and row[q[-1]] >= row[j]:
                q.pop()
            q.append(j)
            while q[0] <= j - b:
                q.popleft()
            if j >= b - 1:
                row_min.append(row[q[0]])
        row_minima.append(row_min)

    # Compute column-wise sliding minimum
    col_minima = []
    for j in range(len(row_minima[0])):
        column = [row_minima[i][j] for i in range(n)]
        q = deque()
        col_min = []
        for i in range(len(column)):
            while q and column[q[-1]] >= column[i]:
                q.pop()
            q.append(i)
            while q[0] <= i - a:
                q.popleft()
            if i >= a - 1:
                col_min.append(column[q[0]])
        col_minima.append(col_min)

    # Generate all possible windows
    windows = []
    for i in range(n - a + 1):
        for j in range(m - b + 1):
            # Calculate sum of the window
            sum_rect = prefix[i+a][j+b] - prefix[i][j+b] - prefix[i+a][j] + prefix[i][j]
            # Get min from col_minima
            min_rect = col_minima[j][i]
            removal_cost = sum_rect - min_rect * a * b
            windows.append((removal_cost, i, j))

    # Sort windows by removal cost, then row, then column
    windows.sort(key=lambda x: (x[0], x[1], x[2]))

    # Track blocked cells using bitmasks for each row
    row_bitmask = [0] * n
    result = []

    for cost, i, j in windows:
        # Check if the window is available
        mask = ((1 << b) - 1) << j
        available = True
        for r in range(i, i + a):
            if r >= n:
                available = False
                break
            if (row_bitmask[r] & mask) != 0:
                available = False
                break
        if not available:
            continue
        # Add to result (convert to 1-based)
        result.append((i + 1, j + 1, cost))
        # Update row_bitmask
        for r in range(i, i + a):
            if r >= n:
                break
            row_bitmask[r] |= mask

    # Output
    print(len(result))
    for res in result:
        print(' '.join(map(str, res)))

