    parent = [0] * (n + 1)
    size = [1] * (n + 1)
    visited = [False] * (n + 1)
    q = deque([1])
    visited[1] = True
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v, idx in adj[u]:
            if not visited[v] and v != parent[u]:
                parent[v] = u
                visited[v] = True
                q.append(v)

    # Compute sizes via post-order
    for u in reversed(order):
        for v, idx in adj[u]:
            if v != parent[u]:
                size[u] += size[v]

    candidate = None
    for i in range(n - 1):
        x, y = edges[i]
        if parent[x] == y:
            x, y = y, x
        if parent[y] == x:
            s = size[y]
            if s == k or (n - s) == k:
