    # If no candidate edge, proceed with DP
    adj_list = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v, idx in adj[u]:
            if v == parent[u]:
                adj_list[u].append(v)

    # DP tables and backtrack info
    INF = float('inf')
    dp = [{} for _ in range(n + 1)]
    back = [{} for _ in range(n + 1)]

    # Initialize DP
    for u in range(1, n + 1):
        dp[u][1] = len(adj[u])
        back[u][1] = (None, None)

    # Post-order traversal for DP
    for u in reversed(order):
        for v, idx in adj[u]:
            if parent[v] == u:
                # Process child v
                for s in list(dp[u].keys())[::-1]:
                    for t in dp[v]:
                        if s + t > k:
                            continue
                        new_s = s + t
                        new_sum = dp[u][s] + dp[v][t] - 2  # subtract the edge u-v counted twice
                        if new_s not in dp[u] or new_sum < dp[u][new_s]:
                            dp[u][new_s] = new_sum
                            back[u][new_s] = (v, t)

    # Find the minimal sum_deg and corresponding node
