    def backtrack(u, s):
        nonlocal S
        S.add(u)
        if s == 1:
            return
        while s > 1:
            if u not in back or s not in back[u]:
                break
            v, t = back[u][s]
            if v is None:
                break
            backtrack(v, t)
            s -= t

    backtrack(best_node, k)

    # Collect edges that cross S
    problem = []
    for idx, (x, y) in enumerate(edges, 1):
        if (x in S) ^ (y in S):
            problem.append(idx)

