memo = {}

def dp(i, decider):
    if i == n:
        return (0, 0)
    key = (i, decider)
    if key in memo:
        return memo[key]

    s_i = s[i]

    # Option 1: take the slice, next decider is flipped
    next_decider = 1 - decider
    a1, b1 = dp(i+1, next_decider)
    if decider:
        option1 = (a1, b1 + s_i)
    else:
        option1 = (a1 + s_i, b1)

    # Option 2: give the slice, next decider remains
    a2, b2 = dp(i+1, decider)
    if decider:
        option2 = (a2 + s_i, b2)
    else:
        option2 = (a2, b2 + s_i)

    # Choose the best option based on current decider's interest
    if decider:
        best = option1 if option1[1] >= option2[1] else option2
    else:
        best = option1 if option1[0] >= option2[0] else option2

    memo[key] = best
    return best

