        L = int(input[idx])
        idx += 1
        for k in range(L):
            section = (a + k) % N
            painted[section] = True

    parent = list(range(N))
    size = [1] * N

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if size[u_root] < size[v_root]:
            parent[u_root] = v_root
            size[v_root] += size[u_root]
        else:
            parent[v_root] = u_root
            size[u_root] += size[v_root]

    for i in range(N):
        if painted[i]:
            next_i = (i + 1) % N
            if painted[next_i]:
                union(i, next_i)

    counts = defaultdict(int)
    processed = set()
    for i in range(N):
        if painted[i]:
            root = find(i)
            if root not in processed:
                counts[size[root]] += 1
                processed.add(root)

    sorted_counts = sorted(counts.items(), key=lambda x: (-x[0], x[1]))
    for length, count in sorted_counts:
        print(f"{length} {count}")

