import sys

def get_prime_factors(n):
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n = n // 2
    i = 3
    max_factor = math.isqrt(n)
    while i <= max_factor and n > 1:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n = n // i
            max_factor = math.isqrt(n)
        i += 2
    if n > 1:
        factors.add(n)
    return sorted(factors)

def compute_key(n):
    factors = get_prime_factors(n)
    if not factors:
        return 0
    largest = factors[-1]
    sum_others = sum(factors) - largest
    return largest - sum_others

