        y = int(input[ptr+1])
        c = int(input[ptr+2])
        ptr += 3
        if y not in colored[x]:
            colored[x][y] = c
    f = []
    for _ in range(3):
        row = list(map(int, input[ptr:ptr+3]))
        ptr += 3
        f.append(row)

    # Precompute for each strip the possible grundy numbers and their counts
    strips = []
    for i in range(n):
        strip_len = a[i]
        strip_num = i+1
        pre_colors = colored[strip_num]
        dp = [{} for _ in range(strip_len + 4)]
        dp[0] = {0: 1}
        for x in range(1, strip_len + 1):
            if x in pre_colors:
                c = pre_colors[x]
                allowed = []
                for j in [1,2,3]:
                    if x - j >= 0 and f[c-1][j-1]:
                        allowed.append(j)
                s = set()
                for j in allowed:
                    if x - j >= 0:
                        s.update(dp[x - j].keys())
                mex = 0
                while mex in s:
                    mex += 1
                if mex in dp[x]:
                    dp[x][mex] = (dp[x][mex] + 1) % MOD
                else:
                    dp[x][mex] = 1
            else:
                cnt = {}
                for c in [1,2,3]:
                    allowed = []
                    for j in [1,2,3]:
                        if x - j >= 0 and f[c-1][j-1]:
                            allowed.append(j)
                    s = set()
                    for j in allowed:
                        if x - j >= 0:
                            s.update(dp[x - j].keys())
                    mex = 0
                    while mex in s:
                        mex += 1
                    if mex in cnt:
                        cnt[mex] += 1
                    else:
                        cnt[mex] = 1
                for key in cnt:
                    if key in dp[x]:
                        dp[x][key] = (dp[x][key] + cnt[key]) % MOD
                    else:
                        dp[x][key] = cnt[key] % MOD
        target_x = a[i]
        if target_x > strip_len:
            grundies = {0: 0}
        else:
            grundies = dp[target_x]
        strips.append(grundies)

    dp_xor = {0: 1}
    for strip in strips:
        new_dp = {}
        for g in strip:
            cnt = strip[g]
            for x in dp_xor:
                new_x = x ^ g
                ways = (dp_xor[x] * cnt) % MOD
                if new_x in new_dp:
                    new_dp[new_x] = (new_dp[new_x] + ways) % MOD
                else:
                    new_dp[new_x] = ways % MOD
        dp_xor = new_dp

    print(dp_xor.get(0, 0) % MOD)

