import sys
from collections import defaultdict

def main():
    n, m, q = map(int, sys.stdin.readline().split())
    if m == 1:
        for _ in range(q):
            print(-1)
        return

    rows = [{} for _ in range(n+1)]  # 1-based

    # For each row, track the first two differing columns
    # For each row, track all columns in a BIT
    class BIT:
        def __init__(self, size):
            self.N = size + 2
            self.tree = [0]*(self.N)

        def update(self, idx, val):
            while idx < self.N:
                self.tree[idx] += val
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res % 2

        def range_flip(self, l, r):
            self.update(l, 1)
            self.update(r+1, 1)

    row_bits = [BIT(m) for _ in range(n+1)]  # 1-based

    all_rows = [0]*(n+1)  # 0: all 0, 1: all 1, 2: mixed
    count_all0 = n
    count_all1 = 0

    def get_row_state(a):
        # 0: all 0, 1: all 1, 2: mixed
        is_all0 = True
        is_all1 = True
        for c in range(1, m+1):
            bit = row_bits[a].query(c)
            if bit == 1:
                is_all0 = False
            else:
                is_all1 = False
            if not is_all0 and not is_all1:
                return 2
        if is_all0:
            return 0
        else:
            return 1

    def get_bit(a, c):
        return row_bits[a].query(c)

    def find_two_diff(a, b):
        # Find two columns where a and b differ
        diff = []
        for c in range(1, m+1):
            if get_bit(a, c) != get_bit(b, c):
                diff.append(c)
                if len(diff) >= 2:
                    return diff[0], diff[1]
        return None

    # Track the current certificate
    current = None

    def check_all_pairs():
        # Check all pairs of rows to find a valid certificate
        # First, check if there are both all0 and all1
        if count_all0 > 0 and count_all1 > 0:
            a = None
            b = None
            for i in range(1, n+1):
                if all_rows[i] == 0:
                    a = i
                    break
            for i in range(1, n+1):
                if all_rows[i] == 1:
                    b = i
                    break
            return (a, 1, b, 2)  # columns 1 and 2
        # Check mixed rows
        mixed = []
        for i in range(1, n+1):
            if all_rows[i] == 2:
                mixed.append(i)
        if len(mixed) >= 2:
            # Compare first two mixed rows
            a = mixed[0]
            b = mixed[1]
            diff_cols = find_two_diff(a, b)
            if diff_cols:
                c1, c2 = diff_cols
                return (a, c1, b, c2)
        # Compare mixed with any other
        for a in mixed:
            for b in range(1, n+1):
                if b == a:
                    continue
                diff_cols = find_two_diff(a, b)
                if diff_cols:
                    c1, c2 = diff_cols
                    return (a, c1, b, c2)
        # Check for inverse rows
        hash_map = defaultdict(int)
        for i in range(1, n+1):
            hash_val = tuple([get_bit(i, c) for c in range(1, m+1)])
            hash_map[hash_val] = i
            inv_hash = tuple([1 - bit for bit in hash_val])
            if inv_hash in hash_map:
                j = hash_map[inv_hash]
                return (i, 1, j, 2)
        return None

    for _ in range(q):
        a, l, r = map(int, sys.stdin.readline().split())
        row_bits[a].range_flip(l, r)
        # Update all_rows[a]
        prev_state = all_rows[a]
        new_state = get_row_state(a)
        all_rows[a] = new_state
        if prev_state == 0:
            count_all0 -= 1
        elif prev_state == 1:
            count_all1 -= 1
        if new_state == 0:
            count_all0 += 1
        elif new_state == 1:
            count_all1 += 1

        # Check current state
        cert = check_all_pairs()
        if cert:
            x1, y1, x2, y2 = cert
            if x1 > x2:
                x1, x2 = x2, x1
            if y1 > y2:
                y1, y2 = y2, y1
            print(x1, y1, x2, y2)
        else:
            print(-1)

