        # Compute left_dists
        last_1 = -float('inf')
        for i in range(n):
            if s[i] == '1':
                last_1 = i
                left_dists[i] = 0
            else:
                if last_1 != -float('inf'):
                    left_dists[i] = i - last_1

        # Compute right_dists
        last_1 = float('inf')
        for i in range(n-1, -1, -1):
            if s[i] == '1':
                last_1 = i
                right_dists[i] = 0
            else:
                if last_1 != float('inf'):
                    right_dists[i] = last_1 - i

        res = []
        for i in range(n):
            if s[i] == '1':
                res.append('1')
            else:
                left = left_dists[i]
                right = right_dists[i]
                min_step = min(left, right)
                if left != right and min_step <= m:
                    res.append('1')
                else:
                    res.append('0')
        print(''.join(res))

