import sys
from collections import deque, defaultdict

def kosaraju(n, adj):
    visited = [False] * (n + 1)
    order = []
    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited[v]:
                    stack.append((v, False))
    for u in range(1, n + 1):
        if not visited[u]:
            dfs(u)
    reverse_adj = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        for v in adj[u]:
            reverse_adj[v].append(u)
    visited = [False] * (n + 1)
    component = [0] * (n + 1)
    current = 0
    while order:
        u = order.pop()
        if not visited[u]:
            current += 1
            stack = [u]
            visited[u] = True
            current_component = [u]
            while stack:
                node = stack.pop()
                for v in reverse_adj[node]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
                        current_component.append(v)
            for node in current_component:
                component[node] = current
    return component, current

def main():
    n, m, s = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
    component, num_components = kosaraju(n, adj)
    condensed_adj = defaultdict(set)
    condensed_in_edges = defaultdict(set)
    for u in range(1, n + 1):
        for v in adj[u]:
            cu = component[u]
            cv = component[v]
            if cu != cv:
                if cv not in condensed_adj[cu]:
                    condensed_adj[cu].add(cv)
                    condensed_in_edges[cv].add(cu)
    c_s = component[s]
    reachable = set()
    queue = deque([c_s])
    reachable.add(c_s)
    while queue:
        u = queue.popleft()
        for v in condensed_adj.get(u, []):
            if v not in reachable:
                reachable.add(v)
                queue.append(v)
    S = set()
    for comp in range(1, num_components + 1):
        if comp not in reachable:
            S.add(comp)
    if not S:
        print(0)
        return
    count = 0
    for b in S:
        in_degree = 0
        for a in condensed_in_edges.get(b, []):
            if a in S:
                in_degree += 1
        if in_degree == 0:
            count += 1
    print(count)

