def kosaraju(n, adj, rev_adj):
    visited = [False] * (n + 1)
    order = []
    for u in range(1, n + 1):
        if not visited[u]:
            stack = [(u, False)]
            while stack:
                node, processed = stack.pop()
                if processed:
                    order.append(node)
                    continue
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, True))
                for v in adj[node]:
                    if not visited[v]:
                        stack.append((v, False))
    visited = [False] * (n + 1)
    component = [0] * (n + 1)
    current = 0
    for u in reversed(order):
        if not visited[u]:
            current += 1
