        while stack:
            v = stack.pop()
            for w in r_edges[v]:
                if w not in visited:
                    visited.add(w)
                    stack.append(w)
        visited.discard(u)
        mask = 0
        for node in visited:
            mask |= 1 << node
        predecessors[u] = mask

    # Compute DP
    max_mask = 1 << n
    dp = [0] * max_mask
    dp[0] = 1
    for mask in sorted(range(max_mask), key=lambda x: bin(x).count('1')):
        if mask == 0:
            continue
        available = []
        for u in range(n):
            if (mask & (1 << u)) and (mask & predecessors[u]) == 0:
                available.append(u)
        for u in available:
            prev_mask = mask ^ (1 << u)
            dp[mask] += dp[prev_mask]

    full_mask = (1 << n) - 1
    total = dp[full_mask]
    required = y - 2001 + 1
    if required > total or total == 0:
        print("The times have changed")
        return

    k = required - 1
    current_mask = full_mask
    perm = []
    for _ in range(n):
        available = []
        for u in range(n):
            if (current_mask & (1 << u)) and (current_mask & predecessors[u]) == 0:
                available.append(u)
        available.sort()
        found = False
        for u in available:
            cnt = dp[current_mask ^ (1 << u)]
            if k < cnt:
                perm.append(u + 1)
                current_mask ^= (1 << u)
                found = True
                break
            else:
                k -= cnt
        if not found:
            print("The times have changed")
            return
    print(' '.join(map(str, perm)))

