    main()

from collections import deque

def solve():
    lines = [input().strip() for _ in range(8)]
    statues = []
    for r in range(8):
        for c in range(8):
            if lines[r][c] == 'S':
                statues.append((r, c))
    target = (0, 7)
    visited = set()
    queue = deque([(7, 0, 0)])
    visited.add((7, 0, 0))
    directions = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    while queue:
        x, y, s = queue.popleft()
        if (x, y) == target:
            print("WIN")
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 8 and 0 <= ny < 8:
                # Check current statues at step s
                current_blocked = any(r + s == nx and c == ny and (r + s) < 8 for r, c in statues)
                if current_blocked:
                    continue
                # Check next statues at step s+1
                next_blocked = any(r + (s + 1) == nx and c == ny and (r + s + 1) < 8 for r, c in statues)
                if next_blocked:
                    continue
                # Check if reached target
                if (nx, ny) == target:
                    print("WIN")
                    return
                # Add to queue if not visited
                state = (nx, ny, s + 1)
                if state not in visited:
                    visited.add(state)
                    queue.append(state)
    print("LOSE")

