def main():
    import sys
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    fixed = []
    if k > 0:
        fixed = list(map(lambda x: x-1, list(map(int, sys.stdin.readline().split()))))

    # Check if fixed elements are strictly increasing
    for i in range(1, len(fixed)):
        if a[fixed[i]] <= a[fixed[i-1]]:
            print(-1)
            return

    # Check validity between consecutive fixed elements
    for i in range(1, len(fixed)):
        l = fixed[i-1]
        r = fixed[i]
        if a[r] - a[l] - 1 < (r - l - 1):
            print(-1)
            return

    segments = []
    if not fixed:
        segments.append((float('-inf'), float('inf'), 0, n-1))
    else:
        first = fixed[0]
        if first > 0:
            segments.append((float('-inf'), a[first], 0, first-1))
        for i in range(1, len(fixed)):
            l = fixed[i-1]
            r = fixed[i]
            segments.append((a[l], a[r], l+1, r-1))
        last = fixed[-1]
        if last < n-1:
            segments.append((a[last], float('inf'), last+1, n-1))

    total_operations = 0
    for left, right, start, end in segments:
        m = end - start + 1
        if m == 0:
            continue
        elements = a[start:end+1]
        filtered = []
        if left == float('-inf') and right == float('inf'):
            filtered = elements
        elif left == float('-inf'):
            filtered = [x for x in elements if x < right]
        elif right == float('inf'):
            filtered = [x for x in elements if x > left]
        else:
            filtered = [x for x in elements if left < x < right]

        lis = []
        for x in filtered:
            idx = bisect.bisect_left(lis, x)
            if idx == len(lis):
                lis.append(x)
            else:
                lis[idx] = x
        total_operations += (m - len(lis))

    print(total_operations)

