MOD = 10**9 + 7

def count_lucky_digits(m_str):
    n = len(m_str)
    m_digits = list(map(int, m_str))
    max_k = n
    dp = [[[[0] * 2 for _ in range(2)] for __ in range(max_k + 1)] for ___ in range(n + 1)]
    dp[0][0][1][0] = 1

    for pos in range(n):
        for cnt in range(max_k + 1):
            for tight in [0, 1]:
                for started in [0, 1]:
                    current = dp[pos][cnt][tight][started]
                    if current == 0:
                        continue
                    max_d = m_digits[pos] if tight else 9
                    for d in range(0, max_d + 1):
                        new_tight = 1 if (tight and d == max_d) else 0
                        new_started = started or (d != 0)
                        new_cnt = cnt
                        if new_started:
                            if d == 4 or d == 7:
                                new_cnt = cnt + 1
                                if new_cnt > max_k:
                                    continue
                        else:
                            new_cnt = 0
                        dp[pos + 1][new_cnt][new_tight][new_started] = (
                            dp[pos + 1][new_cnt][new_tight][new_started] + current
                        ) % MOD

    C = [0] * (max_k + 1)
    for cnt in range(max_k + 1):
        for tight in [0, 1]:
            for started in [0, 1]:
                if started:
                    C[cnt] = (C[cnt] + dp[n][cnt][tight][started]) % MOD
    return C

def main():
    m = input().strip()
    C = count_lucky_digits(m)
    max_k = len(m)
    max_possible_k = max_k
    fact = [1] * 7
    for i in range(1, 7):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * 7
    inv_fact[6] = pow(fact[6], MOD - 2, MOD)
    for i in range(5, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    ans = 0
    for s in range(max_possible_k + 1):
        if C[s] == 0:
            continue
        available = C.copy()
        available[s] -= 1
        if available[s] < 0:
            continue
        dp = [[0] * 55 for _ in range(7)]
        dp[0][0] = 1
        for k in range(max_possible_k + 1):
            a = available[k]
            if a == 0:
                continue
            for t in range(6, -1, -1):
                for sum_ in range(54, -1, -1):
                    if dp[t][sum_] == 0:
                        continue
                    max_c = min(a, 6 - t)
                    for c in range(1, max_c + 1):
                        new_t = t + c
                        new_sum = sum_ + c * k
                        if new_t > 6 or new_sum >= 55:
                            continue
                        numerator = 1
                        for i in range(c):
                            numerator = numerator * (a - i) % MOD
                        ways = numerator * inv_fact[c] % MOD
                        dp[new_t][new_sum] = (dp[new_t][new_sum] + dp[t][sum_] * ways) % MOD
        total = 0
        for sum_ in range(s):
            total = (total + dp[6][sum_]) % MOD
        ans = (ans + total * fact[6] % MOD * C[s] % MOD) % MOD
    print(ans)

