import sys

def ccw(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def segments_intersect_interior(A, B, C, D):
    ccw1 = ccw(A, B, C)
    ccw2 = ccw(A, B, D)
    ccw3 = ccw(C, D, A)
    ccw4 = ccw(C, D, B)
    if (ccw1 * ccw2 < 0 and ccw3 * ccw4 < 0):
        return True
    def on_segment(p, a, b):
        if ccw(a, b, p) != 0:
            return False
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))
    if on_segment(C, A, B) and (C != A and C != B):
        return True
    if on_segment(D, A, B) and (D != A and D != B):
        return True
    if on_segment(A, C, D) and (A != C and A != D):
        return True
    if on_segment(B, C, D) and (B != C and B != D):
        return True
    return False

def point_in_or_on_polygon(p, polygon):
    n = len(polygon)
    for i in range(n):
        a, b = polygon[i], polygon[(i+1)%n]
        if ccw(a, b, p) == 0:
            if (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1])):
                return True
    inside = False
    for i in range(n):
        a, b = polygon[i], polygon[(i+1)%n]
        if ((a[1] > p[1]) != (b[1] > p[1])):
            x_intersect = ( (p[1] - a[1]) * (b[0] - a[0]) ) / (b[1] - a[1]) if (b[1] != a[1]) else a[0]
            if p[0] < x_intersect:
                inside = not inside
    return inside

def is_valid(A, B, polygon):
    n = len(polygon)
    for i in range(n):
        a, b = polygon[i], polygon[(i+1)%n]
        if (A == a and B == b) or (B == a and A == b):
            return True
    midpoint = ( (A[0] + B[0])/2.0, (A[1] + B[1])/2.0 )
    if not point_in_or_on_polygon(midpoint, polygon):
        return False
    for i in range(n):
        C = polygon[i]
        D = polygon[(i+1)%n]
        if segments_intersect_interior(A, B, C, D):
            return False
    return True

def main():
