import sys
import itertools

INF = float('inf')

def main():
    while True:
        n, m, l, s, t = map(int, sys.stdin.readline().split())
        if n == 0 and m == 0 and l == 0 and s == 0 and t == 0:
            break

        # Initialize distance matrix
        dist = [[INF] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dist[i][i] = 0

        for _ in range(m):
            a, b, c = map(int, sys.stdin.readline().split())
            if dist[a][b] > c:
                dist[a][b] = c
                dist[b][a] = c

        # Floyd-Warshall to compute all pairs shortest paths
        for k in range(1, n + 1):
            for i in range(1, n + 1):
                if dist[i][k] == INF:
                    continue
                for j in range(1, n + 1):
                    if dist[k][j] == INF:
                        continue
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        # Read restaurants and filter unreachable ones
        restaurants = []
        for _ in range(l):
            j, e = map(int, sys.stdin.readline().split())
            if dist[s][j] != INF:
                restaurants.append((j, e))
        l_size = len(restaurants)
        if l_size == 0:
            print(0)
            continue

        # Initialize DP
        max_mask = 1 << l_size
        dp = [[INF] * l_size for _ in range(max_mask)]
        for i in range(l_size):
            j_i, e_i = restaurants[i]
            mask = 1 << i
            dp[mask][i] = dist[s][j_i] + e_i

        # Process masks in increasing order of set bits
        for k in range(1, l_size + 1):
            for bits in itertools.combinations(range(l_size), k):
                mask = sum(1 << b for b in bits)
                for i in bits:
                    current_time = dp[mask][i]
                    if current_time == INF:
                        continue
                    for j in range(l_size):
                        if (mask & (1 << j)) != 0:
                            continue
                        j_station, e_j = restaurants[j]
                        travel_time = dist[restaurants[i][0]][j_station]
                        if travel_time == INF:
                            continue
                        new_time = current_time + travel_time + e_j
                        new_mask = mask | (1 << j)
                        if new_time < dp[new_mask][j]:
                            dp[new_mask][j] = new_time

        # Check all masks for valid time
        max_count = 0
        for mask in range(1, max_mask):
            bits_count = bin(mask).count('1')
            if bits_count <= max_count:
                continue
            min_total = INF
            for i in range(l_size):
                if mask & (1 << i):
                    j_i = restaurants[i][0]
                    return_time = dist[j_i][s]
                    if return_time == INF:
                        continue
                    total = dp[mask][i] + return_time
                    if total < min_total:
                        min_total = total
            if min_total <= t and bits_count > max_count:
                max_count = bits_count

        print(max_count)

