import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n, m = map(int, stdin.readline().split())
    a = list(map(int, stdin.readline().split()))

    # Segment tree implementation
    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [[] for _ in range(2 * self.size)]
            for i in range(self.n):
                self.tree[self.size + i] = [data[i]]
            for i in range(self.size - 1, 0, -1):
                self.tree[i] = self.merge(self.tree[2*i], self.tree[2*i+1])

        def merge(self, left, right):
            res = []
            i = j = 0
            while i < len(left) and j < len(right) and len(res) < 20:
                if left[i] < right[j]:
                    res.append(left[i])
                    i += 1
                else:
                    res.append(right[j])
                    j += 1
            while i < len(left) and len(res) < 20:
                res.append(left[i])
                i += 1
            while j < len(right) and len(res) < 20:
                res.append(right[j])
                j += 1
            return res

        def update(self, pos, old_val, new_val):
            pos += self.size
            self.tree[pos] = [new_val]
            pos >>= 1
            while pos >= 1:
                self.tree[pos] = self.merge(self.tree[2*pos], self.tree[2*pos+1])
                pos >>= 1

        def query(self, l, r):
            res = []
            l += self.size
            r += self.size
            while l <= r:
                if l % 2 == 1:
                    res = self.merge(res, self.tree[l])
                    l += 1
                if r % 2 == 0:
                    res = self.merge(res, self.tree[r])
                    r -= 1
                l >>= 1
                r >>= 1
            return res

    st = SegmentTree(a)

    def is_unbalanced(subset):
        s = sum(subset)
        sum_str = str(s)
        len_sum = len(sum_str)
        digits_sum = list(sum_str)
        digits_elements = []
        for num in subset:
            num_str = str(num).zfill(len_sum)
            digits_elements.append(num_str)
        for pos in range(len_sum):
            target = digits_sum[pos]
            found = False
            for elem in digits_elements:
                if elem[pos] == target:
                    found = True
                    break
            if not found:
                return True
        return False

    for _ in range(m):
        parts = stdin.readline().split()
        if not parts:
            continue
        if parts[0] == '1':
            i = int(parts[1]) - 1
            x = int(parts[2])
            st.update(i, a[i], x)
            a[i] = x
        else:
            l = int(parts[1]) - 1
            r = int(parts[2]) - 1
            elements = st.query(l, r)
            min_sum = float('inf')

            # Check pairs
            for i in range(len(elements)):
                for j in range(i+1, len(elements)):
                    pair = [elements[i], elements[j]]
                    if is_unbalanced(pair):
                        s = sum(pair)
                        if s < min_sum:
                            min_sum = s

            # Check triplets
            for i in range(len(elements)):
                for j in range(i+1, len(elements)):
                    for k in range(j+1, len(elements)):
                        triplet = [elements[i], elements[j], elements[k]]
                        if is_unbalanced(triplet):
                            s = sum(triplet)
                            if s < min_sum:
                                min_sum = s

            if min_sum != float('inf'):
                print(min_sum)
            else:
                print(-1)

