def get_cells(i, j, orientation):
    cells = []
    if orientation == 0:  # stem down
        if j - 1 < 0 or j + 1 >= m or i + 2 >= n:
            return None
        cells = [(i, j-1), (i, j), (i, j+1), (i+1, j), (i+2, j)]
    elif orientation == 1:  # stem up
        if j - 1 < 0 or j + 1 >= m or i - 2 < 0:
            return None
        cells = [(i, j-1), (i, j), (i, j+1), (i-1, j), (i-2, j)]
    elif orientation == 2:  # stem right
        if i - 1 < 0 or i + 1 >= n or j + 2 >= m:
            return None
        cells = [(i-1, j), (i, j), (i+1, j), (i, j+1), (i, j+2)]
    elif orientation == 3:  # stem left
        if i - 1 < 0 or i + 1 >= n or j - 2 < 0:
            return None
        cells = [(i-1, j), (i, j), (i+1, j), (i, j-1), (i, j-2)]
    else:
        return None
    for x, y in cells:
        if x < 0 or x >= n or y < 0 or y >= m or current_grid[x][y] != '.':
            return None
    return cells

def backtrack(start_i, start_j, count):
