                        new_count = count + 1
                        if new_count > max_count:
                            max_count = new_count
                            best_grid = [row.copy() for row in current_grid]
                        remaining = n * m - new_count * 5
                        if new_count + (remaining // 5) > max_count:
                            if j + 1 < m:
                                ni, nj = i, j + 1
                            else:
                                ni, nj = i + 1, 0
                            backtrack(ni, nj, new_count)
                        for x, y in cells:
                            current_grid[x][y] = '.'
                if j + 1 < m:
                    ni, nj = i, j + 1
                else:
                    ni, nj = i + 1, 0
                backtrack(ni, nj, count)
                return
    if not found:
        if count > max_count:
            max_count = count
            best_grid = [row.copy() for row in current_grid]
        return

