def compute_closure(mask, prereq_masks):
    closure = mask
    while True:
        temp = 0
        current = closure
        i = 0
        while current:
            if current & 1:
                temp |= prereq_masks[i]
            current >>= 1
            i += 1
        new_closure = closure | temp
        if new_closure == closure:
            break
        closure = new_closure
    return closure

