        s_x, s_y = s
        t_x, t_y = t

        visited = {}
        queue = deque()
        queue.append((s_x, s_y, start_piece, 0, 0))
        visited_key = (s_x, s_y, start_piece)
        visited[visited_key] = (0, 0)
        result = {}

        while queue:
            x, y, piece, steps, reps = queue.popleft()

            if (x, y) == (t_x, t_y):
                if piece not in result or (steps < result[piece][0]) or (steps == result[piece][0] and reps < result[piece][1]):
                    result[piece] = (steps, reps)
                continue

            moves = []
            if piece == 'knight':
                deltas = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                          (1, 2), (1, -2), (-1, 2), (-1, -2)]
                for dx, dy in deltas:
                    nx = x + dx
                    ny = y + dy
                    if 0 <= nx < n_size and 0 <= ny < n_size:
                        moves.append((nx, ny))
            elif piece == 'bishop':
                directions = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
                for dx, dy in directions:
                    nx, ny = x, y
                    while True:
                        nx += dx
                        ny += dy
                        if 0 <= nx < n_size and 0 <= ny < n_size:
                            moves.append((nx, ny))
                        else:
                            break
            elif piece == 'rook':
                directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
                for dx, dy in directions:
                    nx, ny = x, y
                    while True:
                        nx += dx
                        ny += dy
                        if 0 <= nx < n_size and 0 <= ny < n_size:
                            moves.append((nx, ny))
                        else:
                            break

            for nx, ny in moves:
                new_piece = piece
                new_steps = steps + 1
                new_reps = reps
                key = (nx, ny, new_piece)
                if key not in visited or (new_steps < visited[key][0]) or (new_steps == visited[key][0] and new_reps < visited[key][1]):
                    visited[key] = (new_steps, new_reps)
                    queue.append((nx, ny, new_piece, new_steps, new_reps))

            for new_piece in ['knight', 'bishop', 'rook']:
                if new_piece == piece:
                    continue
                key = (x, y, new_piece)
                new_steps = steps + 1
                new_reps = reps + 1
                if key not in visited or (new_steps < visited[key][0]) or (new_steps == visited[key][0] and new_reps < visited[key][1]):
                    visited[key] = (new_steps, new_reps)
                    queue.append((x, y, new_piece, new_steps, new_reps))

        return result

    max_num = n * n
