    for current_num in range(1, max_num):
        next_num = current_num + 1
        for start_p in dp[current_num]:
            current_steps, current_reps = dp[current_num][start_p]
            transition = transitions.get((current_num, start_p), {})
            for end_p in transition:
                steps_needed, reps_needed = transition[end_p]
                total_steps = current_steps + steps_needed
                total_reps = current_reps + reps_needed
                if end_p not in dp[next_num] or total_steps < dp[next_num][end_p][0] or (total_steps == dp[next_num][end_p][0] and total_reps < dp[next_num][end_p][1]):
                    dp[next_num][end_p] = (total_steps, total_reps)

    min_steps = float('inf')
