    b = list(map(int, sys.stdin.readline().split()))

    # Convert to 0-based
    s_clock = [a[i] - b[i] for i in range(n)]
    s_counter = [a[i] - b[(i-1) % n] for i in range(n)]

    def process(s):
        prefix = [0] * (2 * n + 1)
        for i in range(2 * n):
            prefix[i+1] = prefix[i] + s[i % n]

        min_prefix = [0] * n
        dq = deque()

        for j in range(1, 2 * n + 1):
            while dq and dq[0] < (j - n):
                dq.popleft()
            while dq and prefix[j] <= prefix[dq[-1]]:
                dq.pop()
            dq.append(j)

            if j >= n:
                i = j - n
                min_prefix[i] = prefix[dq[0]]

        valid = [False] * n
        for i in range(n):
            if min_prefix[i] - prefix[i] >= 0:
                valid[i] = True
        return valid

    valid_clock = process(s_clock)
    valid_counter = process(s_counter)

    result = []
    for i in range(n):
        if valid_clock[i] or valid_counter[i]:
            result.append(i + 1)  # Convert to 1-based

    result.sort()
    print(len(result))
