    # Perform Gaussian elimination mod 2
    for i in range(n):
        # Find pivot row
        pivot = -1
        for j in range(i, n):
            if (M[j] >> i) & 1:
                pivot = j
                break
        # Swap with pivot row
        if pivot != i:
            M[i], M[pivot] = M[pivot], M[i]
            inv[i], inv[pivot] = inv[pivot], inv[i]
        # Eliminate all other rows
        for j in range(n):
            if j != i and (M[j] & (1 << i)):
                M[j] ^= M[i]
                inv[j] ^= inv[i]

    # Check each pair and output the result
    for a, b in pairs:
        # Check if inv[b][a] is 0 (0-based)
