def determine_winner(n):
    sequence = [n]
    current = n
    while current != 1:
        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1
        sequence.append(current)
    steps = len(sequence) - 1
    if steps == 0:
        steps = 1  # Handle case when n is 1 to avoid division by zero
    sum_even = sum(x for x in sequence if x % 2 == 0)
    sum_odd = sum(x for x in sequence if x % 2 != 0)
    even_rem = sum_even % steps
    odd_rem = sum_odd % steps
    if odd_rem > even_rem:
        return "Odd Rules"
    elif even_rem > odd_rem:
        return "Even Rules"
    else:
        return "Tie"

