def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        current_powers = [p**e for e in range(1, exp + 1)]
        temp = []
        for d in divisors:
            for power in current_powers:
                temp.append(d * power)
        divisors += temp
    return divisors

def main():
    N = int(input())
    if N == 1:
        print(0)
        return
    factors = factorize(N)
    divisors = get_divisors(factors)
    sum_ans = 0
    for q in divisors:
        if q == N:
            continue
        if q * (q + 1) < N:
            sum_ans += (N // q) - 1
    print(sum_ans)

