        v = a[i]
        adj[u].append(v)
        adj[v].append(u)

    degree = [0] * (n + 1)
    q = deque()
    for u in range(1, n + 1):
        degree[u] = len(adj[u])
        if degree[u] == 1:
            q.append(u)

    while q:
        u = q.popleft()
        for v in adj[u]:
            if degree[v] > 0:
                degree[v] -= 1
                if degree[v] == 1:
                    q.append(v)

    cycle = [u for u in range(1, n + 1) if degree[u] >= 2]
    m = len(cycle)
    if m == 0:
        cycle = [1]
        m = 1

    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    hash_subtree = {}
    stack = []
    cycle_nodes = set(cycle)

    def dfs(u):
        stack.append(u)
        visited[u] = True
        children = []
        for v in adj[u]:
            if not visited[v] and (v in cycle_nodes or degree[v] < 2):
                if v == parent[u]:
                    continue
                parent[v] = u
                dfs(v)
                children.append(hash_subtree[v])
        children.sort()
        h = 1
        for c in children:
            h = (h * (c + 12345)) % MOD
        hash_subtree[u] = h
        return h

    for u in cycle:
        if not visited[u]:
            dfs(u)

    cycle_order = []
    for u in cycle:
        cycle_order.append(u)
    cycle_order.sort()
    cycle = cycle_order
    cycle_hashes = []
    for u in cycle:
        children = []
        for v in adj[u]:
            if v in cycle_nodes or degree[v] < 2:
                if parent[v] == u:
                    children.append(hash_subtree[v])
        children.sort()
        h = 1
        for c in children:
            h = (h * (c + 123)) % MOD
        cycle_hashes.append(h)

    def minimal_period(arr):
        n = len(arr)
        for d in range(1, n + 1):
            if n % d != 0:
                continue
            valid = True
            for i in range(n):
                if arr[i] != arr[i % d]:
                    valid = False
                    break
            if valid:
                return d
        return n

    d = minimal_period(cycle_hashes)
    is_palin = True
    for i in range(m):
        if cycle_hashes[i] != cycle_hashes[m - 1 - i]:
            is_palin = False
            break

    group_size = m // d
    if is_palin:
        group_size *= 2

    sum_k = 0

    for rot in range(m // d):
        s = rot * d
        c_cycle = gcd(m, s)
        c = c_cycle
        sum_k = (sum_k + pow(k, c, MOD)) % MOD

    if is_palin:
        for ref in range(m // d):
            c = 0
            for i in range(m):
                j = (m - 1 - (i + ref * d)) % m
                if i < j:
                    if cycle_hashes[i] == cycle_hashes[j]:
                        c += 1
                    else:
                        c = -1
                        break
                elif i == j:
                    c += 1
            if c != -1:
                sum_k = (sum_k + pow(k, c, MOD)) % MOD

    inv_group = pow(group_size, MOD - 2, MOD)
    ans = (sum_k * inv_group) % MOD
    print(ans)

