def mcxi_to_num(s):
    value_map = {'m': 1000, 'c': 100, 'x': 10, 'i': 1}
    total = 0
    i = 0
    while i < len(s):
        if s[i] in '23456789':
            digit = int(s[i])
            char = s[i+1]
            total += digit * value_map[char]
            i += 2
        else:
            char = s[i]
            total += value_map[char]
            i += 1
    return total

def num_to_mcxi(n):
    res = []
    for val, char in [(1000, 'm'), (100, 'c'), (10, 'x'), (1, 'i')]:
        coeff = n // val
        if coeff == 0:
            continue
        if coeff == 1:
            res.append(char)
        else:
            res.append(f"{coeff}{char}")
        n -= coeff * val
    return ''.join(res)

