import math
from heapq import heappop, heappush

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __repr__(self):
        return f"({self.x}, {self.y})"

class Segment:
    def __init__(self, p1, p2):
        self.p1 = p1
        self.p2 = p2
        self.is_sign = False

    def length(self):
        return math.hypot(self.p2.x - self.p1.x, self.p2.y - self.p1.y)

    def __repr__(self):
        return f"{self.p1} -> {self.p2} (sign: {self.is_sign})"

def readints():
    return list(map(int, sys.stdin.readline().split()))

def parse_segments(n):
    segments = []
    for _ in range(n):
        x1, y1, x2, y2 = readints()
        p1 = Point(x1, y1)
        p2 = Point(x2, y2)
        segments.append(Segment(p1, p2))
    return segments

def classify_segments(segments):
    for seg in segments:
        seg.is_sign = False

    changed = True
    while changed:
        changed = False
        point_counts = {}
        for seg in segments:
            if seg.is_sign:
                continue
            for p in [seg.p1, seg.p2]:
                if p not in point_counts:
                    point_counts[p] = 0
                point_counts[p] += 1

        for seg in segments:
            if seg.is_sign:
                continue
            count_p1 = 0
            count_p2 = 0
            for other in segments:
                if other == seg or other.is_sign:
                    continue
                if seg.p1 == other.p1 or seg.p1 == other.p2:
                    count_p1 += 1
                if seg.p2 == other.p1 or seg.p2 == other.p2:
                    count_p2 += 1
            if (count_p1 == 1 and count_p2 == 0) or (count_p2 == 1 and count_p1 == 0):
                seg.is_sign = True
                changed = True

def build_graph(segments, start, goal):
    streets = [seg for seg in segments if not seg.is_sign]
    signs = [seg for seg in segments if seg.is_sign]

    adj = {}

    for street in streets:
        for p in [street.p1, street.p2]:
            if p not in adj:
                adj[p] = []

    for street in streets:
        p1, p2 = street.p1, street.p2
        for a, b in [(p1, p2), (p2, p1)]:
            allowed = True
            if allowed:
                if a not in adj:
                    adj[a] = []
                adj[a].append( (b, street.length()) )

    return adj

def dijkstra(graph, start, goal):
    heap = []
    heappush(heap, (0, start, [start]))
    visited = set()
    while heap:
        dist, current, path = heappop(heap)
        if current == goal:
            return path
        if current in visited:
            continue
        visited.add(current)
        for neighbor, weight in graph.get(current, []):
            if neighbor not in visited:
                heappush(heap, (dist + weight, neighbor, path + [neighbor]))
    return None

def solve():
    while True:
        n = int(sys.stdin.readline())
        if n == 0:
            break
        xs, ys = readints()
        xg, yg = readints()
        start = Point(xs, ys)
        goal = Point(xg, yg)
        segments = parse_segments(n)
        classify_segments(segments)
        graph = build_graph(segments, start, goal)
        path = dijkstra(graph, start, goal)
        if not path:
            print(-1)
        else:
            output = []
            for p in path:
                if p == start or p == goal:
                    output.append(p)
                    continue
                cnt = 0
                for seg in segments:
                    if not seg.is_sign and (p == seg.p1 or p == seg.p2):
                        cnt += 1
                if cnt >= 2:
                    output.append(p)
            if len(output) == 0 or output[-1] != goal:
                print(-1)
            else:
                for p in output:
                    print(p.x, p.y)
                print(0)

