def compute_cost(n, m, a, b, c, grid):
    desired_black = [[False]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            desired_black[i][j] = (grid[i][j] == '#')

    # Black phase
    painted = [[0]*m for _ in range(n)]
    cost = 0

    # Process horizontal lines for black phase
    for i in range(n):
        j = 0
        while j < m:
            if not desired_black[i][j]:
                j += 1
                continue
            start_j = j
            while j < m and desired_black[i][j]:
                j += 1
            length = j - start_j
            if length == 0:
                continue
            # Consider line from start_j to j-1
            line_black_pixels = length
            line_cost_line = a * length + b
            line_cost_single = c * line_black_pixels
            if line_cost_line < line_cost_single:
                # Check if any white pixels in this line
                can_paint = True
                for k in range(start_j, j):
                    if not desired_black[i][k] and painted[i][k] + 1 > 1:
                        can_paint = False
                        break
                if can_paint:
                    cost += line_cost_line
                    for k in range(start_j, j):
                        painted[i][k] += 1

    # Process vertical lines for black phase
    for j in range(m):
        i = 0
        while i < n:
            if not desired_black[i][j]:
                i += 1
                continue
            start_i = i
            while i < n and desired_black[i][j]:
                i += 1
            length = i - start_i
            if length == 0:
                continue
            line_black_pixels = length
            line_cost_line = a * length + b
            line_cost_single = c * line_black_pixels
            if line_cost_line < line_cost_single:
                can_paint = True
                for k in range(start_i, i):
                    if not desired_black[k][j] and painted[k][j] + 1 > 1:
                        can_paint = False
                        break
                if can_paint:
                    cost += line_cost_line
                    for k in range(start_i, i):
                        painted[k][j] += 1

    # Add single pixels for remaining black pixels not covered by lines
    for i in range(n):
        for j in range(m):
            if desired_black[i][j] and painted[i][j] == 0:
                cost += c
                painted[i][j] += 1

    # White phase: pixels that are white in desired and painted once in black phase
    white_target = []
    for i in range(n):
        for j in range(m):
            if not desired_black[i][j] and painted[i][j] == 1:
                white_target.append((i, j))

    # Now, process white phase
    white_painted = [[False]*m for _ in range(n)]
    white_cost = 0

    # Function to process lines for white phase
    def process_white_lines(lines, is_horizontal):
        for line in lines:
            i1, j1, i2, j2 = line
            line_pixels = []
            if is_horizontal:
                row = i1
                start = j1
                end = j2
                for j in range(start, end + 1):
                    if (row, j) in white_set and not white_painted[row][j]:
                        line_pixels.append((row, j))
            else:
                col = j1
                start = i1
                end = i2
                for i in range(start, end + 1):
                    if (i, col) in white_set and not white_painted[i][col]:
                        line_pixels.append((i, col))
            l = len(line_pixels)
            if l < 2:
                continue
            cost_line = a * l + b
            cost_single = c * l
            if cost_line < cost_single:
                white_cost += cost_line
                for (x, y) in line_pixels:
                    white_painted[x][y] = True

    white_set = set(white_target)
    # Horizontal lines in white phase
    white_lines = []
    for i in range(n):
        j = 0
        while j < m:
            if (i, j) not in white_set or white_painted[i][j]:
                j += 1
                continue
            start_j = j
            while j < m and (i, j) in white_set and not white_painted[i][j]:
                j += 1
            end_j = j - 1
            if end_j - start_j + 1 >= 2:
                white_lines.append((i, start_j, i, end_j))
    process_white_lines(white_lines, True)

    # Vertical lines in white phase
    white_lines_vert = []
    for j in range(m):
        i = 0
        while i < n:
            if (i, j) not in white_set or white_painted[i][j]:
                i += 1
                continue
            start_i = i
            while i < n and (i, j) in white_set and not white_painted[i][j]:
                i += 1
            end_i = i - 1
            if end_i - start_i + 1 >= 2:
                white_lines_vert.append((start_i, j, end_i, j))
    process_white_lines(white_lines_vert, False)

    # Add single pixels for remaining white pixels
    for (i, j) in white_target:
        if not white_painted[i][j]:
            white_cost += c

    return cost + white_cost

