def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return list(divisors)

def count_ways(x):
    if x == 0:
        return 0
    two_x = 2 * x
    divisors = set()
    for i in range(1, int(two_x**0.5) + 1):
        if two_x % i == 0:
            divisors.add(i)
            divisors.add(two_x // i)
    count = 0
    for k in divisors:
        term = (two_x // k) - k + 1
        if term <= 0:
            continue
        if term % 2 != 0:
            continue
        a = term // 2
        if a >= 1:
            count += 1
    return count

