import sys

def find_min_operations(t, test_cases):
    results = []
    for a, b in test_cases:
        d = abs(a - b)
        if d == 0:
            results.append(0)
            continue
        low = 1
        high = 2 * 10**9
        while low < high:
            mid = (low + high) // 2
            s = mid * (mid + 1) // 2
            if s >= d:
                high = mid
            else:
                low = mid + 1
        k0 = low
        sum_k0 = k0 * (k0 + 1) // 2
        if (sum_k0 - d) % 2 == 0:
            results.append(k0)
        else:
            if (k0 + 1) % 2 == 1:
                results.append(k0 + 1)
            else:
                results.append(k0 + 2)
    return results

