import math

t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Compute the overall GCD
    g = a[0]
    for num in a[1:]:
        g = math.gcd(g, num)

    # Check if all elements are already equal to g
    if all(x == g for x in a):
        print(0)
        continue

    # Transform the array by dividing each element by g
    b = [x // g for x in a]

    # Compute the maximum linear run of GCD > 1
    current_gcd = 0
    current_run = 0
    max_linear_run = 0
    for x in b:
        if current_gcd == 0:
            current_gcd = x
            current_run = 1
        else:
            current_gcd = math.gcd(current_gcd, x)
            if current_gcd > 1:
                current_run += 1
            else:
                current_gcd = 0
                current_run = 0
        if current_run > max_linear_run:
            max_linear_run = current_run

    # Compute prefix run
    prefix_gcd = 0
    prefix_len = 0
    for x in b:
        if prefix_gcd == 0:
            prefix_gcd = x
            prefix_len = 1
        else:
            new_gcd = math.gcd(prefix_gcd, x)
            if new_gcd > 1:
                prefix_gcd = new_gcd
                prefix_len += 1
            else:
                break

    # Compute suffix run
    suffix_gcd = 0
    suffix_len = 0
    for x in reversed(b):
        if suffix_gcd == 0:
            suffix_gcd = x
            suffix_len = 1
        else:
            new_gcd = math.gcd(suffix_gcd, x)
            if new_gcd > 1:
                suffix_gcd = new_gcd
                suffix_len += 1
            else:
                break

    # Check if combined run is possible
    max_run = max_linear_run
    if prefix_len > 0 and suffix_len > 0:
        combined_gcd = math.gcd(prefix_gcd, suffix_gcd)
        if combined_gcd > 1:
            max_run = max(max_run, prefix_len + suffix_len)

    # Calculate the result
    print(max_run)

