import sys
from collections import deque

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        board = []
        # Read 8 lines, skipping any empty lines
        while len(board) < 8:
            line = sys.stdin.readline().strip()
            if line:
                board.append(line)
        # Find positions of the two 'K's
        k_positions = []
        for i in range(8):
            for j in range(8):
                if board[i][j] == 'K':
                    k_positions.append((i, j))
        k1, k2 = k_positions
        # BFS setup
        visited = set()
        queue = deque()
        initial_state = (k1[0], k1[1], k2[0], k2[1])
        visited.add(initial_state)
        queue.append(initial_state)
        found = False
        directions = [(2, 2), (2, -2), (-2, 2), (-2, -2)]
        while queue:
            x1, y1, x2, y2 = queue.popleft()
            # Check if both are at the same position and the cell is not '#'
            if (x1, y1) == (x2, y2):
                if board[x1][y1] != '#':
                    found = True
                    break
                continue  # Meeting on bad square, continue searching
            # Generate all possible moves for both knights
            moves_k1 = []
            for dx, dy in directions:
                nx, ny = x1 + dx, y1 + dy
                if 0 <= nx < 8 and 0 <= ny < 8:
                    moves_k1.append((nx, ny))
            moves_k2 = []
            for dx, dy in directions:
                nx, ny = x2 + dx, y2 + dy
                if 0 <= nx < 8 and 0 <= ny < 8:
                    moves_k2.append((nx, ny))
            # Explore all combinations of moves
            for new_k1 in moves_k1:
                for new_k2 in moves_k2:
                    state = (new_k1[0], new_k1[1], new_k2[0], new_k2[1])
                    if state not in visited:
                        visited.add(state)
                        queue.append(state)
        print("YES" if found else "NO")

