def main():
    import sys
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()
    if n == 0 or k == 0:
        print('0' * n)
        return

    # Compute Z-array
    Z = [0] * n
    Z[0] = n
    l, r = 0, 0
    for i in range(1, n):
        if i > r:
            l = r = i
            while r < n and s[r - l] == s[r]:
                r += 1
            Z[i] = r - l
            r -= 1
        else:
            k = i - l
            if Z[k] < r - i + 1:
                Z[i] = Z[k]
            else:
                l = i
                while r < n and s[r - l] == s[r]:
                    r += 1
                Z[i] = r - l
                r -= 1

    # Precompute hashes
    MOD = 10**18 + 3
    BASE = 911382629
    prefix_hash = [0] * (n + 1)
    power = [1] * (n + 1)
    for i in range(n):
        prefix_hash[i+1] = (prefix_hash[i] * BASE + ord(s[i])) % MOD
        power[i+1] = (power[i] * BASE) % MOD

    def get_hash(l, r):
        if l > r:
            return 0
        res = (prefix_hash[r+1] - prefix_hash[l] * power[r - l + 1]) % MOD
        return res if res >= 0 else res + MOD

    res = [0] * n

    max_l = n // k
    for l in range(1, max_l + 1):
        kl = k * l
        if kl > n:
            continue
        max_a = min(l, n - kl)
        for a in range(0, max_a + 1):
            i = kl + a
            if i == 0 or i > n:
                continue
            if a > 0:
                hash_A = get_hash(0, a-1)
                hash_last_A = get_hash(kl, kl + a - 1)
                if hash_A != hash_last_A:
                    continue
            if Z[l] < l * (k - 1):
                continue
            res[i-1] = 1  # 1-based to 0-based index

    print(''.join(map(str, res)))

