import sys
sys.setrecursionlimit(1 << 25)

def main():
    n, m, MOD = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(n)]

    parent = {}
    rank = {}

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
            rank[v_root] += rank[u_root]
        else:
            parent[v_root] = u_root
            rank[u_root] += v_root
        return True

    edges = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                edges.append((i, j))

    from collections import defaultdict
    var_edges = defaultdict(list)
    for idx, (i, j) in enumerate(edges):
        var_edges[i, j] = idx

    free_vars = len(edges)

    cnt = [0]
    def backtrack(pos):
        if pos == free_vars:
            cnt[0] += 1
            return
        i, j = edges[pos]
        for mirror in ['/', '\\']:
            valid = True
            temp_parent = parent.copy()
            temp_rank = rank.copy()
            if mirror == '\\':
                left = ('L', i, j)
                top = ('T', i, j)
                right = ('R', i, j)
                bottom = ('B', i, j)
                lu = left
                lv = top
                ru = right
                rv = bottom
            else:
                left = ('L', i, j)
                bottom = ('B', i, j)
                right = ('R', i, j)
                top = ('T', i, j)
                lu = left
                lv = bottom
                ru = right
                rv = top

            for u, v in [(lu, lv), (ru, rv)]:
                if u not in parent:
                    parent[u] = u
                    rank[u] = 1
                if v not in parent:
                    parent[v] = v
                    rank[v] = 1
                if not union(u, v):
                    valid = False
                    break
            if valid:
                backtrack(pos + 1)
            parent = temp_parent
            rank = temp_rank

    backtrack(0)
    print(cnt[0] % MOD)

