import sys
from functools import lru_cache

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    @lru_cache(maxsize=None)
    def dfs(left, right, k, is_igor):
        if left > right:
            return 0
        available = right - left + 1
        if is_igor:
            max_val = -float('inf')
            for take in [k, k + 1]:
                if take > available:
                    continue
                new_left = left + take
                current_sum = prefix[new_left] - prefix[left]
                res = current_sum + dfs(new_left, right, take, False)
                if res > max_val:
                    max_val = res
            return max_val if max_val != -float('inf') else 0
        else:
            min_val = float('inf')
            for take in [k, k + 1]:
                if take > available:
                    continue
                new_right = right - take
                current_sum = prefix[right + 1] - prefix[new_right + 1]
                res = dfs(left, new_right, take, True) - current_sum
                if res < min_val:
                    min_val = res
            return min_val if min_val != float('inf') else 0

    max_diff = -float('inf')
    # Initial move by Igor: take 1 or 2
    for take in [1, 2]:
        if take > n:
            continue
        new_left = take
        current_sum = prefix[new_left] - prefix[0]
        res = current_sum + dfs(new_left, n - 1, take, False)
        if res > max_diff:
            max_diff = res
    print(max_diff)

