import sys
from collections import defaultdict

def sieve():
    sieve = []
    max_num = 100000
    is_prime = [True] * (max_num + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_num**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, max_num+1, i):
                is_prime[j] = False
    for i in range(2, max_num+1):
        if is_prime[i]:
            sieve.append(i)
    return sieve

primes = sieve()

def factorize(n):
    factors = defaultdict(int)
    for p in primes:
        if p*p > n:
            break
        while n % p == 0:
            factors[p] += 1
            n //= p
    if n > 1:
        factors[n] += 1
    return factors

