import sys

def find_level(v, N):
    if N == 1:
        return (v, v, 0, 0)
    sum_so_far = 0
    term = 1
    current_level = 1
    current_S = 1
    while True:
        next_sum = sum_so_far + term
        next_S = next_sum + 1
        if next_S > v:
            break
        sum_so_far = next_sum
        term *= N
        current_level += 1
        current_S = next_S
    return (current_level, current_S, sum_so_far, term)

def get_parent(v, N):
    if N == 1:
        return v - 1 if v > 1 else None
    k, s_k, sum_so_far, term = find_level(v, N)
    if k == 1:
        return None
    term_prev = term // N
    s_km1 = s_k - term_prev
    pos_in_level = v - s_k
    parent = s_km1 + (pos_in_level // N)
    return parent

def lca(v, w, N):
    if N == 1:
        return v
    while True:
        kv, _, _, _ = find_level(v, N)
        kw, _, _, _ = find_level(w, N)
        if kv == kw:
            break
        if kv > kw:
            v = get_parent(v, N)
        else:
            w = get_parent(w, N)
    while v != w:
        v = get_parent(v, N)
        w = get_parent(w, N)
    return v

