import sys

def rotate_90(mat):
    m = len(mat)
    return [[mat[m - j - 1][i] for j in range(m)] for i in range(m)]

def rotate_180(mat):
    m = len(mat)
    return [[mat[m - i - 1][m - j - 1] for j in range(m)] for i in range(m)]

def rotate_270(mat):
    m = len(mat)
    return [[mat[j][m - i - 1] for j in range(m)] for i in range(m)]

