def main():
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    while True:
        h, w = map(int, input().split())
        if h == 0 and w == 0:
            break
        grid = []
        golds = []
        entrance = None
        for i in range(h):
            line = input().strip()
            grid.append(line)
            for j, c in enumerate(line):
                if c == '%':
                    entrance = (i, j)
                elif c == '*':
                    golds.append((i, j))
        gold_indices = { pos:i for i, pos in enumerate(golds) }
        total_golds = len(golds)
        heap = []
        visited = {}
        # (cost, -gold_count, x, y, dir, mode, steps_in_dir, gold_mask)
        heapq.heappush(heap, (0, 0, entrance[0], entrance[1], None, 'normal', 0, 0))
        max_gold = 0
        min_cost = 0
        found = False
        while heap:
            cost, neg_gold, x, y, last_dir, mode, steps, gold_mask = heapq.heappop(heap)
            gold_count = -neg_gold
            if (x, y) == entrance:
                if gold_count > max_gold or (gold_count == max_gold and cost < min_cost):
                    max_gold = gold_count
                    min_cost = cost
                    found = True
            key = (x, y, last_dir, mode, steps, gold_mask)
            if key in visited:
                if visited[key] <= cost:
                    continue
            visited[key] = cost
            for dx, dy in directions:
                new_x, new_y = x + dx, y + dy
                if new_x < 0 or new_x >= h or new_y < 0 or new_y >= w:
                    continue
                if grid[new_x][new_y] == '#':
                    continue
                new_mode = mode
                new_steps = steps
                new_gold_mask = gold_mask
                new_dir = (dx, dy)
                current_cost = cost + 1
                collected = False
                if (new_x, new_y) in gold_indices and not (new_gold_mask & (1 << gold_indices[(new_x, new_y)])):
                    new_gold_mask = gold_mask | (1 << gold_indices[(new_x, new_y)])
                    new_gold_count = gold_count + 1
                    collected = True
                else:
                    new_gold_count = gold_count
                if collected or (new_dir != last_dir and last_dir is not None):
                    new_mode = 'normal'
                    new_steps = 0
                else:
                    new_steps += 1
                    if new_steps >= 2:
                        new_mode = 'dash'
                    else:
                        new_mode = 'normal'
                if grid[new_x][new_y] == '^':
                    continue
                key_new = (new_x, new_y, new_dir, new_mode, new_steps, new_gold_mask)
                if key_new not in visited or visited.get(key_new, float('inf')) > current_cost:
                    heapq.heappush(heap, (current_cost, -new_gold_count, new_x, new_y, new_dir, new_mode, new_steps, new_gold_mask))
                if mode == 'dash':
                    for dash_steps in [2,3,4]:
                        wx, wy = x + dx*dash_steps, y + dy*dash_steps
