from collections import defaultdict, deque

def main():
    n, *rest = map(int, sys.stdin.read().split())
    a = rest[:n]

    freq = defaultdict(int)
    for num in a:
        freq[num] += 1

    valid_partners = defaultdict(int)
    reverse_partners = defaultdict(list)

    for x in freq:
        partners = set()
        for d in range(32):
            s = 1 << d
            y = s - x
            if y not in freq:
                continue
            if y == x:
                if freq[x] >= 2:
                    partners.add(y)
            else:
                if freq[y] >= 1:
                    partners.add(y)
        for y in partners:
            valid_partners[x] += 1
            reverse_partners[y].append(x)

    queue = deque()
    total_removed = 0

    for x in freq:
        if valid_partners[x] == 0 and freq[x] > 0:
            queue.append(x)

    while queue:
        x = queue.popleft()
        if freq[x] == 0:
            continue
        total_removed += freq[x]
        for y in reverse_partners[x]:
            valid_partners[y] -= 1
            if valid_partners[y] == 0 and freq[y] > 0:
                queue.append(y)
        freq[x] = 0

    print(total_removed)

