import itertools

def convex_hull(points):
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def point_in_polygon(p, polygon):
    x, y = p
    n = len(polygon)
    inside = False
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        if ((y1 > y) != (y2 > y)):
            xinters = (y - y1) * (x2 - x1) / (y2 - y1) + x1
            if x <= xinters:
                inside = not inside
    return inside

def compute_circumcircle(a, b, c):
    ax, ay = a
    bx, by = b
    cx, cy = c

    d = 2 * ((bx - ax) * (cy - ay) - (by - ay) * (cx - ax))
    if d == 0:
        return None

    part1 = (bx**2 + by**2) - (ax**2 + ay**2)
    part2 = (cx**2 + cy**2) - (ax**2 + ay**2)
    x = ((cy - ay) * part1 - (by - ay) * part2) / d
    y = ((bx - ax) * part2 - (cx - ax) * part1) / d

    radius = ((x - ax)**2 + (y - ay)**2)**0.5
    return ((x, y), radius)

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    idx += 1
    points = []
    for _ in range(n):
        x = int(input[idx])
        y = int(input[idx + 1])
        points.append((x, y))
        idx += 2

    if n < 3:
        print(-1)
        return

    hull = convex_hull(points)
    candidates = []

    for triplet in itertools.combinations(points, 3):
        a, b, c = triplet
        ax, ay = a
        bx, by = b
        cx, cy = c
        area_twice = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
        if area_twice == 0:
            continue

        res = compute_circumcircle(a, b, c)
        if not res:
            continue
        center, radius = res

        if point_in_polygon(center, hull):
            candidates.append(radius)

    if not candidates:
        print(-1)
    else:
