def sum_digits(s):
    return sum(int(c) for c in s)

def add_one(s):
    digits = list(s)
    carry = 1
    for i in range(len(digits)-1, -1, -1):
        d = int(digits[i]) + carry
        if d == 10:
            digits[i] = '0'
            carry = 1
        else:
            digits[i] = str(d)
            carry = 0
        if carry == 0:
            break
    if carry == 1:
        digits = ['1'] + digits
    return ''.join(digits)

def distribute(s, delta):
    digits = list(map(int, list(s)))
    for i in range(len(digits)-1, -1, -1):
        if delta <= 0:
            break
        max_add = 9 - digits[i]
        if max_add <= 0:
            continue
        add = min(max_add, delta)
        digits[i] += add
        delta -= add
    if delta > 0:
        new_digits = list(map(int, str(delta))) + [0] * len(digits)
        new_str = ''.join(map(str, new_digits)).lstrip('0')
        if not new_str:
            return '0'
        return new_str
    new_str = ''.join(map(str, digits)).lstrip('0')
    return new_str if new_str else '0'

