import sys
from collections import deque

def get_direction(b, swapLR, swapUD):
    if b == 'L':
        return (0, -1) if swapLR == 0 else (0, 1)
    elif b == 'R':
        return (0, 1) if swapLR == 0 else (0, -1)
    elif b == 'U':
        return (-1, 0) if swapUD == 0 else (1, 0)
    elif b == 'D':
        return (1, 0) if swapUD == 0 else (-1, 0)
    else:
        return (0, 0)

def find_path_after_swap(grid, n, m, swapLR, swapUD, start_x, start_y):
    start = (start_x-1, start_y-1)
    finish = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                finish = (i, j)
    if not finish:
        return []
    visited = set()
    queue = deque([(start[0], start[1], [])])
    visited.add((start[0], start[1]))

    while queue:
        x, y, path = queue.popleft()
        if (x, y) == finish:
            return path
        for b in ['L', 'R', 'U', 'D']:
            dx, dy = get_direction(b, swapLR, swapUD)
            nx = x + dx
            ny = y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                if grid[nx][ny] in ('.', 'F'):
                    visited.add((nx, ny))
                    queue.append((nx, ny, path + [b]))
    return []

