import sys
from collections import Counter

def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors, reverse=True)

def main():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    counts = Counter(s)
    total_odds = sum(1 for cnt in counts.values() if cnt % 2 != 0)

    divisors = get_divisors(n)

    k_found = None
    m_found = None
    for k in divisors:
        m = n // k
        if m % 2 == 0:
            if all(cnt % 2 == 0 for cnt in counts.values()):
                k_found = k
                m_found = m
                break
        else:
            if total_odds == k:
                k_found = k
                m_found = m
                break

    palindromes = []
    if m_found % 2 == 0:
        pairs = []
        for c in sorted(counts.keys()):
            pairs.extend([c] * (counts[c] // 2))
        group_size = m_found // 2
        groups = [pairs[i*group_size : (i+1)*group_size] for i in range(k_found)]
        for g in groups:
            left = ''.join(g)
            palindromes.append(left + left[::-1])
    else:
        middle_chars = []
        for c in counts:
            if counts[c] % 2 != 0:
                middle_chars.append(c)
        for c in middle_chars:
            counts[c] -= 1
        pairs = []
        for c in counts:
            pairs.extend([c] * (counts[c] // 2))
        group_size = (m_found - 1) // 2
        groups = [pairs[i*group_size : (i+1)*group_size] for i in range(k_found)]
        for i in range(k_found):
            left = ''.join(groups[i])
            mid = middle_chars[i]
            palindromes.append(left + mid + left[::-1])

    print(k_found)
    print(' '.join(palindromes))

