import sys
import math
from functools import lru_cache

def compute_overall_gcd(cards):
    from math import gcd
    current_gcd = cards[0]
    for num in cards[1:]:
        current_gcd = math.gcd(current_gcd, num)
    return current_gcd

def solve_optimal(cards):
    n = len(cards)
    overall_gcd = compute_overall_gcd(cards)
    if overall_gcd != 1:
        return 1 if n % 2 == 1 else 0
    else:
        for i in range(n):
            new_cards = cards[:i] + cards[i+1:]
            if len(new_cards) == 0:
                continue
            current_gcd = new_cards[0]
            for num in new_cards[1:]:
                current_gcd = math.gcd(current_gcd, num)
            if current_gcd == 1:
                return 1
        return 0

