        count = 0
        for i in range(n):
            if (remaining_mask >> i) & 1:
                remaining.append(cards[i])
                count += 1
        if g == 1:
            return 0.0
        if count == 0:
            return 0.0
        prob = 0.0
        for i in range(n):
            if (remaining_mask >> i) & 1:
                new_g = math.gcd(g, cards[i])
                new_mask = remaining_mask & ~(1 << i)
                if new_g == 1:
                    res = 0.0
                else:
                    res = 1.0 - dp(new_g, new_mask)
                prob += res
        prob /= count
        return prob

    initial_g = 0
    initial_mask = (1 << n) - 1
    return dp(initial_g, initial_mask)

