    for i in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))
        adj[u].append((v, i))
        adj[v].append((u, i))

    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    time = 0
    bridges = set()
    parent = [-1] * (n + 1)

    for u in range(1, n+1):
        if disc[u] == -1:
            stack = [(u, -1, False)]
            while stack:
                node, parent_node, visited = stack.pop()
                if visited:
                    for child, edge_idx in adj[node]:
                        if child != parent_node:
                            if disc[child] > disc[node]:
                                low[node] = min(low[node], low[child])
                                if low[child] > disc[node]:
                                    bridges.add(edge_idx)
                    continue
                if disc[node] != -1:
                    continue
                disc[node] = time
                low[node] = time
                time += 1
                stack.append((node, parent_node, True))
                for child, edge_idx in reversed(adj[node]):
                    if child == parent_node:
                        continue
                    if disc[child] == -1:
                        parent[child] = node
                        stack.append((child, node, False))
                    else:
                        low[node] = min(low[node], disc[child])

    component = [0] * (n + 1)
    current_component = 0
    visited = [False] * (n + 1)
    for u in range(1, n+1):
        if not visited[u]:
            current_component += 1
            q = deque([u])
            visited[u] = True
            component[u] = current_component
            while q:
                v = q.popleft()
                for w, edge_idx in adj[v]:
                    if edge_idx in bridges:
                        continue
                    if not visited[w]:
                        visited[w] = True
                        component[w] = current_component
                        q.append(w)

    if current_component == 1:
        print(0)
        return

    bridge_tree_adj = [[] for _ in range(current_component + 1)]
    for i in bridges:
        u, v = edges[i]
        cu, cv = component[u], component[v]
        if cu != cv:
            bridge_tree_adj[cu].append(cv)
            bridge_tree_adj[cv].append(cu)

    def bfs(start, adj_):
        max_dist, far_node = 0, start
        visited = [-1] * (len(adj_))
        q = deque([start])
        visited[start] = 0
        while q:
            u = q.popleft()
            for v in adj_[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    if visited[v] > max_dist:
                        max_dist, far_node = visited[v], v
                    q.append(v)
        return far_node, max_dist

    u, _ = bfs(1, bridge_tree_adj)
    _, diameter = bfs(u, bridge_tree_adj)
    print(diameter)

