def main():
    import sys
    from collections import deque

    n, m = map(int, sys.stdin.readline().split())
    if m == 0:
        print(0)
        return

    rows = []
    cols = []
    rects = []
    for _ in range(m):
        x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
        rects.append((x1, y1, x2, y2))
        rows.append((y1, y2))
        cols.append((x1, x2))

    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_intervals = sorted(intervals)
        merged = [sorted_intervals[0]]
        for current in sorted_intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1] + 1:
                merged[-1] = (last[0], max(last[1], current[1]))
            else:
                merged.append(current)
        return merged

    merged_rows = merge_intervals(rows)
    merged_cols = merge_intervals(cols)

    row_nodes = []
    for a, b in merged_rows:
        row_nodes.extend(range(a, b + 1))

    col_nodes = []
    for a, b in merged_cols:
        col_nodes.extend(range(a, b + 1))

    graph = {}
    for r in row_nodes:
        graph[('row', r)] = []
    for c in col_nodes:
        graph[('col', c)] = []

    for x1, y1, x2, y2 in rects:
        for y in range(y1, y2 + 1):
            if ('row', y) not in graph:
                continue
            for x in range(x1, x2 + 1):
                if ('col', x) not in graph:
                    continue
                graph[('row', y)].append(('col', x))
                graph[('col', x)].append(('row', y))

    def hopcroft_karp():
        pair_u = {}
        pair_v = {}
        dist = {}
        for u in graph:
            if u[0] == 'row':
                pair_u[u] = None
            else:
                pair_v[u] = None

        def bfs():
            queue = deque()
            for u in pair_u:
                if pair_u[u] is None:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist[None] = float('inf')
            while queue:
                u = queue.popleft()
                if dist[u] < dist[None]:
                    for v in graph[u]:
                        if dist.get(pair_v.get(v, None), float('inf')) == float('inf'):
                            dist[pair_v.get(v, None)] = dist[u] + 1
                            queue.append(pair_v.get(v, None))
            return dist[None] != float('inf')

        def dfs(u):
            if u is not None:
                for v in graph[u]:
                    if dist.get(pair_v.get(v, None), float('inf')) == dist[u] + 1:
                        if dfs(pair_v.get(v, None)):
                            pair_u[u] = v
                            pair_v[v] = u
                            return True
                dist[u] = float('inf')
                return False
            return True

        result = 0
        while bfs():
            for u in pair_u:
                if pair_u[u] is None:
                    if dfs(u):
                        result += 1
        return result

    max_matching = hopcroft_karp()
    print(max_matching)

