def precompute(max_n):
    spf = [0] * (max_n + 1)
    for i in range(2, max_n + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * i, max_n + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    y = [0] * (max_n + 1)
    for i in range(1, max_n + 1):
        for j in range(2 * i, max_n + 1, i):
            y[j] += i

    f = [0] * (max_n + 1)
    for n in range(2, max_n + 1):
