def factor(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def find_min_k(N):
    D = 2 * N
    if D == 0:
        return 0  # Not possible per problem constraints
    factors = factor(D)
    primes = list(factors.keys())
    m = len(primes)
    min_k = float('inf')

    for mask in range(1 << m):
        d = 1
        for i in range(m):
            if mask & (1 << i):
                p = primes[i]
                d *= p ** factors[p]
        e = D // d

        # Case 1: k ≡ 0 mod d, k ≡ -1 mod e
        if e == 1:
            k1 = d
        else:
            inv_d = pow(d, -1, e)
            x = (-inv_d) % e
            k1 = d * x

        # Case 2: k ≡ -1 mod d, k ≡ 0 mod e
        if d == 1:
            k2 = e
        elif e == 1:
            k2 = d - 1
        else:
            inv_e = pow(e, -1, d)
            t = (-inv_e) % d
            k2 = e * t

        if k1 > 0 and k1 < min_k:
            min_k = k1
        if k2 > 0 and k2 < min_k:
            min_k = k2

    return min_k

