from collections import deque

def main():
    n = int(stdin.readline())
    edges_input = []
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, stdin.readline().split())
        edges_input.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    root = 1
    parent[root] = -1
    queue = deque([root])
    depth[root] = 0

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if parent[v] == 0:
                parent[v] = u
                depth[v] = depth[u] + 1
                queue.append(v)

    LOG = 20
    up = [[-1] * (n + 1) for _ in range(LOG)]
    for i in range(1, n+1):
        up[0][i] = parent[i] if parent[i] != -1 else -1

    for k in range(1, LOG):
        for i in range(1, n+1):
            if up[k-1][i] != -1:
                up[k][i] = up[k-1][up[k-1][i]]
            else:
                up[k][i] = -1

    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        for k in range(LOG-1, -1, -1):
            if depth[a] - (1 << k) >= depth[b]:
                a = up[k][a]
        if a == b:
            return a
        for k in range(LOG-1, -1, -1):
            if up[k][a] != up[k][b]:
                a = up[k][a]
                b = up[k][b]
        return up[0][a]

    k = int(stdin.readline())
    count = [0] * (n + 1)
    for _ in range(k):
        a, b = map(int, stdin.readline().split())
        L = lca(a, b)
        count[a] += 1
        count[b] += 1
        count[L] -= 2

    children = [[] for _ in range(n+1)]
    for v in range(1, n+1):
        if parent[v] != -1:
            children[parent[v]].append(v)

    nodes = sorted(range(1, n+1), key=lambda x: -depth[x])
    for u in nodes:
        for v in children[u]:
            count[u] += count[v]

    edge_children = []
    for u, v in edges_input:
        if parent[v] == u:
            edge_children.append(v)
        else:
            edge_children.append(u)

    print(' '.join(map(str, [count[c] for c in edge_children])))

