from collections import deque

def compute_diameter(adj):
    def bfs(start):
        visited = [-1] * (len(adj) + 1)
        q = deque([start])
        visited[start] = 0
        max_dist = 0
        far_node = start
        while q:
            u = q.popleft()
            for v in adj[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    q.append(v)
                    if visited[v] > max_dist:
                        max_dist = visited[v]
                        far_node = v
        return far_node, max_dist

    u, _ = bfs(1)
    v, diameter = bfs(u)
    return diameter

