import itertools

def solve():
    t = int(input())
    for _ in range(t):
        points = [tuple(map(int, input().split())) for _ in range(4)]
        best_max = float('inf')
        best_targets = None

        for perm in itertools.permutations(points):
            p0, p1, p2, p3 = perm
            # Check square conditions
            if p0[0] != p2[0] or p1[0] != p3[0]:
                continue
            if p0[1] != p1[1] or p2[1] != p3[1]:
                continue
            s_x = p1[0] - p0[0]
            s_y = p2[1] - p0[1]
            if s_x != s_y or s_x <= 0:
                continue

            # Check each point's validity and compute distances
            valid = True
            current_max = 0
            targets = [p0, p1, p2, p3]
            for op in points:
                try:
                    idx = perm.index(op)
                except ValueError:
                    valid = False
                    break
                tx, ty = targets[idx]
                ox, oy = op
                if tx != ox and ty != oy:
                    valid = False
                    break
                distance = abs(tx - ox) + abs(ty - oy)
                current_max = max(current_max, distance)

            if valid and current_max < best_max:
                best_max = current_max
                # Prepare output in input order
                current_targets = []
                for op in points:
                    idx = perm.index(op)
                    current_targets.append(targets[idx])
                best_targets = current_targets

        if best_max != float('inf'):
            print(best_max)
            for x, y in best_targets:
                print(x, y)
        else:
            print(-1)

