import heapq

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx])
    m = int(data[idx+1])
    s = int(data[idx+2]) - 1  # 0-based
    idx +=3

    edges = [[] for _ in range(n)]
    for _ in range(m):
        u = int(data[idx])-1
        v = int(data[idx+1])-1
        w = int(data[idx+2])
        edges[u].append( (v, w) )
        edges[v].append( (u, w) )
        idx +=3

    # Dijkstra's algorithm
    d_initial = [float('inf')] * n
    d_initial[s] = 0
    heap = [ (0, s) ]
    visited = [False] * n

    while heap:
        dist, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        for v, w in edges[u]:
            if not visited[v] and d_initial[v] > dist + w:
                d_initial[v] = dist + w
                heapq.heappush(heap, (d_initial[v], v))

    # Build DAG
    dag = [[] for _ in range(n)]
    for u in range(n):
        for v, w in edges[u]:
            if d_initial[u] != float('inf') and d_initial[u] + w == d_initial[v]:
                dag[v].append(u)

    # Topological order (sorted by distance, then node index)
    top_order = sorted( (d_initial[u], u) for u in range(n) if d_initial[u] != float('inf') )
    top_order = [u for (d, u) in top_order]

    LOG = 20
    up = [ [ -1 ] * LOG for _ in range(n) ]
    parent = [ -1 ] * n
    depth = [0] * n
    idom = [ -1 ] * n

    def lca(a, b):
        if a == -1 or b == -1:
            return -1
        if depth[a] < depth[b]:
            a, b = b, a
        # Bring a up to depth of b
        for i in range(LOG-1, -1, -1):
            if depth[a] - (1 << i) >= depth[b]:
                a = up[a][i]
        if a == b:
            return a
        for i in range(LOG-1, -1, -1):
            if up[a][i] != -1 and up[a][i] != up[b][i]:
                a = up[a][i]
                b = up[b][i]
        return up[a][0]

    for v in top_order:
        if v == s:
            idom[v] = s
            parent[v] = s
            depth[v] = 0
            for i in range(LOG):
                up[v][i] = s if i ==0 else up[up[v][i-1]][i-1] if up[v][i-1] != -1 else -1
            continue
        preds = dag[v]
        if not preds:
            continue
        idom_list = []
        for u in preds:
            if idom[u] != -1:
                idom_list.append(idom[u])
        if not idom_list:
            continue
        current_lca = idom_list[0]
        for x in idom_list[1:]:
            current_lca = lca(current_lca, x)
        idom[v] = current_lca
        if idom[v] == -1:
            continue
        parent[v] = idom[v]
        depth[v] = depth[idom[v]] + 1
        up[v][0] = idom[v]
        for i in range(1, LOG):
            if up[v][i-1] == -1:
                up[v][i] = -1
            else:
                up[v][i] = up[ up[v][i-1] ][i-1]

    # Compute subtree sizes
    subtree_size = [1] * n
    for v in reversed(top_order):
        if v == s:
            continue
        if parent[v] != -1:
            subtree_size[parent[v]] += subtree_size[v]

    max_sub = 0
    for u in range(n):
        if u == s:
            continue
        if subtree_size[u] > max_sub:
            max_sub = subtree_size[u]
    print(max_sub)

