import sys
from itertools import product

def parse_mask(mask_str):
    return [i for i, c in enumerate(mask_str) if c == 'x']

def compute_gate(gate_type, var_values):
    a, b = var_values
    if gate_type == 'and':
        res = a & b
    elif gate_type == 'or':
        res = a | b
    elif gate_type == 'nand':
        res = not (a & b)
    elif gate_type == 'nor':
        res = not (a | b)
    else:
        assert False
    return 1 if res else 0

def is_constant_second_layer(gate1, gate2, second_type, first_gates):
    g1_type, g1_inputs = first_gates[gate1]
    g2_type, g2_inputs = first_gates[gate2]
    combined_vars = sorted(list(set(g1_inputs + g2_inputs)))
    seen = set()
    for assignment in product([0, 1], repeat=len(combined_vars)):
        # Get values for gate1
        x1 = combined_vars.index(g1_inputs[0])
        x2 = combined_vars.index(g1_inputs[1])
        a = compute_gate(g1_type, [assignment[x1], assignment[x2]])
        # Get values for gate2
        x1_g2 = combined_vars.index(g2_inputs[0])
        x2_g2 = combined_vars.index(g2_inputs[1])
        b = compute_gate(g2_type, [assignment[x1_g2], assignment[x2_g2]])
        seen.add((a, b))
    # Check outputs for second layer gate
    outputs = []
    for a, b in seen:
        if second_type == 'and':
            res = a & b
        elif second_type == 'or':
            res = a | b
        elif second_type == 'nand':
            res = not (a & b)
        elif second_type == 'nor':
            res = not (a | b)
        outputs.append(1 if res else 0)
    if all(x == outputs[0] for x in outputs):
        return (True, outputs[0])
    else:
        return (False, None)

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    first_layer = []
    for _ in range(m):
        parts = sys.stdin.readline().split()
        for i in range(0, len(parts), 2):
            gate_type = parts[i]
            mask = parts[i+1]
            inputs = parse_mask(mask)
            first_layer.append((gate_type, inputs))
    second_layer = []
    for _ in range(k):
        parts = sys.stdin.readline().split()
        for i in range(0, len(parts), 2):
            gate_type = parts[i]
            mask = parts[i+1]
            inputs = parse_mask(mask)
            second_layer.append((gate_type, inputs))
    # Process second layer gates
    const_0 = 0
    const_1 = 0
    for s_gate in second_layer:
        s_type, s_mask = s_gate
        g1, g2 = s_mask
        is_const, val = is_constant_second_layer(g1, g2, s_type, first_layer)
        if is_const:
            if val == 0:
                const_0 += 1
            else:
                const_1 += 1
    max_count = max(const_0, const_1)
    if max_count == 0:
        print(-1)
    else:
        print(k - max_count)

