        nx = x + dx
        ny = y + dy
        if nx < 0 or nx >= m or ny < 0 or ny >= n:
            break
        cell = maze[nx][ny]
        if cell == '#':
            break
        if cell in ['<', '>', '^', 'v']:
            cells.append((nx, ny))
            break
        x, y = nx, ny
    return cells

def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr +=1
    for case in range(T):
        M = int(input[ptr])
        N = int(input[ptr+1])
        ptr +=2
        maze = []
        for _ in range(M):
            row = input[ptr].strip()
            maze.append(list(row))
            ptr +=1
        start = None
        goal = None
        teachers = []
        for i in range(M):
            for j in range(N):
                if maze[i][j] == 'S':
                    start = (i, j)
                elif maze[i][j] == 'G':
                    goal = (i, j)
                elif maze[i][j] in ['<', '>', '^', 'v']:
                    teachers.append((i, j, maze[i][j]))
        # Precompute unsafe cells for each mod
        unsafe = [set() for _ in range(4)]
        for tx, ty, initial_dir in teachers:
            for mod in range(4):
                current_dir = rotate_direction(initial_dir, mod)
                line = get_line_of_sight(tx, ty, current_dir, maze, M, N)
                for (x, y) in line:
                    unsafe[mod].add((x, y))
        # BFS
        visited = [[[False]*4 for _ in range(N)] for _ in range(M)]
        queue = deque()
        start_x, start_y = start
        queue.append((start_x, start_y, 0, 0))
        visited[start_x][start_y][0] = True
        found = False
        answer = -1
        while queue:
            x, y, mod, steps = queue.popleft()
            if (x, y) == goal:
                if (x, y) not in unsafe[mod]:
                    answer = steps
                    found = True
                    break
                else:
                    continue
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < M and 0 <= ny < N:
                    cell = maze[nx][ny]
                    if cell != '#' and cell not in ['<', '>', '^', 'v']:
                        next_mod = (mod + 1) % 4
                        if not visited[nx][ny][next_mod]:
                            if (nx, ny) not in unsafe[next_mod]:
                                visited[nx][ny][next_mod] = True
                                queue.append((nx, ny, next_mod, steps + 1))
        if found:
            print(f"Case #{case+1}: {answer}")
        else:
            print(f"Case #{case+1}: impossible")

