import sys

def readints():
    return list(map(int, sys.stdin.readline().split()))

def are_colinear(seg1, seg2):
    a1, a2 = seg1
    b1, b2 = seg2
    x1, y1 = a1
    x2, y2 = a2

    a = y2 - y1
    b = x1 - x2
    c = x2 * y1 - x1 * y2

    val1 = a * b1[0] + b * b1[1] + c
    val2 = a * b2[0] + b * b2[1] + c
    return val1 == 0 and val2 == 0

def segments_intersect(seg1, seg2):
    a, b = seg1
    c, d = seg2

    def ccw(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    ccw1 = ccw(a, b, c)
    ccw2 = ccw(a, b, d)
    ccw3 = ccw(c, d, a)
    ccw4 = ccw(c, d, b)

    if (ccw1 * ccw2 < 0) and (ccw3 * ccw4 < 0):
        return True

    def on_segment(p, seg):
        seg_a, seg_b = seg
        if ccw(seg_a, seg_b, p) != 0:
            return False
        return (min(seg_a[0], seg_b[0]) <= p[0] <= max(seg_a[0], seg_b[0]) and
                min(seg_a[1], seg_b[1]) <= p[1] <= max(seg_a[1], seg_b[1]))

    return on_segment(c, seg1) or on_segment(d, seg1) or on_segment(a, seg2) or on_segment(b, seg2)

def line_intersection(seg1, seg2):
    a1, a2 = seg1
    b1, b2 = seg2

    x1, y1 = a1
    x2, y2 = a2
    x3, y3 = b1
    x4, y4 = b2

    denominator = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if denominator == 0:
        return None

    t_numerator = (x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)
    t = t_numerator / denominator
    x = x1 + t * (x2 - x1)
    y = y1 + t * (y2 - y1)
    return (x, y)

def same_point(a, b):
    return abs(a[0] - b[0]) < 1e-8 and abs(a[1] - b[1]) < 1e-8

