def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx]); idx +=1
    M = int(data[idx]); idx +=1

    edges = []
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u = int(data[idx]); idx +=1
        v = int(data[idx]); idx +=1
        w = int(data[idx]); idx +=1
        edges.append((u, v, w))
        adj[u].append((v, w))
        adj[v].append((u, w))

    parent = [0]*(N+1)
    parent_weight = [0]*(N+1)
    disc = [0]*(N+1)
    low = [0]*(N+1)
    time = 1
    bridges = set()
    stack = [(1, 0, False)]
    while stack:
        u, p, visited = stack.pop()
        if not visited:
            if disc[u] != 0:
                continue
            disc[u] = low[u] = time
            time += 1
            parent[u] = p
            stack.append((u, p, True))
            for v, w in adj[u]:
                if v == p:
                    continue
                if disc[v] == 0:
                    parent_weight[v] = w
                    stack.append((v, u, False))
                else:
                    low[u] = min(low[u], disc[v])
        else:
            for v, w in adj[u]:
                if parent[v] == u:
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        bridges.add((u, v))
            for v, w in adj[u]:
                if v != p and parent[v] != u and disc[v] < disc[u]:
                    low[u] = min(low[u], disc[v])

    depth = [0]*(N+1)
    for u in range(2, N+1):
        depth[u] = depth[parent[u]] + 1

    LOG = 20
    up = [[0]*(N+1) for _ in range(LOG)]
    up[0] = parent
    for k in range(1, LOG):
        for u in range(1, N+1):
            up[k][u] = up[k-1][up[k-1][u]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    lca_sum = [0]*(N+1)
    for u, v, w in edges:
        if (u == parent[v] and (u, v) in bridges) or (v == parent[u] and (v, u) in bridges):
            continue
        if parent[v] != u and parent[u] != v:
            a = lca(u, v)
            lca_sum[a] += w

    children = [[] for _ in range(N+1)]
    for v in range(2, N+1):
        u = parent[v]
        children[u].append(v)

    tree_sum = [0]*(N+1)
    stack = []
    visited = [False]*(N+1)
    stack.append((1, False))
    while stack:
        u, done = stack.pop()
        if done:
            for v in children[u]:
                tree_sum[u] += tree_sum[v] + parent_weight[v]
            continue
        if visited[u]:
            continue
        visited[u] = True
        stack.append((u, True))
        for v in reversed(children[u]):
            stack.append((v, False))

    total_sum = sum(w for _, _, w in edges)

    min_cost = float('inf')
    best_edge = (0, 0)
    for u, v, w in edges:
        cost = 0
        is_bridge = False
        if parent[v] == u and (u, v) in bridges:
            sum_sub = tree_sum[v] + lca_sum[v]
            cost = abs(2 * sum_sub - (total_sum - w))
            is_bridge = True
        elif parent[u] == v and (v, u) in bridges:
            sum_sub = tree_sum[u] + lca_sum[u]
            cost = abs(2 * sum_sub - (total_sum - w))
            is_bridge = True
        else:
            cost = total_sum - w

        a, b = u, v
        if a > b:
            a, b = b, a

        if cost < min_cost or (cost == min_cost and (a < best_edge[0] or (a == best_edge[0] and b < best_edge[1]))):
            min_cost = cost
            best_edge = (a, b)

    print(best_edge[0], best_edge[1])

