import sys
from collections import defaultdict

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Precompute smallest prime factors up to 200000
    max_spf = 200000
    spf = list(range(max_spf + 1))
    for i in range(2, int(max_spf**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_spf+1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_exponents = defaultdict(list)

    for num in a:
        if num == 1:
            continue  # 1 contributes no primes
        temp = num
        factors = {}
        while temp != 1:
            p = spf[temp]
            cnt = 0
            while temp % p == 0:
                cnt += 1
                temp //= p
            factors[p] = cnt
        for p, exp in factors.items():
            prime_exponents[p].append(exp)

    result = 1
    for p, exponents in prime_exponents.items():
        count_divisible = len(exponents)
        count_zero = n - count_divisible
        if count_zero >= 2:
            continue
        elif count_zero == 1:
            min_exp = min(exponents)
            result *= p ** min_exp
        else:
            sorted_exponents = sorted(exponents)
            if len(sorted_exponents) >= 2:
                exp = sorted_exponents[1]
                result *= p ** exp

    print(result)

