import sys
sys.setrecursionlimit(1 << 25)

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n + 1)]  # 1-based indexing

    for i in range(n - 1):
        p, c = map(int, sys.stdin.readline().split())
        node = i + 2
        adj[node].append((p, c))
        adj[p].append((node, c))

    stack = [(1, None, False)]  # (node, parent, visited)
    data = {}  # Stores computed data for each node

    while stack:
        node, parent, visited = stack.pop()
        if not visited:
            stack.append((node, parent, True))
            # Push children (excluding parent) to process them first
            for neighbor, c in adj[node]:
                if neighbor != parent:
                    stack.append((neighbor, node, False))
        else:
            max_dist = 0
            min_a_minus = a[node - 1]
            leaves_kept = 0
            leaves_removed = 0

            for neighbor, c in adj[node]:
                if neighbor == parent:
                    continue
                child_data = data[neighbor]
                if c <= child_data['min_a_minus']:
                    # Keep this child's subtree
                    leaves_kept += child_data['leaves_kept']
                    leaves_removed += child_data['leaves_removed']
                    current_max = c + child_data['max_dist']
                    if current_max > max_dist:
                        max_dist = current_max
                    current_min = child_data['min_a_minus'] - c
                    if current_min < min_a_minus:
                        min_a_minus = current_min
                else:
                    # Prune this child's subtree
                    leaves_removed += child_data['leaves_kept'] + child_data['leaves_removed']

            if leaves_kept == 0:
                leaves_kept = 1

            data[node] = {
                'max_dist': max_dist,
                'min_a_minus': min_a_minus,
                'leaves_kept': leaves_kept,
                'leaves_removed': leaves_removed,
            }

    print(data[1]['leaves_removed'])

