    if coins[0] != 1:
        print(f"Case #{test_case}: Cannot pay some amount")
        continue

    if n >= 2:
        sum_upper = coins[-1] + coins[-2]
    else:
        sum_upper = coins[0]

    max_m = sum_upper
    dp = [float('inf')] * (max_m + 1)
    dp[0] = 0
    for i in range(1, max_m + 1):
        for c in coins:
            if c > i:
                break
            if dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1

    is_greedy_ok = True
    for m in range(1, sum_upper + 1):
        rem = m
        greedy = 0
        for c in reversed(coins):
            if rem >= c:
                q, rem = divmod(rem, c)
                greedy += q
            if rem == 0:
                break
        if dp[m] < greedy:
            is_greedy_ok = False
            break

    if is_greedy_ok:
        print(f"Case #{test_case}: OK")
    else:
        print(f"Case #{test_case}: Cannot use greedy algorithm")

def multiply_poly(a, b, f, p_mod):
    m = len(a)
    n = len(b)
    product = [0] * (m + n - 1)
    for i in range(m):
        if a[i] == 0:
            continue
        for j in range(n):
            product[i + j] = (product[i + j] + a[i] * b[j]) % p_mod
    return poly_mod(product, f, p_mod)

def poly_mod(dividend, divisor, p_mod):
    if not divisor:
        return []
    dividend = [x % p_mod for x in dividend]
    divisor = [x % p_mod for x in divisor]
    while len(divisor) > 0 and divisor[-1] == 0:
        divisor.pop()
    if not divisor:
        return []
    divisor_degree = len(divisor) - 1
    divisor_leading = divisor[-1]
    inv_lead = pow(divisor_leading, p_mod - 2, p_mod) if divisor_leading != 0 else 0
    remainder = dividend.copy()
    len_remainder = len(remainder)
    for i in range(len_remainder - divisor_degree - 1, -1, -1):
        if i + divisor_degree >= len(remainder):
            continue
        current_lead = remainder[i + divisor_degree]
        if current_lead == 0:
            continue
        factor = (current_lead * inv_lead) % p_mod
        for j in range(len(divisor)):
            idx = i + j
            if idx >= len(remainder):
                remainder.append(0)
            remainder[idx] = (remainder[idx] - factor * divisor[j]) % p_mod
    last_non_zero = -1
    for idx in range(len(remainder)):
        if remainder[idx] != 0:
            last_non_zero = idx
    return remainder[: last_non_zero + 1] if last_non_zero != -1 else []

def pow_x(n, f, p_mod):
    result = [1]
    current_base = [0, 1]
    while n > 0:
        if n % 2 == 1:
            result = multiply_poly(result, current_base, f, p_mod)
        current_base = multiply_poly(current_base, current_base, f, p_mod)
        n //= 2
    return result

def poly_gcd(a, b, p_mod):
    a, b = a.copy(), b.copy()
    while True:
        if not b:
            return a
        remainder = poly_mod(a, b, p_mod)
        a, b = b, remainder

