def simulate_explosions(grid):
    grid = [list(row) for row in grid]
    explode_queue = []
    for i in range(4):
        for j in range(4):
            if grid[i][j] >= 5:
                explode_queue.append((i, j))

    active_waterdrops = []

    while explode_queue or active_waterdrops:
        while explode_queue:
            i, j = explode_queue.pop(0)
            if grid[i][j] < 5:
                continue
            grid[i][j] = 0
            dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            for dx, dy in dirs:
                active_waterdrops.append((i, j, dx, dy))

        hits = defaultdict(int)
        new_waterdrops = []
        for w in active_waterdrops:
            x, y, dx, dy = w
            nx = x + dx
            ny = y + dy
            if 0 <= nx < 4 and 0 <= ny < 4:
                if grid[nx][ny] >= 1:
                    hits[(nx, ny)] += 1
                else:
                    new_waterdrops.append((nx, ny, dx, dy))

        active_waterdrops = new_waterdrops

        for (x, y), cnt in hits.items():
            grid[x][y] += cnt
            if grid[x][y] >= 5:
                explode_queue.append((x, y))

    return tuple(tuple(row) for row in grid)

