import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def max_row_from_bricks(N):
    # Calculate the maximum row index m such that total bricks up to m is <= N
    m = (int(math.sqrt(8 * N + 1)) - 1) // 2
    while (m + 1) * (m + 2) // 2 > N:
        m -= 1
    return m

