from collections import deque

def count_components(grid, target):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    visited = set()
    count = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == target and (i, j) not in visited:
                # BFS to find all connected components
                queue = deque([(i, j)])
                visited.add((i, j))
                while queue:
                    x, y = queue.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == target and (nx, ny) not in visited:
                                visited.add((nx, ny))
                                queue.append((nx, ny))
                count += 1
    return count

