    type_root = [0] * (k + 1)  # type 1..k
    for i in range(1, k + 1):
        # Determine start and end indices for type i
        start = sum(c[:i-1]) + 1
        end = start + c[i-1] - 1
        if start > end:
            valid = False
            break
        # Check all bacteria in type i have the same root
        root = dsu.find(start)
        for u in range(start, end + 1):
            if dsu.find(u) != root:
                valid = False
                break
        if not valid:
            break
        type_root[i] = root

    if not valid:
        print("No")
        return

    # Build component graph adjacency list
    adj = defaultdict(list)
    for u, v, x in edges:
        if x > 0:
            ru = dsu.find(u)
            rv = dsu.find(v)
            if ru != rv:
                adj[ru].append((rv, x))
                adj[rv].append((ru, x))

    # Collect unique roots of types
    S = list(set(type_root[1:]))
    # Precompute distances using Dijkstra for each root in S
    dists = {}
    for root in S:
        dist = defaultdict(lambda: float('inf'))
        dist[root] = 0
        heap = [(0, root)]
        visited = set()
        while heap:
            d, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            for v, w in adj.get(u, []):
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        dists[root] = dist

    # Build the answer matrix
    ans = []
    for i in range(1, k + 1):
        row = []
        for j in range(1, k + 1):
            if i == j:
                row.append(0)
            else:
                ri = type_root[i]
                rj = type_root[j]
                if ri == rj:
                    row.append(0)
                else:
                    if ri not in dists or rj not in dists[ri]:
                        row.append(-1)
                    else:
                        d = dists[ri][rj]
                        row.append(d if d != float('inf') else -1)
        ans.append(row)

    print("Yes")
    for row in ans:
        print(' '.join(map(str, row)))

