import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    d = []
    for _ in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        d.append(row)

    if n == 1:
        print("YES" if d[0][0] == 0 else "NO")
        return

    # Check diagonal elements
    for i in range(n):
        if d[i][i] != 0:
            print("NO")
            return

    # Check symmetry and positive for non-diagonal
    for i in range(n):
        for j in range(n):
            if i != j:
                if d[i][j] <= 0 or d[i][j] != d[j][i]:
                    print("NO")
                    return

    # Generate all edges (i, j) with i < j, sorted by weight
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((d[i][j], i, j))
    edges.sort()

    # Kruskal's algorithm to find MST
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        parent[v_root] = u_root
        return True

    adj = [[] for _ in range(n)]
    edge_count = 0
    for w, u, v in edges:
        if union(u, v):
            adj[u].append((v, w))
            adj[v].append((u, w))
            edge_count += 1
            if edge_count == n - 1:
                break

    # Check if all pairs' distances match using BFS
    valid = True
    for u in range(n):
        dist = [-1] * n
        q = deque()
        q.append(u)
        dist[u] = 0
        while q:
            current = q.popleft()
            for neighbor, weight in adj[current]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[current] + weight
                    q.append(neighbor)
        for v in range(n):
            if dist[v] != d[u][v]:
                valid = False
                break
        if not valid:
            break

    print("YES" if valid else "NO")

