import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, q = int(input[ptr]), int(input[ptr+1])
    ptr +=2
    a = list(map(int, input[ptr:ptr+n]))
    ptr +=n
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u = int(input[ptr])
        v = int(input[ptr+1])
        adj[u].append(v)
        adj[v].append(u)
        ptr +=2

    in_time = [0]*(n+1)
    out_time = [0]*(n+1)
    parent = [0]*(n+1)
    depth = [0]*(n+1)
    time = 0
    LOG = 20
    up = [[0]*(n+1) for _ in range(LOG)]

    stack = [(1, 0, False)]
    while stack:
        u, p, visited = stack.pop()
        if visited:
            out_time[u] = time
            continue
        time +=1
        in_time[u] = time
        parent[u] = p
        up[0][u] = p
        depth[u] = depth[p] +1
        stack.append( (u, p, True) )
        for v in adj[u]:
            if v != p:
                stack.append( (v, u, False) )

    for k in range(1, LOG):
        for u in range(1, n+1):
            up[k][u] = up[k-1][up[k-1][u]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1<<k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    def ancestor(u, d):
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1<<k) >= d:
                u = up[k][u]
        return u

    size = [0]*(n+1)
    def dfs_size(u, p):
        size[u] =1
        for v in adj[u]:
            if v != p:
                dfs_size(v, u)
                size[u] += size[v]
        return
    dfs_size(1,0)

    head = [0]*(n+1)
    pos = [0]*(n+1)
    curr_pos =0
    def dfs_hld(u, p, h):
        nonlocal curr_pos
        head[u] = h
        pos[u] = curr_pos
        curr_pos +=1
        max_size = -1
        heavy = -1
        for v in adj[u]:
            if v != p and size[v] > max_size:
                max_size = size[v]
                heavy = v
        if heavy != -1:
            dfs_hld(heavy, u, h)
            for v in adj[u]:
                if v != p and v != heavy:
                    dfs_hld(v, u, v)
    dfs_hld(1,0,1)

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0]*(self.n+2)
        def add(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx
        def range_add(self, l, r, delta):
            self.add(l, delta)
            self.add(r+1, -delta)
        def query_point(self, idx):
            res =0
            while idx>0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res
        def query_range(self, l, r):
            return self.query_point(r) - self.query_point(l-1)

    ft_orig = FenwickTree(n)
    for i in range(1, n+1):
        ft_orig.range_add(pos[i], pos[i], a[i-1])

    def get_child(v, r):
        if depth[r] < depth[v]:
            return -1
        d = depth[v] +1
        u = ancestor(r, d)
        if parent[u] == v:
            return u
        else:
            return -1

    def query_subtree(v, current_root):
        if in_time[v] <= in_time[current_root] <= out_time[v]:
            c = get_child(v, current_root)
            if c == -1:
                return ft_orig.query_range(pos[v], pos[v] + size[v] -1)
            sum_v = ft_orig.query_range(pos[v], pos[v] + size[v] -1)
            sum_c = ft_orig.query_range(pos[c], pos[c] + size[c] -1)
            return sum_v - sum_c
        else:
            return ft_orig.query_range(pos[v], pos[v] + size[v] -1)

    def update_path(u, v, x):
        while head[u] != head[v]:
            if depth[head[u]] < depth[head[v]]:
                u, v = v, u
            ft_orig.range_add(pos[head[u]], pos[u], x)
            u = parent[head[u]]
        if depth[u] > depth[v]:
            u, v = v, u
        ft_orig.range_add(pos[u], pos[v], x)

    current_root =1
    output = []
    for _ in range(q):
        query = input[ptr]
        ptr +=1
        if query == '1':
            v = int(input[ptr])
            ptr +=1
            current_root = v
        elif query == '2':
            u = int(input[ptr])
            v = int(input[ptr+1])
            x = int(input[ptr+2])
            ptr +=3
            l = lca(u, v)
            update_path(u, l, x)
            update_path(v, l, x)
            update_path(l, l, -x)
        elif query == '3':
            v = int(input[ptr])
            ptr +=1
            res = query_subtree(v, current_root)
            output.append(str(res))
    print('\n'.join(output))

