from collections import deque

def main():
    N, M = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(N + 1)]
    in_degree = [0] * (N + 1)

    for _ in range(M):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        in_degree[y] += 1

    # Kahn's algorithm for topological sort
    queue = deque()
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Calculate longest path
    dp = [0] * (N + 1)
    for u in top_order:
        for v in adj[u]:
            if dp[v] < dp[u] + 1:
                dp[v] = dp[u] + 1

    print(max(dp))

