import sys

def process_dataset(n):
    grid = []
    heights = [0] * 5
    for _ in range(n):
        d, p, q = map(int, sys.stdin.readline().split())
        if d == 1:
            # Horizontal block
            c_start = q - 1
            c_end = c_start + p - 1
            max_landing_row = max(heights[c] for c in range(c_start, c_end + 1))
            # Extend grid if needed
            while len(grid) <= max_landing_row:
                grid.append([0]*5)
            # Update grid
            for c in range(c_start, c_end + 1):
                grid[max_landing_row][c] = 1
            # Update heights
            for c in range(c_start, c_end + 1):
                heights[c] = max_landing_row + 1
        else:
            # Vertical block
            c = q - 1
            landing_row = heights[c]
            new_height = landing_row + p
            # Extend grid if needed
            while len(grid) < landing_row + p:
                grid.append([0]*5)
            # Update grid
            for row in range(landing_row, landing_row + p):
                grid[row][c] = 1
            # Update heights
            heights[c] = new_height

        # Check for filled rows
        filled_rows = []
        for row_idx in range(len(grid)):
            if all(cell == 1 for cell in grid[row_idx]):
                filled_rows.append(row_idx)
        # Remove filled rows and adjust heights
        filled_rows.sort(reverse=True)
        for row in filled_rows:
            for c in range(5):
                if grid[row][c] == 1:
                    heights[c] -= 1
            del grid[row]
    return sum(heights)

