        memo = {}

        def dfs(state):
            if state in memo:
                return memo[state]
            m = len(state)
            if m == 0:
                return 0
            pairs = []
            for x in range(m):
                for y in range(x + 1, m):
                    row_x, col_x = x // 4, x % 4
                    row_y, col_y = y // 4, y % 4
                    if abs(row_x - row_y) <= 1 and abs(col_x - col_y) <= 1:
                        if original_values[state[x]] == original_values[state[y]]:
                            pairs.append((x, y))
            if not pairs:
                memo[state] = m
                return m
            min_p = m
            for x, y in pairs:
                new_list = list(state)
                new_list.pop(x)
                new_list.pop(y - 1)
                new_state = tuple(new_list)
                res = dfs(new_state)
                if res < min_p:
                    min_p = res
                    if min_p == 0:
                        break
            memo[state] = min_p
            return min_p

