import sys
from collections import defaultdict

def main():
    lines = [line.rstrip() for line in sys.stdin]
    ptr = 0
    while True:
        n = int(lines[ptr])
        ptr += 1
        if n == 0:
            break
        territories = []
        for _ in range(n):
            country = lines[ptr]
            ptr += 1
            points = []
            while True:
                line = lines[ptr]
                ptr += 1
                if line == '-1':
                    break
                x, y = map(int, line.split())
                points.append((x, y))
            edges = set()
            for i in range(len(points)):
                p1 = points[i]
                p2 = points[(i + 1) % len(points)]
                edge = frozenset([p1, p2])
                edges.add(edge)
            territories.append((country, edges))
        # Group by country
        countries = defaultdict(list)
        for name, edges in territories:
            countries[name].append(edges)
        # Aggregate edges per country
        country_edges = {}
        for name in countries:
            all_edges = set()
            for edges_list in countries[name]:
                all_edges.update(edges_list)
            country_edges[name] = all_edges
        # Build adjacency
        country_list = list(countries.keys())
        num = len(country_list)
        adj = [[False]*num for _ in range(num)]
        for i in range(num):
            for j in range(i+1, num):
                a_edges = country_edges[country_list[i]]
                b_edges = country_edges[country_list[j]]
                if a_edges & b_edges:
                    adj[i][j] = adj[j][i] = True
        # Find minimal colors
        min_k = num
        for k in range(1, num + 1):
            colors = [-1] * num
            def backtrack(index):
                if index == num:
                    return True
                for c in range(k):
                    valid = True
                    for neighbor in range(num):
                        if adj[index][neighbor] and colors[neighbor] == c:
                            valid = False
                            break
                    if valid:
                        colors[index] = c
                        if backtrack(index + 1):
                            return True
                        colors[index] = -1
                return False
            if backtrack(0):
                min_k = k
                break
        print(min_k)

