    input = sys.stdin.read().splitlines()
    idx = 0
    T = int(input[idx])
    idx += 1
    for _ in range(T):
        if idx >= len(input):
            break
        line = input[idx].strip()
        while not line:
            idx += 1
            line = input[idx].strip()
        X, Y, Z = map(int, line.split())
        idx += 1
        B = [[[0 for _ in range(Z)] for __ in range(Y)] for ___ in range(X)]
        for l in range(X * Y):
            if idx >= len(input):
                break
            current_line = input[idx].strip()
            while not current_line:
                idx += 1
                current_line = input[idx].strip()
            nums = list(map(int, current_line.split()))
            i = l // Y
            j = l % Y
            for k in range(Z):
                if k < len(nums):
                    B[i][j][k] = nums[k]
                else:
                    B[i][j][k] = 0
            idx += 1
        A = [[[0 for _ in range(Z)] for __ in range(Y)] for ___ in range(X)]
        for i in range(X):
            for j in range(Y):
                for k in range(Z):
                    a = B[i][j][k]
                    if i > 0:
                        a -= B[i-1][j][k]
                    if j > 0:
                        a -= B[i][j-1][k]
                    if k > 0:
                        a -= B[i][j][k-1]
                    if i > 0 and j > 0:
                        a += B[i-1][j-1][k]
                    if i > 0 and k > 0:
                        a += B[i-1][j][k-1]
                    if j > 0 and k > 0:
                        a += B[i][j-1][k-1]
                    if i > 0 and j > 0 and k > 0:
                        a -= B[i-1][j-1][k-1]
                    A[i][j][k] = a
        for i in range(X):
            for j in range(Y):
                line = ' '.join(map(str, A[i][j])) + ' '
                print(line)

