import sys
from collections import deque

MOD = 998244353

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    # Precompute distances from each node
    dist = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n+1):
        d = [-1] * (n + 1)
        d[i] = 0
        q = deque([i])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] == -1:
                    d[v] = d[u] + 1
                    q.append(v)
        dist[i] = d

    # Compute the result for each pair (i, j)
    result = []
    for i in range(1, n+1):
        row = []
        for j in range(1, n+1):
            res = 1
            for t in range(1, n+1):
                if t == i or t == j:
                    continue
                di_t = dist[i][t]
                dj_t = dist[j][t]
                req_i = di_t - 1
                req_j = dj_t - 1
                cnt = 0
                for u in adj[t]:
                    if dist[i][u] == req_i and dist[j][u] == req_j:
                        cnt += 1
                if cnt == 0:
                    res = 0
                    break
                res = (res * cnt) % MOD
            row.append(res % MOD)
        result.append(row)

    for row in result:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()

