import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(n)]

    # Directions: right, down, left, up
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start_x, start_y, direction):
        visited = [[[False]*4 for _ in range(m)] for _ in range(n)]
        q = deque()
        q.append((start_x, start_y, direction))
        visited[start_x][start_y][direction] = True
        while q:
            x, y, d = q.popleft()
            dx, dy = dirs[d]
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                cell = grid[nx][ny]
                if cell == '#':
                    # Regular column, continue in the same direction
                    if not visited[nx][ny][d]:
                        visited[nx][ny][d] = True
                        q.append((nx, ny, d))
                else:
                    # Empty cell, continue in the same direction
                    if not visited[nx][ny][d]:
                        visited[nx][ny][d] = True
                        q.append((nx, ny, d))
        reachable = [[False]*m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                for k in range(4):
                    if visited[i][j][k]:
                        reachable[i][j] = True
        return reachable

    # Person starts at (0,0) looking right (direction 0)
    person_reach = bfs(0, 0, 0)
    # Basilisk starts at (n-1, m-1) looking left (direction 2)
    basilisk_reach = bfs(n-1, m-1, 2)

    # Check for any '.' in the intersection
    impossible = False
    for i in range(n):
        for j in range(m):
            if person_reach[i][j] and basilisk_reach[i][j]:
                if grid[i][j] == '.':
                    impossible = True

    if impossible:
        print(-1)
        return

    # Build bipartite graph for # cells that are in both reaches
    edges = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#' and person_reach[i][j] and basilisk_reach[i][j]:
                edges.append((i, j))

    # Bipartite graph matching using Hopcroft-Karp algorithm
    from collections import defaultdict
    graph = defaultdict(list)
    u_rows = set()
    u_cols = set()
    for i, j in edges:
        u_rows.add(i)
        u_cols.add(j)
        graph[i].append(j)

    # Maximum bipartite matching
    def max_matching(graph, U):
        pair_U = {u: None for u in U}
        pair_V = {}
        dist = {}

        def bfs_hk():
            queue = deque()
            for u in U:
                if pair_U[u] is None:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist[None] = float('inf')
            while queue:
                u = queue.popleft()
                if u is not None:
                    for v in graph.get(u, []):
                        if dist.get(pair_V.get(v), float('inf')) == float('inf'):
                            dist[pair_V.get(v)] = dist[u] + 1
                            queue.append(pair_V.get(v))
            return dist[None] != float('inf')

        def dfs_hk(u):
            if u is not None:
                for v in graph.get(u, []):
                    if dist.get(pair_V.get(v), float('inf')) == dist[u] + 1:
                        if dfs_hk(pair_V.get(v)):
                            pair_U[u] = v
                            pair_V[v] = u
                            return True
                dist[u] = float('inf')
                return False
            return True

        result = 0
        while bfs_hk():
            for u in U:
                if pair_U[u] is None:
                    if dfs_hk(u):
                        result += 1
        return result

    U = list(u_rows)
    match_size = max_matching(graph, U)
    print(match_size)

if __name__ == "__main__":
    main()

