    h, l, r = map(int, input().split())
    buildings.append((h, l, r))

events = []
for h, l, r in buildings:
    events.append((l, h, True))
    events.append((r, h, False))

def event_key(event):
    x, h, is_start = event
    return (x, 0 if is_start else 1, -h if is_start else h)

events.sort(key=event_key)

key_points = []
heap = []
count = defaultdict(int)
current_max = 0
prev_max = 0

for event in events:
    x, h, is_start = event

    if is_start:
        heapq.heappush(heap, -h)
        count[h] += 1
    else:
        count[h] -= 1
        if count[h] == 0:
            del count[h]

    # Find current_max
    while heap:
        potential_h = -heap[0]
        if potential_h in count and count[potential_h] > 0:
            current_max = potential_h
            break
        else:
            heapq.heappop(heap)
    else:
        current_max = 0

    if current_max != prev_max:
        key_points.append((x, current_max))
        prev_max = current_max

vertices = []
