class TrieNode:
    __slots__ = ['children', 'is_end']
    def __init__(self):
        self.children = {}
        self.is_end = False

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx +=1
    L = int(input[idx])
    idx +=1
    strings = []
    for _ in range(N):
        s = input[idx]
        idx +=1
        strings.append(s)

    root = TrieNode()
    for s in strings:
        node = root
        for c in s:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
            if node.is_end:
                break  # Since the input is prefix-free, this shouldn't happen
        node.is_end = True

    stack = [('', root)]
    available = []

    while stack:
        path, node = stack.pop()
        depth = len(path)
        if depth > L:
            continue
        if not node.is_end:
            available.append(depth)
        if node.is_end:
            continue
        for c in ['0', '1']:
            if c in node.children:
                stack.append((path + c, node.children[c]))
            else:
                stack.append((path + c, TrieNode()))

    xor_sum = 0
    for depth in available:
        m = L - depth
        if m <=0:
            continue
        m_plus_1 = m + 1
        trailing_ones = 0
        while m_plus_1 & 1 == 0:
            m_plus_1 >>=1
            trailing_ones +=1
        grundy = trailing_ones
        xor_sum ^= grundy

    if xor_sum !=0:
        print("Alice")
    else:
        print("Bob")

