from math import gcd

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        p, q, a, n = map(int, line.split())
        if p == 0 and q == 0 and a == 0 and n == 0:
            break
        g = gcd(p, q)
        p_simplified = p // g
        q_simplified = q // g

        def dfs(num, den, product, steps_left, last_d):
            if num == 0:
                return 1
            if steps_left == 0:
                return 0
            count = 0
            d_min = max(last_d, (den + num - 1) // num)
            d = d_min
            while True:
                try:
                    d_power = d ** steps_left
                except OverflowError:
                    break
                if product * d_power > a:
                    break
                if num * d > steps_left * den:
                    d += 1
                    continue
                new_num = num * d - den
                new_den = den * d
                if new_num < 0:
                    d += 1
                    continue
                g_new = gcd(new_num, new_den)
                new_num_simplified = new_num // g_new
                new_den_simplified = new_den // g_new
                if new_num_simplified == 0:
                    count += 1
                else:
                    count += dfs(new_num_simplified, new_den_simplified, product * d, steps_left - 1, d)
                d += 1
            return count

        result = dfs(p_simplified, q_simplified, 1, n, 0)
        print(result)

