import sys
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        while ptr < len(input) and input[ptr] == '':
            ptr += 1
        if ptr >= len(input):
            break
        n = int(input[ptr])
        m = int(input[ptr+1])
        ptr += 2
        edges = []
        for __ in range(m):
            a = int(input[ptr]) - 1
            b = int(input[ptr+1]) - 1
            edges.append((a, b))
            ptr += 2

        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)

        # Determine reachable nodes from 0 (1-based)
        reachable = [False] * n
        q = deque([0])
        reachable[0] = True
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not reachable[v]:
                    reachable[v] = True
                    q.append(v)

        # Build subgraph edges for reachable nodes
        sub_edges = []
        for a, b in edges:
            if reachable[a] and reachable[b]:
                sub_edges.append((a, b))

        sub_adj = [[] for _ in range(n)]
        for a, b in sub_edges:
            sub_adj[a].append(b)

        # Kosaraju's algorithm for SCCs in subgraph
        def kosaraju(adj, n, reachable):
            order = []
            visited = [False] * n
            for u in range(n):
                if reachable[u] and not visited[u]:
                    stack = [(u, False)]
                    while stack:
                        node, processed = stack.pop()
                        if processed:
                            order.append(node)
                            continue
                        if visited[node]:
                            continue
                        visited[node] = True
                        stack.append((node, True))
                        for v in reversed(adj[node]):
                            if reachable[v] and not visited[v]:
                                stack.append((v, False))
            reverse_adj = [[] for _ in range(n)]
            for a, b in sub_edges:
                reverse_adj[b].append(a)
            visited = [False] * n
            components = []
            for u in reversed(order):
                if not visited[u]:
                    stack = [u]
                    visited[u] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for v in reverse_adj[node]:
                            if not visited[v]:
                                visited[v] = True
                                stack.append(v)
                    components.append(component)
            return components

        components = kosaraju(sub_adj, n, reachable)
        comp_id = [-1] * n
        for i, comp in enumerate(components):
            for u in comp:
                comp_id[u] = i

        cyclic_component = [False] * len(components)
        for i, comp in enumerate(components):
            if len(comp) > 1:
                cyclic_component[i] = True
            else:
                u = comp[0]
                cyclic_component[i] = any(v == u for v in sub_adj[u])

        dag_adj = [[] for _ in range(len(components))]
        edge_set = set()
        for a, b in sub_edges:
            u_comp = comp_id[a]
            v_comp = comp_id[b]
            if u_comp != v_comp and (u_comp, v_comp) not in edge_set:
                edge_set.add((u_comp, v_comp))
                dag_adj[u_comp].append(v_comp)

        dangerous_components = [False] * len(components)
        q = deque()
        for i in range(len(components)):
            if cyclic_component[i]:
                dangerous_components[i] = True
                q.append(i)
        while q:
            u_comp = q.popleft()
            for v_comp in dag_adj[u_comp]:
                if not dangerous_components[v_comp]:
                    dangerous_components[v_comp] = True
                    q.append(v_comp)

        answer = [0] * n
        for i in range(n):
            if not reachable[i]:
                answer[i] = 0
            elif dangerous_components[comp_id[i]]:
                answer[i] = -1

        non_dangerous_adj = [[] for _ in range(n)]
        for a, b in sub_edges:
            if not dangerous_components[comp_id[a]] and not dangerous_components[comp_id[b]]:
                non_dangerous_adj[a].append(b)

        in_degree = [0] * n
        for a in range(n):
            if reachable[a] and not dangerous_components[comp_id[a]]:
                for b in non_dangerous_adj[a]:
