s = input()
result = []
i = 0
n = len(s)
in_quote = False

while i < n:
    if not in_quote:
        # Skip spaces
        while i < n and s[i] == ' ':
            i += 1
        if i >= n:
            break
        if s[i] == '"':
            # Start quoted lexeme
            in_quote = True
            i += 1
        else:
            # Start unquoted lexeme
            start = i
            while i < n and s[i] != ' ':
                i += 1
            lex = s[start:i]
            result.append(lex)
    else:
        # Inside quote, find closing "
        end = s.find('"', i)
        lex = s[i:end]
        result.append(lex)
        i = end + 1
        in_quote = False

for lex in result:
    print(f"<{lex}>")

