def can_partition(costs):
    total = sum(costs)
    if total % 2 != 0:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for num in costs:
        for i in range(target, num - 1, -1):
            if dp[i - num]:
                dp[i] = True
        if dp[target]:
            return True
    return dp[target]

