            if current_state[0] == (X, Y):
                print(steps)
                found = True
                break

            for mask in [m for m in range(1 << n) if (m & (m << 1)) == 0]:
                moving = []
                valid_mask = True
                possible_positions = []
                for i in range(n):
                    if not (mask & (1 << i)):
                        continue
                    moving.append(i)
                    if i == 0:
                        adj = current_state[1]
                        candidates = []
                        for dx, dy in directions:
