                                    occupied = True
                                    break
                            if not occupied and (nx, ny) != current_state[i]:
                                candidates.append((nx, ny))
                    elif i == n - 1:
                        adj = current_state[i-1]
                        candidates = []
                        for dx, dy in directions:
                            nx, ny = adj[0] + dx, adj[1] + dy
                            if (nx, ny) in rocks:
                                continue
                            occupied = False
                            for j in range(n):
