                    else:
                        prev_p = current_state[i-1]
                        next_p = current_state[i+1]
                        adj_prev = set((prev_p[0]+dx, prev_p[1]+dy) for dx, dy in directions)
                        adj_next = set((next_p[0]+dx, next_p[1]+dy) for dx, dy in directions)
                        common = adj_prev & adj_next
                        candidates = []
                        for (nx, ny) in common:
                            if (nx, ny) in rocks:
                                continue
                            occupied = False
                            for j in range(n):
                                if j not in moving and (nx, ny) == current_state[j]:
                                    occupied = True
                                    break
                            if not occupied and (nx, ny) != current_state[i]:
                                candidates.append((nx, ny))
                    if not candidates:
                        valid_mask = False
                        break
                    possible_positions.append(candidates)
                if not valid_mask or not moving:
