import sys
from collections import defaultdict

class Edge:
    def __init__(self, u, v, weight):
        self.u = u
        self.v = v
        self.weight = weight

def read_vectors():
    input = sys.stdin.read().split()
    idx = 0
    n, m = int(input[idx]), int(input[idx+1])
    idx +=2
    vectors = []
    for _ in range(m):
        vec = list(map(float, input[idx:idx+n]))
        idx +=n
        vectors.append(vec)
    return vectors

def dot(v1, v2):
    return sum(a*b for a, b in zip(v1, v2))

def norm_sq(vec):
    return dot(vec, vec)

def compute_residual_cost(i_vec, j_vec):
    if all(x == 0 for x in i_vec):
        return norm_sq(j_vec)
    numerator = dot(i_vec, j_vec)
    denominator = norm_sq(i_vec)
    r = numerator / denominator
    residual_sq = norm_sq([j - r*i for i, j in zip(i_vec, j_vec)])
    return residual_sq

def edmonds(edges, root, num_nodes):
    incoming = defaultdict(list)
    for e in edges:
        incoming[e.v].append(e)

    min_in_edges = {}
    for v in incoming:
        if v == root:
            continue
        if not incoming[v]:
            continue
        min_edge = min(incoming[v], key=lambda e: e.weight)
        min_in_edges[v] = min_edge

    visited = set()
    cycle = None
    for v in min_in_edges:
        if v in visited:
            continue
        path = []
        current = v
        while True:
            if current in visited:
                if current in path:
                    idx = path.index(current)
                    cycle = path[idx:]
                    break
                else:
                    break
            visited.add(current)
            path.append(current)
            if current not in min_in_edges:
                break
            current = min_in_edges[current].u
        if cycle:
            break

    if not cycle:
        return sum(e.weight for e in min_in_edges.values())

    cycle_nodes = set(cycle)
    cycle_edges = [min_in_edges[v] for v in cycle]
    min_cycle_weight = min(e.weight for e in cycle_edges)

    new_node = num_nodes
    contracted_edges = []
    for e in edges:
        if e.v in cycle_nodes:
            if e.u not in cycle_nodes:
                uv_in_cycle = next(ce for ce in cycle_edges if ce.v == e.v)
                new_weight = e.weight - uv_in_cycle.weight
                contracted_edges.append(Edge(e.u, new_node, new_weight))
        elif e.u in cycle_nodes:
            uv_in_cycle = min_in_edges[e.u]
            new_weight = e.weight - uv_in_cycle.weight
            contracted_edges.append(Edge(new_node, e.v, new_weight))
        else:
            contracted_edges.append(e)

    contracted_total = edmonds(contracted_edges, root, new_node + 1)

    selected = None
    for e in contracted_edges:
        if e.v == new_node and e.weight == (contracted_total - sum(ce.weight for ce in cycle_edges) + min_cycle_weight):
            selected = e
            break

    if selected is None:
        return contracted_total + sum(e.weight for e in cycle_edges) - min_cycle_weight

    for e in cycle_edges:
        if e.u == selected.u and e.v == selected.v:
            return contracted_total + sum(e.weight for e in cycle_edges) - min_cycle_weight

    selected_v = None
    for e in edges:
        if e.u == selected.u and e.v in cycle_nodes:
            selected_v = e.v
            break

    exclude_edge = None
