    for i in range(n):
        catalan[n] = (catalan[n] + catalan[i] * catalan[n - 1 - i]) % MOD

def compute_case(N, K):
    if N == 0 or K == 0:
        return 0
    total = 0
    for d in range(1, K + 1):
        if N < 2 * d:
            continue
        if (N - d) % (d + 1) == 0:
            m = (N - d) // (d + 1)
            if m < 0:
                continue
            if m <= MAX_N // 2:
                total = (total + catalan[m]) % MOD
    return total

