import sys
from collections import deque

def compute_diameter(n, edges):
    adj = [[] for _ in range(n+1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        visited = [False] * (n+1)
        q = deque()
        q.append((start, 1))
        visited[start] = True
        max_node, max_dist = start, 1
        while q:
            u, d = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append((v, d + 1))
                    if d + 1 > max_dist:
                        max_dist = d + 1
                        max_node = v
        return max_node, max_dist

    u, _ = bfs(1)
    v, dist = bfs(u)
    return dist + 1  # number of nodes in the diameter

def max_matching(n, edges):
    adj = [[] for _ in range(n+1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    dp = [[0, 0] for _ in range(n+1)]  # 0: not matched, 1: matched

    def dfs(u, parent):
        for v in adj[u]:
            if v != parent:
                dfs(v, u)
                dp[u][0] += max(dp[v][0], dp[v][1])
        for v in adj[u]:
            if v != parent:
                current = 1 + dp[v][0] + (dp[u][0] - max(dp[v][0], dp[v][1]))
                if current > dp[u][1]:
                    dp[u][1] = current

    dfs(1, -1)
    return max(dp[1][0], dp[1][1])

def main():
    n = int(sys.stdin.readline())
    edges = []
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))

    diameter = compute_diameter(n, edges)
    matching = max_matching(n, edges)

    ans = [0] * (n + 1)
    ans[1] = n
    if n >= 2:
        ans[2] = matching

    for k in range(3, diameter + 1):
        ans[k] = min(ans[k-1], n // k)

    for k in range(diameter + 1, n + 1):
        ans[k] = 0

    print(' '.join(map(str, ans[1:n+1])))

