def main():
    n = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    B = list(map(int, sys.stdin.readline().split()))

    if n == 1:
        if A == B:
            print("SMALL")
            print(0)
            print()
        else:
            print("IMPOSSIBLE")
        return

    current = B.copy()
    ops = []
    count_p = 0

    def is_non_decreasing(arr):
        for i in range(1, len(arr)):
            if arr[i] < arr[i-1]:
                return False
        return True

    while True:
        if current == A:
            break
        rev_current = current[::-1]
        if rev_current == A:
            ops.append('R')
            break

        if is_non_decreasing(current):
            if n == 2:
                x, y = current
                if x <= 0 or y < x:
                    rev_cur = current[::-1]
                    if is_non_decreasing(rev_cur):
                        current = rev_cur
                        ops.append('R')
                        continue
                    else:
                        print("IMPOSSIBLE")
                        return
                if x == 0:
                    print("IMPOSSIBLE")
                    return
                k = (y - x) // x
                if k <= 0:
                    k = 1
                new_y = y - k * x
                if new_y < x:
                    k = 1
                    new_y = y - x
                if new_y < 0:
                    print("IMPOSSIBLE")
                    return
                count_p += k
                current = [x, new_y]
                ops.extend(['P'] * k)
            else:
                prev = []
                valid = True
                prev_val = current[0]
                if prev_val <= 0:
                    valid = False
                else:
                    prev.append(prev_val)
                    for i in range(1, n):
                        diff = current[i] - current[i-1]
                        if diff <= 0:
                            valid = False
                            break
                        prev.append(diff)
                if valid:
                    current = prev
                    count_p += 1
                    ops.append('P')
                    if count_p > 2 * 10**5:
                        print("BIG")
                        print(count_p)
                        return
                else:
                    rev_cur = current[::-1]
                    if is_non_decreasing(rev_cur):
                        current = rev_cur
                        ops.append('R')
                    else:
                        print("IMPOSSIBLE")
                        return
        else:
            rev_cur = current[::-1]
            if is_non_decreasing(rev_cur):
                current = rev_cur
                ops.append('R')
            else:
                print("IMPOSSIBLE")
                return

        if count_p > 2 * 10**5:
            print("BIG")
            print(count_p)
            return

    if current != A and current[::-1] == A:
        ops.append('R')

    ops.reverse()
    total_ops = len(ops)
    for c in ops:
        if c == 'P':
            count_p += 1

    if count_p > 2 * 10**5:
        print("BIG")
        print(count_p)
    else:
        print("SMALL")
        print(total_ops)
        print(''.join(ops))

