import sys

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def main():
    n = int(sys.stdin.readline())
    if n < 2:
        print(0)
        return

    primes = sieve(n)
    even = list(range(2, n + 1, 2))
    used = [False] * (n + 1)
    pairs = []

    # Pair even numbers
    even_count = len(even)
    even_pairs = even_count // 2
    for i in range(even_pairs):
        a = even[2 * i]
        b = even[2 * i + 1]
        pairs.append((a, b))
        used[a] = used[b] = True

    # Handle remaining even number
    remaining_even = even[2 * even_pairs:]
    if remaining_even:
        x = remaining_even[0]
        m = x
        while m % 2 == 0:
            m = m // 2
        if m > 1 and m <= n and not used[m]:
            pairs.append((x, m))
            used[x] = used[m] = True

    # Process primes >= 3
    for p in primes:
        if p < 3:
            continue
        multiples = []
        multiple = p
        while multiple <= n:
            if not used[multiple]:
                multiples.append(multiple)
            multiple += 2 * p  # Next odd multiple
        count = len(multiples)
        if count < 2:
            continue
        if count % 2 == 0:
            for i in range(0, count, 2):
                a = multiples[i]
                b = multiples[i + 1]
                pairs.append((a, b))
                used[a] = used[b] = True
        else:
            # Leave the first element (p) and pair the rest
            a = multiples[0]
            rest = multiples[1:]
            for i in range(0, len(rest), 2):
                if i + 1 < len(rest):
                    pairs.append((rest[i], rest[i + 1]))
                    used[rest[i]] = used[rest[i + 1]] = True

    print(len(pairs))
    for pair in pairs:
        print(pair[0], pair[1])

