    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and component_id[i][j] == -1:
                q = deque()
                q.append((i, j))
                component_id[i][j] = current_id
                size = 0
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    size += 1
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
