class SegmentTreeNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.min_val = 0
        self.max_val = 0
        self.count_min = 0
        self.count_max = 0
        self.lazy = 0

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.root = self.build(0, self.n - 1, data)

    def build(self, l, r, data):
        node = SegmentTreeNode(l, r)
        if l == r:
            node.min_val = data[l]
            node.max_val = data[l]
            node.count_min = 1
            node.count_max = 1
            return node
        mid = (l + r) // 2
        node.left = self.build(l, mid, data)
        node.right = self.build(mid + 1, r, data)
        self.push_up(node)
        return node

    def push_up(self, node):
        left = node.left
        right = node.right
        if left.min_val < right.min_val:
            node.min_val = left.min_val
            node.count_min = left.count_min
        elif left.min_val > right.min_val:
            node.min_val = right.min_val
            node.count_min = right.count_min
        else:
            node.min_val = left.min_val
            node.count_min = left.count_min + right.count_min

        if left.max_val > right.max_val:
            node.max_val = left.max_val
            node.count_max = left.count_max
        elif left.max_val < right.max_val:
            node.max_val = right.max_val
            node.count_max = right.count_max
        else:
            node.max_val = left.max_val
            node.count_max = left.count_max + right.count_max

    def apply(self, node, val):
        node.min_val += val
        node.max_val += val
        node.lazy += val

    def push_down(self, node):
        if node.lazy != 0 and node.left is not None:
            self.apply(node.left, node.lazy)
            self.apply(node.right, node.lazy)
            node.lazy = 0

    def range_add(self, l, r, val):
        self._range_add(self.root, l, r, val)

    def _range_add(self, node, l, r, val):
        if node.end < l or node.start > r:
            return
        if l <= node.start and node.end <= r:
            self.apply(node, val)
            return
        self.push_down(node)
        self._range_add(node.left, l, r, val)
        self._range_add(node.right, l, r, val)
        self.push_up(node)

    def query_min_max(self, l, r):
        return self._query_min_max(self.root, l, r)

    def _query_min_max(self, node, l, r):
        if node.end < l or node.start > r:
            return (float('inf'), 0, float('-inf'), 0)
        if l <= node.start and node.end <= r:
            return (node.min_val, node.count_min, node.max_val, node.count_max)
        self.push_down(node)
        left_min, left_cmin, left_max, left_cmax = self._query_min_max(node.left, l, r)
        right_min, right_cmin, right_max, right_cmax = self._query_min_max(node.right, l, r)
        min_val = min(left_min, right_min)
        if left_min < right_min:
            cmin = left_cmin
        elif left_min > right_min:
            cmin = right_cmin
        else:
            cmin = left_cmin + right_cmin

        max_val = max(left_max, right_max)
        if left_max > right_max:
            cmax = left_cmax
        elif left_max < right_max:
            cmax = right_cmax
        else:
            cmax = left_cmax + right_cmax
        return (min_val, cmin, max_val, cmax)

