def increment_binary_str(s):
    s_list = list(s)
    carry = 1
    i = len(s_list) - 1
    while i >= 0 and carry:
        if s_list[i] == '0':
            s_list[i] = '1'
            carry = 0
        else:
            s_list[i] = '0'
            carry = 1
        i -= 1
    if carry:
        return '1' + ''.join(s_list)
    else:
        return ''.join(s_list)

def next_magic_number(n_str):
    binary = n_str.replace('4', '0').replace('7', '1')
    incremented = increment_binary_str(binary)
    if len(incremented) > len(binary):
        return '4' * (len(n_str) + 1)
    else:
        return incremented.replace('0', '4').replace('1', '7')

