        result = [[0] * m for _ in range(m)]
        for i in range(m):
            for k in range(m):
                if A[i][k]:
                    for j in range(m):
                        result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(mat, power, mod):
        m = len(mat)
        result = [[0] * m for _ in range(m)]
        for i in range(m):
            result[i][i] = 1
        current = [row[:] for row in mat]
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, current, mod)
            current = multiply(current, current, mod)
            power //= 2
        return result

    T_power = matrix_power(T, n-1, MOD)
    total = 0
    for row in T_power:
