def indent_ruby_code(code):
    lines = code.split('\n')
    current_level = 0
    stack = []
    group_a = {'class', 'module', 'def', 'if', 'unless', 'case', 'for', 'while', 'until', 'begin', 'do'}
    group_b = {'elsif', 'else', 'when', 'rescue', 'ensure'}
    output = []
    for line in lines:
        stripped = line.lstrip()
        first_word = stripped.split(' ', 1)[0] if stripped else ''
        # Determine indent
        if stripped.startswith('end'):
            indent = ' ' * current_level
        elif first_word in group_a:
            indent = ' ' * current_level
        elif first_word in group_b:
            if stack:
                indent = ' ' * stack[-1]
            else:
                indent = ' ' * current_level
        else:
            indent = ' ' * current_level
        # Append the line
        output.append(indent + stripped)
        # Update current_level for next line
        if stripped.startswith('end'):
            if stack:
                current_level = stack.pop()
        elif first_word in group_a:
            stack.append(current_level)
            current_level += 1
        elif first_word in group_b:
            if stack:
                current_level = stack[-1] + 1
            else:
                current_level += 1
    return '\n'.join(output)

