import sys
from heapq import heappop, heappush

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = []
    penguin = None
    icebergs = []
    for i in range(H):
        line = sys.stdin.readline().strip()
        row = list(line)
        for j in range(W):
            if row[j] == 'P':
                penguin = (i, j)
                row[j] = '+'
            if row[j] == '#':
                icebergs.append((i, j))
        grid.append(row)
    px, py = penguin

    # Directions for vertical and horizontal
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    # Precompute the iceberg positions as a list and their indices
    ice_idx = {pos: idx for idx, pos in enumerate(icebergs)}
    total_ice = len(icebergs)

    # Use a priority queue (cost, smashed_icebergs_bitmask)
    heap = []
    heappush(heap, (0, 0))

    visited = set()

    while heap:
        cost, smashed = heappop(heap)
        if smashed in visited:
            continue
        visited.add(smashed)

        # Create the current grid
        current_grid = [row.copy() for row in grid]
        for idx in range(total_ice):
            if smashed & (1 << idx):
                i, j = icebergs[idx]
                current_grid[i][j] = '+'

        # Simulate collapse process
        present = [[True for _ in range(W)] for __ in range(H)]
        for i in range(H):
            for j in range(W):
                if current_grid[i][j] == '#':
                    present[i][j] = False  # Icebergs are present, but can't collapse

        # Find all thin ice cells
        q = []
        for i in range(H):
            for j in range(W):
                if current_grid[i][j] == '+':
                    # Check collapse condition
                    vertical_ok = False
                    if i-1 >=0 and present[i-1][j] and i+1 < H and present[i+1][j]:
                        vertical_ok = True
                    horizontal_ok = False
                    if j-1 >=0 and present[i][j-1] and j+1 < W and present[i][j+1]:
                        horizontal_ok = True
                    if not vertical_ok and not horizontal_ok:
                        q.append((i, j))
        # BFS to collapse
        collapsed = set()
        for (i,j) in q:
            collapsed.add((i,j))
            present[i][j] = False
        new_q = q.copy()
        while new_q:
            temp = []
            for (i,j) in new_q:
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < H and 0 <= nj < W and current_grid[ni][nj] == '+' and (ni, nj) not in collapsed:
                        # Check if it should collapse now
                        vertical_ok = False
                        if ni-1 >=0 and present[ni-1][nj] and ni+1 < H and present[ni+1][nj]:
                            vertical_ok = True
                        horizontal_ok = False
                        if nj-1 >=0 and present[ni][nj-1] and nj+1 < W and present[ni][nj+1]:
                            horizontal_ok = True
                        if not vertical_ok and not horizontal_ok:
                            collapsed.add((ni, nj))
                            present[ni][nj] = False
                            temp.append((ni, nj))
            new_q = temp
        # Check if penguin's cell is collapsed
        if not present[px][py]:
            print(cost)
            return

        # Generate next states by adding one more iceberg to smash
        for idx in range(total_ice):
            if not (smashed & (1 << idx)):
                new_smashed = smashed | (1 << idx)
                if new_smashed not in visited:
                    heappush(heap, (cost + 1, new_smashed))

    print(-1)

