def max_matching(adj, m, n):
    pair_u = [-1] * m
    pair_v = [-1] * n
    dist = [0] * m

    def bfs():
        queue = deque()
        for u in range(m):
            if pair_u[u] == -1:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        dist_null = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < dist_null:
                for v in adj[u]:
                    if pair_v[v] == -1:
                        dist_null = dist[u] + 1
                    elif dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        queue.append(pair_v[v])
        return dist_null != float('inf')

    def dfs(u):
        for v in adj[u]:
            if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = float('inf')
        return False

    result = 0
    while bfs():
        for u in range(m):
            if pair_u[u] == -1:
                if dfs(u):
                    result += 1
    return result

