    sum_d = 0
    degrees = [0]*V

    for _ in range(E):
        s = int(input[idx])
        idx +=1
        t = int(input[idx])
        idx +=1
        d = int(input[idx])
        idx +=1
        edges.append((s, t, d))
        sum_d +=d
        degrees[s] +=1
        degrees[t] +=1

    O = [i for i in range(V) if degrees[i] %2 !=0]

    if len(O) ==0:
        print(sum_d)
        return

    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF]*V for _ in range(V)]
    for i in range(V):
        dist[i][i] =0

    for s, t, d in edges:
        if dist[s][t] > d:
            dist[s][t] =d
        if dist[t][s] > d:
            dist[t][s] =d

    # Floyd-Warshall
    for k in range(V):
        for i in range(V):
            for j in range(V):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    k = len(O)
    memo = {}

    def dfs(mask):
        if mask in memo:
            return memo[mask]
        if mask == (1 <<k) -1:
            return 0
        res = float('inf')
        first = 0
        for i in range(k):
            if not (mask & (1 <<i)):
                first =i
                break
        for j in range(first +1, k):
            if not (mask & (1 <<j)):
                new_mask = mask | (1 <<first) | (1 <<j)
                cost = dist[O[first]][O[j]] + dfs(new_mask)
                if cost < res:
                    res = cost
        memo[mask] = res
        return res

    min_add = dfs(0)
    print(sum_d + min_add)

