import sys

def process_blocks(s):
    blocks = []
    count = 0
    for c in s:
        if c == '.':
            count += 1
        else:
            if count > 0:
                blocks.append(count)
            count = 0
    if count > 0:
        blocks.append(count)
    return blocks

