        blocks = process_blocks(s)
        has_a = any(l >= a for l in blocks)
        if not has_a:
            print("NO")
            continue
        found = False
        for l in blocks:
            if l < a:
                continue
            # Check if there exists i where i < b and (l -i -a) < b
            # i ranges from max(0, l -a -b +1) to min(b-1, l -a)
            low = max(0, l - a - b + 1)
            high = min(b - 1, l - a)
            if low <= high:
                found = True
                break
        if found:
            print("YES")
            continue
        # Check if any block >= 2a
        if any(l >= 2 * a for l in blocks):
            print("YES")
        else:
            print("NO")

