def main():
    n, d = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    # Filter the elements based on d's conditions
    filtered = []
    has_even = False
    has_five = False
    if d == 0:
        # Must have at least one even and one five
        required_even = False
        required_five = False
        for num in a:
            if num % 2 == 0:
                required_even = True
            if num % 5 == 0:
                required_five = True
            filtered.append(num)
        if not (required_even and required_five):
            print(-1)
            return
    elif d == 5:
        # Must have at least one five and no even numbers
        required_five = False
        for num in a:
            if num % 2 == 1:
                if num % 5 == 0:
                    required_five = True
                filtered.append(num)
        if not required_five:
            print(-1)
            return
    elif d in {1, 3, 7, 9}:
        # No even or five
        for num in a:
            if num % 2 != 0 and num % 5 != 0:
                filtered.append(num)
        if not filtered:
            print(-1)
            return
    else:  # d is 2,4,6,8
        # Must have at least one even and no five
        required_even = False
        for num in a:
            if num % 5 != 0:
                if num % 2 == 0:
                    required_even = True
                filtered.append(num)
        if not required_even:
            print(-1)
            return

    # Compute total product mod 10
    total_mod = 1
    for num in filtered:
        total_mod = (total_mod * (num % 10)) % 10

    if total_mod == d:
        print(len(filtered))
        print(' '.join(map(str, filtered)))
        return

    # Try to remove one element
    required_removed_mod = None
    if d == 0:
        required_removed_mod = (total_mod * 1) % 10  # Not applicable, but handle anyway
    else:
        # Find required_removed_mod such that (total_mod / removed_mod) %10 == d
        # Which is equivalent to (total_mod * inv(removed_mod)) %10 == d
        # So, removed_mod must be such that (total_mod * inv(removed_mod)) == d mod10
        # => inv(removed_mod) = (d * inv(total_mod)) mod10
        # => removed_mod = inv(d * inv(total_mod)) mod10
        # Which is inv(d) * total_mod mod10
        # But this requires d and total_mod to be invertible
        # So only when d and 10 are coprime
        inv_d = None
        if d in {1,3,7,9}:
            for i in range(1, 10):
                if (d * i) % 10 == 1:
                    inv_d = i
                    break
            if inv_d is None:
                print(-1)
                return
            required_removed_mod = (inv_d * total_mod) % 10
        else:
            # d is even, not 0. So, total_mod is even, but not 0
            # We need to find removed_mod such that (total_mod / removed_mod) %10 ==d
            # But division is not possible in mod 10 for even d
            # So, this approach doesn't work
            # Instead, try to find any element whose removal changes the mod to d
            # Brute force for each element
            best = None
            for i, num in enumerate(filtered):
                num_mod = num % 10
                new_mod = (total_mod * pow(num_mod, -1, 10)) % 10
                if new_mod == d:
                    if best is None or num < best[0]:
                        best = (num, i)
            if best:
                k = best[1]
                filtered.pop(k)
                if filtered:
                    print(len(filtered))
                    print(' '.join(map(str, filtered)))
                else:
                    print(-1)
                return
            else:
                print(-1)
                return

    # For d in {1,3,7,9}
    # Now, required_removed_mod is (inv_d * total_mod) %10
    best = None
    for i, num in enumerate(filtered):
        num_mod = num % 10
        if num_mod == required_removed_mod:
            if best is None or num < best[0]:
                best = (num, i)

    if best is not None:
        filtered.pop(best[1])
        if filtered:
            print(len(filtered))
            print(' '.join(map(str, filtered)))
        else:
            print(-1)
        return
    else:
        print(-1)

