class Node:
    __slots__ = ['goto', 'failure', 'output']
    def __init__(self):
        self.goto = {}
        self.failure = None
        self.output = []

def build_aho_corasick(surnames):
    root = Node()
    for idx, s in enumerate(surnames):
        current = root
        for c in s:
            if c not in current.goto:
                current.goto[c] = Node()
            current = current.goto[c]
        current.output.append(idx)

    from collections import deque
    queue = deque()
    root.failure = None
    for child in root.goto.values():
        child.failure = root
        queue.append(child)

    while queue:
        current_node = queue.popleft()
        for c, child in current_node.goto.items():
            fail_node = current_node.failure
            while fail_node is not None and c not in fail_node.goto:
                fail_node = fail_node.failure
            child.failure = fail_node.goto[c] if fail_node and c in fail_node.goto else root
            child.output += child.failure.output
            queue.append(child)
    return root

