def multiply(a, b):
    res = [[0]*3 for _ in range(3)]
    for i in range(3):
        for j in range(3):
            res[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j] + a[i][2] * b[2][j]) % MOD
    return res

def matrix_pow(mat, power):
    result = [[1 if i == j else 0 for j in range(3)] for i in range(3)]
    while power > 0:
        if power % 2 == 1:
            result = multiply(result, mat)
        mat = multiply(mat, mat)
        power //= 2
    return result

def compute_S(n):
    if n == 1:
        return 2 % MOD
    elif n == 2:
        return 14 % MOD
    elif n == 3:
        return 46 % MOD
    else:
        T = [
            [3, 2, -4],
            [1, 0, 0],
            [0, 1, 0]
        ]
        for i in range(3):
            for j in range(3):
                T[i][j] %= MOD
        power = n - 3
        mat_pow = matrix_pow(T, power)
        s3, s2, s1 = 46 % MOD, 14 % MOD, 2 % MOD
        new_s = (mat_pow[0][0] * s3 + mat_pow[0][1] * s2 + mat_pow[0][2] * s1) % MOD
        return new_s

