import sys
from collections import deque

class Node:
    def __init__(self, value):
        self.value = value
        self.parent = None
        self.children = []
        self.dead = False

    def add_child(self, child):
        self.children.append(child)
        child.parent = self

    def __repr__(self):
        return f"Node({self.value}, {'dead' if self.dead else 'alive'})"

def compute_next(n):
    temp = 3 * n + 1
    while temp % 2 == 0:
        temp //= 2
    if temp > 12345678:
        temp -= 12345678
    return temp

def get_alive_nodes(root):
    alive = []
    visited = set()
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node.dead or id(node) in visited:
            continue
        visited.add(id(node))
        if not node.dead:
            alive.append(node)
            for child in node.children:
                queue.append(child)
    return alive

def process_seed(initial_value):
    root = Node(initial_value)
    lifetime = 0
    max_cells = 1
    current_clock = 0

    while True:
        alive_nodes = get_alive_nodes(root)
        if not alive_nodes:
            break

        next_n_map = {}
        for node in alive_nodes:
            next_n_map[node] = compute_next(node.value)

        candidate_leaves = []
        for node in alive_nodes:
            if not node.children:
                if next_n_map[node] > node.value:
                    candidate_leaves.append(node)

        original_nodes = []
        queue = deque([root])
        visited = set()
        while queue:
            node = queue.popleft()
            if node.dead or id(node) in visited:
                continue
            visited.add(id(node))
            original_nodes.append(node)
            for child in node.children:
                queue.append(child)

        numoeba_died = False
        original_root = root
        for node in original_nodes:
            if node.dead:
                continue
            if next_n_map.get(node, 0) != 1:
                continue
            node.dead = True
            if node is original_root:
                current_alive = len(get_alive_nodes(root))
                max_cells = max(max_cells, current_alive)
                return (current_clock + 1, max_cells)
            parent = node.parent
            if parent is None:
                continue
            if node in parent.children:
                parent.children.remove(node)
            alive_children = [child for child in node.children if not child.dead]
            if len(alive_children) == 1:
                parent.add_child(alive_children[0])
            else:
                queue_mark = deque([node])
                while queue_mark:
                    current = queue_mark.popleft()
                    if current.dead:
                        continue
                    current.dead = True
                    for child in current.children:
                        queue_mark.append(child)

        if root.dead:
            current_alive = len(get_alive_nodes(root))
            max_cells = max(max_cells, current_alive)
            return (current_clock + 1, max_cells)

        for candidate in candidate_leaves:
            if not candidate.dead and next_n_map[candidate] != 1:
                n_val = next_n_map[candidate]
                target = (n_val + 1) // 2
                new_value = target + 1 if target % 2 == 0 else target
                bonus = Node(new_value)
                candidate.add_child(bonus)

        alive_nodes = get_alive_nodes(root)
        if not alive_nodes:
            break

        max_val = max(node.value for node in alive_nodes)
        max_nodes = [node for node in alive_nodes if node.value == max_val]
        if len(max_nodes) == 1:
            new_leader = max_nodes[0]
            path = []
            current = new_leader
            while current is not None:
                path.append(current)
                current = current.parent
            path = path[::-1]
            for i in range(len(path) - 1):
                parent = path[i]
                child = path[i+1]
                if child in parent.children:
                    parent.children.remove(child)
                parent.parent = child
                child.children.append(parent)
            new_leader.parent = None
            root = new_leader
            m = new_leader.value
            lb_val = (m + 1) // 2
            if lb_val % 2 == 0:
                lb_val -= 1
            lb_val = max(lb_val, 1)
            leader_bonus = Node(lb_val)
            new_leader.add_child(leader_bonus)

        current_alive = len(get_alive_nodes(root))
        if current_alive == 0:
            break
        max_cells = max(max_cells, current_alive)
        current_clock += 1
        if current_clock >= 500:
            break

    return (lifetime, max_cells)

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    k = int(line)
    if k == 0:
        break
    lifetime, max_cells = process_seed(k)
    print(f"{lifetime} {max_cells}")

