import sys
from sys import stdin
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    edges = set()
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)
        edges.add(frozenset((a, b)))

    # Tarjan's algorithm to find bridges iteratively
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    time = 0
    bridges = set()
    stack = []
    parent = [-1] * (n + 1)
    for start in range(1, n + 1):
        if disc[start] == -1:
            stack.append((start, -1, False))
            while stack:
                node, prev, visited = stack.pop()
                if not visited:
                    if disc[node] != -1:
                        continue
                    disc[node] = low[node] = time
                    time += 1
                    stack.append((node, prev, True))
                    # Process children
                    for neighbor in adj[node]:
                        if neighbor == prev:
                            continue
                        if disc[neighbor] == -1:
                            parent[neighbor] = node
                            stack.append((neighbor, node, False))
                        else:
                            # Back edge
                            low[node] = min(low[node], disc[neighbor])
                else:
                    for neighbor in adj[node]:
                        if neighbor == prev:
                            continue
                        if disc[neighbor] > disc[node]:  # Child in DFS tree
                            low[node] = min(low[node], low[neighbor])
                            if low[neighbor] > disc[node]:
                                bridges.add(frozenset((node, neighbor)))
                    if prev != -1:
                        low[prev] = min(low[prev], low[node])

    # Assign components
    comp = [-1] * (n + 1)
    current_comp = 0
    for u in range(1, n + 1):
        if comp[u] == -1:
            q = deque()
            q.append(u)
            comp[u] = current_comp
            while q:
                node = q.popleft()
                for neighbor in adj[node]:
                    edge = frozenset((node, neighbor))
                    if edge not in bridges:
                        if comp[neighbor] == -1:
                            comp[neighbor] = current_comp
                            q.append(neighbor)
            current_comp += 1

    # Build bridge tree
    bridge_tree_adj = [[] for _ in range(current_comp)]
    for bridge in bridges:
        u, v = bridge
        c1 = comp[u]
        c2 = comp[v]
        bridge_tree_adj[c1].append(c2)
        bridge_tree_adj[c2].append(c1)

    # Compute depth and parent for LCA
    LOG = 20
    depth = [0] * current_comp
    parent_comp = [-1] * current_comp
    # BFS to set parent and depth
    q = deque()
    if current_comp > 0:
        q.append(0)
        parent_comp[0] = -1
        depth[0] = 0
        while q:
            u = q.popleft()
            for v in bridge_tree_adj[u]:
                if v != parent_comp[u] and depth[v] == 0 and v != 0:
                    depth[v] = depth[u] + 1
                    parent_comp[v] = u
                    q.append(v)

    # Precompute binary lifting table
    up = [[-1] * current_comp for _ in range(LOG)]
    up[0] = parent_comp
    for k in range(1, LOG):
        for i in range(current_comp):
            if up[k-1][i] != -1:
                up[k][i] = up[k-1][up[k-1][i]]

    # LCA function
    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # Bring u to the depth of v
        for k in reversed(range(LOG)):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in reversed(range(LOG)):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # Distance function
    def distance(u, v):
        ancestor = lca(u, v)
        return depth[u] + depth[v] - 2 * depth[ancestor]

    # Process queries
    k = int(stdin.readline())
    for _ in range(k):
        s, l = map(int, stdin.readline().split())
        cs = comp[s]
        cl = comp[l]
        if cs == cl:
            print(0)
        else:
            print(distance(cs, cl))

