    sets = []
    for _ in range(m):
        parts = list(map(int, sys.stdin.readline().split()))
        si = parts[0]
        elements = sorted(parts[1:])
        intervals = []
        if not elements:
            sets.append(intervals)
            continue
        current_start = elements[0]
        current_end = elements[0]
        for e in elements[1:]:
            if e == current_end + 1:
                current_end = e
            else:
                intervals.append((current_start, current_end))
                current_start = current_end = e
        intervals.append((current_start, current_end))
        sets.append(intervals)

    min_k = float('inf')
    # Iterate over all possible subsets
    for mask in range(1, 1 << m):
        selected = []
        for i in range(m):
            if mask & (1 << i):
                selected.extend(sets[i])
        if not selected:
            continue
        # Sort intervals by start
        selected.sort()
        first_start = selected[0][0]
        if first_start > d:
            continue
        last_end = selected[-1][1]
        if last_end < (n - d + 1):
            continue
        max_gap = 0
        prev_end = selected[0][1]
        for interval in selected[1:]:
            current_start = interval[0]
            gap = current_start - prev_end
            if gap > max_gap:
                max_gap = gap
            prev_end = interval[1]
        if max_gap > d:
            continue
        # Valid subset, update min_k
        k = bin(mask).count('1')
        if k < min_k:
            min_k = k
    print(min_k)

