import sys
from collections import deque

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    r = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n)]
    in_edges = [[] for _ in range(n)]
    for _ in range(m):
        xi, yi = map(int, sys.stdin.readline().split())
        xi -= 1
        yi -= 1
        adj[xi].append(yi)
        in_edges[yi].append(xi)

    # Check for existing fixed ranks that violate edges
    for u in range(n):
        if r[u] == 0:
            continue
        for v in adj[u]:
            if r[v] != 0 and r[u] <= r[v]:
                print(-1)
                return

    # Check for cycles using Kahn's algorithm
    in_degree = [0] * n
    for u in range(n):
        for v in adj[u]:
            in_degree[v] += 1
    q = deque()
    for u in range(n):
        if in_degree[u] == 0:
            q.append(u)
    top_order = []
    while q:
        u = q.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)
    if len(top_order) != n:
        print(-1)
        return

    # Compute min_rank in reverse topological order
    min_rank = [1] * n
    reverse_top_order = reversed(top_order)
    for u in reverse_top_order:
        current_max = 0
        for v in adj[u]:
            current_max = max(current_max, min_rank[v])
        if adj[u]:
            min_rank[u] = current_max + 1
        if r[u] != 0:
            if r[u] < min_rank[u]:
                print(-1)
                return
            min_rank[u] = r[u]

    # Compute max_rank in topological order
    max_rank = [k] * n
    for u in top_order:
        current_min = k
        for w in in_edges[u]:
            current_min = min(current_min, max_rank[w] - 1)
        if in_edges[u]:
            max_rank[u] = current_min
        if r[u] != 0:
            if r[u] > max_rank[u]:
                print(-1)
                return
            max_rank[u] = r[u]

    # Check if all ranks 1..k are covered by some node's [min, max]
    intervals = []
    for u in range(n):
        intervals.append((min_rank[u], max_rank[u]))
    intervals.sort()
    merged = []
    if not intervals:
        print(-1)
        return
    current_start, current_end = intervals[0]
    for s, e in intervals[1:]:
        if s <= current_end + 1:
            current_end = max(current_end, e)
        else:
            merged.append((current_start, current_end))
            current_start, current_end = s, e
    merged.append((current_start, current_end))
    prev_end = 0
    coverage = False
    for s, e in merged:
        if s > prev_end + 1:
            break
        prev_end = max(prev_end, e)
    else:
        if prev_end >= k and merged[0][0] <= 1:
            coverage = True
    if not coverage:
        print(-1)
        return

    # Assign initial ranks (min_rank for unassigned)
    current_r = [0] * n
    fixed = set()
    for u in range(n):
        if r[u] != 0:
            current_r[u] = r[u]
            fixed.add(u)
        else:
            current_r[u] = min_rank[u]

    # Check initial coverage
    present = set(current_r)
    missing = []
    for i in range(1, k+1):
        if i not in present:
            missing.append(i)
    if not missing:
        print(' '.join(map(str, current_r)))
        return

    # Collect unassigned nodes (those that were 0 and not fixed)
    unassigned = []
    for u in range(n):
        if r[u] == 0:
            unassigned.append(u)
    # Sort unassigned by max_rank descending
    unassigned.sort(key=lambda u: (-max_rank[u], -min_rank[u]))

    # Process missing ranks in descending order
    missing_sorted = sorted(missing, reverse=True)
    assigned = set()
    for r_val in missing_sorted:
        found = False
        for i in range(len(unassigned)):
            u = unassigned[i]
            if min_rank[u] <= r_val <= max_rank[u]:
                current_r[u] = r_val
                assigned.add(u)
                del unassigned[i]
                found = True
                break
        if not found:
            print(-1)
            return

    # Assign remaining unassigned to min_rank
    for u in unassigned:
        current_r[u] = min_rank[u]

    # Final check
    final_present = set(current_r)
    for i in range(1, k+1):
        if i not in final_present:
            print(-1)
            return
    print(' '.join(map(str, current_r)))

