def compute(x):
    total = 0
    for mask in range(1, 1 << n):
        bits = bin(mask).count('1')
        product = 1
        for i in range(n):
            if mask & (1 << i):
                p = primes[i]
                if product > x // p:
                    product = -1
                    break
                product *= p
        if product == -1 or product > x:
            continue
        cnt = x // product
        if bits % 2 == 1:
            total += cnt
        else:
            total -= cnt
    return total

