import sys
from collections import deque

def main():
    N, M, P = map(int, sys.stdin.readline().split())
    edges = []
    reversed_adj = [[] for _ in range(N+1)]
    for _ in range(M):
        A, B, C = map(int, sys.stdin.readline().split())
        edges.append((A, B, C - P))
        reversed_adj[B].append(A)

    # Determine nodes reachable to N
    R = [False] * (N + 1)
    q = deque()
    q.append(N)
    R[N] = True
    while q:
        u = q.popleft()
        for v in reversed_adj[u]:
            if not R[v]:
                R[v] = True
                q.append(v)

    # Bellman-Ford algorithm
    INF = float('-inf')
    dist = [INF] * (N + 1)
    dist[1] = 0
    for i in range(N - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[v] < dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break

    # Check for positive cycles affecting the result
    has_cycle = False
    for u, v, w in edges:
        if dist[u] != INF and dist[v] < dist[u] + w and R[v]:
            has_cycle = True
            break

    if has_cycle:
        print(-1)
    else:
        print(max(dist[N], 0))

