from collections import deque

directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def main():
    H, W, N = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        grid.append(sys.stdin.readline().strip())

    snake_pos = {}
    food_pos = {}
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                snake_pos['head'] = (i, j)
            elif c in {'a', 'b', 'c', 'd', 'e'}:
                snake_pos[c] = (i, j)
            elif c.isdigit():
                num = int(c)
                if 1 <= num <= N:
                    food_pos[num] = (i, j)

    body = [snake_pos['head']]
    for seg in ['a', 'b', 'c', 'd', 'e']:
        body.append(snake_pos[seg])
    current_body = tuple(body)

    targets = [food_pos[i] for i in range(1, N+1)]
    total_steps = 0

    for target in targets:
        visited = set()
        queue = deque()
        queue.append((current_body, 0))
        visited.add(current_body)
        found = False
        while queue:
            body, steps = queue.popleft()
            head = body[0]
            if head == target:
                current_body = body
                total_steps += steps
                found = True
                break
            for dr, dc in directions:
                new_r = head[0] + dr
                new_c = head[1] + dc
                if 0 <= new_r < H and 0 <= new_c < W:
                    if grid[new_r][new_c] == '#':
                        continue
                    new_head = (new_r, new_c)
                    if new_head in body:
                        continue
                    new_body = (new_head,) + body[:-1]
                    if new_body not in visited:
                        visited.add(new_body)
                        queue.append((new_body, steps + 1))
        if not found:
            print(-1)
            return
    print(total_steps)

