def fib_mod(n, mod):
    if n == 0:
        return 0
    a, b = 0, 1
    for bit in bin(n)[3:]:
        c = (a * (2 * b - a)) % mod
        d = (a*a + b*b) % mod
        if bit == '1':
            a, b = d, (c + d) % mod
        else:
            a, b = c, d
    return b

