import itertools

def is_square(points):
    dists = []
    for i in range(4):
        x1, y1 = points[i]
        for j in range(i + 1, 4):
            x2, y2 = points[j]
            dx = x1 - x2
            dy = y1 - y2
            dists.append(dx * dx + dy * dy)
    dists.sort()
    unique = sorted(set(dists))
    if len(unique) != 2:
        return False
    d1, d2 = unique
    if d2 != 2 * d1:
        return False
    if dists.count(d1) == 4 and dists.count(d2) == 2:
        return True
    return False

def is_rectangle(points):
    if is_square(points):
        return True
    dists = []
    for i in range(4):
        x1, y1 = points[i]
        for j in range(i + 1, 4):
            x2, y2 = points[j]
            dx = x1 - x2
            dy = y1 - y2
            dists.append(dx * dx + dy * dy)
    dists.sort()
    unique = sorted(set(dists))
    if len(unique) != 3:
        return False
    x, y, z = unique
    if z != x + y:
        return False
    if dists.count(x) == 2 and dists.count(y) == 2 and dists.count(z) == 2:
        return True
    return False

