MOD = 10**9 + 7

def is_rotation(start, end):
    return len(start) == len(end) and end in (start + start)

def find_min_rotation(start, end):
    L = len(start)
    concatenated = start + start
    for s in range(L):
        if concatenated[s:s+L] == end:
            return s
    return -1

def minimal_period(s):
    n = len(s)
    for d in range(1, n+1):
        if n % d != 0:
            continue
        valid = True
        for i in range(n):
            if s[i] != s[i % d]:
                valid = False
                break
        if valid:
            return d
    return n  # Fallback, though the loop should find d <= n

def compute_c(L, d):
    c = [0] * d
    for s in range(1, L):
        t = s % d
        c[t] += 1
    return c

def multiply(p, q, d, mod):
    res = [0] * d
    for i in range(d):
        for j in range(d):
            res[(i + j) % d] = (res[(i + j) % d] + p[i] * q[j]) % mod
    return res

def polynomial_pow(p, exponent, d, mod):
    result = [0] * d
    result[0] = 1  # Identity element (x^0)
    while exponent > 0:
        if exponent % 2 == 1:
            result = multiply(result, p, d, mod)
        p = multiply(p, p, d, mod)
        exponent //= 2
    return result

