C = [[0]*(max_k+1) for _ in range(max_k+1)]
for i in range(max_k+1):
    C[i][0] = 1
    C[i][i] = 1
    for j in range(1, i):
        C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

# Precompute powers of 2
pow2 = [1]*(max_k +1)
for i in range(1, max_k+1):
    pow2[i] = (pow2[i-1] * 2) % MOD

size = 2 * max_k + 3

# Initialize transition matrix
matrix = [[0]*size for _ in range(size)]

for t in range(max_k + 1):
    # Handle a'_t = sum C(t, s) a_s + sum C(t, r) 2^{t-r} b_r
    for s in range(t + 1):
        matrix[t][s] = (matrix[t][s] + C[t][s]) % MOD
    for r in range(t + 1):
        matrix[t][(max_k + 1) + r] = (matrix[t][(max_k + 1) + r] + C[t][r] * pow2[t - r]) % MOD

for t in range(max_k + 1):
    # Handle b'_t = a_t (previous state's a_t)
    matrix[(max_k + 1) + t][t] = 1

# Handle S' = S_prev + sum C(k, s) a_s + sum C(k, r) 2^{k-r} b_r
row_S = 2 * max_k + 2
for s in range(max_k + 1):
    matrix[row_S][s] = (matrix[row_S][s] + C[k][s]) % MOD
for r in range(max_k + 1):
    matrix[row_S][(max_k + 1) + r] = (matrix[row_S][(max_k + 1) + r] + C[k][r] * pow2[k - r]) % MOD
matrix[row_S][row_S] = (matrix[row_S][row_S] + 1) % MOD

# Matrix exponentiation functions
def multiply(A, B):
    result = [[0]*len(B[0]) for _ in range(len(A))]
    for i in range(len(A)):
        for k_ind in range(len(B)):
            if A[i][k_ind]:
                for j in range(len(B[0])):
                    result[i][j] = (result[i][j] + A[i][k_ind] * B[k_ind][j]) % MOD
    return result

def matrix_power(mat, power):
    result = [[0]*len(mat) for _ in range(len(mat))]
    for i in range(len(mat)):
        result[i][i] = 1
    while power > 0:
        if power % 2 == 1:
            result = multiply(result, mat)
        mat = multiply(mat, mat)
        power //= 2
    return result

