from collections import defaultdict

def main():
    import sys
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split(',')
    stack = []
    depth_map = defaultdict(list)

    for i in range(0, len(tokens), 2):
        text = tokens[i]
        child_count = int(tokens[i+1])
        if not stack:
            depth = 1
        else:
            parent_node, remaining = stack[-1]
            depth = parent_node.depth + 1
        new_node = Node(text, depth)
        depth_map[depth].append(text)

        if stack:
            parent_node.children.append(new_node)
            remaining -= 1
            if remaining == 0:
                stack.pop()
            else:
                stack[-1] = (parent_node, remaining)

        if child_count > 0:
            stack.append((new_node, child_count))

    max_depth = max(depth_map.keys()) if depth_map else 0
    print(max_depth)
