import math

def build_sparse_table(arr):
    n = len(arr)
    log_table = [0] * (n + 1)
    for i in range(2, n + 1):
        log_table[i] = log_table[i // 2] + 1
    k = log_table[n] if n > 0 else 0
    st = [[0] * n for _ in range(k + 1)]
    st[0] = arr.copy()
    for j in range(1, k + 1):
        for i in range(n - (1 << j) + 1):
            st[j][i] = max(st[j-1][i], st[j-1][i + (1 << (j-1))])
    return st, log_table

def query_sparse_table(st, log_table, l, r):
    if l > r:
        return -float('inf')
    length = r - l + 1
    k = log_table[length]
    return max(st[k][l], st[k][r - (1 << k) + 1])

def main():
    n, *rest = map(int, sys.stdin.read().split())
    a = rest[:n]
    if n == 0:
        print()
        return
    pair_max = [max(a[i], a[i+1]) for i in range(n-1)] if n > 1 else []

    # Build sparse tables
    a_st, a_log = build_sparse_table(a)
    if len(pair_max) > 0:
        pair_st, pair_log = build_sparse_table(pair_max)
    else:
        pair_st, pair_log = None, None

    ans = [0] * n
    for m in range(1, n+1):
        if m % 2 == 1:
            p = (m - 1) // 2
            l = p
            r = (n-1) - p
            if l > r:
                max_val = 0
            else:
                max_val = query_sparse_table(a_st, a_log, l, r)
        else:
            p = m // 2
            l = p - 1
            r = (n-1) - p
            if l < 0 or (len(pair_max) == 0) or r >= len(pair_max) or l > r:
                max_val = 0
            else:
                max_val = query_sparse_table(pair_st, pair_log, l, r)
        ans_idx = n - m
        ans[ans_idx] = max_val

    print(' '.join(map(str, ans)))

