                    for idx_next, (x, d) in enumerate(stones[1]):
                        new_line = 1
                        new_risk = risk
                        new_state = (new_line, idx_next, skips)
                        if new_state not in distance or new_risk < distance.get(new_state, float('inf')):
                            distance[new_state] = new_risk
                            heapq.heappush(heap, (new_risk, new_line, idx_next, skips))
                if m >= 1 and 2 <= n:
                    for idx_next, (x, d) in enumerate(stones[2]):
