import heapq

def compute_counts(start, adj, n):
    dist = [float('inf')] * n
    dist[start] = 0
    heap = []
    heapq.heappush(heap, (0, start))

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > current_dist + w:
                dist[v] = current_dist + w
                heapq.heappush(heap, (dist[v], v))

    count = [0] * n
    count[start] = 1
    nodes = sorted([(dist[u], u) for u in range(n)], key=lambda x: x[0])

    for d, u in nodes:
        if d == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] == d + w:
                count[v] += count[u]

    return dist, count

def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0

    while True:
        n = int(input[ptr])
        m = int(input[ptr+1])
        p = int(input[ptr+2])
        ptr += 3

        if n == 0 and m == 0 and p == 0:
            break

        adj = [[] for _ in range(n)]
        for _ in range(m):
            u = int(input[ptr])
            v = int(input[ptr+1])
            w = int(input[ptr+2])
            adj[u].append((v, w))
            adj[v].append((u, w))
            ptr += 3

        c_list = []
        for _ in range(p):
            c_list.append(int(input[ptr]))
            ptr += 1

        forward_dist, forward_count = compute_counts(0, adj, n)
        backward_dist, backward_count = compute_counts(n-1, adj, n)
        D = forward_dist[n-1]

        probs = []
        for c in c_list:
            if D == float('inf'):
                probs.append(0.0)
                continue
            if forward_dist[c] + backward_dist[c] != D:
                probs.append(0.0)
            else:
                total = forward_count[n-1]
                if total == 0:
                    probs.append(0.0)
                else:
                    prob = (forward_count[c] * backward_count[c]) / total
                    probs.append(prob)

        for prob in probs:
            print("{0:.8f}".format(prob))
        print()

