import math

def process_test_case(p, n):
    sqrt_p = math.sqrt(p)
    lower_candidates = []
    upper_candidates = []

    for y in range(1, n + 1):
        y_sqrtp = y * sqrt_p
        lower_x = int(math.floor(y_sqrtp))

        # Check and add lower candidate
        if 1 <= lower_x <= n:
            if math.gcd(lower_x, y) == 1:
                lower_candidates.append((lower_x, y))

        # Check and add upper candidate
        upper_x = lower_x + 1
        if upper_x <= n:
            if math.gcd(upper_x, y) == 1:
                upper_candidates.append((upper_x, y))

    # Find maximum lower candidate
    max_lower_num, max_lower_den = 0, 1
    for a, b in lower_candidates:
        if a * max_lower_den > max_lower_num * b:
            max_lower_num, max_lower_den = a, b

    # Find minimum upper candidate
    min_upper_num, min_upper_den = (n + 1), 1
    for c, d in upper_candidates:
        if c * min_upper_den < min_upper_num * d:
            min_upper_num, min_upper_den = c, d

    return f"{min_upper_num}/{min_upper_den} {max_lower_num}/{max_lower_den}"

