import sys

def generate_valid_splits(num_str):
    n = len(num_str)
    valid_splits = []
    for mask in range(0, 1 << (n-1)):
        split_points = []
        for i in range(n-1):
            if (mask >> i) & 1:
                split_points.append(i+1)
        split_points.sort()
        parts = []
        prev = 0
        for point in split_points:
            parts.append(num_str[prev:point])
            prev = point
        parts.append(num_str[prev:])
        valid = True
        for part in parts:
            if len(part) > 1 and part[0] == '0':
                valid = False
                break
        if valid:
            valid_splits.append(parts)
    return valid_splits

