        sum_parts = sum(int(p) for p in parts)
        sums.append(sum_parts)
    filtered = []
    for s, parts in zip(sums, valid_splits):
        if s <= target_num:
            filtered.append((s, parts))
    if not filtered:
        return "error"
    max_sum = max(s for s, _ in filtered)
    candidates = [(s, parts) for s, parts in filtered if s == max_sum]
    if len(candidates) > 1:
        return "rejected"
    else:
        s, parts = candidates[0]
        return f"{s} {' '.join(parts)}"

