        block_grid = [sys.stdin.readline().strip() for _ in range(h_block)]
        # Read board
        h_board, w_board = map(int, sys.stdin.readline().split())
        board_grid = [sys.stdin.readline().strip() for _ in range(h_board)]
        original_board_counts = [row.count('#') for row in board_grid]

        # Generate block coordinates
        block_coords = []
        for y in range(h_block):
            for x in range(w_block):
                if block_grid[y][x] == '#':
                    block_coords.append((y, x))

        # Generate all unique rotated shapes
        def rotate_coords(coords, h_orig, w_orig, rotation_step):
            rotated = []
            for y, x in coords:
                if rotation_step == 0:
                    ny, nx = y, x
                elif rotation_step == 1:
                    ny, nx = x, h_orig - 1 - y
                elif rotation_step == 2:
                    ny, nx = h_orig - 1 - y, w_orig - 1 - x
                else:
                    ny, nx = w_orig - 1 - x, y
                rotated.append((ny, nx))
            min_y = min(y for y, x in rotated) if rotated else 0
            min_x = min(x for y, x in rotated) if rotated else 0
            shifted = [(y - min_y, x - min_x) for y, x in rotated]
            return shifted

        unique_shapes = set()
        for step in range(4):
            rotated = rotate_coords(block_coords, h_block, w_block, step)
            shape = frozenset(rotated)
            unique_shapes.add(shape)

        max_score = -1
        for shape in unique_shapes:
            if not shape:
                continue
            shape_list = list(shape)
            h_shape = max(dy for dy, dx in shape_list) + 1
            w_shape = max(dx for dy, dx in shape_list) + 1
            if h_shape > h_board or w_shape > w_board:
                continue
            for y_pos in range(h_board - h_shape + 1):
                for x_pos in range(w_board - w_shape + 1):
                    valid = True
                    for dy, dx in shape_list:
                        by = y_pos + dy
                        bx = x_pos + dx
                        if board_grid[by][bx] != '.':
                            valid = False
                            break
                    if not valid:
                        continue
                    added = defaultdict(int)
                    for dy, dx in shape_list:
                        by = y_pos + dy
                        added[by] += 1
                    current_score = 0
                    for row in range(h_board):
                        total = original_board_counts[row] + added.get(row, 0)
                        if total == w_board:
                            current_score += 1
                    if current_score > max_score:
                        max_score = current_score
        print(max_score if max_score != -1 else -1)

