import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    grid = [sys.stdin.readline().strip() for _ in range(N)]

    required_rows = set()
    required_cols = set()

    for i in range(1, N+1):
        for j in range(1, N+1):
            if grid[i-1][j-1] == 'x':
                if i % 2 == 0 and j % 2 == 1:
                    required_rows.add(i)
                elif i % 2 == 1 and j % 2 == 0:
                    required_cols.add(j)

    r = len(required_rows)
    c = len(required_cols)
    base = max(r, c)

    even_rows = [i for i in range(2, N+1, 2) if i not in required_rows]
    even_cols = [j for j in range(2, N+1, 2) if j not in required_cols]

    graph = defaultdict(list)
    for i in even_rows:
        for j in even_cols:
            if grid[i-1][j-1] == 'x':
                graph[i].append(j)

    row_to_id = {row: idx for idx, row in enumerate(even_rows)}
    col_to_id = {col: idx for idx, col in enumerate(even_cols)}

    adj = [[] for _ in range(len(even_rows))]
    for i in even_rows:
        row_idx = row_to_id[i]
        for j in graph[i]:
            col_idx = col_to_id[j]
            adj[row_idx].append(col_idx)

    def max_matching(adj, n_left, n_right):
        match_to = [-1] * n_right
        result = 0
        for u in range(n_left):
            seen = [False] * n_right
            if dfs(u, adj, seen, match_to):
                result += 1
        return result

    def dfs(u, adj, seen, match_to):
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                if match_to[v] == -1 or dfs(match_to[v], adj, seen, match_to):
                    match_to[v] = u
                    return True
        return False

    matching_size = max_matching(adj, len(even_rows), len(even_cols))
    total = base + matching_size
    print(total)

