def can_form(s, a_start, a_end, b_start, b_end):
    m = a_end - a_start
    n = b_end - b_start
    if m != n + 1:
        return False
    i = a_start
    j = b_start
    deletions = 0
    while i < a_end and j < b_end:
        if s[i] == s[j]:
            i += 1
            j += 1
        else:
            deletions += 1
            if deletions > 1:
                return False
            i += 1
    total_deletions = deletions + (a_end - i)
    return j == b_end and total_deletions == 1

