for current_a in a:
    threshold = m - current_a
    k = bisect.bisect_left(a, threshold)

    intervals = []

    if k > 0:
        start1 = current_a + a[0]
        end1 = current_a + a[k - 1]
        if start1 <= end1:
            intervals.append((start1, end1))

    if k < n:
        start2 = current_a + a[k] - m
        end2 = current_a + a[-1] - m
        if start2 <= end2:
            intervals.append((start2, end2))

    new_forbidden = []
    for (s, e) in forbidden:
        for (new_s, new_e) in intervals:
            overlap_s = max(s, new_s)
            overlap_e = min(e, new_e)
            if overlap_s <= overlap_e:
                new_forbidden.append((overlap_s, overlap_e))

    if not new_forbidden:
        forbidden = []
        break

    new_forbidden.sort()
    merged = []
    for s, e in new_forbidden:
        if not merged:
            merged.append([s, e])
        else:
            last_s, last_e = merged[-1]
            if s > last_e + 1:
                merged.append([s, e])
            else:
                merged[-1][1] = max(last_e, e)

    forbidden = [(s, e) for s, e in merged]

    if not forbidden:
        break

