from collections import deque

def is_bipartite(adj, excluded_edge, n):
    color = [-1] * (n + 1)
    for i in range(1, n + 1):
        if color[i] == -1:
            queue = deque()
            queue.append(i)
            color[i] = 0
            while queue:
                u = queue.popleft()
                for v, idx in adj[u]:
                    if idx == excluded_edge:
                        continue
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

