MOD = 10**9 + 7

def get_order(k, p):
    n = p - 1
    factors = {}
    temp = n
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        factors[temp] = 1

    divisors = [1]
    for prime, exp in factors.items():
        current_length = len(divisors)
        new_divisors = []
        for e in range(1, exp + 1):
            pe = prime ** e
            for d in divisors[:current_length]:
                new_divisors.append(d * pe)
        divisors += new_divisors

    divisors = sorted(divisors)
    for d in divisors:
        if pow(k, d, p) == 1:
            return d
    return n

