import sys
from sys import stdin
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(stdin.readline())

    initial_edges = set()
    for _ in range(n-1):
        u, v = map(int, stdin.readline().split())
        if u > v:
            u, v = v, u
        initial_edges.add((u, v))

    target_edges = set()
    for _ in range(n-1):
        u, v = map(int, stdin.readline().split())
        if u > v:
            u, v = v, u
        target_edges.add((u, v))

    sym_diff = initial_edges.symmetric_difference(target_edges)
    if len(sym_diff) % 2 != 0:
        print(-1)
        return

    # Build initial tree and compute in_time, out_time, parent_initial
    initial_adj = [[] for _ in range(n+1)]
    for u, v in initial_edges:
        initial_adj[u].append(v)
        initial_adj[v].append(u)

    in_time = [0] * (n + 1)
    out_time = [0] * (n + 1)
    parent_initial = [0] * (n + 1)
    time = 0
    stack = [(1, -1, False)]

    while stack:
        node, p, visited = stack.pop()
        if visited:
            out_time[node] = time
            time += 1
            continue
        parent_initial[node] = p
        in_time[node] = time
        time += 1
        stack.append((node, p, True))
        for neighbor in reversed(initial_adj[node]):
            if neighbor != p:
                stack.append((neighbor, node, False))

    # Build target tree and parent_target with BFS
    target_adj = [[] for _ in range(n+1)]
    for u, v in target_edges:
        target_adj[u].append(v)
        target_adj[v].append(u)

    parent_target = [0] * (n + 1)
    q = deque()
    q.append(1)
    parent_target[1] = -1

    while q:
        u = q.popleft()
        for v in target_adj[u]:
            if parent_target[v] == 0 and v != parent_target[u]:
                parent_target[v] = u
                q.append(v)

    # Build binary lifting table
    log_max = 20
    lift = [[-1] * (n + 1) for _ in range(log_max)]
    for i in range(1, n+1):
        lift[0][i] = parent_target[i]

    for k in range(1, log_max):
        for i in range(1, n+1):
            if lift[k-1][i] != -1:
                lift[k][i] = lift[k-1][lift[k-1][i]]
            else:
                lift[k][i] = -1

    # Process each edge in initial_edges - target_edges
    steps = []
    for e in initial_edges - target_edges:
        u, v = e
        if parent_initial[u] == v:
            child = u
        elif parent_initial[v] == u:
            child = v
        else:
            print(-1)
            return

        B_in = in_time[child]
        B_out = out_time[child]
        current_node = child

        for k in range(log_max-1, -1, -1):
            if lift[k][current_node] != -1:
                ancestor = lift[k][current_node]
                if B_in <= in_time[ancestor] <= B_out:
                    current_node = ancestor

        parent_current = parent_target[current_node]
        if parent_current == -1:
            print(-1)
            return

        f = (current_node, parent_current)
        if f[0] > f[1]:
            f = (f[1], f[0])
        steps.append((u, v, f[0], f[1]))

    print(len(steps))
    for step in steps:
        print(' '.join(map(str, step)))

