import sys

def count_substrings(s):
    n = len(s)
    has_a = 'a' in s
    has_b = 'b' in s
    has_c = 'c' in s
    if not (has_a and has_b and has_c):
        return n * (n + 1) // 2
    last_a = last_b = last_c = -1
    bad_count = 0
    for i in range(n):
        char = s[i]
        if char == 'a':
            last_a = i
        elif char == 'b':
            last_b = i
        else:
            last_c = i
        current_min = min(last_a, last_b, last_c)
        if current_min != -1:
            bad_count += current_min + 1
    return n * (n + 1) // 2 - bad_count

