            dy = points[i][1] - points[j][1]
            dists.append(dx*dx + dy*dy)
    cnt = {}
    for d in dists:
        cnt[d] = cnt.get(d, 0) + 1
    if len(cnt) != 2:
        return False
    keys = sorted(cnt.keys())
    s_sq, d_sq = keys[0], keys[1]
    return cnt[s_sq] == 4 and cnt[d_sq] == 2 and d_sq == 2 * s_sq

def is_rectangle(points):
    def check(p1, p2, p3, p4):
        sum_x1 = points[p1][0] + points[p2][0]
        sum_y1 = points[p1][1] + points[p2][1]
        sum_x2 = points[p3][0] + points[p4][0]
        sum_y2 = points[p3][1] + points[p4][1]
        if sum_x1 != sum_x2 or sum_y1 != sum_y2:
            return False
        dx1 = points[p1][0] - points[p2][0]
        dy1 = points[p1][1] - points[p2][1]
        dx2 = points[p3][0] - points[p4][0]
        dy2 = points[p3][1] - points[p4][1]
        return (dx1*dx1 + dy1*dy1) == (dx2*dx2 + dy2*dy2)
    return (check(0, 1, 2, 3) or check(0, 2, 1, 3) or check(0, 3, 1, 2))

