class Block:
    def __init__(self, sorted_elements):
        self.sorted_elements = sorted_elements
        self.median = self.compute_median()
        self.cost = self.compute_cost()

    def compute_median(self):
        m = len(self.sorted_elements)
        if m % 2 == 1:
            return self.sorted_elements[m // 2]
        else:
            return (self.sorted_elements[(m // 2) - 1] + self.sorted_elements[m // 2]) / 2

    def compute_cost(self):
        median = self.median
        return sum(abs(x - median) for x in self.sorted_elements)

