    suffix_prefix_sum = [0] * (n+1)
    for i in range(n):
        suffix_prefix_sum[i+1] = suffix_prefix_sum[i] + initial[i]

    def update_suffix_prefix_sum():
        nonlocal suffix_prefix_sum
        suffix_prefix_sum = [0] * (len(current_suffix)+1)
        for i in range(len(current_suffix)):
            suffix_prefix_sum[i+1] = suffix_prefix_sum[i] + current_suffix[i]

    def next_suffix():
        nonlocal current_suffix, suffix_start
        s = current_suffix
        i = len(s) - 2
        while i >= 0 and s[i] >= s[i+1]:
            i -= 1
        if i == -1:
            return False
        j = len(s) - 1
        while s[j] <= s[i]:
            j -= 1
        s[i], s[j] = s[j], s[i]
        s[i+1:] = s[i+1:][::-1]
        update_suffix_prefix_sum()
        return True

    def expand_suffix():
        nonlocal current_suffix, suffix_start
        suffix_start -= 1
        new_suffix = [initial[suffix_start]] + current_suffix
        current_suffix = new_suffix
        has_next = next_suffix()
        if not has_next:
            current_suffix = new_suffix.copy()
            next_suffix()
        update_suffix_prefix_sum()

