def main():
    sys.setrecursionlimit(1 << 25)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while True:
        n, m = map(int, stdin.readline().split())
        if n == 0 and m == 0:
            break
        grid = []
        for _ in range(n):
            line = stdin.readline().strip()
            grid.append(list(line))

        entrance = (0, 0)
        treasures = [(n-1, 0), (0, m-1), (n-1, m-1)]
        for t in treasures:
            if grid[t[0]][t[1]] != '.':
                print("NO")
                break
        else:
            visited = [[False for _ in range(m)] for _ in range(n)]
            required = set(treasures)
            found = False

            def dfs(i, j, collected, steps):
                nonlocal found
                if found:
                    return
                if (i, j) == entrance and len(collected) == 3:
                    found = True
                    return
                current = (i, j)
                if current != entrance:
                    if visited[i][j]:
                        return
                    visited[i][j] = True
                new_collected = set(collected)
                if current in required:
                    new_collected.add(current)
                if len(new_collected) == 3 and (i, j) == entrance:
                    found = True
                    visited[i][j] = False
                    return
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] == '.' and not visited[ni][nj]:
                            dfs(ni, nj, new_collected, steps + 1)
                            if found:
                                break
                if current != entrance:
                    visited[i][j] = False

            visited[entrance[0]][entrance[1]] = False
            dfs(entrance[0], entrance[1], set(), 0)
            print("YES" if found else "NO")

