import heapq

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx])
    m = int(data[idx+1])
    k = int(data[idx+2])
    idx +=3

    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        x = int(data[idx])
        y = int(data[idx+1])
        w = int(data[idx+2])
        adj[x].append((y, w))
        adj[y].append((x, w))
        idx +=3

    heap = []

    for u in range(1, n+1):
        dist = [float('inf')] * (n +1)
        dist[u] = 0
        visited = set()
        pq = [(0, u)]

        while pq:
            current_dist, v = heapq.heappop(pq)
            if v in visited:
                continue
            visited.add(v)

            if v > u:
                if len(heap) < k:
                    heapq.heappush(heap, -current_dist)
                    if len(heap) > k:
                        heapq.heappop(heap)
                else:
                    current_max = -heap[0]
                    if current_dist >= current_max:
                        break
                    else:
                        heapq.heappush(heap, -current_dist)
                        if len(heap) > k:
                            heapq.heappop(heap)

            for neighbor, weight in adj[v]:
                if dist[neighbor] > current_dist + weight:
                    dist[neighbor] = current_dist + weight
                    heapq.heappush(pq, (dist[neighbor], neighbor))

    print(-heap[0])

