import sys
from collections import deque

def main():
    n, m, w = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        grid.append(row)

    def bfs(start_row, start_col):
        dist = [[-1] * m for _ in range(n)]
        if grid[start_row][start_col] == -1:
            return dist
        dist[start_row][start_col] = 0
        q = deque([(start_row, start_col)])
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while q:
            r, c = q.popleft()
            current = dist[r][c]
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] != -1 and dist[nr][nc] == -1:
                        dist[nr][nc] = current + 1
                        q.append((nr, nc))
        return dist

    dist_start = bfs(0, 0)
    dist_end = bfs(n-1, m-1)

    time1 = dist_start[n-1][m-1] * w if dist_start[n-1][m-1] != -1 else float('inf')

    portals = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] > 0:
                portals.append((i, j))

    min_s = min_e = float('inf')
    for i, j in portals:
        if dist_start[i][j] != -1:
            s = dist_start[i][j] * w + grid[i][j]
            if s < min_s:
                min_s = s
        if dist_end[i][j] != -1:
            e = dist_end[i][j] * w + grid[i][j]
            if e < min_e:
                min_e = e

    time2 = min_s + min_e if (min_s != float('inf') and min_e != float('inf')) else float('inf')
    result = min(time1, time2)
    print(-1 if result == float('inf') else result)

