    main()

import math
import sys
from math import acos, sqrt, pi
from itertools import combinations

def convex_hull(points):
    points = sorted(points)
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def circle_intersection_area(c1, c2, r):
    x1, y1 = c1
    x2, y2 = c2
    d = sqrt((x1-x2)**2 + (y1-y2)**2)
    if d >= 2*r:
        return 0.0
    angle = 2 * acos(d/(2*r))
    sector = 0.5 * r * r * angle
    triangle = 0.5 * r * r * math.sin(angle)
    return 2 * (sector - triangle)

def main():
    n, r = map(float, sys.stdin.readline().split())
    n = int(n)
    points = [tuple(map(float, sys.stdin.readline().split())) for _ in range(n)]
    if n == 1:
        print(math.pi * r * r)
        return
    hull = convex_hull(points)
    m = len(hull)
    min_area = math.pi * r * r
    for i in range(m):
        for j in range(i+1, m):
            area = circle_intersection_area(hull[i], hull[j], r)
            if area < min_area:
                min_area = area
    print("{0:.10f}".format(min_area))

