import sys
sys.setrecursionlimit(1 << 25)

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size
        self.parity = [0] * size  # 0 for same, 1 for inverse

    def find(self, x):
        if self.parent[x] != x:
            orig_parent = self.parent[x]
            self.parent[x] = self.find(self.parent[x])
            self.parity[x] ^= self.parity[orig_parent]
        return self.parent[x]

    def union(self, x, y, p):
        # x and y should be connected with x = y XOR p
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            if (self.parity[x] ^ self.parity[y]) != p:
                return False
            return True
        if self.rank[x_root] < self.rank[y_root]:
            x_root, y_root = y_root, x_root
            x, y = y, x
            p ^= self.parity[x] ^ self.parity[y]
        self.parent[y_root] = x_root
        self.parity[y_root] = self.parity[y] ^ p ^ self.parity[x]
        if self.rank[x_root] == self.rank[y_root]:
            self.rank[x_root] += 1
        return True

