        nonlocal max_freq, sum_colors
        if freq[c] == 1:
            del freq[c]
        else:
            freq[c] -= 1
        current = freq.get(c, 0)
        old_count = current + 1

        if old_count == max_freq:
            sum_colors -= c
            if sum_colors <= 0:
                new_max = 0
                new_sum = 0
                if freq:
                    new_max = max(freq.values(), default=0)
                    new_sum = sum(k for k, v in freq.items() if v == new_max)
                max_freq = new_max
                sum_colors = new_sum

    def dfs_heavy(u, parent):
        stack = [(u, parent, False)]
        while stack:
            node, p, visited = stack.pop()
            if visited:
                for v in adj[node]:
                    if v != p and v != heavy_child[node]:
                        dfs_light(v, node)
                add(color[node-1])
                ans[node] = sum_colors
            else:
                stack.append((node, p, True))
                if heavy_child[node] != -1:
                    stack.append((heavy_child[node], node, False))

    def dfs_light(u, parent):
        stack = [(u, parent)]
        remove_stack = []
        while stack:
            node, p = stack.pop()
            remove_stack.append(color[node-1])
            for v in adj[node]:
                if v != p and v != heavy_child[node]:
                    stack.append((v, node))
        for c in remove_stack:
            remove(c)

    dfs_heavy(1, -1)

    print(' '.join(map(str, ans[1:n+1])))

