MOD = 10**9 + 7

def main():
    s = input().strip()
    left_pos = [i for i, c in enumerate(s) if c == '(']
    right_pos = [i for i, c in enumerate(s) if c == ')']

    if not left_pos:
        print(0)
        return

    max_n = len(left_pos) + len(right_pos)
    max_fact = max_n
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], MOD-2, MOD)
    for i in range(max_fact -1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    res = 0
    for i in range(len(left_pos)):
        left = left_pos[i]
        low, high = 0, len(right_pos)
        while low < high:
            mid = (low + high) // 2
            if right_pos[mid] > left:
                high = mid
            else:
                low = mid + 1
        r_i = len(right_pos) - low
        if r_i == 0:
            continue
        n = i + r_i
        k = i + 1
        res = (res + comb(n, k)) % MOD
    print(res)

