import math

def multiplicative_order(a, q):
    if math.gcd(a, q) != 1:
        return -1  # not coprime

    def euler_phi(n):
        result = n
        i = 2
        while i * i <= n:
            if n % i == 0:
                while n % i == 0:
                    n //= i
                result -= result // i
            i += 1
        if n > 1:
            result -= result // n
        return result

    phi = euler_phi(q)

    factors = []
    temp = phi
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            factors.append(i)
            while temp % i == 0:
                temp //= i
        i += 1
    if temp > 1:
        factors.append(temp)
    factors = list(set(factors))

    divisors = {1}
    for p in factors:
        new_divs = [d * p for d in divisors]
        divisors.update(new_divs)

    for d in sorted(divisors):
        if pow(a, d, q) == 1:
            return d
    return -1

def main():
    import sys
    N, M, a, Q = map(int, sys.stdin.readline().split())
    ord = multiplicative_order(a, Q)

    if ord == 0:
        print(' '.join(['1'] * N))
        return

    d_max = min(M, N-1)

    if ord == 1:
        print(' '.join(['1'] * N))
        return

    max_k = d_max
    fact = [1] * (max_k + 1)
    for i in range(1, max_k + 1):
        fact[i] = fact[i-1] * i % ord

    inv_fact = [1] * (max_k + 1)
    inv_fact[max_k] = pow(fact[max_k], ord-2, ord)
    for i in range(max_k-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % ord

    comb = [0] * (max_k + 1)
    comb[0] = 1 % ord
    if max_k >= 1:
        comb[1] = M % ord

    current_numerator = comb[1]
    for k in range(2, max_k + 1):
        current_numerator = current_numerator * (M - k + 1) % ord
        comb[k] = current_numerator * inv_fact[k] % ord

    prefix = [0] * (max_k + 2)
    for k in range(max_k + 1):
        prefix[k+1] = (prefix[k] + comb[k]) % ord

    result = []
    for i in range(N):
        d = min(M, (N-1) - i)
        d = min(d, max_k)
        sum_c = prefix[d+1]
        res = pow(a, sum_c, Q)
        result.append(res)

    print(' '.join(map(str, result)))

