from collections import defaultdict

def process_dataset():
    pc_states = {}  # key: PC number, value: (student, login_time)
    student_intervals = defaultdict(list)  # key: student, value: list of (start, end)

    # Read N and M
    line = sys.stdin.readline().strip()
    while line == '':
        line = sys.stdin.readline().strip()
    N, M = map(int, line.split())
    if N == 0 and M == 0:
        return False

    # Read r
    r = int(sys.stdin.readline().strip())
    # Read r records
    for _ in range(r):
        line = sys.stdin.readline().strip()
        while line == '':
            line = sys.stdin.readline().strip()
        t, n, m, s = map(int, line.split())
        if s == 1:
            pc_states[n] = (m, t)
        else:
            if n in pc_states:
                m_login, login_time = pc_states.pop(n)
                student_intervals[m_login].append((login_time, t))

    # Read q
    q = int(sys.stdin.readline().strip())
    # Process each query
    for _ in range(q):
        line = sys.stdin.readline().strip()
        while line == '':
            line = sys.stdin.readline().strip()
        ts, te, m = map(int, line.split())
        intervals = student_intervals.get(m, [])
        if not intervals:
            print(0)
            continue

        # Sort and merge intervals
        sorted_intervals = sorted(intervals, key=lambda x: x[0])
        merged = []
        for start, end in sorted_intervals:
            if not merged:
                merged.append([start, end])
            else:
                last_end = merged[-1][1]
                if start <= last_end:
                    merged[-1][1] = max(last_end, end)
                else:
                    merged.append([start, end])

        # Calculate overlapping time
        total = 0
        for start, end in merged:
            overlap_start = max(start, ts)
            overlap_end = min(end, te)
            if overlap_start < overlap_end:
                total += overlap_end - overlap_start
        print(total)

    return True

def main():
    while True:
        if not process_dataset():
            break

