from collections import deque

def main():
    while True:
        W, H = map(int, sys.stdin.readline().split())
        if W == 0 and H == 0:
            break
        left_room = []
        right_room = []
        for _ in range(H):
            line = sys.stdin.readline().strip()
            l, r = line.split()
            left_room.append(l)
            right_room.append(r)
        # Find start positions and destinations
        len_start = None
        left_dest = None
        for i in range(H):
            for j in range(W):
                if left_room[i][j] == 'L':
                    len_start = (i, j)
                if left_room[i][j] == '%':
                    left_dest = (i, j)
        rin_start = None
        right_dest = None
        for i in range(H):
            for j in range(W):
                if right_room[i][j] == 'R':
                    rin_start = (i, j)
                if right_room[i][j] == '%':
                    right_dest = (i, j)
        # Check if already at destination
        if len_start == left_dest and rin_start == right_dest:
            print("Yes")
            continue
        # BFS setup
        visited = set()
        queue = deque()
        start_state = (len_start, rin_start)
        visited.add(start_state)
        queue.append(start_state)
        found = False
        directions = [('N','N'), ('W','E'), ('E','W'), ('S','S')]
        # BFS loop
        while queue and not found:
            l_pos, r_pos = queue.popleft()
            # Check current state
            if l_pos == left_dest and r_pos == right_dest:
                found = True
                break
            # Generate next states
            for dl, dr in directions:
                # Calculate new positions
                # Len's movement
                lx, ly = l_pos
                if dl == 'N':
                    new_lx, new_ly = lx - 1, ly
                elif dl == 'S':
                    new_lx, new_ly = lx + 1, ly
                elif dl == 'W':
                    new_lx, new_ly = lx, ly - 1
                else:  # E
                    new_lx, new_ly = lx, ly + 1
                if 0 <= new_lx < H and 0 <= new_ly < W and left_room[new_lx][new_ly] != '#':
                    new_l = (new_lx, new_ly)
                else:
                    new_l = l_pos
                # Rin's movement
                rx, ry = r_pos
                if dr == 'N':
                    new_rx, new_ry = rx - 1, ry
                elif dr == 'S':
                    new_rx, new_ry = rx + 1, ry
                elif dr == 'W':
                    new_rx, new_ry = rx, ry - 1
                else:  # E
                    new_rx, new_ry = rx, ry + 1
                if 0 <= new_rx < H and 0 <= new_ry < W and right_room[new_rx][new_ry] != '#':
                    new_r = (new_rx, new_ry)
                else:
                    new_r = r_pos
                new_state = (new_l, new_r)
                # Check if destination is reached
                if new_l == left_dest and new_r == right_dest:
                    found = True
                    queue = deque()
                    break
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)
            # Exit loop if found
            if found:
                break
        print("Yes" if found else "No")

