class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def is_rotation(P, N):
    s = list(range(1, N+1))
    if P == s:
        return True
    try:
        idx = P.index(1)
    except ValueError:
        return False
    for i in range(N):
        if s[i] != P[(idx + i) % N]:
            return False
    return True

