        if K == N:
            print("Yes" if is_rotation(P, N) else "No")
        else:
            print("Yes")
    else:
        ft = FenwickTree(N)
        parity = 0
        for num in reversed(P):
            count = ft.query(num - 1)
            parity += count
            parity %= 2
            ft.update(num, 1)
        print("Yes" if parity % 2 == 0 else "No")

