import sys
from collections import deque

class DSU:
    def __init__(self, n):
        self.parent = list(range(n+1))
        self.rank = [0]*(n+1)

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        u_root = self.find(u)
        v_root = self.find(v)
        if u_root == v_root:
            return False
        if self.rank[u_root] < self.rank[v_root]:
            self.parent[u_root] = v_root
        else:
            self.parent[v_root] = u_root
            if self.rank[u_root] == self.rank[v_root]:
                self.rank[u_root] += 1
        return True

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v, w = map(int, sys.stdin.readline().split())
        edges.append((w, u, v))
    edges_sorted = sorted(edges)
    dsu = DSU(n)
    mst_edges = []
    non_mst_edges = []
    for edge in edges_sorted:
        w, u, v = edge
        if dsu.find(u) != dsu.find(v):
            dsu.union(u, v)
            mst_edges.append((u, v, w))
        else:
            non_mst_edges.append((u, v, w))

    if n == 1:
        print(0)
        return

    adj = [[] for _ in range(n+1)]
    for u, v, w in mst_edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    log_max = 20
    parent = [0]*(n+1)
    depth = [0]*(n+1)
    edge_weight = [0]*(n+1)
    visited = [False]*(n+1)
    q = deque([1])
    visited[1] = True
    while q:
        u = q.popleft()
        for v, w in adj[u]:
            if not visited[v] and v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                edge_weight[v] = w
                visited[v] = True
                q.append(v)

    up = [[0]*(n+1) for _ in range(log_max)]
    max_edge = [[0]*(n+1) for _ in range(log_max)]
    for i in range(1, n+1):
        up[0][i] = parent[i]
        max_edge[0][i] = edge_weight[i]

    for k in range(1, log_max):
        for i in range(1, n+1):
            up_prev = up[k-1][i]
            up[k][i] = up[k-1][up_prev]
            max_edge[k][i] = max(max_edge[k-1][i], max_edge[k-1][up_prev])

    def get_max_edge(u, v):
        if u == v:
            return 0
        max_val = 0
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(log_max-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                max_val = max(max_val, max_edge[k][u])
                u = up[k][u]
        if u == v:
            return max_val
        for k in range(log_max-1, -1, -1):
            if up[k][u] != up[k][v]:
                max_val = max(max_val, max_edge[k][u], max_edge[k][v])
                u = up[k][u]
                v = up[k][v]
        max_val = max(max_val, max_edge[0][u], max_edge[0][v])
        return max_val

    total = 0
    for u, v, w in non_mst_edges:
        current_max = get_max_edge(u, v)
        if w <= current_max:
            total += (current_max - w + 1)
    print(total)

