def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = list(map(int, input[1:n+1]))
    value_to_pos = {v: i for i, v in enumerate(p)}

    # Compute previous greater element
    prev_greater = [-1] * n
    stack = []
    for i in range(n):
        while stack and p[stack[-1]] <= p[i]:
            stack.pop()
        if stack:
            prev_greater[i] = stack[-1]
        stack.append(i)

    # Compute next greater element
    next_greater = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and p[stack[-1]] <= p[i]:
            stack.pop()
        if stack:
            next_greater[i] = stack[-1]
        stack.append(i)

    count = 0
    for pos in range(n):
        M = p[pos]
        left = prev_greater[pos]
        right = next_greater[pos]
        x_start = left + 1
        x_end = pos - 1
        y_start = pos + 1
        y_end = right - 1

        # Iterate x in [x_start, x_end]
        if x_start <= x_end:
            for x in range(x_start, x_end + 1):
                target = M - p[x]
                if target not in value_to_pos:
                    continue
                y_pos = value_to_pos[target]
                if y_start <= y_pos <= y_end:
                    count += 1

        # Also check for x <= pos and y >= pos (earlier approach)
        # Handle case where x_range is [left+1, pos] and y_range is [pos, right-1]
        x_start2 = left + 1
        x_end2 = pos
        y_start2 = pos
        y_end2 = right -1

        if x_start2 <= x_end2:
            for x in range(x_start2, x_end2 + 1):
                target = M - p[x]
                if target not in value_to_pos:
                    continue
                y_pos = value_to_pos[target]
                if y_start2 <= y_pos <= y_end2 and y_pos >= x:
                    count += 1

    print(count)

