import sys
from collections import Counter
from functools import lru_cache

def main():
    while True:
        n, m = map(int, sys.stdin.readline().split())
        if n == 0 and m == 0:
            break
        elements = [sys.stdin.readline().strip() for _ in range(n)]
        text_lines = [sys.stdin.readline().strip() for _ in range(m)]
        text = ''.join(text_lines)
        total_length = sum(len(e) for e in elements)
        text_len = len(text)
        if total_length == 0 or text_len < total_length:
            print(0)
            continue

        element_counter = Counter(elements)
        elements_sorted = sorted(element_counter.keys())
        element_lengths = [len(e) for e in elements_sorted]
        k = len(elements_sorted)
        initial_counts = tuple(element_counter[e] for e in elements_sorted)
        count = 0

        for i in range(text_len - total_length + 1):
            s = text[i:i+total_length]

            @lru_cache(maxsize=None)
            def backtrack(pos, current_counts):
                if pos == total_length:
                    return all(c == 0 for c in current_counts)
                for idx in range(k):
                    if current_counts[idx] == 0:
                        continue
                    e_len = element_lengths[idx]
                    if pos + e_len > total_length:
                        continue
                    if s[pos:pos+e_len] != elements_sorted[idx]:
                        continue
                    new_counts = list(current_counts)
                    new_counts[idx] -= 1
                    if backtrack(pos + e_len, tuple(new_counts)):
                        return True
                return False

            if backtrack(0, initial_counts):
                count += 1
            backtrack.cache_clear()

        print(count)

