import math

def main():
    while True:
        line = input().strip()
        while not line:
            line = input().strip()
        parts = list(map(int, line.split()))
        n, hx, hy, dx, dy = parts[:5]
        if n == 0 and hx == 0 and hy == 0 and dx == 0 and dy == 0:
            break
        crystals = []
        for _ in range(n):
            cx, cy = map(int, input().split())
            crystals.append((cx, cy))

        deadlines = []
        for cx, cy in crystals:
            s = (cx - dx)**2 + (cy - dy)**2
            D = math.sqrt(s)
            deadline = math.floor(D - 1e-9)
            deadlines.append(deadline)

        n_crystals = len(crystals)
        dist_start = [0.0] * n_crystals
        for i in range(n_crystals):
            cx, cy = crystals[i]
            dist_start[i] = math.hypot(cx - hx, cy - hy)

        dist_matrix = [[0.0 for _ in range(n_crystals)] for _ in range(n_crystals)]
        for i in range(n_crystals):
            for j in range(n_crystals):
                if i != j:
                    dx_i = crystals[i][0] - crystals[j][0]
                    dy_i = crystals[i][1] - crystals[j][1]
                    dist_matrix[i][j] = math.hypot(dx_i, dy_i)

        dp = {}
        for u in range(n_crystals):
            if dist_start[u] <= deadlines[u]:
                mask = 1 << u
                key = (mask, u)
                dp[key] = dist_start[u]

        masks = sorted(range(1 << n_crystals), key=lambda x: bin(x).count('1'))
        for mask in masks:
            for u in range(n_crystals):
                if not (mask & (1 << u)):
                    continue
                key = (mask, u)
                if key not in dp:
                    continue
                current_time = dp[key]
                for v in range(n_crystals):
                    if mask & (1 << v):
                        continue
                    dist_uv = dist_matrix[u][v]
                    new_time = current_time + dist_uv
                    if new_time <= deadlines[v]:
                        new_mask = mask | (1 << v)
                        new_key = (new_mask, v)
                        if new_key not in dp or new_time < dp.get(new_key, float('inf')):
                            dp[new_key] = new_time

        full_mask = (1 << n_crystals) - 1
