import heapq

def main():
    directions = [ (-1, 0), (0, 1), (1, 0), (0, -1) ]
    while True:
        H, W, N = map(int, input().split())
        if H == 0 and W == 0 and N == 0:
            break
        commands = input().strip()
        grid = []
        for _ in range(H):
            grid.append(input().strip())

        # Find start and goal positions
        sx = sy = gx = gy = -1
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 'S':
                    sx, sy = i, j
                if grid[i][j] == 'G':
                    gx, gy = i, j

        # Precompute directions for each k
        max_k = N
        dirs = [0] * (max_k + 1)
        current_dir = 0
        dirs[0] = current_dir
        for i in range(max_k):
            cmd = commands[i]
            if cmd == 'L':
                current_dir = (current_dir + 3) % 4
            else:
                current_dir = (current_dir + 1) % 4
            dirs[i+1] = current_dir

        INF = 10**18
        dist = [ [ [INF] * 4 for _ in range(W) ] for _ in range(H) ]
        initial_dir = dirs[0]
        dist[sx][sy][initial_dir] = 0
        heap = []
        heapq.heappush(heap, (0, sx, sy))
        found = False

        while heap:
            k, x, y = heapq.heappop(heap)
            current_d = dirs[k]
            if x == gx and y == gy:
                found = True
                break
            if k > dist[x][y][current_d]:
                continue

            # Move forward
            dx, dy = directions[current_d]
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W:
                if grid[nx][ny] != '#':
                    new_k = k
                    new_d = dirs[new_k]
                    if dist[nx][ny][new_d] > new_k:
                        dist[nx][ny][new_d] = new_k
                        heapq.heappush(heap, (new_k, nx, ny))

            # Turn
            if k < max_k:
                new_k = k + 1
                new_d = dirs[new_k]
                if dist[x][y][new_d] > new_k:
                    dist[x][y][new_d] = new_k
                    heapq.heappush(heap, (new_k, x, y))

        print("Yes" if found else "No")

