import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    children = [[] for _ in range(n + 1)]
    original_val = [None] * (n + 1)
    type_node = [None] * (n + 1)

    for u in range(1, n + 1):
        parts = sys.stdin.readline().split()
        type_u = parts[0]
        type_node[u] = type_u
        if type_u == 'IN':
            original_val[u] = int(parts[1])
        else:
            if type_u in ('AND', 'OR', 'XOR'):
                a, b = map(int, parts[1:3])
                children[u] = [a, b]
            else:  # NOT
                a = int(parts[1])
                children[u] = [a]

    parents = [[] for _ in range(n + 1)]
    dependency_count = [0] * (n + 1)
    for u in range(1, n + 1):
        if type_node[u] != 'IN':
            for v in children[u]:
                parents[v].append(u)
            dependency_count[u] = len(children[u])

    queue = deque()
    for u in range(1, n + 1):
        if type_node[u] == 'IN':
            for p in parents[u]:
                dependency_count[p] -= 1
                if dependency_count[p] == 0:
                    queue.append(p)

    while queue:
        u = queue.popleft()
        child_vals = [original_val[v] for v in children[u]]
        if type_node[u] == 'AND':
            original_val[u] = child_vals[0] & child_vals[1]
        elif type_node[u] == 'OR':
            original_val[u] = child_vals[0] | child_vals[1]
        elif type_node[u] == 'XOR':
            original_val[u] = child_vals[0] ^ child_vals[1]
        elif type_node[u] == 'NOT':
            original_val[u] = 1 - child_vals[0]
        for p in parents[u]:
            dependency_count[p] -= 1
            if dependency_count[p] == 0:
                queue.append(p)

    sensitivity = [False] * (n + 1)
    sensitivity[1] = True
    queue = deque([1])

    while queue:
        u = queue.popleft()
        if type_node[u] == 'IN':
            continue
        child = children[u]
        if type_node[u] == 'AND':
            a, b = child
            sa = sensitivity[u] and original_val[b]
            sb = sensitivity[u] and original_val[a]
            if sa and not sensitivity[a]:
                sensitivity[a] = True
                queue.append(a)
            if sb and not sensitivity[b]:
                sensitivity[b] = True
                queue.append(b)
        elif type_node[u] == 'OR':
            a, b = child
            sa = sensitivity[u] and (1 - original_val[b])
            sb = sensitivity[u] and (1 - original_val[a])
            if sa and not sensitivity[a]:
                sensitivity[a] = True
                queue.append(a)
            if sb and not sensitivity[b]:
                sensitivity[b] = True
                queue.append(b)
        elif type_node[u] == 'XOR':
            a, b = child
            if not sensitivity[a]:
                sensitivity[a] = sensitivity[u]
                queue.append(a)
            if not sensitivity[b]:
                sensitivity[b] = sensitivity[u]
                queue.append(b)
        elif type_node[u] == 'NOT':
            a = child[0]
            if not sensitivity[a]:
                sensitivity[a] = sensitivity[u]
                queue.append(a)

    in_nodes = []
    for u in range(1, n + 1):
        if type_node[u] == 'IN':
            in_nodes.append(u)
    in_nodes.sort()
    res = []
    root_val = original_val[1]
    for u in in_nodes:
        res.append(str(root_val ^ sensitivity[u]))
    print(''.join(res))

