class SegmentTree:
    def __init__(self, size):
        self.n = size
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.data = [float('inf')] * (2 * self.size)
        for i in range(self.n):
            self.data[self.size + i] = 0
        for i in range(self.size - 1, 0, -1):
            self.data[i] = min(self.data[2 * i], self.data[2 * i + 1])

    def increment(self, pos):
        pos += self.size
        self.data[pos] += 1
        pos >>= 1
        while pos >= 1:
            new_val = min(self.data[2 * pos], self.data[2 * pos + 1])
            if self.data[pos] == new_val:
                break
            self.data[pos] = new_val
            pos >>= 1

    def get_min(self):
        return self.data[1]

