import sys

def shortest_substring(s):
    if '1' not in s or '2' not in s or '3' not in s:
        return 0
    counts = {'1': 0, '2': 0, '3': 0}
    left = 0
    min_len = float('inf')
    for right in range(len(s)):
        c = s[right]
        counts[c] += 1
        while counts['1'] > 0 and counts['2'] > 0 and counts['3'] > 0:
            current_len = right - left + 1
            if current_len < min_len:
                min_len = current_len
            left_c = s[left]
            counts[left_c] -= 1
            left += 1
    return min_len

