import sys
import bisect

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    parent = list(map(int, sys.stdin.readline().split()))
    parent = [0] + parent  # Adjust to 1-based index
    children = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        p = parent[i]
        if p != 0:
            children[p].append(i)

    in_time = [0] * (n + 1)
    out_time = [0] * (n + 1)
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)
    time = 0

    for i in range(1, n+1):
        if not visited[i] and parent[i] == 0:
            stack = [(i, False)]
            while stack:
                current, processed = stack.pop()
                if not processed:
                    if visited[current]:
                        continue
                    visited[current] = True
                    in_time[current] = time
                    time += 1
                    if parent[current] == 0:
                        current_depth = 0
                    else:
                        current_depth = depth[parent[current]] + 1
                    depth[current] = current_depth
                    stack.append((current, True))
                    for child in reversed(children[current]):
                        stack.append((child, False))
                else:
                    out_time[current] = time
                    time += 1

    max_level = 20
    up = [[0] * (n + 1) for _ in range(max_level)]
    for i in range(1, n+1):
        up[0][i] = parent[i]
    for k in range(1, max_level):
        for i in range(1, n+1):
            up[k][i] = up[k-1][up[k-1][i]]

    depth_dict = {}
    for i in range(1, n+1):
        d = depth[i]
        if d not in depth_dict:
            depth_dict[d] = []
        depth_dict[d].append(in_time[i])
    for d in depth_dict:
        depth_dict[d].sort()

    m = int(sys.stdin.readline())
    output = []
    for _ in range(m):
        v, p = map(int, sys.stdin.readline().split())
        if depth[v] < p:
            output.append('0')
            continue
        req_depth = depth[v] - p
        current = v
        for k in reversed(range(max_level)):
            if up[k][current] != 0 and depth[up[k][current]] >= req_depth:
                current = up[k][current]
        if depth[current] != req_depth:
            output.append('0')
            continue
        z = current
        d = depth[z] + p
        if d not in depth_dict:
            output.append('0')
            continue
        list_in = depth_dict[d]
        in_z = in_time[z]
        out_z = out_time[z]
        left = bisect.bisect_left(list_in, in_z)
        right = bisect.bisect_right(list_in, out_z)
        count = right - left
        ans = max(count - 1, 0)
        output.append(str(ans))
    print(' '.join(output))

