def get_bulls_cows(guess, secret):
    bulls = sum(g == s for g, s in zip(guess, secret))
    cows = 0
    for d in set(guess):
        if d in secret:
            cows += min(guess.count(d), secret.count(d))
    cows -= bulls
    return (bulls, cows)

