    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        x, y, w = map(int, sys.stdin.readline().split())
        adj[x].append((y, w))
        adj[y].append((x, w))

    xors = [-1] * (n + 1)
    xors[1] = 0
    basis = [0] * 30  # Basis for XOR values up to 30 bits

    q = deque([1])
    while q:
        u = q.popleft()
        for v, w in adj[u]:
            new_xor = xors[u] ^ w
            if xors[v] == -1:
                xors[v] = new_xor
                q.append(v)
            else:
                # Calculate cycle XOR and insert into basis
                cycle_xor = new_xor ^ xors[v]
                x = cycle_xor
                for i in reversed(range(30)):
                    if (x >> i) & 1:
                        if basis[i]:
                            x ^= basis[i]
                        else:
                            basis[i] = x
                            break

    res = xors[n]
    for i in reversed(range(30)):
        if basis[i] and (res >> i) & 1:
            res ^= basis[i]

    print(res)

