def case1(p, y):
    for n in range(y, p, -1):
        if is_prime(n):
            return n
    return -1

def case2(p, y):
    for n in range(y, p, -1):
        if n <= p:
            continue
        max_d = math.isqrt(n)
        safe = True
        for d in range(2, max_d + 1):
            if n % d == 0:
                other = n // d
                if d <= p or other <= p:
                    safe = False
                    break
        if safe:
            return n
    return -1

