import heapq

def main():
    W, H = map(int, input().split())
    grid = []
    holes = []
    start = None
    goal = None
    ms = []
    for y in range(H):
        line = input().strip()
        grid.append(line)
        for x, c in enumerate(line):
            if c == 'S':
                start = (x, y)
            elif c == 'G':
                goal = (x, y)
            elif c == 'M':
                ms.append((x, y))
            elif c == '#':
                holes.append((x, y))

    movement_cost = [[1 for _ in range(W)] for _ in range(H)]
    for y in range(H):
        for x in range(W):
            if grid[y][x] == '#':
                continue
            if not holes:
                continue
            min_dist = float('inf')
            for (hx, hy) in holes:
                d = abs(x - hx) + abs(y - hy)
                if d < min_dist:
                    min_dist = d
            if min_dist == 1:
                movement_cost[y][x] = 3
            elif min_dist == 2:
                movement_cost[y][x] = 2
            else:
                movement_cost[y][x] = 1

    important_points = [start] + ms + [goal]
    distance = {}
    for p in important_points:
        dist = {}
        for x in range(W):
            for y in range(H):
                dist[(x, y)] = float('inf')
        px, py = p
        dist[p] = 0
        heap = [(0, px, py)]
        visited = set()
        while heap:
            d, x, y = heapq.heappop(heap)
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx = x + dx
                ny = y + dy
                if 0 <= nx < W and 0 <= ny < H:
                    if grid[ny][nx] == '#':
                        continue
                    cost = movement_cost[ny][nx]
                    if dist[(nx, ny)] > d + cost:
                        dist[(nx, ny)] = d + cost
                        heapq.heappush(heap, (dist[(nx, ny)], nx, ny))
        distance[p] = {q: dist[q] for q in important_points}

    n_m = len(ms)
    full_mask = (1 << n_m) - 1
    heap = []
    heapq.heappush(heap, (0, start, 0))
    dp = {}
    dp[(start, 0)] = 0
    min_total = float('inf')
    while heap:
        current_cost, current_pos, mask = heapq.heappop(heap)
        if current_cost > dp.get((current_pos, mask), float('inf')):
            continue
        if mask == full_mask:
            total = current_cost + distance[current_pos][goal]
            if total < min_total:
                min_total = total
            continue
        for m_idx in range(n_m):
            if not (mask & (1 << m_idx)):
                m_pos = ms[m_idx]
                new_mask = mask | (1 << m_idx)
                dist = distance[current_pos][m_pos]
                if dist == float('inf'):
                    continue
                new_cost = current_cost + dist
                key = (m_pos, new_mask)
                if new_cost < dp.get(key, float('inf')):
                    dp[key] = new_cost
                    heapq.heappush(heap, (new_cost, m_pos, new_mask))
    print(min_total)

