import sys
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N, M, K, Q = map(int, input[ptr:ptr+4])
    ptr +=4

    graph = [[] for _ in range(N+1)]  # 1-based
    for _ in range(M):
        u = int(input[ptr])
        v = int(input[ptr+1])
        ptr +=2
        graph[u].append(v)
        graph[v].append(u)

    capitals = set()
    for _ in range(K):
        c = int(input[ptr])
        ptr +=1
        capitals.add(c)

    queries = []
    for _ in range(Q):
        a = int(input[ptr])
        b = int(input[ptr+1])
        ptr +=2
        queries.append((a, b))

    # Precompute connected components
    def bfs_connected(start, target, exclude=None):
        visited = set()
        q = deque()
        q.append(start)
        visited.add(start)
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v == exclude:
                    continue
                if v not in visited:
                    if v == target:
                        return True
                    visited.add(v)
                    q.append(v)
        return target in visited  # in case start == target

    for a, b in queries:
        if a == b:
            cnt = 1 if a in capitals else 0
            if cnt ==0:
                print(0, 0)
            else:
                print(a, 1)
            continue

        # Check if a and b are connected
        if not bfs_connected(a, b, None):
            print(0, 0)
            continue

        res = []
        if a in capitals:
            res.append(a)
        if b in capitals:
            res.append(b)

        for c in capitals:
            if c == a or c == b:
                continue
            # Check if removing c disconnects a and b
            if not bfs_connected(a, b, c):
                res.append(c)

        if not res:
            print(0, 0)
        else:
            max_val = max(res)
            count = res.count(max_val)
            print(max_val, count)

