import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    t = int(input[idx])
    idx += 1
    for _ in range(t):
        n = int(input[idx])
        idx +=1
        a = list(map(int, input[idx:idx+n]))
        idx +=n

        # Compute reachable
        reachable = [False]*(n+2)
        reachable[n] = True
        for i in range(n-1, 0, -1):
            end_j = i + a[i-1]
            end_j = min(end_j, n)
            for j in range(i+1, end_j+1):
                if reachable[j]:
                    reachable[i] = True
                    break

        # Precompute possible_ks for each i
        possible_ks_count = [0]*(n+1)
        possible_ks_set = [set() for _ in range(n+1)]
        for i in range(1, n):
            if not reachable[i]:
                possible_ks_count[i] = 0
                possible_ks_set[i] = set()
                continue
            start_k = i+1
            end_k = i + a[i-1]
            end_k = min(end_k, n)
            count = 0
            s = set()
            for k in range(start_k, end_k+1):
                if k > n:
                    continue
                if reachable[k] and a[k-1] !=0:
                    count +=1
                    s.add(k)
            possible_ks_count[i] = count
            possible_ks_set[i] = s

        # Build edges
        edges = [[] for _ in range(n+1)]
        for i in range(1, n):
            if not reachable[i]:
                continue
            end_j = i + a[i-1]
            end_j = min(end_j, n)
            for j in range(i+1, end_j+1):
                if j >n or not reachable[j]:
                    continue
                cost = 0
                if a[i-1] != (j -i):
                    cost +=1
                if j in possible_ks_set[i]:
                    cost += possible_ks_count[i] -1
                else:
                    cost += possible_ks_count[i]
                edges[i].append( (j, cost) )

        # Shortest path using DP
        INF = float('inf')
        distance = [INF]*(n+1)
        distance[1] = 0
        for i in range(1, n+1):
            if distance[i] == INF:
                continue
