import sys

def main():
    n, p, q = map(int, sys.stdin.readline().split())
    projects = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    min_single = float('inf')
    for a, b in projects:
        time_p = p / a
        time_q = q / b
        current_time = max(time_p, time_q)
        if current_time < min_single:
            min_single = current_time

    # Function to compute convex hull
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Sort and deduplicate
    points = sorted(projects, key=lambda x: (x[0], -x[1]))
    unique = []
    for p in points:
        while unique and unique[-1][0] == p[0] and unique[-1][1] >= p[1]:
            unique.pop()
        unique.append(p)
    points = unique

    if not points:
        print("{0:.15f}".format(min_single))
        return

    # Compute convex hull
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]
    if not hull:
        hull = [points[0]]

    min_two = float('inf')
    for i in range(len(hull)):
        j = (i + 1) % len(hull)
        a_i, b_i = hull[i]
        a_j, b_j = hull[j]
        D = a_i * b_j - a_j * b_i
        if D == 0:
            continue
        t_i = (p * b_j - q * a_j) / D
        t_j = (q * a_i - p * b_i) / D
        if t_i >= -1e-9 and t_j >= -1e-9:
            total = t_i + t_j
            if total < min_two:
                min_two = total

    result = min(min_single, min_two)
    print("{0:.15f}".format(result))

