class Edge:
    def __init__(self, to, rev, capacity, cost):
        self.to = to
        self.rev = rev
        self.capacity = capacity
        self.cost = cost

def add_edge(graph, fr, to, capacity, cost):
    graph[fr].append(Edge(to, len(graph[to]), capacity, cost))
    graph[to].append(Edge(fr, len(graph[fr])-1, 0, -cost))

def min_cost_flow(graph, s, t, max_flow):
    N = len(graph)
    res = 0
    h = [float('inf')] * N
    h[s] = 0
    for _ in range(N):
        update = False
        for v in range(N):
            if h[v] == float('inf'):
                continue
            for e in graph[v]:
                if e.capacity > 0 and h[e.to] > h[v] + e.cost:
                    h[e.to] = h[v] + e.cost
                    update = True
        if not update:
            break
    from heapq import heappush, heappop
    flow = 0
    while flow < max_flow:
        dist = [float('inf')] * N
        dist[s] = 0
        prevv = [-1] * N
        preve = [-1] * N
        heap = []
        heappush(heap, (0, s))
        while heap:
            d, v = heappop(heap)
            if d > dist[v]:
                continue
            for i, e in enumerate(graph[v]):
                if e.capacity > 0 and dist[e.to] > d + e.cost + h[v] - h[e.to]:
                    dist[e.to] = d + e.cost + h[v] - h[e.to]
                    prevv[e.to] = v
                    preve[e.to] = i
                    heappush(heap, (dist[e.to], e.to))
        if dist[t] == float('inf'):
            break
        for v in range(N):
            if dist[v] < float('inf'):
                h[v] += dist[v]
        d = max_flow - flow
        v = t
        while v != s:
            d = min(d, graph[prevv[v]][preve[v]].capacity)
            v = prevv[v]
        if d == 0:
            break
        res += d * h[t]
        flow += d
        v = t
        while v != s:
            e = graph[prevv[v]][preve[v]]
            e.capacity -= d
            graph[v][e.rev].capacity += d
            v = prevv[v]
    return res, flow

