def is_coplanar(a, b, c, d):
    ab = (b[0]-a[0], b[1]-a[1], b[2]-a[2])
    ac = (c[0]-a[0], c[1]-a[1], c[2]-a[2])
    ad = (d[0]-a[0], d[1]-a[1], d[2]-a[2])
    cx = ab[1]*ac[2] - ab[2]*ac[1]
    cy = ab[2]*ac[0] - ab[0]*ac[2]
    cz = ab[0]*ac[1] - ab[1]*ac[0]
    dot = cx * ad[0] + cy * ad[1] + cz * ad[2]
    return dot == 0

def project_point(p, normal):
    nx, ny, nz = abs(normal[0]), abs(normal[1]), abs(normal[2])
    if nx >= ny and nx >= nz:
        return (p[1], p[2])
    elif ny >= nz:
        return (p[0], p[2])
    else:
        return (p[0], p[1])

def point_in_2d_triangle(p_proj, a_proj, b_proj, c_proj):
    def cross_sign(o, v1, v2):
        return (v1[0]-o[0])*(v2[1]-o[1]) - (v1[1]-o[1])*(v2[0]-o[0])
    s1 = cross_sign(a_proj, b_proj, p_proj)
    s2 = cross_sign(b_proj, c_proj, p_proj)
    s3 = cross_sign(c_proj, a_proj, p_proj)
    return (s1 >= 0 and s2 >= 0 and s3 >= 0) or (s1 <= 0 and s2 <= 0 and s3 <= 0)

def is_point_in_triangle(p, a, b, c):
    if not is_coplanar(a, b, c, p):
        return False
    vec1 = (b[0]-a[0], b[1]-a[1], b[2]-a[2])
    vec2 = (c[0]-a[0], c[1]-a[1], c[2]-a[2])
    normal = (
        vec1[1]*vec2[2] - vec1[2]*vec2[1],
        vec1[2]*vec2[0] - vec1[0]*vec2[2],
        vec1[0]*vec2[1] - vec1[1]*vec2[0]
    )
    a_proj = project_point(a, normal)
    b_proj = project_point(b, normal)
    c_proj = project_point(c, normal)
    p_proj = project_point(p, normal)
    return point_in_2d_triangle(p_proj, a_proj, b_proj, c_proj)

