        for frisbee in frisbees:
            fx, fy, fvx, fvy = frisbee
            t_list = []
            for i in range(N):
                dog = dogs[i]
                dx = fx - dog[0]
                dy = fy - dog[1]
                Vi = dog[2]
                a = Vi ** 2 - (fvx ** 2 + fvy ** 2)
                b = -2 * (dx * fvx + dy * fvy)
                c = -(dx ** 2 + dy ** 2)
                t_i = float('inf')
                epsilon = 1e-8

                if abs(a) < epsilon:
                    if abs(b) < epsilon:
                        if abs(c) < epsilon:
                            t_i = 0.0
                    else:
                        candidate = -c / b
                        if candidate >= -1e-12:
                            if candidate < 0:
                                candidate = 0.0
                            t_i = candidate
                else:
                    discriminant = b ** 2 - 4 * a * c
                    if discriminant >= -1e-12:
                        discriminant = max(discriminant, 0)
                        sqrt_d = math.sqrt(discriminant)
                        roots = []
                        for root in [(-b + sqrt_d)/(2*a), (-b - sqrt_d)/(2*a)]:
                            if root >= -1e-12:
                                if root < 0:
                                    root = 0.0
                                roots.append(root)
                        if roots:
                            t_i = min(roots)
                t_list.append(t_i)

            min_t = float('inf')
            min_index = -1
            for i in range(N):
                if t_list[i] < min_t:
                    min_t = t_list[i]
                    min_index = i
            counts[min_index] += 1

            for i in range(N):
                dog = dogs[i]
                current_x, current_y = dog[0], dog[1]
                t_i = t_list[i]
                if t_i == float('inf'):
                    continue
                if min_t < 1e-12:
                    new_x, new_y = current_x, current_y
                else:
                    if t_i < 1e-12:
                        new_x, new_y = current_x, current_y
                    else:
