def parse_input(s):
    dummy = []
    stack = [dummy]
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '[':
            new_list = []
            stack[-1].append(new_list)
            stack.append(new_list)
            i += 1
        elif s[i] == ']':
            stack.pop()
            i += 1
        elif s[i].isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            stack[-1].append([num])
            i = j
        else:
            i += 1
    return dummy[0]

def compute_min_votes(district):
    if len(district) == 1 and isinstance(district[0], int):
        c = district[0]
        return (c // 2) + 1
    else:
        sub_min = [compute_min_votes(sub) for sub in district]
        sub_min.sort()
        m = len(sub_min)
        required = (m // 2) + 1
        return sum(sub_min[:required])

