        for i in range(h):
            for j in range(w):
                c = grid[i][j]
                if c.isdigit():
                    d = int(c)
                    cells = set()
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            x = i + dx
                            y = j + dy
                            if 0<=x<h and 0<=y<w and grid[x][y] != '.':
                                cells.add((x,y))
                    constraints.append( {'d': d, 'cells': cells} )

        current_sum = 0
        forced_zero = set()
        forced_ones = set()
        changed = True
        while changed:
            changed = False
            new_constraints = []
            for c in constraints:
                d = c['d']
                cells = c['cells'].copy()
                cells -= forced_zero
                cells -= forced_ones
                if d ==0:
                    new_forced = cells.copy()
                    if new_forced:
                        forced_zero.update(new_forced)
                        changed = True
                elif len(cells) == d:
                    new_forced = cells.copy()
                    if new_forced:
                        current_sum += len(new_forced)
                        forced_ones.update(new_forced)
                        changed = True
                else:
                    new_constraints.append({'d':d, 'cells': cells})
            if not changed:
                break
            constraints = []
            for c in new_constraints:
                d = c['d']
                cells = c['cells'].copy()
                overlap = cells & forced_ones
                d -= len(overlap)
                cells -= forced_ones
                cells -= forced_zero
                if d <0 or (len(cells) ==0 and d !=0):
                    continue
                constraints.append({'d':d, 'cells':cells})

        variables_set = set()
        for c in constraints:
            variables_set.update(c['cells'])
        variables = list(variables_set)
        if not variables:
            print(current_sum)
            continue

        var_to_idx = {v:i for i,v in enumerate(variables)}
        var_constraints = [[] for _ in variables]
        for c_idx, c in enumerate(constraints):
            for v in c['cells']:
                var_idx = var_to_idx[v]
                var_constraints[var_idx].append(c_idx)

        constraint_vars = []
        for c in constraints:
            lst = []
            for v in c['cells']:
                if v in var_to_idx:
                    lst.append(var_to_idx[v])
            lst.sort()
            constraint_vars.append(lst)

        n = len(variables)
        m = len(constraints)
        best = [float('inf')]
        remaining_d = [c['d'] for c in constraints]

        def backtrack(idx, curr_sum, rem_d):
            if curr_sum >= best[0]:
                return
            if idx == n:
                for d in rem_d:
                    if d !=0:
                        return
                best[0] = curr_sum
                return

            v_idx = idx
            include = True
            new_rem = rem_d.copy()
            for c_idx in var_constraints[v_idx]:
                if new_rem[c_idx] <=0:
                    include = False
                    break
                new_rem[c_idx] -=1
            if include:
                valid = True
                for c_idx in var_constraints[v_idx]:
                    lst = constraint_vars[c_idx]
                    pos = bisect.bisect_left(lst, idx+1)
                    cnt = len(lst) - pos
                    if new_rem[c_idx] > cnt:
                        valid = False
                        break
                if valid:
                    backtrack(idx+1, curr_sum +1, new_rem)

            exclude = True
            valid = True
            for c_idx in var_constraints[v_idx]:
                lst = constraint_vars[c_idx]
                pos = bisect.bisect_left(lst, idx+1)
                cnt = len(lst) - pos
                if rem_d[c_idx] > cnt:
                    valid = False
                    break
            if valid:
                backtrack(idx+1, curr_sum, rem_d.copy())

        backtrack(0, 0, remaining_d)
        print(current_sum + best[0])

