        current_u, current_v = edges[i]
        temp_edges = edges[:i]
        adj = [[] for _ in range(N+1)]
        for a, b in temp_edges:
            adj[a].append(b)
            adj[b].append(a)

        case_a = False
        case_b = False

        # Check case a: 1 -> current_u, current_v -> 1, disjoint
        visited_u = {1}
        q = deque([1])
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited_u:
                    visited_u.add(neighbor)
                    q.append(neighbor)
        if current_u in visited_u:
            visited_v = {current_v}
            q = deque([current_v])
            found = False
            while q and not found:
                node = q.popleft()
                if node == 1:
                    found = True
                    break
                for neighbor in adj[node]:
                    if neighbor not in visited_v:
                        visited_v.add(neighbor)
                        q.append(neighbor)
