                if not intersection:
                    case_a = True

        # Check case b: 1 -> current_v, current_u -> 1, disjoint
        visited_v_caseb = {1}
        q = deque([1])
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited_v_caseb:
