    current_S = 0
    current_C = 0
    max_a = 0
    temp_T = T
    for ai in a:
        if temp_T >= ai:
            current_S += ai
            current_C += 1
            if ai > max_a:
                max_a = ai
            temp_T -= ai
    if current_C == 0:
