import sys
from collections import deque

def find_cycle(n, adj):
    visited = [False] * n
    parent = [-1] * n
    cycle = None

    def dfs(u, prev):
        nonlocal cycle
        visited[u] = True
        for v in adj[u]:
            if v == prev:
                continue
            if visited[v]:
                cycle = []
                current = u
                while current != v:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(v)
                return True
            parent[v] = u
            if dfs(v, u):
                return True
        return False

    for u in range(n):
        if not visited[u]:
            if dfs(u, -1):
                break

    cycle_edges = set()
    for i in range(len(cycle)):
        a = cycle[i]
        b = cycle[(i + 1) % len(cycle)]
        if a > b:
            a, b = b, a
        cycle_edges.add((a, b))
    return cycle_edges

def compute_max_sum(n, adj, skip_edge):
    skip_u, skip_v = skip_edge

    def bfs(start):
        visited = [False] * n
        q = deque([(start, 0)])
        visited[start] = True
        max_node, max_dist = start, 0
        while q:
            u, d = q.popleft()
            for v in adj[u]:
                if (u == skip_u and v == skip_v) or (u == skip_v and v == skip_u):
                    continue
                if not visited[v]:
                    visited[v] = True
                    q.append((v, d + 1))
                    if d + 1 > max_dist:
                        max_dist = d + 1
                        max_node = v
        return max_node, max_dist

    u, _ = bfs(0)
    v, _ = bfs(u)

    def sum_depths(root):
        visited = [False] * n
        q = deque([(root, 0)])
        visited[root] = True
        total = 0
        while q:
            node, depth = q.popleft()
            total += depth
            for neighbor in adj[node]:
                if (node == skip_u and neighbor == skip_v) or (node == skip_v and neighbor == skip_u):
                    continue
                if not visited[neighbor]:
                    visited[neighbor] = True
                    q.append((neighbor, depth + 1))
        return total

    sum_v = sum_depths(v)
    sum_u = sum_depths(u)
    return max(sum_u, sum_v)

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n)]
    edges = []
    for _ in range(n):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    cycle_edges = find_cycle(n, adj)
    max_sum = 0

    for edge in cycle_edges:
        current_sum = compute_max_sum(n, adj, edge)
        if current_sum > max_sum:
            max_sum = current_sum

    print(max_sum)

