                min_cost = e[2]
                selected_edge = e
        if selected_edge is None:
            return None
        min_in[v] = selected_edge

    # Check for cycles
    visited = {v: False for v in nodes}
    cycle = None
    for v in nodes:
        if v == root or visited[v]:
            continue
        path = []
        current = v
        while True:
            if visited[current]:
                if current in path:
                    idx = path.index(current)
                    cycle = path[idx:]
                    break
                else:
                    break
            visited[current] = True
            path.append(current)
            if current not in min_in:
                break
            current = min_in[current][0]
        if cycle:
            break

    if not cycle:
        total = sum(e[2] for e in min_in.values())
        return total

    # Contract the cycle
    sum_cycle = sum(min_in[v][2] for v in cycle)
    new_node = max(nodes) + 1
    cycle_set = set(cycle)

    # Build new edges
    new_edges = []
    for e in edges:
        u, v, c = e
        if v in cycle_set:
            new_cost = c - min_in[v][2]
            new_edges.append((u, new_node, new_cost))
        elif u in cycle_set and v not in cycle_set:
            new_edges.append((new_node, v, c))
        elif u not in cycle_set and v not in cycle_set:
            new_edges.append((u, v, c))

    new_nodes = [n for n in nodes if n not in cycle_set] + [new_node]

    res = min_arborescence(root, new_nodes, new_edges)
    if res is None:
        return None
    return sum_cycle + res


