import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n+1)]
    reverse_edges = [[] for _ in range(n+1)]
    out_degree = [0] * (n+1)
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        reverse_edges[v].append(u)
        out_degree[u] += 1
    s, t = map(int, sys.stdin.readline().split())

    if s == t:
        print(0)
        return

    # Compute safe nodes
    safe = [False] * (n+1)
    safe[t] = True
    queue = deque([t])
    unsafe_outgoing = [0] * (n+1)
    for u in range(1, n+1):
        unsafe_outgoing[u] = out_degree[u]
        if u == t:
            unsafe_outgoing[u] = 0  # t has no outgoing edges considered
    for u in range(1, n+1):
        if u == t:
            continue
        unsafe_outgoing[u] = out_degree[u]

    # Adjust unsafe_outgoing for t's neighbors
    for v in reverse_edges[t]:
        unsafe_outgoing[v] -= 1
        if unsafe_outgoing[v] == 0 and v != t:
            queue.append(v)
            safe[v] = True

    while queue:
        u = queue.popleft()
        for v in reverse_edges[u]:
            if safe[v]:
                continue
            unsafe_outgoing[v] -= 1
            if unsafe_outgoing[v] == 0:
                safe[v] = True
                queue.append(v)

    # BFS for minimal orders
    INF = float('inf')
    dist = [INF] * (n+1)
    dist[s] = 0
    dq = deque()
    dq.append((s, 0))
    visited = [False] * (n+1)

    while dq:
        u, cost = dq.popleft()
        if visited[u]:
            continue
        visited[u] = True
        if u == t:
            print(cost)
            return
        if out_degree[u] > 1 and not safe[u]:
            new_cost = cost + 1
        else:
            new_cost = cost
        for v in edges[u]:
            if dist[v] > new_cost:
                dist[v] = new_cost
                if new_cost == cost:
                    dq.appendleft((v, new_cost))
                else:
                    dq.append((v, new_cost))

    print(-1 if dist[t] == INF else dist[t])

