import bisect

class SegmentTree:
    def __init__(self, size):
        self.n = 1
        while self.n < size:
            self.n <<= 1
        self.tree = [-1] * (2 * self.n)

    def update(self, idx, value):
        idx += self.n
        if self.tree[idx] < value:
            self.tree[idx] = value
            idx >>= 1
            while idx >= 1:
                new_val = max(self.tree[2 * idx], self.tree[2 * idx + 1])
                if self.tree[idx] == new_val:
                    break
                self.tree[idx] = new_val
                idx >>= 1

    def query(self, l, r):
        res = -1
        l += self.n
        r += self.n
        while l <= r:
            if l % 2 == 1:
                res = max(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = max(res, self.tree[r])
                r -= 1
            l >>= 1
            r >>= 1
        return res

