import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    if N == 1:
        print(1)
        return
    adj = [[] for _ in range(N+1)]
    for _ in range(N-1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        visited = [-1] * (N+1)
        q = deque([start])
        visited[start] = 0
        max_dist, far_node = 0, start
        while q:
            u = q.popleft()
            for v in adj[u]:
                if visited[v] == -1:
                    visited[v] = visited[u] + 1
                    if visited[v] > max_dist:
                        max_dist, far_node = visited[v], v
                    q.append(v)
        return far_node, max_dist

    u, _ = bfs(1)
    v, _ = bfs(u)

    parent = [0]*(N+1)
    def get_path(u, v):
        visited = [False]*(N+1)
        q = deque([u])
        visited[u], parent[u] = True, -1
        while q:
            node = q.popleft()
            if node == v:
                break
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor], parent[neighbor] = True, node
                    q.append(neighbor)
        path = []
        current = v
        while current != -1:
            path.append(current)
            current = parent[current]
        path.reverse()
        return path

    path = get_path(u, v)
    path_set = set(path)
    L = len(path)

    distance = [-1]*(N+1)
    q = deque(path)
    for node in path:
        distance[node] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + 1
                q.append(v)

    dist_list = [distance[i] for i in range(1, N+1) if i not in path_set]
    dist_list.sort(reverse=True)
    prefix = [0]*(len(dist_list)+1)
    for i in range(len(dist_list)):
        prefix[i+1] = prefix[i] + dist_list[i]

    res = []
    for K in range(1, N+1):
        if K == 1:
            res.append(1)
        else:
            if K == 2:
                res.append(L)
            else:
                t = K-2
                if t <= 0:
                    res.append(L)
                else:
                    add = prefix[-1] if t > len(dist_list) else prefix[t]
                    res.append(min(L + add, N))
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    main()

