class Node:
    __slots__ = ['l', 'r', 'left', 'right', 'max']
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.max = 0

def build(l, r, A):
    node = Node(l, r)
    if l == r:
        node.max = A[l]
    else:
        mid = (l + r) // 2
        node.left = build(l, mid, A)
        node.right = build(mid + 1, r, A)
        node.max = max(node.left.max, node.right.max)
    return node

def update(node, idx, value):
    if node.l == node.r == idx:
        node.max = value
    else:
        if idx <= node.left.r:
            update(node.left, idx, value)
        else:
            update(node.right, idx, value)
        node.max = max(node.left.max, node.right.max)

def query_max(node, l, r):
    if node.r < l or node.l > r:
        return -float('inf')
    if l <= node.l and node.r <= r:
        return node.max
    return max(query_max(node.left, l, r), query_max(node.right, l, r))

def find_first_ge(node, X, V, N):
    stack = [node]
    result = N + 1
    while stack:
        current = stack.pop()
        if current.r < X:
            continue
        if current.max < V:
            continue
        if current.l == current.r:
            result = current.l
            break
        stack.append(current.right)
        stack.append(current.left)
    return result

