import re

def convert_identifier(name, target_type):
    if '_' in name:
        words = name.split('_')
    else:
        spaced = re.sub(r'([A-Z])', r' \1', name)
        words = [word.lower() for word in spaced.split()]

    if target_type == 'U':
        return ''.join(word.capitalize() for word in words)
    elif target_type == 'L':
        if not words:
            return ''
        return words[0].lower() + ''.join(word.capitalize() for word in words[1:])
    elif target_type == 'D':
        return '_'.join(words)
    return ''

