import sys

def process_board(H, board):
    total_score = 0
    while True:
        marked = [[False]*5 for _ in range(H)]
        # Step 1: Mark stones to disappear
        for row in range(H):
            i = 0
            while i < 5:
                current = board[row][i]
                j = i
                while j < 5 and board[row][j] == current:
                    j += 1
                if j - i >= 3:
                    for k in range(i, j):
                        marked[row][k] = True
                i = j
        # Check if any marked
        if not any(any(row) for row in marked):
            break
        # Sum the marked stones
        current_sum = 0
        for row in range(H):
            for col in range(5):
                if marked[row][col]:
                    current_sum += board[row][col]
        total_score += current_sum
        # Step 2: Drop stones
        for col in range(5):
            collected = []
            for row in reversed(range(H)):
                if not marked[row][col]:
                    collected.append(board[row][col])
            # Create new_col
            new_col = [0] * H
            for i in range(len(collected)):
                new_col[H - 1 - i] = collected[i]
            # Update the board
            for row in range(H):
                board[row][col] = new_col[row]
    return total_score

