import math

def euler_phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n = n // p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def get_divisors(n):
    if n == 0:
        return []
    factors = {}
    temp = n
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp = temp // i
        i += 1
    if temp > 1:
        factors[temp] = 1
    divisors = [1]
    for p in factors:
        exponents = [p**e for e in range(1, factors[p]+1)]
        new_divisors = []
        for d in divisors:
            for exp in exponents:
                new_divisors.append(d * exp)
        divisors += new_divisors
    divisors = list(set(divisors))
    divisors.sort()
    return divisors

def multiplicative_order(a, n):
    if math.gcd(a, n) != 1:
        return 0
    phi_val = euler_phi(n)
    divisors = get_divisors(phi_val)
    for d in sorted(divisors):
        if pow(a, d, n) == 1:
            return d
    return phi_val  # Should not reach here

