from collections import deque, defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    max_a = 200000
    spf = list(range(max_a + 1))
    for i in range(2, int(max_a ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_nodes = defaultdict(list)
    for idx in range(n):
        x = a[idx]
        if x == 1:
            continue
        tmp = x
        primes = set()
        while tmp != 1:
            p = spf[tmp]
            primes.add(p)
            while tmp % p == 0:
                tmp //= p
        for p in primes:
            prime_nodes[p].append(idx + 1)

    max_diameter = 0
    for p, nodes in prime_nodes.items():
        nodes_p = set(nodes)
        if not nodes_p:
            continue
        visited = [False] * (n + 1)
        current_max = 0
        for u in nodes:
            if not visited[u]:
                q = deque([(u, 1)])
                visited[u] = True
                farthest_node = u
                max_dist = 1
                while q:
                    v, d = q.popleft()
                    if d > max_dist:
                        max_dist = d
                        farthest_node = v
                    for neighbor in adj[v]:
                        if neighbor in nodes_p and not visited[neighbor]:
                            visited[neighbor] = True
                            q.append((neighbor, d + 1))
                visited2 = [False] * (n + 1)
                q = deque([(farthest_node, 1)])
                visited2[farthest_node] = True
                max_d = 1
                while q:
                    v, d = q.popleft()
                    if d > max_d:
                        max_d = d
                    for neighbor in adj[v]:
                        if neighbor in nodes_p and not visited2[neighbor]:
                            visited2[neighbor] = True
                            q.append((neighbor, d + 1))
                current_max = max(current_max, max_d)
        if current_max > max_diameter:
            max_diameter = current_max
    print(max_diameter if max_diameter != 0 else 0)

