import math
from itertools import combinations

def lcm(a, b):
    return a * b // math.gcd(a, b)

def get_divisors(m):
    divisors = set()
    for i in range(1, int(math.isqrt(m)) + 1):
        if m % i == 0:
            if i >= 3:
                divisors.add(i)
            if (m // i) >= 3:
                divisors.add(m // i)
    return sorted(divisors)

def inclusion_exclusion(divisors, n):
    total = 0
    for i in range(1, len(divisors) + 1):
        for subset in combinations(divisors, i):
            current_lcm = 1
            for num in subset:
                current_lcm = lcm(current_lcm, num)
                if current_lcm > n:
                    break
            if current_lcm > n:
                continue
            cnt = (n // current_lcm) - (2 // current_lcm)
            if i % 2 == 1:
                total += cnt
            else:
                total -= cnt
    return total

