        factors = {}
        for p in primes:
            if p * p > temp:
                break
            if temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                factors[p] = cnt
            if temp == 1:
                break
        if temp > 1:
            factors[temp] = 1
        factors_list[x] = factors

    total = 0
    for i in range(1, a + 1):
        i_factors = factors_list[i]
        for j in range(1, b + 1):
            j_factors = factors_list[j]
            for k in range(1, c + 1):
                k_factors = factors_list[k]
                merged = {}
