import sys
from collections import deque

sys.setrecursionlimit(1 << 25)

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    q = deque()
    q.append(1)
    parent[1] = -1
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v != parent[u] and parent[v] == 0:
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    LOG = 20
    up = [[-1]*(n+1) for _ in range(LOG)]
    up[0] = parent[:]
    for k in range(1, LOG):
        for v in range(1, n+1):
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
            else:
                up[k][v] = -1

    def lift(node, k):
        current = node
        for i in range(LOG):
            if (k >> i) & 1:
                if current == -1:
                    return -1
                current = up[i][current]
        return current

    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        a = lift(a, depth[a] - depth[b])
        if a == b:
            return a
        for i in reversed(range(LOG)):
            if up[i][a] != up[i][b]:
                a = up[i][a]
                b = up[i][b]
        return parent[a]

    size = [1]*(n+1)
    stack = [(1, False)]
    while stack:
        node, visited = stack.pop()
        if visited:
            for v in adj[node]:
                if v != parent[node]:
                    size[node] += size[v]
        else:
            stack.append((node, True))
            for v in reversed(adj[node]):
                if v != parent[node]:
                    stack.append((v, False))

    m = int(sys.stdin.readline())
    for _ in range(m):
        x, y = map(int, sys.stdin.readline().split())
        if x == y:
            print(1)
            continue
        l = lca(x, y)
        a = depth[x] - depth[l]
        b = depth[y] - depth[l]
        D = a + b
        if D % 2 != 0:
            print(0)
            continue
        k = D // 2
        if k <= a:
            mid_node = lift(x, k)
        else:
            mid_node = lift(y, (b - (k - a)))

        u, v = None, None
        if x != mid_node:
            steps_x = depth[x] - (depth[mid_node] + 1)
            u = lift(x, steps_x)
        if y != mid_node:
            steps_y = depth[y] - (depth[mid_node] + 1)
            v = lift(y, steps_y)

        ans = size[mid_node]
        if u is not None and parent[u] == mid_node:
            ans -= size[u]
        if v is not None and parent[v] == mid_node:
            ans -= size[v]
        print(ans)

