import sys
from collections import defaultdict, deque

def is_dag(adj, n):
    in_degree = [0] * (n + 1)
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1
    queue = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            queue.append(i)
    count = 0
    while queue:
        u = queue.popleft()
        count += 1
        for v in adj.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return count == n

def kosaraju(adj, n):
    visited = [False] * (n + 1)
    order = []
    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in reversed(adj.get(node, [])):
                if not visited[v]:
                    stack.append((v, False))
    for u in range(1, n+1):
        if not visited[u]:
            dfs(u)
    reversed_adj = defaultdict(list)
    for u in adj:
        for v in adj[u]:
            reversed_adj[v].append(u)
    visited = [False] * (n + 1)
    sccs = []
    for u in reversed(order):
        if not visited[u]:
            stack = [u]
            visited[u] = True
            scc = []
            while stack:
                node = stack.pop()
                scc.append(node)
                for v in reversed_adj.get(node, []):
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            sccs.append(scc)
    return sccs

def find_cycle_edges(adj, nodes):
    visited = {node: 0 for node in nodes}
    parent = {}
    stack = []
    cycle_nodes = []
    found = False
    def dfs(u):
        nonlocal found
        visited[u] = 1
        stack.append(u)
        for v in adj.get(u, []):
            if v not in visited:
                continue
            if visited[v] == 1:
                idx = stack.index(v)
                cycle_nodes.extend(stack[idx:] + [v])
                found = True
                return
            elif visited[v] == 0:
                parent[v] = u
                dfs(v)
                if found:
                    return
        visited[u] = 2
        stack.pop()
    for node in nodes:
        if visited[node] == 0 and not found:
            dfs(node)
            if found:
                break
    if not found:
        return []
    edges = []
    for i in range(len(cycle_nodes) - 1):
        edges.append((cycle_nodes[i], cycle_nodes[i+1]))
    return edges

def is_acyclic(temp_adj, nodes):
    in_degree = defaultdict(int)
    for u in temp_adj:
        for v in temp_adj[u]:
            in_degree[v] += 1
    queue = deque()
    for node in nodes:
        if in_degree.get(node, 0) == 0:
            queue.append(node)
    count = 0
    while queue:
        u = queue.popleft()
        count += 1
        for v in temp_adj.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return count == len(nodes)

def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    if is_dag(adj, n):
        print("YES")
        return
    sccs = kosaraju(adj, n)
    cyclic_sccs = [scc for scc in sccs if len(scc) >= 2]
    if len(cyclic_sccs) > 1:
        print("NO")
        return
    component_nodes = cyclic_sccs[0] if cyclic_sccs else []
    if not component_nodes:
        print("YES")
        return
    component_edges = [ (u, v) for u, v in edges if u in component_nodes and v in component_nodes ]
    component_adj = defaultdict(list)
    for u, v in component_edges:
        component_adj[u].append(v)
    cycle_edges = find_cycle_edges(component_adj, component_nodes)
    if not cycle_edges:
        print("NO")
        return
    for u, v in cycle_edges:
        temp_adj = defaultdict(list)
        for a in component_adj:
            for b in component_adj[a]:
                if not (a == u and b == v):
                    temp_adj[a].append(b)
        if is_acyclic(temp_adj, component_nodes):
            print("YES")
            return
    print("NO")

