    main()

MOD = 10**9 + 7

def main():
    import sys
    R, a1, a2, a3, a4 = map(int, sys.stdin.readline().split())
    sum_a = a1 + a2 + a3 + a4
    sum_a_mod = sum_a % MOD

    # Generate all states (x, y) with x² + y² <= R²
    states = []
    for x in range(-R, R + 1):
        max_y = int((R**2 - x**2)**0.5)
        for y in range(-max_y, max_y + 1):
            if x**2 + y**2 <= R**2:
                states.append((x, y))
    n = len(states)
    states_dict = {(x, y): i for i, (x, y) in enumerate(states)}

    # Build augmented matrix
    aug = [[0] * (n + 1) for _ in range(n)]
    for i in range(n):
        x, y = states[i]
        # Equation: sum_a * E[i] - a1*E_left - a2*E_down - a3*E_right - a4*E_up = sum_a
        aug[i][i] = sum_a_mod
        aug[i][-1] = sum_a_mod  # RHS is sum_a
        for dx, dy, a in [(-1, 0, a1), (0, -1, a2), (1, 0, a3), (0, 1, a4)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in states_dict:
                j = states_dict[(nx, ny)]
                aug[i][j] = (aug[i][j] - a) % MOD

    # Gaussian elimination modulo MOD
    for col in range(n):
        # Find pivot
        pivot = None
        for row in range(col, n):
            if aug[row][col] != 0:
                pivot = row
                break
        if pivot is None:
            continue
        aug[col], aug[pivot] = aug[pivot], aug[col]
        # Compute inverse of pivot element
        inv = pow(aug[col][col], MOD - 2, MOD)
        # Normalize pivot row
        for j in range(col, n + 1):
            aug[col][j] = (aug[col][j] * inv) % MOD
        # Eliminate other rows
        for row in range(n):
            if row != col and aug[row][col] != 0:
                factor = aug[row][col]
                for j in range(col, n + 1):
                    aug[row][j] = (aug[row][j] - factor * aug[col][j]) % MOD

    # Find the solution for (0, 0)
    idx = states_dict.get((0, 0), -1)
    if idx == -1:
        print(0)
    else:
        res = aug[idx][-1] % MOD
        print(res)

