        if cmd_type == 'forward':
            arg = parts[1]
            if arg == 'char':
                if pos < len(buffer):
                    pos += 1
            elif arg == 'word':
                n = len(buffer)
                s = pos
                while s < n and buffer[s] == ' ':
                    s += 1
                if s >= n:
                    pos = n
                else:
                    e = s
                    while e < n and buffer[e] != ' ':
                        e += 1
                    pos = e

        elif cmd_type == 'backward':
            arg = parts[1]
            if arg == 'char':
                if pos > 0:
                    pos -= 1
            elif arg == 'word':
                if pos == 0:
                    continue
                n = len(buffer)
                e = pos - 1
                while e >= 0 and buffer[e] == ' ':
                    e -= 1
                if e < 0:
                    pos = 0
                else:
                    s = e
                    while s >= 0 and buffer[s] != ' ':
                        s -= 1
                    pos = s + 1

        elif cmd_type == 'insert':
            insert_text = parts[1].strip('"')
            inserted = list(insert_text)
            buffer[pos:pos] = inserted
            pos += len(inserted)

        elif cmd_type == 'delete':
            arg = parts[1]
            if arg == 'char':
                if pos < len(buffer):
                    del buffer[pos]
            elif arg == 'word':
                n = len(buffer)
                if n == 0:
                    continue
                s = pos
                while s < n and buffer[s] == ' ':
                    s += 1
                if s < n:
                    e = s
                    while e < n and buffer[e] != ' ':
                        e += 1
                    del buffer[pos:e]
                    if pos > len(buffer):
                        pos = len(buffer)

    left = ''.join(buffer[:pos])
    right = ''.join(buffer[pos:])
    print(f"{left}^{right}")

