                    if b <= s - 1:
                        if new_dp[a][e] < current_val + w:
                            new_dp[a][e] = current_val + w
            dp = new_dp
        # Find the maximum value in dp
        max_val = 0
        for row in dp:
            current_max = max(row)
            if current_max > max_val:
