class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_matching(s, start):
    count = 0
    for i in range(start, len(s)):
        if s[i] == '(':
            count += 1
        elif s[i] == ')':
            count -= 1
            if count == 0:
                return i
    return -1  # According to problem statement, input is valid

def parse_tree(s):
    if not s:
        return None
    left_end = find_matching(s, 0)
    left_str = s[1:left_end]
    remaining = s[left_end+1:]
    val_start = remaining.find('[') + 1
    val_end = remaining.find(']')
    val = int(remaining[val_start:val_end])
    remaining_after_val = remaining[val_end+1:]
    right_str = ""
    if remaining_after_val.startswith('('):
        right_end = find_matching(remaining_after_val, 0)
        right_str = remaining_after_val[1:right_end]
    left_child = parse_tree(left_str) if left_str else None
    right_child = parse_tree(right_str) if right_str else None
    return Node(val, left_child, right_child)

def combine(a, b):
    if a is None or b is None:
        return None
    new_val = a.val + b.val
    new_left = combine(a.left, b.left) if (a.left and b.left) else None
    new_right = combine(a.right, b.right) if (a.right and b.right) else None
    return Node(new_val, new_left, new_right)

def to_string(node):
    if node is None:
        return ""
    left_str = to_string(node.left)
    right_str = to_string(node.right)
    return f"({left_str}) [{node.val}] ({right_str})"

