import sys
from collections import defaultdict

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    intervals = []
    for _ in range(m):
        l, r, c = map(int, sys.stdin.readline().split())
        intervals.append((l, r, c))

    # Preprocess intervals to keep minimal cost for each (l, r)
    interval_map = defaultdict(lambda: float('inf'))
    for l, r, c in intervals:
        if c < interval_map[(l, r)]:
            interval_map[(l, r)] = c

    # For each l, find the best interval (max r, min cost)
    best_l = defaultdict(lambda: (-1, float('inf')))  # key is l, value is (r, cost)
    for (l, r), c in interval_map.items():
        current_r, current_c = best_l[l]
        if r > current_r or (r == current_r and c < current_c):
            best_l[l] = (r, c)

    # Initialize DP: dp[j][r] = minimal cost to cover j holes up to position r
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    ans = INF

    for j_prev in range(k + 1):
        for r_prev in range(n + 1):
            current_cost = dp[j_prev][r_prev]
            if current_cost == INF:
                continue

            # Process intervals starting at l <= r_prev + 1
            for l in range(1, r_prev + 2):
                if l not in best_l:
                    continue
                r_interval, c = best_l[l]
                start = max(l, r_prev + 1)
                if start > r_interval:
                    new_j = j_prev
                    new_r = r_prev
                else:
                    added = r_interval - start + 1
                    new_j = j_prev + added
                    new_r = r_interval
                if new_j > k:
                    new_j = k
                new_cost = current_cost + c
                if new_j >= k:
                    if new_cost < ans:
                        ans = new_cost
                else:
                    if new_r <= n and new_cost < dp[new_j][new_r]:
                        dp[new_j][new_r] = new_cost

            # Process intervals starting at l > r_prev + 1
            for l in best_l:
                if l > r_prev + 1:
                    r_interval, c = best_l[l]
                    added = r_interval - l + 1
                    new_j = j_prev + added
                    new_r = r_interval
                    if new_j > k:
                        new_j = k
                    new_cost = current_cost + c
                    if new_j >= k:
                        if new_cost < ans:
                            ans = new_cost
                    else:
                        if new_r <= n and new_j <= k and new_cost < dp[new_j][new_r]:
                            dp[new_j][new_r] = new_cost

    # Check for states where j >= k in the DP table
    for j in range(k, k + 1):
        for r in range(n + 1):
            if dp[j][r] < ans:
                ans = dp[j][r]

    print(ans if ans != INF else -1)

