# Check strong connectivity using Kosaraju's algorithm
def is_strongly_connected(adj, n):
    visited = [False] * n
    order = []

    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in reversed(adj[node]):
                if not visited[v]:
                    stack.append((v, False))

    for u in range(n):
        if not visited[u]:
            dfs(u)

    reversed_adj = [[] for _ in range(n)]
    for u in range(n):
        for v in adj[u]:
            reversed_adj[v].append(u)

    visited = [False] * n
    components = 0

    def reverse_dfs(u):
        stack = [u]
        visited[u] = True
        while stack:
            node = stack.pop()
            for v in reversed_adj[node]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)

    while order:
        u = order.pop()
        if not visited[u]:
            components += 1
            reverse_dfs(u)
            if components > 1:
                return False
    return components == 1

