import math
import random

def is_inside(circle, point):
    if circle is None:
        return False
    cx, cy, r = circle
    dx = point[0] - cx
    dy = point[1] - cy
    return dx*dx + dy*dy <= r*r + 1e-8

def circle_from_two(a, b):
    cx = (a[0] + b[0]) / 2.0
    cy = (a[1] + b[1]) / 2.0
    r = math.hypot(a[0]-b[0], a[1]-b[1]) / 2.0
    return (cx, cy, r)

def circle_from_three(a, b, c):
    area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    if area == 0:
        d1_sq = (a[0]-b[0])**2 + (a[1]-b[1])**2
        d2_sq = (a[0]-c[0])**2 + (a[1]-c[1])**2
        d3_sq = (b[0]-c[0])**2 + (b[1]-c[1])**2
        max_d = max(d1_sq, d2_sq, d3_sq)
        if max_d == d1_sq:
            return circle_from_two(a, b)
        elif max_d == d2_sq:
            return circle_from_two(a, c)
        else:
            return circle_from_two(b, c)
    else:
        x1, y1 = a
        x2, y2 = b
        x3, y3 = c
        A = x2 - x1
        B = y2 - y1
        C = x3 - x1
        D = y3 - y1
        E = A*(x1 + x2) + B*(y1 + y2)
        F = C*(x1 + x3) + D*(y1 + y3)
        G = 2*(A*(y3 - y2) - B*(x3 - x2))
        if G == 0:
            return circle_from_two(a, b)
        cx = (D*E - B*F) / G
        cy = (A*F - C*E) / G
        r = math.hypot(cx - x1, cy - y1)
        return (cx, cy, r)

def circle_from_points(support):
    if not support:
        return (0.0, 0.0, 0.0)
    elif len(support) == 1:
        return (support[0][0], support[0][1], 0.0)
    elif len(support) == 2:
        return circle_from_two(support[0], support[1])
    else:
        return circle_from_three(support[0], support[1], support[2])

def minimal_enclosing_circle(points):
    if not points:
        return (0.0, 0.0, 0.0)
    shuffled = list(points)
    random.shuffle(shuffled)
    support = []
    circle = None
    for p in shuffled:
        if circle is None or not is_inside(circle, p):
            support.append(p)
            new_circle = circle_from_points(support)
            i = 0
            while i < len(support):
                temp_support = support[:i] + support[i+1:]
                if not temp_support:
                    temp_circle = (0.0, 0.0, 0.0)
                else:
                    temp_circle = circle_from_points(temp_support)
                valid = True
                for s in support:
                    if not is_inside(temp_circle, s):
                        valid = False
                        break
                if valid:
                    support = temp_support
                    new_circle = temp_circle
                    i = 0
                else:
                    i += 1
            circle = new_circle
    return circle

def check_case(inside_points, outside_points):
    if not inside_points:
        return False
    circle = minimal_enclosing_circle(inside_points)
    cx, cy, r = circle
    r_squared = r*r
    for (x, y) in outside_points:
        dx = x - cx
        dy = y - cy
        dist_sq = dx*dx + dy*dy
        if dist_sq <= r_squared + 1e-8:
            return False
    return True

