import sys
import math
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, q = int(input[ptr]), int(input[ptr+1])
    ptr += 2
    a = list(map(int, input[ptr:ptr+n]))
    ptr += n

    queries = []
    for i in range(q):
        t = int(input[ptr])
        if t == 1:
            l = int(input[ptr+1]) - 1
            r = int(input[ptr+2]) - 1
            queries.append((t, l, r, i))
        else:
            p = int(input[ptr+1]) - 1
            x = int(input[ptr+2])
            queries.append((t, p, x, i))
        ptr += 3

    block_size = int(math.sqrt(n)) + 1

    mo_queries = [query for query in queries if query[0] == 1]
    mo_queries.sort(key=lambda x: (x[1] // block_size, x[2] if (x[1] // block_size) % 2 == 0 else -x[2]))

    current_l = 0
    current_r = -1
    freq = defaultdict(int)
    cnt = defaultdict(int)
    max_freq = n

    class BIT:
        def __init__(self, size):
            self.N = size + 2
            self.tree = [0] * (self.N)

        def update(self, idx, delta):
            idx += 1
            while idx < self.N:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            idx += 1
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    bit = BIT(max_freq)
    cnt = defaultdict(int)
    present = defaultdict(int)

    def add(x):
        nonlocal cnt, present, bit
        prev_f = freq[x]
        if prev_f > 0:
            cnt[prev_f] -= 1
            if cnt[prev_f] == 0:
                if present[prev_f]:
                    present[prev_f] = 0
                    bit.update(prev_f, -1)
        freq[x] += 1
        new_f = prev_f + 1
        cnt[new_f] += 1
        if cnt[new_f] == 1:
            if not present[new_f]:
                present[new_f] = 1
                bit.update(new_f, 1)

    def remove(x):
        nonlocal cnt, present, bit
        prev_f = freq[x]
        cnt[prev_f] -= 1
        if cnt[prev_f] == 0:
            if present[prev_f]:
                present[prev_f] = 0
                bit.update(prev_f, -1)
        freq[x] -= 1
        new_f = prev_f - 1
        if new_f > 0:
            cnt[new_f] += 1
            if cnt[new_f] == 1:
                if not present[new_f]:
                    present[new_f] = 1
                    bit.update(new_f, 1)
        if new_f == 0:
            del freq[x]

    def get_mex():
        low = 1
        high = max_freq
        mex = 1
        while low <= high:
            mid = (low + high) // 2
            total = bit.query(mid)
            if total < mid:
                mex = mid
                high = mid - 1
            else:
                low = mid + 1
        return mex

    res = [0] * q
    updates = []
    current_time = 0
    original = a.copy()
    for query in queries:
        if query[0] == 2:
            updates.append((query[1], query[2], query[3]))

    ptr = 0
    for query in mo_queries:
        t, l, r, idx = query
        while current_time <= idx:
            qq = queries[current_time]
            if qq[0] == 2:
                p, x, _ = qq[1], qq[2], qq[3]
                if current_l <= p <= current_r:
                    remove(original[p])
                original[p] = x
                if current_l <= p <= current_r:
                    add(original[p])
            current_time += 1

        while current_l > l:
            current_l -= 1
            add(original[current_l])
        while current_r < r:
            current_r += 1
            add(original[current_r])
        while current_l < l:
            remove(original[current_l])
            current_l += 1
        while current_r > r:
            remove(original[current_r])
            current_r -= 1
        mex = get_mex()
        res[idx] = mex

    for query in queries:
        if query[0] == 1:
            print(res[query[3]])

