def is_point_on_segment(p, a, b):
    cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
    if cross != 0:
        return False
    return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

def orientation(a, b, c):
    val = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    if val > 0:
        return 1
    elif val < 0:
        return 2
    else:
        return 0

def segments_intersect(a1, a2, b1, b2):
    if (is_point_on_segment(a1, b1, b2) or is_point_on_segment(a2, b1, b2) or
        is_point_on_segment(b1, a1, a2) or is_point_on_segment(b2, a1, a2)):
        return True
    o1 = orientation(a1, a2, b1)
    o2 = orientation(a1, a2, b2)
    o3 = orientation(b1, b2, a1)
    o4 = orientation(b1, b2, a2)
    return (o1 != o2 and o3 != o4)

def point_in_polygon(p, polygon):
    x, y = p
    inside = False
    n = len(polygon)
    for i in range(n):
        a, b = polygon[i], polygon[(i+1) % n]
        if is_point_on_segment(p, a, b):
            return True
        ay, by = a[1], b[1]
        if (ay > y) != (by > y):
            dx = b[0] - a[0]
            dy = by - ay
            if dy == 0:
                continue
            t = (y - ay) / dy
            x_intersect = a[0] + t * dx
            if x < x_intersect:
                inside = not inside
    return inside

