class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.p = None

def insert(root, z):
    y = None
    x = root
    while x is not None:
        y = x
        if z.key < x.key:
            x = x.left
        else:
            x = x.right
    z.p = y
    if y is None:
        root = z
    else:
        if z.key < y.key:
            y.left = z
        else:
            y.right = z
    return root

def inorder(root):
    res = []
    if root:
        res += inorder(root.left)
        res.append(root.key)
        res += inorder(root.right)
    return res

def preorder(root):
    res = []
    if root:
        res.append(root.key)
        res += preorder(root.left)
        res += preorder(root.right)
    return res

