def is_alphabetical(s):
    n = len(s)
    required = set(chr(ord('a') + i) for i in range(n))
    if set(s) != required:
        return False
    dq = deque(s)
    for i in range(n, 0, -1):
        target = chr(ord('a') + i - 1)
        if not dq:
            return False
        if dq[0] == target:
            dq.popleft()
        elif dq[-1] == target:
            dq.pop()
        else:
            return False
    return True

