from collections import defaultdict

def compute_factorial(a, max_S):
    res = 1
    for i in range(1, a+1):
        res *= i
        if res > max_S:
            return None
    return res

def generate_combinations(group, S):
    count = defaultdict(int)
    n = len(group)
    pre = []
    for a in group:
        fact = compute_factorial(a, S)
        pre.append((a, fact))
    stack = [(0, 0, 0, False)]
    while stack:
        index, current_sum, current_t, has_selected = stack.pop()
        if index == n:
            if has_selected:
                count[(current_sum, current_t)] += 1
            continue
        a, fact = pre[index]
        stack.append((index + 1, current_sum, current_t, has_selected))
        stack.append((index + 1, current_sum + a, current_t, True))
        if fact is not None:
            stack.append((index + 1, current_sum + fact, current_t + 1, True))
    return count

