import re

class SimpleWidget:
    def __init__(self, name, width, height):
        self.name = name
        self.width = width
        self.height = height

    def compute_size(self, widgets_dict):
        return (self.width, self.height)

class HBoxWidget:
    def __init__(self, name):
        self.name = name
        self.children = []
        self.border = 0
        self.spacing = 0

    def compute_size(self, widgets_dict):
        if not self.children:
            return (0, 0)
        total_width = 0
        max_height = 0
        for child_name in self.children:
            child = widgets_dict[child_name]
            cw, ch = child.compute_size(widgets_dict)
            total_width += cw
            if ch > max_height:
                max_height = ch
        total_width += (len(self.children) - 1) * self.spacing
        total_width += 2 * self.border
        max_height += 2 * self.border
        return (total_width, max_height)

class VBoxWidget:
    def __init__(self, name):
        self.name = name
        self.children = []
        self.border = 0
        self.spacing = 0

    def compute_size(self, widgets_dict):
        if not self.children:
            return (0, 0)
        total_height = 0
        max_width = 0
        for child_name in self.children:
            child = widgets_dict[child_name]
            cw, ch = child.compute_size(widgets_dict)
            total_height += ch
            if cw > max_width:
                max_width = cw
        total_height += (len(self.children) - 1) * self.spacing
        total_height += 2 * self.border
        max_width += 2 * self.border
        return (max_width, total_height)

