import math

def find_identification_string(N, M):
    sum_before = 0
    k = 0
    while True:
        current_count = math.comb(N, k)
        if sum_before + current_count >= M:
            break
        sum_before += current_count
        k += 1
    idx = M - sum_before - 1
    res = []
    remaining_ones = k
    for pos in range(N):
        if remaining_ones == 0:
            res.append('0')
            continue
        possible_zeros = math.comb(N - pos - 1, remaining_ones)
        if idx < possible_zeros:
            res.append('0')
        else:
            res.append('1')
            idx -= possible_zeros
            remaining_ones -= 1
    return ''.join(res)

