import sys

def is_connected(mask, W, H, start_idx, end_idx):
    if not (mask & (1 << start_idx)) or not (mask & (1 << end_idx)):
        return False
    visited = set()
    queue = deque()
    start_x = start_idx % W
    start_y = start_idx // W
    queue.append((start_x, start_y))
    visited.add((start_x, start_y))
    found_end = False
    while queue:
        x, y = queue.popleft()
        current_idx = y * W + x
        if current_idx == end_idx:
            found_end = True
            break
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < W and 0 <= ny < H:
                idx = ny * W + nx
                if (mask & (1 << idx)) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
    return found_end

def main():
    W, H, S = map(int, sys.stdin.readline().split())
    K = W * H - S
    if K < 2:
        print(0)
        return
    start_x, start_y = 0, 0
    end_x, end_y = W-1, H-1
    start_idx = start_y * W + start_x
    end_idx = end_y * W + end_x
    if K == 2:
        if (abs(start_x - end_x) + abs(start_y - end_y)) == 1:
            print(1)
        else:
            print(0)
        return
    initial_mask = (1 << start_idx) | (1 << end_idx)
    visited = set()
    queue = deque()
    queue.append(initial_mask)
    visited.add(initial_mask)
    count = 0
    while queue:
        mask = queue.popleft()
        current_size = bin(mask).count('1')
        if current_size == K:
            if is_connected(mask, W, H, start_idx, end_idx):
                count += 1
            continue
        elif current_size > K:
            continue
        adj_cells = set()
        for y in range(H):
            for x in range(W):
                idx = y * W + x
                if mask & (1 << idx):
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < W and 0 <= ny < H:
                            new_idx = ny * W + nx
                            if not (mask & (1 << new_idx)):
                                adj_cells.add(new_idx)
        for cell in adj_cells:
            new_mask = mask | (1 << cell)
            if new_mask not in visited:
                if (new_mask & (1 << start_idx)) and (new_mask & (1 << end_idx)):
                    visited.add(new_mask)
                    queue.append(new_mask)
    print(count)

