import sys
from collections import deque

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_next_prime(n):
    if n <= 1:
        return 2
    if n == 2:
        return 3
    if n % 2 == 0:
        n += 1
    while True:
        if is_prime(n):
            return n
        n += 2

