MOD = 10**9 + 7

def is_rotation(s, t):
    return len(s) == len(t) and t in s + s

def find_t(s, t):
    n = len(s)
    for i in range(n):
        if s[i:] + s[:i] == t:
            return i
    return -1

def minimal_period(s):
    n = len(s)
    for d in range(1, n+1):
        if n % d != 0:
            continue
        valid = True
        for j in range(n):
            if s[j] != s[j % d]:
                valid = False
                break
        if valid:
            return d
    return n

def compute_cnt(L, d):
    cnt = [0] * d
    for i in range(1, L):
        s_i = L - i
        r = s_i % d
        cnt[r] += 1
    return cnt

def multiply(a, b, d):
    res = [0] * d
    for i in range(d):
        if a[i] == 0:
            continue
        for j in range(d):
            res[(i + j) % d] = (res[(i + j) % d] + a[i] * b[j]) % MOD
    return res

def pow_poly(g, exponent, d):
    result = [0] * d
    result[0] = 1  # Identity element (x^0)
    while exponent > 0:
        if exponent % 2 == 1:
            result = multiply(result, g, d)
        g = multiply(g, g, d)
        exponent = exponent // 2
    return result

