    # Check if all edges are reachable from vertex 1
    visited = set()
    if m > 0:
        q = deque([1])
        visited.add(1)
        while q:
            u = q.popleft()
            for v in adj.get(u, []):
                if v not in visited:
                    visited.add(v)
                    q.append(v)

    # Check each edge's reachability
    valid = True
    for x, y, w in edges:
        if x not in visited and y not in visited:
            valid = False
            break
    if not valid:
        print(-1)
        return

    # Calculate degrees and sum of edges
    sum_edges = sum(w for x, y, w in edges)
    degrees = [0] * (n + 1)
    for x, y, w in edges:
        degrees[x] += 1
        degrees[y] += 1

    S = [i for i in range(1, n+1) if degrees[i] % 2 != 0]
    if not S:
        print(sum_edges)
        return

    # Floyd-Warshall to compute all pairs shortest paths
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dist[i][i] = 0
    for x, y, w in edges:
        if dist[x][y] > w:
            dist[x][y] = w
            dist[y][x] = w
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Dynamic programming for minimal matching
    size = len(S)
    full_mask = (1 << size) - 1
    dp = [INF] * (1 << size)
    dp[0] = 0
    for mask in range(1 << size):
        if dp[mask] == INF:
            continue
        # Find first unset bit
        first = -1
        for i in range(size):
            if not (mask & (1 << i)):
                first = i
                break
        if first == -1:
            continue
        # Pair with all j > first
        for j in range(first + 1, size):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << first) | (1 << j)
                new_cost = dp[mask] + dist[S[first]][S[j]]
                if new_cost < dp[new_mask]:
                    dp[new_mask] = new_cost

    if dp[full_mask] == INF:
        print(-1)
    else:
        print(sum_edges + dp[full_mask])

