from functools import lru_cache
import sys

def solve():
    input = sys.stdin.read().split()
    t = int(input[0])
    idx = 1
    for _ in range(t):
        l = int(input[idx])
        r = int(input[idx+1])
        idx += 2

        if l == 0 and r == 0:
            print(1)
            continue

        bits_l = []
        bits_r = []
        for i in range(30):
            bits_l.append((l >> (29 - i)) & 1)
            bits_r.append((r >> (29 - i)) & 1)

        @lru_cache(maxsize=None)
        def dp(pos, a_low, a_high, b_low, b_high):
            if pos == 30:
                return 1
            res = 0
            for a_bit in 0, 1:
                for b_bit in 0, 1:
                    if (a_bit & b_bit) != 0:
                        continue

                    allowed_a = True
                    if a_low:
                        if a_bit < bits_l[pos]:
                            allowed_a = False
                    if a_high:
                        if a_bit > bits_r[pos]:
                            allowed_a = False
                    if not allowed_a:
                        continue

                    allowed_b = True
                    if b_low:
                        if b_bit < bits_l[pos]:
                            allowed_b = False
                    if b_high:
                        if b_bit > bits_r[pos]:
                            allowed_b = False
                    if not allowed_b:
                        continue

                    new_a_low = a_low and (a_bit == bits_l[pos])
                    new_a_high = a_high and (a_bit == bits_r[pos])
                    new_b_low = b_low and (b_bit == bits_l[pos])
                    new_b_high = b_high and (b_bit == bits_r[pos])

                    res += dp(pos + 1, new_a_low, new_a_high, new_b_low, new_b_high)
            return res

        total = dp(0, True, True, True, True)
        print(total)

