import math

def minimal_sum(n_str):
    if n_str == '1':
        return 1
    n = int(n_str)
    if n == 1:
        return 1
    min_sum = float('inf')
    max_m = int(math.log(n, 2)) + 2  # Estimate the maximum m to check
    for m in range(1, max_m + 1):
        # Binary search for x
        low, high = 1, n
        x = 1
        while low <= high:
            mid = (low + high) // 2
            try:
                mid_power = mid ** m
            except OverflowError:
                high = mid - 1
                continue
            if mid_power < n:
                low = mid + 1
            else:
                high = mid - 1
        x = high
        # Compute the product x^m
        product = x ** m
        if product >= n:
            current_sum = m * x
            if current_sum < min_sum:
                min_sum = current_sum
            continue
        # Calculate required k using logarithms
        if x == 0:
            x = 1
        required = math.log(n) - m * math.log(x)
        if required <= 0:
            k = 0
        else:
            ratio = math.log((x + 1) / x)
            k = required / ratio
            k = math.ceil(k)
        k = min(k, m)
        current_sum = m * x + k
        if current_sum < min_sum:
            min_sum = current_sum
    return min_sum

