import sys
from collections import deque

def main():
    N, M, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    prev_dp = [0] * (N + 2)  # 1-based indexing
    for j in range(1, N + 1):
        prev_dp[j] = A[j-1] * 1  # step 1

    for step in range(2, K + 1):
        # Compute prefix_max
        prefix_max = [-float('inf')] * (N + 1)
        prefix_max[0] = -float('inf')
        for x in range(1, N + 1):
            prefix_max[x] = max(prefix_max[x-1], prev_dp[x])

        # Compute sliding_max
        sliding_max = [-float('inf')] * (N + 1)
        dq = deque()
        for x in range(1, N + 1):
            while dq and prev_dp[x] >= prev_dp[dq[-1]]:
                dq.pop()
            dq.append(x)
            # Maintain the window [x-M+1, x]
            while dq[0] < (x - M + 1):
                dq.popleft()
            sliding_max[x] = prev_dp[dq[0]]

        # Compute curr_dp
        curr_dp = [-float('inf')] * (N + 2)
        for j in range(1, N + 1):
            if j == 1:
                curr_dp[j] = -float('inf')
                continue
            if j <= (M + 1):
                max_prev = prefix_max[j-1]
            else:
                if (j-1) >= 1:
                    max_prev = sliding_max[j-1]
                else:
                    max_prev = -float('inf')
            if max_prev == -float('inf'):
                curr_dp[j] = -float('inf')
            else:
                curr_dp[j] = max_prev + step * A[j-1]

        prev_dp = curr_dp

    max_score = max(prev_dp[1:N+1])
    print(max_score)

