def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    while True:
        m = int(input[ptr])
        ptr += 1
        n = int(input[ptr])
        ptr += 1
        if m == 0 and n == 0:
            break
        grid = []
        for _ in range(n):
            row = list(map(int, input[ptr:ptr+m]))
            ptr += m
            grid.append(row)
        max_steps = 0
        visited = [[False for _ in range(m)] for _ in range(n)]

        def backtrack(i, j, cnt):
            nonlocal max_steps
            max_steps = max(max_steps, cnt)
            for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    if grid[ni][nj] == 1 and not visited[ni][nj]:
                        visited[ni][nj] = True
                        backtrack(ni, nj, cnt + 1)
                        visited[ni][nj] = False

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    # Reset visited for each starting cell
                    for a in range(n):
                        for b in range(m):
                            visited[a][b] = False
                    visited[i][j] = True
                    backtrack(i, j, 1)
        print(max_steps)

