# Helper functions to check attacks
def queen_attack(qx, qy, nx, ny, p_old_x, p_old_y, board):
    if not (qx == nx or qy == ny or (abs(qx - nx) == abs(qy - ny))):
        return False
    dx = (nx - qx) // max(1, abs(nx - qx)) if nx != qx else 0
    dy = (ny - qy) // max(1, abs(ny - qy)) if ny != qy else 0
    steps = max(abs(nx - qx), abs(ny - qy))
    for step in range(1, steps):
        x = qx + dx * step
        y = qy + dy * step
        if (x, y) == (p_old_x, p_old_y):
            continue
        if board[x][y] != '_':
            return False
    return True

def rook_attack(rx, ry, nx, ny, p_old_x, p_old_y, board):
    if rx != nx and ry != ny:
        return False
    dx = (nx - rx) // max(1, abs(nx - rx)) if nx != rx else 0
    dy = (ny - ry) // max(1, abs(ny - ry)) if ny != ry else 0
    steps = max(abs(nx - rx), abs(ny - ry))
    for step in range(1, steps):
        x = rx + dx * step
        y = ry + dy * step
        if (x, y) == (p_old_x, p_old_y):
            continue
        if board[x][y] != '_':
            return False
    return True

def bishop_attack(bx, by, nx, ny, p_old_x, p_old_y, board):
    if abs(bx - nx) != abs(by - ny):
        return False
    dx = 1 if nx > bx else -1
    dy = 1 if ny > by else -1
    steps = abs(nx - bx)
    for step in range(1, steps):
        x = bx + dx * step
        y = by + dy * step
        if (x, y) == (p_old_x, p_old_y):
            continue
        if board[x][y] != '_':
            return False
    return True

