from collections import defaultdict

def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

cache = {}

def grundy(exp_tuple):
    if not exp_tuple:
        return 0
    if exp_tuple in cache:
        return cache[exp_tuple]
    max_e = exp_tuple[0]
    mex = set()
    for k in range(1, max_e + 1):
        new_exp = []
        for e in exp_tuple:
            if e >= k:
                new_e = e - k
                if new_e > 0:
                    new_exp.append(new_e)
        new_exp_sorted = tuple(sorted(new_exp, reverse=True))
        mex.add(grundy(new_exp_sorted))
    res = 0
    while res in mex:
        res += 1
    cache[exp_tuple] = res
    return res

