import bisect

class Node:
    def __init__(self, start, end, left=None, right=None, lines=None, critical_points=None):
        self.start = start
        self.end = end
        self.left = left
        self.right = right
        self.lines = lines if lines is not None else []
        self.critical_points = critical_points if critical_points is not None else []

def build(start, end, arr):
    if start == end:
        a, b = arr[start - 1]
        line = (a, b, start)
        return Node(start, end, lines=[line], critical_points=[])
    mid = (start + end) // 2
    left = build(start, mid, arr)
    right = build(mid + 1, end, arr)
    merged_lines = merge_lines(left.lines, right.lines)
    envelope_lines, envelope_critical = build_envelope(merged_lines)
    return Node(start, end, left, right, envelope_lines, envelope_critical)

def merge_lines(a_lines, b_lines):
    merged = []
    i = j = 0
    while i < len(a_lines) and j < len(b_lines):
        a_line = a_lines[i]
        b_line = b_lines[j]
        if a_line[1] < b_line[1]:
            merged.append(a_line)
            i += 1
        elif a_line[1] > b_line[1]:
            merged.append(b_line)
            j += 1
        else:
            if a_line[0] >= b_line[0]:
                merged.append(a_line)
            else:
                merged.append(b_line)
            i += 1
            j += 1
    merged.extend(a_lines[i:])
    merged.extend(b_lines[j:])
    return merged

def build_envelope(lines):
    envelope = []
    critical_points = []
    for line in lines:
        a, b, x = line
        while len(envelope) >= 1 and envelope[-1][1] == b:
            if envelope[-1][0] >= a:
                break
            else:
                envelope.pop()
                if len(critical_points) >= 1:
                    critical_points.pop()
        else:
            if len(envelope) >= 1 and envelope[-1][1] == b:
                continue
        while len(envelope) >= 2:
            a1, b1, x1 = envelope[-2]
            a2, b2, x2 = envelope[-1]
            num = a2 - a1
            den = b1 - b2
            x_prev = num / den if den != 0 else float('-inf')
            num_cur = a2 - a
            den_cur = b - b2
            x_cur = num_cur / den_cur if den_cur != 0 else float('-inf')
            if x_cur <= x_prev:
                envelope.pop()
                critical_points.pop()
            else:
                break
        if len(envelope) >= 1:
            a_prev, b_prev, x_prev = envelope[-1]
            num = a - a_prev
            den = b_prev - b
            intersect = num / den if den != 0 else float('inf')
            critical_points.append(intersect)
        envelope.append(line)
    return envelope, critical_points

def query_tree(l, r, t, node):
    if node.end < l or node.start > r:
        return None
    if l <= node.start and node.end <= r:
        if not node.lines:
            return None
        idx = bisect.bisect_right(node.critical_points, t)
        line = node.lines[idx] if idx < len(node.lines) else node.lines[-1]
        val = line[0] + line[1] * t
        return (val, line[2])
    left_res = query_tree(l, r, t, node.left) if node.left else None
    right_res = query_tree(l, r, t, node.right) if node.right else None
    candidates = []
    if left_res is not None:
        candidates.append(left_res)
    if right_res is not None:
        candidates.append(right_res)
    if not candidates:
        return None
    max_val = -float('inf')
    best_x = -1
    for val, x in candidates:
        if val > max_val or (val == max_val and x > best_x):
            max_val = val
            best_x = x
    return (max_val, best_x)

