def determine_outcome(n, a, b, c, d, move):
    x = c - a
    dy = abs(d - b)
    k = n - a

    if move == 0:
        if x < 0:
            return "White Wins"
        else:
            i_min = max((x + 1) // 2, dy)
            if i_min <= k:
                return "Draw"
            else:
                return "White Wins"
    else:
        if x < -1:
            return "White Wins"
        else:
            s = (x - 1) / 2
            ceil_s = math.ceil(s)
            i_min = max(ceil_s, dy - 1, 1)
            if i_min <= k:
                return "Draw"
            else:
                return "White Wins"

