def sum_of_divisors(n):
    if n == 0:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            exponent = 0
            while n % i == 0:
                exponent += 1
                n = n // i
            s = (i**(exponent + 1) - 1) // (i - 1)
            total *= s
        i += 1
    if n > 1:
        s = (n * n - 1) // (n - 1)
        total *= s
    return total

