import sys

class SegmentTreeNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.sorted_elements = []
        self.prefix_max_next = []
        self.prefix_max_a = []

def build(start, end, a, prev, next_):
    node = SegmentTreeNode(start, end)
    if start == end:
        node.sorted_elements = [(prev[start], next_[start], a[start])]
    else:
        mid = (start + end) // 2
        node.left = build(start, mid, a, prev, next_)
        node.right = build(mid + 1, end, a, prev, next_)
        left_list = node.left.sorted_elements
        right_list = node.right.sorted_elements
        merged = []
        i = j = 0
        while i < len(left_list) and j < len(right_list):
            if left_list[i][0] <= right_list[j][0]:
                merged.append(left_list[i])
                i += 1
            else:
                merged.append(right_list[j])
                j += 1
        merged.extend(left_list[i:])
        merged.extend(right_list[j:])
        node.sorted_elements = merged
    max_next = -1
    current_a = 0
    node.prefix_max_next = []
    node.prefix_max_a = []
    for elem in node.sorted_elements:
        p, nxt, a_val = elem
        if nxt > max_next:
            max_next = nxt
            current_a = a_val
        node.prefix_max_next.append(max_next)
        node.prefix_max_a.append(current_a)
    return node

def query_range(node, L, R, target_L):
    if node.end < L or node.start > R:
        return (-1, 0)
    if L <= node.start and node.end <= R:
        elements = node.sorted_elements
        left = 0
        right = len(elements) - 1
        k = -1
        while left <= right:
            mid = (left + right) // 2
            if elements[mid][0] < target_L:
                k = mid
                left = mid + 1
            else:
                right = mid - 1
        if k == -1:
            return (-1, 0)
        else:
            return (node.prefix_max_next[k], node.prefix_max_a[k])
    else:
        left_max, left_a = query_range(node.left, L, R, target_L)
        right_max, right_a = query_range(node.right, L, R, target_L)
        if left_max > right_max:
            return (left_max, left_a)
        else:
            return (right_max, right_a)

