def main():
    n = int(sys.stdin.readline())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, sys.stdin.readline().split())))

    # Precompute adjacents for each cell (only non-broken cells)
    adjacents = [[[] for _ in range(n)] for _ in range(n)]
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == -1:
                continue
            for dx, dy in directions:
                ni = i + dx
                nj = j + dy
                if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] != -1:
                    adjacents[i][j].append((ni, nj))

    # Initialize current values
    current_values = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                current_values[i][j] = 0
            else:
                current_values[i][j] = grid[i][j]

    # Iterate until no changes
    changed = True
    while changed:
        changed = False
        new_values = [row.copy() for row in current_values]
        for i in range(n):
            for j in range(n):
                if grid[i][j] != 0:
                    continue  # only process variables
                adj_values = []
                for (ni, nj) in adjacents[i][j]:
                    adj_values.append(current_values[ni][nj])
                if not adj_values:
                    continue  # no adjacents, value doesn't matter
                # Compute median
                adj_values.sort()
                m = len(adj_values)
                if m % 2 == 1:
                    median = adj_values[m//2]
                else:
                    median = (adj_values[m//2 - 1] + adj_values[m//2]) // 2
                if new_values[i][j] != median:
                    new_values[i][j] = median
                    changed = True
        current_values = new_values

    # Calculate total contrast
    total = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == -1:
                continue
            # Right neighbor
            if j+1 < n and grid[i][j+1] != -1:
                total += abs(current_values[i][j] - current_values[i][j+1])
            # Down neighbor
            if i+1 < n and grid[i+1][j] != -1:
                total += abs(current_values[i][j] - current_values[i+1][j])
    print(total)

