def main():
    n, a, b = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()
    k = a / b  # Not used directly, but the condition is a * spread <= b * count

    from collections import defaultdict
    char_info = defaultdict(lambda: {'first': n, 'last': -1, 'count': 0})
    for idx, c in enumerate(s):
        if idx < char_info[c]['first']:
            char_info[c]['first'] = idx
        if idx > char_info[c]['last']:
            char_info[c]['last'] = idx
        char_info[c]['count'] += 1

    # Build adjacency list for initial conversion graph
    graph = defaultdict(list)
    chars = list(char_info.keys())
    for c in chars:
        spread = char_info[c]['last'] - char_info[c]['first'] + 1
        m = char_info[c]['count']
        if a * spread <= b * m:
            for other in chars:
                if other != c:
                    graph[c].append(other)

    # For each z, check if all other x can reach z in the graph
    obtainable = []
    for z in chars:
        all_reachable = True
        for x in chars:
            if x == z:
                continue
            visited = set()
            q = deque([x])
            found = False
            while q:
                node = q.popleft()
                if node == z:
                    found = True
                    break
                if node in visited:
                    continue
                visited.add(node)
                for neighbor in graph.get(node, []):
                    if neighbor not in visited:
                        q.append(neighbor)
            if not found:
                all_reachable = False
                break
        if all_reachable:
            obtainable.append(z)

    # Sort and output
    obtainable.sort()
    print(len(obtainable), end='')
    if obtainable:
        print(' ' + ' '.join(obtainable))
    else:
        print()

