    b = list(map(int, sys.stdin.readline().split()))

    def factorize(nums):
        factors = {}
        for num in nums:
            if num == 1:
                continue
            temp = num
            while temp != 1:
                p = spf[temp]
                count = 0
                while temp % p == 0:
                    count += 1
                    temp = temp // p
                if p in factors:
                    factors[p] += count
                else:
                    factors[p] = count
        return factors

    numerator = factorize(a)
    denominator = factorize(b)

    gcd_factors = {}
    primes = set(numerator.keys()).union(denominator.keys())
    for p in primes:
        cnt_n = numerator.get(p, 0)
        cnt_d = denominator.get(p, 0)
        min_cnt = min(cnt_n, cnt_d)
        if min_cnt > 0:
            gcd_factors[p] = min_cnt

    for p in gcd_factors:
        cnt = gcd_factors[p]
        numerator[p] -= cnt
        if numerator[p] == 0:
            del numerator[p]
        denominator[p] -= cnt
        if denominator[p] == 0:
            del denominator[p]

    def generate_elements(factors):
        elements = []
        for p in sorted(factors.keys()):
            exp = factors[p]
            remaining = exp
            while remaining > 0:
                current_pow = 1
                k = 0
                while True:
                    next_pow = current_pow * p
                    if next_pow > 10**7 or (k + 1) > remaining:
                        break
                    current_pow = next_pow
                    k += 1
                elements.append(current_pow)
                remaining -= k
        if not elements:
            elements.append(1)
        return elements

    a_out = generate_elements(numerator)
    b_out = generate_elements(denominator)

    print(len(a_out), len(b_out))
    print(' '.join(map(str, a_out)))
    print(' '.join(map(str, b_out)))

