import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n, m = map(int, stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    reverse_adj = [[] for _ in range(n+1)]
    edges = []
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        adj[a].append(b)
        reverse_adj[b].append(a)
        edges.append((a, b))

    # Compute SCCs using Kosaraju's algorithm
    visited = [False] * (n+1)
    order = []
    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited[v]:
                    stack.append((v, False))
    for u in range(1, n+1):
        if not visited[u]:
            dfs(u)

    visited = [False] * (n+1)
    scc = []
    component = [0] * (n+1)
    current_component = 0
    for u in reversed(order):
        if not visited[u]:
            current_component += 1
            stack = [u]
            visited[u] = True
            members = []
            while stack:
                node = stack.pop()
                members.append(node)
                for v in reverse_adj[node]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            scc.append(members)
            for node in members:
                component[node] = current_component

    # Build condensed DAG
    condensed_edges = set()
    for a, b in edges:
        ca = component[a]
        cb = component[b]
        if ca != cb:
            condensed_edges.add((ca, cb))

    # Build adjacency list for condensed graph
    adj_condensed = [[] for _ in range(current_component + 1)]
    for ca, cb in condensed_edges:
        adj_condensed[ca].append(cb)

    # Compute topological order using Kahn's algorithm
    in_degree = [0] * (current_component + 1)
    for ca in range(1, current_component + 1):
        for cb in adj_condensed[ca]:
            in_degree[cb] += 1
    from collections import deque
    queue = deque()
    for ca in range(1, current_component + 1):
        if in_degree[ca] == 0:
            queue.append(ca)
    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj_condensed[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Precompute reachable sets
    reachable = [set() for _ in range(current_component + 1)]
    for u in reversed(topo_order):
        reachable[u].add(u)
        for v in adj_condensed[u]:
            reachable[u].update(reachable[v])

    # Count non-redundant edges in condensed DAG
    transitive_red_edges = 0
    for (ca, cb) in condensed_edges:
        redundant = False
        for w in adj_condensed[ca]:
            if w == cb:
                continue
            if cb in reachable[w]:
                redundant = True
                break
        if not redundant:
            transitive_red_edges += 1

    # Calculate total edges
    total = transitive_red_edges
    for members in scc:
        if len(members) > 1:
            total += len(members)
    print(total)

