class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [{} for _ in range(2 * self.size)]
        for i in range(self.size):
            if i < self.n:
                val = data[i]
                self.tree[self.size + i] = {
                    'first_val': val,
                    'last_val': val,
                    'inc_prefix': 1,
                    'inc_suffix': 1,
                    'dec_prefix': 1,
                    'dec_suffix': 1,
                    'max_hill': 1,
                    'lazy': 0,
                    'length': 1
                }
            else:
                self.tree[self.size + i] = {
                    'first_val': 0,
                    'last_val': 0,
                    'inc_prefix': 0,
                    'inc_suffix': 0,
                    'dec_prefix': 0,
                    'dec_suffix': 0,
                    'max_hill': 0,
                    'lazy': 0,
                    'length': 0
                }
        for i in range(self.size - 1, 0, -1):
            left = self.tree[2 * i]
            right = self.tree[2 * i + 1]
            self.tree[i] = self.merge(left, right)

    def merge(self, left, right):
        if left['length'] == 0:
            return right
        if right['length'] == 0:
            return left
        res = {
            'first_val': left['first_val'],
            'last_val': right['last_val'],
            'length': left['length'] + right['length'],
            'lazy': 0
        }

        # Calculate inc_prefix
        if left['inc_prefix'] == left['length'] and left['last_val'] < right['first_val']:
            res['inc_prefix'] = left['inc_prefix'] + right['inc_prefix']
        else:
            res['inc_prefix'] = left['inc_prefix']

        # Calculate inc_suffix
        if right['inc_suffix'] == right['length'] and left['last_val'] < right['first_val']:
            res['inc_suffix'] = left['inc_suffix'] + right['inc_suffix']
        else:
            res['inc_suffix'] = right['inc_suffix']

        # Calculate dec_prefix
        if left['dec_prefix'] == left['length'] and left['last_val'] > right['first_val']:
            res['dec_prefix'] = left['dec_prefix'] + right['dec_prefix']
        else:
            res['dec_prefix'] = left['dec_prefix']

        # Calculate dec_suffix
        if right['dec_suffix'] == right['length'] and left['last_val'] > right['first_val']:
            res['dec_suffix'] = left['dec_suffix'] + right['dec_suffix']
        else:
            res['dec_suffix'] = right['dec_suffix']

        # Calculate max_hill
        cross = left['inc_suffix'] + right['dec_prefix'] if left['last_val'] > right['first_val'] else 0
        res['max_hill'] = max(left['max_hill'], right['max_hill'], cross)

        return res

    def apply_lazy(self, node, val):
        if val == 0 or node['length'] == 0:
            return
        node['first_val'] += val
        node['last_val'] += val
        node['lazy'] += val

    def push(self, node):
        if node['lazy'] != 0 and node['length'] > 1:
            self.apply_lazy(self.tree[2 * node['index']], node['lazy'])
            self.apply_lazy(self.tree[2 * node['index'] + 1], node['lazy'])
            node['lazy'] = 0

    def range_add(self, l, r, val, node_index=1, node_l=0, node_r=None):
        if node_r is None:
            node_r = self.size - 1
        node = self.tree[node_index]
        if r < node_l or l > node_r:
            return
        if l <= node_l and node_r <= r:
            self.apply_lazy(node, val)
            return
        self.push(node)
        mid = (node_l + node_r) // 2
        self.range_add(l, r, val, 2 * node_index, node_l, mid)
        self.range_add(l, r, val, 2 * node_index + 1, mid + 1, node_r)
        left = self.tree[2 * node_index]
        right = self.tree[2 * node_index + 1]
        self.tree[node_index] = self.merge(left, right)

    def get_max_hill(self):
        return self.tree[1]['max_hill']

