MOD = 10**9 + 7

def compute(A, B, K):
    if K < 0:
        return (0, 0)
    bits = 30  # since 2^30 is over 1e9
    a_bits = [(A >> i) & 1 for i in reversed(range(bits + 1))]
    b_bits = [(B >> i) & 1 for i in reversed(range(bits + 1))]
    k_bits = [(K >> i) & 1 for i in reversed(range(bits + 1))]

    dp = {(0, 0, 0): (1, 0)}

    for i in range(bits + 1):
        current_bit = bits - i
        new_dp = {}
        for state in dp:
            a_state, b_state, xor_state = state
            cnt, s = dp[state]

            max_a = a_bits[i] if a_state == 0 else 1
            for a_bit in range(0, max_a + 1):
                new_a_state = a_state
                if a_state == 0 and a_bit < a_bits[i]:
                    new_a_state = 1

                max_b = b_bits[i] if b_state == 0 else 1
                for b_bit in range(0, max_b + 1):
                    new_b_state = b_state
                    if b_state == 0 and b_bit < b_bits[i]:
                        new_b_state = 1

                    xor_bit = a_bit ^ b_bit
                    current_k_bit = k_bits[i]

                    new_xor_state = xor_state
                    if xor_state == 0:
                        if xor_bit < current_k_bit:
                            new_xor_state = 1
                        elif xor_bit > current_k_bit:
                            new_xor_state = 2
                        else:
                            new_xor_state = 0
                    elif xor_state == 2:
                        continue

                    if new_xor_state == 2:
                        continue

                    key = (new_a_state, new_b_state, new_xor_state)
                    bit_val = (1 << current_bit) if current_bit >=0 else 0
                    add_s = xor_bit * bit_val * cnt
                    new_s = s * 2 + add_s
                    new_cnt = cnt

                    if key in new_dp:
                        prev_cnt, prev_s = new_dp[key]
                        new_dp[key] = ((prev_cnt + new_cnt) % MOD, (prev_s + new_s) % MOD)
                    else:
                        new_dp[key] = (new_cnt % MOD, new_s % MOD)
        dp = new_dp

    total_cnt = 0
    total_s = 0
    for state in dp:
        a_state, b_state, xor_state = state
        if xor_state != 2:
            cnt, s = dp[state]
            total_cnt = (total_cnt + cnt) % MOD
            total_s = (total_s + s) % MOD
    return (total_cnt, total_s)

