import sys
from collections import defaultdict

def count(x, k):
    if x == 0:
        return 0
    digits = list(map(int, str(x)))
    n = len(digits)
    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[0][(True, False, 0, 1)] = 1  # (tight, started, sum_so_far, mask)

    for i in range(n):
        for state in list(dp[i].keys()):
            tight, started, sum_so_far, mask = state
            current_count = dp[i][state]
            max_d = digits[i] if tight else 9

            for d in range(0, max_d + 1):
                new_tight = tight and (d == max_d)
                new_started = started or (d != 0)
                new_sum = sum_so_far + (d if new_started else 0)
                new_mask = mask

                if new_started:
                    if not started:
                        new_mask = 1 << d
                    else:
                        new_mask |= mask << d

                new_state = (new_tight, new_started, new_sum, new_mask)
                dp[i+1][new_state] += current_count

    total = 0
    for state in dp[n]:
        tight, started, sum_so_far, mask = state
        if not started:
            continue
        S = sum_so_far
        low = (S - k + 1) // 2
        high = (S + k) // 2

        if low > high:
            continue

        valid_low = max(0, low)
        valid_high = min(S, high)
        if valid_low > valid_high:
            continue

        valid_mask = ((1 << (valid_high + 1)) - 1) ^ ((1 << valid_low) - 1)
        if (mask & valid_mask) != 0:
            total += dp[n][state]

    return total

