def compute_lps(s):
    n = len(s)
    lps = [0] * n
    for i in range(1, n):
        j = lps[i-1]
        while j > 0 and s[i] != s[j]:
            j = lps[j-1]
        if s[i] == s[j]:
            j += 1
        lps[i] = j
    return lps

def main():
    N, M, K = map(int, sys.stdin.readline().split())
    S = sys.stdin.readline().strip()
    T = sys.stdin.readline().strip()

    lps = compute_lps(S)
    n = len(S)
    trans = [[0]*26 for _ in range(n)]
    for state in range(n):
        for c in range(26):
            current_char = chr(ord('a') + c)
            if current_char == S[state]:
                trans[state][c] = state + 1
            else:
                j = lps[state-1] if state > 0 else 0
                while j > 0 and current_char != S[j]:
                    j = lps[j-1] if j > 0 else 0
                if current_char == S[j]:
                    j += 1
                trans[state][c] = j

    cost = []
    for i in range(M):
        original_char = T[i]
        row = []
        for c in range(26):
            target_char = chr(ord('a') + c)
            a_ord = ord(original_char) - ord('a')
            b_ord = ord(target_char) - ord('a')
            delta = abs(a_ord - b_ord)
            row.append(min(delta, 26 - delta))
        cost.append(row)

    current_dp = [[-1]*(K+1) for _ in range(n)]
    current_dp[0][0] = 0

    for i in range(M):
        next_dp = [[-1]*(K+1) for _ in range(n)]
        for state_prev in range(n):
            for k_prev in range(K+1):
                if current_dp[state_prev][k_prev] == -1:
                    continue
                for c in range(26):
                    delta = cost[i][c]
                    new_k = k_prev + delta
                    if new_k > K:
                        continue
                    next_state = trans[state_prev][c]
                    new_occurrences = current_dp[state_prev][k_prev]
                    if next_state == n:
                        new_occurrences += 1
                        next_state = lps[next_state - 1]
                    if next_dp[next_state][new_k] < new_occurrences:
                        next_dp[next_state][new_k] = new_occurrences
        current_dp = next_dp

    max_occur = 0
    for state in range(n):
        for k in range(K+1):
            if current_dp[state][k] > max_occur:
                max_occur = current_dp[state][k]
    print(max_occur)

