def min_operations(a, b):
    count = 0
    while a != 1 or b != 1:
        if a > b:
            q = a // b
            count += q
            a = a % b
            if a == 0:
                a = b
                count -= 1
        else:
            q = b // a
            count += q
            b = b % a
            if b == 0:
                b = a
                count -= 1
    return count

