import sys
from bisect import bisect_right, bisect_left

def main():
    sys.setrecursionlimit(1 << 25)
    N, K = map(int, sys.stdin.readline().split())
    X = list(map(int, sys.stdin.readline().split()))
    Q = int(sys.stdin.readline())
    queries = [tuple(map(int, sys.stdin.readline().split())) for _ in range(Q)]

    # Precompute next_pos and prev_pos
    next_pos = [N] * N
    prev_pos = [-1] * N

    j = 0
    for i in range(N):
        while j < N and X[j] - X[i] < K:
            j += 1
        if j < N:
            next_pos[i] = j
        else:
            next_pos[i] = N

    j = N-1
    for i in range(N-1, -1, -1):
        while j >= 0 and X[i] - X[j] < K:
            j -= 1
        if j >= 0:
            prev_pos[i] = j
        else:
            prev_pos[i] = -1

    # Binary lifting tables for next_pos (left)
    LOG = 20
    jump_left = [[N] * N for _ in range(LOG)]
    jump_left[0] = next_pos[:]
    for k in range(1, LOG):
        for i in range(N):
            if jump_left[k-1][i] < N:
                jump_left[k][i] = jump_left[k-1][jump_left[k-1][i]]
            else:
                jump_left[k][i] = N

    # Binary lifting tables for prev_pos (right)
    jump_right = [[-1] * N for _ in range(LOG)]
    jump_right[0] = prev_pos[:]
    for k in range(1, LOG):
        for i in range(N):
            if jump_right[k-1][i] != -1:
                jump_right[k][i] = jump_right[k-1][jump_right[k-1][i]]
            else:
                jump_right[k][i] = -1

    def compute_left(L, R):
        if L > R:
            return 0, []
        res = []
        current = L
        res.append(current)
        while True:
            for k in reversed(range(LOG)):
                if jump_left[k][current] <= R:
                    current = jump_left[k][current]
                    res.append(current)
                    break
            else:
                break
        return len(res), res[:len(res)]

    def compute_right(R, L):
        if R < L:
            return 0, []
        res = []
        current = R
        res.append(current)
        while True:
            for k in reversed(range(LOG)):
                if jump_right[k][current] >= L:
                    current = jump_right[k][current]
                    res.append(current)
                    break
            else:
                break
        return len(res), res[:len(res)]

    for L, R in queries:
        L -= 1
        R -= 1
        # Compute left selection
        s_left, path_left = compute_left(L, R)
        # Compute right selection
        s_right, path_right = compute_right(R, L)
        S = max(s_left, s_right)
        if s_left == 0 or s_right == 0:
            print(S)
            continue

        # Find intersection using two pointers
        i = 0
        j = 0
        I = 0
        path_left_set = set(path_left[:S])
        path_right_set = set(path_right[:S])
        intersection = path_left_set & path_right_set
        I = len(intersection)
        ans = 2 * S - I
        print(ans)

