def main():
    from sys import stdin
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        m, n = map(int, line.strip().split())
        if m == 0 and n == 0:
            break
        objects = [stdin.readline().strip() for _ in range(n)]

        def solve(objects):
            memo = {}
            def dfs(s):
                if len(s) == 1:
                    return 0
                if s in memo:
                    return memo[s]
                min_depth = float('inf')
                m = len(next(iter(s)))
                for feature in range(m):
                    s0 = frozenset(obj for obj in s if obj[feature] == '0')
                    s1 = s - s0
                    if not s0 or not s1:
                        continue
                    d0 = dfs(s0)
                    d1 = dfs(s1)
                    current = 1 + max(d0, d1)
                    if current < min_depth:
                        min_depth = current
                memo[s] = min_depth
                return min_depth
            return dfs(frozenset(objects))

        result = solve(objects)
        print(result)

