import math

def compute_entropy(freq, n):
    entropy = 0.0
    for count in freq.values():
        p = count / n
        entropy += p * math.log2(p)
    return -entropy

def find_min_entropy_params(n, i_list):
    best_H = float('inf')
    best_S = best_A = best_C = 16  # Initialize with values higher than possible

    for S in range(16):
        for A in range(16):
            for C in range(16):
                # Generate R sequence
                R = [S]
                for j in range(1, n + 1):
                    next_R = (A * R[j-1] + C) % 256
                    R.append(next_R)

                # Compute O values
                O = [i_list[k] ^ R[k+1] for k in range(n)]

                # Count frequencies
                freq = {}
                for o in O:
                    freq[o] = freq.get(o, 0) + 1

                # Calculate entropy
                H = compute_entropy(freq, n)

                # Update best parameters
                if (H < best_H) or (H == best_H and (S, A, C) < (best_S, best_A, best_C)):
                    best_H = H
                    best_S, best_A, best_C = S, A, C
    return best_S, best_A, best_C

