    G = None
    for i in range(H):
        line = sys.stdin.readline().strip()
        row = list(line)
        grid.append(row)
        for j in range(W):
            if row[j] == 's':
                S = (i, j)
            elif row[j] == 'g':
                G = (i, j)

    # Initialize E_old with BFS from G ignoring springs
    INF = float('inf')
    current = [[INF for _ in range(W)] for _ in range(H)]
    gi, gj = G
    current[gi][gj] = 0
    q = deque()
    q.append((gi, gj))
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]

    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                cell = grid[ni][nj]
                if cell in ('.', 's') and current[ni][nj] == INF:
                    current[ni][nj] = current[i][j] + 1
                    q.append((ni, nj))

    # Compute initial A_old
    K = 0
    total = 0.0
    for i in range(H):
        for j in range(W):
            if grid[i][j] in ('.', 's'):
                K += 1
                total += current[i][j]
    A_old = total / K if K else 0.0

    # Iterate until convergence
    while True:
        next_grid = [[INF]*W for _ in range(H)]
        A_new = 0.0
        for i in range(H):
            for j in range(W):
                if grid[i][j] not in ('.', 's'):
                    continue
                min_val = INF
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W:
                        neighbor = grid[ni][nj]
                        if neighbor == 'g':
                            candidate = 1.0
                        elif neighbor in ('.', 's'):
                            candidate = 1.0 + current[ni][nj]
                        elif neighbor == '*':
                            candidate = 2.0 + A_old
                        else:
                            continue
                        if candidate < min_val:
                            min_val = candidate
                next_grid[i][j] = min_val
                A_new += min_val
        A_new /= K

        if abs(A_new - A_old) < 1e-15:
            break
        current = [row[:] for row in next_grid]
        A_old = A_new

    si, sj = S
    print("{0:.12f}".format(current[si][sj]))

