import math

def is_hypotenuse(c):
    if c == 0:
        return False
    c_abs = c
    factors = set()
    i = 2
    while i * i <= c_abs:
        while c_abs % i == 0:
            factors.add(i)
            c_abs //= i
        i += 1
    if c_abs > 1:
        factors.add(c_abs)
    for p in factors:
        if p % 4 == 1:
            return True
    return False

def generate_pairs(c):
    pairs = set()
    c_sq = c * c
    max_x = int(math.isqrt(c_sq))
    for x in range(1, max_x + 1):
        y_sq = c_sq - x * x
        if y_sq <= 0:
            continue
        y = math.isqrt(y_sq)
        if y * y == y_sq and y != 0:
            for sx in [1, -1]:
                for sy in [1, -1]:
                    pairs.add((x * sx, y * sy))
                    pairs.add((y * sy, x * sx))
    return pairs

