import sys

class BIT2D:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.tree = [[0]*(m+2) for _ in range(n+2)]

    def update(self, x, y, delta):
        i = x
        while i <= self.n:
            j = y
            while j <= self.m:
                self.tree[i][j] += delta
                j += j & -j
            i += i & -i

    def query(self, x, y):
        res = 0
        i = x
        while i > 0:
            j = y
            while j > 0:
                res += self.tree[i][j]
                j -= j & -j
            i -= i & -i
        return res

    def range_query(self, x1, y1, x2, y2):
        return (self.query(x2, y2) - self.query(x1-1, y2) 
                - self.query(x2, y1-1) + self.query(x1-1, y1-1))

