def parse(s):
    elements = []
    current_pos = 0
    while current_pos < len(s):
        if s[current_pos].isdigit():
            num = 0
            while current_pos < len(s) and s[current_pos].isdigit():
                num = num * 10 + int(s[current_pos])
                current_pos += 1
            if current_pos >= len(s):
                break
            next_char = s[current_pos]
            if next_char == '(':
                current_pos += 1
                sub_elements, current_pos = parse_parentheses(s, current_pos)
                elements.append(('r', num, sub_elements))
            else:
                elements.append(('r', num, [('s', next_char)]))
                current_pos += 1
        else:
            start = current_pos
            while current_pos < len(s) and s[current_pos].isalpha():
                current_pos += 1
            letters = s[start:current_pos]
            elements.append(('s', letters))
    return elements

def parse_parentheses(s, start_pos):
    elements = []
    current_pos = start_pos
    while current_pos < len(s):
        if s[current_pos] == ')':
            current_pos += 1
            break
        elif s[current_pos].isdigit():
            num = 0
            while current_pos < len(s) and s[current_pos].isdigit():
                num = num * 10 + int(s[current_pos])
                current_pos += 1
            if current_pos >= len(s):
                break
            next_char = s[current_pos]
            if next_char == '(':
                current_pos += 1
                sub_sub, current_pos = parse_parentheses(s, current_pos)
                elements.append(('r', num, sub_sub))
            else:
                elements.append(('r', num, [('s', next_char)]))
                current_pos += 1
        else:
            start = current_pos
            while current_pos < len(s) and s[current_pos].isalpha() and s[current_pos] != ')':
                current_pos += 1
            letters = s[start:current_pos]
            elements.append(('s', letters))
    return elements, current_pos

def compute_length(elements):
    total = 0
    for elem in elements:
        if elem[0] == 's':
            total += len(elem[1])
        else:
            n = elem[1]
            sub_len = compute_length(elem[2])
            total += n * sub_len
    return total

def find_character(elements, i):
    for elem in elements:
        if elem[0] == 's':
            s = elem[1]
            if i < len(s):
                return s[i]
            else:
                i -= len(s)
        else:
            n = elem[1]
            sub_elements = elem[2]
            sub_len = compute_length(sub_elements)
            total_len = n * sub_len
            if i < total_len:
                pos_in_sub = i % sub_len
                return find_character(sub_elements, pos_in_sub)
            else:
                i -= total_len
    return None

