import bisect

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 2)  # 1-based indexing

    def update(self, idx, delta):
        idx += 1  # convert 0-based to 1-based
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query_range(self, l, r):
        if l > r:
            return 0
        return self._query(r + 1) - self._query(l)

    def _query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def main():
    import sys
