        if x1 == x2:
            # Vertical segment
            y_min = min(y1, y2)
            y_max = max(y1, y2)
            verticals.append((x1, y_min, y_max))
        else:
            # Horizontal segment
            y = y1
            x_min = min(x1, x2)
            x_max = max(x1, x2)
            horizontals.append((y, x_min, x_max))

    # Collect unique x coordinates from verticals
    xs = sorted({v[0] for v in verticals})
    x_to_idx = {x: i for i, x in enumerate(xs)}
    ft = FenwickTree(len(xs))

    events = []
    for x, y_low, y_high in verticals:
        events.append((y_low, 'add', x))
        events.append((y_high + 1, 'remove', x))

    for y, x1, x2 in horizontals:
        events.append((y, 'query', x1, x2))

    # Sort events: first by y, then by type (add < query < remove)
    def event_key(event):
        y, typ = event[0], event[1]
        if typ == 'add':
            priority = 0
        elif typ == 'query':
            priority = 1
        else:
            priority = 2
        return (y, priority)

    events.sort(key=event_key)

    total = 0
    for event in events:
        y = event[0]
        typ = event[1]
        if typ == 'add' or typ == 'remove':
            x = event[2]
            if x not in x_to_idx:
                continue  # should not happen as xs includes all verticals
            idx = x_to_idx[x]
            delta = 1 if typ == 'add' else -1
            ft.update(idx, delta)
        elif typ == 'query':
            x1, x2 = event[2], event[3]
            if not xs:
                continue
            left = bisect.bisect_left(xs, x1)
            right = bisect.bisect_right(xs, x2) - 1
            cnt = ft.query_range(left, right)
            total += cnt

    print(total)

