import sys
from collections import deque

def is_connected(n, edges):
    if n == 1:
        return True
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * n
    q = deque()
    q.append(0)
    visited[0] = True
    count = 1
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                q.append(v)
                if count == n:
                    return True
    return count == n

def build_laplacian(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    laplacian = [[0] * n for _ in range(n)]
    for i in range(n):
        laplacian[i][i] = len(adj[i])
    for i in range(n):
        for j in adj[i]:
            if i != j:
                laplacian[i][j] -= 1
    return laplacian

def determinant(mat):
    n = len(mat)
    if n == 0:
        return 1
    mat = [row.copy() for row in mat]
    prev_pivot = 1
    sign = 1
    for k in range(n):
        pivot_row = -1
        for i in range(k, n):
            if mat[i][k] != 0:
                pivot_row = i
                break
        if pivot_row == -1:
            return 0
        if pivot_row != k:
            mat[k], mat[pivot_row] = mat[pivot_row], mat[k]
            sign *= -1
        pivot = mat[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                mat[i][j] = (mat[i][j] * pivot - mat[i][k] * mat[k][j])
                if k > 0:
                    mat[i][j] = mat[i][j] // prev_pivot
        prev_pivot = pivot
    return sign * mat[-1][-1]

