from collections import defaultdict

def main():
    MOD = 10**18 + 3
    BASE = 911382629

    while True:
        line = sys.stdin.readline()
        if not line:
            break
        L, H = map(int, line.split())
        if L == 0 and H == 0:
            break
        S = sys.stdin.readline().strip()
        n = len(S)
        if n == 0:
            print(0, 0)
            continue

        # Precompute prefix_hash and pow_base
        prefix_hash = [0] * (n + 1)
        pow_base = [1] * (n + 1)
        for i in range(n):
            prefix_hash[i + 1] = (prefix_hash[i] * BASE + ord(S[i])) % MOD
            pow_base[i + 1] = (pow_base[i] * BASE) % MOD

        max_char_freq = 0
        if n > 0:
            char_count = defaultdict(int)
            for c in S:
                char_count[c] += 1
            max_char_freq = max(char_count.values()) if char_count else 0

        current_max_count = 0
        current_max_length = 0

        max_possible_l = min(H, n)
        min_possible_l = max(L, 1)
        for l in range(max_possible_l, min_possible_l - 1, -1):
            possible_max = n - l + 1
            if possible_max <= 0:
                continue
            possible_max = min(possible_max, max_char_freq)
            if current_max_count > possible_max:
                continue

            hash_dict = defaultdict(int)
            max_freq = 0
            for i in range(n - l + 1):
                current_hash = (prefix_hash[i + l] - prefix_hash[i] * pow_base[l]) % MOD
                hash_dict[current_hash] += 1
                if hash_dict[current_hash] > max_freq:
                    max_freq = hash_dict[current_hash]

            actual_max = max_freq
            if actual_max > current_max_count:
                current_max_count = actual_max
                current_max_length = l
            elif actual_max == current_max_count and l > current_max_length:
                current_max_length = l

            if current_max_count >= possible_max:
                break
            next_l = l - 1
            if next_l >= L:
                next_possible_max = n - next_l + 1
                if current_max_count > next_possible_max:
                    break

        print(current_max_count, current_max_length)

