def stable_roommates(n, prefs):
    if n % 2 != 0:
        return None
    pointers = [0] * n
    proposal = [None] * n
    inverse = [{} for _ in range(n)]
    for i in range(n):
        for rank, j in enumerate(prefs[i]):
            inverse[i][j] = rank
    holds = {}
    free = list(range(n))
    while free:
        i = free.pop()
        while pointers[i] < len(prefs[i]):
            j = prefs[i][pointers[i]]
            pointers[i] += 1
            if j not in holds:
                holds[j] = i
                proposal[j] = i
                break
            else:
                current = holds[j]
                if inverse[j][i] < inverse[j][current]:
                    holds[j] = i
                    free.append(current)
                    proposal[j] = i
                    break
        else:
            return None
    for i in range(n):
        if proposal[proposal[i]] != i:
            return None
    return proposal

