import math

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    m = int(input[idx+1])
    idx +=2
    a = list(map(int, input[idx:idx+n]))
    idx +=n
    bad_primes = set(map(int, input[idx:idx+m]))
    idx +=m

    memo = {}

    def compute_f(s):
        if s == 1:
            return 0
        if s in memo:
            return memo[s]
        factors = []
        temp = s
        i = 2
        while i * i <= temp:
            while temp % i == 0:
                factors.append(i)
                temp //= i
            i += 1
        if temp > 1:
            factors.append(temp)
        factors.sort()
        res = 0
        for p in factors:
            if p in bad_primes:
                res -= 1
            else:
                res += 1
        memo[s] = res
        return res

    total = sum(compute_f(x) for x in a)

    for r in range(n, 0, -1):
        current_gcd = a[0]
        for i in range(1, r):
            current_gcd = math.gcd(current_gcd, a[i])
            if current_gcd == 1:
                break
        if current_gcd == 1:
            continue

        sum_before = 0
        for i in range(r):
            sum_before += compute_f(a[i])

        sum_after = 0
        for i in range(r):
            new_s = a[i] // current_gcd
            sum_after += compute_f(new_s)

        delta = sum_after - sum_before
        if delta > 0:
            total += delta
            for i in range(r):
                a[i] = a[i] // current_gcd

    print(total)

