MOD = 10**9 + 7

def subtract_one(s):
    s_list = list(s)
    i = len(s_list) - 1
    while i >= 0 and s_list[i] == '0':
        s_list[i] = '9'
        i -= 1
    if i < 0:
        return '0'
    s_list[i] = str(int(s_list[i]) - 1)
    result = ''.join(s_list)
    if result.startswith('0') and len(result) > 1:
        return result.lstrip('0') or '0'
    else:
        return result

def count(s, k):
    if s == '0':
        return 0
    n = len(s)
    dp = [{} for _ in range(n+1)]
    dp[0][(True, False, -1)] = 1
    for pos in range(n):
        current_digit = int(s[pos])
        for state in list(dp[pos].keys()):
            tight, has_met, last_lp = state
            current_count = dp[pos][state]
            max_d = current_digit if tight else 9
            for d in range(0, max_d + 1):
                new_tight = tight and (d == max_d)
                new_has_met = has_met
                new_last_lp = last_lp
                current_pos = pos + 1
                if not new_has_met:
                    if d in {4, 7}:
                        if last_lp != -1 and (current_pos - last_lp) <= k:
                            new_has_met = True
                            new_last_lp = -1
                        else:
                            new_last_lp = current_pos
                new_state = (new_tight, new_has_met, new_last_lp)
                if new_has_met:
                    new_state = (new_tight, True, -1)
                if new_state in dp[pos+1]:
                    dp[pos+1][new_state] = (dp[pos+1][new_state] + current_count) % MOD
                else:
                    dp[pos+1][new_state] = current_count % MOD
    total = 0
    for state in dp[n]:
        if state[1]:
            total = (total + dp[n][state]) % MOD
    return total

