import sys

def process_matrix(w, h, matrix):
    dp = [['' for _ in range(w)] for _ in range(h)]

    for i in reversed(range(h)):
        for j in reversed(range(w)):
            c = matrix[i][j]
            if not c.isdigit():
                dp[i][j] = ''
                continue
            candidates = [c]
            # Check right neighbor
            if j + 1 < w and matrix[i][j+1].isdigit():
                right_dp = dp[i][j+1]
                if right_dp:
                    candidates.append(c + right_dp)
            # Check down neighbor
            if i + 1 < h and matrix[i+1][j].isdigit():
                down_dp = dp[i+1][j]
                if down_dp:
                    candidates.append(c + down_dp)
            # Determine the maximum candidate
            if candidates:
                max_candidate = max(candidates, key=lambda x: (len(x), x))
                dp[i][j] = max_candidate
            else:
                dp[i][j] = c

    max_str = ''
    for i in range(h):
        for j in range(w):
            if matrix[i][j].isdigit():
                current = dp[i][j]
                if (len(current) > len(max_str)) or (len(current) == len(max_str) and current > max_str):
                    max_str = current

    stripped = max_str.lstrip('0')
    return stripped if stripped else '0'

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        w, h = map(int, line.split())
        if w == 0 and h == 0:
            break
        matrix = []
        for _ in range(h):
            row = sys.stdin.readline().strip()
            matrix.append(row)
        result = process_matrix(w, h, matrix)
        print(result)

