import sys

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.parent = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        new_node = Node(key)
        if self.root is None:
            self.root = new_node
            return
        current = self.root
        parent = None
        while current:
            parent = current
            if key < current.key:
                current = current.left
            else:
                current = current.right
        new_node.parent = parent
        if key < parent.key:
            parent.left = new_node
        else:
            parent.right = new_node

    def find(self, key):
        current = self.root
        while current:
            if current.key == key:
                return True
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return False

    def delete(self, key):
        node = self._find_node(key)
        if not node:
            return
        if node.left and node.right:
            succ = self._find_min(node.right)
            node.key = succ.key
            node = succ
        child = node.left if node.left else node.right
        if child:
            child.parent = node.parent
        if node.parent is None:
            self.root = child
        else:
            if node == node.parent.left:
                node.parent.left = child
            else:
                node.parent.right = child

    def _find_node(self, key):
        current = self.root
        while current:
            if current.key == key:
                return current
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return None

    def _find_min(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def inorder(self):
        res = []
        self._inorder(self.root, res)
        return res

    def _inorder(self, node, res):
        if node:
            self._inorder(node.left, res)
            res.append(node.key)
            self._inorder(node.right, res)

    def preorder(self):
        res = []
        self._preorder(self.root, res)
        return res

    def _preorder(self, node, res):
        if node:
            res.append(node.key)
            self._preorder(node.left, res)
            self._preorder(node.right, res)

def main():
    m = int(sys.stdin.readline())
    bst = BST()
    for _ in range(m):
        parts = sys.stdin.readline().split()
