from collections import deque

def compute_max_matching(n, edges):
    adj = [[] for _ in range(n+1)]
    for u, v in edges:
        adj[u].append(v)

    pair_u = [0] * (n + 1)
    pair_v = [0] * (n + 1)
    dist = [0] * (n + 1)
    result = 0

    def bfs():
        queue = deque()
        for u in range(1, n+1):
            if pair_u[u] == 0:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        dist[0] = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < dist[0]:
                for v in adj[u]:
                    if dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        queue.append(pair_v[v])
        return dist[0] != float('inf')

    def dfs(u):
        if u != 0:
            for v in adj[u]:
                if dist[pair_v[v]] == dist[u] + 1:
                    if dfs(pair_v[v]):
                        pair_u[u] = v
                        pair_v[v] = u
                        return True
            dist[u] = float('inf')
            return False
        return True

    while bfs():
        for u in range(1, n+1):
            if pair_u[u] == 0:
                if dfs(u):
                    result += 1
    return result

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    original_edges = []
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        original_edges.append((u, v))
    x_y = [tuple(map(int, sys.stdin.readline().split())) for _ in range(k)]

    blocked_out = set()
    blocked_in = set()
    actions = []

    for wave in range(k):
        i = wave + 1
        current_edges = []
        for u, v in original_edges:
            if u not in blocked_out and v not in blocked_in:
                current_edges.append((u, v))
        max_match = compute_max_matching(n, current_edges)
        m_req = n - i - 1

        if max_match <= m_req:
            actions.append(0)
            continue

        while True:
            current_edges = []
            for u, v in original_edges:
                if u not in blocked_out and v not in blocked_in:
                    current_edges.append((u, v))
            current_max = compute_max_matching(n, current_edges)
            if current_max <= m_req:
                break

            possible_blocks = []
            for hall in range(1, n+1):
                if hall not in blocked_out:
                    possible_blocks.append(('out', hall))
                if hall not in blocked_in:
                    possible_blocks.append(('in', hall))

            if not possible_blocks:
                break

            best_block = None
            best_reduction = current_max

            for block in possible_blocks:
                temp_blocked_out = set(blocked_out)
                temp_blocked_in = set(blocked_in)
                if block[0] == 'out':
                    temp_blocked_out.add(block[1])
                else:
                    temp_blocked_in.add(block[1])
                temp_edges = []
                for u, v in original_edges:
                    if u not in temp_blocked_out and v not in temp_blocked_in:
                        temp_edges.append((u, v))
                new_match = compute_max_matching(n, temp_edges)
                if new_match < best_reduction:
                    best_reduction = new_match
                    best_block = block

            if best_block is None:
                best_block = possible_blocks[0]

            if best_block[0] == 'out':
                blocked_out.add(best_block[1])
                actions.append(best_block[1])
            else:
                blocked_in.add(best_block[1])
                actions.append(-best_block[1])

        actions.append(0)

    print(len(actions))
    print(' '.join(map(str, actions)))

