def point_on_segment(px, py, x1, y1, x2, y2):
    cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
    if cross != 0:
        return False
    minx = min(x1, x2)
    maxx = max(x1, x2)
    miny = min(y1, y2)
    maxy = max(y1, y2)
    return (minx <= px <= maxx) and (miny <= py <= maxy)

def point_in_polygon(px, py, polygon):
    inside = False
    n = len(polygon)
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i+1) % n]
        if point_on_segment(px, py, x1, y1, x2, y2):
            return True  # on the edge
        if ((y1 > py) != (y2 > py)):
            xinters = (py - y1) * (x2 - x1) / (y2 - y1) + x1
            if px <= xinters:
                inside = not inside
    return inside

