def max_and(a, b):
    if a == b:
        return a
    mask = 0
    for i in reversed(range(64)):  # Assuming 64-bit integers for handling up to 1e18
        a_bit = (a >> i) & 1
        b_bit = (b >> i) & 1
        if a_bit != b_bit:
            mask = (1 << i) - 1
            return (a & ~mask) | mask
        else:
            mask |= (a_bit << i)
    return a  # This line is theoretically unreachable as a < b

