def fibonacci(n, m):
    if n == 0:
        return 0
    def multiply(a, b, mod):
        a11, a12, a21, a22 = a
        b11, b12, b21, b22 = b
        return (
            (a11 * b11 + a12 * b21) % mod,
            (a11 * b12 + a12 * b22) % mod,
            (a21 * b11 + a22 * b21) % mod,
            (a21 * b12 + a22 * b22) % mod,
        )

    def power(matrix, exponent, mod):
        result = (1, 0, 0, 1)  # Identity matrix
        while exponent > 0:
            if exponent % 2 == 1:
                result = multiply(result, matrix, mod)
            matrix = multiply(matrix, matrix, mod)
            exponent = exponent // 2
        return result

    M = (1, 1, 1, 0)
    matrix = power(M, n - 1, m)
    return matrix[0] % m

