class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None, None]
        self.count = 0

def insert(node, number, max_bit):
    current = node
    for i in reversed(range(max_bit)):
        bit = (number >> i) & 1
        if not current.children[bit]:
            current.children[bit] = TrieNode()
        current = current.children[bit]
        current.count += 1

def query_trie(root, target, X, max_bit):
    count = 0
    current_nodes = [(root, 'equal')]
    for i in reversed(range(max_bit)):
        x_bit = (X >> i) & 1
        t_bit = (target >> i) & 1
        new_nodes = []
        for node, state in current_nodes:
            if state == 'greater':
                count += node.count
            elif state == 'equal':
                for child_bit in [0, 1]:
                    if node.children[child_bit] is not None:
                        xor_bit = t_bit ^ child_bit
                        if xor_bit > x_bit:
                            count += node.children[child_bit].count
                        elif xor_bit == x_bit:
                            new_nodes.append((node.children[child_bit], 'equal'))
        current_nodes = new_nodes
    for node, state in current_nodes:
        if state == 'equal':
            count += node.count
    return count

