import sys
from heapq import heappush, heappop
from collections import deque

def minimal_string(adj, start, end):
    best = dict()
    heap = []
    heappush(heap, ('', start))
    best[start] = ''
    while heap:
        current_str, u = heappop(heap)
        if u == end:
            return current_str
        if current_str != best.get(u, None):
            continue
        for v, label in adj[u]:
            new_str = current_str + label
            if v not in best or new_str < best.get(v, chr(ord('z')+1)):
                best[v] = new_str
                heappush(heap, (new_str, v))
    return None

def minimal_cycle(adj, u):
    best = dict()
    heap = []
    for v, label in adj[u]:
        new_str = label
        if v not in best or new_str < best.get(v, chr(ord('z')+1)):
            best[v] = new_str
            heappush(heap, (new_str, v))
    while heap:
        current_str, current_u = heappop(heap)
        if current_u == u:
            return current_str
        if current_str != best.get(current_u, None):
            continue
        for v, label in adj[current_u]:
            new_str = current_str + label
            if v not in best or new_str < best.get(v, chr(ord('z')+1)):
                best[v] = new_str
                heappush(heap, (new_str, v))
    return None

def reachable_from_s(adj, s, n):
    visited = set()
    queue = deque([s])
    visited.add(s)
    while queue:
        u = queue.popleft()
        for v, _ in adj[u]:
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return visited

def can_reach_g(adj, g, n):
    reverse_adj = [[] for _ in range(n)]
    for u in range(n):
        for v, label in adj[u]:
            reverse_adj[v].append( (u, label) )
    visited = set()
    queue = deque([g])
    visited.add(g)
    while queue:
        u = queue.popleft()
        for v, _ in reverse_adj[u]:
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return visited

