import sys

def main():
    n, q = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    class BIT:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)  # 1-based indexing

        def update(self, idx, val):
            while idx <= self.n:
                self.tree[idx] ^= val
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res ^= self.tree[idx]
                idx -= idx & -idx
            return res

    bit = BIT(n)

    for _ in range(q):
