        else:
            l = int(parts[1])
            r = int(parts[2])
            basis = [0] * 30  # For 0 <= ai <= 1e9, 30 bits are sufficient
            for i in range(l, r + 1):
                x = bit.query(i)
                val = a[i - 1] ^ x
                # Insert into basis
                current = val
                for j in reversed(range(30)):
                    if (current >> j) & 1:
                        if basis[j] == 0:
                            basis[j] = current
                            break
                        current ^= basis[j]
                    if current == 0:
