def compute_min_guarantee(R, C, W):
    if W == C:
        steps_1d = W
    else:
        quotient = C // W
        remainder = C % W
        steps_1d = quotient + W - 1
        if remainder != 0:
            steps_1d += 1
    return (R - 1) + steps_1d

