def apply_wordrev(s, n):
    words = s.split()
    for i in range(min(n, len(words))):
        words[i] = words[i][::-1]
    return ' '.join(words)

def find_palindromes(s):
    palindromes = []
    n = len(s)
    for i in range(n):
        for j in range(i+1, n):
            substr = s[i:j+1]
            if substr == substr[::-1]:
                palindromes.append(substr)
    return palindromes

def apply_subpalin(s, n):
    palindromes = find_palindromes(s)
    if n <= len(palindromes):
        return palindromes[n-1]
    else:
        return s

def apply_sortword(s, n):
    words = s.split()
    for i in range(min(n, len(words))):
        min_index = i
        for j in range(i+1, len(words)):
            if words[j] < words[min_index]:
                min_index = j
        words[i], words[min_index] = words[min_index], words[i]
    return ' '.join(words)

