import sys
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        A_edges = []
        for _ in range(N-1):
            a = int(input[ptr])
            b = int(input[ptr+1])
            A_edges.append((a, b))
            ptr +=2
        B_edges = []
        for _ in range(N-1):
            c = int(input[ptr])
            d = int(input[ptr+1])
            B_edges.append((c, d))
            ptr +=2

        def build_parents(edges, root, N):
            adj = [[] for _ in range(N+1)]
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)
            parents = [-1]*(N+1)
            visited = [False]*(N+1)
            q = deque()
            q.append(root)
            visited[root] = True
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parents[v] = u
                        q.append(v)
            return parents

        min_ops = float('inf')
        for root in range(1, N+1):
            parents_A = build_parents(A_edges, root, N)
            parents_B = build_parents(B_edges, root, N)
            S = set()
            for v in range(1, N+1):
                if parents_A[v] != parents_B[v]:
                    S.add(v)
            valid = True
            for v in S:
                children = []
                for u in range(1, N+1):
                    if parents_B[u] == v:
                        children.append(u)
                for u in children:
                    if u not in S:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                min_ops = min(min_ops, len(S))
        if min_ops != float('inf'):
            print(min_ops)
        else:
            print(-1)

if __name__ == "__main__":
    main()

