import sys
from itertools import product

def rotate90(grid):
    if not grid:
        return []
    return [''.join(row[::-1]) for row in zip(*grid)]

def rotate180(grid):
    return [row[::-1] for row in reversed(grid)]

def rotate270(grid):
    if not grid:
        return []
    return [''.join(row) for row in zip(*reversed(grid))][::-1]

def trim(grid):
    if not grid:
        return []
    rows = []
    for row in grid:
        if any(c == '#' for c in row):
            rows.append(row)
    if not rows:
        return []
    left = len(rows[0])
    right = 0
    for row in rows:
        first = next((i for i, c in enumerate(row) if c == '#'), len(row))
        last = next((i for i, c in reversed(list(enumerate(row))) if c == '#'), -1)
        left = min(left, first)
        right = max(right, last + 1)
    trimmed = [row[left:right] for row in rows]
    return trimmed

def main():
    while True:
        H, W = map(int, sys.stdin.readline().split())
        if H == 0 and W == 0:
            break
        puzzle = [sys.stdin.readline().strip() for _ in range(H)]
        target_cells = set()
        for i in range(H):
            for j in range(W):
                if puzzle[i][j] == '.':
                    target_cells.add((i, j))
        target_mask = 0
        for (i, j) in target_cells:
            target_mask |= 1 << (i * W + j)
        n = int(sys.stdin.readline())
        pieces = []
        for _ in range(n):
            h, w = map(int, sys.stdin.readline().split())
            grid = [sys.stdin.readline().strip() for _ in range(h)]
            pieces.append((h, w, grid))
        p = int(sys.stdin.readline())
        players = []
        for _ in range(p):
            parts = list(map(int, sys.stdin.readline().split()))
            k = parts[0]
            selected = parts[1:]
            players.append((k, selected))

        for k, selected in players:
            selected_pieces = [pieces[t-1] for t in selected]
            total_hash = sum(sum(row.count('#') for row in grid) for (h, w, grid) in selected_pieces)
            if total_hash != len(target_cells):
                print("NO")
                continue

            rotated_list = []
            for (h_p, w_p, grid_p) in selected_pieces:
                rotations = [grid_p, rotate90(grid_p), rotate180(grid_p), rotate270(grid_p)]
                unique_rotations = []
                for rot in rotations:
                    trimmed = trim(rot)
                    if not trimmed:
                        continue
                    coords = []
                    for i, row in enumerate(trimmed):
                        for j, c in enumerate(row):
                            if c == '#':
                                coords.append((i, j))
                    h_trim = len(trimmed)
                    w_trim = len(trimmed[0]) if h_trim else 0
                    possible_positions = []
                    for x in range(H - h_trim + 1):
                        for y in range(W - w_trim + 1):
                            valid = True
                            for (dx, dy) in coords:
                                i_rot = x + dx
                                j_rot = y + dy
                                if (i_rot, j_rot) not in target_cells:
                                    valid = False
                                    break
                            if valid:
                                possible_positions.append((x, y))
                    if possible_positions:
                        unique_rotations.append((h_trim, w_trim, coords, possible_positions))
                if not unique_rotations:
                    rotated_list = []
                    break
                rotated_list.append(unique_rotations)
            if not rotated_list:
                print("NO")
                continue

            sorted_rotated = sorted([(sum(len(row) for row in grid_p if '#' in row), rl) for (h_p, w_p, grid_p), rl in zip(selected_pieces, rotated_list)], key=lambda x: -x[0])
            sorted_rotated = [rl for (_, rl) in sorted_rotated]

            stack = [(0, 0)]
            found = False
            while stack:
                index, covered = stack.pop()
                if index == len(sorted_rotated):
                    if covered == target_mask:
                        found = True
                        break
                    continue
                for rotation in sorted_rotated[index]:
                    h_trim, w_trim, coords, possible_positions = rotation
                    for x, y in possible_positions:
                        valid = True
                        new_covered = covered
                        for (dx, dy) in coords:
                            cell = (x + dx) * W + (y + dy)
                            if (new_covered & (1 << cell)) != 0:
                                valid = False
                                break
                        if not valid:
                            continue
                        temp_covered = covered
                        for (dx, dy) in coords:
                            cell = (x + dx) * W + (y + dy)
                            temp_covered |= (1 << cell)
                        stack.append((index + 1, temp_covered))
                if found:
                    break
            print("YES" if found else "NO")

