import heapq

while True:
    h, w = map(int, input().split())
    if h == 0 and w == 0:
        break
    grid = []
    for _ in range(h):
        grid.append(list(map(int, input().split())))
    sr, sc = map(int, input().split())
    er, ec = map(int, input().split())

    heap = []
    heapq.heappush(heap, (0, sr, sc, 1, 5, 3))
    visited = {}
    min_penalty = None

    while heap:
        penalty, r, c, top, north, east = heapq.heappop(heap)
        if r == er and c == ec:
            min_penalty = penalty
            break
        key = (r, c, top, north, east)
        if key in visited:
            if visited[key] <= penalty:
                continue
        visited[key] = penalty

        directions = [(-1, 0), (1, 0), (0, 1), (0, -1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if dr == -1:
                    new_top = 7 - north
                    new_north = top
                    new_east = east
                elif dr == 1:
                    new_top = north
                    new_north = 7 - top
                    new_east = east
                elif dc == 1:
                    new_top = 7 - east
                    new_north = north
                    new_east = top
                else:
                    new_top = east
                    new_north = north
                    new_east = 7 - top
                cell_value = grid[nr][nc]
                new_penalty = penalty + cell_value * (7 - new_top)
                new_key = (nr, nc, new_top, new_north, new_east)
                if new_key not in visited or new_penalty < visited.get(new_key, float('inf')):
                    heapq.heappush(heap, (new_penalty, nr, nc, new_top, new_north, new_east))

    print(min_penalty)

