import sys
from collections import defaultdict, deque

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root != y_root:
            self.parent[y_root] = x_root

def hopcroft_karp(graph, U_nodes, V_nodes):
    pair_U = {u: None for u in U_nodes}
    pair_V = {v: None for v in V_nodes}
    dist = {}

    def bfs():
        queue = deque()
        for u in U_nodes:
            if pair_U[u] is None:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        dist[None] = float('inf')
        while queue:
            u = queue.popleft()
            if u is not None:
                for v in graph[u]:
                    if dist.get(pair_V.get(v, None), float('inf')) == float('inf'):
                        dist[pair_V.get(v, None)] = dist[u] + 1
                        queue.append(pair_V.get(v, None))
        return dist[None] != float('inf')

    def dfs(u):
        if u is not None:
            for v in graph[u]:
                if dist.get(pair_V.get(v, None), float('inf')) == dist[u] + 1:
                    if dfs(pair_V.get(v, None)):
                        pair_U[u] = v
                        pair_V[v] = u
                        return True
            dist[u] = float('inf')
            return False
        return True

    result = 0
    while bfs():
        for u in U_nodes:
            if pair_U[u] is None:
                if dfs(u):
                    result += 1
    return result

