    fib = [0] * (k - 1)
    fib.append(1)
    while True:
        next_term = sum(fib[-k:])
        if next_term > s:
            break
        fib.append(next_term)
    # Extract unique values
    seen = set()
    unique = []
    for num in fib:
        if num not in seen:
            seen.add(num)
            unique.append(num)
    return unique

