def tokenize(expr):
    tokens = []
    current = ''
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit() or (c == '-' and (i == 0 or expr[i-1] in '+-*/(')):
            current += c
            i += 1
            while i < len(expr) and expr[i].isdigit():
                current += expr[i]
                i += 1
            tokens.append(int(current))
            current = ''
        else:
            if current:
                tokens.append(int(current))
                current = ''
            if c in '+-*/()':
                tokens.append(c)
            i += 1
    if current:
        tokens.append(int(current))
    return tokens

def precedence(op):
    if op in '+-':
        return 1
    elif op in '*/':
        return 2
    return 0

def shunting_yard(tokens):
    output = []
    stack = []
    for token in tokens:
        if isinstance(token, int):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        else:
            while stack and stack[-1] != '(' and (precedence(stack[-1]) > precedence(token) or (precedence(stack[-1]) == precedence(token))):
                output.append(stack.pop())
            stack.append(token)
    while stack:
        output.append(stack.pop())
    return output

def evaluate_postfix(postfix):
    stack = []
    for token in postfix:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            elif token == '/':
                if a * b >= 0:
                    res = a // b
                else:
                    res = a // b + 1
            stack.append(res)
    return stack[0]

