        mod_period = len(p)
        visited = [[False] * mod_period for _ in range(n + 2)]
        q = deque()
        start_x = 0
        start_mod = 0
        visited[start_x][start_mod] = True
        q.append((start_x, start_mod))
        found = False
        while q and not found:
            x, mod = q.popleft()
            for dx in [0, 1]:
                new_x = x + dx
                if new_x > n + 1:
                    continue
                new_mod = (mod + 1) % mod_period
                if new_x == n + 1:
                    found = True
                    break
                if new_x == 0:
                    if not visited[new_x][new_mod]:
                        visited[new_x][new_mod] = True
                        q.append((new_x, new_mod))
                elif 1 <= new_x <= n:
                    if d[new_x - 1] + p[new_mod] <= l:
                        if not visited[new_x][new_mod]:
                            visited[new_x][new_mod] = True
                            q.append((new_x, new_mod))
