import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(n):
        line = sys.stdin.readline().strip()
        grid.append([int(c) for c in line])

    # Precompute prefix sums for horizontal and vertical directions
    prefix_h = [[0]*(m+1) for _ in range(n)]
    for i in range(n):
        for j in range(m):
            prefix_h[i][j+1] = prefix_h[i][j] + grid[i][j]

    prefix_v = [[0]*(n+1) for _ in range(m)]
    for j in range(m):
        for i in range(n):
            prefix_v[j][i+1] = prefix_v[j][i] + grid[i][j]

    # Precompute prefix sums for main diagonals (i-j = c)
    main_diag = defaultdict(list)
    main_pos = defaultdict(dict)
    main_prefix = defaultdict(list)
    for i in range(n):
        for j in range(m):
            c = i - j
            main_diag[c].append((i, j))
    for c in main_diag:
        lst = sorted(main_diag[c], key=lambda x: x[0])
        main_prefix[c] = [0]*(len(lst)+1)
        for idx, (i, j) in enumerate(lst):
            main_prefix[c][idx+1] = main_prefix[c][idx] + grid[i][j]
            main_pos[c][(i, j)] = idx

    # Precompute prefix sums for anti diagonals (i+j = c)
    anti_diag = defaultdict(list)
    anti_pos = defaultdict(dict)
    anti_prefix = defaultdict(list)
    for i in range(n):
        for j in range(m):
            c = i + j
            anti_diag[c].append((i, j))
    for c in anti_diag:
        lst = sorted(anti_diag[c], key=lambda x: x[0])
        anti_prefix[c] = [0]*(len(lst)+1)
        for idx, (i, j) in enumerate(lst):
            anti_prefix[c][idx+1] = anti_prefix[c][idx] + grid[i][j]
            anti_pos[c][(i, j)] = idx

    count = 0

    # Orientation 1: Right and Down (horizontal right, vertical down, anti-diagonal)
    max_a = min(n, m)
    for a in range(1, max_a+1):
        for i in range(n - a):
            for j in range(m - a):
                # Horizontal line (i,j) to (i, j+a)
                if prefix_h[i][j+a+1] - prefix_h[i][j] != 0:
                    continue
                # Vertical line (i,j) to (i+a, j)
                if prefix_v[j][i+a+1] - prefix_v[j][i] != 0:
                    continue
                # Anti-diagonal line (i, j+a) to (i+a, j)
                x1, y1 = i, j+a
                x2, y2 = i+a, j
                c = x1 + y1
                if c != x2 + y2 or (x1, y1) not in anti_pos[c] or (x2, y2) not in anti_pos[c]:
                    continue
                start = anti_pos[c][(x1, y1)]
                end = anti_pos[c][(x2, y2)]
                if end < start:
                    continue
                if anti_prefix[c][end+1] - anti_prefix[c][start] != 0:
                    continue
                count += 1

    # Orientation 2: Right and Up (horizontal right, vertical up, main diagonal)
    for a in range(1, max_a+1):
        for i in range(a, n):
            for j in range(m - a):
                # Horizontal line (i,j) to (i, j+a)
                if prefix_h[i][j+a+1] - prefix_h[i][j] != 0:
                    continue
                # Vertical line (i,j) to (i-a, j)
                if prefix_v[j][i+1] - prefix_v[j][i-a] != 0:
                    continue
                # Main diagonal line (i,j+a) to (i-a, j)
                x1, y1 = i, j+a
                x2, y2 = i-a, j
                c = x1 - y1
                if c != x2 - y2 or (x1, y1) not in main_pos.get(c, {}) or (x2, y2) not in main_pos.get(c, {}):
                    continue
                start = main_pos[c][(x1, y1)]
                end = main_pos[c][(x2, y2)]
                if start < end:
                    continue
                if main_prefix[c][start+1] - main_prefix[c][end] != 0:
                    continue
                count += 1

    # Orientation 3: Left and Down (horizontal left, vertical down, main diagonal)
    for a in range(1, max_a+1):
        for i in range(n - a):
            for j in range(a, m):
                # Horizontal line (i,j) to (i, j-a)
                if prefix_h[i][j+1] - prefix_h[i][j-a] != 0:
                    continue
                # Vertical line (i,j) to (i+a, j)
                if prefix_v[j][i+a+1] - prefix_v[j][i] != 0:
                    continue
                # Main diagonal line (i,j-a) to (i+a, j)
                x1, y1 = i, j-a
                x2, y2 = i+a, j
                c = x1 - y1
                if c != x2 - y2 or (x1, y1) not in main_pos.get(c, {}) or (x2, y2) not in main_pos.get(c, {}):
                    continue
                start = main_pos[c][(x1, y1)]
                end = main_pos[c][(x2, y2)]
                if end < start:
                    continue
                if main_prefix[c][end+1] - main_prefix[c][start] != 0:
                    continue
                count += 1

    # Orientation 4: Left and Up (horizontal left, vertical up, anti-diagonal)
    for a in range(1, max_a+1):
        for i in range(a, n):
            for j in range(a, m):
                # Horizontal line (i,j) to (i, j-a)
                if prefix_h[i][j+1] - prefix_h[i][j-a] != 0:
                    continue
                # Vertical line (i,j) to (i-a, j)
                if prefix_v[j][i+1] - prefix_v[j][i-a] != 0:
                    continue
                # Anti-diagonal line (i,j-a) to (i-a, j)
                x1, y1 = i, j-a
                x2, y2 = i-a, j
                c = x1 + y1
                if c != x2 + y2 or (x1, y1) not in anti_pos[c] or (x2, y2) not in anti_pos[c]:
                    continue
                start = anti_pos[c][(x1, y1)]
                end = anti_pos[c][(x2, y2)]
                if end < start:
                    continue
                if anti_prefix[c][end+1] - anti_prefix[c][start] != 0:
                    continue
                count += 1

    print(count)

