import heapq

def main():
    n, m, t, x = map(int, input().split())
    edges = [[] for _ in range(n+1)]
    for _ in range(m):
        ai, bi, ci = map(int, input().split())
        p_list = list(map(int, input().split()))
        non_zero = []
        for k in range(len(p_list)):
            p = p_list[k]
            if p > 0:
                non_zero.append((k+1, p))
        edges[ai].append((bi, ci, non_zero))

    # Compute min_cost using Dijkstra's algorithm
    min_cost = [float('inf')] * (n+1)
    min_cost[n] = 0
    heap = [(0, n)]
    visited = [False] * (n+1)

    while heap:
        cost, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        for edge in edges[u]:
            v, c, _ = edge
            if not visited[v]:
                if min_cost[v] > cost + c:
                    min_cost[v] = cost + c
                    heapq.heappush(heap, (min_cost[v], v))

    # Initialize E
    INF = float('inf')
    E = [[INF] * (t+1) for _ in range(n+1)]
    for s in range(t+1):
        E[n][s] = 0.0

    for s in range(0, t+1):
        for u in range(1, n):
            E[u][s] = INF
            for edge in edges[u]:
                v, c, non_zero_ks = edge
                sum_expected = 0.0
                sum_p = 0
                for (k, p) in non_zero_ks:
                    if k > s:
                        sum_expected += p * (x + min_cost[v])
                    else:
                        sum_expected += p * E[v][s - k]
                    sum_p += p
                sum_p_more = 100000 - sum_p
                sum_expected += sum_p_more * (x + min_cost[v])
                sum_expected /= 100000.0
                current_cost = c + sum_expected
                if current_cost < E[u][s]:
                    E[u][s] = current_cost

    print("{0:.10f}".format(E[1][t]))

