    main()

import sys
from collections import defaultdict

def main():
    n, m = map(int, sys.stdin.readline().split())
    x = [int(sys.stdin.readline()) for _ in range(n)]
    S = sum(x)

    if m == 1:
        print("1.000000000000000")
        return

    # Precompute possible ranks for each competition
    possible_rs_list = []
    for xi in x:
        possible_rs = []
        for r in range(1, m+1):
            if r != xi:
                possible_rs.append(r)
        possible_rs_list.append(possible_rs)

    total_prob = 0.0
    current_dp = defaultdict(float)
    current_dp[0] = 1.0

    for i in range(n):
        next_dp = defaultdict(float)
        possible_rs = possible_rs_list[i]
        for j in current_dp:
            prob = current_dp[j]
            for r in possible_rs:
                j_prime = j + r
                remaining_steps = n - (i + 1)
                if remaining_steps == 0:
                    if j_prime < S:
                        total_prob += prob * (1.0 / (m-1))
                else:
                    min_next_sum = j_prime + remaining_steps * 1
                    max_next_sum = j_prime + remaining_steps * m
                    if max_next_sum < S:
                        total_prob += prob * (1.0 / (m-1))
                    elif min_next_sum > S - 1:
                        continue
                    else:
                        next_dp[j_prime] += prob * (1.0 / (m-1))
        current_dp = next_dp

    expected_rank = 1.0 + (m-1) * total_prob
    print("{0:.15f}".format(expected_rank))

