import sys
from collections import deque

def min_steps(n):
    if n == 1:
        return 0
    visited = {}
    queue = deque([(n, 0)])
    visited[n] = 0
    while queue:
        current, steps = queue.popleft()
        if current == 1:
            return steps
        next_steps = steps + 1
        next_nums = []
        if current % 3 == 0:
            next_nums.append(current // 3)
        if current % 2 == 0:
            next_nums.append(current // 2)
        next_nums.append(current - 1)
        for num in next_nums:
            if num not in visited or next_steps < visited.get(num, float('inf')):
                visited[num] = next_steps
                queue.append((num, next_steps))
    return -1

