def count_patties(L, X):
    if L == 0:
        return 1 if X >= 1 else 0

    if X == 0:
        return 0

    # First bun
    X -= 1
    if X == 0:
        return 0

    # First (L-1) burger
    if X <= layers[L-1]:
        return count_patties(L-1, X)
    else:
        res = patties[L-1]
        X -= layers[L-1]

    # Patty
    if X == 0:
        return res
    res += 1
    X -= 1
    if X == 0:
        return res

    # Second (L-1) burger
    if X <= layers[L-1]:
        res += count_patties(L-1, X)
        return res
    else:
        res += patties[L-1]
        X -= layers[L-1]

    # Last bun
    if X >= 1:
        X -= 1

    return res

