import sys
from functools import lru_cache

def parse(s):
    s = s.strip()
    if s == 'x':
        return 'x'
    s = s[1:-1]
    depth = 0
    split_pos = -1
    for i, c in enumerate(s):
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
        elif c == ' ' and depth == 0:
            split_pos = i
            break
    if split_pos == -1:
        return (parse(s), 'x')  # shouldn't happen for valid input
    left = s[:split_pos]
    right = s[split_pos+1:]
    return (parse(left), parse(right))

memo_cf = {}
memo_subtree = {}
memo_lr = {}

def compute_properties(node):
    if node == 'x':
        return ('x', {'x'}, 0.0)
    if node in memo_cf:
        return (memo_cf[node], memo_subtree[node], memo_lr[node])
    left, right = node
    l_cf, l_subtree, l_lr = compute_properties(left)
    r_cf, r_subtree, r_lr = compute_properties(right)
    intersection = l_subtree & r_subtree
    union = l_subtree | r_subtree
    lr_similarity = len(intersection) / len(union) if union else 0.0
    cmp_val = compare_strength(left, right, l_lr, r_lr)
    if cmp_val >= 0:
        cf = f"({l_cf} {r_cf})"
    else:
        cf = f"({r_cf} {l_cf})"
    subtree = l_subtree.union(r_subtree)
    subtree.add(cf)
    memo_cf[node] = cf
    memo_subtree[node] = subtree
    memo_lr[node] = lr_similarity
    return (cf, subtree, lr_similarity)

def compare_strength(a, b, a_lr, b_lr):
    if a == 'x' and b == 'x':
        return 0
    if a == 'x':
        if b_lr == 0:
            return 0
        return 1
    if b == 'x':
        if a_lr == 0:
            return 0
        return -1
    if a_lr < b_lr:
        return 1
    elif a_lr > b_lr:
        return -1
    else:
        a_left, a_right = a
        b_left, b_right = b
        a_strong = a_left if compare_strength(a_left, a_right, memo_lr.get(a_left, 0.0), memo_lr.get(a_right, 0.0)) >=0 else a_right
        a_weak = a_right if a_strong is a_left else a_left
        b_strong = b_left if compare_strength(b_left, b_right, memo_lr.get(b_left, 0.0), memo_lr.get(b_right, 0.0)) >=0 else b_right
        b_weak = b_right if b_strong is b_left else b_left
        cmp = compare_strength(a_strong, b_strong, memo_lr.get(a_strong, 0.0), memo_lr.get(b_strong, 0.0))
        if cmp != 0:
            return cmp
        return compare_strength(a_weak, b_weak, memo_lr.get(a_weak, 0.0), memo_lr.get(b_weak, 0.0))

def transform(node, position):
    if node == 'x':
        return 'x'
    left, right = node
    left_lr = memo_lr.get(left, 0.0)
    right_lr = memo_lr.get(right, 0.0)
    if position in ('root', 'left'):
        if compare_strength(left, right, left_lr, right_lr) >=0:
            new_left, new_right = left, right
        else:
            new_left, new_right = right, left
    else:
        if compare_strength(right, left, right_lr, left_lr) >=0:
            new_left, new_right = right, left
        else:
            new_left, new_right = left, right
    t_left = transform(new_left, 'left')
    t_right = transform(new_right, 'right')
    return (t_left, t_right)

def to_str(node):
    if node == 'x':
        return 'x'
    l, r = node
    return f"({to_str(l)} {to_str(r)})"

def main():
    for line in sys.stdin:
        line = line.strip()
        if line == '0':
            break
        tree = parse(line)
        compute_properties(tree)
        transformed = transform(tree, 'root')
        print(to_str(transformed))

