def fibonacci(n, mod):
    if mod == 1:
        return 0
    def fast_doubling(n):
        if n == 0:
            return (0, 1)
        a, b = fast_doubling(n // 2)
        c = (a * ((2 * b - a) % mod)) % mod
        d = (a * a + b * b) % mod
        if n % 2 == 0:
            return (c, d)
        else:
            return (d, (c + d) % mod)
    return fast_doubling(n)[0] % mod

