def main():
    import sys
    n = int(sys.stdin.readline())
    w = sys.stdin.readline().strip()

    # Suffix Automaton construction
    class State:
        def __init__(self):
            self.next = {}
            self.link = -1
            self.len = 0

    sa = [State()]
    last = 0
    for c in w:
        p = last
        curr = len(sa)
        sa.append(State())
        sa[curr].len = sa[p].len + 1
        while p >= 0 and c not in sa[p].next:
            sa[p].next[c] = curr
            p = sa[p].link
        if p == -1:
            sa[curr].link = 0
        else:
            q = sa[p].next[c]
            if sa[p].len + 1 == sa[q].len:
                sa[curr].link = q
            else:
                clone = len(sa)
                sa.append(State())
                sa[clone].len = sa[p].len + 1
                sa[clone].next = sa[q].next.copy()
                sa[clone].link = sa[q].link
                while p >= 0 and sa[p].next.get(c, -1) == q:
                    sa[p].next[c] = clone
                    p = sa[p].link
                sa[q].link = clone
                sa[curr].link = clone
        last = curr

    # Now, compute dp for each node
    nodes = sorted(enumerate(sa), key=lambda x: -x[1].len)
    dp = [1] * len(sa)
    max_len = 1
    for idx, node in nodes:
        for c in node.next.values():
            if sa[c].len >= 2 * node.len - 1:
                dp[idx] = max(dp[idx], 1 + dp[c])
        max_len = max(max_len, dp[idx])
    print(max_len)

