memo_len = {}

def compute_length(x):
    if x in memo_len:
        return memo_len[x]
    if x == 0 or x == 1:
        memo_len[x] = 1
        return 1
    stack = []
    current = x
    while current > 1:
        stack.append(current)
        current = current // 2
    res = 1
    for num in reversed(stack):
        res = 2 * res + 1
    memo_len[x] = res
    return res

def get_value(x, pos):
    if x == 0:
        return 0
    if x == 1:
        return 1
    half = x // 2
    len_left = compute_length(half)
    if pos <= len_left:
        return get_value(half, pos)
    elif pos == len_left + 1:
        return x % 2
    else:
        return get_value(half, pos - (len_left + 1))

