import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n+1)]
    reverse_edges = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        reverse_edges[v].append(u)

    visited = [False] * (n + 1)
    order = []

    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in reversed(edges[node]):
                if not visited[v]:
                    stack.append((v, False))

    for u in range(1, n+1):
        if not visited[u]:
            dfs(u)

    visited = [False] * (n + 1)
    component = [0] * (n + 1)
    label = 0

    def reverse_dfs(u, current_label):
        stack = [u]
        visited[u] = True
        component[u] = current_label
        while stack:
            node = stack.pop()
            for v in reverse_edges[node]:
                if not visited[v]:
                    visited[v] = True
                    component[v] = current_label
                    stack.append(v)

    for u in reversed(order):
        if not visited[u]:
            label += 1
            reverse_dfs(u, label)

    condensation = defaultdict(set)
    for u in range(1, n+1):
        for v in edges[u]:
            if component[u] != component[v]:
                condensation[component[u]].add(component[v])

    sink_components = []
    for comp in set(component[1:]):
        if comp not in condensation or len(condensation[comp]) == 0:
            sink_components.append(comp)

    if len(sink_components) != 1:
        print(-1)
        return

    sink_label = sink_components[0]
    nodes_in_sink = [u for u in range(1, n+1) if component[u] == sink_label]

    in_degree = defaultdict(int)
    out_degree = defaultdict(int)
    for u in nodes_in_sink:
        for v in edges[u]:
            if component[v] == sink_label:
                in_degree[v] += 1
                out_degree[u] += 1

    max_degree = -1
    selected_node = -1
    for node in nodes_in_sink:
        current = in_degree.get(node, 0) + out_degree.get(node, 0)
        if current > max_degree:
            max_degree = current
            selected_node = node

    print(selected_node)

if __name__ == "__main__":
    main()

