import sys

def max_hist_area(heights):
    stack = []
    max_area = 0
    n = len(heights)
    for i in range(n):
        while stack and heights[i] < heights[stack[-1]]:
            h = heights[stack.pop()]
            left = stack[-1] if stack else -1
            current_area = h * (i - left - 1)
            if current_area > max_area:
                max_area = current_area
        stack.append(i)
    while stack:
        h = heights[stack.pop()]
        left = stack[-1] if stack else -1
        current_area = h * (n - left - 1)
        if current_area > max_area:
            max_area = current_area
    return max_area

