import sys

def generate_partitions(n):
    partitions = []
    def helper(current, max_part, remaining):
        if remaining == 0:
            partitions.append(current.copy())
            return
        start = min(max_part, remaining)
        for part in range(start, 0, -1):
            current.append(part)
            helper(current, part, remaining - part)
            current.pop()
    helper([], n, n)
    return partitions

