import heapq

def main():
    while True:
        H, W = map(int, input().split())
        if H == 0 and W == 0:
            break
        grid = []
        for _ in range(H):
            row = list(map(int, input().split()))
            grid.append(row)
        hearts = [(i, j) for i in range(H) for j in range(W) if grid[i][j] == 1]
        k = len(hearts)
        total_0s = H * W - k
        if k <= 1:
            print(total_0s)
            continue

        heart_index = [[-1] * W for _ in range(H)]
        for idx, (x, y) in enumerate(hearts):
            heart_index[x][y] = idx
        full_mask = (1 << k) - 1
        INF = float('inf')
        dp = [[[INF] * W for _ in range(H)] for __ in range(1 << k)]
        heap = []

        for idx, (x, y) in enumerate(hearts):
            mask = 1 << idx
            dp[mask][x][y] = 0
            heapq.heappush(heap, (0, mask, x, y))

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        min_cost = INF

        while heap:
            cost, mask, x, y = heapq.heappop(heap)
            if cost > dp[mask][x][y]:
                continue
            if mask == full_mask:
                min_cost = cost
                break
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] == 1:
                        idx = heart_index[nx][ny]
                        new_mask = mask | (1 << idx)
                        if dp[new_mask][nx][ny] > cost:
                            dp[new_mask][nx][ny] = cost
                            heapq.heappush(heap, (cost, new_mask, nx, ny))
                    else:
                        new_cost = cost + 1
                        new_mask = mask
                        if dp[new_mask][nx][ny] > new_cost:
                            dp[new_mask][nx][ny] = new_cost
                            heapq.heappush(heap, (new_cost, new_mask, nx, ny))

        print(total_0s - min_cost if min_cost != INF else 0)

