    main()

import sys

MOD = 2011

def modinv(y):
    return pow(y, MOD-2, MOD)

def trim_cell(lines):
    if not lines:
        return []
    # Trim rows
    start_row = 0
    while start_row < len(lines) and all(c == ' ' for c in lines[start_row]):
        start_row += 1
    if start_row >= len(lines):
        return []
    end_row = len(lines) - 1
    while end_row >= 0 and all(c == ' ' for c in lines[end_row]):
        end_row -= 1
    trimmed_rows = lines[start_row:end_row+1]
    if not trimmed_rows:
        return []
    # Trim columns
    start_col = 0
    while start_col < len(trimmed_rows[0]):
        if any(row[start_col] != ' ' for row in trimmed_rows):
            break
        start_col += 1
    else:
        return []
    end_col = len(trimmed_rows[0]) - 1
    while end_col >= 0:
        if any(row[end_col] != ' ' for row in trimmed_rows):
            break
        end_col -= 1
    return [row[start_col:end_col+1] for row in trimmed_rows]

def parse_digit(cell):
    if len(cell) == 1 and len(cell[0]) == 1 and cell[0][0].isdigit():
        return int(cell[0][0]), 0
    return None, None

def parse_primary(cell):
    trimmed_cell = trim_cell(cell)
    if not trimmed_cell:
        return None, None
    # Check if it's a digit
    val, baseline = parse_digit(trimmed_cell)
    if val is not None:
        return val, baseline
    # Check if it's a fraction
    val, baseline = parse_fraction(trimmed_cell)
    if val is not None:
        return val, baseline
    # Check if parenthesized
    if len(trimmed_cell[0]) > 0 and trimmed_cell[0][0] == '(':
        expr_cell = []
        for row in trimmed_cell:
            if len(row) < 2:
                return None, None
            expr_cell.append(row[1:-1].strip())
        expr_cell = trim_cell(expr_cell)
        if not expr_cell:
            return None, None
        val, baseline = parse_expr(expr_cell)
        if val is not None:
            return val, baseline
    return None, None

def parse_fraction(cell):
    for v_line in range(len(cell)):
        line = ''.join(cell[v_line])
        if '---' in line.replace(' ', ''):
            numerator_lines = trim_cell(cell[:v_line])
            denominator_lines = trim_cell(cell[v_line+1:])
            if not numerator_lines or not denominator_lines:
                continue
            num = parse_expr(numerator_lines)
            den = parse_expr(denominator_lines)
            if num is None or den is None:
                continue
            inv_den = modinv(den)
            return (num * inv_den) % MOD, v_line
    return None, None

def parse_powexpr(cell):
    primary_val, baseline = parse_primary(cell)
    if primary_val is None:
        return None, None
    if baseline > 0:
        exponent_line = baseline - 1
        if exponent_line >= len(cell):
            return primary_val, baseline
        line = cell[exponent_line]
        trimmed = trim_cell([line])
        if trimmed and len(trimmed) == 1 and len(trimmed[0]) == 1 and trimmed[0][0].isdigit():
            exponent = int(trimmed[0][0])
            return pow(primary_val, exponent, MOD), baseline
    return primary_val, baseline

def parse_factor(cell):
    trimmed_cell = trim_cell(cell)
    if not trimmed_cell:
        return None, None
    # Check unary minus
    if trimmed_cell[0][0] == '-':
        rest_cell = []
        for row in trimmed_cell:
            if len(row) < 1:
                continue
            rest_cell.append(row[1:].lstrip())
        rest_cell = trim_cell(rest_cell)
        if not rest_cell:
            return None, None
        val, baseline = parse_factor(rest_cell)
        if val is not None:
            return (-val) % MOD, baseline
    # Check powexpr
    val, baseline = parse_powexpr(trimmed_cell)
    if val is not None:
        return val, baseline
    # Check fraction
    val, baseline = parse_fraction(trimmed_cell)
    if val is not None:
        return val, baseline
    # Check primary
    val, baseline = parse_primary(trimmed_cell)
    return val, baseline

def parse_term(cell):
    cell = trim_cell(cell)
    if not cell:
        return None, None
    baseline = None
    for possible_baseline in range(len(cell)):
        line = cell[possible_baseline]
        for i in range(len(line)):
            if line[i] == '*':
                left_cell = [row[:i] for row in cell]
                left_trimmed = trim_cell(left_cell)
                right_cell = [row[i+1:] for row in cell]
                right_trimmed = trim_cell(right_cell)
                if not left_trimmed or not right_trimmed:
                    continue
                left_val, _ = parse_term(left_trimmed)
                right_val, _ = parse_factor(right_trimmed)
                if left_val is not None and right_val is not None:
                    return (left_val * right_val) % MOD, possible_baseline
    return parse_factor(cell)

def parse_expr(cell):
    cell = trim_cell(cell)
    if not cell:
        return None, None
    for possible_baseline in range(len(cell)):
        line = cell[possible_baseline]
        for i in range(len(line)):
            if line[i] in '+-':
                left_cell = [row[:i] for row in cell]
                left_trimmed = trim_cell(left_cell)
                right_cell = [row[i+1:] for row in cell]
                right_trimmed = trim_cell(right_cell)
                if not left_trimmed or not right_trimmed:
                    continue
                left_val, _ = parse_expr(left_trimmed)
                right_val, _ = parse_term(right_trimmed)
                if left_val is not None and right_val is not None:
                    if line[i] == '+':
                        res = (left_val + right_val) % MOD
                    else:
                        res = (left_val - right_val) % MOD
                    return res, possible_baseline
    return parse_term(cell)

def main():
    for line in sys.stdin:
        n = int(line.strip())
        if n == 0:
            break
        cell = []
        for _ in range(n):
            row = sys.stdin.readline().strip().replace('.', ' ')
            cell.append(row)
        trimmed = trim_cell(cell)
        val, _ = parse_expr(trimmed)
        print(val % MOD if val is not None else 0)

