from collections import defaultdict, deque
import bisect

def main():
    n = int(sys.stdin.readline())
    points = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    existing = set(points)
    if n == 0:
        print(0)
        return

    # Generate all possible t candidates from dx and dy of all pairs
    dxs = set()
    dys = set()
    for i in range(n):
        for j in range(i+1, n):
            dx = abs(points[i][0] - points[j][0])
            dy = abs(points[i][1] - points[j][1])
            if dx > 0:
                dxs.add(dx)
            if dy > 0:
                dys.add(dy)

    def get_divisors(x):
        if x == 0:
            return set()
        divisors = set()
        for i in range(1, int(math.isqrt(x)) + 1):
            if x % i == 0:
                divisors.add(i)
                divisors.add(x // i)
        return divisors

    t_candidates = set()
    for dx in dxs:
        t_candidates.update(get_divisors(dx))
    for dy in dys:
        t_candidates.update(get_divisors(dy))
    t_candidates.add(1)
    t_candidates = sorted(t_candidates, reverse=True)
    t_candidates.append(0)  # handle separately

    def is_connected(points_list):
        rows = defaultdict(list)
        cols = defaultdict(list)
        for x, y in points_list:
            rows[y].append(x)
            cols[x].append(y)
        for y in rows:
            rows[y].sort()
        for x in cols:
            cols[x].sort()

        adj = defaultdict(list)
        for x, y in points_list:
            row = rows[y]
            idx = bisect.bisect_left(row, x)
            if idx > 0:
                left = row[idx-1]
                adj[(x, y)].append( (left, y) )
            if idx < len(row)-1:
                right = row[idx+1]
                adj[(x, y)].append( (right, y) )
            col = cols[x]
            idy = bisect.bisect_left(col, y)
            if idy > 0:
                down = col[idy-1]
                adj[(x, y)].append( (x, down) )
            if idy < len(col)-1:
                up = col[idy+1]
                adj[(x, y)].append( (x, up) )

        visited = set()
        if not points_list:
            return True
        start = points_list[0]
        queue = deque([start])
        visited.add(start)
        while queue:
            current = queue.popleft()
            for neighbor in adj.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited) == len(points_list)

    min_t = None
    # Check case 1: no new point
    for t in sorted(t_candidates):
        if t == 0:
            continue
        x_mod = points[0][0] % t
        y_mod = points[0][1] % t
        valid = True
        for x, y in points:
            if x % t != x_mod or y % t != y_mod:
                valid = False
                break
        if not valid:
            continue
        if is_connected(points):
            min_t = t

    # Check case 2: add new point
    for t in sorted(t_candidates):
        if t == 0:
            continue
        x_mod_base = points[0][0] % t
        y_mod_base = points[0][1] % t
        valid = True
        for x, y in points:
            if x % t != x_mod_base or y % t != y_mod_base:
                valid = False
                break
        if not valid:
            continue
        new_point = (x_mod_base, y_mod_base)
        if new_point in existing:
            continue
        new_points = points + [new_point]
        if is_connected(new_points):
            if (min_t is None) or (t < min_t):
                min_t = t

    if min_t is not None:
        print(min_t)
    else:
        # Check t=0 case (all points are the same, but problem states all are unique, so impossible)
        print(-1)

