    nge = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and s[stack[-1]] <= s[i]:
            stack.pop()
        if stack:
            nge[i] = stack[-1]
        stack.append(i)

    # Precompute log_table for sparse table
    log_table = [0] * (n + 1)
    for i in range(2, n + 1):
        log_table[i] = log_table[i // 2] + 1
    max_level = log_table[n] + 1

    # Build sparse table for range maximum queries (indices)
    st = []
    st.append(list(range(n)))
    for j in range(1, max_level):
        prev = st[j-1]
        curr_len = n - (1 << j) + 1
        curr = []
        for i in range(curr_len):
            a = prev[i]
            b = prev[i + (1 << (j-1))]
            if s[a] > s[b]:
                curr.append(a)
            else:
                curr.append(b)
        st.append(curr)

    # Function to get the index of maximum in [l, r]
    def get_max_index(l, r):
        if l > r:
            return -1
        length = r - l + 1
        if length == 0:
