import sys
from collections import deque

def main():
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    r, c = map(int, sys.stdin.readline().split())
    grid = []
    start = (-1, -1)
    exit_pos = (-1, -1)
    for i in range(r):
        line = sys.stdin.readline().strip()
        grid.append(line)
        if 'S' in line:
            start = (i, line.index('S'))
        if 'E' in line:
            exit_pos = (i, line.index('E'))

    # BFS from start to compute d_p (distance from start)
    d_p = [[-1 for _ in range(c)] for _ in range(r)]
    q = deque()
    q.append(start)
    d_p[start[0]][start[1]] = 0
    while q:
        x, y = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < r and 0 <= ny < c:
                if grid[nx][ny] != 'T' and d_p[nx][ny] == -1:
                    d_p[nx][ny] = d_p[x][y] + 1
                    q.append((nx, ny))

    # BFS from exit to compute d_e (distance to exit)
    d_e = [[-1 for _ in range(c)] for _ in range(r)]
    q = deque()
    q.append(exit_pos)
    d_e[exit_pos[0]][exit_pos[1]] = 0
    while q:
        x, y = q.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < r and 0 <= ny < c:
                if grid[nx][ny] != 'T' and d_e[nx][ny] == -1:
                    d_e[nx][ny] = d_e[x][y] + 1
                    q.append((nx, ny))

    K = d_p[exit_pos[0]][exit_pos[1]]
    if K == -1:
        # According to problem statement, it's guaranteed to be possible.
        print(0)
        return

    ans = 0
    for i in range(r):
        for j in range(c):
            cell = grid[i][j]
            if cell.isdigit() and cell not in {'S', 'E'} and cell != '0':
                cnt = int(cell)
                if d_e[i][j] != -1 and d_e[i][j] <= K:
                    ans += cnt
    print(ans)

