import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    strings = []
    for i in range(n):
        s = sys.stdin.readline().strip()
        strings.append((len(s), s, i + 1))  # (length, string, original index)

    # Sort by length, then by original order to handle ties
    strings.sort(key=lambda x: (x[0], x[2]))
    sorted_strings = [s[1] for s in strings]
    indices = [s[2] for s in strings]
    length = [s[0] for s in strings]

    # Preprocess edges: for each i < j, if len[i] < len[j] and i is substring of j
    edges = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if length[i] < length[j] and sorted_strings[i] in sorted_strings[j]:
                edges[i].append(j)

    # Build bipartite graph for Hopcroft-Karp
    graph = [[] for _ in range(n)]
    for u in range(n):
        for v in edges[u]:
            graph[u].append(v)

    # Hopcroft-Karp algorithm
    def hopcroft_karp():
        pair_U = [-1] * n
        pair_V = [-1] * n
        dist = [0] * n

        def bfs():
            queue = deque()
            for u in range(n):
                if pair_U[u] == -1:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist_null = float('inf')
            while queue:
                u = queue.popleft()
                if dist[u] < dist_null:
                    for v in graph[u]:
                        if pair_V[v] == -1:
                            dist_null = dist[u] + 1
                        elif dist[pair_V[v]] == float('inf'):
                            dist[pair_V[v]] = dist[u] + 1
                            queue.append(pair_V[v])
            return dist_null != float('inf')

        def dfs(u):
            for v in graph[u]:
                if pair_V[v] == -1 or (dist[pair_V[v]] == dist[u] + 1 and dfs(pair_V[v])):
                    pair_U[u] = v
                    pair_V[v] = u
                    return True
            dist[u] = float('inf')
            return False

        result = 0
        while bfs():
            for u in range(n):
                if pair_U[u] == -1:
                    if dfs(u):
                        result += 1
        return (result, pair_U, pair_V)

    max_matching, pair_U, pair_V = hopcroft_karp()
    max_antichain_size = n - max_matching

    # Find minimum vertex cover using Konig's theorem
    # BFS to find all nodes in U that are reachable via alternating paths
    visited_U = [False] * n
    visited_V = [False] * n
    q = deque()
    for u in range(n):
        if pair_U[u] == -1:
            visited_U[u] = True
            q.append(u)

    while q:
        u = q.popleft()
        for v in graph[u]:
            if not visited_V[v] and pair_V[v] != u:
                visited_V[v] = True
                if pair_V[v] != -1 and not visited_U[pair_V[v]]:
                    visited_U[pair_V[v]] = True
                    q.append(pair_V[v])

    # Vertex cover is visited_U (unvisited) and visited_V (visited)
    # So the nodes not in the vertex cover are !visited_U and !visited_V
    antichain = []
    for i in range(n):
        if not visited_U[i] and not visited_V[i]:
            antichain.append(indices[i])

    print(max_antichain_size)
    print(' '.join(map(str, sorted(antichain))))

