import sys

def point_in_triangle(A, B, C, P):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    c1 = cross(A, B, P)
    c2 = cross(B, C, P)
    c3 = cross(C, A, P)
    return (c1 >= 0 and c2 >= 0 and c3 >= 0) or (c1 <= 0 and c2 <= 0 and c3 <= 0)

def distance_sq_point_to_segment(P, A, B):
    dx = B[0] - A[0]
    dy = B[1] - A[1]
    len_sq = dx * dx + dy * dy
    if len_sq == 0:
        return (P[0] - A[0])**2 + (P[1] - A[1])**2
    t = ((P[0] - A[0]) * dx + (P[1] - A[1]) * dy)
    if t <= 0:
        return (P[0] - A[0])**2 + (P[1] - A[1])**2
    if t >= len_sq:
        return (P[0] - B[0])**2 + (P[1] - B[1])**2
    cross_prod = (B[0] - A[0]) * (P[1] - A[1]) - (B[1] - A[1]) * (P[0] - A[0])
    return (cross_prod ** 2) / len_sq

