MOD = 10**9 + 9

def multiply_matrix(A, B):
    n = len(A)
    l = len(B)
    m = len(B[0]) if l > 0 else 0
    result = [[0] * m for _ in range(n)]
    for i in range(n):
        for k in range(l):
            a = A[i][k]
            if a == 0:
                continue
            for j in range(m):
                result[i][j] = (result[i][j] + a * B[k][j]) % MOD
    return result

def matrix_power(mat, power):
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    while power > 0:
        if power % 2 == 1:
            result = multiply_matrix(result, mat)
        mat = multiply_matrix(mat, mat)
        power //= 2
    return result

def multiply_matrix_vector(mat, vec):
    n = len(mat)
    m = len(vec)
    result = [0] * n
    for i in range(n):
        for j in range(m):
            result[i] = (result[i] + mat[i][j] * vec[j]) % MOD
    return result

def main():
    case = 1
    while True:
        W, H, N = map(int, input().split())
        if W == 0 and H == 0 and N == 0:
            break
        obst = set()
        has_end_blocked = False
        for _ in range(N):
            x, y = map(int, input().split())
            x_obs = x - 1
            if x_obs == W - 1 and y == H:
                has_end_blocked = True
            obst.add((x_obs, y))
        if has_end_blocked:
            print(f"Case {case}: 0")
            case += 1
            continue
        if (0, 1) in obst:
            print(f"Case {case}: 0")
            case += 1
            continue
        sorted_obs = sorted([p for p in obst if p[1] != 1 and p[1] != H], key=lambda x: x[1])
        W_size = W
        base = [[0] * W_size for _ in range(W_size)]
        for x_prev in range(W_size):
            for dx in (-1, 0, 1):
                x_curr = x_prev + dx
                if 0 <= x_curr < W_size:
                    base[x_curr][x_prev] += 1
        dp = [0] * W_size
        dp[0] = 1
        current_y = 1
        for (x_obs, y_obs) in sorted_obs:
            if y_obs <= current_y:
                continue
            steps = (y_obs - 1) - current_y
            if steps > 0:
                mat = matrix_power(base, steps)
                dp = multiply_matrix_vector(mat, dp)
                if all(v == 0 for v in dp):
                    break
            next_dp = [0] * W_size
            for x_prev in range(W_size):
                if dp[x_prev] == 0:
                    continue
                for dx in (-1, 0, 1):
                    x_curr = x_prev + dx
                    if 0 <= x_curr < W_size and (x_curr, y_obs) not in obst:
                        next_dp[x_curr] = (next_dp[x_curr] + dp[x_prev]) % MOD
            for x in range(W_size):
                if (x, y_obs) in obst:
                    next_dp[x] = 0
            dp = next_dp
            current_y = y_obs
            if all(v == 0 for v in dp):
                break
        if current_y < H:
            steps_remaining = H - current_y
            if steps_remaining > 0:
                mat = matrix_power(base, steps_remaining)
                dp = multiply_matrix_vector(mat, dp)
        print(f"Case {case}: {dp[W_size - 1] % MOD if W_size >= 1 else 0}")
        case += 1

