import sys
from itertools import permutations

EPS = 1e-8

def reflect(point, wall):
    (x, y) = point
    ((x1, y1), (x2, y2)) = wall
    a = y2 - y1
    b = x1 - x2
    c = x2 * y1 - x1 * y2
    denom = a * a + b * b
    if denom == 0:
        return (x, y)
    numerator = a * x + b * y + c
    d = numerator / denom
    x_ref = x - 2 * a * d
    y_ref = y - 2 * b * d
    return (x_ref, y_ref)

def solve():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        n = int(line.strip())
        if n == 0:
            break
        sx, sy = map(int, sys.stdin.readline().split())
        points = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
        walls = []
        for i in range(n):
            j = (i + 1) % n
            walls.append((points[i], points[j]))
        count = 0
        for perm in permutations(walls):
            current = (sx, sy)
            for wall in reversed(perm):
                current = reflect(current, wall)
            s_prime = current
            intersections = []
            for idx, wall_seg in enumerate(walls):
                (x1, y1), (x2, y2) = wall_seg
                dx = s_prime[0] - sx
                dy = s_prime[1] - sy
                if dx == 0 and dy == 0:
                    continue
                denominator = dx * (y2 - y1) - dy * (x2 - x1)
                if denominator == 0:
                    continue
                t_numerator = (x1 - sx) * (y2 - y1) - (y1 - sy) * (x2 - x1)
                u_numerator = (x1 - sx) * dy - (y1 - sy) * dx
                t = t_numerator / denominator
                u = u_numerator / denominator
                if u < EPS or u > 1 - EPS:
                    continue
                if t < -EPS:
                    continue
                intersections.append((t, idx))
            intersections.sort()
            valid = len(intersections) >= n
            if valid:
                for k in range(n):
                    expected_wall = perm[k]
                    expected_idx = walls.index(expected_wall)
                    if intersections[k][1] != expected_idx:
                        valid = False
                        break
            if valid:
                count += 1
        print(count)

