import sys

def compute_super_factor_sum(k):
    factors = {}
    n = k
    # Handle factor 2
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    if count > 0:
        factors[2] = count
    # Check odd factors
    p = 3
    while p * p <= n:
        count = 0
        while n % p == 0:
            count += 1
            n //= p
        if count > 0:
            factors[p] = count
        p += 2
    # If remaining n is a prime
    if n > 1:
        factors[n] = 1
    return sum(a * p for p, a in factors.items())

