import sys
from collections import defaultdict

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    vertical_cuts = defaultdict(list)
    horizontal_cuts = defaultdict(list)

    for _ in range(k):
        x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
        if x1 == x2:
            x = x1
            y_start = min(y1, y2)
            y_end = max(y1, y2)
            vertical_cuts[x].append((y_start, y_end))
        else:
            y = y1
            x_start = min(x1, x2)
            x_end = max(x1, x2)
            horizontal_cuts[y].append((x_start, x_end))

    vertical_lines = {0, n}
    for x in vertical_cuts:
        intervals = vertical_cuts[x]
        if not intervals:
            continue
        sorted_intervals = sorted(intervals, key=lambda pair: pair[0])
        merged = [list(sorted_intervals[0])]
        for s, e in sorted_intervals[1:]:
            last = merged[-1]
            if s <= last[1]:
                merged[-1][1] = max(last[1], e)
            else:
                merged.append([s, e])
        total = sum(e - s for s, e in merged)
        if total == m:
            vertical_lines.add(x)
    vertical_lines = sorted(vertical_lines)

    horizontal_lines = {0, m}
    for y in horizontal_cuts:
        intervals = horizontal_cuts[y]
        if not intervals:
            continue
        sorted_intervals = sorted(intervals, key=lambda pair: pair[0])
        merged = [list(sorted_intervals[0])]
        for s, e in sorted_intervals[1:]:
            last = merged[-1]
            if s <= last[1]:
                merged[-1][1] = max(last[1], e)
            else:
                merged.append([s, e])
        total = sum(e - s for s, e in merged)
        if total == n:
            horizontal_lines.add(y)
    horizontal_lines = sorted(horizontal_lines)

    total_xor = 0
    for i in range(len(vertical_lines) - 1):
        x_prev = vertical_lines[i]
        x_curr = vertical_lines[i + 1]
        w = x_curr - x_prev
        for j in range(len(horizontal_lines) - 1):
            y_prev = horizontal_lines[j]
            y_curr = horizontal_lines[j + 1]
            h = y_curr - y_prev
            grundy = (w - 1) ^ (h - 1)
            total_xor ^= grundy

    if total_xor == 0:
        print("SECOND")
        return

    for i in range(len(vertical_lines) - 1):
        x_prev = vertical_lines[i]
        x_curr = vertical_lines[i + 1]
        w = x_curr - x_prev
        for j in range(len(horizontal_lines) - 1):
            y_prev = horizontal_lines[j]
            y_curr = horizontal_lines[j + 1]
            h = y_curr - y_prev
            current_grundy = (w - 1) ^ (h - 1)
            T = total_xor ^ current_grundy

            S = w - 2
            if S >= 0 and T <= S:
                if (S - T) % 2 == 0:
                    c = (S - T) // 2
                    if (c & T) == 0:
                        a = T | c
                        i_split = a + 1
                        if 0 < i_split < w:
                            x_split = x_prev + i_split
                            print("FIRST")
                            print(f"{x_split} {y_prev} {x_split} {y_curr}")
                            return

            S_h = h - 2
            if S_h >= 0 and T <= S_h:
                if (S_h - T) % 2 == 0:
                    c_h = (S_h - T) // 2
                    if (c_h & T) == 0:
                        a_h = T | c_h
                        j_split = a_h + 1
                        if 0 < j_split < h:
                            y_split = y_prev + j_split
                            print("FIRST")
                            print(f"{x_prev} {y_split} {x_curr} {y_split}")
                            return

