import heapq

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    if n == 1:
        print(0)
        return

    prev = [-1] * n
    next = [-1] * n
    for i in range(n):
        prev[i] = i - 1
        next[i] = i + 1
    prev[0] = -1
    next[-1] = -1

    deleted = [False] * n
    heap = []

    for i in range(n):
        if prev[i] == -1 or next[i] == -1:
            current_min = 0
        else:
            current_min = min(a[prev[i]], a[next[i]])
        heapq.heappush(heap, (-current_min, i, prev[i], next[i]))

    sum_points = 0

    while heap:
        current_min_neg, node, stored_prev, stored_next = heapq.heappop(heap)
        current_min = -current_min_neg
        if deleted[node]:
            continue
        if prev[node] != stored_prev or next[node] != stored_next:
            continue
        sum_points += current_min
        deleted[node] = True

        p = prev[node]
        nxt = next[node]
        if p != -1:
            next[p] = nxt
        if nxt != -1:
            prev[nxt] = p

        for neighbor in [p, nxt]:
            if neighbor == -1 or deleted[neighbor]:
                continue
            if prev[neighbor] == -1 or next[neighbor] == -1:
                new_min = 0
            else:
                new_min = min(a[prev[neighbor]], a[next[neighbor]])
            heapq.heappush(heap, (-new_min, neighbor, prev[neighbor], next[neighbor]))

    print(sum_points)

