import sys
from fractions import Fraction
from collections import defaultdict

def main():
    k, t = map(int, sys.stdin.readline().split())

    # Precompute factorials up to 160
    max_fact = 160
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i-1] * i

    def count_valid(current_count, m, t):
        s_list = [t - cnt for cnt in current_count]
        coeffs = defaultdict(Fraction)
        coeffs[0] = Fraction(1)
        for d in range(16):
            s = min(s_list[d], m)
            new_coeffs = defaultdict(Fraction)
            for exp in coeffs:
                for k in range(0, s + 1):
                    new_exp = exp + k
                    if new_exp > m:
                        continue
                    term = coeffs[exp] * Fraction(1, fact[k])
                    new_coeffs[new_exp] += term
            coeffs = new_coeffs
        if m not in coeffs:
            return 0
        total = coeffs[m] * fact[m]
        return total.numerator // total.denominator

    # Determine the length of the k-th number
    current_k = k
    length = 1
    while True:
        count_L = 0
        if length == 1:
            count_L = 15  # digits 1-9, a-f (15 options)
        else:
            for first_digit in range(1, 16):
                current_count = [0] * 16
                current_count[first_digit] = 1
                if current_count[first_digit] > t:
                    continue
                cnt = count_valid(current_count, length - 1, t)
                count_L += cnt
        if current_k > count_L:
            current_k -= count_L
            length += 1
        else:
            break

    # Generate the number digit by digit
    current_count = [0] * 16
    result = []
    remaining = length
    for i in range(length):
        if i == 0:
            possible_digits = list(range(1, 16))  # 1-15
        else:
            possible_digits = list(range(0, 16))  # 0-15

        for d in possible_digits:
            if current_count[d] >= t:
                continue
            # Try this digit
            current_count[d] += 1
            remaining_positions = length - i - 1
            if remaining_positions == 0:
                # Check if all counts are <= t
                valid = True
                for cnt in current_count:
                    if cnt > t:
                        valid = False
                        break
                cnt = 1 if valid else 0
            else:
                cnt = count_valid(current_count, remaining_positions, t)
            if cnt >= current_k:
                result.append(d)
                remaining -= 1
                break
            else:
                current_k -= cnt
                current_count[d] -= 1

    # Convert digits to hexadecimal string
    hex_digits = '0123456789abcdef'
    hex_str = ''.join(hex_digits[d] for d in result)
    print(hex_str)

