    main()

import sys
from collections import deque

def main():
    n, k = map(int, sys.stdin.readline().split())
    main_courses = list(map(int, sys.stdin.readline().split()))
    prerequisites = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        parts = list(map(int, sys.stdin.readline().split()))
        ti = parts[0]
        if ti > 0:
            prerequisites[i] = parts[1:]
        else:
            prerequisites[i] = []

    required = set(main_courses)
    queue = deque(main_courses)
    while queue:
        course = queue.popleft()
        for prereq in prerequisites[course]:
            if prereq not in required:
                required.add(prereq)
                queue.append(prereq)

    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)
    for u in required:
        for v in prerequisites[u]:
            adj[v].append(u)
            in_degree[u] += 1

    order = []
    queue = deque()
    for u in required:
        if in_degree[u] == 0:
            queue.append(u)

    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(order) != len(required):
        print(-1)
    else:
        print(len(order))
        print(' '.join(map(str, order)))

