import sys
import bisect
from collections import deque

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        w, h = map(int, line.strip().split())
        if w == 0 and h == 0:
            break
        n = int(sys.stdin.readline())
        rectangles = []
        x_vals = {0, w}
        y_vals = {0, h}
        for _ in range(n):
            x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
            rectangles.append((x1, y1, x2, y2))
            x_vals.update([x1, x2])
            y_vals.update([y1, y2])
        x_coords = sorted(x_vals)
        y_coords = sorted(y_vals)
        nx = len(x_coords) - 1
        ny = len(y_coords) - 1

        merged_intervals = [[] for _ in range(nx)]
        for x1, y1, x2, y2 in rectangles:
            start_x = bisect.bisect_left(x_coords, x1)
            end_x = bisect.bisect_left(x_coords, x2)
            start_y = bisect.bisect_left(y_coords, y1)
            end_y = bisect.bisect_left(y_coords, y2)
            y_start = y_coords[start_y]
            y_end = y_coords[end_y]
            for x_idx in range(start_x, end_x):
                merged_intervals[x_idx].append((y_start, y_end))

        for x_idx in range(nx):
            intervals = merged_intervals[x_idx]
            if not intervals:
                continue
            intervals.sort()
            merged = []
            current_start, current_end = intervals[0]
            for s, e in intervals[1:]:
                if s <= current_end:
                    current_end = max(current_end, e)
                else:
                    merged.append((current_start, current_end))
                    current_start, current_end = s, e
            merged.append((current_start, current_end))
            merged_intervals[x_idx] = merged

        visited = [[False] * ny for _ in range(nx)]
        count = 0

        for x_idx in range(nx):
            for y_idx in range(ny):
                if visited[x_idx][y_idx]:
                    continue
                y_start = y_coords[y_idx]
                y_end = y_coords[y_idx+1]
                intervals = merged_intervals[x_idx]
                covered = False
                if intervals:
                    starts = [s for s, e in intervals]
                    pos = bisect.bisect_right(starts, y_start) - 1
                    if pos >= 0:
                        s, e = intervals[pos]
                        if y_start < e and e >= y_end:
                            covered = True
                if not covered:
                    count += 1
                    queue = deque()
                    queue.append((x_idx, y_idx))
                    visited[x_idx][y_idx] = True
                    while queue:
                        cx, cy = queue.popleft()
                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nx_, ny_ = cx + dx, cy + dy
                            if 0 <= nx_ < nx and 0 <= ny_ < ny and not visited[nx_][ny_]:
                                y_start_nx = y_coords[ny_]
                                y_end_nx = y_coords[ny_ + 1]
                                intervals_nx = merged_intervals[nx_]
                                cell_covered = False
                                if intervals_nx:
                                    starts_nx = [s for s, e in intervals_nx]
                                    pos_nx = bisect.bisect_right(starts_nx, y_start_nx) - 1
                                    if pos_nx >= 0:
                                        s_nx, e_nx = intervals_nx[pos_nx]
                                        if y_start_nx < e_nx and e_nx >= y_end_nx:
                                            cell_covered = True
                                if not cell_covered:
                                    visited[nx_][ny_] = True
                                    queue.append((nx_, ny_))
        print(count)

