import sys
from itertools import combinations

def read_grid(n):
    grid = []
    for _ in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        grid.append(row)
    return grid

def generate_rect_masks(n):
    rect_masks = []
    for x1 in range(n):
        for x2 in range(x1, n):
            for y1 in range(n):
                for y2 in range(y1, n):
                    mask = 0
                    for i in range(x1, x2 + 1):
                        for j in range(y1, y2 + 1):
                            pos = i * n + j
                            mask |= 1 << pos
                    rect_masks.append(mask)
    return list(set(rect_masks))  # Remove duplicates

def solve():
    for line in sys.stdin:
        n = int(line.strip())
        if n == 0:
            break
        grid = read_grid(n)
        target_mask = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j]:
                    target_mask |= 1 << (i * n + j)
        rect_masks = generate_rect_masks(n)
        found = False
        for k in range(1, 6):
            for combo in combinations(rect_masks, k):
                xor = 0
                for mask in combo:
                    xor ^= mask
                if xor == target_mask:
                    print('myon' * k)
                    found = True
                    break
            if found:
                break

