            INF = 1 << 60
            dist = [[INF] * 101 for _ in range(N + 1)]
            dist[start][0] = 0
            heap = []
            heapq.heappush(heap, (0, start, 0))
            while heap:
                a, u, k = heapq.heappop(heap)
                if a > dist[u][k]:
                    continue
                if u == target:
