                for edge in adj[u]:
                    v, is_magical, w = edge
                    new_k = k + 1 if is_magical else k
                    new_a = a + (0 if is_magical else w)
                    if new_k > 100:
                        continue
                    if new_a < dist[v][new_k]:
                        dist[v][new_k] = new_a
                        heapq.heappush(heap, (new_a, v, new_k))
            return [dist[target][k] for k in range(101)]

        a1 = compute_a(S1, T)
        a2 = compute_a(S2, T)

        candidates = {0, 10**18}
        valid_k1 = [k for k in range(101) if a1[k] < (1 << 60)]
        valid_k2 = [k for k in range(101) if a2[k] < (1 << 60)]

        for i in range(len(valid_k1)):
            for j in range(i + 1, len(valid_k1)):
                k1, k2 = valid_k1[i], valid_k1[j]
                denom = k1 - k2
                if denom == 0:
                    continue
                x = (a1[k2] - a1[k1]) / denom
                if x >= 0:
                    candidates.update({math.floor(x), math.ceil(x)})

        for i in range(len(valid_k2)):
            for j in range(i + 1, len(valid_k2)):
                k1, k2 = valid_k2[i], valid_k2[j]
                denom = k1 - k2
                if denom == 0:
                    continue
                x = (a2[k2] - a2[k1]) / denom
                if x >= 0:
                    candidates.update({math.floor(x), math.ceil(x)})

        for k1 in valid_k1:
            for k2 in valid_k2:
                denom = k1 - k2
                if denom == 0:
                    continue
                x = (a2[k2] - a1[k1]) / denom
                if x >= 0:
                    candidates.update({math.floor(x), math.ceil(x)})

        candidate_x = [x for x in candidates if x >= 0]
        min_diff = 1 << 60

        for x in candidate_x:
            d1 = min((a1[k] + k * x for k in valid_k1), default=1 << 60)
            d2 = min((a2[k] + k * x for k in valid_k2), default=1 << 60)
            if d1 >= (1 << 60) or d2 >= (1 << 60):
                continue
            diff = abs(d1 - d2)
