        C = -a
        discriminant = B * B - 4 * A * C
        max_g = 0
        if discriminant >= 0:
            sqrt_disc = math.isqrt(discriminant)
            if sqrt_disc * sqrt_disc == discriminant:
                max_g = ( -B + sqrt_disc ) // (2 * A)
            else:
                max_g = ( -B + int(math.sqrt(discriminant)) ) // (2 * A)
        start_g = b + 1
        if start_g < 1:
            start_g = 1
        for g in range(start_g, max_g + 1):
            if g <= b:
                continue
            D = g * (g - b)
            if D == 0:
                continue
            numerator = a + c * g
            if numerator <= 0:
                continue
            if numerator % D != 0:
                continue
            K = numerator // D
            if K <= 0:
                continue
            cnt = count_distinct_primes(K)
            ways = 2 ** cnt if K > 1 else 1
            total += ways
