        c, d = map(int, stdin.readline().split())
        T2[c].append(d)
        T2[d].append(c)
        edges_T2.append((c, d))

    parent = [0]*(n+1)
    depth = [0]*(n+1)
    heavy = [-1]*(n+1)
    head = [0]*(n+1)
    pos = [0]*(n+1)
    size = [0]*(n+1)
    current_pos = defaultdict(int)
    segment_trees = {}

    def dfs(u, p):
        size[u] = 1
        max_size = 0
        for v in T1[u]:
            if v != p:
                parent[v] = u
                depth[v] = depth[u] + 1
                dfs(v, u)
                size[u] += size[v]
                if size[v] > max_size:
                    max_size = size[v]
                    heavy[u] = v

    dfs(1, -1)

    def decompose(u, h):
        nonlocal current_pos
        head[u] = h
        if h not in current_pos:
            current_pos[h] = 0
        pos[u] = current_pos[h]
        current_pos[h] += 1
        if heavy[u] != -1:
            decompose(heavy[u], h)
            for v in T1[u]:
                if v != parent[u] and v != heavy[u]:
                    decompose(v, v)

    decompose(1, 1)

    edge_to_node = {}
    for u in range(1, n+1):
        if parent[u] != 0:
            a, b = u, parent[u]
            if a > b:
                a, b = b, a
            edge_to_node[(a, b)] = u

    for h in current_pos:
        st_size = current_pos[h]
        segment_trees[h] = SegmentTree(st_size)

    LOG = 20
    up = [[-1]*(n+1) for _ in range(LOG)]
    up[0] = parent[:]
    for k in range(1, LOG):
        for i in range(1, n+1):
            if up[k-1][i] != -1:
                up[k][i] = up[k-1][up[k-1][i]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != -1 and up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return parent[u]

    def get_path_segments(u, v):
        segments = []
        while head[u] != head[v]:
            if depth[head[u]] > depth[head[v]]:
                u, v = v, u
            segments.append((head[v], v))
            v = parent[head[v]]
        if depth[u] > depth[v]:
            u, v = v, u
        segments.append((u, v))
        return segments

    result = []
    used_T2 = set()
    edge_map = {}

    for idx, (c, d) in enumerate(edges_T2):
        l = lca(c, d)
        segments = get_path_segments(c, l) + get_path_segments(d, l)
        found = False
        for seg in segments:
            h, v = seg
            current = v
            path_head = head[current]
            st = segment_trees[path_head]
            l_pos = pos[h]
            r_pos = pos[current]
            if l_pos > r_pos:
                l_pos, r_pos = r_pos, l_pos
            first_available = st.find_first_available(l_pos, r_pos + 1)
            if first_available != -1:
                st.mark_unavailable(first_available)
                node_u = None
                node = path_head
                prev = node
                while node != h:
                    prev = node
                    node = parent[node]
                node = prev
                current_node = path_head
                for _ in range(first_available):
                    current_node = heavy[current_node]
                a, b = current_node, parent[current_node]
                if a > b:
                    a, b = b, a
                e = (a, b)
                edge_map[e] = (c, d)
                result.append((e, (c, d)))
                found = True
                break
        if found:
            continue

    output = []
    for e, f in result:
        a, b = e
        c, d = f
        output.append(f"{a} {b} {c} {d}")

    print(len(output))
    print('\n'.join(output))

class SegmentTree:
    def __init__(self, size):
        self.n = 1
        while self.n < size:
            self.n <<= 1
        self.size = size
        self.tree = [True] * (2 * self.n)
        for i in range(self.n - 1, 0, -1):
            self.tree[i] = self.tree[2*i] or self.tree[2*i+1]

    def find_first_available(self, l, r):
        res = self._find(1, 0, self.n, l, r)
        return res

    def _find(self, node, node_l, node_r, l, r):
        if node_r <= l or node_l >= r or not self.tree[node]:
            return -1
        if node_l >= l and node_r <= r:
            if node_l == node_r -1:
                return node_l
            mid = (node_l + node_r) // 2
            left = self._find(2*node, node_l, mid, l, r)
            if left != -1:
                return left
            return self._find(2*node+1, mid, node_r, l, r)
        mid = (node_l + node_r) // 2
        left = self._find(2*node, node_l, mid, l, r)
        if left != -1:
            return left
        return self._find(2*node+1, mid, node_r, l, r)

    def mark_unavailable(self, pos):
        pos += self.n
        self.tree[pos] = False
        pos >>= 1
        while pos >= 1:
            new_val = self.tree[2*pos] or self.tree[2*pos+1]
            if self.tree[pos] == new_val:
                break
            self.tree[pos] = new_val
            pos >>= 1

