def fib_mod(n, m):
    if m == 1:
        return 0
    def fast_doubling(n, m):
        if n == 0:
            return (0, 1)
        a, b = fast_doubling(n >> 1, m)
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        if n & 1:
            return (d, (c + d) % m)
        else:
            return (c, d)
    _, res = fast_doubling(n - 1, m)
    return res % m

