import heapq

def main():
    lower = []  # max-heap (stored as negatives)
    upper = []   # min-heap

    while True:
        line = input().strip()
        if not line:
            continue
        n = int(line)
        if n == -2:
            break
        if n == 0:
            total = len(lower) + len(upper)
            if total % 2 == 0:
                print(-1)
            else:
                print(-lower[0])
        elif n > 0:
            x = n
            if not lower or x <= -lower[0]:
                heapq.heappush(lower, -x)
            else:
                heapq.heappush(upper, x)

            # Rebalance the heaps
            if len(lower) > len(upper) + 1:
                val = -heapq.heappop(lower)
                heapq.heappush(upper, val)
            elif len(upper) > len(lower):
                val = heapq.heappop(upper)
                heapq.heappush(lower, -val)

