                    grid[i+1][j] == 'X' and grid[i+1][j+1] == 'X'):
                    king_pos = (i, j)
                    break
            if king_pos:
                break

        empties = []
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '.':
                    empties.append((i, j))
        e1, e2 = empties
        sorted_empties = tuple(sorted([e1, e2]))

        if king_pos == (0, 0):
            print(0)
            continue

        obstacles = set()
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '*':
                    obstacles.add((i, j))

        visited = set()
        queue = deque()
        initial_state = (king_pos[0], king_pos[1], sorted_empties)
        visited.add(initial_state)
        queue.append((king_pos[0], king_pos[1], sorted_empties, 0))
        found = False

        while queue:
            x, y, empties, steps = queue.popleft()

            if x == 0 and y == 0:
                print(steps)
                found = True
                break

            for e in empties:
                ex, ey = e
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx = ex + dx
                    ny = ey + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if (nx, ny) in obstacles:
                            continue
                        if x <= nx <= x + 1 and y <= ny <= y + 1:
                            continue
                        other_e = empties[0] if e == empties[1] else empties[1]
                        if (nx, ny) == other_e:
                            continue
                        new_e = (nx, ny)
                        new_empties = sorted([new_e, other_e])
                        new_empties = tuple(new_empties)
                        new_state = (x, y, new_empties)
                        if new_state not in visited:
                            visited.add(new_state)
                            queue.append((x, y, new_empties, steps + 1))

            directions = [
                ('up', (-1, 0)),
                ('down', (1, 0)),
                ('left', (0, -1)),
                ('right', (0, 1)),
            ]
            for dir_name, (dx, dy) in directions:
                if dir_name == 'up':
                    edge_cells = [(x - 1, y), (x - 1, y + 1)]
                elif dir_name == 'down':
                    edge_cells = [(x + 2, y), (x + 2, y + 1)]
                elif dir_name == 'left':
                    edge_cells = [(x, y - 1), (x + 1, y - 1)]
                elif dir_name == 'right':
                    edge_cells = [(x, y + 2), (x + 1, y + 2)]
                else:
                    continue

                valid_edge = True
                for (ex, ey) in edge_cells:
                    if not (0 <= ex < H and 0 <= ey < W):
                        valid_edge = False
                        break
                if not valid_edge:
                    continue

                sorted_edge = tuple(sorted(edge_cells))
                if sorted_edge != empties:
                    continue

                new_x = x + dx
                new_y = y + dy
                if not (0 <= new_x <= H - 2 and 0 <= new_y <= W - 2):
                    continue

                original_king = {(x, y), (x, y + 1), (x + 1, y), (x + 1, y + 1)}
                new_king = {(new_x, new_y), (new_x, new_y + 1), (new_x + 1, new_y), (new_x + 1, new_y + 1)}
                new_empties_list = list(original_king - new_king)
                if len(new_empties_list) != 2:
                    continue
                new_empties = tuple(sorted(new_empties_list))

                obstacle_found = False
                for (kx, ky) in new_king:
                    if (kx, ky) in obstacles:
                        obstacle_found = True
                        break
                if obstacle_found:
                    continue

                new_state = (new_x, new_y, new_empties)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_x, new_y, new_empties, steps + 1))

        if not found:
            print(-1)

