    for x in a:
        for delta in (-1, 0, 1):
            y = x + delta
            if y < 2:
                continue
            fs = factor(y)
            for p in fs:
                primes.add(p)
    min_total = float('inf')
    for d in primes:
        if d == 1:
            continue
        total = 0
        for num in a:
            if num % d == 0:
                continue
            lower = (num // d) * d
            if lower == 0:
                cost = d - (num % d)
            else:
                rem = num % d
                cost = min(rem, d - rem)
            total += cost
            if total >= min_total:
                break
        if total < min_total:
            min_total = total
    print(min_total)

