            new_max = curr_max
            new_min = curr_min

        key = (k, new_d)
        if key not in next_dp:
            next_dp[key] = {'max_p': new_max, 'min_p': new_min}
        else:
            entry = next_dp[key]
            entry['max_p'] = max(entry['max_p'], new_max)
            entry['min_p'] = min(entry['min_p'], new_min)

        # Option 2: Flip the command
        if k + 1 > n:
            continue
        new_k = k + 1
        flipped_c = 'F' if c == 'T' else 'T'
        if flipped_c == 'F':
            flip_d = d
            flip_max = curr_max + d
            flip_min = curr_min + d
        else:
            flip_d = -d
            flip_max = curr_max
            flip_min = curr_min

        key_flip = (new_k, flip_d)
        if key_flip not in next_dp:
            next_dp[key_flip] = {'max_p': flip_max, 'min_p': flip_min}
        else:
            entry = next_dp[key_flip]
            entry['max_p'] = max(entry['max_p'], flip_max)
            entry['min_p'] = min(entry['min_p'], flip_min)

    current_dp = next_dp

