import sys
from collections import defaultdict

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, T = map(int, sys.stdin.readline().split())
        a = list(map(int, sys.stdin.readline().split()))
        freq = defaultdict(list)
        for idx, num in enumerate(a):
            freq[num].append(idx)
        color = [0] * n
        processed = set()
        sorted_keys = sorted(freq.keys())
        for x in sorted_keys:
            if x in processed:
                continue
            complement = T - x
            if x < complement:
                if complement in freq:
                    # Assign x to 0, complement to 1
                    for idx in freq[x]:
                        color[idx] = 0
                    for idx in freq[complement]:
                        color[idx] = 1
                    processed.add(x)
                    processed.add(complement)
                else:
                    for idx in freq[x]:
                        color[idx] = 0
                    processed.add(x)
            elif x == complement:
                indices = freq[x]
                m = len(indices)
                k = m // 2
                for i in range(m):
                    idx = indices[i]
                    if i < k:
                        color[idx] = 0
                    else:
                        color[idx] = 1
                processed.add(x)
            else:
                # x > complement, and complement not present (since processed in sorted order)
                for idx in freq[x]:
                    color[idx] = 0
                processed.add(x)
        print(' '.join(map(str, color)))

