import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    edges = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        x, y = map(int, sys.stdin.readline().split())
        edges[x].append(y)
        edges[y].append(x)

    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    q = deque([1])
    parent[1] = -1

    while q:
        u = q.popleft()
        for v in edges[u]:
            if parent[v] == 0:
                parent[v] = u
                q.append(v)

    for u in range(1, n + 1):
        for v in edges[u]:
            if parent[v] == u:
                children[u].append(v)

    sum_removed = [0] * (n + 1)
    current_weight = [0] * (n + 1)
    stack = [(1, False)]

    while stack:
        node, visited = stack.pop()
        if not visited:
            stack.append((node, True))
            for child in reversed(children[node]):
                stack.append((child, False))
        else:
            if not children[node]:
                sum_removed[node] = 0
                current_weight[node] = a[node - 1]
            else:
                total_sum = 0
                weights = []
                for child in children[node]:
                    total_sum += sum_removed[child]
                    weights.append(current_weight[child])

                if any(w == 0 for w in weights):
                    target = 0
                else:
                    target = min(weights)

                additional = sum(w - target for w in weights)
                sum_removed[node] = total_sum + additional
                current_weight[node] = target * len(children[node])

    print(sum_removed[1])

