def get_factors(x):
    factors = set()
    if x < 2:
        return factors
    i = 2
    while i * i <= x:
        if x % i == 0:
            factors.add(i)
            while x % i == 0:
                x //= i
        i += 1
    if x >= 2:
        factors.add(x)
    return factors

