import sys

def get_furthest_node(start, adj):
    max_dist = 0
    furthest_node = start
    stack = [(start, -1, 0)]
    while stack:
        node, parent, dist = stack.pop()
        if dist > max_dist:
            max_dist = dist
            furthest_node = node
        for neighbor, weight in adj[node]:
            if neighbor != parent:
                stack.append((neighbor, node, dist + weight))
    return (furthest_node, max_dist)

