import sys
from math import atan2, pi
from collections import deque

def readints():
    return list(map(int, sys.stdin.readline().split()))

def convex_hull(points):
    if not points:
        return []
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def main():
    while True:
        C, W = map(int, sys.stdin.readline().split())
        if C == 0 and W == 0:
            break
        points = []
        for _ in range(C):
            x, y = map(int, sys.stdin.readline().split())
            points.append((x, y))
        walls = []
        for _ in range(W):
            s, t = map(int, sys.stdin.readline().split())
            walls.append((s-1, t-1))
        hull_points = convex_hull(points)
        hull_indices = [points.index(p) for p in hull_points]
        convex_edges = set()
        n_hull = len(hull_indices)
        for i in range(n_hull):
            s = hull_indices[i]
            t = hull_indices[(i+1)%n_hull]
            convex_edges.add((s, t))
            convex_edges.add((t, s))
        all_half_edges = []
        for s, t in walls:
            all_half_edges.extend([(s, t), (t, s)])
        outgoing = [[] for _ in range(C)]
        for s, t in all_half_edges:
            outgoing[s].append(t)
        sorted_outgoing = []
        dest_to_index = [{} for _ in range(C)]
        for s in range(C):
            edges_with_angle = []
            for t in outgoing[s]:
                dx = points[t][0] - points[s][0]
                dy = points[t][1] - points[s][1]
                adjusted_angle = (atan2(dy, dx) + 2 * pi) % (2 * pi)
                edges_with_angle.append((t, adjusted_angle))
            edges_with_angle.sort(key=lambda x: x[1])
            sorted_t = [t for t, _ in edges_with_angle]
            sorted_outgoing.append(sorted_t)
            dest_to_index[s] = {t: idx for idx, t in enumerate(sorted_t)}
        next_edge = {}
        for a, b in all_half_edges:
            idx = dest_to_index[b].get(a, 0)
            next_idx = (idx + 1) % len(sorted_outgoing[b])
            next_t = sorted_outgoing[b][next_idx]
            next_edge[(a, b)] = (b, next_t)
        visited = set()
        faces = []
        for a, b in all_half_edges:
            if (a, b) in visited:
                continue
            face = []
            current = (a, b)
            while current not in visited:
                visited.add(current)
                face.append(current)
                current = next_edge[current]
            faces.append(face)
        outer_face = None
        for face in faces:
            for a, b in face:
                if (a, b) in convex_edges:
                    outer_face = face
                    break
            if outer_face is not None:
                break
        face_to_id = {tuple(face): i for i, face in enumerate(faces)}
        outer_id = face_to_id[tuple(outer_face)]
        adj = [[] for _ in range(len(faces))]
        processed = set()
        for s, t in walls:
            if (s, t) in processed or (t, s) in processed:
                continue
            processed.update([(s, t), (t, s)])
            face1 = next(f for f in faces if (s, t) in f)
            face2 = next(f for f in faces if (t, s) in f)
            id1, id2 = face_to_id[tuple(face1)], face_to_id[tuple(face2)]
            adj[id1].append(id2)
            adj[id2].append(id1)
        dist = [-1] * len(faces)
        q = deque([outer_id])
        dist[outer_id] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        max_dist = max(d for i, d in enumerate(dist) if i != outer_id)
        print(max_dist)

