import sys
from collections import deque

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        N = int(line.strip())
        if N == 0:
            break

        # Read Isaac's schedule
        isaac_line = sys.stdin.readline().split()
        M_isaac = int(isaac_line[0])
        isaac_days = list(map(int, isaac_line[1:]))
        S = set(isaac_days)
        days = list(S)
        day_to_idx = {day: idx for idx, day in enumerate(days)}
        K = len(days)

        # Read friends' schedules and build adjacency list
        adj = [[] for _ in range(N)]
        for i in range(N):
            parts = sys.stdin.readline().split()
            M_friend = int(parts[0])
            friend_days = list(map(int, parts[1:]))
            common_days = set(friend_days) & S
            for day in common_days:
                adj[i].append(day_to_idx[day])

        # Hopcroft-Karp algorithm implementation
        pair_u = [-1] * N
        pair_v = [-1] * K
        dist = [0] * N

        def bfs():
            queue = deque()
            for u in range(N):
                if pair_u[u] == -1:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
            dist_null = float('inf')
            while queue:
                u = queue.popleft()
                if dist[u] < dist_null:
                    for v in adj[u]:
                        if pair_v[v] == -1:
                            dist_null = dist[u] + 1
                        elif dist[pair_v[v]] == float('inf'):
                            dist[pair_v[v]] = dist[u] + 1
                            queue.append(pair_v[v])
            return dist_null != float('inf')

        def dfs(u):
            for v in adj[u]:
                if pair_v[v] == -1 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
            dist[u] = float('inf')
            return False

        result = 0
        while bfs():
            for u in range(N):
                if pair_u[u] == -1:
                    if dfs(u):
                        result += 1
        print(result)

