                if parent[u] != u:
                    orig_parent = parent[u]
                    root, exp = find(orig_parent)
                    parent[u] = root
                    weight[u] += exp
                return parent[u], weight[u]

            rootA, a = find(A)
            rootB, b = find(B)

            if rootA == rootB:
                if a != x + b:
                    contradiction = True
            else:
