    input = sys.stdin.read().split()
    ptr = 0
    while True:
        H = int(input[ptr])
        W = int(input[ptr+1])
        R = int(input[ptr+2])
        C = int(input[ptr+3])
        ptr +=4
        if H == 0:
            break
        horz = []
        for _ in range(H+1):
            row = list(map(int, input[ptr:ptr+W]))
            horz.append(row)
            ptr += W
        vert = []
        for _ in range(H):
            row = list(map(int, input[ptr:ptr+W+1]))
            vert.append(row)
            ptr += W+1

        up_wall = [[0]*(W+2) for _ in range(H+2)]
        down_wall = [[0]*(W+2) for _ in range(H+2)]
        left_wall = [[0]*(W+2) for _ in range(H+2)]
        right_wall = [[0]*(W+2) for _ in range(H+2)]

        for r in range(1, H+1):
            for c in range(1, W+1):
                up_wall[r][c] = horz[r-1][c-1]
                down_wall[r][c] = horz[r][c-1] if r < H else 1
        for r in range(1, H+1):
            for c in range(1, W+1):
                left_wall[r][c] = vert[r-1][c-1]
                right_wall[r][c] = vert[r-1][c] if c < W else 1

        memo = [[[[-1 for _ in range(2)] for __ in range(2)] for ___ in range(W+2)] for ____ in range(H+2)]

        def can_escape(r, c, w):
            if r == 1 and (up_wall[r][c] ^ w) == 0:
                return True
            if r == H and (down_wall[r][c] ^ w) == 0:
                return True
            if c == 1 and (left_wall[r][c] ^ w) == 0:
                return True
            if c == W and (right_wall[r][c] ^ w) == 0:
                return True
            return False

        def dfs(r, c, w, turn):
            if memo[r][c][w][turn] != -1:
                return memo[r][c][w][turn]
            if turn == 0:
                if can_escape(r, c, w):
                    memo[r][c][w][turn] = 1
                    return 1
                any_win = False
                if r > 1 and (up_wall[r][c] ^ w) == 0:
                    if dfs(r-1, c, w, 1) == 1:
                        any_win = True
                if r < H and (down_wall[r][c] ^ w) == 0:
                    if dfs(r+1, c, w, 1) == 1:
                        any_win = True
                if c > 1 and (left_wall[r][c] ^ w) == 0:
                    if dfs(r, c-1, w, 1) == 1:
                        any_win = True
                if c < W and (right_wall[r][c] ^ w) == 0:
                    if dfs(r, c+1, w, 1) == 1:
                        any_win = True
                memo[r][c][w][turn] = 1 if any_win else 0
                return memo[r][c][w][turn]
            else:
                res1 = dfs(r, c, 1 - w, 0)
                res2 = dfs(r, c, w, 0)
                memo[r][c][w][turn] = 1 if res1 and res2 else 0
                return memo[r][c][w][turn]

        result = dfs(R, C, 0, 0)
        print("Yes" if result else "No")

