import sys

class SegmentTree:
    def __init__(self, max_size):
        self.n = 1
        while self.n < max_size:
            self.n <<= 1
        self.tree = [ (float('inf'), -1) ] * (2 * self.n)
        for i in range(max_size):
            self.tree[self.n + i] = (float('inf'), -1)
        for i in range(self.n -1, 0, -1):
            left = self.tree[2*i]
            right = self.tree[2*i+1]
            if left[0] < right[0]:
                self.tree[i] = (left[0], left[1])
            elif right[0] < left[0]:
                self.tree[i] = (right[0], right[1])
            else:
                self.tree[i] = (left[0], max(left[1], right[1]))

    def update_point(self, pos, value):
        pos += self.n
        self.tree[pos] = (value, pos - self.n)
        pos >>= 1
        while pos >= 1:
            left = self.tree[2*pos]
            right = self.tree[2*pos+1]
            if left[0] < right[0]:
                self.tree[pos] = (left[0], left[1])
            elif right[0] < left[0]:
                self.tree[pos] = (right[0], right[1])
            else:
                self.tree[pos] = (left[0], max(left[1], right[1]))
            pos >>= 1

    def query_range(self, R):
        res_val = float('inf')
        res_idx = -1
        l = self.n
        r = self.n + R
        while l <= r:
            if l % 2 == 1:
                val, idx = self.tree[l]
                if val < res_val:
                    res_val = val
                    res_idx = idx
                elif val == res_val:
                    res_idx = max(res_idx, idx)
                l += 1
            if r % 2 == 0:
                val, idx = self.tree[r]
                if val < res_val:
                    res_val = val
                    res_idx = idx
                elif val == res_val:
                    res_idx = max(res_idx, idx)
                r -= 1
            l >>= 1
            r >>= 1
        return (res_val, res_idx)

