import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(n)]
    empty_count = sum(row.count('.') for row in grid)
    if empty_count % 2 != 0:
        print("Not unique")
        return

    res = [row.copy() for row in grid]
    covered = [[False]*m for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    q = deque()

    for i in range(n):
        for j in range(m):
            if res[i][j] == '.' and not covered[i][j]:
                possible = 0
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m and res[ni][nj] == '.' and not covered[ni][nj]:
                        possible += 1
                if possible == 1:
                    q.append((i, j))

    while q:
        i, j = q.popleft()
        if covered[i][j]:
            continue
        possible_dirs = []
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < n and 0 <= nj < m and res[ni][nj] == '.' and not covered[ni][nj]:
                possible_dirs.append((dx, dy))
        if len(possible_dirs) != 1:
            print("Not unique")
            return
        dx, dy = possible_dirs[0]
        ni, nj = i + dx, j + dy
        if not (0 <= ni < n and 0 <= nj < m) or res[ni][nj] != '.' or covered[ni][nj]:
            print("Not unique")
            return

        if dx == 0:
            if dy == 1:
                res[i][j] = '<'
                res[ni][nj] = '>'
            else:
                res[i][j] = '>'
                res[ni][nj] = '<'
        else:
            if dx == 1:
                res[i][j] = '^'
                res[ni][nj] = 'v'
            else:
                res[i][j] = 'v'
                res[ni][nj] = '^'

