import bisect

class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [[] for _ in range(self.n + 1)]  # 1-based indexing

    def update(self, idx, value):
        while idx <= self.n:
            bisect.insort(self.tree[idx], value)
            idx += idx & -idx

    def query(self, s, K):
        res = 0
        while s > 0:
            res += self._count_ge(self.tree[s], K)
            s -= s & -s
        return res

    def _count_ge(self, arr, K):
        left = bisect.bisect_left(arr, K)
        return len(arr) - left

