import sys
from collections import deque

def main():
    N, M = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(N+1)]  # Forward edges
    reverse_edges = [[] for _ in range(N+1)]  # Reverse edges
    in_degree = [0] * (N + 1)

    for _ in range(N-1 + M):
        A, B = map(int, sys.stdin.readline().split())
        edges[A].append(B)
        reverse_edges[B].append(A)
        in_degree[B] += 1

    # Find root (node with in_degree 0)
    root = None
    for i in range(1, N+1):
        if in_degree[i] == 0:
            root = i
            break

    # Kahn's algorithm for topological sort
    temp_in_degree = in_degree.copy()
    order = []
    q = deque([root])
    while q:
        u = q.popleft()
        order.append(u)
        for v in edges[u]:
            temp_in_degree[v] -= 1
            if temp_in_degree[v] == 0:
                q.append(v)

    # Create position dictionary
    pos = {u: idx for idx, u in enumerate(order)}

    # Determine parent for each node
    parent = [0] * (N + 1)
    for v in range(1, N+1):
        if v == root:
            parent[v] = 0
        else:
            max_pos = -1
            selected_u = -1
            for u in reverse_edges[v]:
                current_pos = pos[u]
                if current_pos > max_pos:
                    max_pos = current_pos
                    selected_u = u
            parent[v] = selected_u

    # Output
    for i in range(1, N+1):
        print(parent[i])

