import sys
import itertools

def parse_formula(s):
    if not s:
        return None, s
    if s[0] == 'T':
        return ('T',), s[1:]
    elif s[0] == 'F':
        return ('F',), s[1:]
    elif s[0] in 'abcdefghijk':
        return ('var', s[0]), s[1:]
    elif s[0] == '-':
        sub, rest = parse_formula(s[1:])
        return ('-', sub), rest
    elif s[0] == '(':
        s = s[1:]
        left, rest = parse_formula(s)
        if rest.startswith('->'):
            op, rest = '->', rest[2:]
        elif rest[0] in '*+':
            op, rest = rest[0], rest[1:]
        else:
            raise ValueError("Invalid operator")
        right, rest = parse_formula(rest)
        if not rest.startswith(')'):
            raise ValueError("Missing closing parenthesis")
        return (op, left, right), rest[1:]
    else:
        raise ValueError("Unexpected character")

def evaluate(parsed, vars):
    if parsed[0] == 'T':
        return True
    elif parsed[0] == 'F':
        return False
    elif parsed[0] == 'var':
        return vars[parsed[1]]
    elif parsed[0] == '-':
        return not evaluate(parsed[1], vars)
    else:
        op, left, right = parsed
        l = evaluate(left, vars)
        r = evaluate(right, vars)
        if op == '*': return l and r
        if op == '+': return l or r
        if op == '->': return not l or r

def collect_vars(parsed):
    if parsed[0] in ('T', 'F'):
        return set()
    elif parsed[0] == 'var':
        return {parsed[1]}
    elif parsed[0] == '-':
        return collect_vars(parsed[1])
    else:
        return collect_vars(parsed[1]) | collect_vars(parsed[2])

def is_identity(left, right):
    vars = sorted(collect_vars(left) | collect_vars(right))
    for bits in itertools.product([True, False], repeat=len(vars)):
        assignment = dict(zip(vars, bits))
        if evaluate(left, assignment) != evaluate(right, assignment):
            return False
    return True

