    for i in range(22):
        for m in range(size):
            if not (m & (1 << i)):
                or_mask[m] |= or_mask[m | (1 << i)]

    # Compute and_mask using SOS DP
    and_mask = [(1 << 22) - 1] * size
    for s in masks:
        and_mask[s] &= s
    for i in range(22):
        for m in range(size):
            if not (m & (1 << i)):
