def compute_hashes(s, C, base, mod):
    n = len(s)
    if C > n:
        return []
    power = pow(base, C-1, mod)
    current_hash = 0
    for i in range(C):
        current_hash = (current_hash * base + ord(s[i])) % mod
    hashes = [current_hash]
    for i in range(C, n):
        current_hash = (current_hash - ord(s[i-C]) * power) % mod
        current_hash = (current_hash * base + ord(s[i])) % mod
        hashes.append(current_hash)
    return hashes

def compute_lps(pattern):
    R = len(pattern)
    lps = [0] * R
    length = 0
    for i in range(1, R):
        while length > 0 and pattern[i] != pattern[length]:
            length = lps[length-1]
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0
    return lps

def kmp_search(text, pattern, lps):
    R = len(pattern)
    j = 0
    matches = []
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = lps[j-1]
        if text[i] == pattern[j]:
            j += 1
        if j == R:
            matches.append(i - R + 1)
            j = lps[j-1]
    return matches

def main():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    H, W = map(int, input[idx].split())
    idx += 1
    region_grid = [input[idx + i].strip() for i in range(H)]
