    R, C = map(int, input[idx].split())
    idx += 1
    pattern_grid = [input[idx + i].strip() for i in range(R)]
    idx += R

    if R > H or C > W:
        return

    base = 911382629
    mod = 10**18 + 3

    region_row_hashes = []
    for row in region_grid:
        hashes = compute_hashes(row, C, base, mod)
        region_row_hashes.append(hashes)

    pattern_hashes = []
    for row in pattern_grid:
        hashes = compute_hashes(row, C, base, mod)
        if not hashes:
            return
        pattern_hashes.append(hashes[0])

    lps = compute_lps(pattern_hashes)

    results = []
    for j in range(W - C + 1):
        T_j = []
        for i in range(H):
