            if c != '?' and c != req:
                valid_i = False
                break
        if valid_i:
            valid.append(i)

    # Select non-overlapping intervals
    selected = []
    last = -4
    for i in sorted(valid):
        if i >= last + 4:
            selected.append(i)
            last = i

    # Replace selected intervals with CHEF
    for i in selected:
        for j in range(4):
            pos = i + j
            if s_list[pos] == '?':
