import sys
from collections import defaultdict, deque

def main():
    roads = []
    while True:
        line = sys.stdin.readline().strip()
        if line == 'END':
            break
        roads.append((line[0], line[1]))

    adj = defaultdict(list)
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    # Check if A and B are connected in the original graph
    def is_connected(A, B):
        if A not in adj or B not in adj:
            return False
        visited = set()
        queue = deque([A])
        visited.add(A)
        while queue:
            u = queue.popleft()
            if u == B:
                return True
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return False

    if not is_connected('A', 'B'):
        print("Too Bad, We Lose")
        return

    # Find all bridges using Tarjan's algorithm
    bridges = []
    disc = {}
    low = {}
    parent = {}
    time = 0
    visited = set()

    def tarjan(u):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        visited.add(u)
        for v in adj[u]:
            if v == parent.get(u, None):
                continue
            if v not in visited:
                parent[v] = u
                tarjan(v)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
            else:
                low[u] = min(low[u], disc[v])

    for node in adj:
        if node not in visited:
            tarjan(node)

    # Collect roads that are bridges and when removed disconnect A and B
    result = []
    for road in roads:
        u_road, v_road = road
        is_bridge = any(
            (u_b == u_road and v_b == v_road) or (u_b == v_road and v_b == u_road)
            for u_b, v_b in bridges
        )
        if is_bridge:
            # Check connectivity without this road
            visited = set()
            queue = deque(['A'])
            visited.add('A')
            found = False
            while queue:
                u = queue.popleft()
                if u == 'B':
                    found = True
                    break
                for v in adj[u]:
                    if (u == u_road and v == v_road) or (u == v_road and v == u_road):
                        continue
                    if v not in visited:
                        visited.add(v)
                        queue.append(v)
            if not found:
                result.append(road)

    if not result:
        print("Too Bad, We Lose")
    else:
        for r in result:
            print(f"{r[0]}{r[1]}")

