        energy -= 1.0 / (1**2)
        if energy < 0:
            print("? C")  # This query will fail, but just to avoid Idleness
            sys.stdout.flush()
            return
        print("? C")
        sys.stdout.flush()
        parts = sys.stdin.readline().split()
        k = int(parts[0])
        if k == -1:
            return
        c_pos = []
        if k > 0:
            c_pos = list(map(int, parts[1:1+k]))
            for pos in c_pos:
                if 1 <= pos <= n:
                    s[pos-1] = 'C'

        # Query for 'CH'
        if energy >= 1.0/(2**2):
            energy -= 1.0/(2**2)
            print("? CH")
            sys.stdout.flush()
            parts = sys.stdin.readline().split()
            k = int(parts[0])
            if k == -1:
                return
            if k > 0:
                ch_pos = list(map(int, parts[1:1+k]))
                for pos in ch_pos:
                    if pos <= n-1 and s[pos-1] == 'C':
                        s[pos] = 'H'  # Next character after C is H

        # Fill remaining '?' with H or O based on previous queries
        # Check if there are any O's by querying O if energy allows
        # If energy allows, query 'O' to check presence
        o_present = False
        if energy >= 1.0/(1**2):
            energy -= 1.0
            print("? O")
            sys.stdout.flush()
            parts = sys.stdin.readline().split()
            k = int(parts[0])
            if k == -1:
                return
            if k > 0:
                o_present = True
                o_pos = list(map(int, parts[1:1+k]))
                for pos in o_pos:
                    if 1 <= pos <= n:
                        if s[pos-1] == '?':
                            s[pos-1] = 'O'

        # Fill remaining '?' with H or other possible characters
        # Check if O is present
        if o_present:
            # Some O's are present, need to handle
            # This part is complex; as a fallback, fill with H and O where possible
            # This is a heuristic and may not work for all cases
            for i in range(n):
                if s[i] == '?':
                    # Check if there's a C or H nearby that might suggest O?
                    # For simplicity, assume it's H if O is present but not known
                    s[i] = 'H'
        else:
            # No O's, fill with H and C
            for i in range(n):
                if s[i] == '?':
                    s[i] = 'H'

        # Finally, guess the string
        guess = ''.join(s)
        print(f"! {guess}")
