    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)
    s, t = map(int, sys.stdin.readline().split())

    # Check if s and t are connected
    def bfs_connected(start, target):
        visited = [False] * (n + 1)
        q = deque()
        q.append(start)
        visited[start] = True
        while q:
            u = q.popleft()
            if u == target:
                return True
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return False

    if not bfs_connected(s, t):
        print(-1)
        return

    # Binary search for the minimal q
    low = 0
    high = 0
    # Find the maximum possible distance (s to t)
    dist = [-1] * (n + 1)
    q = deque()
    q.append(s)
    dist[s] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
                if v == t:
                    high = dist[v]
                    break
        if dist[t] != -1:
            break

    if dist[t] == -1:
        print(-1)
        return
    high = dist[t]

    # Binary search between low and high
    answer = high
    while low <= high:
        mid = (low + high) // 2
        max_steps = [-1] * (n + 1)
        dq = deque()
        if s in vol_set:
            max_steps[s] = mid
            dq.append(s)
        found = False
        while dq:
            u = dq.popleft()
            current = max_steps[u]
            if current < 0:
                continue
            if u == t:
                found = True
                break
            for v in adj[u]:
                if u in vol_set:
                    new_step = mid
                else:
                    new_step = current - 1
                if new_step < 0:
                    continue
                if new_step > max_steps[v]:
                    max_steps[v] = new_step
                    # Prefer volunteers to be processed first
                    if v in vol_set:
                        dq.appendleft(v)
                    else:
                        dq.append(v)
        if max_steps[t] >=0:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1
    print(answer)

