    is_articulation = [False] * (n + 1)
    block_nodes = []
    block_id = 0

    def dfs(u):
        disc[u] = low[u] = time_counter[0]
        time_counter[0] += 1
        children = 0
        for v in edges[u]:
            if disc[v] == 0:
                parent[v] = u
                children += 1
                stack.append((u, v))
                dfs(v)
                low[u] = min(low[u], low[v])
                if (parent[u] == 0 and children > 1) or (parent[u] != 0 and low[v] >= disc[u]):
                    is_articulation[u] = True
                    block_nodes.append([])
                    while True:
                        edge = stack.pop()
                        block_nodes[-1].append(edge[0])
                        block_nodes[-1].append(edge[1])
                        if edge == (u, v):
                            break
            elif v != parent[u] and disc[v] < disc[u]:
                low[u] = min(low[u], disc[v])
                stack.append((u, v))
        if parent[u] == 0 and children == 0:
            block_nodes.append([u])

