        if disc[u] == 0:
            dfs(u)
            if stack:
                block_nodes.append([])
                while stack:
                    edge = stack.pop()
                    block_nodes[-1].append(edge[0])
                    block_nodes[-1].append(edge[1])

    unique_blocks = []
    for bn in block_nodes:
        unique = list(set(bn))
        unique.sort()
        unique_blocks.append(unique)

    component = [[] for _ in range(n+1)]
    for i, block in enumerate(unique_blocks):
        for node in block:
            component[node].append(i)

    articulations = set()
    for u in range(1, n+1):
        if is_articulation[u]:
            articulations.add(u)

    block_to_nodes = unique_blocks
    node_to_blocks = component

