        art_map[art] = new_id
        new_id += 1

    for i, block in enumerate(block_to_nodes):
        b_id = i + 1
        arts_in_block = []
        for node in block:
            if node in articulations:
                arts_in_block.append(node)
        for art in arts_in_block:
            a_id = art_map[art]
            bc_tree[b_id].append(a_id)
            bc_tree[a_id].append(b_id)

    dp = [{} for _ in range(len(bc_tree))]

    def post_order(node, parent_node):
        if node > len(block_to_nodes):
            art_node = list(art_map.keys())[node - len(block_to_nodes) - 1]
            dp[node][0] = (0, 0)
            dp[node][1] = (1, 1 + len(edges[art_node]))
            return
        current_block = block_to_nodes[node - 1]
        art_points = [n for n in current_block if n in articulations]
        non_art = [n for n in current_block if n not in articulations]
        dp_art = {}
