                art_dp.append(child)
            dp_art[art] = art_dp
        block_dp = {0: (0, 0)}
        for n_node in non_art:
            new_block_dp = {}
            for k in block_dp:
                count, cover = block_dp[k]
                new_block_dp[k] = (count, cover)
                new_count = k + 1
                new_cover = cover + 1 + len(edges[n_node])
                if new_count not in new_block_dp or new_cover < new_block_dp[new_count][1]:
                    new_block_dp[new_count] = (new_count, new_cover)
            block_dp = new_block_dp
        for art in art_points:
            art_dp = dp_art[art]
            for child in art_dp:
                pass
        dp[node] = block_dp

    post_order(1, -1)
    min_coverage = [0]*(n+1)
    for a in range(n+1):
