    for _ in range(q):
        l = int(input[ptr]) - 1
        r = int(input[ptr+1]) - 1
        queries.append((l, r))
        ptr += 2

    max_a = max(a) if a else 0
    max_a = max(max_a, 2)
    spf = list(range(max_a + 1))
    for i in range(2, int(max_a**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_a + 1, i):
                if spf[j] == j:
                    spf[j] = i

    factors_list = []
    for x in a:
        if x == 1:
            factors = []
        else:
            factors = {}
            temp = x
            while temp > 1:
                p = spf[temp]
                while temp % p == 0:
                    factors[p] = factors.get(p, 0) + 1
                    temp //= p
            factors = sorted(factors.items())
        factors_list.append(factors)

    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [[] for _ in range(2 * self.size)]
            for i in range(self.n):
                self.tree[self.size + i] = data[i]
            for i in range(self.size - 1, 0, -1):
                self.tree[i] = self.merge(self.tree[2*i], self.tree[2*i +1])

        def merge(self, a, b):
            res = []
            i = j = 0
            while i < len(a) and j < len(b):
                pa, ca = a[i]
                pb, cb = b[j]
                if pa < pb:
                    res.append((pa, ca))
                    i += 1
                elif pa > pb:
                    res.append((pb, cb))
                    j += 1
                else:
                    res.append((pa, ca + cb))
                    i += 1
                    j += 1
            res.extend(a[i:])
            res.extend(b[j:])
            return res

        def query(self, l, r):
            res = []
            l += self.size
            r += self.size + 1
            while l < r:
                if l % 2:
                    res = self.merge(res, self.tree[l])
                    l += 1
                if r % 2:
                    r -= 1
                    res = self.merge(res, self.tree[r])
                l >>= 1
                r >>= 1
            return res

    st = SegmentTree(factors_list)
    for l, r in queries:
        merged = st.query(l, r)
        res = 1
        for p, cnt in merged:
            term = pow(p, cnt -1, MOD) * (p -1) % MOD
            res = res * term % MOD
        print(res)

