    for _ in range(n):
        a, b, c = map(int, sys.stdin.readline().split())
        segments.append((a, b, c))

    # Initialize state for the first segment
    current_ci = segments[0][2]
    current_state = [0] * (current_ci + 1)
    current_state[0] = 1  # starting at (0,0)

    for i in range(n):
        a, b, c = segments[i]
        ci = c
        if i == n-1:
            m = k - a
        else:
            m = b - a

        # Build transition matrix for current ci
        size = ci + 1
        trans = [[0]*size for _ in range(size)]
        for y in range(size):
            for dy in (-1, 0, 1):
                y_next = y + dy
                if 0 <= y_next < size:
                    trans[y][y_next] += 1

        # Matrix exponentiation
        def matrix_mult(a, b):
            res = [[0]*len(b[0]) for _ in range(len(a))]
            for i in range(len(a)):
                for k_row in range(len(b)):
                    if a[i][k_row]:
                        for j in range(len(b[0])):
                            res[i][j] = (res[i][j] + a[i][k_row] * b[k_row][j]) % MOD
            return res

        def matrix_pow(mat, power):
            result = [[0]*len(mat) for _ in range(len(mat))]
            for i in range(len(mat)):
                result[i][i] = 1
            while power > 0:
                if power % 2 == 1:
                    result = matrix_mult(result, mat)
                mat = matrix_mult(mat, mat)
                power //= 2
            return result

        trans_pow = matrix_pow(trans, m)

        # Multiply current_state with trans_pow
        new_state = [0] * size
        for y in range(size):
            if current_state[y]:
                for y_prime in range(size):
                    new_state[y_prime] = (new_state[y_prime] + current_state[y] * trans_pow[y][y_prime]) % MOD

        current_state = new_state

        # Prepare for next segment if not last
        if i != n-1:
            next_ci = segments[i+1][2]
            filtered = [0] * (next_ci + 1)
            for y_prev in range(len(current_state)):
                if y_prev <= next_ci:
                    filtered[y_prev] = (filtered[y_prev] + current_state[y_prev]) % MOD
