import sys
import math
from functools import lru_cache

sys.setrecursionlimit(1000000)

@lru_cache(maxsize=None)
def min_length(n):
    if n == 0:
        return 1  # "0"
    s = str(n)
    minimal = len(s)
    max_b = 36
    for b in range(2, max_b + 1):
        a = round(n ** (1 / b))
        for delta in (-1, 0, 1):
            candidate = a + delta
            if candidate <= 0:
                continue
            power = 1
            for _ in range(b):
                power *= candidate
                if power > n:
                    break
            if power == n:
                current = min_length(candidate) + 1 + min_length(b)
                if current < minimal:
                    minimal = current
    # Check multiplication
    sqrt_n = int(math.isqrt(n))
    for a in range(2, sqrt_n + 1):
        if n % a == 0:
            b = n // a
            current = min_length(a) + min_length(b) + 1
            if current < minimal:
                minimal = current
    # Check division
    max_b_div = 1000
    max_a = (1 << 36) - 1
    for b in range(1, max_b_div + 1):
        a = n * b
        if a > max_a:
            break
        current = min_length(a) + 1 + min_length(b)
        if current < minimal:
            minimal = current
    # Check addition
    max_a_add = 1000
    for a in range(1, min(max_a_add, n) + 1):
        b = n - a
        if b < 0:
            continue
        current = min_length(a) + min_length(b) + 1
        if current < minimal:
            minimal = current
    # Check subtraction
    max_b_sub = 1000
    for b in range(1, max_b_sub + 1):
        a = n + b
        if a > max_a:
            continue
        current = min_length(a) + min_length(b) + 1
        if current < minimal:
            minimal = current
    return minimal

