def sieve(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])
    return [i for i, is_p in enumerate(sieve) if is_p]

def count_divisible(N, L, R):
    primes = sieve(N)
    k = len(primes)
    total = 0
    for mask in range(1, 1 << k):
        bits = bin(mask).count('1')
        product = 1
        for i in range(k):
            if mask & (1 << i):
                product *= primes[i]
                if product > R:
                    break
        if product > R:
            continue
        cnt = (R // product) - ((L - 1) // product)
        if cnt <= 0:
            continue
        if bits % 2 == 1:
            total += cnt
        else:
            total -= cnt
    return total

