class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [0] * (2 * self.size)
        # Fill leaves
        for i in range(self.n):
            self.tree[self.size + i] = 1 << (ord(data[i]) - ord('a'))
        # Build the tree
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.tree[2*i] | self.tree[2*i +1]

    def update(self, pos, c):
        pos += self.size
        self.tree[pos] = 1 << (ord(c) - ord('a'))
        pos >>= 1
        while pos >= 1:
            new_val = self.tree[2*pos] | self.tree[2*pos +1]
            if self.tree[pos] == new_val:
                break
            self.tree[pos] = new_val
            pos >>= 1

    def query(self, l, r):
        res = 0
        l += self.size
        r += self.size
        while l < r:
            if l % 2 == 1:
                res |= self.tree[l]
                l += 1
            if r % 2 == 1:
                r -= 1
                res |= self.tree[r]
            l >>= 1
            r >>= 1
        return bin(res).count('1')

