            adj[v].append(u)

        parent = [0] * (n + 1)
        parent[1] = -1
        size = [1] * (n + 1)
        stack = [(1, False)]

        while stack:
            node, visited = stack.pop()
            if not visited:
                stack.append((node, True))
                for neighbor in adj[node]:
                    if parent[node] != neighbor:
                        if parent[neighbor] == 0:
                            parent[neighbor] = node
                        stack.append((neighbor, False))
            else:
                for neighbor in adj[node]:
                    if parent[neighbor] == node:
                        size[node] += size[neighbor]

        cnt = []
        for u, v in edges:
            if parent[v] == u:
                s = size[v]
            elif parent[u] == v:
                s = size[u]
            else:
                if parent[u] == -1:
                    s = size[v]
                else:
                    s = size[u]
            cnt.append(s * (n - s))

        cnt.sort(reverse=True)
        e = n - 1

        m = int(stdin.readline())
        primes = list(map(int, stdin.readline().split()))
        primes.sort(reverse=True)

        if m > e - 1:
            first_part = primes[:m - (e - 1)]
            product = 1
            for p in first_part:
                product = (product * p) % MOD
            remaining_primes = primes[m - (e - 1):]
            labels = [product] + remaining_primes
        else:
            labels = primes.copy()
            while len(labels) < e:
                labels.append(1)

        total = 0
        for c, l in zip(cnt, labels):
            total = (total + c * l) % MOD
        print(total % MOD)

