def square_free(x):
    if x == 0:
        return 0
    res = 1
    while x != 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            cnt += 1
            x = x // p
        if cnt % 2 == 1:
            res *= p
    return res

