    visited = set()
    q = deque()
    q.append(S[0])
    visited.add(S[0])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                q.append(v)
    for u in S:
        if u not in visited:
            print(-1)
            return

    # Build a path that connects all S vertices
    # Here, we connect them sequentially
    path = []
    def bfs(s, t):
        parent = {}
        q = deque([s])
        parent[s] = -1
        while q:
            u = q.popleft()
            if u == t:
                break
            for v in adj[u]:
                if v not in parent:
                    parent[v] = u
                    q.append(v)
        # Reconstruct path
        curr = t
        p = []
        while curr != s:
            p.append(curr)
            curr = parent[curr]
        p.append(s)
        return p[::-1]

    # Connect all S vertices in a chain
    current = S[0]
    path.append(current)
    for node in S[1:]:
        p = bfs(current, node)
        path.extend(p[1:])  # append the rest
        current = node

    # Count occurrences
    count = {}
    for u in path:
        count[u] = count.get(u, 0) + 1

    # For each vertex not in S, if count is odd and x is 0, add a cycle
    for u in range(1, n+1):
        if x[u-1] == 0 and count.get(u, 0) % 2 == 1:
            # Find a neighbor
            if adj[u]:
                v = adj[u][0]
                path.extend([v, u])
                count[u] += 2

    # Check if the path is valid (consecutive are connected and distinct)
    # Also, check if it's within 4n length
    if len(path) > 4 * n:
        print(-1)
        return

    # Verify parity
    valid = True
    count_final = {}
    for u in path:
        count_final[u] = count_final.get(u, 0) + 1
    for u in range(1, n+1):
        if (count_final.get(u, 0) % 2) != x[u-1]:
            valid = False
            break
    if not valid:
        print(-1)
        return

    print(len(path))
    print(' '.join(map(str, path)))

