import sys
from sys import stdin

def solve_2sat(n, clauses):
    num_nodes = 2 * n
    adj = [[] for _ in range(num_nodes)]
    reverse_adj = [[] for _ in range(num_nodes)]

    for a, b in clauses:
        def to_idx(lit):
            if lit > 0:
                return 2 * (lit - 1)
            else:
                return 2 * (-lit - 1) + 1

        idx_na = to_idx(-a)
        idx_b = to_idx(b)
        adj[idx_na].append(idx_b)
        reverse_adj[idx_b].append(idx_na)

        idx_nb = to_idx(-b)
        idx_a = to_idx(a)
        adj[idx_nb].append(idx_a)
        reverse_adj[idx_a].append(idx_nb)

    visited = [False] * num_nodes
    order = []

    def dfs(u):
        stack = [(u, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                order.append(node)
                continue
            if visited[node]:
                continue
            visited[node] = True
            stack.append((node, True))
            for v in adj[node]:
                if not visited[v]:
                    stack.append((v, False))

    for i in range(num_nodes):
        if not visited[i]:
            dfs(i)

    visited = [False] * num_nodes
    component = [0] * num_nodes
    current = 0

    def reverse_dfs(u):
        nonlocal current
        stack = [u]
        visited[u] = True
        component[u] = current
        while stack:
            node = stack.pop()
            for v in reverse_adj[node]:
                if not visited[v]:
                    visited[v] = True
                    component[v] = current
                    stack.append(v)

    for node in reversed(order):
        if not visited[node]:
            reverse_dfs(node)
            current += 1

    assignment = [0] * n
    for i in range(n):
        pos = 2 * i
        neg = 2 * i + 1
        if component[pos] == component[neg]:
            return (False, None)
        assignment[i] = 1 if component[pos] > component[neg] else 0
    return (True, assignment)

def check_assignment(assignment, clauses):
    for a, b in clauses:
        val_a = assignment[a-1] if a > 0 else 1 - assignment[-a-1]
        val_b = assignment[b-1] if b > 0 else 1 - assignment[-b-1]
        if not (val_a or val_b):
            return False
    return True

