intervals = [(1, w, h + 1, 1)]

for u, l, r, s in barriers:
    split_cols = []
    if l > 1:
        split_cols.append(l - 1)
    if r < w:
        split_cols.append(r + 1)
    if not split_cols:
        continue

    new_intervals = []
    for (start, end, sh, cnt) in intervals:
        if end < l or start > r:
            new_intervals.append((start, end, sh, cnt))
            continue

        # Left part
        if start < l:
            new_intervals.append((start, l - 1, sh, cnt))

        # Middle part
        mid_s = max(start, l)
        mid_e = min(end, r)
        if mid_s <= mid_e:
            if sh > u + s:
                new_intervals.append((mid_s, mid_e, sh, cnt))
            else:
                num_cols = mid_e - mid_s + 1
                total = num_cols * cnt
                num_split = len(split_cols)
                per_split = (total * 2) // num_split
                for col in split_cols:
                    new_intervals.append((col, col, u, per_split))

        # Right part
        if end > r:
            new_intervals.append((r + 1, end, sh, cnt))

    # Merge intervals
    if not new_intervals:
        intervals = []
        continue
    new_intervals.sort()
    merged = [new_intervals[0]]
    for current in new_intervals[1:]:
        last = merged[-1]
        if (current[0] == last[1] + 1 and current[2] == last[2] and current[3] == last[3]):
            merged[-1] = (last[0], current[1], last[2], last[3])
        else:
            merged.append(current)
    intervals = merged

