import math

def compute_f(n, K):
    if n == 0:
        return 0
    if K >= n:
        return (1 << n) - 1
    else:
        total = 0
        for k in range(1, K+1):
            total += math.comb(n, k)
        return total

def main():
    N, K, S, T = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    if (S & T) != S:
        print(0)
        return

    B = [a for a in A if (a & S) == S and (a | T) == T]
    M = T ^ S

    if M == 0:
        cnt_S = B.count(S)
        ans = 0
        for k in range(1, min(K, cnt_S) + 1):
            ans += math.comb(cnt_S, k)
        print(ans)
        return
    else:
        ans = 0
        for s in range(M + 1):
            if (s & M) != s:
                continue
            bits_count = bin(s).count('1')
            groups = {}
            for a in B:
                mask = a & s
                if mask in groups:
                    groups[mask] += 1
                else:
                    groups[mask] = 1
            f_s = 0
            for count in groups.values():
                f_s += compute_f(count, K)
            ans += ((-1) ** bits_count) * f_s
        print(ans)
        return

