def process_polyline(points):
    directions = []
    lengths = []
    for i in range(len(points)-1):
        x1, y1 = points[i]
        x2, y2 = points[i+1]
        dx = x2 - x1
        dy = y2 - y1
        if dx != 0:
            length = abs(dx)
            dir_x = dx // length
            directions.append((dir_x, 0))
        else:
            length = abs(dy)
            dir_y = dy // length
            directions.append((0, dir_y))
        lengths.append(length)
    return directions, lengths

def rotate(direction, rot):
    dx, dy = direction
    for _ in range(rot):
        dx, dy = dy, -dx
    return (dx, dy)

def is_match(template_dirs, template_lengths, candidate_dirs, candidate_lengths):
    # Check original and reversed candidate directions and lengths
    for dirs, lengths in [
        (candidate_dirs, candidate_lengths),
        ( [(-d[0], -d[1]) for d in reversed(candidate_dirs)], list(reversed(candidate_lengths)) )
    ]:
        for rot in range(4):
            rotated_dirs = [rotate(d, rot) for d in dirs]
            if rotated_dirs == template_dirs and lengths == template_lengths:
                return True
    return False

