import sys

def main():
    input = sys.stdin.readline
    N = int(input())
    C = [0] * (N + 1)

    for i in range(1, N + 1):
        print(f"? 1 {i}")
        sys.stdout.flush()
        C[i] = int(input())

    a = [0] * (N + 1)
    for i in range(1, N + 1):
        a[i] = C[i] - C[i - 1]

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(N)
    for i in range(1, N + 1):
        ft.update(i, 1)

    perm = [0] * (N + 1)
    for i in range(N, 0, -1):
        k = a[i] + 1
        total = ft.query(N)
        k_small = total - k + 1

        low, high, res = 1, N, 0
        while low <= high:
            mid = (low + high) // 2
            sum_mid = ft.query(mid)
            if sum_mid >= k_small:
                res = mid
                high = mid - 1
            else:
                low = mid + 1

        perm[i] = res
        ft.update(res, -1)

    print('! ' + ' '.join(map(str, perm[1:N+1])))
    sys.stdout.flush()

