def get_unique_substrings(s, L):
    n = len(s)
    if L > n:
        return set()
    count = defaultdict(int)
    for i in range(n - L + 1):
        substr = s[i:i+L]
        count[substr] += 1
    unique = set()
    for substr, cnt in count.items():
        if cnt == 1:
            unique.add(substr)
    return unique

