import sys

def compute_max_sum(z):
    z_cubed = z ** 3
    max_sum = 0
    for x in range(1, z):
        x_cubed = x ** 3
        rem = z_cubed - x_cubed
        if rem < 1:
            continue  # Not possible as x < z, but just in case
        # Binary search for max y
        low = 1
        high = 1
        while high ** 3 <= rem:
            high *= 2
        best_y = 0
        while low <= high:
            mid = (low + high) // 2
            mid_cubed = mid ** 3
            if mid_cubed <= rem:
                best_y = mid
                low = mid + 1
            else:
                high = mid - 1
        current_sum = x_cubed + best_y ** 3
        if current_sum > max_sum:
            max_sum = current_sum
    return z_cubed - max_sum

