    print(compute_max_sum(z))

import sys

def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in '+-*/<=>&|^()':
            tokens.append(c)
            i += 1
        elif c.islower():
            tokens.append(c)
            i += 1
        else:
            i += 1
    return tokens

def parse_primary(tokens, op_info):
    if not tokens:
        raise ValueError("Unexpected end of input")
    token = tokens.pop(0)
    if token == '(':
        expr = parse_expression(tokens, op_info)
        if not tokens or tokens.pop(0) != ')':
            raise ValueError("Unclosed parenthesis")
        return expr
    elif token in op_info:
        raise ValueError(f"Unexpected operator {token}")
    else:
        return token

def parse_expression(tokens, op_info):
    lhs = parse_primary(tokens, op_info)
    return parse_expression_rest(lhs, 0, tokens, op_info)

def parse_expression_rest(lhs, min_prec, tokens, op_info):
    while True:
        if not tokens:
            break
        current_token = tokens[0]
        if current_token not in op_info:
            break
        op_prec, op_assoc = op_info[current_token]
        if op_prec < min_prec:
            break
        op = tokens.pop(0)
        rhs = parse_primary(tokens, op_info)
        next_min_prec = op_prec + 1 if op_assoc == 'L' else op_prec
        rhs = parse_expression_rest(rhs, next_min_prec, tokens, op_info)
        lhs = (op, lhs, rhs)
    return lhs

def generate(node):
    if isinstance(node, str):
        return node
    op, left, right = node
    left_str = generate(left)
    right_str = generate(right)
    return f"({left_str}{op}{right_str})"

