def tarjan(u, adj, indices, low, on_stack, S, sccs):
    indices[u] = tarjan.index
    low[u] = tarjan.index
    tarjan.index += 1
    S.append(u)
    on_stack[u] = True
    for v in adj[u]:
        if indices[v] == -1:
            tarjan(v, adj, indices, low, on_stack, S, sccs)
            low[u] = min(low[u], low[v])
        elif on_stack[v]:
            low[u] = min(low[u], indices[v])
    if low[u] == indices[u]:
        scc = []
        while True:
            v = S.pop()
            on_stack[v] = False
            scc.append(v)
            if v == u:
                break
        sccs.append(scc)

