        # Find SCCs using Tarjan's algorithm
        indices = [-1] * (N+1)
        low = [-1] * (N+1)
        on_stack = [False] * (N+1)
        S = []
        sccs = []
        tarjan.index = 0
        for u in range(1, N+1):
            if indices[u] == -1:
                tarjan(u, adj, indices, low, on_stack, S, sccs)
        # Determine source components
        source_components = []
        for scc in sccs:
            scc_set = set(scc)
            is_source = True
            for u in range(1, N+1):
                if u not in scc_set:
                    for v in adj[u]:
                        if v in scc_set:
                            is_source = False
                            break
                    if not is_source:
