import sys
from sys import stdin

def main():
    sys.setrecursionlimit(1 << 25)
    n, q = map(int, stdin.readline().split())
    parents = list(map(int, stdin.readline().split()))
    children = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        p = parents[i - 2]
        children[p].append(i)

    # Compute sizes using iterative post-order traversal
    size = [1] * (n + 1)
    stack = [(1, False)]
    while stack:
        node, processed = stack.pop()
        if not processed:
            stack.append((node, True))
            for child in reversed(children[node]):
                stack.append((child, False))
        else:
            for child in children[node]:
                size[node] += size[child]

    # Compute centroids using post-order traversal
    centroid = [0] * (n + 1)
    stack = [(1, False)]
    while stack:
        node, processed = stack.pop()
        if not processed:
            stack.append((node, True))
            # Push children in reverse to process them in order
            for child in reversed(children[node]):
                stack.append((child, False))
        else:
            max_size = 0
            max_child = -1
            for child in children[node]:
                if size[child] > max_size:
                    max_size = size[child]
                    max_child = child
            if max_size > size[node] // 2:
                centroid[node] = centroid[max_child]
            else:
                centroid[node] = node

    # Answer queries
    for _ in range(q):
        v = int(stdin.readline())
        print(centroid[v])

