import sys
from sys import stdin
from collections import deque

def find_centroid(n, adj):
    size = [0] * (n+1)
    visited = [False] * (n+1)

    def dfs(u, prev):
        size[u] = 1
        for v in adj[u]:
            if v != prev and not visited[v]:
                dfs(v, u)
                size[u] += size[v]
        return size[u]

    def get_centroid(u, prev, total):
        for v in adj[u]:
            if v != prev and not visited[v] and size[v] > total//2:
                return get_centroid(v, u, total)
        return u

    dfs(1, -1)
    centroid = get_centroid(1, -1, size[1])
    return centroid

def main():
    n = int(stdin.readline())
    adj = [[] for _ in range(n+1)]
    edges = []
    for _ in range(n-1):
        a, b = map(int, stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)
        edges.append((a, b))

    centroid = find_centroid(n, adj)

    parent = [0] * (n+1)
    subtree_size = [0] * (n+1)
    visited = [False] * (n+1)
    q = deque()
    q.append(centroid)
    visited[centroid] = True
    parent[centroid] = -1

    while q:
        u = q.popleft()
        subtree_size[u] = 1
        for v in adj[u]:
            if not visited[v] and v != parent[u]:
                parent[v] = u
                visited[v] = True
                q.append(v)

    stack = []
    visited_sub = [False] * (n+1)
    def post_order(u):
        stack.append(u)
        visited_sub[u] = True
        for v in adj[u]:
            if v != parent[u] and not visited_sub[v]:
                post_order(v)
                subtree_size[u] += subtree_size[v]
    post_order(centroid)

    transformations = []
    temp_parent = parent.copy()
    for u in reversed(stack):
        if u == centroid:
            continue
        current = u
        while temp_parent[current] != centroid:
            p = temp_parent[current]
            pp = temp_parent[p]
            if pp == -1:
                break
            if subtree_size[current] <= n // 2:
                transformations.append((p, current, pp))
                temp_parent[current] = pp
            else:
                break

    print(len(transformations))
    for x, y, y_prime in transformations:
        print(x, y, y_prime)

