import sys

def compute_lps(pattern):
    lps = [0] * len(pattern)
    length = 0  # Length of the previous longest prefix suffix

    for i in range(1, len(pattern)):
        while length > 0 and pattern[i] != pattern[length]:
            length = lps[length - 1]

        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0

    return lps

def main():
    T = sys.stdin.readline().strip()
    P = sys.stdin.readline().strip()

    if len(P) == 0 or len(P) > len(T):
        return

    lps = compute_lps(P)

    i = 0  # Index for T
    j = 0  # Index for P
    result = []

    while i < len(T):
        if T[i] == P[j]:
            i += 1
            j += 1
            if j == len(P):
                # Record the starting index of the match
                result.append(i - len(P))
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    for idx in result:
        print(idx)

