def prune(states):
    states = list(set(states))
    states.sort(reverse=True, key=lambda x: sum(x))
    pruned = []
    for candidate in states:
        dominated = False
        for s in pruned:
            if all(candidate[i] <= s[i] for i in range(len(candidate))):
                dominated = True
                break
        if not dominated:
            new_pruned = []
            for s in pruned:
                if not all(s[i] <= candidate[i] for i in range(len(candidate))):
                    new_pruned.append(s)
            new_pruned.append(candidate)
            pruned = new_pruned
    return pruned

