import sys
from fractions import Fraction

def main():
    n = int(sys.stdin.readline())
    lengths = list(map(int, sys.stdin.readline().split()))

    sum_kraft = sum(Fraction(1, 2**l) for l in lengths)
    if sum_kraft > 1:
        print("NO")
        return

    sorted_lengths = sorted([(l, i) for i, l in enumerate(lengths)], key=lambda x: x[0])
    existing_codes = []
    answer = [None] * n

    for l, original_index in sorted_lengths:
        intervals = []
        for code in existing_codes:
            k = len(code)
            if k > l:
                continue
            a = int(code, 2) * (2 ** (l - k))
            b = a + (2 ** (l - k)) - 1
            intervals.append((a, b))

        intervals.sort()
        merged = []
        for a, b in intervals:
            if not merged:
                merged.append((a, b))
            else:
                last_a, last_b = merged[-1]
                if a > last_b + 1:
                    merged.append((a, b))
                else:
                    merged[-1] = (last_a, max(last_b, b))

        max_val = (2 ** l) - 1
        candidate = 0
        found = False

        if not merged:
            found = True
        else:
            if candidate < merged[0][0]:
                found = True
            else:
                for i in range(len(merged) - 1):
                    current_b = merged[i][1]
                    next_a = merged[i + 1][0]
                    if current_b + 1 < next_a:
                        candidate = current_b + 1
                        found = True
                        break
                if not found:
                    last_b = merged[-1][1]
                    if last_b < max_val:
                        candidate = last_b + 1
                        found = True

        binary = bin(candidate)[2:].zfill(l)
        existing_codes.append(binary)
        answer[original_index] = binary

    print("YES")
    for code in answer:
        print(code)

