import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)

    visited = [False] * (n+1)
    components = []

    for u in range(1, n+1):
        if not visited[u]:
            q = deque()
            q.append(u)
            visited[u] = True
            component = []
            while q:
                v = q.popleft()
                component.append(v)
                for w in edges[v]:
                    if not visited[w]:
                        visited[w] = True
                        q.append(w)
            components.append(component)

    total_merges = len(components) - 1

    max_closed = 0
    for comp in components:
        comp_size = len(comp)
        if comp_size == 1:
            current_max = 1
        else:
            current_max = 0
            node_map = {v: i for i, v in enumerate(comp)}
            comp_edges = [[] for _ in comp]
            for v in comp:
                for w in edges[v]:
                    if w in node_map:
                        comp_edges[node_map[v]].append(node_map[w])

            size_comp = len(comp)
            for start in range(size_comp):
                visited_bfs = [False] * size_comp
                q = deque()
                q.append((start, [start]))
                visited_bfs[start] = True
                best_path = []
                while q:
                    node, path = q.popleft()
                    if len(path) > len(best_path):
                        best_path = path[:]
                    for neighbor in comp_edges[node]:
                        if not visited_bfs[neighbor]:
                            visited_bfs[neighbor] = True
                            q.append((neighbor, path + [neighbor]))
                nodes_in_path = set()
                for node in best_path:
                    nodes_in_path.add(comp[node])
                    for neighbor in edges[comp[node]]:
                        if neighbor in node_map:
                            nodes_in_path.add(neighbor)
                current_max = max(current_max, len(nodes_in_path))
        max_closed += current_max

    total_merges += (n - max_closed)
    print(total_merges)

