def count_ways(n):
    total = 0
    k = 2
    while True:
        k_cubed = k ** 3
        if k_cubed > n:
            break
        total += n // k_cubed
        k += 1
    return total

def find_n(m):
    if m == 0:
        return -1
    low = 8
    high = 8
    # Exponential search to find upper bound
    while True:
        current = count_ways(high)
        if current >= m:
            break
        if high > 10**18:
            return -1
        high *= 2
    # Binary search to find the minimal n
    while low <= high:
        mid = (low + high) // 2
        s = count_ways(mid)
        if s < m:
            low = mid + 1
        else:
            high = mid - 1
    # Check if the found n has exactly m ways
    if count_ways(low) == m:
        return low
    else:
        return -1

