import math

def is_prime(m):
    if m <= 1:
        return False
    if m == 2:
        return True
    if m % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(m)) + 1, 2):
        if m % i == 0:
            return False
    return True

def get_prev_prime(n):
    m = n - 1
    while m >= 2:
        if is_prime(m):
            return m
        m -= 1

def get_next_prime(n):
    m = n + 1
    while True:
        if is_prime(m):
