        if m == 0 and n == 0:
            break
        # Calculate the (n+1)th term in the sequence
        heap = []
        current = m
        result = 0
        for step in range(n + 1):
            while True:
                if heap and heap[0][0] <= current:
                    val, k = heapq.heappop(heap)
                    if val < current:
                        next_val = val + k
                        heapq.heappush(heap, (next_val, k))
                    elif val == current:
                        next_val = val + k
                        heapq.heappush(heap, (next_val, k))
                        current += 1
                    else:
                        heapq.heappush(heap, (val, k))
                        break
                else:
                    break
            if step == n:
                result = current
                break
            heapq.heappush(heap, (current * 2, current))
            current += 1
        print(result)

