import math

EPS = 1e-9

class Member:
    def __init__(self):
        self.segments = []  # list of (x0, y0, x1, y1, t_start, t_end)
        self.singing = []   # list of (start, end)

    def get_position(self, t):
        for seg in self.segments:
            if seg[4] - EPS <= t <= seg[5] + EPS:
                x0, y0, x1, y1, t0, t1 = seg
                if t0 == t1:
                    return (x0, y0)
                dt = t - t0
                frac = dt / (t1 - t0)
                x = x0 + (x1 - x0) * frac
                y = y0 + (y1 - y0) * frac
                return (x, y)
        # After last segment, return last point
        last = self.segments[-1]
        return (last[2], last[3])

def read_member():
    m = Member()
    mi = int(input())
    prev_x, prev_y, prev_t = None, None, None
    for _ in range(mi):
        x, y, t = map(int, input().split(','))
        if prev_x is not None:
            seg = (prev_x, prev_y, x, y, prev_t, t)
            m.segments.append(seg)
        prev_x, prev_y, prev_t = x, y, t
    li = int(input())
    for _ in range(li):
        b, e = map(int, input().split(','))
        m.singing.append((b, e))
    return m

def direction(cx, cy, x, y):
    dx = x - cx
    dy = y - cy
    d = math.hypot(dx, dy)
    if d < EPS:
        return (0.0, 0.0)
    return (dx / d, dy / d)

def check_direction(cx, cy, m1, t1, m2, t2):
    x1, y1 = m1.get_position(t1)
    x2, y2 = m2.get_position(t2)
    d1 = direction(cx, cy, x1, y1)
    d2 = direction(cx, cy, x2, y2)
    return math.hypot(d1[0] - d2[0], d1[1] - d2[1]) < EPS

def interval_overlap(a_start, a_end, b_start, b_end):
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    if start > end + EPS:
        return None
    return (start, end)

def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    while True:
        N = int(input[ptr])
        ptr +=1
        if N ==0:
            break
        cx = int(input[ptr])
        cy = int(input[ptr+1])
        ptr +=2
        members = []
        for _ in range(N):
            mi = int(input[ptr])
            ptr +=1
            prev_x, prev_y, prev_t = None, None, None
            segments = []
            for _ in range(mi):
                x = int(input[ptr])
                y = int(input[ptr+1])
                t = int(input[ptr+2])
                ptr +=3
                if prev_x is not None:
                    seg = (prev_x, prev_y, x, y, prev_t, t)
                    segments.append(seg)
                prev_x, prev_y, prev_t = x, y, t
            li = int(input[ptr])
            ptr +=1
            singing = []
            for _ in range(li):
                b = int(input[ptr])
                e = int(input[ptr+1])
                ptr +=2
                singing.append((b, e))
            m = Member()
            m.segments = segments
            m.singing = singing
            members.append(m)

        intervals = []
        for i, m in enumerate(members):
            for (s, e) in m.singing:
                intervals.append((s, e, i))
        intervals.sort()
        max_time = 0.0
        dp = {}
        intervals.sort(key=lambda x: x[0])
        for i in range(len(intervals)):
            s, e, idx = intervals[i]
            dur = e - s
            dp[i] = dur
            for j in range(i):
                js, je, jidx = intervals[j]
                if idx == jidx:
                    continue
                overlap = interval_overlap(js, je, s, e)
                if not overlap:
                    continue
                ol_start, ol_end = overlap
                found = False
                m1 = members[jidx]
                m2 = members[idx]
                for t_test in [ol_start, ol_end, (ol_start + ol_end)/2]:
                    if check_direction(cx, cy, m1, t_test, m2, t_test):
                        found = True
                        break
                if found:
                    dp[i] = max(dp[i], dp[j] + (e - ol_start))
            max_time = max(max_time, dp[i])
        print("{0:.8f}".format(max_time))

