import sys
from itertools import product

def parse(s):
    s = s.replace(' ', '')
    def helper(i):
        if s[i] == '[':
            i += 1
            op = s[i]
            i += 1
            left, i = helper(i)
            right, i = helper(i)
            i += 1  # consume ']'
            return (op, left, right), i
        else:
            char = s[i]
            i += 1
            return char, i
    parsed, _ = helper(0)
    return parsed

def evaluate(node, a, b, c, d):
    if isinstance(node, str):
        if node == 'a':
            return a
        elif node == 'b':
            return b
        elif node == 'c':
            return c
        elif node == 'd':
            return d
        else:
            raise ValueError("Invalid letter")
    else:
        op, left, right = node
        left_val = evaluate(left, a, b, c, d)
        right_val = evaluate(right, a, b, c, d)
        if op == '+':
            return (left_val | right_val) & 0b1111
        elif op == '*':
            return (left_val & right_val) & 0b1111
        elif op == '^':
            return (left_val ^ right_val) & 0b1111
        else:
            raise ValueError("Invalid operator")

