import sys

def comb(n, k):
    if k > n - k:
        k = n - k
    res = 1
    for i in range(1, k + 1):
        res = res * (n - k + i) // i
    return res

def find_min_n(N):
    low = 1
    high = 1
    while comb(high, high // 2) < N:
        high *= 2
    while low < high:
        mid = (low + high) // 2
        c = comb(mid, mid // 2)
        if c >= N:
            high = mid
        else:
            low = mid + 1
    return high

