import sys
from collections import deque, defaultdict

d, n = map(int, sys.stdin.readline().split())
a = list(map(int, sys.stdin.readline().split()))
a = [0] + a  # 1-based indexing

adj = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    u, v = map(int, sys.stdin.readline().split())
    adj[u].append(v)
    adj[v].append(u)

sorted_nodes = sorted(range(1, n + 1), key=lambda x: (a[x], x))

total = 0

for u in sorted_nodes:
    a_u = a[u]
    allowed = [False] * (n + 1)
    for v in range(1, n + 1):
        if a[v] < a_u or a[v] > a_u + d:
            allowed[v] = False
        else:
            if a[v] == a_u:
                allowed[v] = (v >= u)
            else:
                allowed[v] = True

    # BFS to find component
    component = set()
    parent = {}
    queue = deque([u])
    component.add(u)
    parent[u] = None
    while queue:
        node = queue.popleft()
        for neighbor in adj[node]:
            if neighbor not in component and allowed[neighbor]:
                component.add(neighbor)
                parent[neighbor] = node
                queue.append(neighbor)

    # Build children hierarchy
    children = defaultdict(list)
    for v in component:
        p = parent.get(v)
        if p is not None:
            children[p].append(v)

    # Iterative post-order traversal to compute DP
    dp = {}
    stack = [(u, False)]
    while stack:
        node, visited = stack.pop()
        if not visited:
            stack.append((node, True))
            for child in reversed(children[node]):
                stack.append((child, False))
        else:
            res = 1
            for child in children[node]:
                res = res * (1 + dp[child]) % MOD
            dp[node] = res

    total = (total + dp.get(u, 0)) % MOD

print(total)

