import sys
from collections import defaultdict

def main():
    W = int(sys.stdin.readline())
    words = [sys.stdin.readline().strip() for _ in range(W)]

    # Collect all unique characters
    chars = set()
    for word in words:
        for c in word:
            chars.add(c)
    chars = sorted(chars)  # Sorted for processing in natural order

    # Build adjacency list and in-degree
    adj = defaultdict(list)
    in_degree = {c: 0 for c in chars}

    for i in range(W - 1):
        word1 = words[i]
        word2 = words[i + 1]
        min_len = min(len(word1), len(word2))
        for j in range(min_len):
            c1 = word1[j]
            c2 = word2[j]
            if c1 != c2:
                if c2 not in adj[c1]:
                    adj[c1].append(c2)
                    in_degree[c2] += 1
                break  # Only the first differing character matters

    # Kahn's algorithm to find the topological order with levels
    current_in_degree = in_degree.copy()
    result = []
    available = sorted([c for c in chars if current_in_degree[c] == 0])

    while available:
        result.append(available)
        next_available = []
        for c in available:
            for neighbor in adj[c]:
                current_in_degree[neighbor] -= 1
                if current_in_degree[neighbor] == 0:
                    next_available.append(neighbor)
        available = sorted(next_available)  # Sort to process in natural order

    # Output each level's characters in natural order
    for level in result:
        print(''.join(level))

