def compute_minimal_period(s):
    n = len(s)
    failure = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and s[i] != s[j]:
            j = failure[j-1]
        if s[i] == s[j]:
            j += 1
            failure[i] = j
        else:
            failure[i] = 0
    period = n - failure[-1]
    if failure[-1] > 0 and n % period == 0:
        return period
    else:
        return n

def find_occurrences(text, pattern):
    m = len(pattern)
    if m == 0:
        return []
    lps = [0] * m
    length = 0
    for i in range(1, m):
        while length > 0 and pattern[i] != pattern[length]:
            length = lps[length - 1]
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
        else:
            lps[i] = 0
    occurrences = []
    j = 0
    for i in range(len(text)):
        while j > 0 and text[i] != pattern[j]:
            j = lps[j - 1]
        if text[i] == pattern[j]:
            j += 1
            if j == m:
                occurrences.append(i - m + 1)
                j = lps[j - 1]
    return occurrences

