import sys

class SegmentTree:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None
        self.count = 0

    def get_mid(self):
        return (self.start + self.end) // 2

    def extend(self):
        if self.start < self.end - 1 and not self.left:
            mid = self.get_mid()
            self.left = SegmentTree(self.start, mid)
            self.right = SegmentTree(mid, self.end)

    def add(self, a, b):
        if a >= self.end or b <= self.start:
            return
        if a <= self.start and self.end <= b:
            self.count += 1
        else:
            self.extend()
            self.left.add(a, b)
            self.right.add(a, b)

    def remove(self, a, b):
        if a >= self.end or b <= self.start:
            return
        if a <= self.start and self.end <= b:
            self.count -= 1
        else:
            self.extend()
            self.left.remove(a, b)
            self.right.remove(a, b)

    def query(self, a, b):
        if a >= self.end or b <= self.start:
            return 0
        if self.count > 0:
            return min(b, self.end) - max(a, self.start)
        if self.start >= self.end - 1:
            return 0
        return self.left.query(a, b) + self.right.query(a, b)

def process_dataset(n, r, rectangles):
    area = 0
    vertical_perim = 0
    horizontal_perim = 0

    if r == 1 or r == 2:
        vertical_events = []
        for x1, y1, x2, y2 in rectangles:
            vertical_events.append((x1, 'add', y1, y2))
            vertical_events.append((x2, 'remove', y1, y2))
        vertical_events.sort(key=lambda e: (e[0], 0 if e[1] == 'remove' else 1))

        seg_y = SegmentTree(0, 10000)
        prev_x = None
        area = 0
        vertical_perim = 0

        for event in vertical_events:
            curr_x, typ, y1, y2 = event
            if prev_x is not None and curr_x > prev_x:
                dx = curr_x - prev_x
                coverage = seg_y.query(0, 10000)
                area += dx * coverage
            if typ == 'add':
                covered = seg_y.query(y1, y2)
                vertical_perim += (y2 - y1) - covered
                seg_y.add(y1, y2)
            else:
                seg_y.remove(y1, y2)
                covered = seg_y.query(y1, y2)
                vertical_perim += (y2 - y1) - covered
            prev_x = curr_x

    if r == 2:
        horizontal_events = []
        for x1, y1, x2, y2 in rectangles:
            horizontal_events.append((y1, 'add', x1, x2))
            horizontal_events.append((y2, 'remove', x1, x2))
        horizontal_events.sort(key=lambda e: (e[0], 0 if e[1] == 'remove' else 1))

        seg_x = SegmentTree(0, 10000)
        horizontal_perim = 0
        prev_y = None

        for event in horizontal_events:
            curr_y, typ, x1, x2 = event
            if typ == 'add':
                covered = seg_x.query(x1, x2)
                horizontal_perim += (x2 - x1) - covered
                seg_x.add(x1, x2)
            else:
                seg_x.remove(x1, x2)
                covered = seg_x.query(x1, x2)
                horizontal_perim += (x2 - x1) - covered

    if r == 1:
        print(area)
    elif r == 2:
        print(area)
        print(vertical_perim + horizontal_perim)

