import heapq

def main():
    while True:
        n, m = map(int, sys.stdin.readline().split())
        if n == 0 and m == 0:
            break
        d = {}
        alt = [0]*(n+1)
        alt[1] = 0
        if n > 2:
            for i in range(2, n):
                di, ei = map(int, sys.stdin.readline().split())
                d[i] = di
                alt[i] = ei
        alt[n] = 1000
        go_roads = [[] for _ in range(n+1)]
        return_roads = [[] for _ in range(n+1)]
        for _ in range(m):
            a, b, c = map(int, sys.stdin.readline().split())
            if alt[a] <= alt[b]:
                go_roads[a].append((b, c))
            if alt[a] >= alt[b]:
                return_roads[a].append((b, c))
        heap = []
        visited = dict()
        heapq.heappush(heap, (0, 1, 0, 0))  # cost, current, phase, mask
        found = False
        while heap:
            cost, current, phase, mask = heapq.heappop(heap)
            if current == 1 and phase == 1:
                print(cost)
                found = True
                break
            key = (current, phase, mask)
            if key in visited:
                if visited[key] <= cost:
                    continue
            visited[key] = cost
            if phase == 0:  # go phase
                for (neighbor, road_cost) in go_roads[current]:
                    new_mask = mask
                    new_cost = cost + road_cost
                    if 2 <= neighbor <= n-1:
                        bit = 1 << (neighbor - 2)
                        if not (mask & bit):
                            new_cost += d[neighbor]
                            new_mask = mask | bit
                    new_phase = phase
                    if neighbor == n:
                        new_phase = 1
                    new_key = (neighbor, new_phase, new_mask)
                    if new_key not in visited or new_cost < visited.get(new_key, float('inf')):
                        heapq.heappush(heap, (new_cost, neighbor, new_phase, new_mask))
            else:  # return phase
                for (neighbor, road_cost) in return_roads[current]:
                    new_mask = mask
                    new_cost = cost + road_cost
                    if 2 <= neighbor <= n-1:
                        bit = 1 << (neighbor - 2)
                        if not (mask & bit):
                            new_cost += d[neighbor]
                            new_mask = mask | bit
                    new_phase = phase
                    new_key = (neighbor, new_phase, new_mask)
                    if new_key not in visited or new_cost < visited.get(new_key, float('inf')):
                        heapq.heappush(heap, (new_cost, neighbor, new_phase, new_mask))
        if not found:
            print(-1)

