import math

def main():
    while True:
        n = int(input())
        if n == 0:
            break
        vx, vy = map(float, input().split())
        r = float(input())
        robots = []
        for _ in range(n):
            x, y, u = map(float, input().split())
            robots.append((x, y, u))

        min_time = None

        for i in range(n):
            xi, yi, ui = robots[i]
            for j in range(i + 1, n):
                xj, yj, uj = robots[j]
                if ui == uj:
                    continue
                delta_x0 = xi - xj
                delta_y0 = yi - yj
                delta_u = ui - uj
                A = (delta_u ** 2) * (vx ** 2 + vy ** 2)
                if A == 0:
                    continue
                B = 2 * delta_u * (delta_x0 * vx + delta_y0 * vy)
                C = (delta_x0 ** 2 + delta_y0 ** 2) - (2 * r) ** 2
                D = B * B - 4 * A * C
                if D < 0:
                    continue
                sqrtD = math.sqrt(D)
                t1 = (-B - sqrtD) / (2 * A)
                t2 = (-B + sqrtD) / (2 * A)

                if t2 < 0:
                    continue
                if t1 < 0:
                    continue

                if (min_time is None) or (t1 < min_time):
                    min_time = t1

        if min_time is not None:
            print("{0:.6f}".format(min_time))
        else:
            print("SAFE")

