def process_line(line):
    parts = line.strip().split()
    number_part = parts[0]
    remaining = parts[1:]

    prefix_exponent = 0
    unit_parts = []
    if remaining and remaining[0] in prefix_dict:
        prefix = remaining[0]
        prefix_exponent = prefix_dict[prefix]
        unit_parts = remaining[1:]
    else:
        unit_parts = remaining

    unit = ' '.join(unit_parts)

    if '.' in number_part:
        left, right = number_part.split('.', 1)
    else:
        left, right = number_part, ''

    combined = left + right
    start = None
    for i, c in enumerate(combined):
        if c != '0':
            start = i
            break

    if start is None:
        start = 0

    significant_digits = combined[start:] if start < len(combined) else '0'
    if not significant_digits:
        a_str = '0'
    else:
        if len(significant_digits) == 1:
            a_str = significant_digits
        else:
            a_str = significant_digits[0] + '.' + significant_digits[1:]

    exponent = len(left) - start - 1 + prefix_exponent
    return f"{a_str} * 10^{exponent} {unit}"

