import sys
from sys import stdin
sys.setrecursionlimit(1 << 25)

def main():
    n, m = map(int, stdin.readline().split())
    edges = []
    adj = [[] for _ in range(n+1)]
    for idx in range(m):
        a, b = map(int, stdin.readline().split())
        edges.append((a, b))
        adj[a].append((b, idx))
        adj[b].append((a, idx))

    # Tarjan's algorithm to find bridges, iterative version
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    time = 1
    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)
    bridges = set()

    for start in range(1, n+1):
        if not visited[start]:
            stack = [(start, -1, False)]
            while stack:
                u, p, is_processed = stack.pop()
                if not is_processed:
                    if visited[u]:
                        continue
                    visited[u] = True
                    parent[u] = p
                    disc[u] = low[u] = time
                    time += 1
                    # Push back to stack after children
                    stack.append((u, p, True))
                    # Push children in reverse order
                    for v, idx in reversed(adj[u]):
                        if v == p:
                            continue
                        if not visited[v]:
                            stack.append((v, u, False))
                        else:
                            # Update low for back edge
                            if disc[v] < low[u]:
                                low[u] = disc[v]
                else:
                    for v, idx in adj[u]:
                        if parent[v] == u:  # u is the parent of v (tree edge)
                            if low[v] < low[u]:
                                low[u] = low[v]
                            if low[v] > disc[u]:
                                bridges.add(idx)

    if bridges:
        print(0)
    else:
        directions = []
        for a, b in edges:
            # Check if it's a tree edge
            if parent[b] == a:
                directions.append(f"{a} {b}")
            elif parent[a] == b:
                directions.append(f"{b} {a}")
            else:
                if disc[a] > disc[b]:
                    directions.append(f"{a} {b}")
                else:
                    directions.append(f"{b} {a}")
        print('\n'.join(directions))

