def prime_factors(x):
    factors = set()
    if x % 2 == 0:
        factors.add(2)
        while x % 2 == 0:
            x //= 2
    i = 3
    while i * i <= x:
        if x % i == 0:
            factors.add(i)
            while x % i == 0:
                x //= i
        i += 2
    if x > 1:
        factors.add(x)
    return factors

