def compute_times(h, a, x, y, m):
    current = h
    seen = {}
    t0 = None
    time = 0
    while True:
        if current == a:
            t0 = time
            break
        if current in seen:
            return (None, None)
        seen[current] = time
        current = (x * current + y) % m
        time += 1

    current = a
    seen_post = {}
    delta = None
    post_time = 0
    while True:
        if current == a and post_time != 0:
            delta = post_time
            break
        if current in seen_post:
            break
        seen_post[current] = post_time
        current = (x * current + y) % m
        post_time += 1
    return (t0, delta)

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = extended_gcd(b, a % b)
        return (g, y, x - (a // b) * y)

def find_min_common(a, m, b, n):
    g, xg, yg = extended_gcd(m, n)
    if (b - a) % g != 0:
        return -1
    lcm = m // g * n
    m_div_g = m // g
    n_div_g = n // g
    c = (b - a) // g
    _, inv, _ = extended_gcd(m_div_g, n_div_g)
    inv %= n_div_g
    k = (c * inv) % n_div_g
    x0 = a + k * m
    x = x0
    if x < max(a, b):
        delta = (max(a, b) - x + lcm - 1) // lcm
        x += delta * lcm
    if (x - a) % m == 0 and (x - b) % n == 0 and x >= max(a, b):
        return x
    else:
        return -1

