        adj = [[] for _ in range(n + 1)]
        for u, v, c in edges:
            if target == 'R':
                if c == 'R':
                    type_u_v = 'same'
                else:
                    type_u_v = 'different'
            else:
                if c == 'B':
                    type_u_v = 'same'
                else:
                    type_u_v = 'different'
            adj[u].append((v, type_u_v))
            adj[v].append((u, type_u_v))

        visited = [False] * (n + 1)
        color = [0] * (n + 1)
        total_flips = 0
        flip_list = []
        possible = True

        for u in range(1, n + 1):
            if not visited[u]:
                queue = deque()
                queue.append(u)
                visited[u] = True
                color[u] = 0
                count0 = 1
                count1 = 0
                current_nodes = [u]
                valid = True

                while queue and valid:
                    v = queue.popleft()
                    for neighbor, edge_type in adj[v]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            current_nodes.append(neighbor)
                            if edge_type == 'same':
                                c = color[v]
                            else:
                                c = 1 - color[v]
                            color[neighbor] = c
                            if c == 0:
                                count0 += 1
                            else:
                                count1 += 1
                            queue.append(neighbor)
                        else:
                            expected = color[v] if edge_type == 'same' else 1 - color[v]
                            if color[neighbor] != expected:
                                valid = False
                                possible = False
                                break
                    if not valid:
                        break

                if not possible:
                    break

                if count0 <= count1:
                    for node in current_nodes:
                        if color[node] == 0:
                            flip_list.append(node)
                else:
                    for node in current_nodes:
                        if color[node] == 1:
                            flip_list.append(node)
                total_flips += min(count0, count1)

        if possible:
            return (total_flips, flip_list)
        else:
            return (float('inf'), [])

    r_res = solve('R')
    b_res = solve('B')
    min_flips = min(r_res[0], b_res[0])

