import math
from functools import lru_cache

def integer_root(n, b):
    if n < 0 or b < 1:
        return None
    low = 1
    high = n
    while low <= high:
        mid = (low + high) // 2
        power = mid ** b
        if power == n:
            return mid
        elif power < n:
            low = mid + 1
        else:
            high = mid - 1
    if high ** b == n:
        return high
    else:
        return None

def get_exponents(n):
    exponents = []
    if n < 2:
        return exponents
    max_b = int(math.log(n, 2)) + 2
    for b in range(2, max_b + 1):
        a = integer_root(n, b)
        if a is not None and a ** b == n:
            exponents.append((a, b))
    return exponents

@lru_cache(maxsize=None)
def minimal_representation(m, allow_exponents):
    if m == 0:
        return ("0", 1)
    s = str(m)
    min_len = len(s)
    best = s

    for a in range(1, int(math.isqrt(m)) + 1):
        if m % a == 0:
            b = m // a
            if a > b:
                continue
            a_str, a_len = minimal_representation(a, allow_exponents)
            b_str, b_len = minimal_representation(b, allow_exponents)
            total_len = a_len + b_len + 1
            if total_len < min_len:
                min_len = total_len
                best = f"{a_str}*{b_str}"

    for a in range(1, min(m, 100) + 1):
        b = m - a
        if b < 1:
            continue
        a_str, a_len = minimal_representation(a, allow_exponents)
        b_str, b_len = minimal_representation(b, allow_exponents)
        total_len = a_len + b_len + 1
        if total_len < min_len:
            min_len = total_len
            best = f"{a_str}+{b_str}"

    if allow_exponents:
        exponents = get_exponents(m)
        for a, b in exponents:
            a_str, a_len = minimal_representation(a, False)
            b_str, b_len = minimal_representation(b, False)
            total_len = a_len + 1 + b_len
            if total_len < min_len:
                min_len = total_len
                best = f"{a_str}^{b_str}"

    return (best, min_len)

