class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)  # 1-based indexing

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

def count_inversions(arr):
    n = len(arr)
    ft = FenwickTree(n)
    inversions = 0
    for x in reversed(arr):
        inversions += ft.query(x)
        ft.update(x + 1, 1)  # x is 0-based, stored at x+1 in FenwickTree
    return inversions

