def solve():
    import sys

    def can_form(counts):
        def backtrack(remaining, cnts):
            if remaining == 0:
                return all(c == 0 for c in cnts)
            # Try same triplets
            for i in range(1, 10):
                if cnts[i] >= 3:
                    new_cnts = list(cnts)
                    new_cnts[i] -= 3
                    if backtrack(remaining - 1, new_cnts):
                        return True
            # Try consecutive triplets
            for i in range(1, 8):
                if cnts[i] >= 1 and cnts[i+1] >= 1 and cnts[i+2] >= 1:
                    new_cnts = list(cnts)
                    new_cnts[i] -= 1
                    new_cnts[i+1] -= 1
                    new_cnts[i+2] -= 1
                    if backtrack(remaining - 1, new_cnts):
                        return True
            return False

        return backtrack(4, list(counts))

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        counts = [0] * 10  # indexes 0-9, 0 unused
        for c in line:
            num = int(c)
            counts[num] += 1
        valid = []
        for x in range(1, 10):
            if counts[x] >= 4:
                continue
            new_counts = counts.copy()
            new_counts[x] += 1
            possible_pairs = [i for i in range(1, 10) if new_counts[i] >= 2]
            found = False
            for pair in possible_pairs:
                temp_counts = new_counts.copy()
                temp_counts[pair] -= 2
                if can_form(temp_counts):
                    valid.append(x)
                    found = True
                    break
            if found:
                continue
        if valid:
