import math

def get_positive_divisors(n):
    if n == 0:
        return []
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors, reverse=True)

def get_divisors(n):
    if n == 0:
        return set()
    divisors = set()
    for i in range(1, int(math.isqrt(abs(n))) + 1):
        if n % i == 0:
            divisors.add(i)
