import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    while True:
        N = int(input[ptr])
        M = int(input[ptr+1])
        Z = int(input[ptr+2])
        ptr +=3
        if N == 0 and M ==0 and Z ==0:
            break
        adj = [[] for _ in range(N+1)]  # 1-based indexing
        for _ in range(M):
            s = int(input[ptr])
            d = int(input[ptr+1])
            adj[s].append(d)
            adj[d].append(s)
            ptr +=2

        # BFS to find minimal steps to reach each (current, prev) state
        min_steps = [[-1]*(N+1) for _ in range(N+1)]
        q = deque()
        q.append( (1, 0) )
        min_steps[1][0] = 0
        while q:
            current, prev = q.popleft()
            for neighbor in adj[current]:
                if neighbor != prev:
                    if min_steps[neighbor][current] == -1:
                        min_steps[neighbor][current] = min_steps[current][prev] + 1
                        q.append( (neighbor, current) )

        # Check if any (N, v) has steps == Z
        found_early = False
        candidates = []
        for prev_st in range(N+1):
            if min_steps[N][prev_st] != -1:
                if min_steps[N][prev_st] == Z:
                    found_early = True
                    break
                if min_steps[N][prev_st] <= Z:
                    candidates.append( (prev_st, min_steps[N][prev_st]) )
        if found_early:
            print("yes")
            continue

        # Check for cycles from each candidate (N, prev_st)
        possible = False
        for (prev_st, m) in candidates:
            # BFS to find paths returning to N
            visited = {}
            q = deque()
            q.append( (N, prev_st, 0) )
            visited[(N, prev_st)] = 0
            found_inner = False
            while q and not found_inner:
                current, prev, steps = q.popleft()
                for neighbor in adj[current]:
                    if neighbor != prev:
                        next_state = (neighbor, current)
                        next_steps = steps + 1
                        if next_state not in visited:
                            visited[next_state] = next_steps
                            q.append( (neighbor, current, next_steps) )
                        # Check if neighbor is N (destination)
                        if neighbor == N:
                            c = next_steps
                            if (Z - m) >= 0 and (Z - m) % c == 0:
                                possible = True
                                found_inner = True
                                break
                if found_inner:
                    break
            if possible:
                break
        print("yes" if possible else "no")

