def parse_row(s):
    row = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isdigit():
            num = 0
            while i < n and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            row.extend(['.'] * num)
        else:
            row.append('b')
            i += 1
    return row

def encode_row(row):
    parts = []
    current = 0
    for cell in row:
        if cell == '.':
            current += 1
        else:
            if current > 0:
                parts.append(str(current))
                current = 0
            parts.append('b')
    if current > 0:
        parts.append(str(current))
    return ''.join(parts)

