    while heap:
        d, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        for v, w in adj[u]:
            if not visited[v] and dist[v] > d + w:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))

    min_edge = [(INF, -1)] * (n + 1)
    for node in range(1, n + 1):
        if node != start:
            min_edge[node] = (INF, -1)

