def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    m = int(input[ptr])
    ptr += 1
    q = int(input[ptr])
    ptr += 1

    S = n * m
    blocked = set()

    current_time = 1
    start_r, start_c = 1, 1
    start_idx = (start_r - 1) * m + (start_c - 1)
    dp = [0] * S
    dp[start_idx] = 1

    def build_matrix(blocked_set):
        mat = [[0] * S for _ in range(S)]
        for j in range(S):
            r = (j // m) + 1
            c = (j % m) + 1
            if (r, c) in blocked_set:
                continue
            moves = [(r, c)]
            moves.append((r - 1, c))
            moves.append((r + 1, c))
            moves.append((r, c - 1))
            moves.append((r, c + 1))
            for nr, nc in moves:
                if 1 <= nr <= n and 1 <= nc <= m:
                    ni = (nr - 1) * m + (nc - 1)
                    if (nr, nc) not in blocked_set:
                        mat[ni][j] += 1
        return mat

    def multiply(a, b):
        res = [[0] * S for _ in range(S)]
        for i in range(S):
            for k in range(S):
                if a[i][k] == 0:
                    continue
                for j in range(S):
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
        return res

    def matrix_pow(mat, power):
        result = [[0] * S for _ in range(S)]
        for i in range(S):
            result[i][i] = 1
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    def apply_vector(vec, mat):
        new_vec = [0] * S
        for j in range(S):
            if vec[j] == 0:
                continue
            for i in range(S):
                new_vec[i] = (new_vec[i] + vec[j] * mat[i][j]) % MOD
        return new_vec

    for _ in range(q):
        tpi = int(input[ptr])
        ptr += 1
        xi = int(input[ptr])
        ptr += 1
        yi = int(input[ptr])
        ptr += 1
        ti = int(input[ptr])
        ptr += 1

        delta = ti - current_time
        if delta > 0:
            mat = build_matrix(blocked)
            mat_pow = matrix_pow(mat, delta)
            dp = apply_vector(dp, mat_pow)
            current_time = ti

        if tpi == 1:
            idx = (xi - 1) * m + (yi - 1)
            print(dp[idx] % MOD)
        elif tpi == 2:
            blocked.add((xi, yi))
        elif tpi == 3:
            if (xi, yi) in blocked:
                blocked.remove((xi, yi))

