# Parser to build spans dictionary
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.spans = {}

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        self.pos += 1

    def parse(self):
        self.parse_expression()
        return self.spans

    def parse_expression(self):
        left_val, left_start, left_end = self.parse_term()
        while True:
            current = self.current_token()
            if current and current[0] == '+':
                self.consume()
                right_val, right_start, right_end = self.parse_term()
                combined_val = (left_val + right_val) % MOD
                combined_start = left_start
                combined_end = right_end
                self.spans[(combined_start, combined_end)] = combined_val
                left_val, left_start, left_end = combined_val, combined_start, combined_end
            else:
                break
        return left_val, left_start, left_end

    def parse_term(self):
        left_val, left_start, left_end = self.parse_factor()
        while True:
            current = self.current_token()
            if current and current[0] == '*':
                self.consume()
                right_val, right_start, right_end = self.parse_factor()
                combined_val = (left_val * right_val) % MOD
                combined_start = left_start
                combined_end = right_end
                self.spans[(combined_start, combined_end)] = combined_val
                left_val, left_start, left_end = combined_val, combined_start, combined_end
            else:
                break
        return left_val, left_start, left_end

    def parse_factor(self):
        current = self.current_token()
        if not current:
            return (0, 0, 0)
        if current[0] == '(':
            start_pos = current[1]
            self.consume()
            expr_val, expr_start, expr_end = self.parse_expression()
            closing = self.current_token()
            if closing and closing[0] == ')':
                end_pos = closing[2]
                self.consume()
                self.spans[(start_pos, end_pos)] = expr_val
                return (expr_val, start_pos, end_pos)
            else:
                return (0, 0, 0)
        elif current[0] == 'number':
            s_start, s_end = current[1], current[2]
            length = s_end - s_start + 1
            val = (prefix_num[s_end] - (prefix_num[s_start-1] * pow10[length]) % MOD) % MOD
            self.spans[(s_start, s_end)] = val
            self.consume()
            return (val, s_start, s_end)
        else:
            return (0, 0, 0)

