MOD = 10**9 + 7

def main():
    L, C = map(int, sys.stdin.readline().split())
    constraints = [sys.stdin.readline().split() for _ in range(C)]

    max_pos = 10**15
    len_list = [1] * L  # len_list[i] is the length of A[i+1]
    x_current = L + 1
    while True:
        sum_prev = sum(len_list[-L:])
        if sum_prev > max_pos:
            break
        len_list.append(sum_prev)
        x_current += 1
    x_max = x_current - 1  # Last x where len[x] is computed

    def decompose(x, pos):
        while x > L:
            if x <= x_max:
                start_idx = x - L - 1  # 0-based index for x-L
                end_idx = x - 2        # 0-based index for x-1
                prev_lens = len_list[start_idx : end_idx + 1]
                cum_sum = 0
                found = False
                for i in range(len(prev_lens)):
                    cum_sum += prev_lens[i]
                    if cum_sum >= pos:
                        x = x - L + i  # x-L + i is the correct term
                        pos -= (cum_sum - prev_lens[i])
                        found = True
                        break
                if not found:
                    return None
            else:
                # x > x_max, previous terms are x-L to x-1
                found = False
                for i in range(L):
                    y = x - L + i
                    if y < 1:
                        return None
                    if y <= x_max:
                        current_len = len_list[y - 1]
                        if current_len >= pos:
                            x = y
                            found = True
                            break
                        else:
                            pos -= current_len
                    else:
                        x = y
                        found = True
                        break
                if not found:
                    return None
        if x <= L and pos == 1:
            return x
        else:
            return None

    constraints_dict = defaultdict(set)
    valid = True
    for parts in constraints:
        if not valid:
            break
        n_str, x_str, c = parts
        x = int(x_str)
        n = int(n_str)
        if x < 1 or n < 1:
            valid = False
            break
        if x <= x_max:
            if n > len_list[x-1]:
                valid = False
                break
        else:
            if n > max_pos:
                valid = False
                break
        k = decompose(x, n)
        if k is None or k < 1 or k > L:
            valid = False
            break
        constraints_dict[k].add(c)

    for k in constraints_dict:
        if len(constraints_dict[k]) > 1:
            valid = False
            break

    if not valid:
        print(0)
    else:
        num_constrained = len(constraints_dict)
        ans = pow(62, L - num_constrained, MOD)
        print(ans)

