def multiply(a, b, mod):
    m = len(a)
    bT = list(zip(*b))  # Transpose b to access rows for faster column access
    result = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(m):
            total = 0
            for k in range(m):
                total = (total + a[i][k] * bT[j][k]) % mod
            result[i][j] = total
    return result

def matrix_power(mat, power, mod):
    m = len(mat)
    # Initialize result as identity matrix
    result = [[0] * m for _ in range(m)]
    for i in range(m):
        result[i][i] = 1
    current = mat
    while power > 0:
        if power % 2 == 1:
            result = multiply(result, current, mod)
        current = multiply(current, current, mod)
        power = power // 2
    return result

