    coords = list(map(int, input[2:2+2*n]))
    points = [Point(coords[2*i], coords[2*i+1]) for i in range(n)]
    hull = convex_hull(points)
    min_area = float('inf')
    epsilon = 1e-7

    for i in range(len(hull)):
        a = hull[i]
        b = hull[(i+1)%len(hull)]
        edge = b - a
        outward = Point(edge.y, -edge.x)
        if outward.norm() == 0:
            continue
        outward = outward.normalized()
        e = Point(b.x + outward.x * epsilon, b.y + outward.y * epsilon)
        candidate = hull + [e]
        new_hull = convex_hull(candidate)
        if len(new_hull) != 5:
            continue
        area = polygon_area(new_hull)
        if area < min_area:
            min_area = area

    print("{0:.6f}".format(min_area))

