import math

def sum_proper_divisors(n):
    if n == 1:
        return 0
    total = 1
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            other = n // i
            if other == i:
                total += i
            else:
                total += i + other
    return total

