import itertools

def parse_cipher(s):
    collected_q = []
    nodes, _ = parse_helper(s, 0, collected_q)
    return nodes, collected_q

def parse_helper(s, index, collected_q):
    nodes = []
    while index < len(s):
        if s[index] == '[':
            index += 1
            child_nodes, index = parse_helper(s, index, collected_q)
            nodes.append(('reverse', child_nodes))
        elif s[index] == ']':
            index += 1
            break
        else:
            shift = 0
            while index < len(s) and s[index] in '+-':
                if s[index] == '+':
                    shift += 1
                else:
                    shift -= 1
                index += 1
            if index >= len(s):
                break
            base_char = s[index]
            index += 1
            q_index = None
            if base_char == '?':
                q_index = len(collected_q)
                node = ('letter', shift, base_char, q_index)
                collected_q.append(node)
            else:
                node = ('letter', shift, base_char, None)
            nodes.append(node)
    return nodes, index

def evaluate(nodes, substitution):
    result = []
    for node in nodes:
        if node[0] == 'letter':
            shift, base_char, q_index = node[1], node[2], node[3]
            if base_char == '?':
                c = substitution[q_index]
            else:
                c = base_char
            shifted = (ord(c) - ord('A') + shift) % 26
            if shifted < 0:
                shifted += 26
            shifted_char = chr(ord('A') + shifted)
            result.append(shifted_char)
        elif node[0] == 'reverse':
            child_str = evaluate(node[1], substitution)
            result.append(child_str[::-1])
    return ''.join(result)

def main():
    import sys
    for line in sys.stdin:
        line = line.strip()
        if line == '.':
            break
        nodes, collected_q = parse_cipher(line)
        if not collected_q:
            decoded = evaluate(nodes, ())
            print(decoded)
        else:
            min_str = None
            k = len(collected_q)
            for subs in itertools.product('ABCDEFGHIJKLMNOPQRSTUVWXYZ', repeat=k):
                current_subs = subs
                decoded = evaluate(nodes, current_subs)
                if min_str is None or decoded < min_str:
                    min_str = decoded
            print(min_str)

