def main():
    n, m, q = map(int, stdin.readline().split())
    p = list(map(int, stdin.readline().split()))
    edges = []
    for _ in range(m):
        a, b = map(int, stdin.readline().split())
        edges.append((a, b))

    queries = []
    deleted = [False] * m
    for _ in range(q):
        parts = stdin.readline().split()
        if parts[0] == '1':
            v = int(parts[1])
            queries.append((1, v))
        else:
            i = int(parts[1]) - 1  # edge indices are 0-based
            queries.append((2, i))
            deleted[i] = True

    original_p = p.copy()
    current_p = p.copy()
    restore = []

    parent = list(range(n + 1))
    max_val = [0] * (n + 1)
    for i in range(n):
        max_val[i + 1] = current_p[i]

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if max_val[u_root] > max_val[v_root]:
            parent[v_root] = u_root
        else:
            parent[u_root] = v_root

    for i in range(m):
        if not deleted[i]:
            a, b = edges[i]
            union(a, b)

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            edge_idx = query[1]
            a, b = edges[edge_idx]
            union(a, b)
        else:
            v = query[1]
            root = find(v)
            max_u = max_val[root]
            answers.append(max_u)
            if max_u != 0:
                for i in range(1, n + 1):
                    if find(i) == root and original_p[i-1] == max_u:
                        current_p[i-1] = max_u
                        max_val[find(i)] = 0
                        parent[i] = i
                        new_root = i
                        for neighbor in [edges[e][0] for e in range(m) if not deleted[e] and (edges[e][0] == i or edges[e][1] == i)] + [edges[e][1] for e in range(m) if not deleted[e] and (edges[e][0] == i or edges[e][1] == i)]:
                            if find(neighbor) != new_root:
                                union(new_root, neighbor)
                        break

    for ans in reversed(answers):
        print(ans)

