import sys
from struct import unpack

def main():
    data = sys.stdin.buffer.read()
    ptr = 0
    parent = {}
    rank = {}

    def find(x):
        if x not in parent:
            parent[x] = x
            rank[x] = 0
            return x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1

    while ptr < len(data):
        if ptr >= len(data):
            break
        op = data[ptr]
        ptr += 1
        if op == 0:
            if ptr + 8 > len(data):
                break
            x, y = unpack('<II', data[ptr:ptr+8])
            ptr += 8
            union(x, y)
        elif op == 1:
            if ptr + 4 > len(data):
                break
            x, = unpack('<I', data[ptr:ptr+4])
            ptr += 4
            root = find(x)
            print(root)
        else:
            continue

