import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    h = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n)]
    in_degree = [0] * n
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        in_degree[v] += 1

    # Compute topological order using Kahn's algorithm
    q = deque()
    for i in range(n):
        if in_degree[i] == 0:
            q.append(i)
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Process nodes in topological order
    modified = h.copy()
    count = 0
    for u in topo:
        if modified[u] > 0:
            count += 1
            for v in adj[u]:
                modified[v] = 0

    if count % 2 == 1:
        print("WIN")
        print(' '.join(map(str, modified)))
    else:
        print("LOSE")

