import sys
from math import gcd
from collections import defaultdict

MOD = 10**9 + 7

def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    return factors

def extended_gcd(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, x, y = extended_gcd(b, a % b)
        return (g, y, x - (a // b) * y)

def crt(equations):
    x, mod = 0, 1
    for m, r in equations:
        d = gcd(mod, m)
        if (r - x) % d != 0:
            return (None, None)
        g, p, q = extended_gcd(mod, m)
        lcm = mod // d * m
        tmp = ((r - x) // d * p) % (m // d)
        x += mod * tmp
        mod = lcm
        x %= mod
    return (x, mod)

def main():
    n = int(sys.stdin.readline())
    a_list = []
    all_a_factors = []
    all_b_factors = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())
        a_factors = factorize(a)
        b_factors = factorize(b)
        all_a_factors.append(a_factors)
        all_b_factors.append(b_factors)
        a_list.append((a_factors, b_factors))

    lcm_factors = defaultdict(int)
    for af in all_a_factors:
        for p, exp in af.items():
            if exp > lcm_factors[p]:
                lcm_factors[p] = exp

    for i in range(n):
        af, bf = a_list[i]
        c_factors = {}
        for p in lcm_factors:
            exp_in_a = af.get(p, 0)
            exp_in_c = lcm_factors[p] - exp_in_a
            if exp_in_c > 0:
                c_factors[p] = exp_in_c
        for p in c_factors:
            if p not in bf:
                print(-1)
                return

    p_info = defaultdict(list)
    for i in range(n):
        af, bf = a_list[i]
        c_factors = {}
        for p in lcm_factors:
            exp_in_a = af.get(p, 0)
            exp_in_c = lcm_factors[p] - exp_in_a
            if exp_in_c > 0:
                c_factors[p] = exp_in_c
        for p, e in c_factors.items():
            f = bf[p]
            p_info[p].append((f, e))

    m_p = {}
    for p in p_info:
        equations = []
        max_min = 0
        for f, e in p_info[p]:
            r = (-e) % f
            equations.append((f, r))
            current_min = ((e + f - 1) // f) * f - e
            if current_min > max_min:
                max_min = current_min
        x, mod = crt(equations)
        if x is None:
            print(-1)
            return
        if x >= max_min:
            mp = x
        else:
            delta = max_min - x
            k = (delta + mod - 1) // mod
            mp = x + k * mod
        m_p[p] = mp

    result = 1
    for p in lcm_factors:
        exp = lcm_factors[p] + m_p.get(p, 0)
        result = (result * pow(p, exp, MOD)) % MOD
    print(result)

