def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    M = int(input[idx])
    idx += 1
    N = int(input[idx])
    idx +=1

    initial = []
    for _ in range(M):
        row = list(map(int, input[idx:idx+N]))
        idx +=N
        num = 0
        for bit in row:
            num = (num << 1) | bit
        initial.append(num)
    initial_state = tuple(initial)

    def has_2x2(state):
        for i in range(M-1):
            for j in range(N-1):
                mask_j = (1 << (N-1 - j)) | (1 << (N-1 - (j+1)))
                row1 = state[i]
                row2 = state[i+1]
                if (row1 & mask_j) == mask_j and (row2 & mask_j) == mask_j:
                    return True
        return False

    if has_2x2(initial_state):
        print(0)
        return

    moves = []
    for i1 in range(M):
        for i2 in range(i1, M):
            for j1 in range(N):
                for j2 in range(j1, N):
                    L = i2 - i1 +1
                    B = j2 - j1 +1
                    if max(L, B) >1:
                        mask = (1 << (N - j1)) - (1 << (N - j2 -1))
                        moves.append( (i1, i2, j1, j2, mask) )

    visited = set([initial_state])
    q = deque([(initial_state, 0)])

    while q:
        state, steps = q.popleft()
        for i1, i2, j1, j2, mask in moves:
            new_rows = list(state)
            for row_idx in range(i1, i2+1):
                new_rows[row_idx] ^= mask
            new_state = tuple(new_rows)
            if new_state not in visited:
                if has_2x2(new_state):
                    print(steps +1)
                    return
                visited.add(new_state)
                q.append( (new_state, steps +1) )

    print(-1)

