from collections import defaultdict

def subtract_one(s):
    if s == '0':
        return '0'
    digits = list(s)
    i = len(digits) - 1
    while i >= 0 and digits[i] == '0':
        digits[i] = '9'
        i -= 1
    if i == -1:
        return '0'
    digits[i] = str(int(digits[i]) - 1)
    if digits[0] == '0':
        first_non_zero = next((idx for idx, d in enumerate(digits) if d != '0'), None)
        if first_non_zero is None:
            return '0'
        digits = digits[first_non_zero:]
    return ''.join(digits)

def count(x_str, M):
    if M == 0:
        return 0
    digits = list(map(int, x_str))
    n = len(digits)
    dp = [defaultdict(int) for _ in range(n + 1)]
    initial_state = (0, -1, 0, True, False)
    dp[0][initial_state] = 1

    for i in range(n):
        current_dp = dp[i]
        if not current_dp:
            continue
        for state, cnt in current_dp.items():
            current_mod, last_digit, prev_dir, is_tight, started = state
            max_digit = digits[i] if is_tight else 9
            for d in range(0, max_digit + 1):
                new_is_tight = is_tight and (d == max_digit)
                new_mod = (current_mod * 10 + d) % M
                if started:
                    new_started = True
                    new_last_digit = d
                else:
                    if d == 0:
                        new_started = False
                        new_last_digit = -1
                    else:
                        new_started = True
                        new_last_digit = d
                new_prev_dir = prev_dir
                valid = True

                if new_started:
                    if started:
                        if last_digit == d:
                            valid = False
                        else:
                            current_dir = 1 if d > last_digit else 2
                            if prev_dir == 0:
                                new_prev_dir = current_dir
                            else:
                                if (prev_dir == 1 and current_dir != 2) or (prev_dir == 2 and current_dir != 1):
                                    valid = False
                                else:
                                    new_prev_dir = current_dir
                    else:
                        new_prev_dir = 0

                if not valid:
                    continue

                new_state = (new_mod, new_last_digit, new_prev_dir, new_is_tight, new_started)
                dp[i + 1][new_state] = (dp[i + 1][new_state] + cnt) % 10000

    total = 0
    for state in dp[n]:
        mod, ld, pd, it, started = state
        if started and mod == 0:
            total = (total + dp[n][state]) % 10000
    return total

