import sys

def get_covered_positions(r, c):
    return {r * 4 + c, r * 4 + c + 1, (r + 1) * 4 + c, (r + 1) * 4 + c + 1}

def find_cloud_position(schedule):
    zeros = [i for i, val in enumerate(schedule) if val == 0]
    if len(zeros) != 4:
        return None
    for r in range(3):
        for c in range(3):
            covered = get_covered_positions(r, c)
            if set(zeros) == covered:
                return (r, c)
    return None

def is_valid_move(r_prev, c_prev, r_curr, c_curr):
    if r_curr < 0 or r_curr > 2 or c_curr < 0 or c_curr > 2:
        return False
    delta_r = r_curr - r_prev
    delta_c = c_curr - c_prev
    if delta_r == 0 and delta_c == 0:
        return True
    if delta_r != 0 and delta_c != 0:
        return False
    steps = abs(delta_r) if delta_r != 0 else abs(delta_c)
    return steps in (1, 2)

