    prefix = [0]
    for num in l:
        prefix.append(prefix[-1] + num)
    if prefix[-1] != 31:
        return False
    for a1 in range(1, len(prefix)):
        if prefix[a1] == 5:
            for a2 in range(a1, len(prefix)):
                if prefix[a2] - prefix[a1] == 7:
                    for a3 in range(a2, len(prefix)):
                        if prefix[a3] - prefix[a2] == 5:
                            for a4 in range(a3, len(prefix)):
                                if prefix[a4] - prefix[a3] == 7:
                                    if prefix[-1] - prefix[a4] == 7:
                                        return True
    return False

def find_start(words):
    n = len(words)
    for i in range(n):
        for j in range(i, n):
            sub = words[i:j+1]
            total = sum(len(w) for w in sub)
            if total != 31:
                continue
            lengths = [len(w) for w in sub]
            if is_valid_subarray(lengths):
                return i + 1
    return -1

