def compute_cumulative(A, op):
    if op == 'AND':
        cum = A[0]
        for num in A[1:]:
            cum &= num
    elif op == 'OR':
        cum = A[0]
        for num in A[1:]:
            cum |= num
    elif op == 'XOR':
        cum = A[0]
        for num in A[1:]:
            cum ^= num
    return cum

