    n, m, k = map(int, lines[ptr].split())
    ptr += 1

    grid = {}

    sections = [
        (m, k, lambda y, z: [(x, y, z) for x in range(1, n+1)]),
        (m, k, lambda y, z: [(x, y, z) for x in range(n, 0, -1)]),
        (n, k, lambda x, z: [(x, y, z) for y in range(1, m+1)]),
        (n, k, lambda x, z: [(x, y, z) for y in range(m, 0, -1)]),
        (n, m, lambda x, y: [(x, y, z) for z in range(1, k+1)]),
        (n, m, lambda x, y: [(x, y, z) for z in range(k, 0, -1)]),
    ]

    for sec_idx in range(6):
        num_lines, num_per_line, path_func = sections[sec_idx]
        data = []
        for _ in range(num_lines):
            if ptr >= len(lines):
                print(-1)
                return
            row = list(map(int, lines[ptr].split()))
            if len(row) != num_per_line:
                print(-1)
                return
            data.append(row)
            ptr += 1

        if sec_idx in [0, 1]:
            for y in range(1, num_lines + 1):
                row = data[y - 1]
                for z in range(1, len(row) + 1):
                    S = row[z - 1]
                    path = path_func(y, z)
                    if not process_sensor(S, path, grid):
                        print(-1)
                        return
        elif sec_idx in [2, 3]:
            for x in range(1, num_lines + 1):
                row = data[x - 1]
                for z in range(1, len(row) + 1):
                    S = row[z - 1]
                    path = path_func(x, z)
                    if not process_sensor(S, path, grid):
                        print(-1)
                        return
        elif sec_idx in [4, 5]:
            for x in range(1, num_lines + 1):
                row = data[x - 1]
                for y in range(1, len(row) + 1):
                    S = row[y - 1]
                    path = path_func(x, y)
                    if not process_sensor(S, path, grid):
                        print(-1)
                        return

    output = []
    for x in range(1, n + 1):
        for y in range(1, m + 1):
            line = []
            for z in range(1, k + 1):
                line.append(str(grid.get((x, y, z), 0)))
            output.append(' '.join(line))
    print('\n'.join(output))

def process_sensor(S, path, grid):
    if S == 0:
        for cell in path:
            if grid.get(cell, 0) != 0:
                return False
        return True
    else:
        hit_pos = None
        for i, cell in enumerate(path):
            current_val = grid.get(cell, 0)
            if current_val != 0:
                if current_val != S:
                    return False
                else:
                    for j in range(i):
                        if grid.get(path[j], 0) != 0:
                            return False
                    hit_pos = i
                    break
            else:
                all_zero = True
                for j in range(i):
                    if grid.get(path[j], 0) != 0:
                        all_zero = False
                        break
                if all_zero:
                    grid[cell] = S
                    hit_pos = i
                    break
        if hit_pos is None:
            first_cell = path[0]
            if grid.get(first_cell, 0) != 0:
                return False
            grid[first_cell] = S
        return True

