import bisect

def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n = int(input[ptr])
        ptr +=1
        tags = list(map(int, input[ptr:ptr+n]))
        ptr +=n
        s = list(map(int, input[ptr:ptr+n]))
        ptr +=n

        c = [0] * (n + 1)
        for i in range(1, n+1):
            c[i] = 1 << i  # 2^i

        dp = [[] for _ in range(n+1)]  # dp[0] unused, 1-based
        for i in range(1, n+1):
            dp[i].append((0, 0))  # initial state

        for i in range(1, n+1):
            for j in range(1, n+1):
                if i == j or tags[i-1] == tags[j-1]:
                    continue
                d_ij = abs(c[i] - c[j])
                to_add = []
                # Iterate through all (iq, score) pairs in dp[i]
                for current_iq, current_score in dp[i]:
                    if current_iq < d_ij:
                        new_iq = d_ij
                        new_score = current_score + abs(s[i-1] - s[j-1])
                        to_add.append((new_iq, new_score))
                # Process all new entries for j
                for new_iq, new_score in to_add:
                    current_list = dp[j]
                    iqs = [pair[0] for pair in current_list]
                    idx = bisect.bisect_left(iqs, new_iq)
                    # Check for existing pairs that dominate new
                    found = False
                    for k in range(idx, len(current_list)):
                        if current_list[k][1] >= new_score:
                            found = True
                            break
                    if found:
                        continue
                    # Remove dominated entries
                    new_list = []
                    for (eiq, escore) in current_list:
                        if eiq <= new_iq:
                            if escore > new_score:
                                new_list.append((eiq, escore))
                        else:
                            new_list.append((eiq, escore))
                    new_list.append((new_iq, new_score))
                    new_list.sort()
                    dp[j] = new_list

        max_score = 0
        for j in range(1, n+1):
            for (iq, score) in dp[j]:
                if score > max_score:
                    max_score = score
        print(max_score)

