def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def factor(n):
    factors = []
    count = 0
    while n % 2 == 0:
        count += 1
        n = n // 2
    if count > 0:
        factors.append((2, count))
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n = n // i
        if count > 0:
            factors.append((i, count))
        i += 2
    if n > 1:
        factors.append((n, 1))
    return factors

