import heapq

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx]); idx +=1
    m = int(data[idx]); idx +=1
    L = int(data[idx]); idx +=1
    s = int(data[idx]); idx +=1
    t = int(data[idx]); idx +=1

    edges = []
    variable_edges_set = set()

    for _ in range(m):
        u = int(data[idx]); idx +=1
        v = int(data[idx]); idx +=1
        w = int(data[idx]); idx +=1
        edges.append((u, v, w))
        if w == 0:
            a, b = sorted((u, v))
            variable_edges_set.add((a, b))

    # Step 1: Compute S (shortest path in fixed-only graph)
    fixed_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if w > 0:
            fixed_adj[u].append((v, w))
            fixed_adj[v].append((u, w))

    # Dijkstra for fixed graph
    def dijkstra_fixed():
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == t:
                return d
            if d > dist[u]:
                continue
            for v, w in fixed_adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')  # no path

    S = dijkstra_fixed()
    if S < L:
        print("NO")
        return

    # Step 2: Compute D (shortest path with variables as 1)
    combined_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if w == 0:
            combined_adj[u].append((v, 1, u, v, w))
            combined_adj[v].append((u, 1, v, u, w))
        else:
            combined_adj[u].append((v, w, u, v, w))
            combined_adj[v].append((u, w, v, u, w))

    # Dijkstra for combined graph with path tracking
    prev = [None] * n
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s, -1, -1, -1)]
    while heap:
        d, u, orig_u, orig_v, orig_w = heapq.heappop(heap)
        if u == t:
            break
        if d > dist[u]:
            continue
        for edge in combined_adj[u]:
            v, current_w, ou, ov, ow = edge
            if dist[v] > d + current_w:
                dist[v] = d + current_w
                prev[v] = (ou, ov, ow)
                heapq.heappush(heap, (dist[v], v, ou, ov, ow))

    D = dist[t]
    if D > L:
        print("NO")
        return
    if D == L:
        print("YES")
        for u, v, w in edges:
            print(u, v, w if w != 0 else 1)
        return

    # Reconstruct path
    path_edges = []
    current = t
    while current != s:
        if prev[current] is None:
            print("NO")
            return
        ou, ov, ow = prev[current]
        path_edges.append((ou, ov, ow))
        current = ou

    variables_in_path = []
    for ou, ov, ow in path_edges:
        if ow == 0:
            a, b = sorted((ou, ov))
            variables_in_path.append((a, b))

    if not variables_in_path:
        print("NO")
        return

    sum_required = L - D

    # Prepare the output
    print("YES")
    first_var = variables_in_path[0]

    for edge in edges:
        u, v, w = edge
        if w == 0:
            a, b = sorted((u, v))
            if (a, b) in variable_edges_set and (a, b) in variables_in_path:
                if (a, b) == first_var:
                    print(u, v, 1 + sum_required)
                else:
                    print(u, v, 1)
            else:
                print(u, v, 10**18)
        else:
            print(u, v, w)

