from functools import lru_cache

def solve():
    N = input().strip()
    K = int(input())
    digits = list(map(int, N))

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zero):
        if pos == len(digits):
            return 1 if (count == K and not leading_zero) else 0
        res = 0
        max_d = digits[pos] if tight else 9
        for d in range(0, max_d + 1):
            new_tight = tight and (d == max_d)
            new_leading_zero = leading_zero and (d == 0)
            if new_leading_zero:
                new_count = count
            else:
                new_count = count + (d != 0)
            if new_count > K:
                continue
            res += dp(pos + 1, new_count, new_tight, new_leading_zero)
        return res

    print(dp(0, 0, True, True))

