import sys
from collections import deque
from itertools import product

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        w, h, n = map(int, line.strip().split())
        if w == 0 and h == 0 and n == 0:
            break
        grid = []
        for _ in range(h):
            row = sys.stdin.readline().rstrip('\n')  # Read the entire line and strip newline
            grid.append(row[:w])  # Ensure we take exactly w characters

        # Collect initial and target positions
        initial = []
        target = []
        for y in range(h):
            for x in range(w):
                c = grid[y][x]
                if c == '#':
                    continue
                if c.islower():
                    idx = ord(c) - ord('a')
                    if idx < n:
                        if len(initial) <= idx:
                            initial.extend([None] * (idx - len(initial) + 1))
                        initial[idx] = (x, y)
                elif c.isupper():
                    idx = ord(c) - ord('A')
                    if idx < n:
                        if len(target) <= idx:
                            target.extend([None] * (idx - len(target) + 1))
                        target[idx] = (x, y)
        initial_state = tuple(initial)
        target_state = tuple(target)

        # Precompute possible moves for each cell
        move_map = {}
        for y in range(h):
            for x in range(w):
                if grid[y][x] == '#':
                    continue
                moves = [(x, y)]  # Staying is allowed
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx = x + dx
                    ny = y + dy
                    if 0 <= nx < w and 0 <= ny < h and grid[ny][nx] != '#':
                        moves.append((nx, ny))
                move_map[(x, y)] = moves

        # BFS setup
        visited = set()
        queue = deque()
        queue.append((initial_state, 0))
        visited.add(initial_state)
        answer = -1

        while queue:
            current_state, steps = queue.popleft()
            if current_state == target_state:
                answer = steps
                break

            # Generate all possible next moves
            possible_moves = [move_map[pos] for pos in current_state]
            for moves in product(*possible_moves):
                # Check all positions are unique
                if len(set(moves)) != n:
                    continue
                # Check for swaps
                swap = False
                for i in range(n):
                    for j in range(i + 1, n):
                        if moves[i] == current_state[j] and moves[j] == current_state[i]:
                            swap = True
                            break
                    if swap:
                        break
                if swap:
                    continue
                # Check if new state is visited
                new_state = tuple(moves)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, steps + 1))

        print(answer)

if __name__ == "__main__":
    main()

import sys
from copy import deepcopy

def parse_sequence(s):
    stack = []
    current = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '(':
            stack.append(current)
            current = []
            i += 1
        elif c == ')':
            i += 1
            k_str = ''
            while i < n and s[i].isdigit():
                k_str += s[i]
                i += 1
            k = int(k_str) if k_str else 0
            parent = stack.pop()
            parent.append((current, k))
            current = parent
        elif c in 'UDLR':
            current.append(c)
            i += 1
        else:
            i += 1
    return current

def tilt_left(board):
    n = len(board)
    for i in range(n):
        row = board[i]
        new_row = ['.'] * n
        pos = 0
        for c in row:
            if c != '.':
                new_row[pos] = c
                pos += 1
        board[i] = new_row

def tilt_right(board):
    n = len(board)
    for i in range(n):
        row = board[i]
        new_row = ['.'] * n
        pos = n - 1
        for c in reversed(row):
            if c != '.':
                new_row[pos] = c
                pos -= 1
        board[i] = new_row

def tilt_up(board):
    n = len(board)
    transposed = [list(row) for row in zip(*board)]
    tilt_left(transposed)
    new_board = list(zip(*transposed))
    for i in range(n):
        board[i] = list(new_board[i])

def tilt_down(board):
    n = len(board)
    transposed = [list(row) for row in zip(*board)]
    tilt_right(transposed)
    new_board = list(zip(*transposed))
    for i in range(n):
        board[i] = list(new_board[i])

def copy_board(board):
    return [row.copy() for row in board]

def boards_equal(b1, b2):
    for r1, r2 in zip(b1, b2):
        if r1 != r2:
            return False
    return True

def assign_board(dest, src):
    for i in range(len(dest)):
        dest[i][:] = src[i]

def apply_repetition(board, sub_seq, k):
    if k == 0:
        return
    original = copy_board(board)
    process_parsed(board, sub_seq)
    if k == 1:
        return
    if boards_equal(original, board):
        return
    after_first = copy_board(board)
    process_parsed(board, sub_seq)
    if boards_equal(after_first, board):
        if k % 2 == 0:
            assign_board(board, original)
        else:
            assign_board(board, after_first)
        return
    after_second = copy_board(board)
    process_parsed(board, sub_seq)
    if boards_equal(after_second, board):
        remaining = k - 2
        if remaining <= 0:
            return
        cycle = 2
        remaining %= cycle
        if remaining:
            process_parsed(board, sub_seq)
        return
    for _ in range(k-2):
        process_parsed(board, sub_seq)

def process_parsed(board, parsed):
    for element in parsed:
        if isinstance(element, tuple):
            sub_seq, k = element
            apply_repetition(board, sub_seq, k)
        else:
            dir = element
            if dir == 'L':
                tilt_left(board)
            elif dir == 'R':
                tilt_right(board)
            elif dir == 'U':
                tilt_up(board)
            elif dir == 'D':
                tilt_down(board)

