import sys

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = list(map(int, line.split()))
        if len(parts) < 3:
            continue
        N, M, L = parts
        if N == 0 and M == 0 and L == 0:
            break
        data = list(map(float, sys.stdin.readline().split()))
        N_data = len(data)
        if N_data == 0:
            print("0.000000")
            continue

        # Precompute error for all possible segments
        error = [[0.0 for _ in range(N_data)] for _ in range(N_data)]
        for start in range(N_data):
            for end in range(start + 1, N_data):
                sub = data[start:end+1]
                vmin = min(sub)
                vmax = max(sub)
                if vmin == vmax:
                    e = sum((x - vmin)**2 for x in sub)
                else:
                    delta = (vmax - vmin) / (2 * L - 1)
                    total = 0.0
                    for x in sub:
                        t = (x - vmin) / delta
                        i = round(t)
                        if i < 0:
                            i = 0
                        elif i >= 2 * L:
                            i = 2 * L - 1
                        q = vmin + i * delta
                        total += (x - q)**2
                    e = total
                error[start][end] = e

        # Dynamic programming setup
        INF = float('inf')
        dp = [[INF] * (N_data + 1) for _ in range(M + 1)]
        dp[0][0] = 0.0

        for m in range(1, M + 1):
            max_end = N_data
            for end in range(2 * m, max_end + 1):
                min_j = 2 * (m - 1)
                max_j = end - 2
                if min_j > max_j:
                    continue
                for j in range(min_j, max_j + 1):
                    if dp[m-1][j] < INF:
                        current_error = error[j][end-1]
                        if dp[m][end] > dp[m-1][j] + current_error:
                            dp[m][end] = dp[m-1][j] + current_error

        result = dp[M][N_data]
        print("{0:.6f}".format(result))

