import sys

def minimal_changes(s):
    n = len(s)
    if n == 0:
        return 0
    INF = float('inf')
    current = [[INF]*26 for _ in range(27)]  # prev_prev: 26 represents None
    for c in range(26):
        cost = 0 if (chr(c + ord('a')) == s[0]) else 1
        current[26][c] = cost

    for i in range(1, n):
        next_dp = [[INF]*26 for _ in range(27)]
        for prev_prev in range(27):
            for prev_char in range(26):
                if current[prev_prev][prev_char] == INF:
                    continue
                if prev_prev == 26:
                    allowed = [cc for cc in range(26) if cc != prev_char]
                else:
                    allowed = [cc for cc in range(26) if cc != prev_char and cc != prev_prev]
                for cc in allowed:
                    cost = current[prev_prev][prev_char] + (0 if (chr(cc + ord('a')) == s[i]) else 1)
                    if next_dp[prev_char][cc] > cost:
                        next_dp[prev_char][cc] = cost
        current = [[INF]*26 for _ in range(26)]
        for new_pp in range(26):
            for new_p in range(26):
                current[new_pp][new_p] = next_dp[new_pp][new_p]

    min_cost = INF
    for pp in range(26):
        for p in range(26):
            if current[pp][p] < min_cost:
                min_cost = current[pp][p]
    return min_cost

