import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def get_divisors(c):
    divisors = set()
    for i in range(1, int(math.isqrt(c)) + 1):
        if c % i == 0:
            divisors.add(i)
            divisors.add(c // i)
    return sorted(divisors, reverse=True)

def is_sum_term(s):
    if s == 1:
        return (True, 0, 0)
    # Check for k=2
    p_k2 = s - 1
    if p_k2 >= 2 and is_prime(p_k2):
        return (True, p_k2, 2)
    # Check for k >=3
    max_k = int(math.log(s * (s) + 1, 2))  # Approximate upper bound for k
    for k in range(3, max_k + 1):
        low = 2
        high = s - 1
        while low <= high:
            mid = (low + high) // 2
            val = (mid ** k - 1) // (mid - 1) if mid != 1 else 1
            if val == s:
                if is_prime(mid):
                    return (True, mid, k)
                else:
                    break
            elif val < s:
                low = mid + 1
            else:
                high = mid - 1
    return (False, 0, 0)

def find_min_n(c):
    if c == 1:
        return 1
    divisors = get_divisors(c)
    min_n = float('inf')

    def backtrack(remaining, current_n, last_p):
        nonlocal min_n
        if remaining == 1:
            if current_n < min_n:
                min_n = current_n
            return
        for s in get_divisors(remaining):
            if s == 1:
                continue
            valid, p, k = is_sum_term(s)
            if not valid or p <= last_p:
                continue
            if not is_prime(p):
                continue
            exponent = k - 1
            backtrack(remaining // s, current_n * (p ** exponent), p)

    for s in divisors:
        valid, p, k = is_sum_term(s)
        if not valid or not is_prime(p):
            continue
        exponent = k - 1
        backtrack(c // s, p ** exponent, p)

    return min_n if min_n != float('inf') else -1

