import sys
from collections import deque

def main():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for i in range(n):
        parts = list(map(int, sys.stdin.readline().split()))
        ci = parts[0]
        adj[i+1] = parts[1:] if ci > 0 else []
    s = int(sys.stdin.readline())

    # Check if a node is a sink
    sinks = [False] * (n + 1)
    for i in range(1, n + 1):
        if len(adj[i]) == 0:
            sinks[i] = True

    # BFS for Win condition
    visited0 = [False] * (n + 1)
    visited1 = [False] * (n + 1)
    parent = {}
    queue = deque()
    start = (s, 0)
    visited0[s] = True
    queue.append(start)
    found = False
    end_state = None

    while queue:
        v, p = queue.popleft()
        if p == 1 and sinks[v]:
            end_state = (v, p)
            found = True
            break
        next_p = 1 - p
        for u in adj[v]:
            if next_p == 0 and not visited0[u]:
                visited0[u] = True
                parent[(u, next_p)] = (v, p)
                queue.append((u, next_p))
            elif next_p == 1 and not visited1[u]:
                visited1[u] = True
                parent[(u, next_p)] = (v, p)
                queue.append((u, next_p))

    if found:
        # Reconstruct path
        path = []
        current = end_state
        while current is not None:
            path.append(current[0])
            current = parent.get(current)
        path = path[::-1]
        print("Win")
        print(' '.join(map(str, path)))
        return

    # Check if any node is visited in both parities
    draw = False
    for i in range(1, n+1):
        if visited0[i] and visited1[i]:
            draw = True
            break

    if not draw:
        # Find all reachable nodes from s
        reachable = [False] * (n + 1)
        q = deque()
        q.append(s)
        reachable[s] = True
        while q:
            v = q.popleft()
            for u in adj[v]:
                if not reachable[u]:
                    reachable[u] = True
                    q.append(u)
        reachable_nodes = [i for i in range(1, n+1) if reachable[i]]

        # Check for cycle using Kahn's algorithm
        in_degree = {i: 0 for i in reachable_nodes}
        for v in reachable_nodes:
            for u in adj[v]:
                if u in in_degree:
                    in_degree[u] += 1
        queue_kahn = deque()
        for v in reachable_nodes:
            if in_degree[v] == 0:
                queue_kahn.append(v)
        cnt = 0
        while queue_kahn:
            v = queue_kahn.popleft()
            cnt += 1
            for u in adj[v]:
                if u in in_degree:
                    in_degree[u] -= 1
                    if in_degree[u] == 0:
                        queue_kahn.append(u)
        if cnt != len(reachable_nodes):
            draw = True

    if draw:
        print("Draw")
    else:
        print("Lose")

