from sys import stdin

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    edges = []
    for idx in range(1, m + 1):
        u, v = map(int, stdin.readline().split())
        adj[u].append((v, idx))
        adj[v].append((u, idx))
        edges.append((u, v))

    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    edge_stack = []
    components = []
    time_counter = [1]

    for u in range(1, n + 1):
        if not visited[u]:
            stack = []
            parent = {}
            parent[u] = -1
            disc[u] = low[u] = time_counter[0]
            time_counter[0] += 1
            stack.append((u, iter(adj[u])))
            visited[u] = True
            while stack:
                node, neighbors = stack[-1]
                try:
                    v, idx = next(neighbors)
                    if v == parent.get(node, -1):
                        continue
                    if not visited[v]:
                        parent[v] = node
                        disc[v] = low[v] = time_counter[0]
                        time_counter[0] += 1
                        visited[v] = True
                        edge_stack.append((node, v, idx))
                        stack.append((v, iter(adj[v])))
                    else:
                        if disc[v] < disc[node]:
                            edge_stack.append((node, v, idx))
                            low[node] = min(low[node], disc[v])
                except StopIteration:
                    stack.pop()
                    if stack:
                        p = stack[-1][0]
                        low[p] = min(low[p], low[node])
                        if low[node] >= disc[p]:
                            component = []
                            while True:
                                edge = edge_stack.pop()
                                component.append(edge)
                                if (edge[0] == p and edge[1] == node) or (edge[0] == node and edge[1] == p):
                                    break
                            components.append(component)
                    else:
                        if edge_stack:
                            component = list(edge_stack)
                            edge_stack.clear()
                            components.append(component)

    answer = set()
    for comp in components:
        if len(comp) == 1:
            continue
        nodes = set()
        for edge in comp:
            nodes.add(edge[0])
            nodes.add(edge[1])
        if len(comp) == len(nodes):
            for edge in comp:
                answer.add(edge[2])

    sorted_answer = sorted(answer)
    print(len(sorted_answer))
    if sorted_answer:
        print(' '.join(map(str, sorted_answer)))
    else:
        print()

