import sys

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    parent = list(range(N + 1))
    distance = [0] * (N + 1)
    rank = [1] * (N + 1)

    def find(u):
        path = []
        while parent[u] != u:
            path.append(u)
            u = parent[u]
        current_distance = 0
        for v in reversed(path):
            orig_parent = parent[v]
            orig_distance = distance[v]
            parent[v] = u
            distance[v] = orig_distance + current_distance
            current_distance = distance[v]
        return (u, current_distance)

    for _ in range(M):
        L, R, D = map(int, sys.stdin.readline().split())
        rootL, distL = find(L)
        rootR, distR = find(R)
        if rootL == rootR:
            if distR != distL + D:
                print("No")
                return
        else:
            if rank[rootL] >= rank[rootR]:
                parent[rootR] = rootL
                distance[rootR] = distL + D - distR
                if rank[rootL] == rank[rootR]:
                    rank[rootL] += 1
            else:
                parent[rootL] = rootR
                distance[rootL] = distR - D - distL
                if rank[rootL] == rank[rootR]:
                    rank[rootR] += 1

    print("Yes")

