def right_rotate(s):
    return s[-1] + s[:-1] if s else s

def left_rotate(s):
    return s[1:] + s[0] if s else s

def swap_halves(s):
    n = len(s)
    if not n:
        return s
    mid = n // 2
    if n % 2 == 0:
        return s[mid:] + s[:mid]
    else:
        return s[mid+1:] + s[mid] + s[:mid]

