import sys

MOD = 10**9 + 7

def sieve(max_num):
    if max_num < 2:
        return []
    is_prime = [True] * (max_num + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_num**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, max_num + 1, i):
                is_prime[j] = False
    return is_prime

def main():
    input = sys.stdin.read().split()
    if not input:
        print(0)
        return
    N = int(input[0])
    if len(input) != N + 1:
        print(0)
        return
    q_str = input[1:N+1]
    q = []
    try:
        for s in q_str:
            num = int(s)
            if num < 2:
                print(0)
                return
            q.append(num)
    except:
        print(0)
        return

    if not q:
        print(0)
        return
    max_prime_val = max(q)
    is_prime = sieve(max_prime_val)

    dp = [{} for _ in range(N + 2)]
    dp[0][0] = 1

    for i in range(N + 1):
        if not dp[i]:
            continue
        current_dict = dp[i]
        for last_p, cnt in current_dict.items():
            if i < N:
                current_q = q[i]
                if current_q > last_p and is_prime[current_q]:
                    next_p = current_q
                    if next_p in dp[i+1]:
                        dp[i+1][next_p] = (dp[i+1][next_p] + cnt) % MOD
                    else:
                        dp[i+1][next_p] = cnt % MOD
            if i + 1 < N:
                current_q = q[i]
                next_q = q[i+1]
                if current_q > last_p and is_prime[current_q] and next_q >= 2:
                    next_p = current_q
                    if next_p in dp[i+2]:
                        dp[i+2][next_p] = (dp[i+2][next_p] + cnt) % MOD
                    else:
                        dp[i+2][next_p] = cnt % MOD

    total = sum(dp[N].values()) % MOD
    print(total)

