import math

def find_min_max_pair(X):
    if X == 1:
        return (1, 1)

    factors = {}
    x = X
    while x % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        x = x // 2
    i = 3
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 2
    if x > 1:
        factors[x] = 1

    divisors = [1]
    for p, cnt in factors.items():
        current_powers = [p**e for e in range(cnt + 1)]
        new_divisors = []
        for d in divisors:
            for power in current_powers:
                new_divisors.append(d * power)
        divisors = new_divisors

    divisors = sorted(divisors)
    sqrt_x = math.isqrt(X)
    best_d = 0
    best_pair = (1, X)
    for d in divisors:
        if d > sqrt_x:
            continue
        other = X // d
        if math.gcd(d, other) == 1 and d > best_d:
            best_d = d
            best_pair = (d, other)
    return best_pair

