import sys
from collections import deque

sys.setrecursionlimit(1 << 25)

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)
    q = deque([1])
    visited[1] = True
    up[0][1] = 0

    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v] and v != up[0][u]:
                visited[v] = True
                up[0][v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    for k in range(1, LOG):
        for v in range(1, n + 1):
            up[k][v] = up[k-1][up[k-1][v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    def distance(u, v):
        ancestor = lca(u, v)
        return depth[u] + depth[v] - 2 * depth[ancestor]

    q_num = int(sys.stdin.readline())
    for _ in range(q_num):
        x, y, a, b, k = map(int, sys.stdin.readline().split())
        d_ab = distance(a, b)
        if k >= d_ab and (k - d_ab) % 2 == 0:
            print("YES")
            continue

        d_ax = distance(a, x)
        d_ay = distance(a, y)
        d_bx = distance(b, x)
        d_by = distance(b, y)
        new_dist = min(d_ax + 1 + d_by, d_ay + 1 + d_bx)
        d_xy = distance(x, y)
        C = d_xy + 1

        if k >= new_dist and (k - new_dist) % C == 0:
            print("YES")
        else:
            print("NO")

