import sys

def main():
    n = int(sys.stdin.readline())
    intervals = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    class SegmentTreeMin:
        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.min_tree = [float('inf')] * (2 * self.n)
            for i in range(1, size + 1):
                self.min_tree[self.n + i - 1] = i
            for i in range(self.n - 1, 0, -1):
                self.min_tree[i] = min(self.min_tree[2*i], self.min_tree[2*i + 1])

        def update(self, x):
            pos = self.n + x - 1
            self.min_tree[pos] = float('inf')
            pos >>= 1
            while pos >= 1:
                new_val = min(self.min_tree[2*pos], self.min_tree[2*pos + 1])
                if self.min_tree[pos] == new_val:
                    break
                self.min_tree[pos] = new_val
                pos >>= 1

        def query_min(self, a, b):
            res = float('inf')
            a += self.n - 1
            b += self.n - 1
            while a <= b:
                if a % 2 == 1:
                    res = min(res, self.min_tree[a])
                    a += 1
                if b % 2 == 0:
                    res = min(res, self.min_tree[b])
                    b -= 1
                a >>= 1
                b >>= 1
            return res

    class SegmentTreeMax:
        def __init__(self, size):
            self.n = 1
            while self.n < size:
                self.n <<= 1
            self.max_tree = [-float('inf')] * (2 * self.n)
            for i in range(1, size + 1):
                self.max_tree[self.n + i - 1] = i
            for i in range(self.n - 1, 0, -1):
                self.max_tree[i] = max(self.max_tree[2*i], self.max_tree[2*i + 1])

        def update(self, x):
            pos = self.n + x - 1
            self.max_tree[pos] = -float('inf')
            pos >>= 1
            while pos >= 1:
                new_val = max(self.max_tree[2*pos], self.max_tree[2*pos + 1])
                if self.max_tree[pos] == new_val:
                    break
                self.max_tree[pos] = new_val
                pos >>= 1

        def query_max(self, a, b):
            res = -float('inf')
            a += self.n - 1
            b += self.n - 1
            while a <= b:
                if a % 2 == 1:
                    res = max(res, self.max_tree[a])
                    a += 1
                if b % 2 == 0:
                    res = max(res, self.max_tree[b])
                    b -= 1
                a >>= 1
                b >>= 1
            return res

    # Generate minimal permutation
    st_min = SegmentTreeMin(n)
    min_perm = []
    for a, b in intervals:
        x = st_min.query_min(a, b)
        min_perm.append(x)
        st_min.update(x)

    # Generate maximal permutation
    st_max = SegmentTreeMax(n)
    max_perm = []
    for a, b in intervals:
        x = st_max.query_max(a, b)
        max_perm.append(x)
        st_max.update(x)

    if min_perm == max_perm:
        print("YES")
        print(' '.join(map(str, min_perm)))
    else:
        print("NO")
        print(' '.join(map(str, min_perm)))
        print(' '.join(map(str, max_perm)))

