        x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
        if x1 == x2:
            # Vertical cut
            x = x1
            a = min(y1, y2)
            b = max(y1, y2)
            vertical[x].append((a, b))
        elif y1 == y2:
            # Horizontal cut
            y = y1
            a = min(x1, x2)
            b = max(x1, x2)
            horizontal[y].append((a, b))

    # Calculate V_covered
    v_covered = 0
    for x in vertical:
        intervals = vertical[x]
        intervals.sort()
        merged = []
        for a, b in intervals:
            if not merged:
                merged.append([a, b])
            else:
                last_a, last_b = merged[-1]
                if a <= last_b:
                    merged[-1][1] = max(last_b, b)
                else:
                    merged.append([a, b])
        total = sum(b - a for a, b in merged)
        if total == m:
            v_covered += 1

    # Calculate H_covered
    h_covered = 0
    for y in horizontal:
        intervals = horizontal[y]
        intervals.sort()
