import bisect

class SegmentTreeMin:
    def __init__(self, size):
        self.n = 1
        while self.n < size:
            self.n <<= 1
        self.size = size
        self.tree = [float('inf')] * (2 * self.n)

    def update(self, pos, value):
        pos += self.n
        self.tree[pos] = value
        while pos > 1:
            pos >>= 1
            self.tree[pos] = min(self.tree[2*pos], self.tree[2*pos +1])

    def query_range(self, l, r):
        res = float('inf')
        l += self.n
        r += self.n
        while l <= r:
            if l % 2 == 1:
                res = min(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = min(res, self.tree[r])
                r -= 1
            l >>= 1
            r >>= 1
        return res

class SegmentTreeMax:
    def __init__(self, data):
        self.n = 1
        while self.n < len(data):
            self.n <<= 1
        self.size = len(data)
        self.tree = [[] for _ in range(2 * self.n)]
        for i in range(self.size):
            mx, r = data[i]
            self.tree[self.n + i] = [(mx, r)]
            self.precompute_suffix_max(self.n + i)
        for i in range(self.n - 1, 0, -1):
            left = self.tree[2*i]
            right = self.tree[2*i+1]
            merged = []
            ptr_l = 0
            ptr_r = 0
            while ptr_l < len(left) and ptr_r < len(right):
                if left[ptr_l][0] <= right[ptr_r][0]:
                    merged.append(left[ptr_l])
                    ptr_l += 1
                else:
                    merged.append(right[ptr_r])
                    ptr_r += 1
            merged.extend(left[ptr_l:])
            merged.extend(right[ptr_r:])
            self.tree[i] = merged
            self.precompute_suffix_max(i)

    def precompute_suffix_max(self, pos):
        lst = self.tree[pos]
        suffix_max = [0] * len(lst)
        max_so_far = -float('inf')
        for i in range(len(lst)-1, -1, -1):
            if lst[i][1] > max_so_far:
                max_so_far = lst[i][1]
            suffix_max[i] = max_so_far
        self.tree[pos] = (lst, suffix_max)

    def query(self, a, b, x):
        res = -float('inf')
        a += self.n
        b += self.n
        while a <= b:
            if a % 2 == 1:
                if self.tree[a]:
                    lst, sm = self.tree[a]
                    low, high = 0, len(lst)
                    ans = -1
                    while low < high:
                        mid = (low + high) // 2
                        if lst[mid][0] <= x:
                            ans = mid
                            low = mid + 1
                        else:
                            high = mid
                    if ans != -1:
                        res = max(res, sm[ans])
                a += 1
            if b % 2 == 0:
                if self.tree[b]:
                    lst, sm = self.tree[b]
                    low, high = 0, len(lst)
                    ans = -1
                    while low < high:
                        mid = (low + high) // 2
                        if lst[mid][0] <= x:
                            ans = mid
                            low = mid + 1
                        else:
                            high = mid
                    if ans != -1:
                        res = max(res, sm[ans])
                b -= 1
            a >>= 1
            b >>= 1
        return res

