import math

def main():
    max_A = 10**6
    sieve = list(range(max_A + 1))
    for i in range(2, int(math.isqrt(max_A)) + 1):
        if sieve[i] == i:
            for j in range(i*i, max_A + 1, i):
                if sieve[j] == j:
                    sieve[j] = i

    input = sys.stdin.read().split()
    n = int(input[0])
    A = list(map(int, input[1:n+1]))

    current_gcd = 0
    for num in A:
        current_gcd = math.gcd(current_gcd, num)
    if current_gcd != 1:
        print("not coprime")
        return

    seen_primes = set()
    pairwise = True
    for a in A:
        if a == 1:
            continue
        x = a
        primes = set()
        while x != 1:
            p = sieve[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        for p in primes:
            if p in seen_primes:
                pairwise = False
                break
            seen_primes.add(p)
        if not pairwise:
            break

    print("pairwise coprime" if pairwise else "setwise coprime")

