import sys
from collections import deque

def main():
    H, W, K = map(int, sys.stdin.readline().split())
    grid = []
    start = None
    for i in range(H):
        line = sys.stdin.readline().strip()
        grid.append(list(line))
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)

    # Precompute distance from each cell to the nearest exit (Manhattan)
    dist_exit = [[float('inf')] * W for _ in range(H)]
    q = deque()
    for i in range(H):
        for j in range(W):
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                dist_exit[i][j] = 0
                q.append((i, j))

    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        i, j = q.popleft()
        for dx, dy in dirs:
            ni, nj = i + dx, j + dy
            if 0 <= ni < H and 0 <= nj < W:
                if dist_exit[ni][nj] > dist_exit[i][j] + 1:
                    dist_exit[ni][nj] = dist_exit[i][j] + 1
                    q.append((ni, nj))

    # BFS for each cast
    visited = [[False]*W for _ in range(H)]
    q = deque()
    q.append((start[0], start[1]))
    visited[start[0]][start[1]] = True
    cast = 0

    while True:
        # Check if current level has exit
        current_level = []
        for _ in range(len(q)):
            i, j = q.popleft()
            current_level.append((i, j))
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                print(cast + 1)
                return

        # Perform BFS up to K steps
        next_reachable = set()
        temp_visited = [row[:] for row in visited]
        temp_q = deque(current_level)
        for step in range(K):
            if not temp_q:
                break
            for _ in range(len(temp_q)):
                i, j = temp_q.popleft()
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < H and 0 <= nj < W and not temp_visited[ni][nj] and grid[ni][nj] != '#':
                        temp_visited[ni][nj] = True
                        next_reachable.add((ni, nj))
                        temp_q.append((ni, nj))

        # Check exit in next_reachable
        for i, j in next_reachable:
            if i == 0 or i == H-1 or j == 0 or j == W-1:
                print(cast + 1)
                return

        # Collect adjacent walls
        walls = set()
        for i, j in next_reachable:
            for dx, dy in dirs:
                ni, nj = i + dx, j + dy
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                    walls.add((ni, nj))

        # Sort walls by dist_exit and select up to K
        walls = sorted(walls, key=lambda x: dist_exit[x[0]][x[1]])
        walls = walls[:K]

        # Update grid and prepare next level
        q = deque()
        seen = set()
        for i, j in walls:
            grid[i][j] = '.'
        for i, j in next_reachable:
            if (i, j) not in seen:
                seen.add((i, j))
                q.append((i, j))
        for i, j in walls:
            if (i, j) not in seen:
                seen.add((i, j))
                q.append((i, j))

        # Update visited
        for i, j in seen:
            if not visited[i][j]:
                visited[i][j] = True

        cast += 1

