import itertools

def ccw(A, B, C):
    return (B[0]-A[0])*(C[1]-A[1]) - (B[1]-A[1])*(C[0]-A[0])

def segment_intersect(s1, s2):
    A, B = s1[0], s1[1]
    C, D = s2[0], s2[1]
    ccw1 = ccw(A, B, C)
    ccw2 = ccw(A, B, D)
    ccw3 = ccw(C, D, A)
    ccw4 = ccw(C, D, B)
    if ((ccw1 > 0 and ccw2 < 0) or (ccw1 < 0 and ccw2 > 0)) and \
       ((ccw3 > 0 and ccw4 < 0) or (ccw3 < 0 and ccw4 > 0)):
        return True
    if ccw(A, B, C) == 0 and min(A[0], B[0]) <= C[0] <= max(A[0], B[0]) and min(A[1], B[1]) <= C[1] <= max(A[1], B[1]):
        return True
    if ccw(A, B, D) == 0 and min(A[0], B[0]) <= D[0] <= max(A[0], B[0]) and min(A[1], B[1]) <= D[1] <= max(A[1], B[1]):
        return True
    if ccw(C, D, A) == 0 and min(C[0], D[0]) <= A[0] <= max(C[0], D[0]) and min(C[1], D[1]) <= A[1] <= max(C[1], D[1]):
        return True
    if ccw(C, D, B) == 0 and min(C[0], D[0]) <= B[0] <= max(C[0], D[0]) and min(C[1], D[1]) <= B[1] <= max(C[1], D[1]):
        return True
    return False

def point_in_triangle(p, a, b, c):
    def same_side(p1, p2, a, b):
        cp1 = ccw(a, b, p1)
        cp2 = ccw(a, b, p2)
        return (cp1 * cp2) >= 0
    return same_side(p, a, b, c) and same_side(p, b, a, c) and same_side(p, c, a, b)

def is_edge_visible(v, a, b, edges, polygon, vertex_edges):
    if v == a or v == b:
        return True
    adjacent = vertex_edges[id(v)]
    e_forward = (a, b)
    e_backward = (b, a)
    if e_forward in adjacent or e_backward in adjacent:
        return True
    for edge in edges:
        c, d = edge
        if (c, d) == (a, b) or (d, c) == (a, b):
            continue
        if (c, d) in adjacent or (d, c) in adjacent:
            continue
        if segment_intersect((c, d), (v, a)) or \
           segment_intersect((c, d), (a, b)) or \
           segment_intersect((c, d), (b, v)):
            return False
        if point_in_triangle(c, v, a, b) or point_in_triangle(d, v, a, b):
            return False
    return True

