import sys

def main():
    while True:
        n = int(sys.stdin.readline())
        if n == 0:
            break
        islands = []
        possible = True
        for _ in range(n):
            t, c = map(int, sys.stdin.readline().split())
            islands.append((t, c))
            if t > c:
                possible = False  # Even if one island's t > c, impossible
        if not possible:
            print("No")
            continue

        sum_all = sum(t for t, c in islands)
        candidates = [i for i in range(n) if islands[i][1] >= sum_all]
        if not candidates:
            print("No")
            continue

        found = False
        for cand in candidates:
            remaining = []
            for i in range(n):
                if i != cand:
                    t, c = islands[i]
                    remaining.append((t, c))

            # Sort by (c - t) ascending, then t ascending
            remaining_sorted = sorted(remaining, key=lambda x: (x[1] - x[0], x[0]))
            sum_so_far = 0
            valid = True
            for t, c in remaining_sorted:
                if sum_so_far > (c - t):
                    valid = False
                    break
                sum_so_far += t
            if valid:
                found = True
                break

        print("Yes" if found else "No")

