        for i in range(len(words) - 1):
            a = words[i]
            b = words[i+1]
            if len(a) > len(b) and a.startswith(b):
                valid = False
                break
        if not valid:
            print("no")
            continue
        # Build adjacency and in_degree
        adj = {chr(ord('a') + i): set() for i in range(26)}
        in_degree = {chr(ord('a') + i): 0 for i in range(26)}
        for i in range(len(words) - 1):
            a = words[i]
            b = words[i+1]
            min_len = min(len(a), len(b))
            found = False
            for j in range(min_len):
                if a[j] != b[j]:
                    c1 = a[j]
                    c2 = b[j]
                    if c2 not in adj[c1]:
                        adj[c1].add(c2)
                        in_degree[c2] += 1
                    found = True
                    break
            if not found and len(a) > len(b):
                valid = False
                break
        if not valid:
            print("no")
            continue
        # Check for cycles using Kahn's algorithm
        temp_indegree = in_degree.copy()
        queue = deque([c for c in temp_indegree if temp_indegree[c] == 0])
        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                temp_indegree[v] -= 1
                if temp_indegree[v] == 0:
                    queue.append(v)
        if count == 26:
            print("yes")
        else:
            print("no")

