def min_arborescence(current_nodes, edges, root, next_supernode):
    min_edges = {}
    for node in current_nodes:
        if node == root:
            continue
        incoming = [e for e in edges if e[1] == node]
        if not incoming:
            return float('inf')
        min_edge = min(incoming, key=lambda x: x[2])
        min_edges[node] = min_edge

    visited = set()
    cycle = None
    for node in min_edges:
        if node in visited:
            continue
        path = []
        current = node
        while True:
            if current in visited:
                if current in path:
                    idx = path.index(current)
                    cycle = path[idx:]
                    break
                else:
                    break
            visited.add(current)
            path.append(current)
            if current not in min_edges:
                break
            parent = min_edges[current][0]
            if parent == root:
                break
            current = parent
        if cycle:
            break

    if not cycle:
        return sum(e[2] for e in min_edges.values())
    else:
        sum_cycle = sum(min_edges[node][2] for node in cycle)
        supernode = next_supernode
        new_nodes = set(current_nodes)
        for node in cycle:
            new_nodes.remove(node)
        new_nodes.add(supernode)

        new_edges = []
        for e in edges:
            s, t, w = e
            s_in_cycle = s in cycle
            t_in_cycle = t in cycle

            if s_in_cycle and t_in_cycle:
                continue
            elif t_in_cycle:
                adjusted_w = w - min_edges[t][2]
                new_edges.append((s, supernode, adjusted_w))
            elif s_in_cycle:
                new_edges.append((supernode, t, w))
            else:
                new_edges.append(e)

        return sum_cycle + min_arborescence(new_nodes, new_edges, root, next_supernode + 1)

