import bisect

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def crt(a, m, b, n):
    g, p, q = extended_gcd(m, n)
    if (b - a) % g != 0:
        return None
    lcm = m // g * n
    x = (a + (b - a) // g * p % (n // g) * m) % lcm
    return x

