import heapq

n, m = map(int, input().split())
edges = []
for _ in range(m):
    a, b, l, r = map(int, input().split())
    edges.append((a, b, l, r))

r_values = sorted(set(e[3] for e in edges), reverse=True)
max_loyalty = 0

for R in r_values:
    adj = [[] for _ in range(n + 1)]
    for a, b, l, r in edges:
        if r >= R:
            adj[a].append((b, l))
            adj[b].append((a, l))

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[1] = 0
    heap = [(0, 1)]
    heapq.heapify(heap)

    while heap:
        current_max, u = heapq.heappop(heap)
        if u == n:
            break
        if current_max > dist[u]:
            continue
        for v, l in adj[u]:
            new_max = max(current_max, l)
            if new_max < dist[v]:
                dist[v] = new_max
                heapq.heappush(heap, (new_max, v))

    if dist[n] != INF and dist[n] <= R:
        current = R - dist[n] + 1
        if current > max_loyalty:
            max_loyalty = current

